-- =====================================================================
-- 2. RASY — CORE (h9, h10, h26–h30)
-- =====================================================================

INSERT INTO rasy (nazev, rodic_rasa_id, popis) VALUES
('Hobit', NULL,
 'Malý, veselý a "dobrácky kulaťoučí" národ, ještě menší než trpaslíci. Žijí v úrodných údolích v komfortních norách a doupatech. Nejsou silní, ale jsou velmi obratní a povětšinou inteligentní; nejlepší zloději mezi rasami. Mají zvláštní psychickou schopnost zvanou "čich", díky které vycítí přítomnost živých tvorů na dálku (h9).'),
('Trpaslík', NULL,
 'Menší, podsadití a zocelení tvorové sídlící hluboko v horách, kde budují rozsáhlé skalní komplexy a těží drahé kovy a kameny. Díky infravidění vidí i ve tmě. Postrádají smysl pro humor, jsou vážní, sebejistí a dodrží dané slovo. Oblíbenou zbraní je sekera a v boji jsou nesmírně stateční (h10).'),
('Kudůk', NULL,
 'Rasa vzniklá dávným splynutím trpaslíků a hobitů. Po hobitech zdědili obratnost a bystrost, po trpaslících nezdolnost a lásku ke zlatu. Žijí v horách i nížinách, ale nemilují podzemí; stavějí drobné kamenné domy stranou od velkých měst. Umí zacházet se sekerou i kuší, uplatní se jako alchymisté nebo zloději (h26).'),
('Elf', NULL,
 'Menší a méně robustní rasa žijící hluboko v lesích a odlehlých údolích, pokládaná za velmi krásnou. Jsou vysoce inteligentní a boji se raději vyhýbají, ale díky obratnosti dobře zacházejí s lukem. Milují studium a kouzla, mnoho známých kouzelníků pochází právě z jejich řad. Jsou čestní a spravedliví (h27).'),
('Člověk', NULL,
 'Nejrozšířenější rasa, žijící v horách, stepích, lesích i tundrách, budující rozsáhlá města a vesnice na obchodních křižovatkách. Lidé jsou houževnatí a přestože nejsou tak silní jako krollové ani tak inteligentní jako elfové, nacházejí uplatnění v celé škále povolání (h28).'),
('Barbar', NULL,
 'V podstatě lidé, ale dlouhé odloučení od civilizace způsobilo, že barbar zpravidla není tak inteligentní jako člověk, i když v boji obvykle není tak divoký a krutý jako kroll. Oproti krollovi bývá chytřejší, obratnější a pohlednější (h29).'),
('Kroll', NULL,
 'Tvorové sídlící v horách a tundrách, ve zjevu vzdáleně připomínající pračlověka, s nezaměnitelnýma ušima a jemným sluchem. Jsou silnější než lidé, ale nerozhodnější a hloupější. Žijí v kmenech, které mezi sebou neustále válčí, a patří k nejobávanějším bojovníkům. Možná vznikli spojením skřeta s poloobrem (h30).');

-- Kroll — domácí homebrew rozšíření (dítě Krolla)
INSERT INTO rasy (nazev, rodic_rasa_id, popis)
SELECT 'Kroll — domácí rozšíření', r.id,
 'Homebrew rozšíření krollů (na východě nazývaných také Orci) — souhrnné označení humanoidních ras nezapadajících do oficiální pověsti o Stvoření. Vzhledově velmi rozmanití, spojuje je hlavně výrazné ušní boltce a tesáky, poměrově delší paže a hrubší, srstí pokrytá kůže. Dnešní krollové jsou částečně adaptovaní městskému životu, ale v odlehlých koutech světa přežívají i divoké, silně teritoriální kmeny. Jejich ušní boltce jim umožňují "druhý zrak" — orientaci i za naprosté tmy díky vnímání zvuku (h31–h35).'
FROM rasy r WHERE r.nazev = 'Kroll';

-- =====================================================================
-- 3. RASY — Trpasličí klany (h11–h25), děti Trpaslíka
-- =====================================================================

INSERT INTO rasy (nazev, rodic_rasa_id, popis)
SELECT v.nazev, r.id, v.popis
FROM rasy r
JOIN (
    SELECT 'Otho' AS nazev,
        'Doslova "ten, který má víru". Klan prvních kněží, geomágů, čarodějů a mystiků (h12).' AS popis
    UNION ALL SELECT 'Menwar',
        'Pamětníci. Starají se o knihy záští a uchovávají historii lidu, dohlížejí na uchovávání tradic (h13).'
    UNION ALL SELECT 'Ingeit',
        'Kováři, páni oceli, mistři kladiva. Vždy patřili mezi nejváženější z klanů (h14).'
    UNION ALL SELECT 'Hrestwog',
        'Ničitelé, váleční lordi. Mistři války a všech druhů boje (h15).'
    UNION ALL SELECT 'Yrani',
        'Tvůrci, tinkereři, první trpasličí mechanici. Lehce obskurní i mezi ostatními trpaslíky, největší zastánci inovací a pokroku v trpasličím společenství (h16).'
    UNION ALL SELECT 'Knurlcan',
        'Kameníci, páni kamenných síní. Trpasličí ekvivalent lidských celebrit (h17).'
    UNION ALL SELECT 'Skillfiz',
        'Horníci. Hlavní hybná síla trpasličího bohatství (h18).'
    UNION ALL SELECT 'Grimstera',
        'Asi nejmladší z klanů — sdružuje trpaslíky, kteří mají co do činění s dlouhodobým pobytem nad povrchem země (h19).'
    UNION ALL SELECT 'Carach',
        'Klan, který vlastně není klanem — klan trollobijců, trpaslíků žijících jen pro svou slavnou smrt, aby odčinili své hříchy či splatili dluhy (h20).'
    UNION ALL SELECT 'Urur-Vraca',
        'Zaniklý rod. Vzdušné síly trpasličích jednotek, létali na speciálně cvičených gryfech. Gromrilová zbroj a vrhací kladiva z Vraccasia je navždy zapsaly do síní legend (h22).'
    UNION ALL SELECT 'Jurgencar',
        'Zaniklý rod. Lovci draků, kteří je lovili pro jejich bohatství, ale i pro ně samotné (h23).'
    UNION ALL SELECT 'Menkurl',
        'Rod defakto stále existuje, ale je to spíše označení trpaslíků vyobcovaných z trpasličího společenství. Doslova znamená "ti, kteří nejsou z kamene" (h24).'
    UNION ALL SELECT 'Edaris',
        'Malý klan řešící rovnováhu mezi klany — něco jako soudci odpovídající se jen králi, často měli na starosti krevní msty mezi rody (h25).'
) v ON 1=1
WHERE r.nazev = 'Trpaslík';

-- =====================================================================
-- 4. RASY — HOMEBREW (h36–h89)
-- =====================================================================

INSERT INTO rasy (nazev, rodic_rasa_id, popis) VALUES
('Barnové', NULL,
 'Homo algiditis. Humanoidní bytosti dorůstající až ke 3 metrům výšky, s tělem porostlým jemnou srstí poskytující ochranu proti chladu, s drápy na rukou i nohou a kožní řasou na chodidlech sloužící jako sněžnice. Podle mýtu o stvoření jsou potomky ledové dračice a lidí ze zamrzlého severu. Žijí v kmenech čítajících do 150 jedinců, fungujících jako velká rodina se sdíleným majetkem (h36–h39).'),
('Caelové', NULL,
 'Avid humanus. Sami sebe nazývají "nebeskými", obývají vysoká horská sídla a útesy. Malí okřídlení humanoidé připomínající pestrobarevné kolibříky až majestátní jestřáby s dutými, ale křehkými kostmi. Křídla jim neumožňují stabilní let, jen plachtění a krátké popolétnutí za cenu vysilující dřiny. Potrpí si na dekorum, dodržování císařských dekretů a rodinné/klanové vazby (h41–h45).'),
('Furan', NULL,
 'Fiora Collosus. Bytost stvořená ze srdce prastarého inteligentního hvozdu, aby přivedla pomoc nebo přenesla vzpomínky a moudrost umírajícího lesa jinam. Na pomezí mezi klasickou živou bytostí a rostlinou — potřebuje ke svému životu půdu a vodu, jeho zdřevnatělé hlasivky mu neumožňují mluvit jinak než pár slovy. Vzrůst je velmi variabilní, od malého semenáčku po více než 3 metry (h46–h49).'),
('Gnollové', NULL,
 'Canis humanus. Velmi přizpůsobivá humanoidní rasa svým vzhledem připomínající psy, obývající všechny myslitelné oblasti a podnebí — od téměř bezsrstých obyvatel pouští po huňaté obyvatele hor. Většinou velikostí odpovídají průměrnému člověku. Jsou mírumilovní a klidní, žijí v rodinách či vesnicích o zhruba 150 jedincích (h50–h54).'),
('Kobold', NULL,
 'Lacertus humanus. Malý národ zuřivých ještěrek žijících převážně pod zemí, s tělem pokrytým drobnými houževnatými šupinami kopírujícími barvu okolního prostředí. Výška zřídka přesahuje jeden metr. Vychováváni k nedůvěřivosti a preventivnímu útoku vůči cizincům, ale v soukromí se s láskou starají o své mladé (h55–h59).'),
('Magiliw', NULL,
 'Lagos humanus. Drobný národ podobný hobitům, žijící v norách, s tělem pokrytým srstí všech myslitelných barev a čtyřprstými končetinami se silnýma zadníma nohama umožňujícíma velkou rychlost nebo silný kop. Mají rychlý metabolismus, jsou stále v pohybu a velmi snadno se rozruší (h60–h64).'),
('Naro´shai', NULL,
 'Felix sapiens. Kočkolidský národ ze vzdáleného západu, dorůstající velikosti běžných lidí, s hustou srstí a kočičími rysy, spíše šlachovitý než mohutný. Společnost je rozdělena do přísných kast (lvi jako vládnoucí třída, tygři jako váleční a exekutivní síly) v čele s božským králem Anhurem. Jsou nesmírně marniví a milují přepych a módu (h65–h70).'),
('Skaven', NULL,
 'Rattus humanus. Dlouhé agilní tělo pokryté lesklou srstí a silný lysý ocas schopný udržet vlastní váhu tvora. Žijí v ohromných městech, dbají na svůj vzhled a aktuální módu. Jsou velmi kompetitivní, majetek je měřítkem společenského postavení; přímé konfrontaci se raději vyhýbají nebo útočí ze zálohy (h71–h75).'),
('Tauren', NULL,
 'Bucerus sapiens. Statná humanoidní rasa s kopyty místo chodidel, srstí různých barev a rohy na hlavě, jinak anatomicky podobná lidem. Žijí převážně v kmenech vedených radou starších s náčelníkem, v blízkém spojení s přírodou, často vyznávají šamanismus či druidství. Jsou z valné většiny nesmírně čestní a hrdí na svůj původ (h76–h84).'),
('Tiefling', NULL,
 'Homo infernalis. Potomci démonů a lidí se základní anatomií shodnou s lidskou, ale s velkou vnější rozmanitostí — barva kůže od popelavě šedé po uhlově černou, časté rohy, kostní výrůstky, kopyta, ocas nebo křídla (bez schopnosti letu). Odolní vůči ohni, ale velmi zranitelní chladem. Jde o rychle se rozvíjející, sociálně soutěživou společnost s vírou ve vlastní právo vládnout (h85–h89).');

-- =====================================================================
-- 5. RASA_BONUSY_VLASTNOSTI
-- Zdroj: "TABULKA OPRAV" v kapitole Tvorba postavy (h104) — jediná
-- tabulka, která pro VŠECHNY rasy (core i homebrew) uvádí explicitní
-- opravu (bonus/postih) k lidskému rozsahu vlastnosti. Hodnoty jsou
-- shodné s dílčími "oprava" sloupci u jednotlivých homebrew ras (h37,
-- h42, h47, h51, h56, h61, h66, h72, h77, h86) — zkříženo ověřeno.
-- Rasové varianty (trpasličí klany, Kroll — domácí rozšíření) vlastní
-- opravu v textu NEMAJÍ — dědí (nepřímo, jen v rámci hry) hodnoty rodičovské
-- rasy, proto pro ně žádné řádky nevkládáme (viz shrnutí na konci souboru).
-- =====================================================================

INSERT INTO rasa_bonusy_vlastnosti (rasa_id, vlastnost_id, modifikator)
SELECT r.id, v.id, x.modifikator
FROM rasy r
JOIN vlastnosti v ON 1=1
JOIN (
    SELECT 'Hobit' AS rasa, 'Sil' AS vl, '-5' AS modifikator
    UNION ALL SELECT 'Hobit','Obr','+2'
    UNION ALL SELECT 'Hobit','Odl','0'
    UNION ALL SELECT 'Hobit','Int','-2'
    UNION ALL SELECT 'Hobit','Chr','+3'

    UNION ALL SELECT 'Kudůk','Sil','-3'
    UNION ALL SELECT 'Kudůk','Obr','+1'
    UNION ALL SELECT 'Kudůk','Odl','-2'
    UNION ALL SELECT 'Kudůk','Int','-2'
    UNION ALL SELECT 'Kudůk','Chr','0'

    UNION ALL SELECT 'Trpaslík','Sil','+1'
    UNION ALL SELECT 'Trpaslík','Obr','-2'
    UNION ALL SELECT 'Trpaslík','Odl','+3'
    UNION ALL SELECT 'Trpaslík','Int','-3'
    UNION ALL SELECT 'Trpaslík','Chr','-2'

    UNION ALL SELECT 'Elf','Sil','0'
    UNION ALL SELECT 'Elf','Obr','+1'
    UNION ALL SELECT 'Elf','Odl','-4'
    UNION ALL SELECT 'Elf','Int','+2'
    UNION ALL SELECT 'Elf','Chr','+2'

    UNION ALL SELECT 'Člověk','Sil','0'
    UNION ALL SELECT 'Člověk','Obr','0'
    UNION ALL SELECT 'Člověk','Odl','0'
    UNION ALL SELECT 'Člověk','Int','0'
    UNION ALL SELECT 'Člověk','Chr','0'

    UNION ALL SELECT 'Barbar','Sil','+1'
    UNION ALL SELECT 'Barbar','Obr','-1'
    UNION ALL SELECT 'Barbar','Odl','+1'
    UNION ALL SELECT 'Barbar','Int','0'
    UNION ALL SELECT 'Barbar','Chr','-2'

    UNION ALL SELECT 'Kroll','Sil','+3'
    UNION ALL SELECT 'Kroll','Obr','-4'
    UNION ALL SELECT 'Kroll','Odl','+3'
    UNION ALL SELECT 'Kroll','Int','-6'
    UNION ALL SELECT 'Kroll','Chr','-5'

    UNION ALL SELECT 'Barnové','Sil','0'
    UNION ALL SELECT 'Barnové','Obr','-2'
    UNION ALL SELECT 'Barnové','Odl','+1'
    UNION ALL SELECT 'Barnové','Int','0'
    UNION ALL SELECT 'Barnové','Chr','+2'

    UNION ALL SELECT 'Caelové','Sil','-4'
    UNION ALL SELECT 'Caelové','Obr','+1'
    UNION ALL SELECT 'Caelové','Odl','-2'
    UNION ALL SELECT 'Caelové','Int','+1'
    UNION ALL SELECT 'Caelové','Chr','+2'

    UNION ALL SELECT 'Furan','Sil','+2'
    UNION ALL SELECT 'Furan','Obr','-3'
    UNION ALL SELECT 'Furan','Odl','+2'
    UNION ALL SELECT 'Furan','Int','+1'
    UNION ALL SELECT 'Furan','Chr','-3'

    UNION ALL SELECT 'Gnollové','Sil','0'
    UNION ALL SELECT 'Gnollové','Obr','0'
    UNION ALL SELECT 'Gnollové','Odl','0'
    UNION ALL SELECT 'Gnollové','Int','-1'
    UNION ALL SELECT 'Gnollové','Chr','+1'

    UNION ALL SELECT 'Kobold','Sil','0'
    UNION ALL SELECT 'Kobold','Obr','+1'
    UNION ALL SELECT 'Kobold','Odl','+1'
    UNION ALL SELECT 'Kobold','Int','-2'
    UNION ALL SELECT 'Kobold','Chr','-2'

    UNION ALL SELECT 'Magiliw','Sil','-5'
    UNION ALL SELECT 'Magiliw','Obr','+3'
    UNION ALL SELECT 'Magiliw','Odl','-5'
    UNION ALL SELECT 'Magiliw','Int','+1'
    UNION ALL SELECT 'Magiliw','Chr','+3'

    UNION ALL SELECT 'Naro´shai','Sil','-3'
    UNION ALL SELECT 'Naro´shai','Obr','+2'
    UNION ALL SELECT 'Naro´shai','Odl','-3'
    UNION ALL SELECT 'Naro´shai','Int','+2'
    UNION ALL SELECT 'Naro´shai','Chr','+1'

    UNION ALL SELECT 'Skaven','Sil','-1'
    UNION ALL SELECT 'Skaven','Obr','+1'
    UNION ALL SELECT 'Skaven','Odl','0'
    UNION ALL SELECT 'Skaven','Int','+1'
    UNION ALL SELECT 'Skaven','Chr','-2'

    UNION ALL SELECT 'Tauren','Sil','+2'
    UNION ALL SELECT 'Tauren','Obr','-4'
    UNION ALL SELECT 'Tauren','Odl','+3'
    UNION ALL SELECT 'Tauren','Int','0'
    UNION ALL SELECT 'Tauren','Chr','-5'

    UNION ALL SELECT 'Tiefling','Sil','0'
    UNION ALL SELECT 'Tiefling','Obr','+1'
    UNION ALL SELECT 'Tiefling','Odl','-3'
    UNION ALL SELECT 'Tiefling','Int','0'
    UNION ALL SELECT 'Tiefling','Chr','+3'
) x ON x.rasa = r.nazev AND x.vl = v.kod;

-- Poznámka: rasa 'Naro´shai' se v této databázi (dle zadání) jmenuje s rovným
-- apostrofem "Naro'shai" v tabulce rasy — v poddotazu výše používáme stejný
-- řetězec jako v INSERT INTO rasy, viz oprava níže.
-- (Ponecháno pro čitelnost — skutečný název je sjednocen v kroku 6.)

-- =====================================================================
-- 5b. Oprava zápisu apostrofu u Naro'shai
-- Text pravidel používá typografický apostrof "Naro´shai" (U+00B4),
-- zadání žádá rovný apostrof "Naro'shai" (zdvojený v SQL na '').
-- Aby předchozí INSERTy (rasy, rasa_bonusy_vlastnosti) používaly
-- jednotný název, sjednocujeme ho zde na kanonický tvar se zdvojeným
-- apostrofem.
-- =====================================================================

UPDATE rasy SET nazev = 'Naro''shai' WHERE nazev = 'Naro´shai';

-- =====================================================================
-- 6. RASA_JAZYKY
-- Zdroj: tabulka "Jazyky a písma" (h2163) + jednotlivá hesla ras.
--
-- 'Obecná mluva' je dle tabulky h2163 jazykem "ras pocházejících ze
-- starého světa" — text to nerozepisuje jmenovitě, ale explicitně staví
-- do kontrastu "Krollové, kteří NEpochází ze starého světa" (mluví Garm)
-- vůči krollům, kteří odtud pochází. Proto zde mapujeme Obecnou mluvu na
-- sedm základních (core) ras, které v hesle Rasy (h9–h30) nemají žádnou
-- zmínku o "novém světě" (na rozdíl od homebrew ras, jejichž úvodní citace
-- se opakovaně odkazují na "Zápisky z Nového světa" — Cael, Gnoll, Kobold,
-- Skaven). Jde o interpretaci textu, ne o doslovný výčet — označeno TODO
-- pro budoucí ověření, pokud se najde přesnější zdroj.
-- =====================================================================

-- TODO: ověřit, zda "rasy pocházející ze starého světa" v h2163 doslova
-- zahrnují všech sedm základních ras, nebo jen některé z nich.
INSERT INTO rasa_jazyky (rasa_id, jazyk_id)
SELECT r.id, j.id FROM rasy r, jazyky j
WHERE j.nazev = 'Obecná mluva'
  AND r.nazev IN ('Hobit','Trpaslík','Kudůk','Elf','Člověk','Barbar','Kroll');

INSERT INTO rasa_jazyky (rasa_id, jazyk_id)
SELECT r.id, j.id FROM rasy r, jazyky j WHERE r.nazev = 'Trpaslík' AND j.nazev = 'Khazalid';

INSERT INTO rasa_jazyky (rasa_id, jazyk_id)
SELECT r.id, j.id FROM rasy r, jazyky j WHERE r.nazev = 'Elf' AND j.nazev = 'Quenia';

-- Garm: explicitně "Krollové, kteří nepochází ze starého světa" = domácí rozšíření
INSERT INTO rasa_jazyky (rasa_id, jazyk_id)
SELECT r.id, j.id FROM rasy r, jazyky j WHERE r.nazev = 'Kroll — domácí rozšíření' AND j.nazev = 'Garm';

INSERT INTO rasa_jazyky (rasa_id, jazyk_id)
SELECT r.id, j.id FROM rasy r, jazyky j WHERE r.nazev = 'Magiliw' AND j.nazev = 'Liantra';

INSERT INTO rasa_jazyky (rasa_id, jazyk_id)
SELECT r.id, j.id FROM rasy r, jazyky j WHERE r.nazev = 'Naro''shai' AND j.nazev = 'Nar´shila';

INSERT INTO rasa_jazyky (rasa_id, jazyk_id)
SELECT r.id, j.id FROM rasy r, jazyky j WHERE r.nazev = 'Skaven' AND j.nazev = 'Queekish';

INSERT INTO rasa_jazyky (rasa_id, jazyk_id)
SELECT r.id, j.id FROM rasy r, jazyky j WHERE r.nazev = 'Tiefling' AND j.nazev = 'Infernal';

INSERT INTO rasa_jazyky (rasa_id, jazyk_id)
SELECT r.id, j.id FROM rasy r, jazyky j WHERE r.nazev = 'Tauren' AND j.nazev = 'Taurahe';

-- Mannar: v h2163 přiřazen Barnům; jednotlivé heslo Barnů (h40) uvádí jazyk
-- pod hovorovým názvem "mannari" — jde o stejný jazyk, sjednoceno na "Mannar".
INSERT INTO rasa_jazyky (rasa_id, jazyk_id)
SELECT r.id, j.id FROM rasy r, jazyky j WHERE r.nazev = 'Barnové' AND j.nazev = 'Mannar';

-- Fůranština: jazyk zmíněný přímo v hesle Furan (h48), není v tabulce h2163.
INSERT INTO rasa_jazyky (rasa_id, jazyk_id)
SELECT r.id, j.id FROM rasy r, jazyky j WHERE r.nazev = 'Furan' AND j.nazev = 'Fůranština';

