INSERT INTO finty (nazev, typ, bonus_iniciativa, pocet_akci, pozadovana_zbran, pozadovany_protivnik, poznamky) VALUES
('Odstrčení', 'kombinovana', 1, 2, 'libovolná délky 1', 'humanoid se zbraní délky 1',
 'Homebrew. 1. akce: šermíř se buď útokem dostane k protivníkovi (musí ho zranit aspoň za 1 život), nebo se naopak ubrání jeho útoku (zůstane nezraněn) — při obraně může použít útok z obrany. 2. akce: místo útoku hází past Sil-3+Sil protivníka ~ odstrčení o 1 sáh/nic. -- TODO ověřit proti PPE str.9-14: zdroj u obou akcí uvádí shodně "1. akce" (druhá zjevně měla být "2. akce" — transkripční chyba skenu, zde zapsáno jako poradi 1 a 2 dle pořadí v textu).'),

('Podražení', 'kombinovana', 2, 2, 'libovolná zbraň délky 1', 'humanoid se zbraní délky 1',
 'Homebrew doplněk. Probíhá stejně jako finta Odstrčení, ale protivník je sražen na zem na hex, kde právě stojí (místo odstrčení o 1 sáh).'),

('Přetlak', 'kombinovana', 2, NULL, 'sečná', 'humanoid se sečnou zbraní',
 'Homebrew. Zdroj tuto fintu jmenuje jak mezi útočnými, tak mezi kombinovanými fintami (viz komentář k rozřazení na začátku souboru) — zde zapsána jako kombinovaná, protože jde o útok kombinovaný s pastí na sílu a možností srazit protivníka k zemi. 1. akce: rychlý přísun k protivníkovi a zablokování jeho zbraně; přísun se zdaří, uspěje-li šermíř v hodu na útok (protivník ale není zraněn). 2. akce: past na sílu — oba soci házejí současně, šermíř má bonus +1 (nebo +2, ovládá-li fintu už 5 úrovní) k hodu na sílu, ať už útočí, nebo se brání; hodí-li šermíř na sílu více, protivník je sražen k zemi, při shodě se nic neděje. Je-li protivníkem jiný šermíř ovládající Přetlak, může ve fintě pokračovat s vynaložením 1 akce (samotný hod na sílu žádnou akci nevyžaduje). Sražený protivník vstává 1 kolo (2 akce), po tu dobu se nemůže bránit ani zbraní, ani štítem, nemůže kouzlit ani útočit. V základním soubojovém systému odpovídá manévru Sražení protivníka. -- TODO ověřit proti PPE str.9-14: finta je na skenu uvedena zároveň v seznamu útočných i kombinovaných fint a její text se dle poznámky u Úderu hlavicí na str.14 PPE opakuje/duplikuje s dřívějším výskytem.');

