-- --- EFEKTY ---
INSERT INTO efekty (nazev, typ, cil, hodnota_vzorec, mechanika_aplikace, trvani, podminka_ukonceni, stackovatelne, tooltip_text) VALUES
('Chycen v lovecké pasti', 'debuff', 'životy, pohyb', 'Žk6 (úspěch zvířete) / Žk6+4×Ž (neúspěch), Ž=životaschopnost zvířete', 'jednorazove', 'okamžité', NULL, FALSE, 'Zvíře padlé do hraničářovy/chodcovy lovecké pasti je zraněno nebo (dle nastavení pasti) živě lapeno.'),
('Prokletí sejmuto (chodec)', 'buff', 'kletba', 'odstranění aktivní kletby', 'jednorazove', 'okamžité, trvalé', NULL, FALSE, 'Výsledek úspěšného snímání kletby chodcem.');

-- --- PASTI ---
INSERT INTO pasti (vlastnosti, obtiznost, efekt_uspech_id, efekt_neuspech_id, pouziva_4stupnovou_skalu, poznamka) VALUES
('Obr', 'dle Tabulky loveckých pastí (terén: 1-7) + bonus chodce dle úrovně', NULL,
   (SELECT id FROM efekty WHERE nazev='Chycen v lovecké pasti'), FALSE,
   'Past se hází za chycené zvíře. Zápis Žk6/Žk6+4×Ž — Ž=životaschopnost loveného zvířete; při nastavení "na lapení" je výsledek jen lapení/nic.'),
('Int+Roz', '10 (snímání), 5/1 (rozeznání nespravedlivé/spravedlivé kletby cíleně), 5 (samovolné); "Roz"=rozdíl úrovní chodce a sesilatele kletby; při spravedlivé kletbě se počítá, jako by byl chodec o 15 úrovní níž',
   (SELECT id FROM efekty WHERE nazev='Prokletí sejmuto (chodec)'), NULL, FALSE,
   'Snímání kletby: nebezpečnost klesá o 1 na konci každé směny soustředění (10 magů/10 životů/10 bodů únavy za směnu); přerušení = nutno začít od základní nebezpečnosti znovu.');

-- --- HRANIČÁŘ (základní obor) ---
INSERT INTO zvlastni_schopnosti (nazev, druh, popis, uroven_od, mechanika) VALUES
('Boj proti zvířatům', 'schopnost', 'Hraničář má bonus +1 k útoku i obraně proti nemagickým zvířatům.', 1, '+1 ÚČ/OČ proti nemagickým zvířatům'),
('Stopování', 'dovednost', 'Šance na úspěšné vystopování závisí na terénu (volná příroda/uzavřené prostory × lehký/těžký/nepoužitelný terén: 80/50/0 % resp. 60/40/0 %), +2 % za úroveň hraničáře, +3 % za dalšího tvora ve skupině, -10 % za každých 24 hodin od zanechání stopy. Na 15. a nižší úrovni lze stopovat jen chůzí, od 16. úrovně i při spěchu.', 1, 'Šance = základ dle terénu + 2 %/úroveň + 3 %/tvor navíc - 10 %/24 h stáří stopy'),
('Pes', 'schopnost', 'Hraničář má 40% šanci mít psa (hlídací/lovecký/válečný dle k%), opakuje se při postupu na úroveň, dokud jej nezíská; může vychovávat jen jednoho najednou. Pes od 5. úrovně hraničáře zesílí (vyšší staty), od 16. úrovně hraničáře se učí druhou až čtvrtou speciální schopnost (Vícenásobné útoky/Zadrž/Trhej u válečného, Hledej/Revír/Cíl hledání/Bonus k iniciativě u loveckého, Větší dosah/Hlídej/Ticho-štěkej u hlídacího).', 1, 'k% 1-20 hlídací, 21-34 lovecký, 35-40 válečný; staty a speciální povely viz Tabulka psů'),
('Mimosmyslové schopnosti (Hraničář)', 'schopnost', 'Od 4. úrovně získá hraničář náhodnou (k%) mimosmyslovou schopnost: telekineze (1-40, pohyb předmětů silou vůle, limit = váha×vzdálenost dle stupně znalosti), pyrokineze (41-75, zažehnutí ohně na dálku, limit = čas×vzdálenost) nebo telepatie (76-100, přenos/čtení myšlenek, dosah dle stupně znalosti a materiálu překážky; povolené/nepovolené čtení/vnuknutí jsou pasti s nebezpečností 1/2/6/7 upravené o inteligenci terče). Použití vyžaduje 1 směnu soustředění, max. 1×/7 hodin.', 4, 'Tabulka telekineze/pyrokineze/telepatie dle "stupně znalosti" (roste s úrovní); telepatie: past Int(+Roz u nepovoleného) proti nebezpečnosti 1/2/6/7 -- TODO ověřit plné tabulky (OCR nejisté nad stupněm 13, viz kontrolní seznam)'),
('Rozsah léčivých a ochranných kouzel', 'schopnost', 'Rozšiřuje okruh tvorů, na které lze sesílat léčivá/ochranná kouzla s rozsahem "1 postava": od 6. úrovně obratlovci, od 12. úrovně i běžní neobratlovci. Od 18. úrovně i zcela neznámé bílkovinné bytosti, od 24. úrovně nebílkovinné hmotné tvory, od 30. úrovně nehmotné tvory (se sníženými účinky). Analogicky platí odstupňování 6./10./15. úrovně pro chodce a druida.', 6, 'Progrese cílovatelnosti kouzel: 6.úr humanoidé, 12.úr obratlovci, 18.úr neobvyklí neobratlovci, 24.úr nebílkovinní, 30.úr nehmotní'),
('Magický střeh', 'schopnost', 'Hraničářské kouzlo popisované jako zvláštní schopnost pro svůj význam: chrání terč (hraničáře/druida/chodce od 16. úrovně) proti kouzelnickým kouzlům vynaložením vlastní magenergie terče místo samostatného pole. Síla/trvání dle vynaložené magenergie (I: 5 magů/do prvního kouzla, II: 20/2 dny, III: 50/2 týdny, IV: 100/2 měsíce, Velký: 1000/12 měsíců). Dle Tabulky magického střehu (typ kouzla fyzická/psychická/útočná/ochranná × stav terče) se určí násobek magenergie pro pohlcení (P) a odražení (O) a nebezpečnost pasti (N), upravená o čtvrtinu rozdílu úrovní sesilatele a terče. Nekombinuje se s magickým zrcadlem.', 16, 'Tabulka magického střehu: P/O/N dle typu kouzla a stavu terče (bdělý/spící, chodec/druid/druid ve hvozdu); past terče proti N ovlivňuje pohlcení, odražení jen hod na terč'),
('Získávání jedů (Hraničář)', 'dovednost', 'Hraničář umí získávat výchozí suroviny přírodních živočišných jedů z čerstvě zabitého nebo lapeného jedovatého tvora, kterého dobře zná (mohl by na něj seslat uzdrav lehká zranění); z jednoho tvora lze za 1 směnu vytěžit 1-3 dávky, živý tvor je znovu použitelný po 12 hodinách. Zpracovat jed do použitelné formy umí až pyrofor.', 1, 'Preparace 1 směna, 1-3 dávky jedu; tvor max. velikosti hraničáře, obnova jedu za 12 h');

-- --- DRUID (obor Hraničáře) ---
INSERT INTO zvlastni_schopnosti (nazev, druh, popis, uroven_od, mechanika) VALUES
('Boj se zvířaty (Druid)', 'schopnost', 'Proti nemagickým tvorům s inteligencí 1 má druid bonus k útoku i obraně: +2 (6.úr), +3 (10.úr), +4 (14.úr), +5 (19.úr), +6 (22.úr); proti inteligenci 0 menší tabulkové bonusy od 14. úrovně (+1 až +3). Nesčítá se s hraničářovým základním bonusem proti zvířatům.', 6, 'Bonus ÚČ/OČ dle úrovně proti Int 1 (a menší proti Int 0 od 14.úr)'),
('Nepřirozené chování zvířat', 'dovednost', 'Druid pozná, že zvíře jedná nepřirozeně (ovládané kouzlem apod.) — během boje po 1 kole, při pozorování cizího boje po 3 kolech, jinak po 1 směně. Nezabírá herní čas/akce, ale musí se ohlásit PJ předem. Od 12. úrovně lze odhadovat celou smečku najednou (i podíl ovlivněných jedinců), od 18. úrovně bez omezení počtu/druhů.', 6, 'Doba rozpoznání: 1 kolo (vlastní boj) / 3 kola (cizí boj) / 1 směna (klid); od 12.úr celá smečka, od 18.úr neomezeně'),
('Odvracení zvířat', 'schopnost', 'Druid může odvrátit napadající nemagické zvíře/smečku s inteligencí 1 (musí je vidět). Hází 2k6 proti hodnotě v Tabulce odvracení zvířat (dle úrovně druida a životaschopnosti zvířete, "N" = nelze odvrátit); u ovládaných zvířat se počítá, jako by byl druid o 5 úrovní níž. Sám v lese 12+ h bez kontaktu s lidmi: "N" se mění na 18 a hází 4k6 místo 2k6. Neúspěch se u daného zvířete/smečky neopakuje. Od 16. úrovně se schopnost dále zlepšuje, na 36. úrovni odvrací automaticky (A) cokoliv. Nelze odvracet prehistorická zvířata.', 6, 'Hod 2k6 (4k6 v lese samotný 12+h) proti Tabulce odvracení zvířat dle úrovně a životaschopnosti zvířete; ovládaná zvířata: past jako o 5 úrovní níž'),
('Očištění', 'schopnost', 'Zabije-li druid vlastnoručně zvíře druhu, který mohl odvrátit, musí se do hodiny očistit (1 směna meditace), jinak ztrácí schopnost odvracet zvířata na počet dní = životaschopnost zabitého zvířete. Není nutné po zabití nemocného nebo ovládaného zvířete.', 6, 'Očista = 1 směna meditace do 1 hodiny od zabití; jinak ztráta odvracení na X dní (X=životaschopnost zvířete)'),
('Druidova hůl', 'schopnost', 'Druid dostane od stromu svou hůl — téměř 2 sáhy dlouhá obouruční zbraň, SZ 7/-2, obrana zbraně +2, váha 15 mn (v cizích rukou obrana zbraně 0). Nesmí být magicky upravena. Od 10. úrovně útočí holí 3×/2 kola (+3 Ini), od 15. úrovně 2×/kolo (+6 Ini). Použití železných zbraní/zbrojí/štítu druidem riskuje dočasnou ztrátu schopnosti sesílat lesní kouzla.', 6, 'Hůl: SZ 7/-2, OZ +2; útoky 3/2kola (10.úr), 2/kolo (15.úr)'),
('Předpovídání počasí', 'dovednost', 'Druid předpovídá počasí mimo město/podzemí po 1 směně soustředění: pravděpodobnost 60 % + úroveň + bonus za inteligenci pro nejbližší den, klesá o 20 % za každý další den dopředu.', 6, 'Šance = 60 % + úroveň + bonus Int, -20 %/další den'),
('Pohyb v lese', 'schopnost', 'Díky obeznámenosti s přírodou má druid při chůzi i běhu ve hvozdu bonus +1 až +3 k pohyblivosti (dle hustoty lesa, určuje PJ).', 6, '+1 až +3 pohyblivost ve hvozdu'),
('Posílení kouzel (hvozd)', 'schopnost', 'Vlastnost prostředí hvozdu, ne kouzlo: některá hraničářská léčivá/užitková kouzla sesílaná druidem ve hvozdu mají silnější účinek, ale odčerpají část probouzecí magenergie hvozdu (např. uzdrav lehká zranění +5-10 životů za 2 magy hvozdu, uzdrav těžká zranění +8-18 za 4 magy, ošetři zranění chladem/kyselinou/ohněm silnější o 3-5 magů hvozdu, odstranění únavy 1k10 za 1 mag, oživ mrtvého 1/5 magenergie z hvozdu).', 6, 'Bonus efekt vybraných kouzel ve hvozdu za cenu probouzecí magenergie hvozdu'),
('Půst', 'schopnost', 'Druid, který jeden den nepřijímá potravu, získá druhý den při meditaci o 1 mag víc, ale i 1 trvalý bod únavy (nelze odstranit odpočinkem ani kouzlem); efekty se při delším půstu kumulují. Opustí-li během půstu les, přijde o nadbytečné magy a ztrácí 10 bodů únavy denně. Během půstu se neuplatňují klasická pravidla pro hladovění.', 6, '+1 mag a +1 trvalá únava za den půstu, kumulativní');

-- --- CHODEC (obor Hraničáře) ---
INSERT INTO zvlastni_schopnosti (nazev, druh, popis, uroven_od, mechanika, past_id, vysledek_skala) VALUES
('Odhad přesvědčení (Chodec)', 'dovednost', 'Chodec dokáže při 1 směně komunikace odhadnout přesvědčení postavy podle Tabulky odhadu přesvědčení (dle úrovně chodce × inteligence terče, "N" = nelze určit, u vyšší inteligence nižší šance). Od 16. úrovně "N" znamená automatický odhad s možností fatálního neúspěchu. Nový pokus u téže osoby jen po přestupu na vyšší úroveň.', 6, 'Šance dle Tabulky odhadu přesvědčení (úroveň × inteligence terče); od 16.úr i "N" pole automaticky s rizikem fatálního neúspěchu -- Pozn.: hodnota sloupce 19-20 u vyšších úrovní na skenu PPE nečitelná/chybí.', NULL, TRUE),
('Rychlý pochod', 'schopnost', 'Chodec může 24 hodin "spěchat" s dvojnásobkem bodů pohybu při běžné (nezvýšené) únavě a bez jejích průběžných účinků; zastaví-li se (např. boj), účinky únavy se projeví najednou. Může strhnout i další postavy s vytrvalostí 11+ (jen o polovinu rychleji). Platí jen pro chůzi. Od 16. úrovně lze při rychlém pochodu i stopovat a sesílat kouzla pocestných.', 6, 'Dvojnásobek bodů pohybu po 24 h bez průběžných účinků únavy (jen chůze)', NULL, FALSE),
('Hbitost v obraně', 'schopnost', 'Chodec má bonus +1 k hodu na obranu od 6. úrovně (nevztahuje se na jiné hody obratnosti, např. proti pasti); od 16. úrovně +2 proti humanoidům (nesčítá se s původním +1).', 6, '+1 OČ (6.úr), +2 OČ proti humanoidům (16.úr, nesčítá se)', NULL, FALSE),
('Ochočování nestvůr', 'schopnost', 'Chodec má bonus k ochočování nestvůr: +1 (6.úr), +2 (12.úr), +3 (24.úr).', 6, '+1/+2/+3 dle úrovně (6./12./24.úr)', NULL, FALSE),
('Líčení loveckých pastí', 'dovednost', 'Chodec (jen on) má bonus k pravděpodobnosti a nebezpečnosti nalíčení lovecké pasti podle terénu (džungle 7/70% až poušť 1/10%): +1 nebezpečnosti/+5% (6.-8.úr), +2/+10% (9.-12.úr), +3/+15% (13.-17.úr), +4/+20% (18.-23.úr), +5/+25% (24.-30.úr), +6/+30% (31.-36.úr). Past pro chycené zvíře: Obr proti nebezpečnosti terénu — úspěch: Žk6 zranění, neúspěch: Žk6+4×Ž (Ž=životaschopnost), nebo jen lapení/nic pokud past cílí na živý odchyt. Nalíčení trvá 1-3 směny, cena 1 zl/stupeň životaschopnosti (2× pro lapací past).', 6, 'Past Obr proti nebezpečnosti terénu (1-7) + bonus chodce; efekt Žk6/(Žk6+4×Ž)', (SELECT id FROM pasti WHERE vlastnosti='Obr' AND obtiznost LIKE 'dle Tabulky loveckých pastí%'), FALSE),
('Rychlá střelba', 'schopnost', 'Od 7. úrovně střílí chodec z dlouhého/krátkého luku 3×/2 kola (+3 Ini), od 12. úrovně 2×/kolo (+6 Ini), od 17. úrovně 5×/2 kola (+9 Ini), od 22. úrovně 3×/kolo (+12 Ini). Vyžaduje věnovat střelbě první akci a alespoň polovinu akcí kola.', 7, 'Progrese počtu výstřelů/bonusů k iniciativě dle úrovně (7./12./17./22.úr)', NULL, FALSE),
('Výpad a kryt (Chodec)', 'schopnost', 'Od 9. úrovně bonus +1 k vybranému hodu na útok/obranu a postih -2 k opačným (musí se ohlásit před hodem na iniciativu); od 18. úrovně +2/-4.', 9, '9.úr: +1/-2; 18.úr: +2/-4', NULL, FALSE),
('Mimosmyslové schopnosti (Chodec, další)', 'schopnost', 'Chodec získá druhou mimosmyslovou schopnost na 12. úrovni, třetí na 18. úrovni (viz základní schopnost hraničáře).', 12, 'Druhá schopnost (12.úr), třetí (18.úr) z telekineze/pyrokineze/telepatie', NULL, FALSE),
('Snímání kletby', 'dovednost', 'Od 16. úrovně chodec rozeznává a snímá kletby (prokletí/urknutí/vysátí) — jediný, kdo to umí. Rozeznání: samovolné past Int+Roz-5-, cílené past Int+Roz-1- (u spravedlivé kletby jako o 15 úrovní níž; "Roz"=rozdíl úrovní chodce a sesilatele). Jednou cíleně na osobu, opakovat lze až po přestupu na úroveň. Snímání: past Int+Roz-10- (u spravedlivé jako o 15 úrovní níž); 1 směna soustředění stojí 10 magů/10 životů/10 bodů únavy, nebezpečnost klesá o 1 za směnu, dokud past nevyjde nebo je pokus přerušen (pak nutno začít znovu s plnou nebezpečností).', 16, 'Past Int+Roz proti 5/1/10 dle fáze; cena 10 magů/10 životů/10 únavy za směnu snímání, -1 nebezpečnost/směnu', (SELECT id FROM pasti WHERE vlastnosti='Int+Roz'), FALSE),
('Boj proti zvířatům (Chodec, rozšíření)', 'schopnost', 'Od 17. úrovně se chodcův základní hraničářský bonus proti nemagickým zvířatům zvyšuje na +2.', 17, '+2 ÚČ/OČ proti nemagickým zvířatům (místo +1)', NULL, FALSE);

-- --- PSÍ VÝCVIK (homebrew rozšíření companion mechaniky Hraničáře) ---
INSERT INTO zvlastni_schopnosti (nazev, druh, popis, uroven_od, mechanika) VALUES
('Psí výcvik', 'schopnost', 'Hraničářův pes (musí s ním strávit alespoň 1 úroveň) může projít 30denním výcvikem (70-200 zl), po němž unese speciální zbroj (kožená/lamelová/plátová dle questu). Hraničář od 16. úrovně může mít dvě hraničářská zvířata. Vycvičený pes i se zbrojí zvládne 3 hexy/kolo v rozšířeném soubojovém systému.', 1, 'Výcvik 30 dní, 70-200 zl; zbroj kožená/lamelová/plátová (3/4/5 OZ)'),
('Speciální výcvik (pes)', 'schopnost', 'Vycvičený pes získává +1 OČ/+1 ÚČ proti všem zvířatům, +2/+2 (obráceně) proti psovitým a kočkovitým šelmám.', 1, '+1 OČ/ÚČ vs. zvířata, +2 vs. psovité/kočkovité šelmy'),
('Zardoušení (pes)', 'schopnost', 'Jednou za 5 kol může pes místo klasického útoku zaútočit na masivní zranění cíle max. velikosti C. Past Roz.-3-Odol. zranění/nic, síla útoku 5k6 + životaschopnost psa. U letců jde o vyklovnutí očí (stejná pravidla).', 1, 'Past Roz.-3-Odol.; zranění 5k6+životaschopnost psa; 1×/5 kol'),
('Specializace (pes)', 'schopnost', 'Po každých 4 společných úrovních hraničáře a psa lze psa specializovat na boj proti konkrétnímu typu protivníka (nemrtví, lykantropové, zvířata...); +1 ÚČ/+1 OČ za každý stupeň specializace, lze opakovat i na stejnou skupinu.', 1, '+1 ÚČ/+1 OČ za stupeň specializace, získatelný po 4 společných úrovních');

-- --- PROPOJENÍ SE SCHOPNOST_POVOLANI ---
INSERT INTO schopnost_povolani (schopnost_id, povolani_id)
SELECT s.id, p.id FROM zvlastni_schopnosti s, povolani p WHERE
   (s.nazev IN ('Boj proti zvířatům','Stopování','Pes','Rozsah léčivých a ochranných kouzel',
                'Získávání jedů (Hraničář)','Psí výcvik','Speciální výcvik (pes)','Zardoušení (pes)','Specializace (pes)')
    AND p.nazev='Hraničář')
OR (s.nazev IN ('Boj se zvířaty (Druid)','Nepřirozené chování zvířat','Odvracení zvířat','Očištění',
                'Druidova hůl','Předpovídání počasí','Pohyb v lese','Posílení kouzel (hvozd)','Půst')
    AND p.nazev='Druid')
OR (s.nazev IN ('Odhad přesvědčení (Chodec)','Rychlý pochod','Hbitost v obraně','Ochočování nestvůr',
                'Líčení loveckých pastí','Rychlá střelba','Výpad a kryt (Chodec)',
                'Mimosmyslové schopnosti (Chodec, další)','Snímání kletby','Boj proti zvířatům (Chodec, rozšíření)')
    AND p.nazev='Chodec')
OR (s.nazev = 'Mimosmyslové schopnosti (Hraničář)' AND p.nazev IN ('Hraničář','Druid','Chodec'))
OR (s.nazev = 'Magický střeh' AND p.nazev IN ('Hraničář','Druid','Chodec'));
-- =====================================================================
-- ČÁST 3: ALCHYMISTA / THEURG / PYROFOR (h271-h294)
-- Naprostá většina obsahu jsou recepty na lektvary/svitky/artefakty/jedy
-- (tabulky `lektvary`, `predmety`) a kouzla theurga (astrální sféry,
-- elementálové) — mimo rozsah tohoto importu. Zde jen skutečné
-- schopnosti/dovednosti a past-mechanismy líčení pastí pyrofora.
-- Očekávané názvy v `povolani`: 'Alchymista', 'Theurg', 'Pyrofor'.
-- =====================================================================

-- --- EFEKTY (Líčení pastí pyrofora) ---
INSERT INTO efekty (nazev, typ, cil, hodnota_vzorec, mechanika_aplikace, trvani, podminka_ukonceni, stackovatelne, tooltip_text) VALUES
('Rozdrcen padající zátěží', 'debuff', 'životy', '(1k6 za každých 200 mn váhy a sáh pádu) × úroveň pyrofora, max. 9k6', 'jednorazove', 'okamžité', NULL, FALSE, 'Následek neúspěchu proti drtivé pasti pyrofora.'),
('Zasažen šipkovou pastí', 'debuff', 'životy', '1k6 / 3k6 / 5k6 dle provedení pasti (příp. jed na šipkách)', 'jednorazove', 'okamžité', NULL, FALSE, 'Zásah vystřelenou otrávenou či neotrávenou šipkou z pasti.'),
('Zraněn výbuchem pasti (mírně)', 'debuff', 'životy', '2-12 životů v okruhu 4 sáhů', 'jednorazove', 'okamžité', NULL, FALSE, 'Úspěšná obrana (Odl) proti výbušné pasti — slabší zranění.'),
('Zraněn výbuchem pasti (těžce)', 'debuff', 'životy', '4-24 životů v okruhu 4 sáhů', 'jednorazove', 'okamžité', NULL, FALSE, 'Neúspěšná obrana (Odl) proti výbušné pasti — plné zranění.');

-- --- PASTI (nalíčené pyroforem) ---
INSERT INTO pasti (vlastnosti, obtiznost, efekt_uspech_id, efekt_neuspech_id, pouziva_4stupnovou_skalu, poznamka) VALUES
('Obr', '5', NULL, (SELECT id FROM efekty WHERE nazev='Rozdrcen padající zátěží'), FALSE,
   'Drtivá past (pyrofor) — objekt, nápadnost 10-30 %, doba naléčení 3-6 směn. PJ upravuje parametry dle konkrétní konstrukce.'),
('Obr', '6 (síla 1k6) / 5 (síla 3k6) / 4 (síla 5k6) dle provedení — viz Tabulka šipkových pastí', NULL,
   (SELECT id FROM efekty WHERE nazev='Zasažen šipkovou pastí'), FALSE,
   'Šipková past (pyrofor) — mechanismus, nápadnost 5/10/15 % dle provedení; lze snížit nápadnost (+1 směna naléčení/-1 %, max -10 %), zvýšit nebezpečnost (2× cena) nebo osadit tajným výpínačem (+5 % nápadnost) a otrávenými šipkami.'),
('Odl', '6', (SELECT id FROM efekty WHERE nazev='Zraněn výbuchem pasti (mírně)'),
   (SELECT id FROM efekty WHERE nazev='Zraněn výbuchem pasti (těžce)'), FALSE,
   'Výbušná past (pyrofor) — mina z ohnivé hlíny, mechanismus, nápadnost 5 %, doba naléčení 2 kola, okruh 4 sáhy.');

-- --- ALCHYMISTA (základní obor) ---
INSERT INTO zvlastni_schopnosti (nazev, druh, popis, uroven_od, mechanika) VALUES
('Odolnost vůči jedům', 'schopnost', 'Alchymista při hodech proti jedu (nikoli proti jiným útokům na odolnost) počítá dvojnásobek svého bonusu za odolnost (při postihu jen polovinu postihu).', 1, '2× bonus za odolnost (nebo 1/2 postihu) jen při hodech proti jedu'),
('Vidění magenergie', 'dovednost', 'Alchymista dokáže po 1 směně zkoumání rozpoznat, zda předmět obsahuje magenergii a přibližně kolik (ale ne její příčinu), dle Tabulky pravděpodobnosti objevení magenergie (dle úrovně a množství magů v předmětu). Neobjeví-li ji, nelze to zkusit znovu do postupu na vyšší úroveň. Alchymisté jsou jediní, kdo umí magenergii mezi předměty přelévat.', 1, 'Šance dle tabulky (úroveň × množství magů 1-2000); 1 směna na zkoumání, opakování jen po postupu na úroveň'),
('Lučba', 'dovednost', 'Alchymista vyrábí kouzelné i nekouzelné předměty (lektvary, svitky, jedy, trvalé artefakty) z magenergie (destilované z výtažků) a nemagických surovin, skladovaných ve své truhle (max. 100 mincí obsahu, hustota magenergie roste s úrovní). Konkrétní recepty jsou vedeny v tabulkách `lektvary`/`predmety`, mimo rozsah této tabulky schopností.', 1, 'Truhla max. 100 mincí obsahu; hustota magenergie dle úrovně (1.úr 5 magů/mn, 2.úr 10, 3.úr 15, 10.úr 50...)');

-- --- PYROFOR (obor Alchymisty) ---
INSERT INTO zvlastni_schopnosti (nazev, druh, popis, uroven_od, mechanika) VALUES
('Pyroforova pravděpodobnost objevení magenergie', 'dovednost', 'Rozšíření Vidění magenergie pro vlastní výrobky: pyrofor od 6. úrovně dokáže odhadnout zbývající životnost bomby (1 směna zkoumání) či ohnivé hlíny (3 kola) 24 hodin před výbuchem/zvlhnutím — šance = šance lučby + úroveň pyrofora. Od 12. úrovně stejně odhaduje životnost dýmovky (3 kola).', 6, 'Šance = šance lučby + úroveň; rozšířená tabulka pravděpodobnosti objevení magenergie pro vyšší úrovně (6.-15.)'),
('Líčení pastí', 'dovednost', 'Pyrofor umí nalíčit mechanické a magické pasti spouštěné táhlem, náslapnou deskou, světlem, hlukem apod. Základní typy: Drtivá past (past Obr-5-nic/rozdrcení, objekt), Plynová past (past dle náplně jedu, mechanismus, nápadnost 15 %), Šipková past (past Obr dle tabulky, mechanismus, 3 stupně provedení), Výbušná past (past Odl-6-2-12/4-24 život v okruhu 4 sáhů, z ohnivé hlíny), Náslapná spoušť (past Obr-5-nespustí/spustí) a Světelná spoušť (past dle intenzity světla-11-spustí/nespustí). Pasti lze kombinovat se spouští přes "spojení" (mechanické +25 % nápadnosti, nebo magické za 10 magů/5 zl +5 % nápadnosti). Pyrofor má navíc bonus 10 % na postřeh při hledání/rozpoznávání jedů.', 6, 'Viz jednotlivé typy pastí (Drtivá/Plynová/Šipková/Výbušná/Náslapná/Světelná) v tabulce `pasti`'),
('Pokročilé protijedy', 'dovednost', 'Od 20. úrovně (viz sekce protijedů) pyrofor rozšiřuje výrobu protijedů o pokročilejší receptury a preventivní (imunizační) úpravu podávanou 1 směnu předem za 2 magy a poloviční cenu surovin (umí ji až od 2 úrovní nad úrovní, na které se naučil daný protijed vyrábět).', 20, 'Preventivní úprava protijedu: 1 směna, 2 magy, 1/2 ceny surovin; umí od +2 úrovně nad naučením protijedu -- TODO: konkrétní seznam nových protijedů z PPE není v tomto importu rozpracován, viz `lektvary`.');

-- --- PROPOJENÍ SE SCHOPNOST_POVOLANI ---
INSERT INTO schopnost_povolani (schopnost_id, povolani_id)
SELECT s.id, p.id FROM zvlastni_schopnosti s, povolani p WHERE
   (s.nazev IN ('Odolnost vůči jedům','Vidění magenergie','Lučba') AND p.nazev='Alchymista')
OR (s.nazev IN ('Pyroforova pravděpodobnost objevení magenergie','Líčení pastí','Pokročilé protijedy') AND p.nazev='Pyrofor');
-- =====================================================================
