-- --- EFEKTY ---
INSERT INTO efekty (nazev, typ, cil, hodnota_vzorec, mechanika_aplikace, trvani, podminka_ukonceni, stackovatelne, tooltip_text) VALUES
('Podrobení odhaleno', 'debuff', 'informace', 'mág pozná, že bytost je podrobena cizím mágem', 'jednorazove', 'okamžité (informace)', NULL, FALSE, 'Výsledek úspěšného hodu na odhalení podrobení.'),
('Ovládnutí odhaleno', 'debuff', 'informace', 'mág pozná, že postava je ovládána cizím mágem', 'jednorazove', 'okamžité (informace)', NULL, FALSE, 'Výsledek úspěšného hodu na odhalení ovládnutí.'),
('Drak splní žádost/rozkaz', 'debuff', 'chování', 'drak splní požadavek, není-li nebezpečný/sebevražedný', 'jednorazove', '4 hodiny (žádost/rozkaz) / 1 den (zmámení)', NULL, FALSE, 'Výsledek neúspěšné obrany draka proti drakomluvě.');

-- --- PASTI ---
INSERT INTO pasti (vlastnosti, obtiznost, efekt_uspech_id, efekt_neuspech_id, pouziva_4stupnovou_skalu, poznamka) VALUES
('Int+Roz', '15 − počet mágem úspěšně podrobených bytostí ("Roz"=rozdíl úrovní mág vs. podrobitel)', NULL,
   (SELECT id FROM efekty WHERE nazev='Podrobení odhaleno'), FALSE,
   'Odhalení podrobení — háže se automaticky při každém setkání s potenciálně podrobenou bytostí, kdy má mág lepší šanci než při minulém pokusu.'),
('Int+Roz', 'dle stupně ovládnutí terče (přítel 15, žák 12, sluha 9, otrok 6) − počet mágem úspěšně ovládnutých postav ("Roz"=rozdíl úrovní)', NULL,
   (SELECT id FROM efekty WHERE nazev='Ovládnutí odhaleno'), FALSE,
   'Odhalení ovládnutí — háže se automaticky bez soustředění při každém setkání s novou šancí na úspěch.'),
('Int (draka)', 'úroveň mága − 6 (žádost) / − 8 (rozkaz) / − 10 (zmámení)', NULL,
   (SELECT id FROM efekty WHERE nazev='Drak splní žádost/rozkaz'), FALSE,
   'Past hází drak (obránce); neúspěch draka = splní/vyplní/je zmámen. Žádost 2×/4h, rozkaz 1×/4h, zmámení 1×/24h na konkrétního draka.');

-- --- MÁG (obor Kouzelníka) ---
INSERT INTO zvlastni_schopnosti (nazev, druh, popis, uroven_od, mechanika, past_id) VALUES
('Posílení kouzel (Mág)', 'schopnost', 'Mág dobře rozumí psychice, takže při sesílání vybraných kouzel (Čtení myšlenek, Hypnóza, Kouzelná rušička, Montyho čardáš, Poslání, Sugesce, Svaž postavu, Zenerova karta, Zmatek) je nebezpečnost pasti pro terč o 1 vyšší.', 6, '+1 k nebezpečnosti pasti u vyjmenovaných psychických kouzel', NULL),
('Odolnost proti psychickým kouzlům (Mág)', 'schopnost', 'Mág má díky studiu mysli bonus +1 ke všem hodům proti pasti u kouzelnických kouzel působících na psychiku, seslaných na něj.', 6, '+1 k hodu proti pasti psychických kouzel na mága', NULL),
('Pomocná kouzla (Dvířka/Dveře/Brána)', 'schopnost', 'Mág smí sesílat obvyklým způsobem jen omezený seznam kouzel; ostatní musí vyvolávat přes jedno ze tří pomocných kouzel: Dvířka (1 mag, -50 % šance na úspěch), Dveře (1,5× magenergie zamýšleného kouzla, -25 % šance) nebo Brána (2× magenergie, beze změny šance). Pomocné kouzlo prodlužuje vyvolání o 1 kolo a samo se vždy podaří automaticky; přerušení mezi pomocným a zamýšleným kouzlem znamená ztrátu vynaložené magenergie.', 6, 'Dvířka: 1 mag/-50 %; Dveře: 1,5× magenergie/-25 %; Brána: 2× magenergie/beze změny šance', NULL),
('Podrobování', 'schopnost', 'Mág útočí na mysl inteligentní bytosti (ne magické nestvůry, ne jiného mága bez rozdílu úrovní, ne povolání z Tabulky nepodrobitelných povolání mimo příslušný rozdíl úrovní — Kouzelník/Čaroděj 12, Theurg/Druid 9, Hraničář 8, Chodec 7, Alchymista 6, Pyrofor 5 úrovní). Vzdálenost/přesnost/průchodnost překážky roste s úrovní mága (Tabulka vzdáleností, 6.-36. úroveň). Útočí Silou mysli (SM = 2×bonus za charizma ± 1 za každé 2 úrovně rozdílu vůči pevnosti mysli terče) proti Pevnosti mysli oběti (PM dle inteligence, Tabulka pevnosti mysli); oba hodí 1k6+ a přičtou SM/PM, rozdíl = ztracené životy oběti (útočník ztrácí 1 mag za 2 odebrané životy, nebo 1 mag při neúspěchu/mimo dosah). Klesnou-li životy oběti na 0, je mrtvá, nebo (mág 10.+ úrovně) ji lze podrobit vydáním magenergie = polovina ztracených životů — mág pak sdílí mysl s podrobeným tělem (BV systém, 0-4 body vnímání dle úrovně a rozdělení pozornosti, určuje možnosti těla od "minimální" po "plné" vnímání). Podrobování trvá 1 kolo (2 akce), lze zaslechnout (past Int-10-…-zaslechne/nezaslechne, šíří se 1 míli/kolo).', 6, 'SM=2×bonus Chr ±1/2 úrovně rozdílu; PM dle Int (Tabulka pevnosti mysli); hod 1k6+SM vs 1k6+PM; podrobení od 10.úr za magy=1/2 ztracených životů; BV 0-4 dle úrovně (od 10.úr)', NULL),
('Mentální souboj', 'schopnost', 'Mág (i proti povoláním z Tabulky nepodrobitelných povolání, ta ale sama vyvolat souboj nemohou) vede souboj SUM (síla mysli v útoku = ZSM+úroveň+bonus Chr) proti SOM (obrana = ZSM+úroveň+bonus Int) protivníka. ZSM dle povolání: Mág 10, Čaroděj/Kouzelník 9, Theurg 8, Druid 7, Chodec/Hraničář 6, Pyrofor/Alchymista 5. Všichni účastníci hlásí cíl útoku a hází 1k6 na iniciativu; vítěz hodu na útok (1k6+SUM) proti obraně cíle (1k6+SOM) mu při úspěchu odebere 2× rozdíl životů, nebo 4× rozdíl magů (má-li aktivní magenergii), nebo (nemá-li už magenergii) polovinu rozdílu z inteligence. Zranění tvora účastnícího se souboje vyšle "mentální vlnu" po přímce (síla = SUM/SOM viníka + 1k6, klesá se vzdáleností a KZ), zasažené odhazuje 1 sáh/10 ztracených životů. Stejná Tabulka vzdáleností jako u podrobování; lze zaslechnout.', 6, 'SUM/SOM = ZSM+úroveň+bonus(Chr/Int); vítěz odebere 2×rozdíl životů nebo 4×rozdíl magů nebo 1/2 rozdílu z Int', NULL),
('Kouzla bez omezení (Mág)', 'schopnost', 'Od 16. úrovně smí mág bez pomocných kouzel sesílat navíc: Davová hypnóza, Dotyk upíra, Duševní rozštěp, Kouzlo spánku, Pamatuj, Přetvělení, Usni, Vzpomeň, Zapomeň, Zapůjčení, Zastrašení. Může také bez omezení vkládat libovolná kouzla do svitků vyráběných ve spolupráci s pyroforem.', 16, 'Rozšíření seznamu kouzel sesílaných bez pomocných kouzel (dvířka/dveře/brána)', NULL),
('Mentální souboj (rozšíření)', 'schopnost', 'Od 16. úrovně může mág dočasně zvýšit svou sílu mysli (5 magů za +1, 10 za +2 atd.) nebo poskytnout Pomoc v obraně jinému účastníkovi souboje (ohlášeno před hodem na iniciativu; chráněný získá na celé kolo bonus k obraně = úroveň pomáhajícího, ten sám má o 1 akci/mentální útok méně a nesmí sám nikoho chránit ani být chráněn navíc; poloha pomáhajícího zůstává skryta).', 16, 'Zvýšení SUM/SOM: 5 magů/+1, 10/+2...; Pomoc v obraně: +bonus OČ mysli = úroveň pomáhajícího, cena 1 akce', NULL),
('Podrobování (rozšíření)', 'schopnost', 'Od 16. úrovně může mít mág podrobeno více obětí najednou (Tabulka počtu podrobených: 10.-19.úr 1, 20.-28.úr 2, 29.-36.úr 3). Umí poskytnout Ochranu před podrobováním (jako u mentálního souboje, zvyšuje PM a efektivní úroveň terče, vyžaduje plné soustředění celé kolo) a Odhalení podrobení (past Int+Roz proti 15 mínus počet úspěšně podrobených bytostí — automaticky při každém setkání s lepší šancí než dřív).', 16, 'Tabulka počtu podrobených: 1/2/3 dle úrovně (10.-19./20.-28./29.-36.); past odhalení Int+Roz-{15-N}-', (SELECT id FROM pasti WHERE vlastnosti='Int+Roz' AND obtiznost LIKE '15%')),
('Vysávání životů', 'schopnost', 'Temná schopnost — mág vysává životní energii inteligentní bytosti, kterou by mohl podrobit, a přidává si ji (max. 2× tolik životů/kolo než při podrobování by odebral, sám mág ztrácí 2× tolik životů, kolik jich předal sobě). Síla mysli proti terči je poloviční oproti podrobování (bonus Chr + rozdíl úrovní/4, zaokrouhleno dolů). Vzdálenost roste s úrovní: dotyk (16.-20.úr), 2 sáhy s pohledem do očí (21.-25.úr), 5 sáhů na dohled (26.-30.úr), 10 sáhů se znalostí polohy (31.-36.úr).', 16, 'SM poloviční oproti podrobování; max. 2× rozdíl životů předáno sobě, mág ztrácí 2× tolik, kolik předal', NULL),
('Předávání životů', 'schopnost', 'Opak vysávání životů — mág předává vlastní životy souhlasícímu inteligentnímu tvoru (i takovému, jehož by nemohl podrobit, pokud souhlasí a nehází si na obranu). Stejné vzdálenosti, síla/pevnost mysli a magenergie jako u vysávání životů; mágovi ubude dvojnásobek předaných životů.', 16, 'Stejné jako Vysávání životů, ale terč souhlasí a nehází na obranu; mág ztrácí 2× předaných životů', NULL),
('Ovládnutí', 'schopnost', 'Mág postupně manipuluje vůli oběti řečí posílenou magenergií (mechanismus jako podrobování — SM vs. PM, magenergie mágovi, "životy" terči vyjadřují míru přesvědčení). Čtyři stupně (Tabulka ovládnutí): přítel (4 měsíce mezi pokusy, radí se ve vedlejších věcech, nebezpečnost 15), žák (3 měsíce, radí se skoro ve všem, 12), sluha (2 měsíce, svěřuje se s problémy, 9), otrok (1 měsíc, splní i sebevražedné příkazy, 6). Postup o stupeň = ztráta "životů" rovná 4× stupni ovládnutí. Neúspěch = oběť nic nepozná; pokračování v neúspěšném pokusu posouvá oběť o stupeň dolů, další neúspěch ji osvobodí (nezávislá na 6 měsíců). Chránící mág dává své oběti bonus k PM = svá úroveň zdarma (Ochrana před ovládnutím). Lze odhalit (past Int+Roz proti nebezpečnosti dle stupně − počet úspěšně ovládnutých).', 16, 'Postup o stupeň = 4×stupeň "životů" ztraceno; past odhalení Int+Roz proti (nebezpečnost dle stupně − N)', (SELECT id FROM pasti WHERE vlastnosti='Int+Roz' AND obtiznost LIKE 'dle stupně ovládnutí%')),
('Drakomluva', 'schopnost', 'Od 16. úrovně se mág učí prastarou dračí řečí, kterou draka nelze zmámit (naopak mág se může pokusit zmámit jen divokého draka) a drak v ní vždy mluví pravdu. Žádost (past draka Int proti úroveň mága−6, 2×/4h, drak splní neškodné přání), Rozkaz (past proti úroveň mága−8, 1×/4h, splní není-li sebevražedné), Zmámení (past proti úroveň mága−10, 1×/24h na daného draka, jedná jako s nejlepším přítelem 1 den, mimo doslech 3 směny). Se stoupající úrovní mága se schopnost zlepšuje (nižší past pro draka = vyšší šance mága).', 16, 'Past draka: Int proti (úroveň mága−6/−8/−10) pro žádost/rozkaz/zmámení', (SELECT id FROM pasti WHERE vlastnosti='Int (draka)')),
('Základní síla', 'schopnost', 'Mágova nejvyšší schopnost — postupné pochopení Základního sporu (Dobro/Zlo, Pořádek/Chaos apod.) vládnoucího herním světem: rozpoznání povahy sporu (prvních 16 úrovní), rozpoznání postoje konkrétní osoby k němu (3 hodiny rozhovoru), rozpoznání dopadu zamýšlené akce na spor (6 hodin přemýšlení), rozpoznání akcí vedoucích k žádoucímu výsledku (3 dny přemýšlení). Nemá číselnou mechaniku ani pasti — obsah zcela určuje PJ podle svého herního světa; informace nemusí být úplné ani pravdivé.', 16, 'Bez číselné mechaniky — narativní schopnost řízená PJ (rozpoznání/analýza Základního sporu světa)', NULL);

-- --- PROPOJENÍ SE SCHOPNOST_POVOLANI ---
-- Pozn.: pokud `povolani` neobsahuje samostatný řádek 'Mág' (větev Kouzelníka),
-- je nutné jej doplnit v souboru definujícím povolání -- OVĚŘIT.
INSERT INTO schopnost_povolani (schopnost_id, povolani_id)
SELECT s.id, p.id FROM zvlastni_schopnosti s, povolani p WHERE
   s.nazev IN ('Posílení kouzel (Mág)','Odolnost proti psychickým kouzlům (Mág)','Pomocná kouzla (Dvířka/Dveře/Brána)',
               'Podrobování','Mentální souboj','Kouzla bez omezení (Mág)','Mentální souboj (rozšíření)',
               'Podrobování (rozšíření)','Vysávání životů','Předávání životů','Ovládnutí','Drakomluva','Základní síla')
   AND p.nazev='Mág';
-- =====================================================================
-- ČÁST 5: ZLODĚJ / LUPIČ / SICCO (h604-h692)
-- Vysoce prioritní sekce dle zadání. "Domácí verze" (h667-h692) z velké
-- části jen přeformulovává stejná pravidla — zaznamenána jen tam, kde
-- přináší číselně odlišný obsah (viz poznámky u jednotlivých schopností).
-- Očekávané názvy v `povolani`: 'Zloděj', 'Lupič', 'Sicco'.
-- =====================================================================

-- --- EFEKTY ---
INSERT INTO efekty (nazev, typ, cil, hodnota_vzorec, mechanika_aplikace, trvani, podminka_ukonceni, stackovatelne, tooltip_text) VALUES
('Zabit ranou ze zálohy (Sicco)', 'debuff', 'životy', 'okamžitá smrt (síla zabití = síla zbraně)', 'jednorazove', 'okamžité', NULL, FALSE, 'Cíl siccova útoku Zabití ze zálohy neuspěl v obraně a je na místě zabit.'),
('Klíč exploduje', 'debuff', 'životy', '2 (nebo 3 při odstraňování pasti) životy za každý mag v zámku/klíči', 'jednorazove', 'okamžité', NULL, FALSE, 'Lupičův magický klíč exploduje, když se pokusí pojmout více magenergie, než unese (běžně max. 16 magů).'),
('Zámek zajištěn kouzelnou pastí v zámku', 'dot', 'životy', 'plamen 20 coulů/mag, zranění dle vzdálenosti', 'pri_zasahu', 'jednorázové vybití', NULL, FALSE, 'Past nastražená lupičovým klíčem v zámku — vyšlehne plamen při manipulaci se zámkem.'),
('Šifra rozluštěna', 'debuff', 'informace', 'odhalení obsahu zprávy', 'jednorazove', 'okamžité', NULL, FALSE, 'Výsledek úspěšného hodu nepovolané osoby proti siccovské šifře.');

-- --- PASTI ---
INSERT INTO pasti (vlastnosti, obtiznost, efekt_uspech_id, efekt_neuspech_id, pouziva_4stupnovou_skalu, poznamka) VALUES
('Roz+Obr', 'kvalita zbroje oběti (bez štítu) + hodnota z Tabulky zabití (A=2, B=1, C=0)', NULL,
   (SELECT id FROM efekty WHERE nazev='Zabit ranou ze zálohy (Sicco)'), FALSE,
   'Sicco: Zabití. Past hází oběť útoku ze zálohy; neúspěch = zabita silou = síla siccovy zbraně. Neúspěch sicca = nemůže útočit ze zálohy příští kolo. Jen na lidi/humanoidy velikosti A-C zranitelné danou zbraní.'),
('Obr', '2 (zastrkávání klíče do magického zámku), +1 za každý vydaný mag', NULL, NULL, FALSE,
   'Lupičův Klíč — vydání magenergie do cizího/vlastního zámku; při neúspěchu ztrácí 1-3 životy za mag, a je-li magenergie zámku vyšší než kapacita klíče (obvykle 16 magů), klíč exploduje (efekt "Klíč exploduje").'),
('Roz+Int', '11 (nepovolaná osoba luští siccovskou šifru); sicco luštící cizí siccovskou šifru má nebezpečnost nižší', NULL,
   (SELECT id FROM efekty WHERE nazev='Šifra rozluštěna'), FALSE,
   'Šifrování (Sicco) — rozluštit smí jen tvor s inteligencí 8+; komu sicco sdělil klíč, luští automaticky.'),
('Int', '12', NULL, NULL, FALSE, 'Určení hodnoty pokladů (Lupič) — ověření pravosti dokumentu porovnáním s originálem: past Int−12 ~ odhalení padělku/nic.');

-- --- ZLODĚJ (základní obor) ---
INSERT INTO zvlastni_schopnosti (nazev, druh, popis, uroven_od, mechanika) VALUES
('Převleky', 'dovednost', 'Zloděj se může vydávat za příslušníka jiného povolání, pouze za stejnou/podobnou rasu. Šance = základ dle úrovně (5 % na 1.úr, +5 %/úroveň do 5.úr) + 3× bonus za charizma. Od 16. úrovně (Lupič) lze maskovat i jiné osoby a vytvářet figuríny (poloviční šance).', 1, 'Šance = tabulka dle úrovně + 3×bonus Chr'),
('Získání důvěry', 'dovednost', 'Zloděj se vetře do přízně jiné osoby; vyžaduje min. 10 kol rozhovoru/kontaktu. Šance = tabulka dle úrovně + 3×bonus Chr, upravená PJ dle okolností (převlek, podezření, chyba v jednání).', 1, 'Šance = tabulka dle úrovně + 3×bonus Chr; min. 10 kol kontaktu'),
('Objevení mechanismů', 'dovednost', 'Zloděj hledá skryté mechanismy (menší, složitější tajné věci jako pasti) — postřeh + tabulková hodnota + 2× bonus za obratnost. Při náhodném objevení odečítá od k% i bonus za obratnost a 1/2 úrovně.', 1, 'Postřeh + tabulka + 2×bonus Obr'),
('Objevení objektů', 'dovednost', 'Zloděj hledá skryté objekty (velké, jednoduché věci jako tajné dveře) — postřeh + tabulková hodnota + 3× bonus za obratnost.', 1, 'Postřeh + tabulka + 3×bonus Obr'),
('Zneškodnění mechanismů', 'dovednost', 'Zloděj se zlodějským nářadím (cca 20 mn, 30 zl) pokouší zneškodnit nalezený mechanismus (past, zámek apod.); každý pokus trvá 1 směnu, opakovatelný libovolně. Nefunguje na magicky zajištěné mechanismy (bez možnosti to předem poznat).', 1, 'Šance = tabulka dle úrovně + 2× bonus Obr; 1 směna/pokus'),
('Otevření objektů', 'dovednost', 'Obdoba zneškodnění mechanismů pro objekty (tajné dveře apod.) — stejná pravidla.', 1, 'Šance = tabulka dle úrovně + 3× bonus Obr'),
('Šplhání po zdech', 'dovednost', 'Zloděj šplhá po kolmé zdi se širokými spárami rychlostí 1 sáh/kolo; šance se ověřuje po každých 10 sázích, neúspěch = pád (lze zmírnit dovedností Skok z výšky).', 1, 'Šance = tabulka dle úrovně + bonus Obr; ověření po 10 sázích'),
('Skok z výšky', 'dovednost', 'Zloděj lépe zvládá dopad — při úspěchu počítá zranění z pádu, jako by skočil/spadl o 5 sáhů níž.', 1, 'Úspěch: efektivní výška pádu −5 sáhů'),
('Tichý pohyb', 'dovednost', 'Bezhlučný přesun rychlostí 2 sáhy/kolo; úspěch se ověřuje každé kolo, hráč se výsledek nedozví.', 1, 'Šance = tabulka dle úrovně + bonus Obr; 2 sáhy/kolo, ověření každé kolo'),
('Schování se ve stínu', 'dovednost', 'V částečně kryté, špatně osvětlené místnosti a mimo přímou pozornost nepřátel se zloděj může schovat (1 kolo pokus); pohyb ve stínu možný, útok schování ruší.', 1, 'Šance = tabulka dle úrovně + bonus Obr; 1 kolo/pokus'),
('Probodnutí ze zálohy', 'schopnost', 'Útok zezadu/ze zálohy s dvojnásobným zraněním (2× rozdíl hodů útok-obrana) oproti běžnému útoku zezadu. V rozšířeném systému vyžaduje, aby zloděj celé předchozí kolo nebyl v zorném poli oběti. Lze i mimo bojový manévr proti nic netušícímu cíli.', 1, '2× rozdíl (útok−obrana) jako zranění; podmínka: cíl netuší o útoku'),
('Vybírání kapes', 'dovednost', 'Zcizení drobného předmětu z kapsy/torny/váčku oběti; obvykle 1×/kolo, PJ upravuje dle ostražitosti oběti. Šance = tabulka dle úrovně + bonus Chr + bonus Obr.', 1, 'Šance = tabulka dle úrovně + 1×bonus Chr + 1×bonus Obr; obvykle 1×/kolo');

-- --- LUPIČ (obor Zloděje) ---
INSERT INTO zvlastni_schopnosti (nazev, druh, popis, uroven_od, mechanika, past_id) VALUES
('Nenápadnost', 'dovednost', 'Lupič budí dojem, že na dané místo přirozeně patří — prakticky "neviditelnost" v davu. Šance = tabulka dle úrovně + 2× bonus Obr, upravená Tabulkou nenápadnosti podle prostředí (dav lidí +66, hostinec +45 až +50, zostřené stráže −30 atd.). k% 01 = vždy úspěch, 00 = vždy fatální neúspěch. Ruší se aktivní činností (mluvení, útok).', 6, 'Šance = tabulka + 2×bonus Obr + úprava dle Tabulky nenápadnosti (−30 až +66)', NULL),
('Klíč', 'schopnost', 'Lupič obdrží na 6. úrovni magický klíč (křišťál, 8-16 magů, trvanlivost 2 roky, cena náhrady 1500-5000 zl, sžívání 6-11 dní). Umožňuje: Otevírání obyčejných zámků (+5 %/mag přítomný v klíči, +4 %/mag postupně vydaný za kolo), Otevírání magických zámků (past Obr proti nebezpečnosti 2+1/vydaný mag, nutno "vybít" zámek o 1 mag víc než jeho uzamykací magenergie — jinak klíč exploduje), Zamykání zámků (−5 % otevíratelnosti pro cizí zloděje/mag, +1 nebezpečnost vyražení/2 magy), Otevírání zámku uzamčeného lupičem (buď jako obyčejný, nebo "nasátím" magů — riziko exploze), Nastražení pasti v zámku (past Obr proti 2+1/mag, 1-3 životy/mag, plamen 20 coulů/mag, past jednorázová) a Odstranění pasti v zámku (jako běžné otevření, ale exploze zraní za 3 životy/mag místo 2).', 6, 'Viz jednotlivé použití; past Obr proti 2+X (X=vydané magy) pro magické zámky a pasti v zámku', (SELECT id FROM pasti WHERE vlastnosti='Obr' AND obtiznost LIKE '2 (zastrkávání%')),
('Určení hodnoty pokladů', 'dovednost', 'Lupič jako jediný umí odhadnout tržní cenu vzácných předmětů (kameny, šperky, umělecké předměty) dle Tabulky odhadu ceny (TODO: číselná tabulka se v předloze nedochovala, jen odkaz) a rozpoznat padělky (nikdy nemůže s jistotou potvrdit pravost). Padělky: jiné kameny/sklo, jiný kov/slitina, profesionální padělky unikátů. Ověření proti originálu/pečeti: past Int−12 ~ odhalení/nic se 4 stupni (fatální úspěch: past jen 6; úspěch: past 8; neúspěch: Int≥14 pozná sám, jinak past Int−5; fatální neúspěch: navíc okolí uvěří v kvalitu padělku). Od 16. úrovně +5 % k šanci, od 26. úrovně +10 %.', 16, 'Past Int−12 ~ odhalení padělku/nic (4 stupně výsledku, viz popis) -- TODO: Tabulka odhadu ceny chybí v předloze', (SELECT id FROM pasti WHERE vlastnosti='Int' AND obtiznost='12')),
('Boj beze zbraně (Lupič)', 'schopnost', 'Lupičův bojový styl proti lidem/humanoidům velikosti A-C: Boj v obraně (uskočení + podražení, sníží zranění na max. 2× bonus Obr, dá protivníkovi −5 na příští obranu; 1×/kolo na 6.-10.úr, 2×/kolo na 11.-15.úr, 3×/kolo na 16.-25.úr za 3× bonus Obr, 4×/kolo od 26.úr za 4× bonus Obr) a Boj v útoku (cílení na citlivá místa dle pásem I-III, síla zbraně dle úrovně/obratnosti nezávisle na útočnosti, výskok/otočka o 180°/360° mění dosah a přesnost, vždy jen stínové zranění). Od 16. úrovně navíc údery kolenem (pásma I-II, +12 %) a loktem (pásmo II, +8 %, i za sebe) a rychlé vstávání (1 akce). Obrana beze zbraně má menší postih: −2 (6.úr), −1 (14.úr) proti humanoidům; od 16. úrovně i menší postih proti nebezpečným nehumanoidům (−2, od 25.úr −1).', 6, 'Síla zbraně dle Tabulky boje beze zbraně (úroveň); vícenásobné útoky dle úrovně (5/2kola, 3/kolo, 7/2kola) -- TODO: Tabulka citlivých míst a Tabulka posunu podle velikosti (PPP) se v předloze nedochovaly, jen PPE rozšíření je kompletní', NULL),
('Vrh (Lupič)', 'schopnost', 'Lupič má bonus k útoku lehkou/střední vrhací zbraní a k iniciativě, rostoucí s úrovní: 6.úr +1 ÚČ/+2 Ini, 12.úr +3 Ini, 18.úr +2 ÚČ, 20.úr 2×/kolo (+6 Ini), 24.úr +3 ÚČ, 30.úr +4 ÚČ a 5×/2kola (+9 Ini). Malou lehkou zbraň lze vytáhnout z úkrytu a vrhnout v jednom kole.', 6, 'ÚČ +1/+2/+3/+4 (6./18./24./30.úr); útoky 1×(6.úr)→2×/kolo(20.úr)→5×/2kola(30.úr)', NULL),
('Útěk z pout', 'dovednost', 'Šance = tabulka dle úrovně + 3× bonus Obr; platí pro provaz i pouta, řetězy jen 1/4 šance, spoutal-li jiný lupič, −jeho úroveň. Neúspěch s provazem zraní 1-3 životy.', 16, 'Šance = tabulka + 3×bonus Obr (řetězy 1/4, spoutal-li lupič −jeho úroveň)', NULL),
('Imitace hlasu', 'dovednost', 'Napodobení slyšeného hlasu/zvuku. Šance = tabulka dle úrovně + 2× bonus Obr, upravená Tabulkou imitace (−10 % až +20 % dle známosti zvuku imitátorem a terčem).', 16, 'Šance = tabulka + 2×bonus Obr ± úprava dle známosti zvuku (Tabulka imitace)', NULL),
('Útok z výšky', 'schopnost', 'Varianta probodnutí ze zálohy — seskok (max. 5 sáhů) na nic netušící oběť, se zbraní i beze zbraně. Vícenásobné útoky lupiče (16.-22.úr 5/2kola +9 Ini, 23.-30.úr 3/kolo +12 Ini, 31.-36.úr 7/2kola +15 Ini).', 16, 'Jako probodnutí ze zálohy, max. seskok 5 sáhů', NULL),
('Zlepšení smyslů', 'schopnost', 'Při postupu na úroveň si lupič může jednou vylepšit jeden smysl (trvale, cena orientační): Zrak (15 zl, noční/ostré vidění, postih ve tmě jen −2, +10 % Tichý pohyb, +5 % Schování, −20 %/−5 % šance jiných zlodějů), Sluch (10 zl, +50 % postřeh sluchem, postih boje se slyšeným-neviděným jen −3, +10 % Tichý pohyb, +10 % Imitace, −30 % šance jiných zlodějů na Tichý pohyb), Hmat (20 zl, rozpoznání materiálů/teploty, +5 % cena pokladů, +10 % pravost, +5 % k Objevení mechanismu/Zneškodnění/Otevření objektu/Šplhání/Vybírání kapes/Útěku z pout), Čich (12 zl, +25 % postřeh čichem, postih boje se cítěným-neviděným −1 až −2, −10 %/−5 % šance jiných zlodějů, +1 vaření), Chuť (8 zl, +8 % rozpoznání padělků kamenů/kovů, +50 % postřeh chutí, +1 vaření) a Rovnováha (15 zl, +5 % šplhání a skok z výšky, +1 až +2 k pastem u akrobacie).', 16, 'Jednorázové trvalé vylepšení 1 smyslu na úroveň, viz konkrétní bonusy v popisu', NULL),
('Šestý smysl', 'schopnost', 'Od 16. úrovně má lupič automatický "instinkt": šance = úroveň + stupeň charizmy (+5 % navíc hobit). Zahrnuje Pocit smrtelného nebezpečí (automatický hod PJ při bezprostředním smrtelném ohrožení), Přítomnost magického nebezpečí (ano/ne/nevíš na dotaz o místě/předmětu/tvorovi), Použití v boji (částečné spolehnutí beze změny šance; úplné spolehnutí +50 % šance, ale neúspěch = automaticky fatální) a Použití při jiné (nonverbální) činnosti. V boji úspěch ruší postih −5 za boj poslepu a dává bonus 3× bonus Obr k OČ/ÚČ; neúspěch ponechává postih −5; fatální neúspěch přidává postih jako na nehybný cíl (obrana) nebo riskantní omyl (útok). Nefunguje proti plošným/prostorovým účinkům (exploze, dech draka).', 16, 'Šance = úroveň + stupeň Chr (+5 hobit); v boji ±3×bonus Obr k ÚČ/OČ dle úspěchu/neúspěchu', NULL);

-- --- SICCO (obor Zloděje) ---
INSERT INTO zvlastni_schopnosti (nazev, druh, popis, uroven_od, mechanika, past_id) VALUES
('Zabití', 'schopnost', 'Sicco se při útoku ze zálohy pokouší oběť zabít jedním zásahem: past Roz+Obr proti (kvalita zbroje bez štítu + Tabulka zabití dle velikosti: A=2, B=1, C=0). Síla zabití = síla zbraně. Jen na lidi/humanoidy velikosti A-C zranitelné danou zbraní. Neúspěch sicca = nemůže útočit ze zálohy příští kolo.', 6, 'Past Roz+Obr proti (KZ+Tabulka zabití); síla=síla zbraně', (SELECT id FROM pasti WHERE vlastnosti='Roz+Obr')),
('Vrh (Sicco)', 'schopnost', 'Sicco vytahuje a vrhá malou lehkou zbraň v 1 kole od 6. úrovně; bonus k útoku roste: +1(10.úr), +2(16.úr,+2 Ini), +2(20.úr, 3×/2kola +3 Ini), +3(30.úr).', 6, 'ÚČ +1(10.úr)/+2(16.úr)/+3(30.úr); 3×/2 kola od 20.úr', NULL),
('Boj s dýkou', 'schopnost', 'Mistrovství v lehkých bodných zbraních (dýka, tesák, krátký meč): +1 ÚČ (6.úr), 3×/2kola (8.úr, +3 Ini), +2 ÚČ (12.úr), 2×/kolo proti humanoidům nebo 3×/2kola proti ostatním (16.úr), +3 ÚČ (20.úr), 5×/2kola proti humanoidům nebo 2×/kolo proti ostatním (25.úr).', 6, 'Progrese ÚČ a počtu útoků dle úrovně, viz popis', NULL),
('Odhad lidí', 'dovednost', 'Sicco téměř okamžitě odhadne povahu (podvodník/hlupák/předstíraný hlupák), NE pravdivost aktuální řeči. Šance = tabulka dle úrovně − 15× bonus/postih za inteligenci posuzované osoby, upravitelná PJ. Jen 1×/setkání na danou osobu.', 6, 'Šance = tabulka − 15×bonus Int oběti; 1×/setkání', NULL),
('Síť (základní budování)', 'schopnost', 'Sicco buduje tři typy sítí — výkonnou (zprostředkuje krádež/přepadení/vraždu/únos/sabotáž za sazbu × úroveň oběti, past síla sítě vs. úroveň oběti, nebezpečnost 4), výzvědnou (zjistí informaci zdarma, stejná past) a ochrannou (pasivní obrana při odhalení, ÚČ=úroveň oběti, OČ=úroveň sítě). Max. úroveň sítě = min(úroveň sicca, úroveň nejvyšší autority města). Údržba 25 zl/týden/úroveň, jinak −1 úroveň/týden. Budování dle Tabulky budování sítě (rychlejší tempo = vyšší cena za úroveň, od 12 zl/2 dny za úroveň 1 po tisíce zl při zrychlení na hodiny).', 6, 'Past síla sítě vs. úroveň oběti, nebezpečnost 4; údržba 25 zl/týden/úroveň', NULL),
('Sítě: odhalování a souboj sítí', 'schopnost', 'Od 16. úrovně dokáže sicco odhalit cizí síť, která se projevila v posledních 24 hodinách (max. 1×/6h/síť): ÚČ=úroveň sicca+úroveň jeho výzvědné sítě, OČ=úroveň skrývajícího sicca+2×úroveň města−úroveň odhalované sítě. Úspěch odhalí síť (a při dostatečném rozdílu i sicca za ní) a umožní zjistit rozdíl-hodů úkolů sítě. Neúspěch dává bránícímu +2 ÚČ na okamžitý protiúder mimo 6h limit. Napadení odhalené sítě: ÚČ=úroveň sicca+výkonná síť, OČ=úroveň sicca+napadená síť; výhra snižuje úroveň napadené sítě (na 0 = lze zaútočit přímo na sicca, není-li chráněn).', 16, 'ÚČ/OČ dle úrovní sicca+sítě vs. obránce+město−síť; útok na síť: úroveň+výkonná síť vs. úroveň+napadená síť', NULL),
('Nové schopnosti sítí', 'schopnost', 'Od 16. úrovně: Sledování (past bonus rozdílu úrovní výzvědné sítě vs. oběti, nebezpečnost 3/4/5 dle typu oběti civilista/zloděj/sicco, ověřuje se každé 2 hodiny), Sabotáž (výkonná síť poškodí stavbu za částku/úroveň sítě = "poškození na úroveň", Tabulka sabotáže dává % úplného/částečného úspěchu/neúspěchu/odhalení dle poškození na úroveň a přítomných vojáků) a Ochrana osob/staveb (ochranná síť jako OČ = úroveň sítě + bonus výzvědné sítě, chrání max. tolik osob, kolik je úroveň ochranné sítě; ochrana staveb zvyšuje efektivní "poškození na úroveň" útočníkovi dle Tabulky ochrany před sabotáží).', 16, 'Sledování past bonus(ÚS−oběť) proti nebezp. 3/4/5; Sabotáž dle Tabulky sabotáže (poškození na úroveň)', NULL),
('Síť vlivu', 'schopnost', 'Od 16. úrovně buduje sicco vlivovou síť ovlivňující spokojenost obyvatelstva: snížení o 2 (16.úr, +1/úroveň dál) nebo zvýšení o 1 (16.úr, +1 za každou druhou úroveň) týdně, zvyšuje pravděpodobnost revolty o 5 % (16.úr) +1 %/úroveň. Šance neúspěchu dle Tabulky sítě vlivu (10-95 % dle aktuální spokojenosti, horší spokojenost = obtížnější další zhoršení); dvojnásobek této šance = selhání a nutnost záchrany ochrannou sítí.', 16, 'Snížení spokojenosti 2+1/úr, zvýšení 1+1/2úr; šance neúspěchu dle Tabulky sítě vlivu', NULL),
('Zemské sítě', 'schopnost', 'Od 16. úrovně buduje sicco sítě (výzvědnou/výkonnou/vlivovou/ochrannou) pro celou zemi z hlavního města, dle stejné Tabulky budování sítě jako městské (jen delší doby). Zprávy/příkazy se šíří rychlostí 50 mil/den. Souboj dvou zemských sítí jako městských (úroveň země místo města). V provinčním městě má zemská síť poloviční efektivní úroveň sicca a při zničení tam neohrožuje sicca v hlavním městě.', 16, 'Šíření zpráv 50 mil/den; souboj sítí jako u městských, s úrovní země', NULL),
('Výpad a kryt (Sicco)', 'schopnost', 'Od 12. úrovně bonus +1 k vybranému hodu na útok/obranu a postih −2 k opačným hodům (ohlášeno před hodem na iniciativu).', 12, '+1/-2 (útok nebo obrana dle volby)', NULL),
('Klamání pláštěm', 'dovednost', 'Sicco se snaží dezorientovat cíl pohybem pláště: úspěch (šance z tabulky + 2× bonus Obr) dá protivníkům do velikosti C postih −2 na útok i obranu po celý souboj a umožní 1 klamný útok/kolo (vyčerpá protivníkovu obranu bez zranění); od 22. úrovně 2 klamné útoky/kolo, od 30. úrovně 3. Neúspěch = beze změny; fatální neúspěch = sicco sám má −1 na útok i obranu (zamotal se do pláště).', 16, 'Šance = tabulka + 2×bonus Obr; úspěch: −2 ÚČ/OČ cíli + N klamných útoků/kolo (N=1/2/3 dle úrovně)', NULL),
('Umění diplomacie', 'dovednost', 'Zahrnuje Získání důvěry a Odhad lidí (viz výše, se sníženými/zvýšenými bonusy dle inteligence oběti z Tabulky diplomatických schopností) a nové schopnosti: Vytáhnutí znalostí (vytáhne z oběti odpověď na konkrétní otázku), Přesvědčování (přiměje oběť k činu/nečinnosti, ne k jisté smrti/těžkému zranění) a Zahánění nepřátel (odežene bezvýznamné útočníky za 1 kolo řeči, lze na více cílů najednou — dělí se šance počtem útočníků, opravy dle nejchytřejšího z nich). Získání důvěry navíc dává +10 % ke zbylým diplomatickým schopnostem (−10 % při fatálním neúspěchu). Ostatní (mimo Zahánění nepřátel) vyžadují min. 1 směnu rozhovoru.', 16, 'Šance = tabulka dle úrovně × bonus Chr ± Tabulka diplomatických schopností (dle Int oběti)', NULL),
('Antiplášť', 'dovednost', 'Sicco potlačí vlastní zlý úmysl natolik, že alchymistický "plášť" (varovná zbroj) spustí poplach až v kole skutečného napadení, ne při přiblížení. Šance z tabulky dle úrovně + 1× bonus Chr.', 16, 'Šance = tabulka + 1×bonus Chr', NULL),
('Šifrování', 'dovednost', 'Sicco šifruje libovolnou zprávu (i v neznámém jazyce); rozluští ji jen ten, komu sdělil klíč, nebo tvor s inteligencí 8+, který uspěje v pasti Roz+Int proti 11 (nižší nebezpečnost, luští-li sicco cizí siccovskou šifru).', 16, 'Past Roz+Int proti 11 pro nepovolané luštění', (SELECT id FROM pasti WHERE vlastnosti='Roz+Int')),
('Prchání', 'dovednost', 'Ve městě může sicco při útěku využívat průchodů, šplhání po stěnách a přeskakování střech místo běžných pravidel o rychlosti pohybu (šance z tabulky dle úrovně + bonus Obr); v přírodě/jeskyních platí běžná pravidla rychlosti.', 16, 'Šance = tabulka + 1×bonus Obr (jen ve městě)', NULL),
('Odhad úrovně města', 'dovednost', 'Nutné pro budování sítí — sicco musí být ve městě/centru země alespoň hodinu, aby odhadl jeho úroveň; síť lze začít budovat už během této hodiny.', 16, 'Šance = tabulka + 1×bonus Chr; nutná min. 1 hodina ve městě', NULL),
('Nečitelnost', 'schopnost', 'Trvalá, nesoustředěná ochrana siccovy mysli před telepatií a čtením myšlenek (i hraničářskou telepatií). Není v tabulce pravděpodobností — mechanismus (a přesná úroveň získání) je odkázán do Příručky PJ, mimo rozsah tohoto dokumentu.', 16, NULL, NULL);

-- --- PROPOJENÍ SE SCHOPNOST_POVOLANI ---
INSERT INTO schopnost_povolani (schopnost_id, povolani_id)
SELECT s.id, p.id FROM zvlastni_schopnosti s, povolani p WHERE
   (s.nazev IN ('Převleky','Získání důvěry','Objevení mechanismů','Objevení objektů','Zneškodnění mechanismů',
                'Otevření objektů','Šplhání po zdech','Skok z výšky','Tichý pohyb','Schování se ve stínu',
                'Probodnutí ze zálohy','Vybírání kapes') AND p.nazev='Zloděj')
OR (s.nazev IN ('Nenápadnost','Klíč','Určení hodnoty pokladů','Boj beze zbraně (Lupič)','Vrh (Lupič)',
                'Útěk z pout','Imitace hlasu','Útok z výšky','Zlepšení smyslů','Šestý smysl') AND p.nazev='Lupič')
OR (s.nazev IN ('Zabití','Vrh (Sicco)','Boj s dýkou','Odhad lidí','Síť (základní budování)',
                'Sítě: odhalování a souboj sítí','Nové schopnosti sítí','Síť vlivu','Zemské sítě',
                'Výpad a kryt (Sicco)','Klamání pláštěm','Umění diplomacie','Antiplášť','Šifrování',
                'Prchání','Odhad úrovně města','Nečitelnost') AND p.nazev='Sicco')
-- "Střelba ze zálohy" je společná Lupiči i Siccovi
OR (s.nazev='Střelba ze zálohy' AND p.nazev IN ('Lupič','Sicco'));

INSERT INTO zvlastni_schopnosti (nazev, druh, popis, uroven_od, mechanika) VALUES
('Střelba ze zálohy', 'schopnost', 'Obdoba Probodnutí ze zálohy pro střelnou/vrhací zbraň na krátkou vzdálenost — cíl nesmí do zásahu tušit; zranění dvojnásobné (2× rozdíl hodů útok-obrana).', 6, '2× rozdíl (útok−obrana) jako zranění; jen na krátkou vzdálenost, cíl nic netuší');

INSERT INTO schopnost_povolani (schopnost_id, povolani_id)
SELECT s.id, p.id FROM zvlastni_schopnosti s, povolani p WHERE s.nazev='Střelba ze zálohy' AND p.nazev IN ('Lupič','Sicco');
-- =====================================================================
-- ČÁST 6: HOMEBREW — TULÁK / BARD / PAMĚTNÍK / KROTITEL (h693-h934)
-- Písně barda (h715-h793), ságy/runy pamětníka (h808-h902) a krotitelovy
-- aspekty/příkazy bičem (h906-h929, h932-933) jsou formátovány jako
-- kouzla (magenergie/dosah/vyvolání/trvání) a jsou MIMO ROZSAH tohoto
-- importu (viz `kouzla`). Zde jen rámcové ne-kouzelné schopnosti/dovednosti.
-- Očekávané názvy v `povolani`: 'Tulák', 'Bard', 'Pamětník', 'Krotitel'.
-- =====================================================================

-- --- EFEKTY ---
INSERT INTO efekty (nazev, typ, cil, hodnota_vzorec, mechanika_aplikace, trvani, podminka_ukonceni, stackovatelne, tooltip_text) VALUES
('Polichocen (Tulák)', 'buff', 'vybraná vlastnost', '+1 (+2 od 9. úrovně tuláka)', 'jednorazove', 'do druhého dne (po spánku)', 'spánek', FALSE, 'Cíl tulákova lichocení má dočasně zvýšenou vybranou vlastnost (bez vlivu na životy/magenergii); max. 21+5.');

-- --- PASTI ---
INSERT INTO pasti (vlastnosti, obtiznost, efekt_uspech_id, efekt_neuspech_id, pouziva_4stupnovou_skalu, poznamka) VALUES
('Int', '6 + 1/2 charizmatu tuláka', NULL, (SELECT id FROM efekty WHERE nazev='Polichocen (Tulák)'), FALSE,
   'Past se hází za cíl lichocení (Tulák); čím nižší inteligence cíle, tím snáze uvěří.');

-- --- TULÁK (základní homebrew povolání) ---
INSERT INTO zvlastni_schopnosti (nazev, druh, popis, uroven_od, mechanika) VALUES
('Pouliční dovednosti', 'dovednost', 'Tulák si na 1. úrovni vybírá jednu ze 4 kategorií pouličních dovedností (Jednání s lidmi: Převleky/Získání důvěry/Odhad lidí; Postřeh a zručnost: Objevení/Zneškodnění mechanismu, Objevení/Otevření objektu; Schovávání se: Šplhání po zdech/Skok z výšky/Tichý pohyb/Schování ve stínu; Zákeřnost: Vybírání kapes/Nenápadnost/Probodnutí ze zálohy). Šance roste dle tabulky do 10. úrovně (dál se nezlepšují).', 1, 'Tabulka pravděpodobností dle úrovně 1-10 a kategorie (viz zlodějovy ekvivalentní dovednosti) -- TODO: chybí přesné znění zvláštního pravidla pro Probodnutí ze zálohy tuláka a možný překlep u Odhadu lidí (9.úr hodnota vyšší než 10.úr)'),
('Vrhací zbraně (Tulák)', 'schopnost', 'Tulák má +1 ÚČ ke všem vrhacím zbraním.', 1, '+1 ÚČ vrhací zbraně'),
('Hbitost (Tulák)', 'schopnost', 'Od 2. úrovně má tulák +1 k hodu na obranu.', 2, '+1 OČ'),
('Lichocení', 'schopnost', 'Tulák lichotí osobě, kterou zná alespoň pár hodin (max. 1 tulák/den na osobu); past Int-{6+1/2 Char tuláka}- polichocen/nic. Při polichocení má cíl do dalšího spánku zvýšenou libovolnou vlastnost o +1 (od 9. úrovně tuláka +2, max. 21+5, žádný vliv na životy/magenergii). Lichocení trvá 1 směnu.', 1, 'Past Int proti (6+1/2 Char tuláka); efekt +1 (+2 od 9.úr) k vybrané vlastnosti do spánku'),
('Umělecké vlohy', 'dovednost', 'Tulák se snadno učí uměleckým dovednostem (Přilákání davu, Tanec, Zpěv, Herectví, Hudba, Imitace humanoidních hlasů) — na 1. úrovni 8× bonus za charizma místo obvyklého 5×. Na 6. úrovni se z tuláka stává bard nebo pamětník.', 1, '8× (místo 5×) bonus Chr k uměleckým dovednostem na 1. úrovni');

-- --- BARD (obor Tuláka) — rámcové ne-kouzelné mechaniky ---
INSERT INTO zvlastni_schopnosti (nazev, druh, popis, uroven_od, mechanika) VALUES
('Vtipálek', 'schopnost', 'Pokud se bard může projevovat (mluvení/hudba/klaunské kousky), všichni členové družiny cestující s ním získávají za každou hodinu odpočinku o 1 bod únavy navíc odpočatý (celkem max. 3 body únavy/hodinu).', 6, 'Odpočinek +1 bod únavy/hodinu navíc, max. 3/hodinu celkem'),
('Jamování', 'schopnost', 'Bard doplňuje magenergii hraním/zkoušením nových písní: 1 hodina, 1 bod únavy, doplní veškerou magenergii; přerušení = žádný zisk. Nelze při únavě stupně 2 a vyšší.', 6, '1 h, 1 bod únavy → plná magenergie'),
('Miláček všech', 'schopnost', 'Bard má bonus k hodům na charizma: +1 od 10. úrovně, +2 od 20. úrovně.', 10, '+1 (10.úr) / +2 (20.úr) k hodům na charizma'),
('Vojenská kapela', 'schopnost', 'Během sesílání může bard chodit; od 10. úrovně i běhat (ne sprintovat) nebo jet na klusajícím/cválajícím jezdeckém zvířeti.', 6, 'Pohyb během kouzlení: chůze (6.úr), běh/klus/cval (10.úr)'),
('Bardova únava za kouzlení', 'schopnost', 'Únava se počítá jen z komponentů potřebných k seslání za směnu boje (i započatou): hlas 1 bod, nástroj 1 bod, tanec 2 body — počet kouzel v rámci jedné směny na únavu nemá vliv.', 6, 'Hlas 1/nástroj 1/tanec 2 body únavy za směnu boje (bez ohledu na počet kouzel)'),
('Psychické zranění (Bard)', 'schopnost', 'Bardova specifická psychická zranění lze léčit jen alchymistickými lektvary nebo přirozenou regenerací spánkem.', 6, 'Léčitelné jen lektvary nebo spánkem'),
('Iniciativa hráče (Bard)', 'schopnost', 'Když bard sesílá, první akcí je píseň a v boji věnuje hraní alespoň polovinu akcí kola; bonus k iniciativě roste s úrovní (+1 až +8 po dvojicích úrovní).', 6, 'Bonus k iniciativě +1 až +8 postupně dle úrovně -- TODO: přesné hranice úrovní pro jednotlivé stupně bonusu nejsou v přepisu jednoznačně přiřazené (jen seznam hodnot)'),
('Učení se písním', 'schopnost', 'Bard se učí dvě libovolné písně za úroveň (musí mít magenergii na seslání a splňovat úrovňové podmínky; číslované varianty vyžadují dřívější naučení nižších stupňů). Od 36. úrovně bez omezení počtu známých písní.', 6, '2 nové písně/úroveň (řetězené číslované varianty); bez limitu od 36.úr'),
('Skládání písní', 'schopnost', 'Od 16. úrovně může bard po domluvě s PJ skládat vlastní písně (sonety, tance, odrhovačky), musí mít kapacitu na jejich naučení.', 16, 'Tvorba vlastních písní po domluvě s PJ'),
('Bardův nástroj', 'schopnost', 'Bardův hudební nástroj (libovolný typ, stejné parametry) slouží jako ohnisko jeho magie; lze jím i normálně bojovat jako zbraní (ÚČ+1/útočnost+0/OČ+1 v kombinaci s jednoruční zbraní). Váha 40 mn, cena 1000 zl, neomezená výdrž.', 6, 'Nástroj: +1 ÚČ / +0 útočnost / +1 OČ v kombinaci se zbraní -- Pozn.: řádek "3 -1 +2" u Parametrů nástroje odpovídá formátu ÚČ/útočnost/OČ (ÚČ 3, útočnost -1, OČ +2) dle konvence vyřešené jinde v předloze.'),
('Komponenty bardova kouzlení', 'schopnost', 'Bardova kouzla vyžadují komponenty H (hlas), N (nástroj) a/nebo T (tanec), samostatně nebo kombinovaně; vynechání komponentu zdvojnásobuje cenu magenergie za každý vynechaný komponent (píseň se 3 komponenty bez jednoho stojí 4× tolik). Mimo boj: hodina zpěvu/hraní = 1 bod únavy, směna tance = 2 body únavy.', 6, 'Vynechaný komponent = 2× magenergie za komponent (kumulativně)');

-- --- PAMĚTNÍK (obor Tuláka) — rámcové ne-kouzelné mechaniky ---
INSERT INTO zvlastni_schopnosti (nazev, druh, popis, uroven_od, mechanika) VALUES
('Inspirace', 'schopnost', 'Pamětníkova obdoba bardovy schopnosti povzbuzovat družinu (analogicky Vtipálkovi) — rámcová schopnost pamětníka od 6. úrovně.', 6, 'Obdoba Vtipálka pro pamětníka -- TODO: přesný text schopnosti ověřit proti úplnějšímu zdroji'),
('Korekce', 'schopnost', 'Pamětníkova doplňková schopnost k jeho kronice/vyprávění, umožňující opravovat/upřesňovat zaznamenané informace.', 6, 'TODO: přesný mechanismus ověřit proti úplnějšímu zdroji'),
('Pouto s trollobíjcem', 'schopnost', 'Pamětník má zvláštní pouto s trollobijcem, kterého doprovází — trollobijec od něj (na rozdíl od jiných) přijímá pomoc a magické efekty (viz Trollobijecká čest).', 6, 'Umožňuje trollobijci přijmout pomoc/magii od jeho pamětníka'),
('Pamětníkova únava za kouzlení', 'schopnost', 'Analogicky bardově únavě — počítána jen z použitých komponentů za směnu, ne z počtu kouzel.', 6, 'Jako u barda: dle komponentů za směnu, ne dle počtu kouzel'),
('Iniciativa mluvčího', 'schopnost', 'Bonus k iniciativě pamětníka při sesílání/vyprávění od 7. úrovně, obdoba bardovy Iniciativy hráče.', 7, 'Bonus k iniciativě dle úrovně -- TODO: přesné hodnoty ověřit'),
('Iniciativa válečného knihovníka', 'schopnost', 'Rozšíření Iniciativy mluvčího od 8. úrovně.', 8, 'TODO: přesné hodnoty ověřit proti úplnějšímu zdroji'),
('Iniciativa runotepce', 'schopnost', 'Další rozšíření iniciativy pamětníka od 20. úrovně, spojené s runovou magií.', 20, 'TODO: přesné hodnoty ověřit'),
('Pamětníkova kronika', 'schopnost', 'Pamětníkova kniha slouží jako ohnisko jeho magie a zápisník dějů, které zaznamenává (obdoba bardova nástroje).', 6, 'Kniha jako kouzelnické ohnisko + kronika událostí'),
('Parametry knihy', 'schopnost', 'Pamětníkova kniha má bojové parametry ÚČ 4 / útočnost +1 / OČ +1 (formát ÚČ/útočnost/OČ, ověřeno uživatelem).', 6, 'Kniha: ÚČ 4 / útočnost +1 / OČ +1'),
('Učení se kouzlům (Pamětník)', 'schopnost', 'Obdoba bardova Učení se písním — pamětník se učí sagy/runy/verše dle stejného principu (číslované řady, magenergie, úrovňové podmínky).', 6, 'Analogie Učení se písním u barda'),
('Skládání ság', 'schopnost', 'Od 16. úrovně může pamětník po domluvě s PJ skládat vlastní ságy/verše, obdoba bardova Skládání písní.', 16, 'Analogie Skládání písní u barda'),
('Runová magie', 'schopnost', 'Trpasličí pamětníci od 16. úrovně ovládají runovou magii — sadu run (Ocel, Odhalení, Hrom, Volnost, Síra, Zničení, Zášť, Voda, Skok, Oběť, Lékárník, Slunce), formálně vedenou jako kouzla (magenergie/dosah/vyvolání), zpracovává samostatný skript `kouzla`.', 16, 'Viz `kouzla` — jednotlivé runy (Runa Oceli I-III atd.) mimo rozsah tohoto importu -- Pozn.: zdroj u Runy Oceli II/III chybně odkazuje na neexistující "Runu ochrany I/II" místo "Runu Oceli I/II".');

-- --- KROTITEL (obor Tuláka) ---
INSERT INTO zvlastni_schopnosti (nazev, druh, popis, uroven_od, mechanika) VALUES
('Rozmazlování', 'schopnost', 'Krotitel doplňuje magenergii mazlením/hrou se svým ochočeným zvířetem: 1 hodina, 1 bod únavy, doplní veškerou magenergii.', 6, '1 h, 1 bod únavy → plná magenergie (jen s vlastním ochočeným zvířetem)'),
('Krotitelská torna', 'schopnost', 'Speciální mimoprostorový vak (vyrábí alchymista od 5. úrovně; první dostává krotitel na 6. úrovni nebo koupí za 5 zl základ + 30 magů výroby, váha 30 mn, výdrž 1 rok). Ukládá aspekty zvířat (kapacita +3 za každé 4 úrovně) a od 10. úrovně i dospělá zvířata (1 za každých 10 úrovní). Vkládání/vyjímání mimo boj trvá 1 směnu.', 6, 'Kapacita aspektů +3/4 úrovně; kapacita zvířat 1/10 úrovní (od 10.úr)'),
('Jesle', 'schopnost', 'Pasivní vlastnost torny — uchová vejce/mláďata (čas jim plyne normálně, nutno krmit), max. 3 mláďata do velikosti D. Roztržení vaku zraní vše uvnitř za 10k10+5 životů. Obsluha 1 tvora trvá 2 směny a 1 bod únavy, není-li řečeno jinak.', 6, 'Max. 3 mláďata (do vel. D); poškození vaku = 10k10+5 zranění'),
('Odhadování zvěře', 'dovednost', 'Šance poznat atribut pozorovaného tvora (životaschopnost, útok, obrana, výcviky, vlivy) = 1 % za úroveň krotitele (základ 0 %); 1 údaj najednou (2 od 12.úr, 3 od 24.úr). V klidu nutná min. 1 směna pozorování, v boji stačí 1 kolo. Bonusy: spí +1 %, pohybuje se +5 %, bojuje +20 %, již se setkal +25 %, má tvora ve vaku +35 %, bojuje sám +25 %, bojuje družina +15 %. Nikdy 100% jistota.', 6, 'Šance = 1 %/úroveň + situační bonusy (viz popis); 1/2/3 údaje dle úrovně (6./12./24.úr)'),
('Ochočování zvěře', 'dovednost', 'Krotitelovo ochočování (primárně Charisma) trvá 3-30 dní; bonus k hodu roste s úrovní (+1/+2/+3 na neurčených prahových úrovních). Jen běžná zvířata s Int ≤3, ne společenský hmyz.', 6, 'Bonus +1/+2/+3 k hodu na ochočení dle úrovně -- TODO: přesné prahové úrovně nejsou v přepisu očíslované'),
('Ošetřovatel zvěře', 'schopnost', 'Krotitel léčí 1 život zvířete za každé 2 své úrovně (1 hodina, 1 bod únavy), max. 1×/den na dané zvíře, jen běžná zvířata.', 6, '1 život/2 úrovně krotitele; 1 h, 1 bod únavy, 1×/den/zvíře'),
('Zvýšení útoku a obrany (Drezura)', 'schopnost', 'Krotitel trénuje ÚČ/OČ svého zvířete (min. 2 hodiny denně): +1 hodnota trvá tolik týdnů, kolik má být nová hodnota; max. dosažitelné zvýšení a počet současně trénovaných atributů (1→2→3) rostou s úrovní krotitele; od jisté úrovně lze drezúrovat i hraničářsky vycvičené tvory. Neplatí pro společenský hmyz.', 6, 'Doba tréninku +1 = X týdnů (X=nová hodnota); max. zvýšení a počet atributů dle úrovně -- TODO: přesné prahové úrovně nejsou v přepisu očíslované'),
('Zvýšení životů (zvěřinec)', 'schopnost', 'Krotitelovi společníci získávají úroveň souběžně s ním (přibližně za každé dvě úrovně hráče); nepostupuje-li hráč, zvíře získává úroveň za půl roku péče.', 6, 'Zvíře +1 úroveň za ~2 úrovně krotitele, nebo za 1/2 roku péče -- Nejasné: text zdroje "za každé dvě hráče" bez upřesnění jednotky.'),
('Speciální výcvik (Krotitel)', 'dovednost', 'Krotitel naučí zvíře složitějším činnostem (dle jeho predispozic, rozhoduje PJ) — základní povely, nošení nákladu/jezdectví, otevírání dveří, plížení, hrabání tunelů, kácení stromů, hlídání, mluvení (jednoduché/pokročilé), skákání, šplhání, stopování, orientace, rdoušení, hraničářský výcvik, nošení zbroje, +3 iniciativa, +2 k Sil/Obr/Odol (max. 21+5). Výcvik trvá 1 měsíc (3 h/den, 3 body únavy); počet výcviků na tvora = úroveň/4. Naučená dovednost se pro účely pastí počítá jako "průměrně", opakováním jako "dobře".', 6, '1 měsíc/výcvik, 3 h/den, 3 body únavy; max. výcviků = úroveň/4'),
('Ochočování magických zvířat', 'schopnost', 'Od 16. úrovně může krotitel ochočovat i magická zvířata a společenský hmyz; výjimečně i nemrtvá zvířata (efekty výcviku poloviční).', 16, 'Rozšíření cílů ochočování na magická zvířata/společenský hmyz/nemrtvá zvířata (poloviční efekt)'),
('Kapacitní drahokamy', 'schopnost', 'Krotitel upravuje drahokamy jako alternativní úložiště zvířat (nářadí 85 mn/2 zl; doba přípravy 4-20 hodin dle velikosti A-D, cena drahokamu 50 st/velikost). Zvíře uvnitř nestárne, max. doba uložení 1 rok + 1 rok/10 úrovní krotitele. Efekty drahokamů dočasně posilují vyjmuté zvíře podle druhu kamene (24 hodin): Jaspis (imunita krvácení, způsobuje 1k4 krvácení), Jadeit (−1k6 zranění, částečná nehmotnost), Topaz (let 20 sáhů/akci), Turmalín (nekrotické zranění), Pyrit (odraz světla, 1k4 nemrtvým/kolo), Prasiolit (regenerace 1k4/kolo), Rubín (50% odolnost ohni, +1k4 ohnivé zranění), Safír (50% odolnost chladu, +1k4 ledové), Smaragd (50% odolnost jedu, +1k4 jedovaté), Olivín (50% odolnost bodné/sečné), Morganit (50% odolnost drtivé), Diamant (jako zbroj Kz 10). Rozbití drahokamu (6+ životů poškození) okamžitě uvolní tvora (případně jej zabije, není-li dost místa); max. počet naplněných drahokamů = aktuální kapacita torny.', 6, 'Doba přípravy 4-20 h dle velikosti; max. uložení 1 rok +1/10 úrovní; rozbití při 6+ životů poškození; efekty dle druhu kamene (viz popis)');

-- --- PROPOJENÍ SE SCHOPNOST_POVOLANI ---
INSERT INTO schopnost_povolani (schopnost_id, povolani_id)
SELECT s.id, p.id FROM zvlastni_schopnosti s, povolani p WHERE
   (s.nazev IN ('Pouliční dovednosti','Vrhací zbraně (Tulák)','Hbitost (Tulák)','Lichocení','Umělecké vlohy') AND p.nazev='Tulák')
OR (s.nazev IN ('Vtipálek','Jamování','Miláček všech','Vojenská kapela','Bardova únava za kouzlení',
                'Psychické zranění (Bard)','Iniciativa hráče (Bard)','Učení se písním','Skládání písní',
                'Bardův nástroj','Komponenty bardova kouzlení') AND p.nazev='Bard')
OR (s.nazev IN ('Inspirace','Korekce','Pouto s trollobíjcem','Pamětníkova únava za kouzlení','Iniciativa mluvčího',
                'Iniciativa válečného knihovníka','Iniciativa runotepce','Pamětníkova kronika','Parametry knihy',
                'Učení se kouzlům (Pamětník)','Skládání ság','Runová magie') AND p.nazev='Pamětník')
OR (s.nazev IN ('Rozmazlování','Krotitelská torna','Jesle','Odhadování zvěře','Ochočování zvěře','Ošetřovatel zvěře',
                'Zvýšení útoku a obrany (Drezura)','Zvýšení životů (zvěřinec)','Speciální výcvik (Krotitel)',
                'Ochočování magických zvířat','Kapacitní drahokamy') AND p.nazev='Krotitel');
-- =====================================================================
-- ČÁST 7: HOMEBREW — STOPAŘ STÍNŮ / LOVEC STÍNŮ (h935-h964)
-- Warlock (druhá větev Stopaře, h1009-h1068) NENÍ v tomto importu
-- zpracován (časová priorita) — zbývá jako TODO pro navazující práci.
-- Stopařova/lovcova kouzla (Čtení tajemství, Kavemur, Nihilanti, Rychlý
-- úder, Stínový krok, Temná čepel, Stínová střela...) a magické oleje
-- (Ohnivý/Ledový olej, Černomor, Karistom) jsou mimo rozsah (kouzla/předměty).
-- Očekávané názvy v `povolani`: 'Stopař stínů', 'Lovec stínů'.
-- =====================================================================

INSERT INTO zvlastni_schopnosti (nazev, druh, popis, uroven_od, mechanika, past_id) VALUES
('Boj proti magickým tvorům (Stopař)', 'schopnost', 'Stopař stínů má +1 ÚČ/OČ proti nemrtvým, lykantropům, neviděným, démonům a magicky pokřiveným tvorům.', 1, '+1 ÚČ/OČ proti magickým tvorům', NULL),
('Posílený metabolismus', 'schopnost', 'Stopařovo tělo lépe reaguje na léčivé lektvary — +2 vyléčených životů za každých 1k6 základní léčivé hodnoty lektvaru (Rudý kříž léčí za 1k6+4 místo 1k6+2 apod.).', 1, '+2 životů/1k6 základní léčivé hodnoty lektvaru', NULL),
('Arbalest', 'dovednost', 'Zbraň vyvinutá pro stopaře — naučení je pro něj "lehká" dovednost vyžadující 1/2 síly a 1/2 obratnosti (profibody jako s učitelem).', 1, 'Lehká dovednost, 1/2 Sil + 1/2 Obr -- TODO: pojem "evoluce" u této dovednosti není v předloze dále vysvětlen', NULL),
('Stopování (Stopař)', 'dovednost', 'Obdoba hraničářova stopování s vlastní škálou (lehký/těžký/nepoužitelný terén: 70/40/5 % volná příroda, 50/45/5 % uzavřené prostory) a 4stupňovým výsledkem: fatální úspěch = stopa jasná, sleduje 12 směn; úspěch = sleduje 6 směn pak nutno opakovat hledání; neúspěch = nenalezl; fatální neúspěch = mylně usoudí, že stopa neexistuje, nebo ji sám zničí. Úspěšná stopa se stopaři jeví jako opalizující "stín" tvora.', 2, 'Tabulka terénu jako u hraničáře (jiné hodnoty); 4 stupně výsledku (fatální úspěch/úspěch/neúspěch/fatální neúspěch)', NULL);

UPDATE zvlastni_schopnosti SET vysledek_skala=TRUE WHERE nazev='Stopování (Stopař)';

INSERT INTO zvlastni_schopnosti (nazev, druh, popis, uroven_od, mechanika) VALUES
('Recepty na magické oleje', 'dovednost', 'Recept na vzácné bojové oleje (Ohnivý, Ledový, Černomor, Karistom) zná jen stopař (rozpozná je i alchymista, který je již vyráběl); vyrábí je alchymista od 5. úrovně, 3 hodiny na cestách / 1 doma. Nesmí se vyrábět pro cizí osoby.', 4, 'Recepty výhradně stopařovy, výroba alchymistou (5.úr+) -- TODO: nejasné, zda dobu výroby lze uplatnit i pro stopaře samotného'),
('Pozměněná mysl', 'schopnost', 'Od 5. úrovně má stopař +1 k hodu proti pastem na inteligenci (odolnost vůči manipulaci s myslí).', 5, '+1 k hodu proti pasti na Int -- Nejasné: text nespecifikuje, kdo přesně "pozná, že je něco špatně" (stopař, nebo útočník)'),
('Demonikon (Stopař)', 'schopnost', 'Magická kniha-bestiář (40 mn, cena 1000 zl, první za 100 zl; výroba 2 měsíce doma; zaniká po 3 letech nepoužívání). Po 2 kolech pozorování magického/nemrtvého/lykantropího/démonického tvora hodí stopař 1k6: 1=jméno, 2=+OČ, 3=+ÚČ, 5=+životaschopnost, 6=vše + bonus ÚČ/OČ proti tomuto tvoru + zranitelnost (PJ rozhoduje, zda kniha tvora vůbec rozpozná). 1×/směnu. Nelze uložit do mimoprostorového vaku (zničí oboje).', 6, '1k6 po 2 kolech pozorování → stupeň odhalených informací (viz popis); 1×/směnu -- Nejasné: seznam přeskakuje číslo 4'),
('Čich (Demonikon)', 'schopnost', 'Kniha Demonikon vnímá v okruhu 12 sáhů (bez ohledu na překážky) přítomnost nebezpečného magického/nemrtvého/lykantropího/démonického tvora (o 6+ úrovní silnějšího) a varuje nositele chvěním, i drží-li knihu jiné povolání.', 6, 'Pasivní detekce nebezpečí v okruhu 12 sáhů');

-- --- LOVEC STÍNŮ (obor Stopaře stínů) ---
INSERT INTO zvlastni_schopnosti (nazev, druh, popis, uroven_od, mechanika) VALUES
('Rychlé nabíjení', 'schopnost', 'Bonus k iniciativě při střelbě z kuše: +3 (7.úr), +6 (12.úr), +9 (18.úr).', 7, '+3/+6/+9 Ini dle úrovně (kuše)'),
('Bojový výcvik (Lovec stínů)', 'schopnost', 'Od 7. úrovně neztrácí lovec iniciativu žádnou zbraní pro boj TvT.', 7, 'Ruší postih iniciativy za obtížné TvT zbraně'),
('Vícenásobné útoky (Lovec stínů)', 'schopnost', 'Bonus k iniciativě v boji TvT libovolnou zbraní: +3 (8.úr), +6 (14.úr), +9 (20.úr), +12 (27.úr).', 8, '+3/+6/+9/+12 Ini dle úrovně'),
('Boj proti magickým tvorům (Lovec stínů)', 'schopnost', 'Rozšiřuje Stopařův bonus proti magickým tvorům: +1 ÚČ/+2 OČ (8.úr), +2/+2 (13.úr), +3/+2 (16.úr), +3/+3 (22.úr).', 8, 'Progrese ÚČ/OČ dle úrovně proti magickým tvorům'),
('Břitká ocel', 'schopnost', 'Bonus k útočnosti všech zbraní TvT: +1 (10.úr), +2 (15.úr), +3 (20.úr).', 10, '+1/+2/+3 útočnost dle úrovně'),
('Nelidské oči', 'schopnost', 'Od 12. úrovně +1 ÚČ na krátkou i střední vzdálenost střelby (celkem +2 na krátký dostřel) a žádný postih na velkou vzdálenost.', 12, '+1 ÚČ krátká/střední vzdálenost, bez postihu na velkou'),
('Trollí metabolizmus', 'schopnost', 'Od 14. úrovně si lovec vyléčí 5 životů za spánek; léčivé lektvary na něj účinkují +4 životy za každých 1k6 základní hodnoty.', 14, '+5 životů/spánek; +4 životů/1k6 lektvaru'),
('Miláček noci', 'schopnost', 'V dostatečné tmě/šeru se lovec pohybuje o polovinu rychleji (+1 sáh v rozšířeném systému) a umí se skrývat ve stínu jako zloděj stejné úrovně. Od 12. úrovně počítá útok ze zálohy i při útoku do zad ve tmě/šeru (mimo střelné zbraně), pokud o něm cíl neví.', 6, '+50 % rychlost ve tmě; skrývání jako zloděj stejné úrovně; útok ze zálohy do zad ve tmě od 12.úr'),
('Pakt (Lovec stínů)', 'schopnost', 'Od 12. úrovně vydrží lovci magické předměty s omezenou trvanlivostí (démoni v nich rádi pobývají blízko jeho knihy) 2× déle.', 12, '2× delší trvanlivost magických předmětů s omezenou životností');

-- --- PROPOJENÍ SE SCHOPNOST_POVOLANI ---
INSERT INTO schopnost_povolani (schopnost_id, povolani_id)
SELECT s.id, p.id FROM zvlastni_schopnosti s, povolani p WHERE
   (s.nazev IN ('Boj proti magickým tvorům (Stopař)','Posílený metabolismus','Arbalest','Stopování (Stopař)',
                'Recepty na magické oleje','Pozměněná mysl','Demonikon (Stopař)','Čich (Demonikon)') AND p.nazev='Stopař stínů')
OR (s.nazev IN ('Rychlé nabíjení','Bojový výcvik (Lovec stínů)','Vícenásobné útoky (Lovec stínů)',
                'Boj proti magickým tvorům (Lovec stínů)','Břitká ocel','Nelidské oči','Trollí metabolizmus',
                'Miláček noci','Pakt (Lovec stínů)') AND p.nazev='Lovec stínů');
