-- --- EFEKTY ---
INSERT INTO efekty (nazev, typ, cil, hodnota_vzorec, mechanika_aplikace, trvani, podminka_ukonceni, stackovatelne, tooltip_text) VALUES
('Zbraň vytasena násilím (Erythen)', 'debuff', 'vybavení', 'zbraň odebrána z pochvy/ruky bez souhlasu', 'jednorazove', 'okamžité', NULL, FALSE, 'Následek neúspěšné obrany proti Erythenovu Rychlému tasení cizí zbraně.'),
('Následek Brány (Osm bran)', 'debuff', 'vlastnosti, životy, smysly', 'dle čísla brány (viz mechanika) — kumulativní a trvalé', 'jednorazove', 'trvalé, léčitelné jen magicky', NULL, TRUE, 'Trvalý následek neúspěšného hodu proti nebezpečí otevřené Brány Erythenovy techniky Osm bran.');

-- --- PASTI ---
INSERT INTO pasti (vlastnosti, obtiznost, efekt_uspech_id, efekt_neuspech_id, pouziva_4stupnovou_skalu, poznamka) VALUES
('Obr', '7', NULL, (SELECT id FROM efekty WHERE nazev='Zbraň vytasena násilím (Erythen)'), FALSE,
   'Rychlé tasení (Erythen) — použití na cizí zbraň bez souhlasu majitele. Zápis zdroje "Obr.-7-Obr." obsahuje zdvojené "Obr.", smysl zdvojení nejasný -- TODO ověřit.'),
('Odol', 'číslo brány × počet kol otevření − úroveň Erythena (kumulativní, viz mechanika)', NULL,
   (SELECT id FROM efekty WHERE nazev='Následek Brány (Osm bran)'), FALSE,
   'Osm bran (Erythen) — past se hází při otevření brány a na začátku každého kola, dokud je otevřená; po uzavření všech bran nebezpečí klesá o úroveň Erythena za směnu, ale nové otevření bez tohoto odečtu okamžitě navyšuje nebezpečí zpět.');

-- --- NOVIC (základní homebrew povolání, mnišský/kněžský archetyp) ---
INSERT INTO zvlastni_schopnosti (nazev, druh, popis, uroven_od, mechanika) VALUES
('Víra (zdroj síly Novice)', 'schopnost', 'Novicovým zdrojem síly je víra — denně má k dispozici tolik víry, kolik je jeho úroveň + bonus za inteligenci. Víra se platí na začátku sesílání disciplíny; při přerušení sesílání se nevrací.', 1, 'Denní víra = úroveň + bonus Int'),
('Nadání (Novic)', 'dovednost', 'Díky podpoře řádu jsou pro novice dovednosti Jazyky a Čtení a psaní na úrovni "střední" místo "těžké"; má také nadprůměrné znalosti božstev, mytologie a politiky.', 1, 'Jazyky, Čtení a psaní: kategorie obtížnosti snížena o 1 stupeň (těžká→střední)'),
('Železná pěst', 'schopnost', 'Novicovy útoky beze zbraně (rvačka) jsou o +1 ÚČ a +1 útočnost silnější, ať už jde o úder rukou nebo kop.', 1, '+1 ÚČ, +1 útočnost k úderům beze zbraně'),
('Zocelení skrze přesvědčení', 'schopnost', 'Novic dokáže silou víry v sebe sama dočasně posílit jednu ze svých fyzických vlastností (Sil/Obr/Odol) o zvolený počet stupňů (disciplína "Probuzení vlastnosti": 1 víra/stupeň, 1 kolo vyvolání, trvá 4k6 kol, 1 bod únavy/stupeň, 2×/den, max. 21+5). Vždy může mít probuzenou jen jednu vlastnost.', 1, 'Probuzení vlastnosti: 1 víra/stupeň zvýšení, trvání 4k6 kol, max. 21+5, 2×/den'),
('Disciplíny (Novic)', 'schopnost', 'Novic se učí 1 disciplínu za úroveň (není-li řečeno jinak) ze společného seznamu, celkový počet známých disciplín nesmí přesáhnout jeho úroveň.', 1, '1 disciplína/úroveň, max. počet = úroveň'),
('Postoj šedivého jeřába', 'schopnost', 'Defenzivní bojový postoj (1 víra, 1 kolo vyvolání, trvá dokud trvá nebo je novic na nohou, 1 únava/3 kola, rozsah 3 hexy před sesilatelem): vyžaduje prázdné ruce a pohyb nejvýše chůzí; +1 KZ proti TvT útokům, +2 KZ proti vrhaným/střeleným; útočí-li sám z postoje, má stejný postih. Zranitelný na postihy k obraně při útoku zezadu (−7) nebo z boku (−5). Lze bez omezení používat disciplíny/kouzlit s prázdnýma rukama. Postoj končí rozběhnutím, zrušením nebo sražením na zem.', 1, '+1 KZ (TvT) / +2 KZ (vrhací, střelné) v postoji; −7/−5 OČ při útoku zezadu/z boku');

-- --- ERYTHEN (obor Novice — mistr sebeovládání a boje beze zbraně) ---
INSERT INTO zvlastni_schopnosti (nazev, druh, popis, uroven_od, mechanika, past_id) VALUES
('Sebedůvěra (Erythen)', 'schopnost', 'Erythenova víra se (na rozdíl od kněze) obnovuje výhradně jeho vlastní sebedůvěrou — odlišné metody doplnění (viz Doplnění víry).', 6, 'Odlišný zdroj obnovy víry oproti knězi', NULL),
('Doplnění víry (Erythen)', 'schopnost', 'Čtyři metody obnovy víry: Rozjímání (1 hodina klidu, doplní plnou kapacitu, probíhá i automaticky během spánku, nelze v boji), Kontemplace (1 směna, 1 únava, +1k6 víry, kdykoliv), Introspekce (1 kolo nehybnosti, 4 únava, +1k12 víry) a Reflexe (výkřik upoutá pozornost v okruhu 5×odolnost sáhů, +1 víra i nad maximum za každého myslícího tvora v dosahu, ale −5 OČ do konce bitvy a stává se prioritním cílem; nabytá víra navíc mizí po boji).', 6, 'Rozjímání 1h/plná kapacita; Kontemplace 1 směna+1 únava/1k6; Introspekce 1 kolo+4 únava/1k12; Reflexe +1 víra/tvor v okruhu 5×Odol, −5 OČ', NULL),
('Rychlé tasení', 'schopnost', 'Jednou za kolo bez použití akce vytasí Erythen 1-2 zbraně TvT nebo vytasí a hodí vrhací zbraň (i cizí, volně dostupnou v dosahu 1 — ne z batohu/rukou). Nesouhlasí-li majitel, past Obr.-7-Obr. tasení/nic. Vržená takto vytasená zbraň má o 2 vyšší ÚČ.', 6, 'Past Obr proti Obr (cizí zbraň); vržená zbraň +2 ÚČ', (SELECT id FROM pasti WHERE vlastnosti='Obr' AND obtiznost='7')),
('Obratný boj (Erythen)', 'schopnost', 'Od 9. úrovně počítá Erythen v boji TvT zbraněmi polovinu bonusu za obratnost místo bonusu za sílu (při postihu jako by měl obratnost 0); od 15. úrovně celý bonus za obratnost.', 9, 'ÚČ počítá z Obr místo Sil: 1/2 bonusu (9.úr), celý bonus (15.úr)', NULL),
('Smršť úderů', 'schopnost', 'Od 10. úrovně, útočil-li Erythen v minulém kole všemi akcemi TvT na jednoho protivníka, může toto kolo zaútočit každou akcí dvakrát na stejný cíl (ÚČ−1 za tyto útoky navíc). Použitelné jen každé druhé kolo.', 10, 'Zdvojení útoků na stejný cíl (ÚČ−1), jen každé 2. kolo', NULL),
('Ocelová pěst', 'schopnost', 'Erythenova holá ruka je zbraň TvT: jedna pěst SZ 1/Odol−2, obě pěsti SZ 2/(2×Odol)−1.', 6, 'Jedna pěst: SZ 1/Odol−2; obě pěsti: SZ 2/2×Odol−1', NULL),
('Osm bran', 'schopnost', 'Erythenovo rozvinutí novicovského zocelení: postupné otevírání 8 stupňovaných "bran" překonávajících tělesné pojistky, každá s mocným efektem a trvalým následkem (léčitelným jen magicky): 1. Otevření (vlastnosti <10 → 10, následek 1k6 zranění), 2. Odpočinku (ignoruje únavu/naložení, následek +1k6 min. únavy), 3. Života (ignoruje mez vyřazení, následek −1k20 max. životů), 4. Bolesti (2× stupeň Obr, následek Obr/2), 5. Uzavření (4× stupeň Sil, následek Sil/4), 6. Zraku (dokonalý přehled, vidí neviditelné/skrz zdi, následek slepota), 7. Úžasu (2× pohyblivost, ignoruje gravitaci, následek trvalé ochromení), 8. Smrti (dočasná nesmrtelnost, nelze svévolně ukončit, následek smrt). Otevření nestojí akci. Nebezpečnost pasti = (číslo brány × kola otevření) − úroveň Erythena, hází se při otevření a na začátku každého kola; po uzavření všech bran klesá o úroveň/směnu, ale další otevření bez odečtu úrovně nebezpečí navyšuje zpět. Následky se sčítají.', 6, 'Past Odol proti (číslo brány×kola−úroveň); 8 stupňovaných efektů + trvalých následků, viz popis', (SELECT id FROM pasti WHERE vlastnosti='Odol')),
('Mimoprostor (Erythen)', 'schopnost', 'Erythen se učí nepřesný mimoprostorový přesun vázaný na kotvu (novicovu disciplínu Tajná značka): Skok (na značku), Přitažení a Prohození (s označeným cílem) — jednotlivé techniky jsou vedeny jako kouzla (víra/dosah/vyvolání), mimo rozsah tohoto importu.', 8, 'Viz `kouzla`: Skok/Přitažení/Prohození — mimo rozsah tohoto importu', NULL),
('Čtení vražedného úmyslu', 'dovednost', 'Mluví-li Erythen s někým alespoň 1 směnu a ten skrytě zamýšlí ohrozit jeho život, má 10% šanci si toho všimnout (5 % nerozumí-li jeho řeči). Musí ohlásit použití; každé 3 směny čtení stojí 1 bod únavy.', 6, 'Šance 10 % (5 % bez znalosti jazyka) za 1 směnu rozhovoru; 1 únava/3 směny', NULL),
('Postoj černého jeřába', 'schopnost', 'Pokročilá verze Postoje šedivého jeřába (rozsah 3 hexy před sesilatelem, 1 kolo vyvolání, trvá dokud trvá/je na nohou, 1 únava/4 kola): +2 KZ proti TvT, +4 KZ proti vrhaným/střeleným zbraním (stejný postih útočí-li sám). Zranitelnost při útoku zezadu −6 OČ, z boku −4 OČ. Lze bez omezení používat disciplíny/kouzlit s prázdnýma rukama.', 11, '+2 KZ (TvT) / +4 KZ (vrhací, střelné); −6/−4 OČ zezadu/z boku -- TODO: dosah kouzla ve zdroji chybí (u obdobných technik bývá 0)', NULL);

-- --- PROPOJENÍ SE SCHOPNOST_POVOLANI ---
INSERT INTO schopnost_povolani (schopnost_id, povolani_id)
SELECT s.id, p.id FROM zvlastni_schopnosti s, povolani p WHERE
   (s.nazev IN ('Víra (zdroj síly Novice)','Nadání (Novic)','Železná pěst','Zocelení skrze přesvědčení',
                'Disciplíny (Novic)','Postoj šedivého jeřába') AND p.nazev='Novic')
OR (s.nazev IN ('Sebedůvěra (Erythen)','Doplnění víry (Erythen)','Rychlé tasení','Obratný boj (Erythen)',
                'Smršť úderů','Ocelová pěst','Osm bran','Mimoprostor (Erythen)','Čtení vražedného úmyslu',
                'Postoj černého jeřába') AND p.nazev='Erythen');
-- =====================================================================
-- ČÁST 9: HOMEBREW — MYSTIK (h1120-h1126, výběr)
-- Mystikova "kouzla/zázraky" (Bezpečná cesta, Rovnováha, Rozkol,
-- Odvracení/Přivolání nemrtvých, Požehnání, Ohlušení, Zlaté/Obsidiánové
-- kopí, Vlna života/smrti, Záře, Požehnání těla...) jsou MIMO ROZSAH
-- tohoto importu (formát magenergie/dosah/vyvolání/trvání). Kněz (další
-- obor Novice, h1166-h1229) není v tomto souboru zpracován — TODO.
-- Očekávaný název v `povolani`: 'Mystik'.
-- =====================================================================

INSERT INTO zvlastni_schopnosti (nazev, druh, popis, uroven_od, mechanika) VALUES
('Poutník (Mystik)', 'schopnost', 'Pohybuje-li se mystik rychlostí procházky, unavuje se jen na 1/3 oproti ostatním postavám.', 6, 'Únava z chůze × 1/3 při rychlosti procházky'),
('Skromné břicho', 'schopnost', 'Mystikovo tělo snáší hladovění lépe — příznaky se dostaví až po 4 dnech bez jídla; tento stav by se však neměl opakovat častěji než 1× za 20 dní.', 6, 'Příznaky hladovění až po 4 dnech (místo obvyklé doby), max. 1×/20 dní'),
('Mystikovo kopí', 'schopnost', 'Mystik smí užívat všechny zbraně jako novic, nejčastěji ale kopí sloužící i jako cestovní hůl a závěs na tlumok. V mystikových rukou má kopí parametry ÚČ 7 / útočnost +1 / OČ +2.', 6, 'Kopí v rukou mystika: ÚČ 7 / útočnost +1 / OČ +2'),
('Iniciativa v kouzlení (Mystik)', 'schopnost', 'Bonus k iniciativě při kouzlení: +1 (6.úr), +2 (12.úr), +3 (18.úr), +4 (24.úr), +5 (30.úr).', 6, '+1 až +5 k iniciativě při kouzlení dle úrovně (po 6 úrovních)'),
('Rychlý boj (Mystik)', 'schopnost', 'Bonus k iniciativě v boji zbraněmi TvT: +3 (9.úr), +6 (17.úr).', 9, '+3/+6 Ini dle úrovně'),
('Vějířová obrana', 'schopnost', 'Od 6. úrovně (2 akce v rozšířeném systému, jen se zbraní dosahu 2) se mystik pevně postaví a soustředí obranu na výseč 3 hexů před sebou až do dohledu; útoky odtud (musí o nich vědět a vidět je) se brání za cenu 1 akce (dvě obrany = 1 akce) s bonusem +1 OČ, proti střelám navíc ekvivalent malého krytu +1 OČ. Lze srazit běžné projektily (ne nad střední vrhací zbraně/arbalest/balistu). Útočí-li mystik sám ve vějířové obraně, má −1 ÚČ. Bonus roste: +2/+1 (12.úr), +3/+2 (22.úr). Otáčet se lze, opustit hex ne; zrušení nestojí akci.', 6, '+1 OČ (i proti střelám +1) v 3hexové výseči; bonus roste na +2/+1 (12.úr) a +3/+2 (22.úr) -- TODO: přesný význam dvou čísel bonusu (12./22. úroveň) není ve zdroji jednoznačně vysvětlen');

INSERT INTO schopnost_povolani (schopnost_id, povolani_id)
SELECT s.id, p.id FROM zvlastni_schopnosti s, povolani p WHERE
   s.nazev IN ('Poutník (Mystik)','Skromné břicho','Mystikovo kopí','Iniciativa v kouzlení (Mystik)',
               'Rychlý boj (Mystik)','Vějířová obrana') AND p.nazev='Mystik';
-- =====================================================================
-- ČÁST 10: HOMEBREW — PALADIN (h1262-h1299, výběr)
-- Paladinova "Přání" (Dotek života, Uzři nemrtvé, Boží zásah, Zahnání
-- únavy/nemoci/strachu, Zpomalení jedu, Mentální ochrana, Požehnání
-- zbraně, Dotyk moci, Vnitřní klid, Muka, Věčný odpočinek, Slepota...)
-- jsou zázraky s dobou vyvolání — MIMO ROZSAH tohoto importu (`kouzla`).
-- Panoš/Rytíř (h1230-h1261) a Zealot (h1325+) nejsou v tomto souboru
-- zpracovány — TODO. Očekávaný název v `povolani`: 'Paladin'.
-- =====================================================================

INSERT INTO zvlastni_schopnosti (nazev, druh, popis, uroven_od, mechanika) VALUES
('Vícenásobné útoky (Paladin)', 'schopnost', 'Bonus k iniciativě pro boj TvT se zbraní TvT: +3 (6.úr), +6 (12.úr), +9 (22.úr).', 6, '+3/+6/+9 Ini dle úrovně'),
('Boj s nemrtvými (Paladin)', 'schopnost', 'Paladin má bonus proti nemrtvým: +1 ÚČ/OČ a +2 k pastem při kontaktu s nemrtvými od 6. úrovně, +2 ÚČ/OČ od 10. úrovně; od 20. úrovně +3 ÚČ/OČ a +3 k pastem, od 30. úrovně +4 ÚČ/OČ.', 6, '+1/+2/+3/+4 ÚČ+OČ dle úrovně (6./10./20./30.úr); +2/+3 k pastem kontaktu s nemrtvými'),
('Štít (Paladin)', 'schopnost', 'Bonus k obraně štítem a útoku úderem štítem (nevztahuje se na pavézu): +2 OČ/+1 ÚČ od 10. úrovně, +3 OČ/+2 ÚČ od 20. úrovně, +4 OČ/+3 ÚČ od 30. úrovně.', 10, 'Štít: +2/+3/+4 OČ a +1/+2/+3 ÚČ dle úrovně (10./20./30.úr)'),
('Vzor', 'schopnost', 'Všechny paladinovy schopnosti (Přání, aury) počítají jen jeho přirozený bonus za charisma (+1 lze získat dovedností Vznešenost elfů) — nezapočítávají se bonusy z lektvarů, kouzel na jiné postavy ani z vybavení.', 6, 'Jen přirozený bonus Chr (+1 z Vznešenosti elfů), žádné jiné externí bonusy'),
('Síla víry', 'schopnost', 'Paladin místo magie čerpá "Přání" — max. počet najednou = bonus za charisma. Obnovuje je Litanií (1 směna, 1 únava/litanie, doplní 1 přání; lze i v boji, ale s −3 ÚČ/OČ za snížené soustředění po dobu odříkávání; nesmí být přerušena, během ní nelze mluvit/sesílat verbálně). Přání mají dosah dotyk (není-li řečeno jinak), nepočítají se jako kouzlení (žádné kouzelnické postihy), ale musí být odříkána nahlas, což na 1 kolo přeruší probíhající litanii.', 6, 'Max. přání = bonus Chr; Litanie: 1 směna/1 únava/+1 přání, −3 ÚČ/OČ pokud v boji'),
('Aury', 'schopnost', 'Pasivní energetické pole v dosahu = bonus za charisma paladina; přepínání aktivní aury na začátku kola je podvědomé (bez akce/únavy) v boji, mimo boj stojí 1 únava/hodinu (v boji 1 únava/směnu). Překrývající se stejné aury více paladinů: platí jen silnější (16.+ úroveň). Typy: Ochrany (spojenci −1 život ze všech zdrojů zranění, odečteno jako poslední; mocnější −2/−3/−5 od 16./26./36.úr), Bolesti (nepřátelé +1 život zranění navíc; mocnější +2/+3/+5), Soustředění (spojenci +5 % k sesílání/zlodějským dovednostem/stopování max. 99 % a +1 k hodu na dovednosti; mocnější +10/+15/+25 % a +2/+3/+5), Rozkolu (nepřátelé −5 % k sesílání min. 10 % a −1 k hodu na dovednosti; mocnější −10/−15/−25 % a −2/−3/−5), Obětování (zranění spojence sníženo až o bonus Chr paladina, paladin dostává stejné stínové zranění; mocnější: 2×/3×/5× bonus Chr sníženo, paladin dostává 1/2, 1/3, 1/5 stínového zranění) a Světla (paladin svítí jako pochodeň; mocnější jako lucerna 7 sáhů/měsíc v úplňku 10 sáhů/slunce 20 sáhů s postihem −1 ÚČ/OČ pro tvory citlivé na světlo). Efekty aury (kromě Obětování a Světla) se netýkají samotného paladina.', 6, 'Dosah = bonus Chr; 5 typů aur + mocné varianty od 16./26./36. úrovně (viz popis)'),
('Svaté Přísahy', 'schopnost', 'Od 16. úrovně může paladin složit přísahu (obsah určuje hráč); po splnění PJ trvale navýší max. počet Přání o 1-5 dle obtížnosti/souladu s vírou (stanoveno PJ předem). Vždy jen 1 aktivní přísaha, ale za život jich lze splnit neomezeně; nesplnění má opačný efekt (snížení).', 16, 'Splnění přísahy: +1 až +5 trvale k max. počtu Přání (dle PJ); nesplnění: penalizace'),
('Litanie (rozšíření)', 'schopnost', 'Od 16. úrovně odříkává paladin litanie podvědomě — už nemá v boji postih k ÚČ/OČ a získává jen 1 bod únavy za každé dvě směny (místo za každou).', 16, 'Zrušen postih −3 ÚČ/OČ; únava jen 1/2 směny litanie'),
('Rychlá odezva (Paladin)', 'schopnost', 'Vyvolání všech Přání je od jisté úrovně o polovinu rychlejší — 1 akce místo 1 kola (2 akcí).', 16, 'Doba vyvolání Přání: 1 akce místo 2 -- TODO: přesná úroveň získání není v úryvku jednoznačně uvedena, kontextově u rozšíření 16. úrovně');

INSERT INTO schopnost_povolani (schopnost_id, povolani_id)
SELECT s.id, p.id FROM zvlastni_schopnosti s, povolani p WHERE
   s.nazev IN ('Vícenásobné útoky (Paladin)','Boj s nemrtvými (Paladin)','Štít (Paladin)','Vzor','Síla víry',
               'Aury','Svaté Přísahy','Litanie (rozšíření)','Rychlá odezva (Paladin)') AND p.nazev='Paladin';
-- =====================================================================
-- ČÁST 11: OBECNÁ PRAVIDLA DOVEDNOSTÍ — kompletní seznam (h1693-h1808)
-- Všechny dovednosti níže používají 4stupňovou škálu výsledku (fatální
-- úspěch / úspěch / neúspěch / fatální neúspěch), shodnou s tabulkou
-- vysledky_testu. Nejsou vázané na konkrétní povolání (obecné dovednosti
-- dostupné každé postavě za cenu a dobu učení dle Tabulky doby učení,
-- viz schopnost 'Obecná pravidla učení dovednostem' níže).
-- Pozn.: text je z velké části přepis přímo ze zdroje (pole Vlastnost/
-- Obtížnost/Ověřování/Totální úspěch/Úspěch/Neúspěch/Fatální neúspěch
-- a poznámky označené hvězdičkou), sloučený do souvislého popisu.
-- =====================================================================

INSERT INTO zvlastni_schopnosti (nazev, druh, popis, mechanika, vysledek_skala) VALUES
('Obecná pravidla učení dovednostem', 'dovednost', 'Doba uceni dovednosti (mimo dovednosti z 1. urovne postavy) zavisi na kategorii obtiznosti (lehka/stredni/tezka/velmi tezka) a dosahovanem stupni znalosti (vubec az dokonale): celkova doba uceni od zakladu na dokonale je 105 dni (lehka), 210 (stredni), 315 (tezka) az 420 dni (velmi tezka). Cena za stupen ucitele je 1/1,5/2/2,5 zlateho za den dle kategorie. S ucitelem postava potrebuje o 25% mene profibodu na kazdy stupen.', 'Tabulka doby uceni a nakladu na vycvik dle obtiznosti a stupne (viz popis)', FALSE),
('Běh na krátké vzdálenosti', 'dovednost', 'Fatální úspěch: +1 sáh k rychlosti pohybu pro běh a sprint při boji.. Mimo boj má postava tolik bodů pohybu, jako by byla její pohyblivost o 2 vyšší. Úspěch: +1 sáh k rychlosti pohybu pro běh a sprint při boji.. Mimo boj má postava tolik bodů pohybu, jako by byla její pohyblivost o 1 vyšší. Neúspěch: Rychlost postavy zůstává nezměněna. Fatální neúspěch: Postava upadne a bolestivě si natáhne nohu. V boji nemůže příští směnu sprintovat. Má bodů sprintu, jako by měla pohyblivost o 2 menší.', 'Vlastnost: síla; Obtížnost: střední; Ověřování: v boji 1 za 3 kola, jinak každých 6 kol', TRUE),
('Kovářství', 'dovednost', 'Fatální úspěch: Není potřeba ověřovat až do konce pracovního dne. Úspěch: Postava úspěšně dokončí dílo. Neúspěch: Postava zamýšlené dílo zkazila a musí ho 9 směn opravovat. Fatální neúspěch: Práce i materiál přišli vniveč a vše se musí udělat znovu. V extrémních případech může dojít k požáru nebo jiným událostem dle okolností.', 'Vlastnost: síla; Obtížnost: střední; Ověřování: každé 3 hodiny', TRUE),
('Legendární kovářství', 'dovednost', 'postava musí nejdříve umět klasické kovářství na dokonale Fatální úspěch: Není potřeba ověřovat až do konce pracovního dne. Úspěch: Postava úspěšně dokončí dílo. Neúspěch: Postava zamýšlené dílo zkazila a musí ho 9 směn opravovat. Fatální neúspěch: Práce i materiál přišli vniveč a vše se musí udělat znovu. V extrémních případech může dojít ke zhroucení stavby apod.', 'Vlastnost: síla; Obtížnost: těžká; Ověřování: každé 3 hodiny', TRUE),
('Medvědí síla', 'dovednost', 'Postava pravidelně posiluje své tělo. Když se postava naučí dovednost na dokonale, zvýší se jí trvale stupeň síly o 2. Lze se naučit vícekrát. Nelze překročit 13+1.', 'Vlastnost: síla; Obtížnost: lehká', TRUE),
('Mistr zbraně', 'dovednost', 'umí li postava mistra zbraně dokonale získá +1k Úč. s tímto druhem zbraně a odstrani postih -2 k iniciative pokud ho ma (tezka/supertezka). Nelze kombinovat s bonusem za rodovou zbrań. Kouzelníkovi tato dovednost umožní používat kombinaci lehká jednoruční zbraň + hůl - Gandalf style. 7-2+2 Past Sil. -x- Int úspěch/nic. Fatální úspěch: postava svou zbraní dodala na váze na svých argumentů. Cíl tohoto zastrašení/přesvědčení/zaujetí, věnuje 100% pozornosti postavě a reaguje pozitivně podle účelu a dle okolností. Úspěch: Cíl uznává, že postava je mistrem své zbraně a není radno se k ní chovat neuctivě. Neúspěch: Zastrašení vyšlo do prázdna. Postava je spíše cílem nepříjemného mlčení. Fatální neúspěch: Postava svůj úmysl zcela nezvládla. je zde riziko že svou zbraň upustí, nebo se i poraní. Úmysl se kterým toto postava prováděla se zcela otočí proti ní samotné.', 'Vlastnost: síla; Obtížnost: těžká; Ověřování: při každém pokusu o zastrašení, zaujetí apod.', TRUE),
('Nošení velkých břemen', 'dovednost', 'Umožňuje postave nosit břemena přesahující její maximální nosnost až o 75% Postava s maximální nosností 2000 mincí je schopna tedy odnést až 3500 mincí nákladu. může se ale pohybovat pouze rychlostí procházka nebo 1-5 a každá hodina kterou břemeno nese jej stojí 3 body únavy. Postava nemůže zvednout více jak dvojnásobek své vlastní hmotnosti. Fatální úspěch: Postava břemeno zvedla až s překvapující lehkostí. Ověřování až za 3 hodiny. Úspěch: Postava břemeno úspěšně zvedla a je schopna jej nést. Neúspěch: Postava předmět špatně uchopila a ten ji vyklouzl. Pouze se unavuje. Každý neúspěšný pokus 1 bod únavy. Fatální neúspěch: Postava je předmětem zavalena, předmět upustí a rozbije apod.', 'Vlastnost: síla; Obtížnost: těžká; Ověřování: Při každém zvedání a každou hodinu.', TRUE),
('Ovládání plachet', 'dovednost', 'základní námořnická dovednost Fatální úspěch: Loď pluje o 25% rychleji Úspěch: Loď pluje plnou rychlosti a požadovaným směrem. Neúspěch: Loď pluje o 25% pomaleji. Fatální neúspěch: Poškození plachet a ráhnoví. Plavba zpomalena o 33% až do opravy.', 'Vlastnost: síla; Obtížnost: střední; Ověřování: jednou za den, nebo při každém manévru', TRUE),
('Plavání', 'dovednost', 'ověřování se provádí vždy, když postava vstoupí do vody, kterou nemůže přeskočit, přebrodit, přelézt apod. Past je ovlivněna teplotou vody, naložením postavy a aktuální únavou. (za každý stupeň únavy a naložení stoupá past o 1) Každé kolo topení stojí 1 bod únavy. Postava která umí plavat aspoň špatně způsobuje plavání jen poloviční únavu. Pokud dobře, tak třetinovou únavu. A umí li plavat dokonale, tak dostává pouze šestinovou únavu. Fatální úspěch: Další ověřování bude zapotřebí až za 6 směn. Úspěch: Postava plave bez obtíží. Neúspěch: Postava se začíná topit a v následujícím kole si hází proti pasti, kde se past zvyšuje o 1. Pokud neuspěje, ztrácí dva životy a past se znovu navyšuje o 1. Zranění topením je pouze stínové, pokud postavě někdo pomůže dříve, než množství jejich životů klesne na 0, zůstane ho pouze čtvrtina. Fatální neúspěch: Stejně jako neúspěch, ale počet ztracených životů vzrůstá po 5. (5,10,15…..)', 'Vlastnost: síla; Obtížnost: střední; Ověřování: jednou za směnu', TRUE),
('Práce s provazy a lany', 'dovednost', 'tato doevdnost umožňuje postavě užívat lasa a sítí k chytání osob či předmětů. Fatální úspěch: Provaz drží naprosto perfektně a sám se nerozváže nebude li si to postava sama přát. Úspěch: Uzly jsou tak jak mají být, ale při velkém namáhání mohou povolit. Neúspěch: Uzly jsou tak leda na okrasu a neplní svoji funkci. Fatální neúspěch: Postava záhadný způsobem svázala sama sebe, ztratila provaz apod.', 'Vlastnost: síla; Obtížnost: střední; Ověřování: Každý pokus o přivázání, uchycení něčeho.', TRUE),
('Silný hod', 'dovednost', 'Tato dovednost umožní postavě vrhnout vrhací zbraň na větší vzdálenost pro každý dostřel. Malý +50%, Střední +30%, Velký +15% Tato dovednost umožňuje efektivněji vrhat i předměty neurčené k vrhání. Židle, stoly, korbely apod. V případě že se nejedná o vrhací zbraň, tak maximální vzdálenost na kterou lze tento předmět vrhnout je roven bonusu za Sílu. nejméně však 1. S bonusem za Sílu 5 je dostřel tedy 5/10/15. Nelze vrhnout předmět těžší, než je maximální nosnost postavy. Fatální úspěch: Postava přesně zasáhla cíl a způsobila dalších 1K6 zranění stínového nebo normálního dle povahy vrženého předmětu. Úspěch: Cíl byl zasažen. Neúspěch: Hod netrefil cíl a všechny potenciální cíle v okruhu dvou sáhů od zamýšleného cíle mají šanci být zasaženi s poloviční silou. Fatální neúspěch: Vržený předmět zraní spolubojovníky v dosahu, nebo se odrazí a zasáhne samotného vrhače. PJ', 'Vlastnost: síla; Obtížnost: těžká; Ověřování: každý pokus', TRUE),
('Síla obrů', 'dovednost', 'Postava se naučí vydat ze sebe maximum síly. Při hodu proti pasti na sílu může postava uplatnit tuto dovednost a navýšit výsledek svého hodu o 1. Naučí li se postava sílu obrů na dokonale, zvýší nosnost postavy o 150mn na všech stupních.', 'Vlastnost: síla; Obtížnost: těžká', TRUE),
('Skok o tyči', 'dovednost', 'umožňuje překonávat překážka jak do dálky tak do výšky. Maximální vzdálenost do dálky je 6 sáhů a do výšky 3. Nelze provozovat když je postava v těžkém naložení. Jsou potřeba minimálně 3 sáhy na rozběh. V případě totálního úspěchu může postava v témže kole zaútočit s bonusem +2 k Úč. Fatální úspěch: Postava se přeskokem nezpomalila. (neztratila akci) Úspěch: Postava úspešně zdolala překážku. Neúspěch: Postava spadla ale nezranila se. Fatální neúspěch: Postava nejen že zničila tyč, ale zranila se za 1K6 životů.', 'Vlastnost: síla; Obtížnost: lehká; Ověřování: Každý pokus.', TRUE),
('Šplh', 'dovednost', 'Tato dovednost se vztahuje na šplh po lanu, tyči, stromu apod. Šplh po zdech v tomto není zahrnut. Každých 5 sáhů šplhu stojí 1 bod únavy a trvá 2 kola. Fatální úspěch: Postava vylezla bez nutnosti dalšího ověřování. Úspěch: Postava vylezla 5 sáhů. Neúspěch: Postava nevylezla, nebo sklouzla o 5 sáhů. Fatální neúspěch: Postava se neudržela a spdla. Zranění dle pravidel.', 'Vlastnost: síla; Obtížnost: lehká; Ověřování: jednou za 5 sáhů', TRUE),
('Tesařina', 'dovednost', 'Fatální úspěch: Není potřeba ověřovat až do konce pracovního dne. Úspěch: Postava úspěšně dokončí dílo. Neúspěch: Postava zamýšlené dílo zkazila a musí ho 9 směn opravovat. Fatální neúspěch: Práce i materiál přišli vniveč a vše se musí udělat znovu. V extrémních případech může dojít ke zhroucení stavby apod.', 'Vlastnost: síla; Obtížnost: střední; Ověřování: každé 3 hodiny', TRUE),
('Veslování', 'dovednost', 'Fatální úspěch: veslování způsobuje poloviční únavu a další ověřování je až za šest mořských směn Úspěch: veslování způsobuje poloviční únavu Neúspěch: postava se unavuje standardně Fatální neúspěch: postava zničí veslo, zraní sebe nebo své okolí, vesluje opačně apod.', 'Vlastnost: síla; Obtížnost: lehká; Ověřování: jednou za mořskou směnu', TRUE),
('Zedničina', 'dovednost', 'Fatální úspěch: Není potřeba ověřovat až do konce pracovního dne. Úspěch: Postava úspěšně dokončí dílo. Neúspěch: Postava zamýšlené dílo zkazila a musí ho 9 směn opravovat. Fatální neúspěch: Práce i materiál přišli vniveč a vše se musí udělat znovu. V extrémních případech může dojít ke zhroucení stavby apod.', 'Vlastnost: síla; Obtížnost: střední; Ověřování: každé 3 hodiny', TRUE),
('Znalec zbraně', 'dovednost', 'Postava s touto dovedností se může naučit ovládat zbraň nespadající do její kategorie dle povolání. Platí pro jeden konkrétní druh zbraně např. dlouhý meč. Lze se naučit více zbraní. S každým stupněm dovednosti klesá postih k Úč. za užívání této zbraně. Vůbec -6Úč. Velmi špatně -5Úč. Špatně -4Úč.. Průměrně -3Úč. Dobře -2Úč. Velmi dobře -1Úč. Dokonale 0Úč. Střelné zbraně jsou střední kategorie. S výjimkou těžké kuše, která je na naučení těžká. Postava velikosti A se takto může naučit střílet z těžké kuše či dlouhého luku, ty ale musí být uzpůsobeny na její velikost. Lze dosáhnout i mistrovství s takto se naučenou zbraní.', 'Vlastnost: síla; Obtížnost: lehká - střední zbraně, střední - těžké zbraně, těžká - super těžké zbraně.', TRUE),
('Akrobacie, kejklířství', 'dovednost', 'Fatální úspěch: Postava sklidí bouřlivý potlesk, obecenstvo ji ochotně hodí peníze. Úspěch: Obecenstvo je pobavené, něco málo přispějí. Neúspěch: Vystoupení se nevyvedlo. Obecenstvo s posměchem odejde. Fatální neúspěch: Během vystoupení omylem něco rozbije, obecenstvo postavu vypíská apod.', 'Vlastnost: obratnost; Obtížnost: střední až těžká; Ověřování: jednou za vystoupení, nebo obtížný kousek', TRUE),
('Brusičství', 'dovednost', 'Úspěšně vybroušený drahokam má dvojnásobnou cenu než v surové podobě. Potřebuje stejnou dílnu jako zlatník. Fatální úspěch: Vybroušený kámen je bezchybný + 15% ceny Úspěch: Kvalitní výbrus. Neúspěch: Kámen je plný vad. -30% ceny Fatální neúspěch: Během řezání se kámen ulomil z lůžka a zcela se rozbil. Šance na zranění brusiče. PJ', 'Vlastnost: obratnost; Obtížnost: těžká; Ověřování: každý výbrus', TRUE),
('Dělostřelectví', 'dovednost', 'podrobnosti na straně 96 a 99, pak kapitola dobývání hradů v pravidlech pro experty - svět. Fatální úspěch: Rozptyl se sníží na polovinu, byl li menší než 5, tak se sníží na 1. Úspěch: Rozptyl se sníží o 2 Neúspěch: Rozptyl se nesníží. Fatální neúspěch: Rozptyl se zvysi na dvojnásobek. Velká šance na zasažení vlastních jednotek apod. PJ', 'Vlastnost: obratnost; Obtížnost: velmi těžká; Ověřování: při každém výstřelu', TRUE),
('Hadí obratnost', 'dovednost', 'Postava pravidelně protahuje své tělo a zvyšuje svou flexibilitu a přesnou motoriku. Když se postava naučí dovednost na dokonale, zvýší se ji stupeň obranosti o 2. Lze se naučit vícekrát. Nelze překročit 13+1.', 'Vlastnost: obratnost; Obtížnost: lehká', TRUE),
('Hrnčířství', 'dovednost', 'viz řezbářství a ostatní běžná řemesla', 'Vlastnost: obratnost; Obtížnost: střední', TRUE),
('Jízda na koni', 'dovednost', 'Fatální úspěch: Postava zvládá jízdu perfektně a nemusí až do konce boje ověřovat tento manévr. Další ověřování mimo boj je až za dvojnásobek obvyklé doby a jezdec získává pouze poloviční únavu. Úspěch: Požadovaný manévr se povedl a únavu získává beze změny. Neúspěch: Postava získává 1 bod únavy za každé 2 body únavy zvířete. Při boji se manévr nepovedl a postava se musí celé následující kolo věnovat ovládání zvířete. Fatální neúspěch: Zvíře se splašilo, postava spadla a zranila se apod. PJ', 'Vlastnost: obratnost; Obtížnost: lehká; Ověřování: Každé 3 hodiny při kroku nebo klusu, každou směnu při cvalu nebo trysku. Při boji dle pravidel pro jízdní boj na str. 104.', TRUE),
('Jízda na leteckých nestvůrách', 'dovednost', 'Fatální úspěch: Postava získává pouze poloviční množství únavy a další ověřování je až za dvojnásobek obvyklé doby. při boji se bere, jako by měla bonus za manévrovací schopnosti o 1 vyšší. Úspěch: Postava úspěšně provedla požadovaný manévr a nespadla z letecké nestvůry. Neúspěch: Postava získává bod únavy za každé 2 body únavy nestvůry a při boji se bere, jako by měla postava bonus za manévrovací schopnosti o 1 nižší. Fatální neúspěch: Postava spadla z letecké nestvůry.', 'Vlastnost: obratnost; Obtížnost: těžká; Ověřování: jednou za 3 hodiny, při boji 1 za 6 kol', TRUE),
('Jízda na lyžích', 'dovednost', 'V případě že se snažila sjet úsek rychle, ale nikoliv bezpečně, může se dle okolností její pohyblivost zvýšit až na 28+8. O konkrétní rychlosti rozhoduje Pj v závislosti na naložení postavy, stavu lyží a terénu. Zrychlení se počítá od pohyblivost postavy dle aktuálního naložení a strmosti terénu. Co 10-50 sáhů sjezdu se zvýší stupeň pohyblivosti rychlosti o 2. Fatální úspěch: Postava daný úsek sjela bravurně. Při totálním úspěchu nemusí ověřovat prudké zastavení, nebo změny směru. V případě že se snažila sjet úsek rychle, ale nikoliv bezpečně, může se dle okolností její pohyblivost zvýšit až na 28+8. Úspěch: Postava sjela normálně. Změny směru a prudké brždění se musí ověřovat. Neúspěch: Postava nezvládla jízdu a spadla. Dle okolností zranění za 1K10 stínových životů. Fatální neúspěch: Postava se nešťastně rozbila za 2K10 stínových do náhodné končetiny. Lyže jsou možná zničené. PJ', 'Vlastnost: obratnost; Obtížnost: lehká; Ověřování: jednou za sjezd, nebo každých 10 mil', TRUE),
('Kočí (řízení spřežení a povozů)', 'dovednost', 'Více o povozech a spřeženích na str. 73. Fatální úspěch: Pravděpodobnost nehody se snižuje o 20% Úspěch: Pravděpodobnost nehody se nemění. Neúspěch: Pravděpodobnost nehody se zvyšuje o 10%. Fatální neúspěch: Pravděpodobnost nehody se zvyšuje o 30%.', 'Vlastnost: obratnost; Obtížnost: lehká; Ověřování: dle PJ', TRUE),
('Kopání štol a podkopů - minér', 'dovednost', 'skála 30 dní skála 30 dní písek 7 dní písek 7 dní hlína 7 dní hlína 7 dní Fatální úspěch: Stavba trvá polovinu doby v tabulce. Úspěch: Stavba trvá stejnou dobu. Neúspěch: Daný úsek se musí hloubit znovu. Fatální neúspěch: Stavba je prozrazena, nebo se zřítila. Šance na zavalení dalších částí. je potřeba začít znovu. PJ', 'Vlastnost: obratnost; Obtížnost: těžká; Ověřování: každých 10 sáhů podkopu', TRUE),
('Malířství a jiné výtvarné umění', 'dovednost', 'Fatální úspěch: Soška dokonale zachycuje podobu osoby. Věhlas o dovednostech se začne šířit. Bonus v podobě peněz apod. Úspěch: Dílo se povedlo a postava dostane zaplaceno plnou cenu. Neúspěch: Dílo je takřka na vyhození a plné vad. Osoba se bude cítit uražena a odmítne zaplatit. Fatální neúspěch: Dílo jo kompletně zničené. Postava sklidí posměch apod. PJ', 'Vlastnost: obratnost; Obtížnost: těžká; Ověřování: každý obraz, nebo každé 3 hodiny.', TRUE),
('Mistr obránce', 'dovednost', 'Dovednost umožní pohltit fyzické útoky z blízka i dálky za cenu rychlejšího zničení štítu. krytí. Štít je poškozen za 20 násobek jeho KZ, ale zranění je poníženo pouze o jeho základní KZ. Pokud tato rána štít úplně zničila, je postava navíc zraněna do ruky ve které drží štít. Šance na vykrytí se odvíjí od stupně na jaký postava dovednost ovládá. Fatální úspěch: Postava vykryla poškození rovnající se až desetinásobku KZ štítu, ale štít je poškozen také za desetinásobek svého KZ. Úspěch: Postava vykryla poškození rovnající se 5 násobku KZ štítu a štít je poškozen za 5 násobek svého KZ. Neúspěch: Postava nezvládla ránu pohltit štítem. Je zraněna standardně a štít také. Fatální neúspěch: Postava naprosto nezvládla', 'Vlastnost: obratnost; Obtížnost: střední; Ověřování: každá ohlášená obrana štítem', TRUE),
('Mučení', 'dovednost', 'Tato praktika je oficiálně používána jen v krajních případech a bez povolení soudu je zakázána. Fatální úspěch: Mučený se svíjí v agonii a řekne postavě vše co chce vědět. Hlavně aby už ji přestal působit tu nesnesitelnu bolest. Příští hod na past +2. Úspěch: Mučený odpověděl na otázku. Neúspěch: Mučený odmítá odpovědět. Fatální neúspěch: Postava neodhadla prostředky jimiž chtěla získat informace a usmrtila mučeného.', 'Vlastnost: obratnost; Obtížnost: střední; Ověřování: Každá otázka', TRUE),
('Opravování zbraní a zbrojí', 'dovednost', 'Procentuální hodnota říká do jaké míry ´´opravenosti´´ je postava schopná danou zbroj opravit. Opravit 1 bod životnosti na cestách trvá 2 kola času. Za 1 směnu práce přibudou 2 body únavy. Opravit 2 body životnosti v dílně trvá 1 kolo času. Za 1 směnu práce přibudou 2 body únavy. 1 Zl hodnoty životnosti zbroje váží 0,1 mince. Potřebná dílna je stejná jako kovářská, sedlářská, krejčovská apod. Fatální úspěch: Opravit zbroj stálo o 50% méně než u řemeslníka. Úspěch: Opravit zbroj stálo o 20% méně než u řemeslníka. Neúspěch: Zbroj se nepodařilo opravit. Postava se může o další opravu pokusit až za hodinu, než se uklidní. Fatální neúspěch: Vše se spiklo proti opravě této zbroje. Všechny suroviny vynaložené na její opravu přišly vniveč a objevilo se několik nových děr... Šance na úplné zničení zbroje apod. Pj', 'Vlastnost: obratnost; Obtížnost: střední; Ověřování: Jednou za opravu', TRUE),
('Ošetřování zvířat', 'dovednost', 'jedná se o ošetřování a obstarávání běžných nemagických zvířat - kůň, pes, kočka. Nefunguje na hmyz a čistě vodní tvory (delfín ne, vydra ano), po poradě s PJ je možné se naučit specializace na méně obvyklé tvory, ale rozhoduje PJ. Fatální úspěch: Zvíře je obstaráno skvěle. Je vyléčeno za 1K6 životů a přes noc si vyléčí dvojnásobek životů z přirozené regenerace. Úspěch: Zvíře je spokojené a má vše co potřebuje. Přes noc si doplní dvojnásobek životů z běžné regenerace. Neúspěch: postava nedokázala zvíře ošetřit ani obstarat. Fatální neúspěch: Zvíře se začalo plašit a postava zpanikařila. Došlo ke zranění zvířete i ošetřovatele za 1K10 životů. PJ', 'Vlastnost: obratnost; Obtížnost: lehká; Ověřování: každé ošetřování 1 zvíře/1 den', TRUE),
('Padělání', 'dovednost', '-12-. všechny postavy dokumentu neznalé ho automaticky považují za pravý. Fatální úspěch: Postava si hází proti pasti Int -12-, zda li bude mít podezření o její pravosti. Lze porovnat pouze s originálem a i tak bude past Int Úspěch: Past na podezření je Int-8-. zde postava nemusí mít k dispozici originál. Všechny osoby dokumentu neznalé jsou přesvědčený o jeho pravosti. Neúspěch: Postavy s Inteligencí 14 a vyšší ihned poznají, že se jedná o padělek, stačí když si dokument aspoň jedno kolo budou prohlížet. Postavy s inteligencí nižší si hází na past Int-5- zda li poznají, že se jedná o padělek. Proti této pasti si hází i postavy dokumentu neznalé. Fatální neúspěch: Totéž co neúspěch, ale všichni kteří o padělání dokumentu vědí, jsou přesvědčeni o jeho bezchybnosti.', 'Vlastnost: obratnost; Obtížnost: těžká; Ověřování: Každá padělaná listina', TRUE),
('Rybaření', 'dovednost', 'Fatální úspěch: Postava ulovila za 2 hodiny 2K6 ryb. 1 ryba = 1 dávka jídla na den. Úspěch: Postava ulovila 1K6 ryb za 2 hodiny. Neúspěch: Postava nechytla nic během 2 hodin. Fatální neúspěch: Postava všechny ryby v okolí na zbytek dne vyplašila, zničila prut apod.', 'Vlastnost: obratnost; Obtížnost: lehká; Ověřování: Na začátku lovu a pak každé 2 hodiny.', TRUE),
('Řezbářství', 'dovednost', 'Fatální úspěch: Soška dokonale zachycuje podobu osoby, Či předmět přesně sedne do vkusu. Postava si vyslouží pozvání, peněžní bonus apod. Úspěch: Dílo se povedlo a postava dostane zaplaceno plnou cenu. Neúspěch: Dílo je takřka na vyhození a plné vad. Osoba se bude cítit uražena a odmítne zaplatit. Fatální neúspěch: Dílo jo kompletně zničené, šance na zničení nástrojů. Postava sklidí posměch apod. PJ', 'Vlastnost: obratnost; Obtížnost: střední; Ověřování: každý předmět, nebo každé 3 hodiny.', TRUE),
('Stavitelství katapultů', 'dovednost', 'Stavitel sám není schopen postavit obléhací stroje, kreslí plány a koordinuje řemeslníky.. V případě, že by měl k dispozici předpřipravené všechny díly, je schopen ho postavit i bez řemeslníků, ale potřebuje fyzickou pomoc dalších osob. Fatální úspěch: Stavba trvá polovinu doby uvedené v tabulce. Úspěch: Stavba trvá jako v tabulce. Neúspěch: Postava trvá dvakrát tak dlouho jako v tabulce. Fatální neúspěch: Stavba se nepovede a vynaložené prostředky přijdou nazmar.', 'Vlastnost: inteligence; Obtížnost: těžká; Ověřování: každá stavba', TRUE),
('Střelba do dálky', 'dovednost', 'Lze použít na všechny luku podobné střelné zbraně, kde střelec ovlivňuje přímo sílu nátahu. kuše musí být pro tyto účely přizpůsobeny na míru zbrojířem. Krátký dostřel se prodlouží o 50% Střední o 30%. A dlouhý o 20% Fatální úspěch: Postava zasáhla naprosto precizně a přesně. Pokud zraní cíl dalších 1K4 bodů zranění. Úspěch: Postava zasáhla cíl i na zvětšenou vzdálenost. Neúspěch: Postava nedostřelila v případě dlouhé dostřelu. Nebo neodhadla správně vzdálenost. - 1K6 od případného zranění cíle. Fatální neúspěch: Něco se ošklivě pokazilo. Šance na přetržení tětivy. Šíp se vydal náhodným směrem. (i za střelce). Luk střelci vyklouzl z ruky a nafackoval si jím za 1K6 životů apod. PJ', 'Vlastnost: obratnost; Obtížnost: těžká; Ověřování: každý výstřel', TRUE),
('Svižnost hobitů', 'dovednost', 'Postava získá díky intenzivnímu tréningu mnohem lepší pohyblivost a lepší reflexy. Při hodu proti pasti na obratnost může postava uplatnit tuto dovednost a navýšit výsledek svého hodu o 1. Naučí li se postava svižnost hobitů na dokonale pohyblivost na všech stupních +2 a bonus za rozběh se zvýší o +2', 'Vlastnost: obratnost; Obtížnost: těžká', TRUE),
('Ševcovství', 'dovednost', 'viz řezbářství a ostatní běžná řemesla', 'Vlastnost: obratnost; Obtížnost: střední', TRUE),
('Švindlování při hazardu', 'dovednost', 'Aby mohla postava podvádět, musí se několika hrami seznámit s pravidly, pokud danou hru již nehrála. 2-5 her, dle složitosti. Fatální úspěch: Brilatní tah. Nikdo nemá šanci si všimnout podvodu. Úspěch: Vše prošlo. Je zde 10% šance že si někdo všimne podvodu. Neúspěch: Nejen že se švindl nevyvedl, ale ještě vyústil v prohru. 35% šance na provalení podvodu. Fatální neúspěch: 100% šance na provalení podvodu.', 'Vlastnost: obratnost; Obtížnost: těžká; Ověřování: každou hru', TRUE),
('Tichý pohyb', 'dovednost', 'Schopnost neslyšně překonávat vzdálenost. Šance jsou silně ovlivněny oblečením postavy, naložením, stupněm dovednosti atd. PJ Šance uvedená v % vyjadřuje šanci na neslyšný přesun za ideálních podmínek. Rychlost přesunu jsou 2 sáhy za kolo. Pokud postava zpomalí na 1 sáh za kolo, její šance vzrostou o dalších 15%. Naučí li se tuto dovednost postava, která již plížení umí od základu, vzroste její šance paušálně o dalších 15%. Fatální úspěch: Postava se pohybuje jako duch. Ověřování za dvojnásobek obvyklé doby. Může se plížit rychlostí až 3 sáhy za kolo. Úspěch: postava se pohybuje neslyšně.. Neúspěch: Postavu uslyší každý v určitém dosahu. Fatální neúspěch: Postava omylem ztropila rámus a stáhla na sebe pozornost i ze širšího okolí.', 'Vlastnost: obratnost; Obtížnost: lehká; Ověřování: každá 3 kola plížení', TRUE),
('Tkaní', 'dovednost', 'viz řezbářství a ostatní běžná řemesla', 'Vlastnost: obratnost; Obtížnost: střední', TRUE),
('Truhlářství, hrnčířství a podobná řemesla', 'dovednost', 'Fatální úspěch: Vyrobený kus je mistrovský a bezvadný. Bude velice žádaný. Úspěch: Vyrobený kus je dobré, ale průměrné kvality. Neúspěch: Výrobek je zralý k putování na skládku. Fatální neúspěch: I skládka odmítá výrobek přijmout. Šance na vznik požáru apod. Dle okolností. PJ.', 'Vlastnost: obratnost; Obtížnost: střední; Ověřování: jednou za výrobek, nebo každé 3 hodiny', TRUE),
('Udržování ohně', 'dovednost', 'Díky této dovednosti má postava i vyšší šance na zapálení mokrého dřeva či všeobecně špatného materiálu a jeho udržení ve velice nepříznivém počasí, udělat ohniště tak, aby nekouřilo apod. Fatální úspěch: oheň hoří přesně dle potřeb a spotřeba dřeva je o polovinu menší Úspěch: oheň hoří normálně Neúspěch: oheň vyhasl Fatální neúspěch: Oheň vyhasl a postava se při pokusu jej rozdmýchat popálila o jeho zbytky za 1K6 životů. Nebo oheň nehoří, ale vše okolo ano. PJ', 'Vlastnost: obratnost; Obtížnost: lehká; Ověřování: jednou za každé ohniště, nebo při změně počasí', TRUE),
('Vaření', 'dovednost', 'Fatální úspěch: Jídlo je naprosto vynikající a dokonce kuchař zdvojnásobil jeho množství. Úspěch: Jídlo je plnohodnotné a dobré. Neúspěch: Jídlo lze sníst s velkým sebezapřením. A polovina surovin při jeho vaření se musela vyhodit. Fatální neúspěch: Vše přišlo vniveč. Pokud se to někdo pokusí sníst, riskuje otravu. PJ', 'Vlastnost: obratnost; Obtížnost: lehká, střední, těžká; Ověřování: Každé jídlo', TRUE),
('Získávání jedů', 'dovednost', 'Fatální úspěch: Jed má poloviční nebezpečnost i sílu Úspěch: Jed má čtvrtinovou sílu a nebezpečnost -2. Neúspěch: Jed se nepodařilo získat. Fatální neúspěch: Postava při sběru otrávila sama sebe.', 'Vlastnost: obratnost; Obtížnost: střední; Ověřování: Každé získávání', TRUE),
('Zlatnictví', 'dovednost', 'Musí mít k dispozici dílnu poloviční velikosti než je kovář, ale výbava stojí o polovinu víc. Zlatník umí zpracovávat všechny drahé kovy běžně se vyskytující v daném světě. Umí li legendární kovářství, umí i ty měnit na šperky. Umí také zasazovat do šperků drahé kameny apod. Fatální úspěch: Výjimečná kvalita a zpracování +15% ceny navíc. Úspěch: Výrobek je běžné kvality. Neúspěch: Výrobek je plný vad. -30% ceny Fatální neúspěch: Zlato díky nehodě shořelo. Šance na podpálení dílny apod. PJ', 'Vlastnost: obratnost; Obtížnost: těžká; Ověřování: každý výrobek', TRUE),
('Asketismus', 'dovednost', 'Postava je schopna déle vydržet nedostatek jídla a vody aniž by se na ní projevily negativní účinky. Pokud postava umí asketismus dobře, a rozhodne se tak, může šetřit jídlem, nebo vodou tzv. obden. Fatální úspěch: Postava pocítí postihy s hladověním a nedostatkem až po 3 dnech. Úspěch: Postava pocítí postihy s hladověním a nedostatkem až po 2 dnech. Neúspěch: Postava je sužována dle pravidel. Fatální neúspěch: Dehydratace a hladovění způsobují dvojnásobnou únavu.', 'Vlastnost: odolnost; Obtížnost: těžká; Ověřování: Každý den kdy se snaží vydržet o hladu a žízni.', TRUE),
('Držení pozice', 'dovednost', 'Za každý rozdíl velikosti se past mění o 1 Když útočník sprintuje, past se zvýší o 1. Pokud obránce úspěšně odolal, je útočník zraněn za SZ, kterou má obránce, v hodnotě 4xSZ. Za každých 200 mincí hmotnosti se past na zastavení zvýší o 1. Za každé 4 sáhy za kolo, kterými se předmět pohybuje, se past zvýší o 1. Pokud je obránce povalen, je zraněn za 1K10 životů za každých 300 mincí hmotnosti předmětu. Aby obránce mohl zastavit nájezd, musí mít k dispozici zbraň minimální délky 2. Pokud je tvor, který najíždí velikosti D, past na zastavení se snižuje o 3. Za každé 4 sáhy za kolo, kterými jezdec najíždí na obránce, se past snižuje o 1. Pokud obránce zastaví nájezd, je jezdecký tvor zraněn za SZ zbraně x9 + rozdíl v hodu na past. Pokud jezdec s tvorem prorazí, je obránce zraněn za 3K10 životů + rozdíl v hodu proti pasti a je povalen na 3 kola. Povalený obránce, pokud má na sobě zbroj, je jeho zranění poníženo o kvalitu zbroje. Když má zvíře na sobě zbroj, zranění které utrpí z nepovedeného nájezdu, je poníženo o kvalitu zbroje. Fatální úspěch: Postava odolala nárazu brilantně a využila hybnosti k další činnosti, možnost okamžitě použít volnou 1 akci, nebo +1 k iniciativě v dalším kole. Úspěch: Postava odolala sražení. Neúspěch: postava neodolala povalení Fatální neúspěch: Postava byla naprosto převálcována a je zraněna za 10 životů.', 'Vlastnost: odolnost; Obtížnost: střední; Ověřování: každý pokus', TRUE),
('Hasičství', 'dovednost', 'Pouze pro menší zranění jakýmkoliv ohněm. Fatální úspěch: Požár se rozšiřuje poloviční rychlostí a způsobuje poloviční škody. Postava je zraněna za polovinu obvyklých životů. Při hodu proti pasti má +2 k hodu. Úspěch: Požár se rozšiřuje o čtvrtinu pomaleji a způsobuje o čtvrtinu menší škody. Postava je zraněna o čtvrtinu méně než obvykle. Při hodu proti pasti má +1 k hodu. Neúspěch: Veškeré hodnoty jsou nezměněny. Fatální neúspěch: Hodnoty se o polovinu zvyšují a hod proti pasti má postava -2.', 'Vlastnost: odolnost; Obtížnost: střední; Ověřování: každý průchod ohněm, každé hašení', TRUE),
('Kachní žaludek', 'dovednost', 'Postava zvládne sníst jídlo které je nevábné až nechutné. Ovšem dovednost neřeší bylo li otrávené či zcela zkažené. Lze použít i v případě alkoholu, kdy se snaží postava zachovat tvář a nezvrátit obsah žaludku. Domluva s PJ. Fatální úspěch: Postava porci snědla bez nejmenších problémů. Pokud se jedná o místní specialitu, sklidí obdiv místních. Úspěch: Postava byla schopná jídlo sníst. Neúspěch: Postava se nedokázala donutit jídlo sníst. Fatální neúspěch: Postava si zprvu myslela že má vše pod kontrolou, ale vše musí ven. 3 kola dávení a případné ostudy.', 'Vlastnost: odolnost; Obtížnost: lehká; Ověřování: S každým jídlem, které postava považuje za nechutné', TRUE),
('Koželužnictví', 'dovednost', 'Stáhnout kůži ze zvířete umí každý hraničář, ale na její vyčinení je zapotřebí aspoň lovecká chata, nebo bytelný přístřešek. Ideálně dílna. Činit lze chemicky, nebo přírodními prostředky. Postava umí vyčinit kůže i kožešiny. Fatální úspěch: Kůže je vyčiněna skvěle, Dostane za ní o 25% více peněz, Úspěch: Kůže je vyčiněna Neúspěch: Kůže je vyčiněná mizerně. -50% z ceny. Fatální neúspěch: Kůže je docela zničená. Postava má šanci se přiotrávit. PJ', 'Vlastnost: odolnost; Obtížnost: lehká; Ověřování: Každá kůže', TRUE),
('Nosič', 'dovednost', 'Fatální úspěch: Postava se cítí a pohybuje jako by měla naložení o stupeň nižší. Další ověřování až za 3 hodiny. Úspěch: Postava se pohybuje, jako by měla naložení o stupeň nižší. Neúspěch: Postava má naložení dle skutečnosti. Fatální neúspěch: Postava se cítí, jako by měla naložení o stupeň vyšší.', 'Vlastnost: odolnost; Obtížnost: lehká; Ověřování: každou hodinu', TRUE),
('Odolávání alkoholu', 'dovednost', 'Fatální úspěch: Postava si při dalším odolávání může přičíst k hodu +2. Pije jako mistr. Úspěch: Postava na sobě zatím cítí sílu a vliv alkoholu s poloviční silou než obvykle. Neúspěch: Alkohol působí na postavu plnou silou. Fatální neúspěch: Alkohol působí na postavu s dvojnásobnou silou. Na příští odolávání se past zvyšuje o 3.', 'Vlastnost: odolnost; Obtížnost: lehká; Ověřování: každé pití, nebo dle okolností', TRUE),
('Odolnost trpaslíků', 'dovednost', 'Postava po vzoru trpaslíků zoceluje svoje tělo všemožnými způsoby. Při hodu na past může postava uplatnit trpasličí odolnost a navýšit výsledek svého hodu o 1. Naučí li se postava dovednost dokonale, získá také +1 život při přestupu na novou úroveň i poté co přestoupila na 9 úroveń a výš.', 'Vlastnost: odolnost; Obtížnost: těžká; Ověřování: při každém pokusu', TRUE),
('Otužilectví', 'dovednost', 'Postava se ve volných chvílích pravidelně otužuje a trochu se ´´trápí´´ aby její tělo bylo odolnější vůči nachlazení a běžným nemocem. PJ Fatální úspěch: Postava má +2 k hodu proti pasti. Úspěch: Postava má +1 k hodu proti pasti. Neúspěch: Postava nemá bonus k pasti. Fatální neúspěch: Postava má -2 k hodu proti pasti.', 'Vlastnost: odolnost; Obtížnost: střední; Ověřování: V případě potřeby - PJ', TRUE),
('Plivání ohně', 'dovednost', 'Dovednost může sloužit jako součást vystoupení, ale i jako bojová dovednost. Postava musí mít k dispozici otevřený oheň a vhodnou hořlavinu, kterou lze plivat. ohněm je schopna zasáhnout až 3 cíle ve vzdálenosti 1-3 ve výseči. Fatální úspěch: Plivnutí se podařilo skvěle. Příští pokus si postava nemusí házet na past. Úspěch: Postava vyplivnula oheń úspěšně. Neúspěch: Postavě se nepodařilo heń zapálit a přišla o dávku hořlaviny. Fatální neúspěch: Postava nešťastně zapálila sama sebe. Hoří za 1K6 životů každé kolo po dobu tří kol, nebo dokud se neuhasí. 40% šance, že ve vzdálenosti 1 hexu od postavy vzplanou hořlavé předměty/osoby. Má li u sebe postava více dobrých hořlavin, je šance že chytnou i ty.', 'Vlastnost: odolnost; Obtížnost: střední; Ověřování: Každé plivnutí', TRUE),
('Rosomáčí odolnost', 'dovednost', 'Postava zvyká své tělo postupně na nepohodlí a zároveň se o něj dobře stará. Když se postava naučí dovednost na dokonale, zvýší se jí stupeń odolnosti o 2. Dovednost se lze naučit vícekrát, ale stupeň za Odolnost nepřesáhne 13+1', 'Vlastnost: odolnost; Obtížnost: lehká', TRUE),
('Řeznictví', 'dovednost', 'Potřebuje nože, pomocnou ruku, či možnost si někam zvíře při bourání zavěsit apod. Fatální úspěch: Podařilo se získat dvojnásobek masa. Úspěch: Postava získala o 20% více masa než obvykle. Neúspěch: Postava přišla o 20% masa. Fatální neúspěch: Maso je znehodnoceno.', 'Vlastnost: odolnost; Obtížnost: střední; Ověřování: Každé bourané zvíře', TRUE),
('Sklářství', 'dovednost', 'Fatální úspěch: Výrobek je bez chybičky. +20% k ceně. Úspěch: Výrobek je normální kvality. Neúspěch: Výrobek je na vyhození. Fatální neúspěch: Do sklářské pece se dostala vlhkost. Várka skla je k ničemu. Šance na výbuch, požár apod. PJ', 'Vlastnost: odolnost; Obtížnost: těžká; Ověřování: Každý výrobek, nebo co 3 hodiny.', TRUE),
('Umění usnout', 'dovednost', 'Zvládne se plnohodnotně vyspat i ve zbroji. Fatální úspěch: Postava usne i v nepohodlných polohách a prostředí a probudí se naprosto svěží. Úspěch: Postava spí prakticky okamžitě. Za spánek si může odečíst o 1 bod únavy navíc. Neúspěch: Postavě se nedaří usnout. Fatální neúspěch: Postava se vnitřně vystresovala z neschopnosti usnout a může se o to znovu pokusit až za hodinu. Za tuto dobu získá 1 bod únavy ze stresu.', 'Vlastnost: odolnost; Obtížnost: lehká; Ověřování: každý pokus o usnutí', TRUE),
('Zadržování dechu', 'dovednost', 'Fatální úspěch: Příští kolo si postava nehází proti pasti a ani se ji nezvyšuje past. Úspěch: Postava se ještě nedusí. Neúspěch: Postava se začíná dusit a musí se nejdéle příští kolo nadechnout. Fatální neúspěch: Postava se musela okamžitě nadechnout. Dle okolností se začíná topit, je otrávena apod.', 'Vlastnost: odolnost; Obtížnost: těžká; Ověřování: Od 4. kola včetně. S každým dalším kolem se past zvyšuje o 1.', TRUE),
('Architekt', 'dovednost', 'Postavy s touto dovedností umí nakreslit plány budov a koordinovat jednotlivé pracovní čety. Fatální úspěch: Stavba je precizní ve všech ohledech. Bude postavena o 4% rychleji, nebo o 4% levněji na materiálu. Úspěch: Stavba je standardní kvality. Neúspěch: Stavba má spoustu chyb, zdi jsou křivé, chybí okna, přebývají dveře apod. Fatální neúspěch: Stavba je na zbourání. Pokoje nemají střechu, sklep je na půdě apod. Ztracený čas.', 'Vlastnost: inteligence; Obtížnost: střední; Ověřování: jednou pro každou stavbu', TRUE),
('Astrologie', 'dovednost', 'Jedná se o věštění z hvězd, dlaně, karet letu ptáků apod. Každá kultůra má své preferované způsoby. Může se jednat i o šamanské rituály a tranz. Astrolog může zjišťovat informace pro nějakou osobu, nebo o nějaké osobě. Pokud má zjistit informace o někom, vždy pomůže když má něco, co té osobě patřilo. Vlasy, oblečení, šperk apod. Snáze se zjišťují infomace minulé než budoucí. a i zde platí omezení jako u sfér. Rozhoduje PJ. Fatální úspěch: Postava je shopna podat poměrně přesné a pravdivé informace Úspěch: Postava je schopna podat povšechné informace Neúspěch: Postava není schopna podat žádnou konkrétní informaci. Fatální neúspěch: Postava předpoví přesný opak.', 'Vlastnost: inteligence; Obtížnost: těžká; Ověřování: při každé předpovědi', TRUE),
('Boj poslepu', 'dovednost', 'Nelze použít proti nehmotným protivníkům. Postava se orientuje o pohybu postavy/postav sluchem . V případě boje s více protivníky si musí házet na každého zvlášť. Fatální úspěch: Nemusí ověřovat příští směnu při boji s tímto jedním konkrétním protivníkem. Postava nemá postih za boj poslepu.. Úspěch: Postava má poloviční postih. Zaokrouhleno nahoru. Neúspěch: Postava má stejný postih dle pravidel. Fatální neúspěch: Postava svůj postih zvýšila o polovinu.', 'Vlastnost: inteligence; Obtížnost: těžká; Ověřování: Každé kolo boje', TRUE),
('Botanik', 'dovednost', 'Aby se postava mohla stát botanikem, musí umět lékárníka na dokonale Fatální úspěch: Postava má větší výnos Úspěch: Postava úspěšně vypěstuje rostliny. Neúspěch: Rostlina zahynula. Fatální neúspěch: Rostlina chytila plíseň a zničila další.', 'Vlastnost: inteligence; Obtížnost: těžká; Ověřování: každá výroba', TRUE),
('Bylinkář', 'dovednost', 'Každý stupeň dovednosti zvyšuje šance na nalezení konkrétní rostliny o 2% Šance na jejich nalezení v tabulce uvádějí % šance, když umí postava dovednost na dokonale. Fatální úspěch: Postava najde bylinu vyšší kvality Úspěch: Postava nalezla co hledala. Neúspěch: Postava nic nenašla. Fatální neúspěch: Postava při pokusu o výrobu zničila suroviny.', 'Vlastnost: inteligence; Obtížnost: lehká; Ověřování: každá výroba/hledání', TRUE),
('Čtení a psaní', 'dovednost', 'Čtení je dovednost, kterou postava umí/neumí. Pokud umí aspoň průměrně, nemusí ověřovat běžné texty. Psaní je složitější. Stupeň dovednosti také ovlivňuje, jak rychle je postava schopna něco přečíst/zapsat. Každý typ písma se musí postava učit zvlášť. Dovednost je spjatá s dovednosti jazyky. Aby se postava mohla naučit dobře psát, musí znát dobře jazyk. Fatální úspěch: Postava bezchybně přečte daný text a objeví všechny pravopisné chyby, či dokonale text zapíše. Úspěch: Postava napíše text tak, že bude pochopen, ale neopraví po sobě hrubky. Neúspěch: Postavě se nepodaří text přečíst, nebo ho napíše nečitelně. Fatální neúspěch: Postava poplete text tak, že je pochopen zcela špatně.', 'Vlastnost: inteligence; Obtížnost: střední; Ověřování: při každém čtení/psaní', TRUE),
('Čtení ze rtů', 'dovednost', 'Pokud postava nezná jazyk, kterým odezíraný mluví, má past o 4 vyšší na rozpoznání toho, co říká. I při úspěchu nebude vědět obsah slov a bude potřebovat je přeložit. Aby mohla ze trů odezírat, musí vidět rty. Maximální vzdálenost na kterou lze odezírat je 15 sáhů. Pokud nepoužije dalekohled apod. Fatální úspěch: Postava rozumí skvěle, nemusí ověřovat dalších 5 minut. Úspěch: Postava rozumí. Neúspěch: Postava nerozumí. Fatální neúspěch: Postava rozumí opak toho, co postava řekla.', 'Vlastnost: inteligence; Obtížnost: těžká; Ověřování: Každá věta', TRUE),
('Jazyky', 'dovednost', 'Každá postava umí na začátku svůj rodný jazyk velmi dobře. Past se upravuje dle složitosti hovoru. Fatální úspěch: Postava až do konce rozhovoru nemusí ověřovat. Úspěch: Postava rozumněla, všemu řečenému. Neúspěch: Postava nepochopila obsah sdělení, či zkomolila své sdělení. Fatální neúspěch: To, co se postava snažila říct, nebo čemu pozorumět, bylo pochopeno zcela opačně.', 'Vlastnost: inteligence; Obtížnost: těžká; Ověřování: jednou za 10 kol nebo při každé otázce', TRUE),
('Kartografie', 'dovednost', 'Dovednost kartografie v sobě zahrnuje jak vytváření map, tak orientaci v nich. Kartograf je schopen tvořit zcela nové mapy podle terénu, nebo je porovnávat se skutečností a určovat jejich přesnost apod. Fatální úspěch: Pravděpodobnost bloudění se snižuje o 20% a výsledná mapa je velice kvalitní a přesná. Úspěch: Pravděpodobnost bloudění se snižuje o 10% a mapa je standardní kvality. Neúspěch: Bloudění podle pravidel, mapu se nepodařilo nakreslit. Fatální neúspěch: Pravděpodobnost bloudění se zvyšuje o 20%. O mapě si tvůrce myslí že je perfektní, ale ve skutečnosti zvyšuje šanci na bloudění o 20%.', 'Vlastnost: inteligence; Obtížnost: střední; Ověřování: Při kreslení nové mapy, nebo při bloudění', TRUE),
('Konstrukce lodí', 'dovednost', 'Tato dovednost umožňuje postavě pouze lodě navrhovat a řídit práce ostatních řemeslníků nezbytných pro její stavbu. Fatální úspěch: Loď bude mít o čtvrtinu vyšší rychlost, než je obvyklé. Úspěch: Loď normální kvality. Neúspěch: Loď bude mít o čtvrtinu nižší rychlost než je obvyklé. Fatální neúspěch: Loď je velice nestabilní, ale pozná se to až po spuštění na vodu.', 'Vlastnost: inteligence; Obtížnost: těžká; Ověřování: jednou pro každou loď', TRUE),
('Lékárník', 'dovednost', 'Aby se postava mohla naučit vyrábět léky, musí umět bylinkáře na dokonale. Fatální úspěch: Postava ze surovin vyrobí o jeden lék navíc. Úspěch: Postava vyrobí lék. Neúspěch: Postava nevyrobila lék. Fatální neúspěch: Postava při pokusu o výrobu zničila suroviny.', 'Vlastnost: inteligence; Obtížnost: střední; Ověřování: každá výroba', TRUE),
('Lodní navigace', 'dovednost', 'Základní dovednost pro všechny lodní kapitány a kormidelníky Fatální úspěch: Správně určený kurz, loď nebloudí až do dalšího dne. Úspěch: Správně určená poloha lodi, ale může dojít během dne k odchylce. Šance na bloudění je o 50% nižší. Neúspěch: Správně určená poloha lodi, ale je vysoká pravděpodobnost bloudění. Fatální neúspěch: Nesprávná poloha, loď bloudí.', 'Vlastnost: inteligence; Obtížnost: těžká; Ověřování: každé ráno, nebo při změně směru', TRUE),
('Lstivost tieflingů', 'dovednost', 'Postava svou mysl vycvičí a pozmění natolik, že její fungování je značně odlišné od zbytku populace. Při hodu proti pasti na inteligenci může postava uplatnit tuto dovednost a navýšit výsledek svého hodu o 1. Naučí li se postava lstivost tieflingů na dokonale získá schopnost poznat že dotyčný lže či neříká celou pravdu. (15%)', 'Vlastnost: inteligence; Obtížnost: těžká; Ověřování: Při každém posuzování jestli dotyčný lže.', TRUE),
('Mantry', 'dovednost', 'mantry slouží k memorizování již naučených kouzel a usnadňují tak jejich sesílání. 100% vždy znamená fatální neúspěch při seslání kouzla. Mantry fungují i na kouzla s vlastní procentuální šanci na seslání nezávisle na inteligenci sesilatele.', 'Vlastnost: inteligence; Obtížnost: těžká; Ověřování: bez ověřování', TRUE),
('Maskování v přírodě, improvizované úkryty', 'dovednost', 'Jakmile se postava ukryje, nesmí se hýbat, jinak musí strávit další směnu novým maskováním. Past pro hledajícího je o 1 nižší. Vytvořit maskovaný úkryt pro jednu osobu trvá minimálně 2 směny za ideálních podmínek. Fatální úspěch: Úkryt je v rámci možnosti perfektní a poskytuje pohodlí jako kvalitní cestovní stan. Úspěch: Úkryt poskytuje základní ochranu proti živlům. Past pro hledajícího je o 1 vyšší. Neúspěch: Úkryt se po dokončení rozpadne. Fatální neúspěch: Postava je přesvědčena o dokonalosti úkrytu, ten spadne na své uživatele a zraní je za 1k4 životů. Past pro hledajícího je o 2 nižší.', 'Vlastnost: inteligence; Obtížnost: lehká; Ověřování: Jednou za úkryt pro 1 osobu', TRUE),
('Orientace podle hvězd', 'dovednost', 'Důlní značky Tuto dovednost se mohou naučit jen trpaslíci během hraní, není li řečeno jinak. Fatální úspěch: Postava až do rozbřesku nemusí ověřovat. Úspěch: Postava ví, kde je jaký směr. Neúspěch: Postava nepoznává souhvězdí. Šance na bloudění je o 20% vyšší. Fatální neúspěch: Postava je přesvědčena, že jde správně. Šance bloudění o 50% vyšší.', 'Vlastnost: inteligence; Obtížnost: lehká; Ověřování: Každou hodinu pochopu pod hvězdami', TRUE),
('Počítání', 'dovednost', 'Fatální úspěch: Postava si příští směnu nemusí házet na ověřování. Úspěch: Postava správně spočítala sumu. Neúspěch: Postava se ve výpočtu zmýlila. Fatální neúspěch: Postava se vy výpočtu naprosto zmýlila, ale svým výsledkem si je naprosto jistá.', 'Vlastnost: inteligence; Obtížnost: střední; Ověřování: Každý odhad, výpočet', TRUE),
('Posunková řeč', 'dovednost', 'Posunková řeč je takřka dokonale univerzální. Dvě osoby které umí posunkovou řeč, ale neznají normální řeč toho druhého, jsou i tak schopné se dorozumět, pokud se bude jednat o dostatečně všeobecné a běžné záležitosti. Fatální úspěch: Postava si příští směnu nemusí házet na ověřování. Úspěch: Postava rozumí. Neúspěch: Postava není shcopná pochopit sdělení, nebo jej předat. Fatální neúspěch: Postava pochopí, nebo sdělí přesný opak.', 'Vlastnost: inteligence; Obtížnost: střední; Ověřování: Každá otázka, odpověď.', TRUE),
('Prospektor, mineralog', 'dovednost', 'Postava s touto dovedností plánuje kopání tunelů a organiuje práce při kopání. Umí poznat složení hornin a minerálů vyskytujících se v zemi. Sama ovšem kopat, nebo dělat výdřevy neumí. Fatální úspěch: Postava nemusí příštích 10 sáhů tunelu ověřovat. Postava přesně pozná všechny a případně nacení nalezené minerály. Úspěch: Postava úspěšně navrhnula 5 sáhů tunelu. Poznala jeden konkrétní minerál. Neúspěch: Postava neodhadla situaci a 5 sáhů tunelu se zřitilo. Postava nepoznala minerál. Fatální neúspěch: Tunel se tvářil v pořádku, ale došlo k závalu, ten poškodí minimálně dalších 5 sáhů tunelů. Šance na zavalení osob apod. Postava považuje minerály za bezcenné, nebo je naprosto milně ohodnotí.', 'Vlastnost: inteligence; Obtížnost: těžká; Ověřování: Každých 5 sáhů tunelu. Každý pokus o rozpoznání minerálu.', TRUE),
('Signalizace', 'dovednost', 'Jedná se o dorozumívání na velké vzdálenosti jinak než řečí. Kouřové signály, prapory apod. Postava si musí vybrat jaký způsob signalizace se její postava naučí. Každý kdo umí signalizaci stejného druhu bude rozumnět předávané zprávě, vidí li ji. Musí ověřovat. Fatální úspěch: Nemusí příští směnu ověřovat Úspěch: Postava pochopí obsah sdělení, nebo jej sama předá. Neúspěch: Postava nechápe obsah, není schopna zprávu předat. Fatální neúspěch: Postava pochopila přesný opak sdělení, nebo sama sdělila přesný opak.', 'Vlastnost: inteligence; Obtížnost: střední; Ověřování: Každá zpráva', TRUE),
('Soví moudrost', 'dovednost', 'Postava pravidelně zaměstnává svou mysl vzděláváním se a bystřením svého ducha. Když se postava naučí dovednost na dokonale, zvýší se ji stupeń inteligence o 2. Nelze navýšit nad 13 +1', 'Vlastnost: inteligence; Obtížnost: lehká', TRUE),
('Stopování', 'dovednost', 'Pro hledání stop se využívá hledání objektů dle pravidel Pro jejich sledování je zapotřebí tato dovednost. šance na úspěch se odvíjí od stupně dovednosti a okolností, za kterých se postava snaží sledovat stopu. Šance uvedená v % vyjadřuje šanci na sledování stopy za ideálních podmínek. Vůbec 0%, Velmi špatně 5%, Špatně 10%, Průměrně 20%, Dobře 25%, Velmi dobře 35%, Dokonale 45%. Naučí li se tuto dovednost postava, která již stopování umí od základu, na dokonale, šance na stopování se pro ni zvýší o 20% ve všech terénech. Fatální úspěch: Postava sleduje stopu bezchybně, ověřování za dvojnásobek obvyklé doby a plnou rychlostí. Úspěch: Sleduje stopu. Neúspěch: Stopa se postavě ztratila,další pokus o stopování až za 1 směnu. Fatální neúspěch: Postava stopy zničila a znemožnila další stopování.', 'Vlastnost: inteligence; Obtížnost: lehká; Ověřování: každé sledování stopy, ověřování každé 3 směny, nebo dle okolností', TRUE),
('Břichomluvectví', 'dovednost', 'Mistři tohoto umění takto dokáží i zpívat, šeptat. Když se bude pokoušet zpívat, past se zvyšuje o 2. Břichomluvci jsou vzácní a bývají velice vítání na slavnostech. Fatální úspěch: Postava naprosto obelství své posluchače. Při hodu na další past si může počítat +2 k hodu. Úspěch: Ostatní si myslí, že mluví někdo jiný. Neúspěch: Postavy poznaly, že zvuky vylizuje postava. Fatální neúspěch: Postava se zakucká a nebude schopna se znovu pokusit o břichomluvectví po dobu 3 směn.', 'Vlastnost: charizma; Obtížnost: těžká; Ověřování: Každá věta, nebo jednou za směnu', TRUE),
('Etiketa', 'dovednost', 'jedná se o znalosti jak se chovat ve společnosti, zásady stolování v urozené společnosti, jak koho pozdravit, v jakém pořadí apod. Fatální úspěch: Postava perfektně zvládá všechny společenské nuance. Nemusí až do konce události ověřovat. Úspěch: Postava správně reaguje a koná, jak se sluší a patří. Neúspěch: Postava neodhadla situaci a způsobila faux-pas. Fatální neúspěch: Postava zareagovala naprosto nevhodně. Někoho urazila. Je vyhozena z večírku, společensky se znemožnila apod.', 'Vlastnost: charizma; Obtížnost: lehká; Ověřování: Při každé společenské události, nebo složité situaci vyžadující správné sociální reakce.', TRUE),
('Handlování', 'dovednost', 'Fatální úspěch: Postava vyhandlovala slevu ve výši 20%. Úspěch: Postava vyhandlovala slevu ve výši 10% Neúspěch: Postava nezískala žádnou slevu. Fatální neúspěch: Postava obchod naprosto nezvládla. Při koupi bude zboží o 30% dražší. Při prodeji dostane pouze polovinu.', 'Vlastnost: charizma; Obtížnost: střední; Ověřování: Každý uzavíraný obchod', TRUE),
('Herectví', 'dovednost', 'Roli si musí postava aspoň připravit v hlavě, když nemá možnost roli nastudovat. Minimání čas je okolo 10 kol. Lze takto předstírat opilectví, bláznovství či že je dočista někým jiným. Zde pomohou převleky, má li je k dispozici. Jakmile někdo postavě uvěří její roli, bude ji věřit dokud v ní postava setrvá, nebo si znovu hází proti pasti další den, co se s ní setká. Fatální úspěch: Postava hraje svoji roli, jako by to byl její skutečný život. Další ověřování až za 10 kol. Úspěch: Postava sehrála roli věrohodně. Osoby si hází past Int-12- věří/nevěří Neúspěch: Lidé neuvěřili jeho roli. Fatální neúspěch: Jeho role měla opačný efekt. Lidé se smějí, když by měli plakat apod. Roli neuvěří ani malé dítě. Posměch apod. PJ', 'Vlastnost: charizma; Obtížnost: střední; Ověřování: Každých 5 kol', TRUE),
('Hudba, zpěv', 'dovednost', 'PJ Fatální úspěch: Píseň měla nečekaně pozitivní ohlas. každého chytla za city tím správným způsobem. Ostatní osoby si budou tak nadaného zpěváka/hudebníka vážit a projeví mu svůj vděk. Úspěch: Píseň byla dobrá. Postava je pozvána na pohoštění, na nějakou veselku apod. Neúspěch: Noty se motají jedna přes druhou a neušlo to uším posluchačů. Nenechají jej ani dohrát. Fatální neúspěch: Vybraná píseň nepadla na úrodnou půdu. nechtěně urazil jejich hrdinu/boha apod. Může sklidit pár facek, vyhazov z akce, ale i omezení svobody v podobě několika dní v šatlavě.', 'Vlastnost: charizma; Obtížnost: těžká; Ověřování: Každou skladbu, píseň nebo směnu', TRUE),
('Imitace humanoidních hlasů', 'dovednost', 'Často se používá při vystoupeních či divadelních hrách. Dá se kombinovat s břichomluvectvím. Dobří herci + imitátoři jsou velice cenění. Fatální úspěch: Hlas zní, jako by jím mluvil jeho majitel. je k nerozeznání. Úspěch: Osoby jež dotyčného znají si hází na past Int-11- jestli poznají, že se nejedná o danou osobu. Neúspěch: Hlas zní podobně, ale pokus o napodobení této osoby selhal. Každý kdo dotyčného aspoň jednou slyšel, pozná, že se jedná o podvrh. Fatální neúspěch: Postavě zaskočilo a vyšel z ní jen chrchlavý zvuk. bolí ji hlasivky. napodobovat cizí hlas nemůže příští směnu.', 'Vlastnost: charizma; Obtížnost: těžká; Ověřování: Jednou za větu/slovo', TRUE),
('Lev salónu', 'dovednost', 'Postava se učí číst sociální situace a co nejlépe se adaptovat. Když se postava naučí dovednost na dokonale, zvýší se ji stupeń charizmatu o 2. Nelze navýšit nad 13 +1 Lze se učit vícekrát', 'Vlastnost: charizma; Obtížnost: lehká', TRUE),
('Ovládání povozů, saní jezdeckými nestvůrami', 'dovednost', 'Past na uklidnění již splašeného spřežení je Char - 11- uklidnění/nic Jinak platí stejná pravidla pro povozy a spřežení dle PPP. Lze využít na všechny tvory, kteří nejsou běžní jezdečtí tvorové, různá exotická zvířata i magičtí tvorové. Musí být způsob jak je zapřáhnout. Fatální úspěch: Ověřování až za dvojnásobek běžné doby, pro další manévr si může k hodu připočíst +2. Úspěch: Spřežení táhne jak má. Neúspěch: Spřežení se plaší, odmítá táhnout, sotva se vleče. Fatální neúspěch: Spřežení se pustilo do sebe, ale i do vozky, ničí postroje i vůz, prchají. PJ', 'Vlastnost: charizma; Obtížnost: střední; Ověřování: Každou hodinu, nebo co 10 mil, nebo při manévru.', TRUE),
('Ovládání velkých jezdeckých nestvůr', 'dovednost', 'Fatální úspěch: Zvíře dělá přesně to co má. Při dalším ověřování má postava +2 k hodu. Úspěch: Zvíře dělá to co má. Neúspěch: Zvíře neposlouchá a dělá to co je pro něj výhodné. Fatální neúspěch: Zvíře dělá přesný opak toho co je po něm požadováno, může na jezdce zaútočit, shodit jej apod.', 'Vlastnost: charizma; Obtížnost: střední; Ověřování: Každé 3 hodiny při kroku či klusu. Každých 10 kol při cvalu nebo trysku. Každý pokus při zvláštním manévru.', TRUE),
('Přilákání davu', 'dovednost', 'Fatální úspěch: Přilákal maximálně velký dav, který byl v rámci možností k dispozici. Je velice jednoduché se v něm ztratit. (půl města, celá vesnice apod.) PJ Úspěch: Podařilo se přilákat dav. Neúspěch: Okolí ignoruje snahy postavy. Fatální neúspěch: Záminka proč přilákat dav, se otočí proti postavě.', 'Vlastnost: charizma; Obtížnost: lehká; Ověřování: Jednou', TRUE),
('Svádění', 'dovednost', 'Fatální úspěch: Sváděná osoba je silně vzrušená a bude velmi nakloněná k přáním postavy jenž ji svádí. Může se i zamilovat. Úspěch: Postava je ráda dobývána, dobře se baví a postava je jí sympatická, ale stále si zachovává svůj úsudek. Neúspěch: Svádění se nezdařilo a druhou postavu spíše odradila. Fatální neúspěch: Postava se dotyčnému znechutila. Je vyzvána na souboj pro urážku na cti apod. PJ', 'Vlastnost: charizma; Obtížnost: střední; Ověřování: Jednou za pokus', TRUE),
('Tanec', 'dovednost', 'Fatální úspěch: Postava tančí fantasticky. +2 k hodu na past při dalším partu či písni. Úspěch: Postava tančí dobře. Neúspěch: Postava klopýtá a nemůže udržet tempo. Fatální neúspěch: Postava se natáhla dlouhá, široká na svého tanečního partnera. Je zesměšněna.', 'Vlastnost: charizma; Obtížnost: střední; Ověřování: Každý tanec, nebo jednou za směnu, nebo každý obtížný part', TRUE),
('Učitelství', 'dovednost', 'Fatální úspěch: Nejlepší učitel jakého si žák mohl přát. Doba výcviku je zkrácena o 10% Odměna učiteli ovšem náleží jako při standardní době a možná ještě něco navíc. Úspěch: Výcvik proběhl dle pravidel. Neúspěch: Nedaří se vysvětlit nové znalosti. Výcvik bude trvat o 15% déle. Dobu navíc učitel nedostane proplacenou. Fatální neúspěch: Uprostřed výcviku to žák vzdal a šel hledat jiného učitele. Učitel nedostane zaplaceno a ještě bude muset vrátit to, co již dostal.', 'Vlastnost: charizma; Obtížnost: střední; Ověřování: Jednou za přestup', TRUE),
('Vynucení přiznání', 'dovednost', 'Nejedná se o fyzické mučení postavy za účelem zjištění informací. Jedná se o psychický nátlak za účelem zmatení cíle a vytáhnutí informací třeba i mimoděk. Fatální úspěch: Postava zapůsobila na slabé místo dotazovaného. Nemusí příští směnu ověřovat. Úspěch: Postava dostala pravdivou odpověď. Neúspěch: Dotazovaný zamlčuje, lže.. Fatální neúspěch: Dotazovaný krmí postavu falešnými informacemi, ale postava je považuje za čistou pravdu. PJ', 'Vlastnost: charizma; Obtížnost: střední; Ověřování: každá otázka', TRUE),
('Vypravěčství', 'dovednost', 'Lze takto povědět smyšlené příběhy, pohádky apod. Ale sdělit přehledně i skutečné události apod. Nebo pohádky pro děti. PJ Fatální úspěch: Lidé jsou naprosto zaujati příběhem. Rádi pozvou na jídlo, nebo dají nějaké mince, pozvou na událost apod. Úspěch: Postava řekla svůj příběh a ten se líbil. Neúspěch: Postava to zamotala a lidé se ztratili v ději. Fatální neúspěch: Vypravěč Pomotal příběh tak, že ho na sebe někdo vztáhl a ten se urazil. lidé se mu vysmějí, nebo jej vyženou apod.', 'Vlastnost: charizma; Obtížnost: lehká; Ověřování: Při každém příběhu', TRUE),
('Vznešenost elfů', 'dovednost', 'Postava dokáže působit sebevědomě a velice přesvědčivě. Při hodu proti pasti na charizma může postava uplatnit tuto dovednost a navýšit výsledek svého hodu o 1. Naučí li se postava vznešenost elfů na dokonale získá vždy lepší ceny při prodeji i nákupu předmětů. (+-15%)', 'Vlastnost: charizma; Obtížnost: těžká', TRUE),
('Zastrašování', 'dovednost', 'Válečníci ovládají tuto dovednost od 1. úrovně na dokonale. Za každou 10. úroveň získá válečník +1 k hodu na past. Nelze zastrašit nemrtvé, draky a bytosti uvedené jako imunní vůči strachu. Dosah: na dosah zbraně TvT Past: Roz. Char -x- stupeň odolnosti zastrašení/nic Tyto hodnoty se přičítají do hodnoty pasti podle Charizmatu postavy, která zastrašuje. Válečník může jako jediný zastrašovat skupiny protivníků. Čím více, tím těžší. Přesnou povahu zastrašování a jeho šance rozhoduje PJ. Silně záleží na okolnostech. Zastrašování trvá 2 akce, počítá se jako bojová činnost. Pokud nepadl fatální neúspěch, lze se znovu pokusit o zastrašení za 3 kola. Fatální úspěch: Zastrašený nepřítel utíká nejvyšší možnou rychlostí, co nejpřímější cestou od postavy jež ho zastrašila po dobu 4 kol. Po tuto dobu má +3 k iniciativě. Úspěch: Vystrašená osoba bude utíkat co nejrychleji pryč po dobu 2 kol. Po tuto dobu má +2 k iniciativě. Neúspěch: Postava zůstala vůči pokusus o zastrašení netečná. Fatální neúspěch: Postava se vysmála pokusu o její zastrašení. Při boji s tím kdo ji zastrašoval má +1 k Úč. a Oč. A stejná osoba ji ten den již nemůže zastrašit.', 'Vlastnost: charizma; Obtížnost: střední; Ověřování: Každý pokus o zastrašení', TRUE),
('Záměrná provokace', 'dovednost', 'Silně záleží na okolnostech, rozhoduje PJ Fatální úspěch: Postava dloubla do toho správného místa dotyčného rozzuřila do běla. Bezhlavě se bude snažit smýt potupu jež mu dotyčný způsobil. Úspěch: Postava vyprovokovala protivníka a ten se jí, ideálně ihned, nebo v budoucnu bude chtít pomstít. Neúspěch: Provokace vyšla nazmar. Cíl opáčil postavě ještě peprněji. Fatální neúspěch: Postava nezvládla provokaci a sama se stala terčem posměchu širokého okolí.', 'Vlastnost: charizma; Obtížnost: střední; Ověřování: Jednou za pokus', TRUE),
('Zvuky ptáků', 'dovednost', 'Slouží hlavně jako prostředek signalizace. Aby se postava mohla učit zvuky ptáka, musí jej mít k dispozici živého po dobu výcviku. Nauči li se 2 druhy, tak třetí a další jsou již lehká obtížnost. postava netuší co říká, jen imituje podobu zvuku. Fatální úspěch: I samotní ptáci budou reagovat na zvuky, jako by byly od skutečného jedince. Úspěch: Zvuk zní jako pták. Hraničáři mají 15% šanci poznat že se jedná imitaci. Neúspěch: Zvuk se nepovedl a vyšel jen podivný skřek. Fatální neúspěch: Postava se zhluboka nadechla při pokusu o co nejlepší imitaci, ale zaskočilo ji a příští 2 kola lape po dechu, kašle apod. PJ', 'Vlastnost: charizma; Obtížnost: střední; Ověřování: Každý zvuk', TRUE),
('První pomoc', 'dovednost', 'Každá směna ošetřování je 1 bod únavy. Pokud bude udržovat při životě, pak každá směna jsou 3 body únavy. Může ošetřovat pouze osoby se standartní fyziologii velikosti A-C (člověk, trpaslík, tiefling,) Pro každé léčení potřebuje základní vybavení. 1 dávka = 1 mince, stojí 3md Každý vyléčený život vyžaduje 1 dávku. Každá směna oddalování smrti vyžaduje dávky 3. Krvácení 4.st. (obvaz, nit, zásyp apod.)', 'Vlastnost: ½ inteligence, ½ obratnost; Obtížnost: střední; Ověřování: Neověřuje se', TRUE),
('Runový obránce', 'dovednost', 'Lze vykrývat pouze kouzla, která míří přímo na postavu, nelze na plošná. (blesky apod.) nefunguje na psychická. Fatální úspěch: Postava vykryla až 20 násobek KZ štítu a ten je poškozen za 10 násobek KZ. Úspěch: Postava vykryla 15 násobek KZ štítu a ten je poškozen za stejné množství. Neúspěch: Kouzlo prošlo skrz. Fatální neúspěch: Kouzlo prorazilo slabinu ve štítu. Ten je poškozen za 50 násobek jeho KZ a postava je zraněna v plné míře.', 'Vlastnost: ½ inteligence, ½ obratnost; Obtížnost: střední; Ověřování: Každé bránění se štítem', TRUE),
('Scholastik', 'dovednost', 'Postava při dalším rozdělování profibodů, získá další, podle stupně dovednosti. Lze se naučit pro všechny atributy, ale pouze jednou.', 'Vlastnost: Síla, Obratnost, Odolnost, Inteligence, Charizma; Obtížnost: lehká', TRUE);
-- =====================================================================
-- ČÁST 12: ROZŠÍŘENÁ PRAVIDLA DOVEDNOSTÍ (h1809+, homebrew) — rámcové
-- řemeslné/přírodní dovednosti. Jednotlivé recepty na dryáky/pokrmy/
-- lektvary a nové předměty/zbraně/zbroje/legendární kovy (h1812+ detaily,
-- h2055+) jsou MIMO ROZSAH této tabulky (patří do `lektvary`/`predmety`).
-- Tyto dovednosti nejsou vázané na konkrétní povolání.
-- =====================================================================

INSERT INTO zvlastni_schopnosti (nazev, druh, popis, mechanika) VALUES
('Bylinkaření', 'dovednost', 'Třístupňové umění práce s bylinami, každý stupeň lze naučit až po zdokonalení předešlého: Bylinkář (lehká — hledání bylin v divočině a příprava dryáků, zvládá suroviny třídy 1-3), Lékárník (střední — výroba specializovaných přírodních léků a preparátů) a Botanik (těžká — vlastní pěstování bylin a unikátní tinktury). Suroviny se dělí do 7 tříd kvality (0-6) dle biomu původu; vyšší třída nahrazuje více kusů nižší třídy (třída 6 = 2× třída 5 = 4× třída 4 = 8× třída 3 = 16× třída 2 = 20× třída 1 = 40× třída 0). Příprava dryáku vyžaduje plné soustředění, past dle receptu upravená stupněm dovednosti; denní limit preparátů bez vedlejších účinků = bonus za Odolnost (min. 2), nutný odstup 24 hodin mezi dávkami.', 'Bylinkář/Lékárník/Botanik: lehká/střední/těžká; 7 tříd kvality surovin (0-6); recepty jednotlivých dryáků mimo rozsah (viz `lektvary`)'),
('Vaření (rozšířené)', 'dovednost', 'Třístupňové kuchařské umění, každý stupeň vyžaduje zdokonalení předešlého: Vaření (lehká — recepty základní/pokročilé úrovně), Mistrovské vaření (střední — mistrovské recepty) a Legendární vaření (těžká — legendární recepty). Vyžaduje koření/byliny/sůl v ceně cca 10 md (0,1 mince na dávku).', 'Vaření/Mistrovské vaření/Legendární vaření: lehká/střední/těžká; jednotlivé recepty mimo rozsah'),
('Řezníkův almanach', 'dovednost', 'Řemeslná znalost speciálních (cenných) surovin z poražených tvorů; almanach lze koupit ve větším městě (10 zl, 40 mn) a rychle se vrátí investicí do vyšších výtěžků při zpracování kořisti.', 'Almanach 10 zl/40 mn; rozšiřuje hodnotu vytěžených surovin z kořisti'),
('Vinař a palič', 'dovednost', 'Alchymisté (a další postavy) pálí alkohol z různých surovin pomocí destilační aparatury — používaný i jako základ pro vlastní lektvary, čímž šetří náklady. Existují 3 úrovně paličství, každá vyžaduje jinou vlastnost/přístup.', 'Tři úrovně paličství (různé vlastnosti); konkrétní recepty destilátů mimo rozsah'),
('Sklízení tvorů', 'dovednost', 'Umožňuje efektivně získávat suroviny z poražených nestvůr i těžit minerály/suroviny na výrobu předmětů či směnu. Vyžaduje sílu i psychickou odolnost (nezkušený sklízeč riskuje zmrzačení či šílenství). Musí začít co nejdříve po smrti tvora — po 1 hodině je bez využitelné esence. 1 pokus = 30 minut, max. 2 pokusy na jednom tvoru.', 'Max. 2 pokusy/tvor, 30 minut/pokus; esence mizí do 1 hodiny od smrti tvora'),
('Inženýr-mechanik', 'dovednost', 'Vyžaduje předchozí dokonalé ovládnutí stavby obléhacích strojů. Inženýr umí zmenšovat obléhací zařízení beze ztráty účinnosti a s pomocníky navrhovat a stavět zcela nová zařízení.', 'Vlastnost Int+Obr; obtížnost těžká; podmínka: dokonalá znalost stavby obléhacích strojů'),
('Střelba – krátké a dlouhé palné zbraně', 'dovednost', 'Homebrew dovednost pro použití raných palných zbraní (pistole/muškety a příbuzné), mimo standardní výbavu povolání dle jádra pravidel.', 'Detaily mechaniky střelby a konkrétní zbraně mimo rozsah tohoto importu (viz `predmety`) -- TODO: doplnit detailní mechaniku'),
('Lékařství', 'dovednost', 'Speciální dovednost přístupná jen pasivním společníkům postav (nebo poskytovaná NPC) — nemagické ošetřování ran a udržování raněných při životě.', 'Přístupná jen pasivním společníkům/NPC; nemagická léčba a stabilizace raněných');

INSERT INTO schopnost_povolani (schopnost_id, povolani_id)
SELECT s.id, p.id FROM zvlastni_schopnosti s, povolani p
WHERE s.nazev='Inženýr-mechanik' AND p.nazev='Pyrofor';
-- Pozn.: výše uvedený vztah Inženýr-mechanik -> Pyrofor je jen předpoklad
-- (obléhací stroje bývají v DrD spojené s pyroforem) -- OVĚŘIT proti zdroji,
-- není v přepisu výslovně uvedeno. Ostatní dovednosti v této části jsou
-- obecné a záměrně bez vazby na povolání.

-- =====================================================================
-- SHRNUTÍ POKRYTÍ A ZNÁMÉ MEZERY (k doplnění v navazující práci)
-- =====================================================================
--
-- POKRYTO (s mechanikou, u vybraných schopností i past/efekty):
--   * Válečník, Bojovník, Šermíř, Trollobijec — kompletně (mimo finty
--     jako takové, ty jsou v `finty`).
--   * Hraničář, Druid, Chodec — všechny schopnosti/dovednosti mimo
--     kouzelnický katalog (spell listy jsou v `kouzla`).
--   * Alchymista (Odolnost vůči jedům, Vidění magenergie, Lučba) a
--     Pyrofor (Pyroforova pravděpodobnost magenergie, Líčení pastí
--     s pastmi Drtivá/Šipková/Výbušná past, Pokročilé protijedy).
--     Theurg NENÍ pokryt (jeho obsah je téměř výhradně astrální
--     sféry/elementálové = kouzla/nestvůry, mimo rozsah).
--   * Kouzelník — obor Mág: Podrobování, Mentální souboj (+ rozšíření),
--     Vysávání/Předávání životů, Ovládnutí, Drakomluva, Základní síla,
--     Posílení kouzel, Odolnost proti psychickým kouzlům, Pomocná
--     kouzla. Čaroděj a homebrew větve (Nekromant, Pyromancer,
--     Cryomancer) NEJSOU pokryty — jejich obsah je téměř výhradně
--     kouzelný katalog.
--   * Zloděj, Lupič, Sicco — kompletně, včetně pastí pro Zabití,
--     Klíč, Šifrování a Určení hodnoty pokladů.
--   * Homebrew: Tulák, Bard (rámec), Pamětník (rámec), Krotitel,
--     Stopař stínů + Lovec stínů, Novic + Erythen (vč. pastí pro
--     Osm bran a Rychlé tasení), Mystik (výběr), Paladin (výběr).
--   * Obecná pravidla dovedností (h1693-h1808) — VŠECH ~106
--     dovedností (Síla/Obratnost/Odolnost/Inteligence/Charizma i
--     kombinované), každá se 4stupňovou škálou výsledku.
--   * Rozšířená pravidla dovedností (h1809+) — rámcové řemeslné
--     dovednosti (Bylinkaření, Vaření, Řezníkův almanach, Vinař a
--     palič, Sklízení tvorů, Inženýr-mechanik, Střelba palné zbraně,
--     Lékařství); jednotlivé recepty/produkty mimo rozsah.
--
-- NEDOKONČENO / TODO PRO NAVAZUJÍCÍ PRÁCI (šířka byla upřednostněna
-- před hloubkou dle zadání, ale čas na tento import nestačil na
-- vyčerpání celého homebrew bloku h693-h1809+):
--   * Warlock (druhá větev Stopaře stínů, h1009-h1068) — nezpracováno.
--   * Kněz (obor Novice, h1166-h1229) — nezpracováno.
--   * Panoš a Rytíř (h1230-h1261), Zealot (h1325-h1343) — nezpracováno,
--     jen Paladin byl vybrán jako explicitně požadovaný.
--   * Střelec + Lučištník + Mechanik (h1344-h1374) — nezpracováno.
--   * Divoch + Pán šelem + Velký lovec (h1375-h1412) — nezpracováno.
--   * Šaman + Ur-shak + Elemancer + Tempest (h1413-h1472) — nezpracováno.
--   * Upír, Dlak, Krvavý poutník (h1473-h1599) — nezpracováno (nejisté,
--     zda jde o povolání nebo rasové/transformační šablony — OVĚŘIT).
--   * Trpasličí runy (jednotlivé Runa Oceli/Odhalení/Hromu/Volnosti/
--     Síry/Zničení/Zášti/Vody/Skoku/Oběti/Lékárníka/Slunce, h871-h902)
--     — pouze rámcová schopnost "Runová magie" u Pamětníka, jednotlivé
--     runy mají formát kouzel a patří do `kouzla`.
--   * Bardovy jednotlivé písně (h715-h793, cca 80 položek) a Pamětníkovy
--     ságy/verše/slova/přísahy (h808-h902) — mimo rozsah (kouzla),
--     zachyceny jen obalové mechaniky (komponenty, únava, učení).
--   * Krotitelovy jednotlivé aspekty a povely bičem (h906-h929, h932-933)
--     — mimo rozsah (kouzla), zachyceny jen torna/drahokamy/výcvik/
--     odhad/ochočování.
--   * Novicovy/Erythenovy jednotlivé disciplíny placené vírou
--     (h1079-h1089, h1100-h1110 kromě Osm bran a Rychlého tasení)
--     a Mystikova jednotlivá "Přání"/kouzla (h1127+) — mimo rozsah.
--   * Paladinova jednotlivá "Přání" (h1270-h1306) — mimo rozsah, kromě
--     rámcové mechaniky Síla víry a Aury.
--   * "Boj beze zbraně" jako obecné jádrové pravidlo (mimo Lupičovu
--     a Erythenovu specializovanou verzi, které jsou pokryty) —
--     nebylo v prostudované části zdroje nalezeno jako samostatná
--     obecná kapitola; možná je součástí základního soubojového
--     systému (h1604+) mimo prostudovaný rozsah -- OVĚŘIT.
--   * `pasti`/`efekty` byly vytvořeny jen pro vybrané "vlajkové"
--     schopnosti explicitně zmíněné v zadání (Zastrašení, Ochromení/
--     stavové efekty u Trollobijce, Změna v berserkra, Sražení a
--     odhození, Odkopnutí, Drapnutí, Zabití, Klíč, Šifrování, Osm
--     bran, Rychlé tasení, Podrobování/Ovládnutí u Mága, Drakomluva,
--     Líčení pastí pyrofora, Snímání kletby chodce, Líčení loveckých
--     pastí). U mnoha dalších schopností se zápis pasti (je-li ve
--     zdroji) nachází přímo v poli `popis`/`mechanika` v textové
--     podobě, ale formální řádek v `pasti` nebyl vytvořen kvůli
--     časové prioritě šířky pokrytí.
--   * Několik hodnot v mechanice je ponecháno jako TODO/Nejasné přesně
--     dle zdroje (viz jednotlivé komentáře u schopností) — jde o
--     stejné nejasnosti, jaké eviduje kontrolni-seznam-neuplnych-mist.md
--     (např. Runa Oceli II/III odkazující na neexistující "Runu
--     ochrany", zdvojené "Obr." u Rychlého tasení, "Roz. Char" u
--     Zastrašení, chybějící dosah u Postoje černého jeřába, nejasné
--     přiřazení efektů u pasti Vržení a Vrhu bojovníka).
--
-- DOPORUČENÍ: než se tento soubor spustí proti produkční databázi,
-- ověřit přesné názvy `povolani`, na které odkazují subquery výše
-- (zejména homebrew větve typu 'Trollobijec', 'Lovec stínů', 'Erythen',
-- 'Mág' coby samostatný řádek odvozený od Kouzelníka), a případně
-- doladit dle skutečného obsahu tabulky `povolani`.
-- =====================================================================

SET FOREIGN_KEY_CHECKS = 1;
-- =====================================================================
-- Data: Kouzla (seznamy_kouzel, kouzla, kouzlo_obor_magie, kouzlo_efekty)
-- Zdroj: DrD PPZ/PPP/PPE (jádrová pravidla) + domácí homebrew rozšíření
-- (viz artifact-0bb18a6e... HTML, sekce h174-h1600 'hrac' část).
--
-- Cizí klíče vždy poddotazem (SELECT id FROM ... WHERE nazev=...).
-- `povolani` a `obory_magie` NEJSOU touto dávkou plněny/měněny — jen odkazovány.
-- Pokud subquery na `povolani` nenajde odpovídající řádek (souběžný skript
-- ještě nevložil dané povolání), INSERT...SELECT pro daný seznam kouzel
-- se tiše přeskočí (0 řádků) — to je vlastnost MySQL, ne chyba tohoto souboru;
-- v takovém případě je potřeba tento soubor spustit znovu až po naplnění
-- tabulky `povolani`.
-- =====================================================================

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- ---------------------------------------------------------------------
-- 0. Úklid DEMO řádků ze schématu (nahrazeny ostrým obsahem níže)
-- ---------------------------------------------------------------------
DELETE k FROM kouzla k JOIN seznamy_kouzel s ON s.id = k.seznam_kouzel_id
  WHERE k.nazev = 'Bábelská rybka' AND s.nazev = 'Kouzla mága PPP';
DELETE FROM seznamy_kouzel WHERE nazev = 'Kouzla mága PPP' AND popis LIKE '%DEMO%';

-- ---------------------------------------------------------------------
-- 1. EFEKTY + PASTI — jen pro kouzla s jasným efektem past->stav
-- ---------------------------------------------------------------------
INSERT INTO efekty (nazev, typ, cil, mechanika_aplikace, trvani, tooltip_text) VALUES
('Spánek', 'debuff', 'akceschopnost', 'jednorazove', 'dle kouzla', 'Postava upadla do kouzelného spánku a je bezbranná; probudí ji jen zlom kouzlo / rozptyl kouzla nebo uplynutí doby trvání.'),
('Ochromení', 'debuff', 'akceschopnost', 'jednorazove', 'dle kouzla', 'Postava je magicky ochromena a nemůže konat žádné akce ani se bránit.');

INSERT INTO pasti (vlastnosti, obtiznost, efekt_uspech_id, efekt_neuspech_id, poznamka) VALUES
('Roz+Odl', '8', NULL, (SELECT id FROM efekty WHERE nazev='Spánek'),
 'AUTO:past_spanku_ppp -- Kouzlo spánku (Šena), h393: neúspěch = spánek po dobu trvání kouzla (5-10 hodin).'),
('Roz+Odl', '5', NULL, (SELECT id FROM efekty WHERE nazev='Spánek'),
 'AUTO:past_usni_ppp -- Usni (Tašem), h436: past zapsána ve zdroji jako "Roz+Odl~5~0", 0 = žádný efekt při úspěchu; neúspěch = hluboký spánek na 2-7 směn (dle popisu kouzla). -- TODO ověřit proti skenu (nestandardní zápis pasti)'),
('Int / Char+Odl', '5', NULL, (SELECT id FROM efekty WHERE nazev='Ochromení'),
 'AUTO:past_zadrz_osobu -- Zadrž osobu (Mystik/Kněz, homebrew): zdroj zapisuje past nejasně jako "Int. -5- Char/Odol ochromení/nic" (mystik) resp. "Int. ~5~ Char/Odol ochromení na 1k6 kol/nic" (kněz) — není jisté, zda Int. je útočníkova vlastnost a Char/Odol obráncova, viz popis kouzla. -- TODO ověřit proti skenu');

