-- ---------------------------------------------------------------------
-- 3. KOUZLA
-- ---------------------------------------------------------------------
-- Kouzla mága PPZ / Kouzelník (27 kouzel)
INSERT INTO kouzla (nazev, seznam_kouzel_id, uroven_kouzla, cena_magenergie, dosah, doba_seslani, doba_trvani, typ_unavy, popis)
SELECT v.nazev, s.id, v.uroven, v.mag, v.dos, v.sesl, v.trv, v.un, v.pop
FROM (
  SELECT 'Dým' AS nazev, NULL AS uroven, '1 mag/2 sáhy (rovná stěna)…' AS mag, '12 sáhů' AS dos, '1 kolo' AS sesl, '1–6 směn' AS trv, 'vycerpavajici' AS un, 'Magenergie (přesně): 1 mag/2 sáhy (rovná stěna) nebo 1 mag/3 krychlové sáhy (nepravidelná). Původní/magické jméno: Fumideó. Rozsah: stěna 3 sáhy vysoká. Hustá šedá kouřová clona; nejedovatá, dá se v ní dýchat. Ultrasluchem lze proniknout, infravidění nespolehlivé (dým je mírně teplý).' AS pop
  UNION ALL SELECT 'Hyperprostor' AS nazev, NULL AS uroven, '4 nebo 6 magů' AS mag, '0' AS dos, '1 kolo' AS sesl, 'ihned' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Hye archom. Rozsah: koule o poloměru 60 sáhů. Teleportace kouzelníka (a věcí/tvorů velikosti A0, které nese) do 60 sáhů. Zná-li přesně cílové místo, stačí 4 magy, jinak 6 (jen směr a vzdálenost). Přemístění do pevné/husté látky zraní za 1k6 životů za každých 10 magů.' AS pop
  UNION ALL SELECT 'Hypnóza' AS nazev, NULL AS uroven, 'Životaschopnost × 2' AS mag, '5 sáhů' AS dos, '1 kolo' AS sesl, 'podle dodané magenergie' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Sómnos. Past: Int+Roz ~ 6 ~ 0. Rozsah: 1 humanoidní postava. Ovládá humanoidního tvora jednoduchými instrukcemi (splní i nebezpečný, ale ne sebevražedný příkaz). Lze uložit jeden posthypnotický příkaz (+10 magů).' AS pop
  UNION ALL SELECT 'Levitace' AS nazev, NULL AS uroven, '3 magy první směna, 1 mag…' AS mag, 'dotyk' AS dos, '3 kola' AS sesl, 'podle dodané magenergie' AS trv, 'vycerpavajici' AS un, 'Magenergie (přesně): 3 magy první směna, 1 mag každá další. Původní/magické jméno: Planere. Rozsah: 1 tvor. Volný pohyb jako ve stavu beztíže, zátěž do 2 000 mn, pád rychlostí 1 sáh/kolo.' AS pop
  UNION ALL SELECT 'Magický štít' AS nazev, NULL AS uroven, '2 magy první kolo, 1 mag…' AS mag, '0' AS dos, '1 kolo' AS sesl, 'dle dodané magenergie' AS trv, 'vycerpavajici' AS un, 'Magenergie (přesně): 2 magy první kolo, 1 mag každé další. Původní/magické jméno: Magomágen. Rozsah: oblast před kouzelníkem. Bariéra před kouzelníkem: poloviční šance zásahu bleskem, KZ +9 proti dračímu dechu, +7 proti střelným/vrhacím zbraním, +5 proti útokům tváří v tvář — jen zepředu (a penalizuje vlastní útoky týmž způsobem).' AS pop
  UNION ALL SELECT 'Mágův velký mix' AS nazev, NULL AS uroven, '(Životaschopnost × 2) + 1' AS mag, '5 sáhů' AS dos, '2 kola' AS sesl, 'ihned' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Magomegamix. Past: Roz ~ 8 ~ !. Rozsah: 1 nestvůra. Rozloží nestvůru (i předměty/tvory A0 u sebe) na hromádku bílkovinného rosolu.' AS pop
  UNION ALL SELECT 'Melenina krása' AS nazev, NULL AS uroven, '6 magů za kolo' AS mag, 'dotyk' AS dos, '1 kolo' AS sesl, 'podle dodané magenergie' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Melenebeau. Rozsah: 1 postava. Zvýší charisma na 21; v 1/6 případů naopak klesne na 1 (hoď 1k6: 1–5 = zvýšení, 6 = snížení).' AS pop
  UNION ALL SELECT 'Metamorfóza' AS nazev, NULL AS uroven, '11 magů za směnu' AS mag, '0' AS dos, '1 kolo' AS sesl, 'podle dodané magenergie' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Aloiósis. Rozsah: 1 tvor do 8 sáhů. Kouzelník se promění v jinou živou bytost (max. ±1 třída velikosti, inteligence > 1); získá její vlastnosti (síla, obratnost, odolnost, charisma) a anatomické schopnosti, ale ne magicky získané vlastnosti (lykantropova odolnost, kouzla apod.) ani rasové zvláštní schopnosti (pokud rasa jiná). Zachovává inteligenci, životy a úroveň.' AS pop
  UNION ALL SELECT 'Modré blesky' AS nazev, NULL AS uroven, '3 magy první, 2 magy každý…' AS mag, '10 sáhů' AS dos, '1 kolo' AS sesl, 'ihned' AS trv, 'vycerpavajici' AS un, 'Magenergie (přesně): 3 magy první, 2 magy každý další. Původní/magické jméno: Artak bárak. Rozsah: 1 nestvůra. Automaticky zasáhne zvolenou nestvůru, 1–6 životů za blesk; více blesků musí mířit na stejný cíl.' AS pop
  UNION ALL SELECT 'Montyho čardáš' AS nazev, NULL AS uroven, '(Životaschopnost + 1) za kolo' AS mag, '10 sáhů' AS dos, '1 kolo' AS sesl, 'podle dodané magenergie' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Montymero. Past: Roz ~ 7 ~ 0. Rozsah: až 3 nestvůry (int. 5+) v kouli 5 sáhů. Donutí neuspěvší nestvůry zběsile tančit (nemohou útočit/bránit se, ztráta 1 životu/kolo).' AS pop
  UNION ALL SELECT 'Najdi neviděné' AS nazev, NULL AS uroven, '7 magů první kolo, 6 každé…' AS mag, '8 sáhů' AS dos, '2 kola' AS sesl, 'podle dodané magenergie' AS trv, 'vycerpavajici' AS un, 'Magenergie (přesně): 7 magů první kolo, 6 každé další. Původní/magické jméno: Heurískon avidia. Rozsah: koule o poloměru 2 sáhy. Zviditelní slabší neviděné (lačnou hrůzu) v pravé, ale nepřesné podobě.' AS pop
  UNION ALL SELECT 'Nebezpečné ovoce' AS nazev, NULL AS uroven, '3 magy za kus' AS mag, NULL AS dos, '3 kola' AS sesl, 'ihned' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Mala mála. Vytvoří výbušné hrušky (5–10 životů při manipulaci nebo po 5–10 směnách samovolně).' AS pop
  UNION ALL SELECT 'Neviditelnost' AS nazev, NULL AS uroven, '7 magů' AS mag, 'dotyk' AS dos, '2 kola' AS sesl, 'viz popis' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Avidius. Rozsah: 1 tvor. Postava (a věci u sebe) se stane neviditelnou; zůstává neviditelná, dokud neútočí, nekouzlí, nepoužije psychickou schopnost nebo nepromluví. Detekovatelná krollem/hobitem, zvukem, pohybem předmětů.' AS pop
  UNION ALL SELECT 'Oheň' AS nazev, NULL AS uroven, '2 magy za sáh' AS mag, 'podle magenergie' AS dos, '1 kolo' AS sesl, 'max. 1–5 směn' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Igneum. Rozsah: půl sáhu. Malý oheň svítící do 7 sáhů, zapaluje hořlaviny; past Obr ~ 5 ~ –/2-7 pro procházející. Trvání závisí na soustředění (soustředěn = 1–5 směn, jinak zhasne za 1–5 kol).' AS pop
  UNION ALL SELECT 'Ohnivý déšť' AS nazev, NULL AS uroven, '35 nebo 50 magů' AS mag, '20 sáhů' AS dos, '4 kola' AS sesl, '1 kolo' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Nefelé ignea. Rozsah: kruh o poloměru 5 sáhů. Vytvoří černý mrak, ze kterého sprchne ohnivý déšť: 1–6 životů/čtvereční sáh (člověk 1–6, kůň 3–18, drak 50–300). Nedostupné pro postavy na 5. úrovni PPZ — uvedeno jako příklad pro vyšší úrovně.' AS pop
  UNION ALL SELECT 'Protoplazma' AS nazev, NULL AS uroven, 'Životaschopnost + 1' AS mag, '10 sáhů' AS dos, '2 kola' AS sesl, '2-7 kol' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Prorep tohabet. Past: Obr ~ 8 ~ 0. Rozsah: 1 nestvůra. Zpomalí nestvůru na poloviční počet útoků/obran po 2–7 kol. Opakované seslání trvání sčítá, nezvyšuje efekt.' AS pop
  UNION ALL SELECT 'Rychlost' AS nazev, NULL AS uroven, '2 magy za kolo' AS mag, 'dotyk' AS dos, '1 kolo' AS sesl, 'podle dodané magenergie' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Hyperio. Rozsah: 1 tvor. Dvojnásobná rychlost pohybu/útoků/obran. Sčítá se s dalším sesláním nebo lektvarem rychlosti (trvání, ne efekt).' AS pop
  UNION ALL SELECT 'Sugesce' AS nazev, NULL AS uroven, '(Životaschopnost × 2) + 5' AS mag, '10 sáhů' AS dos, '2 kola' AS sesl, '1 směna' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Intrinsico. Past: Int ~ 6 ~ 0. Rozsah: max. 3 postavy. Vsugeruje pocit (strach, únava, vztek, bolest) na dálku, bez nutnosti vidět/slyšet cíl.' AS pop
  UNION ALL SELECT 'Světlo' AS nazev, NULL AS uroven, '2 magy za sáh poloměru' AS mag, '0' AS dos, '1 kolo' AS sesl, '1–5 směn' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Luxmen. Rozsah: koule podle magenergie. Dokonale osvětlí okolí, pohybuje se s kouzelníkem.' AS pop
  UNION ALL SELECT 'Ticho' AS nazev, NULL AS uroven, '3 magy (5 magů) za sáh…' AS mag, '0' AS dos, '1 kolo' AS sesl, '1–5 směn' AS trv, 'vycerpavajici' AS un, 'Magenergie (přesně): 3 magy (5 magů) za sáh poloměru. Původní/magické jméno: Silenció. Rozsah: koule podle magenergie. Dokonalé ticho na území (vyřazuje i krollův ultrasluch); za 5 magů jsou zvuky zevnitř slyšet tlumeně navenek.' AS pop
  UNION ALL SELECT 'Tma' AS nazev, NULL AS uroven, '4 magy (6 magů) za sáh…' AS mag, '0' AS dos, '1 kolo' AS sesl, '1–5 směn' AS trv, 'vycerpavajici' AS un, 'Magenergie (přesně): 4 magy (6 magů) za sáh poloměru. Původní/magické jméno: Obscurum. Rozsah: koule podle magenergie. Dokonalá tma (vyřazuje trpasličí infravidění); za 6 magů je uvnitř jen šero jako od malé pochodně a infravidění funguje.' AS pop
  UNION ALL SELECT 'Vodní dech' AS nazev, NULL AS uroven, '3 magy za směnu' AS mag, 'dotyk' AS dos, '3 kola' AS sesl, 'podle dodané magenergie' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Aqua spiro. Rozsah: 1 tvor. Umožní dýchat pod vodou (ale ne mluvit).' AS pop
  UNION ALL SELECT 'Zaklep' AS nazev, NULL AS uroven, '6 magů' AS mag, '20 sáhů' AS dos, '2 kola' AS sesl, 'ihned' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Taptap. Rozsah: 1 dveře. Otevře libovolný zámek nebo kouzlo zamkni/čarodějův zámek.' AS pop
  UNION ALL SELECT 'Zamkni' AS nazev, NULL AS uroven, '4 magů' AS mag, '2 sáhy' AS dos, '2 kola' AS sesl, '2–12 směn' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Linol. Past: Sil ~ +8 ~ 0. Rozsah: 1 vchod. Zamkne vstup (dveře, truhla, okovy) opatřený zámkem/závorou na 2–12 směn; otevřít lze zaklepem nebo násilím. Nelze fyzicky poškodit zamčené dveře.' AS pop
  UNION ALL SELECT 'Zelené blesky' AS nazev, NULL AS uroven, '4 magy první, 3 magy každý…' AS mag, '10 sáhů' AS dos, '1 kolo' AS sesl, 'ihned' AS trv, 'vycerpavajici' AS un, 'Magenergie (přesně): 4 magy první, 3 magy každý další. Původní/magické jméno: Járak bárak. Rozsah: 1 nestvůra. Zranění 2–12 životů za blesk; 80% šance zásahu (společná pro všechny blesky).' AS pop
  UNION ALL SELECT 'Zenerova karta' AS nazev, NULL AS uroven, '7 magů za obláček' AS mag, '10 sáhů' AS dos, '2 kola' AS sesl, '1–3 kola' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Zenerchart. Past: Int ~ 4 ~ 0. Rozsah: tvorové o celkové životaschopnosti 2–4. Fixuje tvory (int. > 1) pohledem na magické karty; neúčinkuje na nemrtvé a neviděné. Útok na fixovaného = útok na vyřazenou postavu.' AS pop
  UNION ALL SELECT 'Zlom kouzlo' AS nazev, NULL AS uroven, 'magenergie lámaného kouzla + 6' AS mag, 'dotyk' AS dos, '10 kol' AS sesl, 'ihned' AS trv, NULL AS un, 'Původní/magické jméno: Frangoetia. Rozsah: 1 tvor. Odstraní účinky psychického kouzelnického kouzla (sugesce, hypnóza). Základní šance 50 %, +5 % za každou úroveň nad kouzelníkem, který kouzlo seslal (a naopak −5 % za nižší úroveň).' AS pop
) v
JOIN seznamy_kouzel s ON s.nazev = 'Kouzla mága PPZ'
JOIN povolani p ON p.id = s.povolani_id AND p.nazev = 'Kouzelník';

-- Kouzla mága PPP / Kouzelník (115 kouzel)
INSERT INTO kouzla (nazev, seznam_kouzel_id, uroven_kouzla, cena_magenergie, dosah, doba_seslani, doba_trvani, typ_unavy, popis)
SELECT v.nazev, s.id, v.uroven, v.mag, v.dos, v.sesl, v.trv, v.un, v.pop
FROM (
  SELECT 'Bábelská rybka' AS nazev, NULL AS uroven, '5 magů' AS mag, '0' AS dos, '1 kolo' AS sesl, '3 směny' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Nun bábelí. Rozsah: všechny bytosti v doslechu. Po seslání tohoto kouzla je kouzelník schopen rozumět jakémukoliv jazyku, pokud ho používá nějaká živá myslící bytost (tj. s inteligencí větší než 1). Neumožňuje tedy číst texty v cizích jazycích ani porozumět řeči a zaznamenané kouzlem (například socha kladoucí hádanku). Cizím jazykem však kouzelník nedokáže mluvit nebo psát.' AS pop
  UNION ALL SELECT 'Beranidlo' AS nazev, NULL AS uroven, 'viz níže' AS mag, '5 sáhů' AS dos, '3 kola' AS sesl, NULL AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Ágnuso. Rozsah: 1 dveře. Po seslání tohoto kouzla se libovolné dveře (brána, dvířka) rozpadnou s rachotem v prach. Neexistuje kouzlo, které by mohlo beranidlu odolat. Ovšem kouzlo musí být sesláno na celkovou plochu dveří. Tedy pro bránu se dvěma křídly musí být beranidlo sesláno na obě dvě křídla. Magenergie spotřebovaná na toto kouzlo závisí na velikosti dveří a pro jeden čtvereční sáh a v závislosti na tloušťce v coulech je udává Tabulka dveří. K údajům v tabulce se ještě přičítá magenergie spotřebovaná na jejich zamčení (byla-li jaká). Viz také kouzlo Orxanův zámek a uzamykací kouzla obecně. PŘÍKLAD: PŘÍKLAD: Na dřevěné dveře o rozměrech 2×1 sáh a o tloušťce 5 coulů, které nejsou nijak magicky chráněny, je potřeba 10 (= 2×5) magů.' AS pop
  UNION ALL SELECT 'Bílá střela' AS nazev, NULL AS uroven, '9 magů za každou střelu' AS mag, '120 sáhů' AS dos, '1 kolo' AS sesl, 'ihned' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Churšeláh. Past: Roz ~ 7 ~ ⅓. Rozsah: 15 sáhů. Toto poeticky nazvané kouzlo je jednou z nejúčinnějších zbraní proti magickým tvorům (fantastičtí tvorové by klidně mohli žít i v našem světě – např. elfové, draci, magičtí tvorové byli stvořeni magií ve světě DrD – např. nevidění, nemrtví), ale neúčinkuje na žádné jiné. Podobá se ohnivé kouli: po jeho seslání vyletí z kouzelníkovy ruky střela většího než velká kroupa a ve vzdálenosti do 120 sáhů v místě zvoleném kouzelníkem vybuchne v kouli bílého světla o průměru 15 sáhů. Každý magický tvor uvnitř koule je zraněn za 3–18 životů za každou čtvereční (1 hex na soubojovém papíře), který zabírá. Proti každé střele si tvor hází zvlášť. Kouzlo nepůsobí na tvory za jinou překážkou. Kouzelník může seslat v jednom kole nejvýše tolik střel, kolik je jeho úroveň, ale nemusí je všechny posílat stejným směrem. PŘÍKLAD: PŘÍKLAD: Kouzelník na 7. úrovni může seslat najednou nejvýše sedm bílých střel, které (pokud vybuchnou na stejném místě) způsobí každému magickému tvoru...' AS pop
  UNION ALL SELECT 'Bílý blesk' AS nazev, NULL AS uroven, '5 magů' AS mag, '100 sáhů' AS dos, '1 kolo' AS sesl, 'ihned' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Barak lavan. Rozsah: 1 tvor. Toto kouzlo se vzdáleně podobá modrým bleskům, ale v jednom kole lze seslat toliko jeden bílý blesk. Bílý blesk způsobí zranění za 1–6 životů.' AS pop
  UNION ALL SELECT 'Břichomluvectví' AS nazev, NULL AS uroven, '4 magy za 10 sáhů' AS mag, '0' AS dos, '1 kolo' AS sesl, '2 směny' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Ledaber alidei betem. Rozsah: koule o poloměru podle dodané magenergie. Pomocí tohoto kouzla může kouzelník nechat vycházet svůj hlas z libovolného místa v dosahu. Kouzelník může mít zároveň břichomluvectví i cizí jazyk, a tedy hovořit hlasem někoho jiného z jiného místa. Na toto kouzlo se kouzelník nemusí dále soustředit.' AS pop
  UNION ALL SELECT 'Cizí jazyk' AS nazev, NULL AS uroven, '4 (8) magy' AS mag, 'dotek' AS dos, '1 kolo' AS sesl, '2 směny' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Nakerí išem. Rozsah: 1 postava. Tímto kouzlem může kouzelník napodobit jakýkoliv hlas, který kdy poslouchal alespoň 1 směnu, nebo tuto schopnost někomu propůjčit. Pokud kouzlo sesílá na sebe, je magenergie 4 magy, pokud na někoho jiného, 8 magů.' AS pop
  UNION ALL SELECT 'Cizí oči' AS nazev, NULL AS uroven, '8 magů' AS mag, '20 sáhů' AS dos, '1 kolo' AS sesl, '12 směn' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Nakerí ejnaim. Past: Int ~ 7 ~ 0. Rozsah: 1 živý tvor. S pomocí tohoto kouzla se kouzelník může dívat očima kteréhokoliv tvora v dosahu. Kouzelník musí být schopen alespoň zhruba určit místo, kde se ten tvor nachází. Kouzlo trvá, i když se tvor vzdálí z dosahu. Během trvání tohoto kouzla kouzelník vidí i svýma vlastníma očima, i když se na kouzlo musí soustředit. V praxi to znamená, že během tohoto soustředění nemůže například kouzlit nebo bojovat. Kouzlo lze kdykoliv ukončit tím, že se na něj kouzelník přestane soustředit. Kouzelník nemůže mít současně cizí oči i cizí uši. Později seslané kouzlo automaticky ukončí trvání předchozího.' AS pop
  UNION ALL SELECT 'Cizí uši' AS nazev, NULL AS uroven, '8 magů' AS mag, '20 sáhů' AS dos, '1 kolo' AS sesl, '12 směn' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Nakerí ozenaim. Past: Int ~ 7 ~ 0. Rozsah: 1 živý tvor. V zásadě stejné kouzlo jako cizí oči, jen místo o zrak jde o sluch. Kouzelník nemůže mít současně cizí oči i cizí uši. Později seslané kouzlo automaticky ukončí trvání předchozího.' AS pop
  UNION ALL SELECT 'Clona myšlenek' AS nazev, NULL AS uroven, '3 (9, 27) magy za směnu' AS mag, NULL AS dos, '6 kol' AS sesl, 'podle dodané magenergie' AS trv, NULL AS un, 'Původní/magické jméno: Machševim b miklab. Past: dotek. Rozsah: 1 živý tvor. Toto kouzlo vytvoří ochrannou bariéru, která chrání před všemi hraničářskými kouzly, která působí na psychiku, stejně jako před nepovolenou telepatií. Dává bonus +2 k hodu proti pasti u všech kouzelnických kouzel působících na psychiku. Pokud je vloženo 9 (27) magů za směnu, bonus je +3 (+4). Stačí, když se kouzelník cíle tohoto kouzla dotýká při jeho vyvolávání, po jeho seslání může odejít. Bonus a trvání určí kouzelník při sesílání; chce-li trvání kouzla prodloužit, musí ho seslat znovu.' AS pop
  UNION ALL SELECT 'Čarodějův zámek' AS nazev, NULL AS uroven, '7 magů' AS mag, '2 sáhy' AS dos, '1 kolo' AS sesl, 'stále' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Kosem armon. Past: Sil ~ +12 ~ 0. Rozsah: 1 dveře. Toto kouzlo je mocnější obdobou kouzla zamkni. Účinkuje na jakékoliv dveře, dokonce i když nemají zavírací mechanismus (zámek, klika, závora, západka). Kouzlo je možné seslat na dveře o maximální velikosti 1,5×3 sáhy. Potrvá, dokud nebude nějakým kouzlem zrušeno. Dveře je možné otevřít kouzlem zaklep nebo hrubou silou. Viz také uzamykací kouzla.' AS pop
  UNION ALL SELECT 'Černý blesk' AS nazev, NULL AS uroven, '25 magů' AS mag, '40 sáhů' AS dos, '1 kolo' AS sesl, 'ihned' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Barak šachor. Rozsah: 1 tvor. Toto kouzlo se vzdáleně podobá modrým bleskům, ale v jednom kole lze seslat toliko jeden černý blesk. Černý blesk způsobí terči zranění za 41–56 (3k6+38) životů.' AS pop
  UNION ALL SELECT 'Čtení myšlenek' AS nazev, NULL AS uroven, '4 magy za směnu' AS mag, '60 sáhů' AS dos, '5 nebo 10 kol' AS sesl, 'podle dodané magenergie' AS trv, NULL AS un, 'Původní/magické jméno: Kria machševim. Past: Roz+Int ~ 8 ~ 0. Rozsah: 1 živý tvor. Kouzelník může pomocí tohoto kouzla "číst" myšlenky tvorů s inteligencí 2 a větší. Pokud chce číst myšlenky jednoho určitého tvora (kouzelník musí vědět, jak tento tvor vypadá a kde se nachází), může začít hned po seslání kouzla. Kouzelník rozumí cizím myšlenkám bez ohledu na jazyk, kterým tvor mluví. V opačném případě kouzelník určí pouze směr a po dalších 5 kolech přečte myšlenky prvního tvora s inteligencí 2 nebo vyšší, na něhož v daném směru narazí. Není-li žádný tvor v dosahu, magenergie kouzla přišla nazmar. Kouzelník může toto kouzlo seslat i na tvora, který s tím souhlasí. V takovém případě si "obět" stejně háže proti pasti, ovšem uvažuje se, jako by byla na první úrovni. Pro hru je důležité si uvědomit, že čtení myšlenek není čtení paměti. Získáš tedy jen myšlenky, které tvor má v okamžiku čtení mysli. Čtení myšlenek nepřekáží dřevo ani jiné přírodní materiály, ale nepronikne ani slabou vrstvou kovu. Kouzelník se musí po celou dobu trvání kouzla soustředit. Pokud soustředění přeruší, kouzlo se ukončí. PŘÍKLAD: PŘÍKLAD: Kouzelník seslal kouzlo čtení myšlenek na rozmazleného válečníka Dhuna. Začne číst jeho myšlenky. Válečník zrovna myslí na: "Kam jsem dal ten zlaťák?"' AS pop
  UNION ALL SELECT 'Dubl' AS nazev, NULL AS uroven, '3 × úroveň kouzelníka' AS mag, '0' AS dos, '1 kolo' AS sesl, '2 dny' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Teom. Rozsah: 1 dvojník. Tímto kouzlem může kouzelník stvořit jednoho svého dvojníka. Dubl je tvořen protoplazmou, na první pohled jej však není možné od kouzelníka rozeznat. Nemá žádnou vlastní inteligenci a je schopen vykonávat jen nejjednodušší příkazy. S kouzelníkem není schopen komunikovat jinak než slovy. Pokud bude kouzelník chtít, okamžitě se rozplyne. Dubl má stejný počet životů jako kouzelník, stejné vlastnosti (jeho inteligence je však jen 2 a OČ je 2 bonus za obratnost), ale neuváveje se. Je ze zranitelný běžnými zbraněmi a kouzly, kromě psychických. Nepůsobí na něj jedy a alchymistické lektvary. Kouzelníkem s ním komunikovat jinak než slovy. Dubl může vy užívat zbraně a zbroje jako kouzelník, a to i způsobem dané kouzlo seslal (např. pomocí svitku) někdo jiný než kouzelník. Dublem způsobené zranění je vždy jen ze stínové. Dubl nemá žádné naučené schopnosti, ani schopnosti dané rasou ci povoláním (neumí kouzlit, plavat, nemá infravidění atd.). Věci, které dubl odloží, se okamžitě rozplynou. Kouzelník může manipulovat i s cizími hmotnými předměty (například pomocí dodanou zbraní – ty se po odložení pochopitelné nerozplynou). (Pozn.: Odstavce o Dublu obsahují na skenu zjevně poškozený/nesouvislý text — rekonstruováno podle smyslu, drobné nejasnosti přetrvávají, zejména věta o komunikaci s dublem a o použití cizích předmětů.)' AS pop
  UNION ALL SELECT 'Leť' AS nazev, NULL AS uroven, '2 magy za 5 kol' AS mag, 'dotek' AS dos, '3 kola' AS sesl, 'podle dodané magenergie' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Ufi. Rozsah: 1 tvor. Příjemce tohoto kouzla (může to být i sám kouzelník) může po dobu jeho trvání volně létat. Na let samotný se nemusí soustředit; nemůže se tedy soustředit ani zúčastnit leteckého souboje ani sesílat kouzla. Nejvyšší rychlost je 20 sáhů za kolo. Pomocí tohoto kouzla je také možné zůstat viset s jediným místem jako při kouzlu levitace. Na to není nutné se soustředit – ale stále je nezbytné bránit se v boji tváří v tvář, neboť to vyžaduje koordinaci pohybů v závislosti na okolním dění. Střílet lze zpravidla také, poslední slovo je posuzování má PJ.' AS pop
  UNION ALL SELECT 'Kouzelná rušička' AS nazev, NULL AS uroven, '10 magů za kolo' AS mag, '50 sáhů' AS dos, '2 kola' AS sesl, 'podle dodané magenergie' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Tyfrey. Rozsah: kruh o poloměru 35 sáhů. Po seslání tohoto kouzla uslyší všichni tvorové na zasaženém území (kromě sesilatele samotného), kteří neuspějí v hodu proti pasti a jsou inteligence větší než 1, temné hučení v hlavě. Nebudou schopni seslat jakékoliv kouzlo a všechna kouzla, která vyžadují soustředění, se přeruší. Kromě toho všechny hody vyžadující inteligenci mají postih −3.' AS pop
  UNION ALL SELECT 'Mrak smrti' AS nazev, NULL AS uroven, '25 magů' AS mag, 'viz níže' AS dos, '1 kolo' AS sesl, '6 měn' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Šamaim mavet. Past: Odl + Žvt ~ 5 ~ 1 život. Rozsah: 10 × 10 × 5 sáhů. Vedle kouzelníka se objeví oválný mrak 5 sáhů vysoký a 10 sáhů dlouhý a širokou. Pokud je bezvětří, dá se mrak do pohybu směrem, který určí kouzelník, rychlostí 20 sáhů za směnu (a už ho není možné zastavit), jinak se pohybuje se stejným směrem a rychlostí jako vítr. Mrak zmizí jen kouzlo rozptyl kouzla nebo náraz na hustě zelené rostlinstvo, například na les a podobně. Mrak je těžší než vzduch a vniká do všech prostor, které se pod ním otevřou (bude klouzat po svahu kopce, do děr atd.). Mrak může být i menší, pokud to bude kouzelník chtít. Tvorové zasažení mrakem, kteří neuspějí v hodu proti pasti, jsou okamžitě mrtví, ostatní jsou v každém kole zraněni za 1 život.' AS pop
  UNION ALL SELECT 'Najdi kouzla' AS nazev, NULL AS uroven, '4 magy' AS mag, '20 sáhů' AS dos, '1 kolo' AS sesl, '1 směna' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Tymcei ksamim. Rozsah: koule o poloměru 5 sáhů. Alchymista a jeho obory mají zvláštní schopnost vidění magenergie. Na podrobnosti se zeptej nějakého alchymisty i a s ním budeš mluvit, řekni mu, že znáš kouzlo, které dokáže ve vymezeném prostoru zvýšit pravděpodobnost úspěšného objevení magenergie. Jaké? Přece najdi kouzla. Toto kouzlo zvýší pro alchymistu pravděpodobnost úspěšného objevení o 25 % všech magenergií, která byla v okamžiku seslání kouzla blíže než 5 sáhů k bodu určenému kouzelníkovi při sesílání kouzla (a tento bod zase nesmí být dále než 5 sáhů od kouzelníka). (Pozn.: Text tohoto kouzla je na skenu částečně nesouvislý — hovoří zároveň o kouzelníkovi i o alchymistovi; rekonstruováno podle smyslu, možná jde o odkaz na to, že alchymista se toto kouzlo od kouzelníka může naučit/přizpůsobit.)' AS pop
  UNION ALL SELECT 'Najdi neviditelnost' AS nazev, NULL AS uroven, '8 magů' AS mag, '3 sáhy a každou úroveň kouzelníka' AS dos, '1 kolo' AS sesl, '6 směn' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Tymcei davar se loroim ota. Rozsah: kruh o poloměru dosahu. Po seslání tohoto kouzla se zviditelní všechny neviditelné předměty a postavy, které byly v okamžiku seslání kouzla blíže než 3 (× úroveň kouzelníka) sáhů k bodu určenému kouzelníkem (a tento bod zase nesmí být dále než dosah kouzla). Sešle-li například kouzelník na 6. úrovni, uvidí všichni veškeré neviditelné předměty a tvory, kteří jsou ke kouzelníkovi blíže než 18 sáhů. Předměty i tvorové zůstanou po celou dobu trvání kouzla viditelní, i když se z rozsahu kouzla vzdálí. Toto kouzlo platí jen na předměty, které byly nějakým způsobem zneviditelněny, nikoliv na ty, jež jsou neviditelné "od přírody" (jako například nevidění).' AS pop
  UNION ALL SELECT 'Najdi předmět' AS nazev, NULL AS uroven, '8 magů' AS mag, '0' AS dos, '1 kolo' AS sesl, '2 směny' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Tymcei davar. Rozsah: 1 předmět do vzdálenosti 20 sáhů + 3 sáhy za každou úroveň kouzelníka. Toto kouzlo je velmi vhodné pro zapomnětlivé starší pány, jakými kouzelníci ostatně obvykle jsou. S jeho pomocí je možné najít jeden libovolný předmět, který kouzelník dobře zná – například lulku od pantofle. Během trvání kouzla si kouzelník hledaný předmět představí a vzápětí se mu v mysli vynoří povědomí o jeho poloze. Kouzelník si může zvolit představit i něco všeobecného (například dveře) a popisovat svoji představu PJ. Měl by uvést alespoň přibližnou velikost, tvar a popřípadě materiál. Pokud něco podobného jeho popisu nalézá ve vzdálenosti nejvýš 20 + (3 × úroveň kouzelníka) sáhů, o tom řekne. Pán jeskyně mu to o tom neřekne.' AS pop
  UNION ALL SELECT 'Najdi zlo' AS nazev, NULL AS uroven, '5 magů' AS mag, '20 sáhů' AS dos, '1 kolo' AS sesl, '2 směny' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Tymcei ra. Rozsah: kruh o poloměru 20 sáhů. Po seslání tohoto kouzla se rozzáří všechny "zlé" předměty nebo postavy, které byly v okamžiku seslání kouzla blíže než 20 sáhů k bodu určenému kouzelníkem (a tento bod zase nesmí být dále než 20 sáhů od kouzelníka), takže je všichni uvidí. Zlo nemá v tomto případě nic společného s přesvědčením; jedná se o prokleté předměty nebo postavy poselné démonem, tj. takové, v nichž sídlí démon astrálních sfér omylem nebo nedopatřením přivolaný nějakým theurgem. Předměty i postavy budou zářit po celou dobu trvání kouzla, i když se z rozsahu kouzla vzdálí.' AS pop
  UNION ALL SELECT 'Neslyšitelnost' AS nazev, NULL AS uroven, '6 magů' AS mag, 'dotyk' AS dos, '2 kola' AS sesl, 'viz níže' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Al tyhí liš moa. Rozsah: 1 tvor. Příjemce tohoto kouzla se pohybuje naprosto neslyšně. Dveře nezaskřípou, schody nezavrzou, jeho zbroj nezařinčí, jeho dech nikdo neuslyší a ani kroll jej nenajde pomocí své zvláštní schopnosti. Tvora je samozřejmě vidět a je možné na něj útočit obvyklým způsobem. Nebude slyšet třesk zbraní, ani výkřiky útočníků a chřestění jejich zbroje ano. Neslyšitelnost pomine v okamžiku, kdy tvor promluví, začíná útočit tváří v tvář, začne sesílat kouzlo nebo začne využívat nějakou zvláštní mimosmyslovou či psychickou schopnost.' AS pop
  UNION ALL SELECT 'Neslyšitelnost do 4 sáhů' AS nazev, NULL AS uroven, '10 magů' AS mag, '32 sáhů' AS dos, '2 kola' AS sesl, 'viz níže' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Al tyhijú liš moa. Rozsah: 1 tvor a 4 sáhy okolí. Toto kouzlo se podobá kouzlu neslyšitelnost. Terč tohoto kouzla a všichni, kdo se v okamžiku jeho seslání nacházeli blíže než 4 sáhy ke terči, se stanou neslyšitelnými za stejných podmínek jako u kouzla neslyšitelnost. Pokud se někdo od terče vzdálí více než 4 sáhy, neslyšitelnost strácí a opětovným přiblížením se ji už nemůže získat zpět.' AS pop
  UNION ALL SELECT 'Neviditelnost do 4 sáhů' AS nazev, NULL AS uroven, '11 magů' AS mag, '32 sáhů' AS dos, '2 kola' AS sesl, 'viz níže' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Al tyhijú lirot. Rozsah: 1 tvor a 4 sáhy okolí. Toto kouzlo se podobá kouzlu neviditelnost z DrD Pravidel pro začátečníky. Terč tohoto kouzla a všichni, kdo se v okamžiku jeho seslání nacházeli blíže než 4 sáhy ke terči, se stanou neviditelnými za stejných podmínek jako v původním kouzlu neviditelnost. Pokud se někdo od terče vzdálí více než 4 sáhy, neviditelnost strácí a opětovným přiblížením se ji už nemůže získat zpět.' AS pop
  UNION ALL SELECT 'Nevycítitelnost' AS nazev, NULL AS uroven, '1 mag za směnu' AS mag, 'dotek' AS dos, '2 kola' AS sesl, 'podle dodané magenergie' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Al tyhí lirgoš. Rozsah: 1 tvor. Toto kouzlo učiní jednoho tvora naprosto nevycítitelným. Není možné jej vystopovat psy a hobit jeucítí svoji zvláštní schopnosti. Tvora je samozřejmě a je možné na něj útočit obvyklým způsobem. Nevycítitelnost pomine v okamžiku, kdy tvor promluví, začíná útočit tváří v tváří, začne sesílat kouzlo nebo začne využívat nějakou zvláštní mimosmyslovou či psychickou schopnost.' AS pop
  UNION ALL SELECT 'Nevycítitelnost do 4 sáhů' AS nazev, NULL AS uroven, '3 magy za směnu' AS mag, '32 sáhů' AS dos, '2 kola' AS sesl, 'podle dodané magenergie' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Al tyhijú hargašim. Rozsah: 1 tvor a 4 sáhy okolí. Toto kouzlo je obdobou kouzla nevycítitelnost a rozšiřuje jeho působnost na všechny tvory v rozsahu kouzla. Pokud se někdo od terče vzdálí více než 4 sáhy, nevycítitelnost strácí a opětovným přiblížením se ji už nemůže získat zpět.' AS pop
  UNION ALL SELECT 'Ohnivá koule' AS nazev, NULL AS uroven, '6 magů za každou kouli' AS mag, '90 sáhů' AS dos, '1 kolo' AS sesl, 'ihned' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Kadur ef. Past: Obr ~ 7 ~ 0. Rozsah: koule o průměru 15 sáhů. Po seslání tohoto kouzla vyletí z kouzelníkovy ruky střela ne větší než kroupa a ve vzdálenosti do 90 sáhů v místě zvoleném kouzelníkem vybuchne v ohnivou kouli o průměru 15 sáhů. Každý zasažený tvor je zraněn za 1–6 životů a každý sáh čtverečně (1 hex na souborovém papíře) zabírá. Proti každé kouli si tvor hází zvlášť. Kouzlo nepůsobí na tvory za zdí ani jinou překážkou. Kouzelník může seslat v jednom kole nejvýše tolik koulí, kolik je jeho úroveň, ale nemusí je všechny vyslat stejným směrem. PŘÍKLAD: PŘÍKLAD: Kouzelník na 7. úrovni může seslat najednou sedm ohnivých koulí, které (pokud vybuchnou na stejném místě) způsobí celkové zranění za 7–42 životů každému zasaženému tvoru lidské velikosti, a spotřebuje na ně 42 magů.' AS pop
  UNION ALL SELECT 'Ochrana před šípy' AS nazev, NULL AS uroven, '9 magů' AS mag, '0' AS dos, '1 kolo' AS sesl, '10 směn' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Kir lchec. Rozsah: povrch koule o poloměru 10 sáhů. Kolem kouzelníka se vytvoří bariéra odklánějící všechny šípy a jiné malé předměty (např. dýky, hvězdice, šipky, kámen z praku), ale ne oštěpy, vrhací sekery, střely z dobývacích zbraní. Bariéra neúčinkuje proti kouzelným střelám (např. kouzelný šíp, kouzelná hvězdice). Tato bariéra se pohybuje zároveň se sesilatelem. Bariéra brání i střelbě zevnitř ven, ne však střelbě pouze zevnitř.' AS pop
  UNION ALL SELECT 'Ochrom bleskem' AS nazev, NULL AS uroven, 'jako u příslušného blesku' AS mag, '12 sáhů' AS dos, '1 kolo' AS sesl, 'ihned' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Barak lik. Past: Int ~ 3–7 ~ 0. Rozsah: 1 tvor. Toto kouzlo navenek vypadá stejně jako blesky – modrý, zelený, žlutý, fialový či rudý. Jedná se ale o kouzlo iluzionistické, které způsobí terči jen zdánlivé zranění. Velikost tohoto zranění odpovídá blesku dané barvy, pravděpodobnost zásahu je ale 100 %. Nebezpečnost pasti při prohlédnutí této iluze závisí na typu blesku – pro modré je to 7, pro zelené 6, pro žluté 5, pro fialové 4 a pro rudé 3. Použitou vlastností je inteligence. Pokud terč uspěje v hodu proti pasti, není vůbec zraněn a má bonus +3 k hodu proti pasti při dalším kouzlu ochrom bleskem, pokud je na něj sesláno tyž den. Zranění způsobené kouzlem ochrom bleskem se projevuje stejně jako stínové zranění po útoku naplocho, s tou výjimkou, že po jedné směně zmizí veškeré zranění způsobené kouzlem (zatímco po útoku naplocho čtvrtina zranění zůstává). PŘÍKLAD: PŘÍKLAD: Kouzelník sešle kouzlo ochrom bleskem na skřeta, zvolí si modrý blesk, aby měl co největší šanci skřeta ochromit. Past pro skřeta bude mít nebezpečnost 7 a při neúspěchu ztratí 1–6 životů. Po jedné směně se mu tyto životy obnoví.' AS pop
  UNION ALL SELECT 'Oko' AS nazev, NULL AS uroven, '10 magů za 6 směn' AS mag, '0' AS dos, '1 kolo' AS sesl, 'podle dodané magenergie' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Ain. Rozsah: viz níže. Tímto kouzlem si kouzelník vytvoří jedno neviditelné oko, kterým vidí (ale neslyší). Je velké jako obyčejné oko a má infravidění. Oko se může pohybovat vzduchem rychlostí až 40 sáhů za směnu, neprojde pevnou překážkou a nevzdálí se více než 80 sáhů od kouzelníka. Na vidění okem se kouzelník musí soustředit, ale stále vidí i svýma vlastníma očima. Pokud se soustředit přestane, je kouzlo přerušeno.' AS pop
  UNION ALL SELECT 'Orxanův zámek' AS nazev, NULL AS uroven, 'nejméně 15 magů' AS mag, '30 sáhů' AS dos, '2 kola' AS sesl, 'stále' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Armon orxan. Past: podle dodané magenergie. Rozsah: 1 dveře, zámek, víko truhlice,…. Orxan byl možná nejmocnějším kouzelníkem země Súr a podle toho také vypadalo bohatství, které nashromáždil. Na jeho ochranu vymyslel nejmocnější uzamykací kouzlo, které podnes nese jeho jméno. Je schopno uzamknout jakékoliv dveře, brány, truhly atd, dokonce i když nemají zavírací mechanismus (zámek, klika, závora, západka). Takto zakleté dveře není možné otevřít kouzlem zaklep, ale je možné je vyrazit beranidlem nebo hrubou silou. Základní zvýšení nebezpečnosti pasti při vyražení silou je +13 a zvyšuje se o 1 za 3 magy nad základní hodnotou kouzla. Přidávání magenergie dá také význam po ochranu před beranidlem. Viz také uzamykací kouzla. PŘÍKLAD: PŘÍKLAD: Kouzelník uzavře 5 coulů tlustou dřevěnou bránu o rozměrech 2×2 sáhy Orxanovým zámkem a použije na to 21 magů. Nebezpečnost při otvírání dveří silou se zvýší o 15, na otevření kouzlem beranidlo bude potřebí 41 magů.' AS pop
  UNION ALL SELECT 'Oživ nemrtvého' AS nazev, NULL AS uroven, 'viz níže' AS mag, 'dotek' AS dos, NULL AS sesl, NULL AS trv, NULL AS un, 'Původní/magické jméno: Tytný chaj l met. Tímto kouzlem je možno stvořit nemrtvé (kostlivce, zombii atd.). Bude se jednat o skutečné nemrtvé – nehluchné vraž edné nestvůry, se kterými ses zatím setkával jen jako s nelítostnými nepřáteli. Nemrtvý takto stvořený budou mít stejná útočná a obranná čísla jako nemrtvý popsaný v bestiáři Pána jeskyně. O jejich zvláštních schopnostech nesmíš do skovis, pokud si daného nemrtvého vyvolávají a vyzvis od něj podrobnosti. Nikdy se nedozvíš jeho čísla údaje o vlastnostech, útočném a obranném čísle a podobně. Magenergie a doba potřebná na stvoření různých nemrtvých jsou různé. Přehledně je ukazuje Tabulka nemrtvých. Protože toto kouzlo je spíše rituálního charakteru, počítá se s způsobeného únava jinak než podle obvyklých pravidel pro nevyčerpávající či vyčerpávající kouzla a je rovněž uvedena v tabulce. Sloupec "životaschopnost" ukazuje, jaká je nejmenší možná životaschopnost daného nemrtvého, sloupec "počet magů" udává, kolik magů je zapotřebí na jeho stvoření na nejnižší úrovni. Číslo v závorce udává, kolik magů je zapotřebí dodat za každé zvýšení životaschopnosti o 1. Sloupec "únava" udává počet bodů skutečné únavy, které stvoření daného nemrtvého kouzelníkovi způsobí, číslo v závorce udává, o kolik se tato únava zvýší při zvýšení životaschopnosti o 1. Životaschopnost nemrtvého nemůže být nikdy větší než úroveň kouzelníka, jenž ho stvořil. K oživení nemrtvého potřebuje kouzelník ještě nějaký vhodný předmět, který může oživit: kostru pro kostlivce, mrtvolu pro zombie nebo ghúla. Pro ducha stačí jakékoliv ostatky (i jen prach a popel). Pro další druhy nemrtvých si podrobnosti o vhodných pozůstatcích musíš zjistit u svého učitele. Oživení nemrtví zpravidla nepociťují žádnou vděk ke svému stvořiteli, ba naopak, nenávidí ho za to, že je probudil z věčného spánku a zaútočí na první od pohledu. Kouzelník ovšem může způsobem a se stejným množstvím magenergie stvořit i nemrtvé, kteří mu jsou zdánlivě fanaticky oddáni. Při každém zaostření vůle však musí věnovat pozornost svojí osobnosti a inteligencí jev každého nemrtvého, který jev v tu chvíli poslouchá, jednu šestinu magenergie spotřebované na jeho oživení. Nemrtvý při tom nesmí být déle, než uvádí Tabulka vzdálenosti, a kouzelník musí mít zajištěno přesnosti uvedené ve sloupci "přesnost". Pokud PJ přesně neurčil polohu nemrtvého, přestane jej ovládat a bude se chovat jako každý jiný příslušníku jeho druhu popsaný v Bestiáři. Kouzelník si vlastnoručně oživeného a dočasně nadovládaného nemrtvého může znovu podřídit přidělením odpovídajícího množství magenergie – to trvá jednu směnu.' AS pop
  UNION ALL SELECT 'Poslání' AS nazev, NULL AS uroven, '25 magů' AS mag, '10 sáhů' AS dos, '3 kola' AS sesl, 'viz níže' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Šiur. Past: Roz ~ 7 ~ 0. Rozsah: 1 tvor. Toto kouzlo přinutí jednoho živého tvora s inteligencí vyšší než 1, aby vykonal nějakou činnost (nebo se jí vyhnul). Postavě je například možné poslat určitý předmět, aby ve tmě zpívala pochodové písně nebo aby nikdy neproznadila určitou informaci. Tato činnost musí být možná a nesmí předstasovat smrtelné nebezpečí, jinak se tomu poslání nezdaří. Nezdaří se ani tehdy, pokud v průběhu zadané činnosti smrtelné nebezpečí vyplyne z okolností. Délka trvání kouzla je omezena a činí cca 3 dny. O tom, kdy přesně kouzlo skončí, rozhodne PJ (který má pro to svá pravidla, ale kouzelník sám je nepozná. Postava si zachovává svoji osobnost a inteligenci, může se dokonce i rozhodnout, že poslání neuposlechne. V takovém případě ji PJ nějak potrestá; to, trest za neuposlechnutí poslání zmizí. Poslání je možné zrušit kouzlem rozptyl kouzla.' AS pop
  UNION ALL SELECT 'Přelož' AS nazev, NULL AS uroven, 'nejméně 7 magů' AS mag, 'slyšitelnost nebo viditelnost' AS dos, '1 kolo' AS sesl, '3 směny' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Tetargem. Rozsah: 1 text. Toto kouzlo se podobá kouzlu bábelská rybka s tím rozdílem, že po jeho použití rozumí i psaným textům a slovům pronášeným nemyslícími tvory (přirozené zvuky vylučované zvířaty z tohoto hlediska za slova nepovažuji) nebo věcmi, stejné jako bábelská rybka neumožňuje cizím jazykem mluvit a psát. Kromě toho je nutné si uvědomit, že kouzelník nezná nebezpečnost textu, tj. neví kolik bylo spotřebováno na kouzlo zašifruj. Hod provádí PJ, a pokud kouzelníkovi neuspěje, nikdy se nedoví, kolik mu chybělo. PŘÍKLAD: PŘÍKLAD: Kouzelník na 13. úrovni zašifroval dopis pomocí 12 magů a nyní se ho pokouší přečíst kouzelník na 10 úrovni s inteligencí 19. Rozhodne se do kouzla přelož vložit 11 magů. PJ tedy hodí 1k10, k výsledku přičte 1 (+4 za kouzelníkovu inteligenci, −3 za rozdíl úrovní), a pokud padlo více než 4 (6 − 2), kouzelník dopisu porozumí (nezávisle na tom, jakým byl psán jazykem).' AS pop
  UNION ALL SELECT 'Přelud nebezpečí' AS nazev, NULL AS uroven, '10 + viz níže' AS mag, '10 sáhů + 1 sáh za každou úroveň kouzelníka' AS dos, '3 kola' AS sesl, '20 kol' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Šikorat mal. Past: Int ~ 7 (0) ~ 0. Rozsah: koule o poloměru podle dosahu. Toto kouzlo vytvoří iluzi jakéhokoliv živého tvora, kterého kouzelník už někdy viděl. Tento tvor se bude chovat zcela přirozeně jako zvíře, kouzelník toto chování nijak neovlivní. Pokud začne tvor na někoho útočit, způsobí jen mu jen stínové zranění. Takto může kouzelník tvořit a napodobovat jen tvory s inteligencí nejvýše 1. Pokud by měli mít inteligenci vyšší, nebezpečnost pasti se snižuje na 0. Magenergie potřebná na dané kouzlo závisí jen na velikosti tvora. Pro tvora do velikosti A0 musí kouzelník vydat navíc 5 magů, pro velikost A 10 magů atd. Maximálně však lze stvořit tvora velikosti C. Vyvolávání kouzla trvá 3 kola a po celou dobu tvor pomalu zhmotňuje. Po ukončení trvání kouzla se tvor okamžitě rozplyne.' AS pop
  UNION ALL SELECT 'Rozptyl kouzla' AS nazev, NULL AS uroven, 'nejméně 8 magů' AS mag, '32 sáhů' AS dos, '1 kolo' AS sesl, 'stále' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Tytafrii et ha kosem. Rozsah: krychle 8×8×8 sáhů. Toto kouzlo je podobné kouzlu zlom kouzlo, ale s jeho pomocí je možné v daném rozsahu zničit jakákoliv kouzelnická kouzla, ne tedy jen ta, která působí na postavy. Kouzlo nemá vliv na kouzelné předměty. Magenergie potřebná k seslání tohoto kouzla se zvyšuje o magenergii kouzel, které má zničit. Pokud vložená magenergie nestačí na zrušení všech kouzel v daném rozsahu, kouzlo pusobí jen na ta kouzla, na které magenergie stačí. Začíná je rušit od kouzel, k jejichž seslání bylo použito nejméně magenergie. PŘÍKLAD: PŘÍKLAD: Tvor s inteligencí větší než 1 je pod vlivem kouzel cizí jazyk (4 magy) a poslání (25 magů). Magenergie potřebná ke zrušení všech tří kouzel je 41 (=4+4+25+8). Pokud bude použita jen 40 magů, rozptyl kouzla bude učinkovat jen na kouzla cizí jazyk a břichomluvectví. Tímto kouzlem je možné likvidovat i účinky některých démonů astrálních sfér (např. démona strážce) či sfér samotných. V takovém případě je potřebná magenergie 8 + (1k6 za každou úroveň démona). S pravděpodobností neúspěchu se to má stejně jako u kouzla zlom kouzlo. Počítá se ovšem pro každé rušené kouzlo zvlášť. Kouzlo nepůsobí proti účinkům alchymistických dočasných předmětů (lektvarů, svitků).' AS pop
  UNION ALL SELECT 'Rudé blesky' AS nazev, NULL AS uroven, '7 magů za první blesk, 6…' AS mag, 'koule o poloměru 10 sáhů' AS dos, '1 kolo' AS sesl, 'ihned' AS trv, 'vycerpavajici' AS un, 'Magenergie (přesně): 7 magů za první blesk, 6 magů za každý blesk navíc. Původní/magické jméno: Barak adom. Rozsah: 1–6 tvorů. Podobné kouzlo jako zelené blesky, ale zranění je za 5–30 životů a pravděpodobnost zásahu je 66 %, pokud je cílem jeden tvor. Za každého dalšího tvora, na kterého je kouzlo sesláno, se pravděpodobnost snižuje o 1 %. Kouzlo je možné seslat až na šest tvorů současně, ale magenergie se bude počítat za každého zvlášť. PŘÍKLAD: PŘÍKLAD: Pokud kouzelník sešle po jednom rudém blesku na 4 skřety, bude ho jejich seslání stát 28 (= 7×4) magů. Pravděpodobnost zásahu je pro každého skřeta 63 %.' AS pop
  UNION ALL SELECT 'Svaž postavu' AS nazev, NULL AS uroven, 'nejméně 2× životaschopnost…' AS mag, '40 sáhů' AS dos, '1 kolo' AS sesl, '1 směna na úroveň kouzelníka' AS trv, 'vycerpavajici' AS un, 'Magenergie (přesně): nejméně 2× životaschopnost za každou postavu. Původní/magické jméno: Likbo. Past: Roz+Sil ~ 5 ~ 0. Rozsah: 1–4 postavy. Toto kouzlo ochromí jen postavy třídy velikosti A0 až C. Postavami se v tomto kouzlu míní všechny humanoidní bytosti: člověk, elf, hobit, poloelf, skřet. Jedná se o úplné fyzické ochromění, takže postava nemůže ani mluvit. Na její mysl a vnímání však kouzlo nepůsobí – to je důležité zejména v případě, že je tímto kouzlem zasažen kouzelník, který má v úmyslu seslat kouzlo. Pokud kouzelník vloží do kouzla za danou postavu tolik magů, kolik je dvojnásobek její životaschopnosti, bude postava čelit pasti a nebezpečnosti 5. Pokud bude trojnásobek její životaschopnosti, nebezpečnost 7, pokud čtyřnásobek, nebezpečnost 9, a tak dále. Podle úvahy kouzelníka může každá postava čelit jiné pasti. Kouzelník si může vybrat, které postavy z větší skupinky chce svázat (nejvýše však 4); pokud své kouzlo sešle jen na jednu postavu, má tato postih −2 k hodu proti pasti. PŘÍKLAD: PŘÍKLAD: Kouzelník Trumb se setká se dvěma skřetími vojáky a jejich velitelem. Rozhodne se je všechny svázat, ale nejvíce mu záleží na veliteli. Proto oznámí PJ, že chce svázat s pastí 5 a velitele s pastí 9. Skřetí vojáci mají životaschopnost 1, jejich náčelník 3, aby k jeho podle kouzelníkova záhadlo podle jeho představ, musí na něj vynaložit alespoň 16 magů (= 2×(2×1) + 4×3).' AS pop
  UNION ALL SELECT 'Zabij' AS nazev, NULL AS uroven, '50 magů' AS mag, '80 sáhů' AS dos, '1 kolo' AS sesl, 'ihned' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Taarog. Past: Roz ~ 5 ~ 0. Rozsah: celková životaschopnost 4–40. Toto kouzlo se pokusí zabít tvory v dosahu s celkovou životaschopností 4–40 (přesná hodnota se určí v okamžiku seslání hodem 4k10). Tvorové s nejnižší životaschopností A0 jsou zabiti automaticky a nepočítají se do celkového součtu mrtvých. Kouzlo nepůsobí na magické tvory. Kouzlo působí nejdřív na tvory s nejnižší životaschopností, a to od celkové životaschopnosti se počítá i tvorů, kteří v hodu proti pasti uspěli. Kouzelník může z účinků kouzla vyjmout nejvýše 8 tvorů, kteří však nesmějí být blíže než 10 sáhů.' AS pop
  UNION ALL SELECT 'Zesměšni' AS nazev, NULL AS uroven, '60 : úroveň kouzelníka' AS mag, '5 sáhů' AS dos, '1 kolo' AS sesl, 'stále' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Aný osá mim chá chok. Past: Roz ~ 5 ~ 0. Rozsah: 1 tvor. Toto kouzlo umožňuje kouzelníkovi zesměšnit jednu postavu tím, že jí například přičaruje ouší uši, dlouhý nos nebo koňskou ohánku. Záleží jen na kouzelníkových vymyslí si vymyslet, co by tím chtěl chtěl, co by chtěl vymyslet, co by chtěl ublížit. Kouzlo trvá, dokud někdo na oběť nesešle kouzlo rozptyl kouzla nebo dokud kouzelník, který kouzlo zesměšní seslal, neusoudí, že splnil svůj účel. Na tomto kouzlu je pozoruhodné, že je jednodušší pro kouzelníky na vyšší úrovni. Dél šedesát úrovní kouzelníka a dostanete počet magů potřebný ke seslání kouzla zesměšni na dané úrovni. Tak například na první úrovni by to bylo šedesát magů, na druhé 30 magů, na třetí 20 magů, na čtvrté 15 magů, na páté 12 magů, na desáté 6 magů, na dvacáté 3 magy atd. Je také vidět, že jen na nejnižší úrovni, na které je skutečně možné kouzlo zesměšni seslat, je třetina úroveň. (Pozn.: Odstavec o mechanismu magenergie kouzla Zesměšni je na skenu poškozený/nesouvislý — rekonstruováno podle smyslu, číselné příklady (60/30/20/15/12/6/3 magů pro úrovně 1/2/3/4/5/10/20) odpovídají vzorci 60:úroveň.)' AS pop
  UNION ALL SELECT 'Zmatek' AS nazev, NULL AS uroven, '12 magů' AS mag, '40 sáhů' AS dos, '1 kolo' AS sesl, '6 kol' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Balagan. Past: Roz ~ 6 ~ 0. Rozsah: tvorové s celkovou životaschopností 3–18. Kouzlo zmate tvory s celkovou životaschopností 3–18 (přesná hodnota se určí v okamžiku seslání hodem 3k6), kteří neuspějí v hodu proti pasti. Zmaten může být každý, kdo je v dosahu, tedy i přátelé kouzelníka. Hod proti pasti se opakuje každé kolo. Zmatený tvor si hodí 2k6, a pokud mu padne: 2–5, napadne kouzelníkovu družinu, 6–8, neudělá nic, 9–12, zaútočí na vlastní družinu.' AS pop
  UNION ALL SELECT 'Zmiz' AS nazev, NULL AS uroven, 'viz níže' AS mag, '20 sáhů' AS dos, '1 kolo' AS sesl, 'ihned' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Taufi. Past: Roz ~ 10 ~ !. Rozsah: 1 tvor nebo předmět. Po seslání tohoto kouzla zmizí živý tvor (pokud neuspěje v hodu proti pasti) nebo neživý předmět (proti kouzlu majitel předmětu háže, pokud k němu není přítomen; jedině pokud se zmizením souhlasí, házet si nemusí).' AS pop
  UNION ALL SELECT 'Žluté blesky' AS nazev, NULL AS uroven, '5 magů za první blesk, 4…' AS mag, '10 sáhů' AS dos, '1 kolo' AS sesl, 'ihned' AS trv, 'vycerpavajici' AS un, 'Magenergie (přesně): 5 magů za první blesk, 4 magy za každý blesk navíc. Původní/magické jméno: Barak cahof. Rozsah: 1 tvor. Podobné kouzlo jako zelené blesky, ale zranění je za 3–18 životů a pravděpodobnost zásahu 72 %.' AS pop
  UNION ALL SELECT 'Améba' AS nazev, NULL AS uroven, '12 magů za směnu' AS mag, 'dotyk' AS dos, '2 kola' AS sesl, 'podle dodané magenergie' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Golem. Rozsah: 1 tvor. Za pomoci tohoto kouzla získává postava schopnosti améby. Může protékat klíčovou dírkou, různě měnit tvar, může se libovolně natahovat. Nemůže se ale rozdělit ani změnit objem svého těla. Při všech tělesných přeměnách však musí zachovávat anatomii vlastního těla – pokud a nedodrží (např. vytvoření si třetí ruky), nemůže svůj orgán ovládat. Změny tvaru těla probíhají jako z tvorova přání a ten se na ně nemusí nijak soustředit. Změny trvají vždy alespoň jedno kolo. Amébovité schopnosti získávají i věci a tvorové velikosti A0, které měla postava při sobě v okamžiku seslání kouzla; věci, které vezme později, již tuto schopnost nemají. Věci (a tvorové), které amébovitou schopnost získaly, ji budou mít po celou dobu trvání kouzla i když je postava odloží. Tyto věci a tvory lze různě tvarovat, ale při první příležitosti se vracejí k původního tvaru – nelze je tedy přetvářet (tuto schopnost získává pouze tvor postavy). Pod vlivem kouzla améba je postava sečnými a bodnými zbraněmi normálně zranitelná, ale zbraněmi tupými (včetně úderu naplocho) je zranění jen poloviční (ztráta životů se zaokrouhluje nahoru). Toto kouzlo je zvláště vhodné k "protékání" skrz mříže či klíčové dírky nebo ke krádežím za pomoci "dlouhých" prstů nebo rukou. Protečení mřížkou trvá asi 2 až 3 kola, klíčovou dírkou je to již o trochu složitější, ale i nezkušená "améba" to lehce zvládne za půl směny.' AS pop
  UNION ALL SELECT 'Barevná změna' AS nazev, NULL AS uroven, '3 magy za 1 sáh²' AS mag, 'dotyk' AS dos, '1 kolo' AS sesl, 'viz níže' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Šinui ceva. Rozsah: podle dodané magenergie. Toto kouzlo přebarví libovolný neživý předmět, který nebyl vytvořen pomocí magie. Barva může být naprosto libovolná, velikost barvené plochy závisí čistě na kouzelníkovi. Platí, že na 1 sáh² plochy jsou zapotřebí 3 magy. Pokud bude chtít kouzelník obarvit plochu větší, stačí přidat magenergii – za každý započatý m² nátěru další 3 magy (z toho vyplývá, že magenergie kouzla nebude nikdy nižší než 3 magy, byť by byla barvená plocha sebenepatrnější). Při barvení oděvu platí, že velikost A = 2 sáhy²; B = 3 sáhy²; C = 4 sáhy². Barva se chová jako obyčejná barva a nátěr – časem vyblednete, odře se, oprýská... Pokud bude chtít kouzelník kvalitnější vodostálou barvu, tj. podstatně trvanlivější, musí magenergii kouzla zdvojnásobit. Pokud bude chtít barvy kombinovat (např. různé vzory na oděvu), magenergie se počítá, jako kdyby každou barvou barvil celou plochu. Zlatá nebo stříbrná barva vytvořená tímto kouzlem neobsahuje sebemenší množství dotyčného kovu! Barvy a nátěry vzniklé za pomoci tohoto kouzla se dají zlikvidovat kouzlem rozptyl kouzla nebo odstranit jako normální barvy.' AS pop
  UNION ALL SELECT 'Bílý blesk kulový' AS nazev, NULL AS uroven, '10 magů' AS mag, '200 sáhů' AS dos, '1 kolo' AS sesl, 'ihned' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Hakadur barak lavan. Rozsah: 10 sáhů, 1 místo. Najednou lze seslat toliko jeden blesk. Do vzdálenosti 200 sáhů vybuchne kdekoliv podle přání kouzelníka v kouli o průměru 10 sáhů a zraní všechny zasažené tvory dohromady za 1–6 životů. Blesk vždy zasáhne cíl; není třeba házet na pravděpodobnost (ale samozřejmě se háže obvyklým způsobem na úspěch kouzla).' AS pop
  UNION ALL SELECT 'Bledý blesk' AS nazev, NULL AS uroven, '65 magů' AS mag, '40 sáhů' AS dos, '1 kolo' AS sesl, 'ihned' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Barak machor. Rozsah: 1 tvor. Toto zaklínadlo je podobné jako černý blesk. Najednou lze seslat jen jeden bledý blesk, který nestvůru automaticky zasáhne a zraní ji za 105–150 životů.' AS pop
  UNION ALL SELECT 'Bledý blesk kulový' AS nazev, NULL AS uroven, '130 magů' AS mag, '80 sáhů' AS dos, '1 kolo' AS sesl, 'ihned' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Hakadur barak machor. Rozsah: 10 sáhů, 1 místo. Najednou lze seslat toliko jeden blesk. Do vzdálenosti 200 sáhů kdekoliv podle přání kouzelníka vybuchne v kouli o průměru 10 sáhů a zraní všechny zasažené nestvůry dohromady za 105–150 životů. Blesk vždy zasáhne cíl; není třeba házet na pravděpodobnost (ale samozřejmě se háže obvyklým způsobem na úspěch kouzla).' AS pop
  UNION ALL SELECT 'Cestář' AS nazev, NULL AS uroven, '20 magů; 35 magů; 45 magů na…' AS mag, '0 (od kouzelníkových nohou)' AS dos, '2 kola' AS sesl, 'maximálně 3 směny' AS trv, 'vycerpavajici' AS un, 'Magenergie (přesně): 20 magů; 35 magů; 45 magů na 100 sáhů. Původní/magické jméno: Dere. Rozsah: dle dodané magenergie. Toto kouzlo základně vytvoří dlážděnou cestu tvořenou kamennými kostkami o hraně půl sáhu (tuto dlažbu nelze jak rozebírat, kostky jsou k sobě vázány kouzlem). Cesta je 2 sáhy široká a 100 sáhů dlouhá, v hrubých rysech kopíruje terén (tedy zvládne převýšení půl sáhu na dvou sáhu délky, pokud narazí na vyšší překážku, na daném místě skončí) a je schopna své trvání dočasně odstranit překážky které nejsou vyšší, než ona sama. Tyto překážky jsou posunuty ke stranám cesty. Pokud bude jedne například les a podrost, na okrajích cesty bude hustší než v okolí. Cesta může procházet pouze územím, které má pevný povrch (to znamená takový povrch, na němž by se běžná dlážděná cesta nebortila – zde je poslední slovo PJ). Může překlenout i terénní nerovnosti, jako jámy, trhliny a strouhy, které nejsou širší než 2 sáhy. Jich po své délce může i několik, ale žádná z nich nesmí být širší než 2 sáhy a žádný pevný úsek nesmí být kratší než 1 sáh. Převýšení mezi okraji pukliny nesmí být větší než půl sáhu. Pokud některá z těchto podmínek nebude splněna, cesta na daném místě skončí. Kouzelník se může rozhodnout za 35 magů vystavět pevnější cestu, která na první pohled vyhlíží stejně, avšak může být stavěna po celé délce a na nezpevněném terénu (písku, bažině). Pevnější cesta je schopna překlenout vzduchem či na hladině vody nejvýše 10 sáhů (ale musí následovat alespoň sáh pevného podkladu). Pokud po přesnění mezi dvěma pevnými místy vyšší než 2 sáhy, cesta toto nezvládne a bude přeté touto překážkou končit. Pokud kouzelník potřebuje překlenout most či vodní hladinu, do kouzla vloží 45 magů. Postavit most, po kterém se lze dostat na druhou stranu. Převýšení mezi okraji propasti nesmí být větší než 20 sáhů. Vidíš to kupříkladu dvojnásobek magenergie pro most, o vyplnutí doby, bude zůstane při vzduchem 200 magů. Stejné tak, dá-li do kouzla trojnásobek magenergie, bude most dlouhý 300 magů, atd... Šířku propasti mu však nikdo neurčil, bude muset odhadnout. (Pozn.: Odstavec o cenách/délce mostu obsahuje viditelně poškozený/přeházený text ze skenu — přepsáno v nejpravděpodobnější interpretaci, bez tiché opravy smyslu.)' AS pop
  UNION ALL SELECT 'Černý blesk kulový' AS nazev, NULL AS uroven, '50 magů' AS mag, '80 sáhů' AS dos, '1 kolo' AS sesl, 'ihned' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Hakadur barak šachor. Rozsah: 10 sáhů, 1 místo. Najednou lze seslat toliko jeden blesk. Do vzdálenosti 80 sáhů vybuchne podle přání kouzelníka v kouli o průměru 10 sáhů a zraní všechny zasažené tvory dohromady za 41–56 životů. Blesk vždy zasáhne cíl; není třeba házet na pravděpodobnost (ale samozřejmě se háže obvyklým způsobem na úspěch kouzla).' AS pop
  UNION ALL SELECT 'Davová hypnóza' AS nazev, NULL AS uroven, '80 magů' AS mag, '200 sáhů' AS dos, '2 kola' AS sesl, '1–3 směny' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Hypno hamon. Past: viz níže. Rozsah: viz níže. Po seslání tohoto kouzla může kouzelník libovolně ovládat dav, který neuspěje v hodu proti pasti. Použitá vlastnost není (k hodu k10 se nic nepřičítá), nebezpečnost dostaneš, když k bonusu za charisma kouzelníka přičteš číslo z Tabulky davové hypnózy. "Počtem lidí" je míněn počet inteligentních bytostí, které se kouzelník pokusí hypnotizovat. Při tom může nikoho vyjmout – kouzelník musí zhypnotizovat celý přítomný dav. Je-li v davu přítomen tvor s životaschopností 5 a vyšší nebo s inteligencí 21 a vyšší, není zhypnotizován a do celkového počtu hypnotizovaných lidí se nepočítá. Za dav nepovažujeme žádnou organizovanou skupinu, například vojenský oddíl nebo policejní hlídku.' AS pop
  UNION ALL SELECT 'Dlouhá ruka' AS nazev, NULL AS uroven, '9 magů' AS mag, '0' AS dos, '1 kolo' AS sesl, '6 kol' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Jat aro. Rozsah: 1 vlastní končetina (ruka, noha, zuby, atd.). Tímto kouzlem si kouzelník může vytvořit neviditelnou hmotnou ruku (či jinou část těla – např. nohu, zuby, atd...), ale nesmí ji vytvořit žádný smyslový a vnitřní orgán (tedy oči, uši, ale ani mozek, plíce, srdce, atd...). Takto vytvořená končetina se plynule pohybuje prostorem (neteleportuje se) rychlostí 10 sáhů a kolo (tedy jeden sáh za vteřinu), ale nemůže procházet žádnou pevnou hmotou. V neviditelné končetině má kouzelník samozřejmě hmat a cit (jinak by nemohl pohybovat předměty). Je-li neviditelná končetina jakýmkoliv způsobem zraněna (ať zbraní nebo ohněm či kouzlem), zranění se přenáší v plné výši na kouzelníka. Tímto způsobem však není možné kouzelníka zabít – pokud by byla ruka zraněna a víc životy, než kolik jich kouzelník v dané chvíli má, zranění se nepřenese všechno a kouzelníkovi jeden život zbude. V případě, že je neviditelná ruka zasažena otrávenou zbraní, otrava se nepřenáší, pouze zranění zbraní. Při vlastním pohybování předměty (nebo třeba i útoku neviditelnou pěstí na protivníka) musí kouzelník cíl svého snažení vždy vidět nebo vědět, kde je, a orientovat se po hmatu, a svoji skutečnou končetinou vykonávat takové pohyby, které má vykonávat končetina vytvořená kouzlem. Touto končetinou lze i normálním způsobem útočit. Pokud kouzelník útočí jen končetinou, má výhodou přesnosti pevnými útočí nemá zbraní přesnosti −1 za prostorovou dezorientaci. Pokud útočí kouzelník neviditelné končetině, ale mí postih −3 za prostorovou dezorientaci. (Pozn.: Věta o postizích za dezorientaci obsahuje viditelně přeházený text ze skenu — přepsáno v nejpravděpodobnější interpretaci se zachováním smyslu.) Neviditelnou ruku je možné přemisťovat i na větší vzdálenost, a to rychlostí 10 sáhů a kolo. V takovém případě však konečnina nemůže vykonávat žádné složité pohyby. Váha přenášených předmětů závisí na síle kouzelníka, samotné kouzlo na sílu nemá vliv. Dlouhou rukou je možné seslat kouzla s dosahem "dotyk" jen tehdy, přidá-li kouzelník při vyvolávání takového kouzla i tou úroveň kouzelníka za polovinu.' AS pop
  UNION ALL SELECT 'Dotyk upíra' AS nazev, NULL AS uroven, 'životaschopnost + 1' AS mag, 'dotyk (viz níže)' AS dos, '3 kola' AS sesl, 'do 3 kol po vyvolání 1 dotyk' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Magat išri. Past: Roz ~ 10 ~ !. Rozsah: 1 tvor. Kouzelníkův dotyk po seslání tohoto kouzla působí jako dotyk upíra vyšších mrtvolí – oběť útoku ztratí jednu úroveň zkušenosti. Po vyvolání tohoto kouzla má kouzelník 3 kola na to, aby se dotkl své oběti (do těchto 3 kol se počítá i seslání kouzla). Pokud tak učiní, oběť ztratí úroveň a kouzlo končí (další dotyk během těchto tří kol již nemá účinek). Upítí úrovně tímto kouzlem nelze zrušit pomocí rozptyl kouzla ani odvolat. Dotyk je normální útok, jen u nejde o zranění cíle – řiď se pravidly pro pěstní souboj v Pravidlech pro pokročilé, a pokud se nesnažíš v pěstním souboji zranit, ale jen zasáhnout, máš bonus +1 k ÚČ. Pak ale není oběť nijak fyzicky zraněna, pouze na ni působí kouzlo. Vlastní kouzlo je možno po dobu trvání ovládat – dotkne-li se náhodou někoho jiného, dotyk upíra na ně nebude působit, nebude-li to kouzelník chtít. Proti pasti si obeť háže vždy, i kdyby si sama přála, ať na ni kouzlo působí.' AS pop
  UNION ALL SELECT 'Duševní rozštěp' AS nazev, NULL AS uroven, 'životaschopnost oběti + 15' AS mag, '10 sáhů' AS dos, '1 kolo' AS sesl, 'stálé' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Picul navši. Past: Roz+Int ~ 9 ~ !. Rozsah: 1 bytost s inteligencí vyšší než I. Po seslání tohoto kouzla vytryskne z kouzelníkovy dlaně zářivý proud energie, jenž narazí do čela zvolené cílové postavy (nestvůry), která musí hodit proti uvedené pasti na inteligenci. Pokud se jí nepodaří hnout se pasti, sníží se jí inteligence na hodnotu 1/–5. Pokud se takto postižene na vlastní postavu, přebírá se PJ (postavy s inteligencí 1 nemohou hrát hráče). Zásah kouzlem duševní rozštěp se dá léčit jedině tak, že oběť každý den sesláním kouzla dané pasti v hodnotě alespoň 10 životů nebo dány léčivá kouzla s podobným účinkem. Životy jí nepřibudou, ale každý den se inteligence na ni zvýší o 1. Léčení je však pochopitelně kdykoliv zastavit, bude-li kouzlo přerušeno na dobu delší než 7 dní, nikdy se v něm již nedá pokračovat! Inteligence postižené postavy lze zvýšit maximálně na stupeň, který měla před zásahem kouzla.' AS pop
  UNION ALL SELECT 'Granátové jablko' AS nazev, NULL AS uroven, '10 magů za kus' AS mag, '0' AS dos, '1 kolo' AS sesl, 'ihned' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Rimon. Toto kouzlo se podobá kouzlu nebezpečné ovoce. Stvoří červené granátové jablko (asi 8 coulů v průměru), jež po odtržení stopky reaguje na jakýkoli prudší náraz výbuchem. Jeho síla je 24/12/5/2/1, zbylé údaje jsou stejné jako u nebezpečné ovoce v Tabulce zbraní v DrD Pravidlech pro pokročilé, kapitola "Nepřímá střelba". Toto jablko i bez odtržení stopky po odtržení stopky reaguje na jakýkoli prudší náraz výbuchem 6–10 směnách samovolně vybuchuje plnou silou! (Pozn.: Poslední odstavec obsahuje viditelně poškozený/duplikovaný text ze skenu — smysl pravděpodobně: jablko po odtržení stopky reaguje výbuchem na náraz, a pokud nevybuchne, samovolně vybuchne po 6–10 směnách. Přepsáno doslovně bez tiché opravy.)' AS pop
  UNION ALL SELECT 'Chlad hvězd' AS nazev, NULL AS uroven, 'zranění: nejméně 4 zmražení:…' AS mag, '20 sáhů' AS dos, '1 kolo' AS sesl, 'ihned (10–60 směn při zmražení)' AS trv, 'vycerpavajici' AS un, 'Magenergie (přesně): zranění: nejméně 4 zmražení: životaschopnost + 15. Původní/magické jméno: Kar kochavim. Past: Roz ~ 8 ~ 0. Rozsah: 1 tvor. Po seslání tohoto kouzla se okamžitě sníží tělesná teplota oběti. Při magenergii 8 magů automaticky zraní chladem za 3–8 životů, za každé 2 magy se rozsah zranění zvedne o 3 životy (tedy dá-li kouzelník 10 magů, tvor zraněn chladem za 6–11 životů, pokud dá 12 magů, tak za 9–14, atd.). Pokud se kouzelník rozhodne nepřátelského tvora zmrazit do ledového bloku, potřebuje na seslání kouzla o 15 magů více, než je jeho životaschopnost tvora. Zmrazení si hodí proti pasti Roz ~ 8 ~ nic/zmrazení. Pokud se nevyhne pasti, je zmražen na 10–60 směn (v teple rozmrznout rychleji). Při roztavení si hodí proti pasti Odl ~ 12 ~ 10k6 stínových životů/10k6 normálního zranění, tvora nezmizí pomineul kouzla ležet na zemi jenom studená mrtvola. (Pozn.: Poslední věta obsahuje viditelně poškozený text ze skenu — přepsáno doslovně, smysl nejasný, bez tiché opravy.)' AS pop
  UNION ALL SELECT 'Jídlonoš' AS nazev, NULL AS uroven, '4 magy (+1 mag za lepší…' AS mag, '5 sáhů' AS dos, '2 kola' AS sesl, 'úroveň kouzelníka : 2 směn' AS trv, 'vycerpavajici' AS un, 'Magenergie (přesně): 4 magy (+1 mag za lepší jídelní servis). Původní/magické jméno: Mazon. Past: Int ~ 10 ~ 0. Rozsah: 1 porce jídla (asi ½ cenu). Toto kouzlo stvoří jednu porci jídla odpovídající přibližně polovině ceny. Jídlo může být libovolného druhu přesně podle přstav kouzelníka. Podmínkou je pouze to, že kouzelník již takové jídlo musel někdy jíst a jídlo nesmí být nijak zdravotně závadné. Pakliže kouzelník chce, může po přidání jednoho magu jídlo obdržet v lepším jídelním servisu a třeba se stříbrným příborem. Veškeré nádoby a příbory však zmizí 3 kola poté, co bude jídlo dojedeno. Důležitý je také fakt, že se nejedná o skutečné jídlo, ale pouze o iluzi. Jeho použití je jen krátkodobě, do doby uvedenou v trvání se to zcela přesvědčeno o sytosti – počítá se to, jako by tvor opravdu najedl, opravil se mu patřičné postihy pří hladovění. Avšak po skončení trvání se všechny přídavky postihy vracejí, jako by nikdy žádné jídlo nebylo. Tímto kouzlem tedy nelze oddálit hladovění, ale pouze na nejakou dobu tělo jeho strádání nemyné. (Pozn.: Tento odstavec i následující dva obsahují viditelně poškozený/přeházený text ze skenu — přepsáno v nejpravděpodobnější interpretaci se zachováním smyslu, bez tiché opravy.) Postava, které uspěje v hodu proti pasti neuspěl, není nijak možné probudit po celou dobu trvání kouzla. Spicí postava, která bude v době trvání kouzla a do tří zasaženého místa vytažena, se do tří kol probudí, ale ne dříve. Taktéž všechny postavy postiženě tímto kouzlem se probudí do 3 kol po jeho skončení. Drobní tvorové (velikosti A0) zasaženi tímto kouzlem usnou okamžitě. Kouzlo nepůsobí na žádné magické tvory. Z působnosti tohoto kouzla se nikoho vyjmout, kouzelníka nevyjímaje. (Pozn.: Poslední dva odstavce popisují zjevně efekty jiného kouzla — pravděpodobně omylem přesazená pasáž ze sousedního kouzla "Kouzlo spánku" v důsledku skenové/sazečské chyby v originále. Ponecháno na svém místě v předloze, přepsáno beze změn.)' AS pop
  UNION ALL SELECT 'Klika' AS nazev, NULL AS uroven, '5×životaschopnost + 25' AS mag, 'dotyk' AS dos, '3 kola' AS sesl, '1 úkon – podle jeho trvání' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Mazal. Rozsah: 1 úkon. Tímto mocným kouzlem může kouzelník vylepšit šance na vykonání nějakého nedlouhého úkonu. Pod pojmem úkon zde rozumíme činnost, která trvá do prvního odpočinku od spánku. Například sesílání kouzla, lezení po skále, pokácení jednoho stromu, atd. Za úkon se nepovažuje přechod přes hory, cesta z jednoho města do druhého – u všech těchto příkladů se uvažuje trvání delší než jeden den. Za úkon, na který si cílem kouzla, si na daný hod dvakrát a poté vybere si lepší z obou pokusů.' AS pop
  UNION ALL SELECT 'Kouzlo spánku' AS nazev, NULL AS uroven, '40 magů' AS mag, '50 sáhů' AS dos, '1 kolo' AS sesl, '5–10 hodin' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Šena. Past: Roz+Odl ~ 8 ~ nic/spánek po dobu trvání kouzla. Rozsah: kruh o poloměru 20 sáhů. Toto kouzlo očaruje místo, na které je sesláno. Každý živý tvor, jenž na něm nachází, nebo do něj v době trvání kouzla vstoupí, si musí hodit proti pasti. Uspěje-li, musí proti ní házet v každém kole, kdy se v poli působení (Pozn.: Popis kouzla "Kouzlo spánku" se zde v předloze přerušuje uprostřed věty — na následující naskenované straně pokračuje text kouzlem "Ledový blesk". Jde zjevně o artefakt řazení/skenování stran; pravděpodobné pokračování popisu se nachází dále v PDF (str.73) a bude doplněno/odkázáno v navazujícím Dokumentu. Nic nebylo vymyšleno ani tiše doplněno.)' AS pop
  UNION ALL SELECT 'Ledový blesk' AS nazev, NULL AS uroven, '8 magů za první blesk, 7…' AS mag, '15 sáhů' AS dos, '1 kolo' AS sesl, 'ihned' AS trv, 'vycerpavajici' AS un, 'Magenergie (přesně): 8 magů za první blesk, 7 magů za každý další. Původní/magické jméno: Lapid kela. Rozsah: 1–7 tvorů. Kouzelník může toto zaklínadlo seslat najednou až za 7 tvorů, pro každého se však magenergie počítá zvlášť. Tyto blesky nespalují ohněm, ale, jak napovídá název, mrazem. Každý blesk zraní zasaženou postavu za 4–40 životů. Má základní pravděpodobnost zásahu 65 %. Za každého dalšího tvora, na kterého je kouzlo sesláno, se pravděpodobnost zásahu snižuje o 1 %.' AS pop
  UNION ALL SELECT 'Lomený plamen' AS nazev, NULL AS uroven, '20 magů za 1 kus' AS mag, '100 sáhů od kouzelníka' AS dos, '1 kolo' AS sesl, 'podle okolností, max. 20 kol' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Lahat. Past: Obr ~ 7 ~ 0. Rozsah: nejvýše tolik "plamenů", jaká je úroveň kouzelníka. Toto kouzlo vyvolá 1 sáh dlouhou a 1 coul širokou "plamennou tyč", která se bude snažit svůj cíl pronásledovat naprosto všude (po schodech, za roh, klíčovou dírkou,...), a to rychlostí 10 sáhů za kolo. Při pronásledování terče ve výšce jednoho sáhu kopíruje terén (tedy plazí se po zemi), a to je efektní zejména na schodech – odtud název lomený plamen. Lomenému plameni je velmi obtížné uniknout – jediná spolehlivá možnost je teleportovat se na vzdálenost větší než 100 sáhů od lomeného plamene nebo za kovovou či kamennou zeď vysokou nejméně dva sáhy, kde bude nejbližší možná vzdálenost kolem překážky alespoň 100 sáhů mezi lomeným plamenem a terčem. Ještě je i možnost utéci z dosahu pomocí kouzla rychlost. V těchto případech lomený plamen zmizí. Lomený plamen zmizí také tehdy, když se při svém pronásledování oběti vzdálí více než 100 sáhů od kouzelníka. Lomený plamen se protahuje jakoukoliv škvírou širší než 1 coul, dokáže se i propálit dřevěnými dveřmi či stěnou, toto však lomený plamen zkrátí o 10 coulů (lomený plamen se bude zkracovat o 10 coulů za každých započatých 10 coulů propalovaného dřeva a každých 10 coulů mu bude trvat 1 kolo). Lomený plamen se bude v každém kole snažit svůj terč zasáhnout – vždy útok je počítán jako past Obr ~ 7 ~ nic/zásah. V případě zásahu obleje lomený plamen zasažený terč a zraní ho za 5 životů za každých 10 coulů plamene. Pokud se postava vyhne pasti, zkrátí se lomený plamen o 10 coulů a každý neúspěšný pokus o zásah. Takto se bude zkracovat do té doby, dokud nezasáhne oběť nebo se úplně nevyčerpá, pak mizí. Proti pasti si hází v momentě seslání a pak pokaždé na začátku kola. Kouzelník může plamen zrušit nu přikázat, aby na svoji oběť neútočil. V takovém případě ji plamen stále pronásleduje, nezkracuje se a neútočí. Na zadržování plamene musí kouzelník soustředit; pokud přestane, plamen bude pokračovat v útocích. Kouzelník může najednou seslat nanejvýš tolik lomených plamenů, kolik je jeho úroveň. Může je sesílat na více postav najednou, ale i všechny na jednu postavu – ta si musí házet proti pasti u každého lomeného plamene jednotlivě.' AS pop
  UNION ALL SELECT 'Magický provaz' AS nazev, NULL AS uroven, '10 magů' AS mag, 'dotyk' AS dos, '1 kolo' AS sesl, 'jedno použití, max. 1 směna' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Chevel kesem. Past: Obr ~ −2 ~ nic/pád. Rozsah: 1 provaz nebo lano. Toto kouzlo lze seslat jen na provaz nebo lano nejdéle 50 sáhů. Nelze jej seslat na magické již magicky upravené provazy a na magicky vytvořené kouzlem. Ten, kdo drží v jednom konci lana, na něž byl seslán magický provaz, může přikázat, aby se někam připlo, aby se svázalo. Lano si vždy plaví po nějakém podkladu – třeba i kolmé stěně – a paklíže po sobě nechá uvázat či zachytit, musí si za to co. Zpravidla tedy není nemožné, ale i s pomocí kouzla a v některé úseky bez pevné vazby, ale mezi jednotlivými pevnými pevnými body nesmí být vzdálenost větší, než je polovina délky provazu. (Pozn.: Předchozí dva odstavce obsahují zjevně poškozený/přeházený text ze skenu — přepsáno v nejpravděpodobnější interpretaci se zachováním smyslu, bez tiché opravy.) Po provazu, na který je bylo toto kouzlo sesláno, je také mnohem snazší šplhat – v praxi znamená, že šplhající postava si hodí proti pasti uvedené parametry kouzla. Základní nebezpečnost, že šplhající postava spadne, snižuje o 1 za každých 200 mncí nákladu postavy. Po uplynutí jedné směny nebo smotání lana kouzlo pomine.' AS pop
  UNION ALL SELECT 'Metamorfóza II' AS nazev, NULL AS uroven, 'viz níže' AS mag, '0' AS dos, '1 kolo' AS sesl, 'podle dodané magenergie' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Acher. Rozsah: 1 tvor. Tímto kouzlem se může kouzelník proměnit v libovolného existujícího nemagického tvora, kterého musel ve svém životě již alespoň jednou vidět (třeba v věrohodném obrázku). Na směnu metamorfózy potřebuje 10 + životaschopnost tvora × 2 × (rozdíl třídy velikosti + 1) magů (rozdíl třídy velikosti je vždy kladný, a to i tehdy, když se kouzelník mění ve tvora, který je menší než on sám). PŘÍKLAD: PŘÍKLAD: Elf kouzelník se chce proměnit v orla královského. Kouzelník je velikosti B a je na 12. úrovni, orel C a jeho životaschopnost je 10. Na směnu působení tohoto kouzla spotřebuje minimálně: 10 + 10 × 2 × (1 + 1) = 50 magů. Rozdíl velikostí může být maximálně 2 třídy (ale postava velikosti A až C se v žádném případě nemůže proměnit na tvora velikosti A0 nebo D a větší). Pro vlastnosti a schopnosti po proměně platí totéž jako u kouzla metamorfóza. Kouzelník může kouzlo z vlastní vůle bez vynaložení magenergie ukončit i v době jeho trvání.' AS pop
  UNION ALL SELECT 'Mluv s mrtvými' AS nazev, NULL AS uroven, '10 magů za kolo' AS mag, 'dotyk' AS dos, '1 směna' AS sesl, 'podle dodané magenergie' AS trv, 'nevycerpavajici' AS un, 'Původní/magické jméno: Diber im metom. Past: viz níže. Rozsah: 1 mrtvola. Tímto kouzlem může kouzelník mluvit s mrtvými inteligentními tvory. Po jeho seslání si kouzelník hodí proti pasti: použitá vlastnost je Int+Chr+Žvt, nebezpečnost je počet hodin, který uplynul od smrti bytosti. PŘÍKLAD: PŘÍKLAD: Mág Ulax má charisma 20 a inteligenci 21 a je 21. úrovně. Při hodu proti pasti si ke k10 přičte 13 (= 4 za charisma + 5 za inteligenci + 4 za svoji životaschopnost), a tudíž může bez problémů mluvit až 14 hod mrtvými bytostmi. Uspěje-li mág v hodu proti pasti, může kouzlo prodlužovat přidáním další magenergie a nemusí si již proti pasti hazet. Mrtvý tvor mluví jako zaživa – proto musí být jeho hlasové ústrojí zachovalé (není například možné rozprávět s někým, komu usekli hlavu). Není také možné mluvit s někým, kdo byl po smrti změněn v nemrtvého. Mrtvý tvor má stejnou povahu, jako měl zaživa. Může kouzelníkovi lhát, spílat nebo se s ním může odmítnout bavit.' AS pop
  UNION ALL SELECT 'Močálové světýlko' AS nazev, NULL AS uroven, '2 magy za směnu, 1 za každou…' AS mag, '15 sáhů' AS dos, '2 kola' AS sesl, 'podle dodané magenergie' AS trv, 'vycerpavajici' AS un, 'Magenergie (přesně): 2 magy za směnu, 1 za každou další. Původní/magické jméno: Or baboc. Rozsah: koule o poloměru 5 sáhů. Kouzlo vytvoří kouli chladného světla o poloměru 5 sáhů, které svítí i nezteněnou intenzitou i pod vodou. Kouzelník může světlem libovolně pohybovat, nejdéle však do 20 sáhů od sebe. Přestane-li se kouzelník o močálové světýlko starat, přesune se tak, že bude bude kráčet v jeho středu. Toto kouzlo lze vyvolat pouze v přítomnosti většího množství vody (láhev rozhodně nestačí), jež musí nejvýše 15 sáhů daleko. Po vyvolání se kouzelník může již vody libovolně vzdálit.' AS pop
  UNION ALL SELECT 'Najdi teleport' AS nazev, NULL AS uroven, '1 mag za 100 sáhů' AS mag, '0' AS dos, '1 směna' AS sesl, 'ihned' AS trv, 'nevycerpavajici' AS un, 'Původní/magické jméno: Timce knisa. Rozsah: 1 teleport. Tímto kouzlem může kouzelník najít směr k nejbližšímu teleportu. Podle množství magenergie, které mu ubude v případě nalezení, může odhadnout, jak daleko teleport je.' AS pop
  UNION ALL SELECT 'Napísknání si' AS nazev, NULL AS uroven, '1 a více magů' AS mag, '5 sáhů' AS dos, '1 směna' AS sesl, '3 hodiny' AS trv, 'nevycerpavajici' AS un, 'Původní/magické jméno: Bore kolšehu. Rozsah: 1 předmět (viz níže). Pomocí tohoto kouzla si může kouzelník vyčarovat jeden nemagický předmět. Platí, že 1 zlatý ceny předmětu = 1 mag. Cena závisí na místě, kde je kouzlo sesíláno. Cena lahve vody je jiná v obchodě v hlavním městě a jiná v poušti. Napísknaný předmět však musí vyhovovat následujícím omezením: (Pozn.: Věta o zbraních a nehledění na materiál obsahuje viditelně poškozený text ze skenu — přepsáno v nejpravděpodobnější interpretaci se zachováním smyslu.) Vyčarovaný předmět, který vyhovuje všem omezením, zmizí po uplynutí tří hodin nebo v okamžiku, kdy se od něj kouzelník vzdálí dále než 5 sáhů, nebo se od vody, když je kouzelník do země. (Pozn.: Poslední věta obsahuje viditelně poškozený text ze skenu — přepsáno doslovně, smysl nejasný, bez tiché opravy.) Kouzlo napísknat si je velmi obtížným kouzlem materiální magie. Pokud jej bude kouzelník chtít použivat, bude muset znát nejméně 8 dalších materiálních kouzel – to proto, aby měl představu, na jakém principu toto kouzlo pracuje.' AS pop
  UNION ALL SELECT 'Neviditelná torna' AS nazev, NULL AS uroven, '5 magů za vyvolání torny + 1…' AS mag, '0' AS dos, '1 kolo' AS sesl, 'viz níže' AS trv, 'vycerpavajici' AS un, 'Magenergie (přesně): 5 magů za vyvolání torny + 1 mag za každé vložení. Původní/magické jméno: Kis bilti rauj. Rozsah: 1 "torna". Toto kouzlo stvoří jakousi neviditelnou "mimoprostorovou kapsu", kterou má kouzelník vždy po ruce. Může do ní ukládat předměty, které ihned po uložení přestanou být vidět. Rozměr žádného nesmí být větší než 60×30×30 coulů. Do torny se vejde obsah s maximální váze 1 000 mn, tyto předměty kouzelníka nijak nezatěžují a jejich váha se nepočítá do kouzelníkova nakládaní. Předmět, jenž by při ukládání těchto 1 000 mn převýšil, se do torny neuloží, do vkládaného předmětu přijde nazmar, torna se protrhne a kouzlo bude zrušeno. Všechny věci, které jsou v torně uloženy, se rozsypou kolem. Pokud je torna prázdná, za 1 směnu kouzlo pomine, jinak trvá, dokud je v ní něco uloženo. Torna plyne normálním způsobem času a předmět se ocitne v tom samém prostředí (teplo, vlhkost), v jakém byl těsně před vložením do torny, takže například jídlo se do torny může zkazit. Do torny může být uložen živý tvor nejvýše velikosti A0. V případě, že do torny bude ukládán větší živý tvor (například kopromlask), kouzelník spotřebuje 1 mag – bez jakýchkoli následků na tornu propadne na zem. Vkládání předmětu z torny k výběru předmětu z torny trvá 1 kolo (v rozšířeném soubojovém systému 1 akce jiná činnost), má-li kouzelník volnou ruku, a má 100 % pravděpodobnost úspěchu; v podstatě se nejedná o kouzlení, takže se za to kouzelník nepotřebuje soustředit. Je možno vkládat a vytahovat některé předměty najednou (truhlice s věcmi, opasek s dýkami), v takovém případě se počítá magenergie za jeden případě. Vložený předmět nelze uvnitř torny dělit na menší díly – musí být vytažen v tomtéž složení, jako byl dovnitř vložen. Stejné tak s předměty uvnitř neviditelné kapsy nedá nijak manipulovat. Nelze tedy například otevřít truhlici nebo vytáhnout dýku z pouzdra. (Pozn.: Odstavec o ukládání větších tvorů obsahuje viditelně poškozený text ze skenu — přepsáno doslovně, smysl nejasný, bez tiché opravy.) Kouzlo je vázáno na kouzelníka, a pokud je zabit, kouzlo pomine a obsah torny se rozsype kolem. Kouzlo může být sesláno i pomocí kouzelného předmětu – i v tom případě je kouzlo vázáno na sesilatele-majitele předmětu. Pokud kouzelný předmět, pomocí něhož byla neviditelná torna vyvolána, ztratí (prodá, půjčí, je mu ukraden...), může nadále věci z torny jen vybírat – není-li sám kouzelník ovládající kouzlo neviditelná torna, neboť pro vkládání věcí potřebuje magenergii (a pochopitelné znalost kouzla). Kouzelník může vyvolánu maximálně 1 tornu. Další pokus o vyvolání neviditelné torny bude automaticky neúspěšný, i kdyby byl proveden pomocí kouzelného předmětu. Pomocí jednoho kouzelného předmětu lze sice seslat více neviditelných toren, ale každou na jinou osobu – nikdo nemůže mít u sebe více než jednu neviditelnou tornu. Při vloženi jednoho pytle beztíže do neviditelné torny dochází k interakci magických a mimoprostorových jevů, což má za následek únik démona z pytle do jeho mateřské astrální sféry. Promění-li se kouzelník pomocí metamorfózy v nějakou nestvůru (nebo pomoci magie nějak změní svůj tvar) a má při tom vyvolanou neviditelnou tornu, může ji během trvání metamorfózy používat, pokud na to má potřebné končetiny. (Pozn.: Popis kouzla "Kouzlo spánku" se v této pasáži PPE přerušuje uprostřed věty (patrně vypadlá strana skenu) a jeho pokračování nebylo ve zdroji nalezeno — kouzlo je zde ponecháno neúplné, bez tiché domýšlené opravy.)' AS pop
  UNION ALL SELECT 'Neviditelná zbroj' AS nazev, NULL AS uroven, 'viz níže' AS mag, '0' AS dos, '1 kolo' AS sesl, 'podle dodané magenergie' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Chamuš bilti rauj. Rozsah: dle dodané magenergie. Tímto kouzlem může čaroděj zvýšit svoji KZ v závislosti na dodané magenergii. Tabulka zbroje ukazuje, kolik magenergie na jednu směnu trvání kouzla musí kouzelník vydat, aby se KZ zvedla o požadovaný počet.' AS pop
  UNION ALL SELECT 'Odzbrojení' AS nazev, NULL AS uroven, '10 magů za 1 zbraň nebo štít' AS mag, '30 sáhů' AS dos, 'podle dodané magenergie' AS sesl, 'ihned' AS trv, NULL AS un, 'Původní/magické jméno: Achar teš. Past: Sil ~ 4 − úroveň démona ~ 0. Toto zaklínadlo vyrazí terči, který neuspěl v hodu proti pasti, z ruky všechny zbraně včetně štítu (případně jiné předměty, které drží v ruce – například flakónek nebo pár rukavic, kterou má postava navlečenou). Oběť je proti pasti házet za každou zbraň i štít zvlášť. Zbraň, štít či jiný předmět je odhozen 2–4 sáhy daleko od majitele. Kouzelník se může rozhodnout, které věci chce protivníkovi vyrazit. Dodáním další magenergie může také zvýšit nebezpečnost pasti, ale pro všechny přidané věci stejně. Za každé přidané 2 magy za každou věc se nebezpečnost zvýší o 1.' AS pop
  UNION ALL SELECT 'Ohniví koně' AS nazev, NULL AS uroven, '30 magů za 1 kus a směnu' AS mag, '10 sáhů' AS dos, '1 kůň = 1 kolo' AS sesl, 'podle dodané magenergie' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Susej eš. Rozsah: podle dodané magenergie. Tímto kouzlem se vytvoří plamenný kůň (nebo i celé stádo – podle dodané magenergie). Jeho existence je omezena na 1 směnu a kůň se může po tuto dobu pohybovat maximální rychlostí 80 mil/hod, může tudíž proběhnout trasu dlouhou maximálně 13 mil. Vše, čeho se dotkne, může vzplanout. Pokud chceš, můžeš koně vyvolat i na delší dobu; za každou směnu navíc a každého koně musíš přidat dalších 30 magů. Tito koně jsou hmotní, a proto mohou způsobit škody i svými kopyty (rozdupat půdu, pobořit ploty…). V případě vyvolání více koní najednou se objeví všichni současně po celkové době vyvolávání a zmaterializují se (přestože jsou hmotní) i ve vzduchu asi 1 sáh nad zemí – proto, aby nezapálili bezprostřední okolí kouzelníka. Je možno zadávat i poměrně složité příkazy (jejich inteligence je 15/4+2) a celou trasu nemusejí proběhnout po zemi, ale část mohou proběhnout i vzduchem (případně i celou trasu). Ohniví koně jsou zranitelní pouze kouzelnými zbraněmi, dále kouzly ledový blesk a bílá střela a obyčejnou vodou (postupuj jako při útoku svěcenou vodou). Všichni ohniví koně mají životaschopnost rovnu počtu směn trvání kouzla, jednu úroveň životů každého koně je roven jeho životaschopnosti.' AS pop
  UNION ALL SELECT 'Ohnivý bič' AS nazev, NULL AS uroven, '25 magů' AS mag, '0' AS dos, '1 kolo' AS sesl, '10 kol' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Marduc eš. Rozsah: jeden bič. Kouzelník si tímto kouzlem vyvolá na ruce "ohnivý bič", kterým může útočit na nestvůry vzdálené až 7 sáhů. "Bič" má základní SZ 4, k ÚČ má místo obvyklého bonusu za sílu započítává bonus za obratnost. Při úspěšném zásahu není obránce zraněn klasickým způsobem, ale je popálen a zraněn za 3–18 životů. Při obraně proti "ohnivému biči" si postava nezapočítává svoji kvalitu zbroje, pokud je však zasažena, od výsledného zranění se kvalita zbroje odečte. Tímto "bičem" se dá útočit pouze na první postavu (nestvůru) v daném směru, pravidla pro boj s "bičem" jsou stejná jako pravidla pro střelecký souboj, nedá se s ním útočit na postavu, která je kryta nějakou jinou postavou.' AS pop
  UNION ALL SELECT 'Orlí oči' AS nazev, NULL AS uroven, '7 magů' AS mag, 'dohled do 10 mil' AS dos, '1 kolo' AS sesl, '1 směna' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Ejnaim nešer. Pomocí tohoto kouzla vidí kouzelník ve vzdálenosti 10 mil. Věci vzdálené 1 míli vidí, jako by byly vzdáleny jen 100 sáhů, věci vzdálené 10 mil, jako by byly 1 míli daleko. Pokud se musí dívat na věci do vzdálenosti 100 sáhů, vidí vše moc rozmazaně. Pro kouzelníka to znamená, že má při činnostech vztahujících se k věcem v této vzdálenosti, k nimž používá zrak, postih −50 % na postřeh, −3 k hodům proti pastem a −3 k ÚČ a OČ. Kouzlo nelze během trvání bez vynaložení magenergie přerušit.' AS pop
  UNION ALL SELECT 'Pamatuj' AS nazev, NULL AS uroven, '5 magů' AS mag, 'dotyk' AS dos, '1 kolo' AS sesl, 'stálé' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Tiskor. Past: Int ~ 4 ~ viz níže. Rozsah: 1 kouzlo, situace, osoba, vyprávění, úkon apod.. Po seslání tohoto kouzla si tvor, který uspěl v hodu proti pasti, vryje hluboko do paměti 1 příběh, heslo, tvář, situaci, obraz apod. a to do nejmenších detailů. Nic z toho však nesmí trvat déle než 6 kol. Nebezpečnost pasti lze snížit o 1 za každé 3 magy vložené navíc. Jestliže kouzelník nesesílá pamatuj na sebe, musí s tím terč kouzla souhlasit, a tak si však musí proti pasti i kouzlo se povede, jen když uspěje. U postav, které se sesláním kouzla na sebe nesouhlasí, se proti pasti ani hazet nemusí – kouzlo se nezdaří automaticky. Pozor! Při příliš častém používání tohoto kouzla se může stát, že dotyčná postava začne zapomínat jiné věci, a může to dojít tak daleko, že postava zešílí.' AS pop
  UNION ALL SELECT 'Pavéza' AS nazev, NULL AS uroven, 'podle úvahy kouzelníka' AS mag, '0' AS dos, '1 kolo' AS sesl, '3 kola' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Magen. Rozsah: oblast před kouzelníkem (jeho šířka × výška). Toto základní zabrání fyzickému útoku skrz bariéru na kouzelníka (jak při boji tváří v tvář, tak při střeleckém souboji), pokud útočník nehodí na útok více než dvojnásobek pravděpodobnosti úspěchu kouzla. Pokud ano, útok projde v nezmenšené síle. Pavéza zastaví každé sesílané kouzlo skrz bariéru na kouzelníka, na které bylo použito méně magenergie, než na její seslání, avšak silnější kouzla přijdou skrz bez omezení. Je samozřejmé, že všechny tyto výhody se vztahují pouze na útoky vedené zepředu. Pavéza také snižuje na polovinu pravděpodobnost úspěšného sesílání kouzla, které kouzelník sesílá skrz bariéru.' AS pop
  UNION ALL SELECT 'Pekelný oheň' AS nazev, NULL AS uroven, '15 magů' AS mag, '30 sáhů' AS dos, '1 kolo' AS sesl, '4–6 kol' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Eš šeol. Rozsah: 10 sáhů čtverečních. Po seslání tohoto kouzla vytryskne z kouzelníkovy ruky ohnivý paprsek, který jím určeném místě vybuchne prudkým ohněm a rozlije se po hořící louže s povrchem 10 čtverečních sáhů – kouzelník sám určuje jejich rozložení (mohou tvořit obdélník či kaňku, avšak celá plocha pekelného ohně musí být v dosahu kouzla). Jedná se o oheň s velmi vysokou teplotou, který zraňuje v každém kole za 6–15 životů. Pekelný oheň má stejnou pravděpodobnost, že něco zapálí, jako zápalná puma (na podrobnosti se zeptej nějakého pyrofora). Je-li na stejné místo seslán pekelný oheň v době, kdy na něm již jiný hoří, účinky kouzel se nesčítají, ale prodlouží se doba trvání.' AS pop
  UNION ALL SELECT 'Pírko' AS nazev, NULL AS uroven, '5 magů za první směnu, 4 za…' AS mag, 'dotyk' AS dos, '1 kolo' AS sesl, 'podle dodané magenergie' AS trv, 'vycerpavajici' AS un, 'Magenergie (přesně): 5 magů za první směnu, 4 za každou další. Původní/magické jméno: Teha kel. Rozsah: 1 předmět. Libovolný nemagický předmět, na nějž je toto kouzlo sesláno, bude o 1 000 mn lehčí. Na jeden předmět je možné kouzlo seslat i vícekrát, ale je jeho váha nikdy neklesne pod 10 % původní váhy. Pírko zbavuje předměty váhy, nikoli hmotnosti (podobně jako démon nosič, kterého vyvolává theurg). Díky tomu nemá vliv na útočné číslo zbraní.' AS pop
  UNION ALL SELECT 'Plošný hyperprostor' AS nazev, NULL AS uroven, '5 + magenergie za vzdálenost…' AS mag, 'podle dodané magenergie' AS dos, '1 kolo' AS sesl, 'ihned' AS trv, 'vycerpavajici' AS un, 'Magenergie (přesně): 5 + magenergie za vzdálenost x počet osob. Původní/magické jméno: Tykach kulam bjachat. Rozsah: 5 sáhů. Při seslání tohoto kouzla budou přemístěni všichni, kdo s tím souhlasí a kdo se nacházejí do vzdálenosti 5 sáhů od kouzelníka, na jím zvolenou vzdálenost. Kouzelník nemůže z působnosti kouzla nikoho vyjmout – ani sebe a sám pochopitelně musí se svým přemístěním souhlasit. "Magenergie za vzdálenost" je do vzdálenosti 100 sáhů za každých 10 sáhů 1 mag, na 100 sáhů 2 magy, na 200 sáhů 3 magy, na vzdálenost, na kterou se přenese kouzelník. Kouzelník nemusí znát místo, kam se chce přemístit, pak však musí použít dvakrát víc magenergie. Rozměry místa, kam se chce přemístit, musejí souhlasit s rozměrem postav s kouzelníkem přemísťovaných. "Magenergie za vzdálenost" na místě je za je zapotřebí 185 (= 5 + (10+20+30) × 3) magů. Kouzelník nemůže nikoho někam teleportovat a sám s sebou právě on nese své okolí – vždy s sebou nese své okolí. PŘÍKLAD: PŘÍKLAD: Na plošný hyperprostor kouzelníka a jeho dvou přátel na vzdálenost 300 sáhů je zapotřebí 185 (= 5 + (10 + 20 + 30) × 3) magů.' AS pop
  UNION ALL SELECT 'Pomocníci' AS nazev, NULL AS uroven, '1 skřítek = 1 mag' AS mag, '0' AS dos, '1 směna' AS sesl, 'maximálně 24 hodin' AS trv, 'nevycerpavajici' AS un, 'Původní/magické jméno: Ozrim. Rozsah: kruh o poloměru 100 sáhů. Po vyvolání tohoto zaklínadla povstanou ze země skřítci – stavitelé. Skřítci i jejich nářadí jsou z hlíny, ale jim neubírá na výkonnosti. 1 skřítek vykoná za jeden den práce v hodnotě 5 zlatých. Jsou schopni postavit cokoliv, i celé město (když má někdo potřebnou magenergii). Skřítci postaví jen to, co dokážou postavit civilizovaní tvorové v té které době! Pomocníci pouze pracují. To znamená, že materiál musejí mít jakýkoli k dispozici, sami si ho z hlíny nevyčarují. Jejich práce samozřejmě může spočívat i v přípravě materiálu, který najdou ve svém dosahu, a jeho zhodnocení (aby byl použitelný pro další zpracování/stavbu). Takže například jablka v lese jsou schopni vyrobit stavební dříví. Mohou tedy vykonávat i jinou fyzickou práci, než přímo stavbu konkrétního objektu. Třeba i bourat stavby, ale formou rozebírání, ne útočení. Zabitý skřítek se okamžitě změní v hromádku hlíny. Skřítci mají sílu 10, obratnost 14, inteligenci 9 (ovšem v záležitostech týkajících se jejich stavitelské práce je to 16), charisma 10, pohyblivost 11, 1 život a životaschopnost 1. Jsou to magičtí tvorové, takže se nemohou unavit a nemá smysl se zmiňovat o jejich odolnosti a vytrvalosti. Skřítci mají OČ 1, ovšem ze všech sil se snaží boji vyhnout a nikdy neútočí. Jsou asi 30 coulů vysocí, umějí mluvit, normálně vidí a slyší, ale nemají žádné zvláštní smysly nebo schopnosti (například infravidění). Skřítci jsou zranitelní běžnými zbraněmi a běžnými mechanickými útoky, fyzickými kouzly a bílou střelou. Pokud se kouzelník vzdálí z oblasti působení kouzla, kouzlo skončí (ale v ní třeba spát). Ani skřítci se nemohou z této oblasti vzdálit, jinak se změní v hromádku hlíny. Kouzlo rovněž skončí, jakmile skřítci vykonají zadanou práci a nedostanou další příkazy. Skřítci jsou schopni (a ochotni) vykonávat pouze fyzickou práci, nelze je tedy využít například ke střežení tábora.' AS pop
  UNION ALL SELECT 'Portál' AS nazev, NULL AS uroven, '100 : úroveň kouzelníka + 5…' AS mag, 'vstupní portál – do 5 sáhů výstupní portál –…' AS dos, '5 kol' AS sesl, '3 kola' AS trv, NULL AS un, 'Magenergie (přesně): 100 : úroveň kouzelníka + 5 (+ viz níže). Dosah (přesně): vstupní portál – do 5 sáhů výstupní portál – úroveň kouzelníka : 2 mil. Původní/magické jméno: Šaar. Rozsah: vstupní a výstupní portál. Tímto zaklínadlem se vytvoří dva portály – magické brány (vstupní a výstupní) o rozměrech 2×1 sáh. Vstupním i výstupním portálem lze v době trvání kouzla procházet oběma směry. Při vyvolávání se portály objeví podle přání kouzelníka v okruhu jeho dosahu jako zářící obdélník ve vzduchu volně v prostoru nebo z základní stojící na zemi či jako součást zdi. Podmínkou je, že jej musí při vyvolávání vidět (tedy pouze ten vstupní). Pakliže kouzelník vyvolává výstupní portál na místě, které nezná, musí přidat dalších 10 magů. Pokud a v tomto případě vytvoří výstupní portál do pevné hmoty (podobné jako u kouzla hyperprostor), bude kdokoli, kdo se jím bude snažit projít, zraněn za 1–6 životů a zůstane na místě. Postava nevidí prostor za výstupním portálem, dokud jím neprostrčí hlavu. Bezpečně může portálem projít jen první osoba. Každá další osoba má pravděpodobnost úspěšného projití o 10 % menší (druhá osoba má pravděpodobnost 90 %, třetí 80 % atd.). Portál po třech kolech pohasne, nezáleží na tom, zda jím někdo prošel či nikoliv. V případě, že postavě padne neúspěch v procházení, ocitne se kdekoli v dosahu kouzla (podle úvahy PJ). Pravděpodobnost úspěchu pro další postavu se sníží ihned po vstupu té předchozí do portálu – nezáleží tedy na tom, zda postava portálem prošla, nebo se od nej nakoukla a vrátila se zpět. Kouzlení skrz portál možné je. Ovšem nejprve musí kouzlící postava po portálu částečně vstoupit, tak aby byla dostatečnou částí těla (hlava, paže, přední část trupu) za ním a alespoň poloviční kouskem (třeba patou) před ním. Pak může seslat kouzlo a poté se musí vrátit. V rozšířeném soubojovém systému to znamená, že první kouzelník potřebuje na vstup do portálu, pak několik akcí (například dvě u jednokolového kouzla) kouzlí a následující akci použije na ústup z portálu. V základním soubojovém systému lze uvažovat, že první kolo souboje opatrně vstupuje do portálu, v dalších kouzlí a rychle se stahuje zpět (tentokrát již v nulovém čase).' AS pop
  UNION ALL SELECT 'Posel' AS nazev, NULL AS uroven, '20 magů za vyvolání + 1 za…' AS mag, '5 sáhů' AS dos, '6 kol' AS sesl, 'viz níže' AS trv, NULL AS un, 'Magenergie (přesně): 20 magů za vyvolání + 1 za každých 25 mil cesty k cíli. Původní/magické jméno: Malach. Rozsah: 1 drozd. Kouzelník tímto kouzlem stvoří posla-drozda, kterému může zadat (nadiktovat) určitou libovolnou zprávu a popsat mu osobu, které má být doručena. Dozvěd poletí rychlostí 55 mil/hod a za každých 25 mil cesty je pravděpodobnost 1 %, že bude drakem uloven. Pokud k tomu nedojde, dotyčnou osobu najde a zprávu jí sdělí (buď je přesně reprodukovat hlasem kouzelníka), poté se rozplyne. Nebude-li hledaná osoba do doletu drozda (podle dodané magenergie), kouzelník si hodí k % k a tak zjistí, kolik mil ještě drozd schopen uletět (hod00 = 100 mil). Nedoletí-li drozd k hledané osobě ani tak, rozplyne se ve vzduchu. Kouzelník musí znát místo, kam přijme zprávy naléz je jaká "posla" kouzlem; kouzelník pouze dodá dostatek magenergie. Kouzelník neví, zda byla zpráva doručena či nikoliv. Je-li hledaná osoba od posla oddělena nepřekonatelnou překážkou hmotného rázu (podzemní kobka), bude drozd poletovat okolo a nakonec zprávy nedoručí. Nedoletí-li drozd k hledané osobě ani tak, rozplyne se ve vzduchu. Kouzelník musí místo nemá zas žádný takto zadávat v poměrně slo- žité příkazy (jejich inteligence je 15/4+2) a celou trasu nemusejí proběhnout po zemi, ale mohou proběhnout i vzduchem (případně i celou trasu). (Pozn.: Tento popis Posla obsahuje viditelně poškozený/přeházený text ze skenu ve druhé polovině hesla — pravděpodobně došlo k duplikaci vět z jiného hesla (Ohniví koně) v předloze. Přepsáno doslovně dle skenu, bez tiché opravy.)' AS pop
  UNION ALL SELECT 'Povolej bytost' AS nazev, NULL AS uroven, '10 + (ÚČ + 2) + (2×OČ + 2)…' AS mag, '100 sáhů' AS dos, '2 kola' AS sesl, 'max. 20 kol' AS trv, 'vycerpavajici' AS un, 'Magenergie (přesně): 10 + (ÚČ + 2) + (2×OČ + 2) magů. Původní/magické jméno: Bo. Rozsah: 1 magická bytost. Tímto nesmírně mocným kouzlem může kouzelník stvořit jednu magickou bytost na svoji obranu. Takto povolaná nestvůra může vypadat různě, ale bude vždy přízračná, přesto však hmotná, a její životaschopnost bude maximálně taková, jaká je úroveň kouzelníka (může být i menší, ale magenergie kouzla se tím nijak neovlivní). Jaká budou ÚČ a OČ nestvůry, určí vždy kouzelník, který ji sesílá kouzla dodáním příslušné magenergie. Velikost nestvůry odpovídá přibližně jejich životaschopnosti a udává ji Tabulka bytostí. Po úspěšném vyvolání kouzla získá kouzelník naprosto oddaného ochránce, jehož údaje jsou následující: Velikost: podle životaschopnosti (viz výše) Životaschop.: libovolná, max. však jako úroveň kouzelníka ÚČ: podle dodané magenergie OČ: podle dodané magenergie Pohyblivost: 20/magický tvor Inteligence: 11 Charisma: 10 Síla: bonus za sílu = ÚČ : 10 Obratnost: bonus za obratnost = OČ : 10 Odolnost: 25 Přesvědčení: neutrální Takto vyvolaná bytost ihned zaútočí na kouzelníkem zvolené tvory a bude v této činnosti pokračovat, dokud kouzelník neodvolá (nejdéle však 20 kol – poté okamžitě zmizí (i pokud nestačila splnit kouzelníkem zadaný úkol). Během této doby se bytost nesmí vzdálit více než 100 sáhů od kouzelníka, jinak okamžitě zmizí. Útok bytosti se považuje za útok obyčejnou zbraní. Povely bytosti může kouzelník zadávat mentálně, tak hlasem. Při smrti sesilatele kouzlo končí. Toto kouzlo má jedno úskalí – bude-li kouzelníkem povolaná bytost v tomto světě zabita, je určitá pravděpodobnost, že kouzelník zahyne s ní. V takovém případě se kouzelníkovo tělo zhroutí za života z kemene. Pravděpodobnost tohoto jevu dostaneš, když životaschopnost bytosti vynásobíš deseti. Kouzelník neví, kolik životů jim povolaná bytost přesně má, ale může jí nechat být kterou bude chtít. Bytost je zranitelná pouze magickými zbraněmi a stříbrnými kouzly, zejména bílou střelou.' AS pop
  UNION ALL SELECT 'Procházení zdí' AS nazev, NULL AS uroven, '20 magů' AS mag, 'dotyk' AS dos, '2 kola' AS sesl, '1 směna' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Avarat kir. Rozsah: 1 tvor. Příjemce tohoto kouzla může volně procházet zdí a i podobnými objekty, a to rychlostí 1 sáh a kolo. Ve zdi vidět a není možné tam dýchat (asi jako ve vodě). Jestliže se tvor ve zdi zůstane ve chvíli, kdy kouzlo pomine, zahyne. Tvor, na něhož bylo sesláno procházení zdí, s tím musí souhlasit a nemůže procházet ničím, co je menší než on, ani ničím živým. Je tedy nezasažitelný pohybujícími se předměty (zejména zahazujícími se předměty (meče, šípy apod.).' AS pop
  UNION ALL SELECT 'Průchodná zeď' AS nazev, NULL AS uroven, 'viz níže' AS mag, 'dotyk' AS dos, '1 kolo' AS sesl, 'podle dodané magenergie' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Kir over. Rozsah: podle dodané magenergie. Tímto kouzlem lze zprůchodnit jakoukoli zeď, která nemá magickou podstatu a je z neživého materiálu. Zeď lze zprůchodnit jen přímým směrem, lhostejno, zda vodorovně či šikmo. Základní magenergie za vyvolání kouzla je délka × šířka × výška tunelu (v sázích). K té je třeba přičíst 1 mag za každé kolo trvání kouzla. Po seslání kouzla zůstane iluze zdi, která bude průchodná jakýmkoliv odporem. Po uplynutí doby trvání kouzla se zeď opět uvede do původního stavu. V případě, že ve zprůchodněné zdi bude nacházet nějaký tvor v okamžiku vyprsení kouzla, zahyne. Bude-li v ní nacházet jiný předmět, zůstane tam zazděn.' AS pop
  UNION ALL SELECT 'Přetvělení' AS nazev, NULL AS uroven, '2×úroveň kouzelníka + 5' AS mag, '0' AS dos, '10 kol' AS sesl, 'viz níže' AS trv, NULL AS un, 'Původní/magické jméno: Gilgul. Rozsah: 1 tělo. K tomuto zaklínadlu potřebuje kouzelník tělo nemagického tvora mrtvého nedéle 24 hodin, kterého může dotknout. Po seslání zaklínadla přenese Duše kouzelníka do nového těla a původní tělo k zemi (tělo není mrtvé, ale vypadá tak, dokud se do něj Duše kouzelníka nenavrátí). Kouzelník neví, kolik životů jim novém těle bude přesně mít, ale ponechává si vlastní paměť a inteligenci. Též mu zůstávají všechny zvláštní schopnosti kouzelníka. Kouzelník se může kdykoliv vrátit do svého starého těla, musí se ho ovšem dotknout. Tento návrat nestojí žádnou magenergii a trvá jedno kolo, během kterého se kouzelník musí soustředit podobně jako při kouzlení. Opuštěné tělo se hroutí k zemi, už definitivně mrtvé. Pokud se do něj Duše do 24 hodin nevrátí, začíná původní tělo postupně chřadnout. Každý den mu ubude 2–7 životů, které nepůjdou žádným způsobem vyléčit do doby, než se vrátí kouzelníkova Duše zpět. Když klesnou životy ve starém těle kouzelníka na nulu nebo níže, pokládá se to tělo za mrtvé a k návratu musí kouzelník použít další přetvělení. Pokud je kouzelník v novém těle zraněn nebo zabit, přenese se jeho Duše zpět do původního těla a kouzelník ztrácí (1–3) × úroveň životů. Zabití či smrt původního těla kouzelník okamžitě pozná. Způsobí mu to totiž obrovský šok, který má za následek, že jeho úroveň v novém těle klesne na polovinu (zaokrouhluj nahoru) se všemi důsledky z toho vyplývajícími. Navíc se vlastnosti nového těla (kromě inteligence) začnou postupně přizpůsobovat tomu, že jeho povoláním kouzelník (například patřilo-li tělo válečníkovi, sníží se síla a odolnost) – přesná pravidla pro to má PJ. Pokud se Duše kouzelníka vrátí zpět do svého původního těla (například novým použitím přetvělení) do 24 hodin od jeho smrti, vrátí se kouzelníkovi jeho úroveň, v opačném případě se snížení trvale.' AS pop
  UNION ALL SELECT 'Přežij' AS nazev, NULL AS uroven, '1 mag za vyvolání + 2 magy…' AS mag, 'dotyk' AS dos, '3 kola' AS sesl, 'tolik směn, jaká je úroveň sesílajícího kouzelníka' AS trv, 'vycerpavajici' AS un, 'Magenergie (přesně): 1 mag za vyvolání + 2 magy za každý "vyléčený" život. Původní/magické jméno: Tišaer bchajim. Past: Int ~ 8 ~ 0. Rozsah: 1 tvor. Tímto kouzlem lze dočasně navrátit odebrané životy odebrané zraněním. Zranění tímto kouzlem není skutečně vyléčeno – příjemce kouzla pouze své zranění necítí a není jím postihován. Po vypršení doby trvání kouzla se příjemce zranění obnoví v plném rozsahu se všemi následky z toho vyplývajícími. Je možné, že během trvání kouzla postava dále zraněna, takže pokud pak kouzlo přestane působit, klesne její počet životů pod nulu, postava okamžitě zemře. Postavu je samozřejmě možné během působení kouzla léčit, ať už kouzly, lektvary nebo léky. Tímto kouzlem nelze odstraňovat zranění, které má jinou podstatu než fyzickou (tedy způsobené kouzlem nebo magickými nestvůrami). Proti pasti si musejí házet i ti, kteří si přejí, aby na ně kouzlo bylo sesláno.' AS pop
  UNION ALL SELECT 'Schodiště' AS nazev, NULL AS uroven, '10 magů za 20 sáhů schodiště…' AS mag, '0 (od kouzelníkových nohou)' AS dos, '1 kolo' AS sesl, 'podle dodané magenergie' AS trv, 'vycerpavajici' AS un, 'Magenergie (přesně): 10 magů za 20 sáhů schodiště + 2 magy za každých 5 navíc. Původní/magické jméno: Madregot. Po seslání tohoto kouzla se pod kouzelníkovýma nohama při každém kroku zhmotní jeden stupeň schodiště, jehož délku určí kouzelník při seslání kouzla. Schodiště může mít libovolný sklon do 45° a sklon i po délce kouzla měnit, může dokonce přejít ze stoupání do klesání. Schodiště bude 2 sáhy široké a bude vypadat jako obyčejné kamenné schodiště. Kouzelník jej může přidáním 1 magu za každých započatých 10 sáhů délky zneviditelnit. Každý schod vydrží jedno kolo od okamžiku, kdy na něj kouzelník poprvé stoupne. Prodloužit dobu trvání kouzla na kouzelník tak, že se každé kolo, o které chce dobu prodloužit, musí přidat 1 mag za každých započatých 10 sáhů celkové délky schodiště.' AS pop
  UNION ALL SELECT 'Smrtící déšt' AS nazev, NULL AS uroven, '50 magů' AS mag, NULL AS dos, '2 kola' AS sesl, '15 kol' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Hagešen hahoreg. Past: Roz ~ 10 ~ 0. Rozsah: kruh o poloměru 7 sáhů. Kouzelník začne vytvářet černozelený mrak. Po skončení vyvolávání začne z mraku dopadat na zem magický déšt, který zraňuje každého, kdo neuspěje v hodu proti pasti, za 2–20 životů za kolo (proti pasti si háže každý živý tvor, na kterého kouzlo dopadá, a to v každé kole bez ohledu na to, zda v minulém kole uspěl v hodu proti pasti). Zasažená oblast je kruh o poloměru 7 sáhů (asi 154 čtverečních sáhů), jehož střed při vyvolání kouzla nesmí být dál než 250 sáhů od kouzelníka. V době trvání kouzla se mrak již může od kouzelníka vzdálit libovolně. Při určování zranění nerozhoduje, jak je zasažený tvor veliký – stačí, je-li deštěm zasažen (drak je zraněn stejně jako třeba hobit). Střed zasažené oblasti lze fixovat buď: a) Na jednu postavu. Tato postava mraku nemůže utéci a střed mraku mu bude vždy nad hlavou. Spolu s touto postavou budou zasaženi i všichni (sesilatele kouzla nevyjímaje), kdo se v daném kole nacházejí ve vzdálenosti nejvýše 7 sáhů od ní. Jedinou nadějí postiženého tvora je vzdálenost větší než 250 sáhů – mrak a s ní ztratí kontakt a bude se pohybovat posledním směrem rychlostí 30 sáhů a kolo, dokud "nevyprší" doba trvání. b) Na místo (mrak se bude po celou dobu trvání kouzla vznášet na místě). c) Volný pohyb mrakem. Kouzelník může libovolně pohybovat mrakem rychlostí 50 sáhů a kolo. Na to se musí soustředit, nepovažuje se však za kouzlení, ale nemůže bojovat, vést mentální souboj ani provádět jinou činnost. Pokud něco z toho dělá a na pohyb mrakem se nesoustředí, mrak se chová jako v případě a). Na mrak působí obvyklým způsobem vítr. Je-li na místě, kde kouzelník smrtící déšt sesílá, větrno, je třeba zvýšit magenergii kouzla o 5 magů. Tím kouzelník dosáhne toho, že mrak nebude ovlivněn vítrem ani síle bouře.' AS pop
  UNION ALL SELECT 'Smrtící koule' AS nazev, NULL AS uroven, '30 magů' AS mag, '50 sáhů' AS dos, '1 kolo' AS sesl, 'viz níže' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Hakadur hahoreg. Past: Roz ~ 8 ~ 0. Rozsah: 1 tvor. Kouzelník vytvoří zářivou žlutou kouli, která se zhmotní 30 coulů nad svou budoucí obětí s nějakou vlastní magenergií, koule je začne vstřebávat rychlostí 2 magy za kolo až do jejího úplného vyčerpání. Po vstřebání všech magů koule spustí i vybuchne silou 1–6 životů za každé 3 vstřebané magy (průměr výbuchu je 2 sáhy a jeho obětí je hlava oběti). Koule se po celou dobu trvání kouzla pohybuje společně se svou obětí, a to i dokonce i tehdy, když kouzelník, který ji seslal, zemře nebo bez ní na ni seslána roztyl kouzla. Koule zmizí tehdy, když kouzelník, který ji seslal, zemře nebo bez ní na ni seslána roztyl kouzla. Jestliže zamýšlená oběť není kouzelníkovi nebo momentálně bez magenergie, koule se po pěti kolech bez následků rozplyne. Toto kouzlo není vzhledem k nemalému množství spotřebované magenergie příliš efektivní a používá se hlavně při rituálních kouzelnických soubojích, kdy oba sokové na počátku souboje sešlou smrtící kouli na svého protivníka.' AS pop
  UNION ALL SELECT 'Soví oči' AS nazev, NULL AS uroven, '12 magů' AS mag, 'dotyk' AS dos, '2 kola' AS sesl, '1 směna' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Ejnaim gefram. Rozsah: 1 postava. Pomocí tohoto kouzla může postava vidět po tmě stejně jako ve dne. Účinnost kouzla závisí na tom, jaká je tma: Naprostá tma (tma na místě zasaženém kouzlem, neosvětlené nic pod nikoli): vidí normálně Hustá tma (tma o bezvětrné noci, v hustém lese): je vidět nezřetelné, ale boj v noci má postih pouze −1. Tma (slabě svítí hvězdy, řídký les): je vidět obstojné, není žádný postih. Řídká tma (měsíc v úplňku): je vidět naprosto ostře a zřetelné. Pološero (soumrak k večeru či za ránem): příliš jasné světlo pro použití tohoto kouzla, uživatele má postih k boji −1. Světlo svíčky nebo malé lampy je příliš jasné, postih k boji −1. Světlo lucerny pro svou intenzitu dává postih k boji −2 a vyvolává bolest. Sluneční světlo je nesnesitelně jasné, postava má v boji postih −4 a při chůzi ji někdo musí vést. Jasný záblesk způsobuje zranění za 1–6 životů a na 3 kola oslepí.' AS pop
  UNION ALL SELECT 'Sprav' AS nazev, NULL AS uroven, '15 magů' AS mag, 'dotyk' AS dos, '2 kola' AS sesl, 'ihned' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Taken. Rozsah: 1 předmět. Toto kouzlo umí spravovat nemagické předměty. Může třeba zašít roztržený oděv, spravit rozbité boty, zacelit prasklý pohár atd. Kouzlo v žádném případě neumí spravit předměty rozdělené na více kusů (třeba i na dva) a neumí ani scelovat zlomené zbraně či zničené předměty (např. vybuchlá bomba, roztříštěný dřevec). Toto kouzlo neumí spravovat poškozené mechanismy, a to z toho důvodu, že mechanismus se skládá z více součástí. Bude-li tedy chtít čaroděj kupříkladu kuši, musí upřesnit, kterou její část chce opravit. Toto kouzlo je možné seslat na zbraně, aby je zbavilo rezu, nečistot a vyhladilo drobné zuby na ostří. A jím také možné opravit zbraně poškozené například při vyrážení dveří nebo při souboji. Nebyla-li zbraň zcela zničená, kouzlo ji sprav dokonale spraví.' AS pop
  UNION ALL SELECT 'Sršatec' AS nazev, NULL AS uroven, '26 magů' AS mag, '20 sáhů' AS dos, '1 kolo' AS sesl, 'ihned' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Ofanim. Past: Obr ~ 8 ~ vyhnutí se/zásah. Rozsah: vše v níže uvedeném území. Po seslání tohoto kouzla vyletí z kouzelníkovy ruky třpytící se bílé koule s průměrem asi 10 coulů, která se pohybuje rychlostí 20 sáhů za kolo. Po sázích letu z ní zasáhne se bílé výbuchy do vzdálenosti jednoho sáhu, které zraňují a to v (v 2 sázích širokém pásu, jehož středem sršatec letí) za 1–10 životů. Kromě toho s sebou sršatec nese ještě energetický náboj, který v místě střetu s cílem po vybuchne rychlostí koulí bleksů o poloměru 2 sáhy a zraní v každém kole za 22–40 životů. Tento náboj během letu ztrácí na síle, a proto se od jím způsobeného zranění odečítá 1 život a každý sáh, který sršatec uletěl. Sršatec lze vesla seslat pouze v prvním směru – to znamená, že kouzelník jej sešle po přímce či určitým směrem. Pokud je cílem živý tvor, může se sršatci pokusit uhnout (viz past uvedená v hlavičce). V případě, že se mu cíli úspěšně vyhnout, prolétne kolem něj, zraní jej jen za 1–10 životů po dvacet sázích letu. Nebezpečnost pasti lze zvýšit o 1 za a další 4 magy navíc. Náboj, který s sebou nese sršatec, se však aktivuje až po 8 sázích letu – střetne-li se tedy sršatec s nějakou překážkou, dříve než náboj aktivuje, k žádnému konečnému výbuchu nedojde a sršatec na místě zanikne.' AS pop
  UNION ALL SELECT 'Světelný most' AS nazev, NULL AS uroven, 'viz níže' AS mag, '0 (od kouzelníkových nohou)' AS dos, '3 kola' AS sesl, 'podle dodané magenergie' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Gešer or. Rozsah: dle dodané magenergie. Jedná se o most stvořený z čistého světla, který překlene skoro jakoukoli propast či průrvu. Magenergie potřebná na vyvolání mostu záleží na jeho délce a době trvání. Každých 10 sáhů délky mostu stojí 5 magů a každá 2 kola trvání 1 mag. Šířka mostu je vždy 1 sáh. PŘÍKLAD: PŘÍKLAD: Na vyvolání 20 sáhů dlouhého mostu na 10 kol bude zapotřebí 15 magů. Most je schůdný jen pro živé tvory. Neživé předměty, které nenese někdo živý, mostem propadnou, jako by tam nebyl. Kouzelník může z působnosti kouzla vyjmout nějaké postavy nebo rasy (budou jej vidět, ale nebude na něj moci vstoupit) – nahmatají jenom prázdno. Za každou postavu nebo rasu vyjmutou z působnosti kouzla se magenergie potřebná na jeho seslání zvýší o 5 magů. Toto kouzlo je velmi efektivní, pokud družinu pronásleduje horda skřetů.' AS pop
  UNION ALL SELECT 'Světlonoš' AS nazev, NULL AS uroven, '3 magy za první směnu, 2…' AS mag, '20 sáhů, pohyb jako kouzelník' AS dos, '2 kola' AS sesl, 'podle dodané magenergie' AS trv, 'vycerpavajici' AS un, 'Magenergie (přesně): 3 magy za první směnu, 2 magy za každou další. Původní/magické jméno: Menora. Rozsah: 5 sáhů. Tímto kouzlem se vytvoří do 20 sáhů od kouzelníka koule světla o průměru 5 sáhů. Tato koule se pohybuje s kouzelníkem a poslouchá jeho myšlenkové příkazy. Světlo pohybuje nejvýše rychlostí 5 mil/hod, nemůže se vzdálit dál než 20 sáhů od kouzelníka. Pokud mu kouzelník uteče nebo ujede, světlo zmizí. Dobu trvání kouzla určuje kouzelník při vyvolání kouzla a dále se již na ni nemusí soustředit (ani na pohyb světlem po okolí). Po uplynutí předem stanovené doby není možné kouzlo prodloužit – kouzelník jej musí seslat znovu.' AS pop
  UNION ALL SELECT 'Šenkýř' AS nazev, NULL AS uroven, '1–4 magy (+1 mag za lepší…' AS mag, '5 sáhů' AS dos, '1 kolo' AS sesl, 'úroveň kouzelníka : 2 směn' AS trv, 'vycerpavajici' AS un, 'Magenergie (přesně): 1–4 magy (+1 mag za lepší pohár). Původní/magické jméno: Pundakaj. Past: Int ~ 9 ~ 0. Rozsah: 0,5 l nápoje. Tímto kouzlem může kouzelník za 1 mag stvořit půl litru nealkoholického nápoje (např. sklenici vody), za 2 magy půl litru slabě alkoholického nápoje (např. holbu piva), za 3 magy půl litru alkoholického nápoje (např. pohár vína) a za 4 magy může stvořit stejné množství silného alkoholického nápoje (např. pohár medoviny). Alkoholem je možné se opít a vodou zahnat žízeň a problémy spojené s dehydratací, ale jen po dobu trvání, pak účinky pominou. Pro lepší stolování může kouzelník přidat ještě jeden mag a vytvořit v lepším poháru či číši. Po dopití však všechny takto vyvolané nádoby (ať už obyčejné nebo luxusní) do 3 kol zmizí. Nápoj a jeho chuť budou přesně podle představ kouzelníka. Nesmí být jedovatý, otrávený ani jinak zdravotně závadný. Pochopitelně se jedná jenom o iluzi. Jeho účinek je jen krátkodobý, po dobu uvedenou v trvání je tělo zcela přesvědčeno o zahnání žízně – počítá se to, jako by se tvor opravdu napil a příslušné postihy při dehydrataci. Avšak po skončení trvání všechny postihy vracejí, jako by nic nepil. Tímto kouzlem tedy nelze oddálit dehydrataci, pouze na nějakou dobu ono strádání znevinní. Postava, která uspěla v hodu proti pasti, pozná, že jedná o iluzi; nápoj nezažene její žízeň, neodstraní dehydrataci, a pokud se nenapije, bude mít pocit, že nic nepila.' AS pop
  UNION ALL SELECT 'Temný úder' AS nazev, NULL AS uroven, '5 + (maximální počet životů…' AS mag, '30 sáhů' AS dos, '1 kolo' AS sesl, 'ihned' AS trv, 'vycerpavajici' AS un, 'Magenergie (přesně): 5 + (maximální počet životů kouzelníka × 2) magů. Původní/magické jméno: Maka šachora. Rozsah: 1 tvor. Po seslání tohoto kouzla vyletí z kouzelníkovy dlaně paprsek energie, který cíl zraní za tolik životů, kolik je momentální počet životů kouzelníka. Oběť je zároveň vržena zpět o 1 sáh za každých načatých 10 životů svého zranění. Není-li za ní místo, je navíc zraněna za jeden život za každý sáh, o který nemohla být vržena zpět. Pokud je postava vržena zpět aspoň o 2 sáhy, spadne a musí jedno kolo vstávat (v rozšířeném soubojovém systému jsou 2 akce). Během této doby se nemůže bránit štítem ani zbraní a nemůže kouzlit ani útočit. Zásah temným úderem je automatický.' AS pop
  UNION ALL SELECT 'Tlampač' AS nazev, NULL AS uroven, '10 magů + 5 magů za každou…' AS mag, '0' AS dos, '2 kola' AS sesl, '1 směna' AS trv, 'vycerpavajici' AS un, 'Magenergie (přesně): 10 magů + 5 magů za každou míli navíc. Původní/magické jméno: Ramatkol. Rozsah: území o poloměru 2 mil a více. Tímto kouzlem může kouzelník nechat svůj hlas znít volně z prostoru nad určitým územím. Při tomto kouzlu "hlasitost" žádný střed, kouzelníkův hlas je v zasaženém území tak hlasitý, jako by mluvil ke každému posluchači (i nedobrovolnému) z bezprostřední blízkosti.' AS pop
  UNION ALL SELECT 'Tlumočník' AS nazev, NULL AS uroven, '5 magů za směnu' AS mag, 'dotyk' AS dos, '1 směna' AS sesl, 'podle dodané magenergie' AS trv, 'nevycerpavajici' AS un, 'Původní/magické jméno: Metargem. Rozsah: 1 tvor. Toto kouzlo umožní inteligentnímu tvorovi (inteligence musí být alespoň 2) mluvit a rozumět jedním určitým jazykem (kromě řeči draka). Tímto jazykem bude mluvit stejně dobře jako vlastním jazykem a psát alespoň v jednom jazyce, rozumí i psaným textům. Toto kouzlo nepřeloží zašifrované texty. Jazyk může být specifikován dvojím způsobem. Buď je to jazyk obecně známý, který má své jméno (například turečtina v našem světě), nebo kouzelník určí, jazyku "kterým hovoří tato bytost", "kterým je psána tato kniha". Kouzelník například nemůže chtít rozumět nejrozšířenějšímu jazyku Zapomenuté země, když Zapomenutá země je oblast, o níž nikdo nic neví, ani to, jakými jazyky se tam hovoří.' AS pop
  UNION ALL SELECT 'Třpytivá zář' AS nazev, NULL AS uroven, '35 magů' AS mag, '0' AS dos, '2 kola' AS sesl, 'ihned' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Zohar mavrik. Past: Obr ~ 9 (11) ~ 0. Rozsah: koule o poloměru 150 sáhů. Po seslání tohoto kouzla se prostorem kouzelníka na krátkou, nesmírně ostrou zář vyplní intenzivní záře. Všichni tvorové v rozsahu kouzla, kteří se nevyhnuli pasti s nebezpečností 9, jsou 1–6 kol oslepeni (oslněni) a zraněni prudkým světlem za 1–6 stínových životů, avšak nesmrtelně zraněn – každou zůstane alespoň 1 život. Ti, kdo uspěli v hodu proti pasti s nebezpečností 9, ale nepřekonali nebezpečnost 11, zraněni nejsou, ale jsou natolik oslněni, že mají 1–6 kol postih −3 na boj (v obranu i útok). Postavám, které uspěly i proti pasti s nebezpečností 11, neublíží. Je-li toto kouzlo sesláno v noci nebo za tmy, nebezpečnost pasti se zvyšuje o 2–3 (určí PJ). Z působnosti tohoto kouzla není možné nikoho vyjmout (výjimkou tvoří samotný kouzelník), a kouzelník musí varovat své přátele, aby zavřeli oči (nejlépe zakryli si je rukama). V takovém případě při úspěchu v hodu proti pasti neublíží. Kouzlo způsobí osvětlení celého prostoru (jako kdyby vzduch světloval), proto na před bleskem například ke stínu nebo pouhým otočením se zády ke kouzelníkovi.' AS pop
  UNION ALL SELECT 'Uhas' AS nazev, NULL AS uroven, '1 mag za sáh²' AS mag, '50 sáhů' AS dos, '1 kolo' AS sesl, 'ihned' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Chabe. Rozsah: dle dodané magenergie. Tímto kouzlem je možné uhasit libovolně velký požár nemagického původu, který není živen zvenčí. Je jím například možné uhasit hořící dům, ale ne sopku.' AS pop
  UNION ALL SELECT 'Ukliď' AS nazev, NULL AS uroven, '10 magů' AS mag, '5 sáhů' AS dos, '2 kola' AS sesl, '1 kolo' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Sider. Rozsah: kruh o poloměru 5 sáhů. Toto kouzlo uspořádá předměty v prostoru podle přání kouzelníka. Kouzlo například uklidí stůl, srovná knihovnu, urovná drobné předměty a umí i setřít prach. Nedokáže však přestavovat nábytek či jinak hýbat s objemnými a těžkými věcmi. Kouzelník ovšem musí vědět, jak mají věci být uspořádány, nestačí pouze kouzlo vyvolat a čekat, že se nějak dopadne. Vlastní úklid či přeuspořádání předmětů probíhá velmi rychle (asi 1 kolo, podle míry nepořádku), přesto však během trvání kouzla nikdy nedojde k poškození žádného předmětu.' AS pop
  UNION ALL SELECT 'Usni' AS nazev, NULL AS uroven, '(2×životaschopnost + 1) za…' AS mag, '20 sáhů' AS dos, '1 kolo' AS sesl, '2–7 směn' AS trv, 'vycerpavajici' AS un, 'Magenergie (přesně): (2×životaschopnost + 1) za každého tvora. Původní/magické jméno: Tašem. Past: Roz + Odl ~ 5 ~ 0. Rozsah: podle dodané magenergie. Tvor, na kterého je toto kouzlo sesláno, si musí hodit proti výše uvedené pasti. Ten, kdo této pasti nevyhne, usne hlubokým spánkem na 2–7 směn. Během této doby je možné ho probudit pouze kouzlem zlom kouzlo (nebo rozptyl kouzla). Kouzlo lze seslat i na více postav najednou.' AS pop
  UNION ALL SELECT 'Velké ochranné kouzlo' AS nazev, NULL AS uroven, 'nejméně 16 magů' AS mag, '0' AS dos, '5 kol' AS sesl, '10 hodin' AS trv, NULL AS un, 'Původní/magické jméno: Kesem gadol hamehagen. Past: podle dodané magenergie. Rozsah: kruh o poloměru 10 sáhů. Tímto zaklínadlem kouzelník vytvoří neviditelnou kulovou bariéru o poloměru 10 sáhů, jejíž střed bude tam, kde se nachází on při vyvolávání kouzla. Bariéra brání komukoliv ve vstupu do kopule. Kouzlo není možné vyvolat tak, aby se jeho kopule s kopulí jiného velkého ochranného kouzla prolínala, byť ho vyvolal stejný kouzelník. Základní past, kterou si háže tvor vstupující dovnitř, je Roz+Sil ~ 8 ~ projde/neprojde. Nebezpečnost pasti se zvyšuje o 1 za každé 3 magy vložené nad základní hodnotu magenergie. Pro magické tvory je nebezpečnost této pasti poloviční (zaokrouhluje se dolů). Postavy, které se nacházejí uvnitř při vyvolávání kouzla, mohou bez problémů opustit, pokud se ale budou chtít vrátit, musí úspěšně čelit pasti. Jestliže kouzli opustit kouzelník, bariéra zmizí a zaklínadlo předčasně skončí. Pokud bude někdo uvnitř bariéry stříleny nebo vrhat zbraněmi, mají všichni uvnitř bonus +7 k OČ. Tento bonus však neplatí v opačném směru – k opuštění kopule vrhané zbraně prochází vše bez zábran. Výjimkou jsou zásahy: ta mají v obou směrech poloviční pravděpodobnost úspěchu.' AS pop
  UNION ALL SELECT 'Vidění dvojmo' AS nazev, NULL AS uroven, '6 magů' AS mag, '50 sáhů' AS dos, '1 kolo' AS sesl, '5 kol' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Rejaik kfula. Past: Roz ~ 8 ~ 0. Rozsah: 1 postava. Postava zasažena tímto kouzlem šilhá – vidí dvojmo – a při boji má postih −3 na útok i na obranu. Toto kouzlo lze seslat pouze na tvory se dvěma očima.' AS pop
  UNION ALL SELECT 'Vidění skrze zeď' AS nazev, NULL AS uroven, '9 magů' AS mag, '0' AS dos, '2 kola' AS sesl, '1 směna' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Rederech kir. Rozsah: až 3 sáhy tlustá zeď. Po seslání tohoto kouzla může kouzelník 6 kol hledět skrze zeď z neprůhledného materiálu, jejíž maximální tloušťka je 3 sáhy, jako by se díval skrze sklo. Kouzlo však neumožňuje procházení světla skrz zeď – pokud je tedy za zdí tma, uvidí kouzelník pouze tmu. Toto kouzlo neumožňuje slyšet zvuky za zdí. Po dobu trvání kouzla se kouzelník nesmí hýbat z místa, může však otáčet hlavou.' AS pop
  UNION ALL SELECT 'Všeronikání' AS nazev, NULL AS uroven, '55 magů' AS mag, '0' AS dos, '2 kola' AS sesl, '1 směna' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Taavor. Rozsah: jen kouzelník. Pod vlivem tohoto kouzla může kouzelník procházet čímkoli a cokoli může procházet skrze něj. V této podobě je zranitelný jen kouzly, ohněm a magickými zbraněmi, kde se počítá pouze démon (SZ a útočnosti zbraně mu k SZ a útočnosti kouzleného démona). Kouzelníkem neprochází nic, o čem kouzelník nechce, aby jím procházelo. Může tedy normálně sedět, jíst, atd., nemůže se však rozhodnout, že část jedné věci jím procházet bude a druhá část téže věci ne. O každé věci musí rozhodovat jako o celku ještě předem. Stav všeronikání nelze měnit v okamžiku, kdy již je kouzelníkově tělo aspoň zčásti v jiné věci. Jestliže se kouzelník nalézá uprostřed nějakého pevného předmětu ve chvíli, kdy kouzlo přestane působit, zahyne.' AS pop
  UNION ALL SELECT 'Vzpomeň' AS nazev, NULL AS uroven, '15 magů' AS mag, 'dotyk' AS dos, '1 kolo' AS sesl, 'ihned' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Schor. Past: Int − 4 ~ 0 nebo Roz+Int ~ 8 ~ 0. Rozsah: 1 tvor. Prostřednictvím tohoto kouzla si lze velmi podrobně vzpomenout na jednu situaci, osobu, jméno, heslo a podobně. To se podaří všem, kdo uspějí v hodu proti první uvedené pasti. Kouzlem vzpomeň je také možné zrušit účinky kouzla zapomeň. V takovém případě si cíl kouzla háže druhé s parametrem uvedenou pasti a v rozdíl se bere rozdíl mezi úrovní kouzelníka, který seslal zapomeň, a kouzelníka, který sesílá vzpomeň. V případě úspěchu jsou účinky kouzla zapomeň zrušeny.' AS pop
  UNION ALL SELECT 'Zapomeň' AS nazev, NULL AS uroven, '15 magů' AS mag, '10 sáhů' AS dos, '1 kolo' AS sesl, 'stálé' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Tiškach. Past: Roz+Int ~ 5 ~ 0. Rozsah: 1 tvor. Pokud terč neuspěje v hodu proti pasti nebo se sesláním kouzla na sebe souhlasí, zapomene na jednu věc, osobu, heslo, situaci, kouzlo a podobně. Toto zaklínadlo je pravým opakem kouzla pamatuj. Jeho účinky lze zrušit kouzlem vzpomeň, zlom kouzlo a rozptyl kouzla. Na postavu, která uspěla v hodu proti pasti, není možné seslat zapomeň podruhé v souvislosti se stejnou věcí. Toto zaklínadlo je možné použít k tomu, že kouzelník zapomene jedno ze svých zaklínadel a při přestupu na vyšší úroveň místo něj může naučit nějaké jiné. Nedoporučuje se však takto postupovat příliš často, může to totiž vést k poruše paměti (posuzuje PJ).' AS pop
  UNION ALL SELECT 'Zapůjčení' AS nazev, NULL AS uroven, '5 + 2×životaschopnost cíle' AS mag, '100 sáhů' AS dos, '3 kola' AS sesl, 'úroveň kouzelníka × směn' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Tašíl li. Rozsah: 1 nemagický tvor. Po úspěšném seslání tohoto kouzla si může kouzelník "zapůjčit" tělo tvora s inteligencí 1 (ani vyšší ani nižší) na tolik směn, kolik je úroveň kouzelníka. Po tuto dobu může "zapůjčené" tělo volně používat se všemi jeho fyzickými vlastnostmi (může například jako pták létat), svoje schopnosti však ztrácí a nemůže dokonce ani mluvit lidskou řečí, zůstává mu pouze jeho inteligence a paměť. K návratu do vlastního těla může dojít, kdykoliv si to kouzelník přeje, ale zapůjčené tělo musí být blíž než 100 sáhů. Při překročení doby trvání kouzla si kouzelník háže proti pasti Int ~ 5 ~ prodloužení o 1 směnu/uvíznutí v zapůjčeném těle. Nebezpečnost pasti se každou směnou zvyšuje o 1. V případě uvíznutí se téměř okamžitě sníží kouzelníkova inteligence na 1/–5 a následky jsou stejné jako u duševního rozštěpu (včetně jejich léčení). Po dobu trvání kouzla zůstává kouzelníkovo tělo ležet v bezduchém spánku na místě, kde se nalézal při sesílání kouzla. Bude-li zabito, kouzelník automaticky uvízne v zapůjčeném těle. Uvíznutí v zapůjčeném těle dokážou navrátit jen druidi – jak, to vědí jen oni sami.' AS pop
  UNION ALL SELECT 'Zastav hraničáře' AS nazev, NULL AS uroven, 'poloměr² : 10' AS mag, '0' AS dos, '1 směna' AS sesl, '24 hodin' AS trv, 'nevycerpavajici' AS un, 'Původní/magické jméno: Tacor iš jaar. Rozsah: podle dodané magenergie. Po seslání tohoto kouzla není možné na zasaženém území sesílat žádná hraničářská kouzla a používat mimosmyslové schopnosti. Pokud se někdo o něco takového v okamžiku, kdy kouzlo bylo sesláno, pokouší, je jeho pokus automaticky neúspěšný a vložená magenergie přijde nazmar. Zastav hraničáře ochrání i před hraničářskými kouzly, která byla seslána z vnějšku do chráněného území. Kouzelník, který zastav hraničáře seslal, může kouzlo kdykoliv zrušit. Může ho také prodloužit o další den, a to se musí 1 kolo soustředit a odevzdat stejné množství magenergie, jaké použil na jeho seslání. Musí se také nacházet uvnitř zasažené oblasti. Potřebnou magenergii dostaneš, když poloměr zasaženého území (v sázích) vynásobíš ještě jím samým a k výsledku přičteš deset. Zasažené území se nepohybuje s kouzelníkem, který z něj může odejít. PŘÍKLAD: PŘÍKLAD: Na zastavení hraničářů v kruhu o poloměru 10 sáhů je zapotřebí 10 magů. (Pozn.: Číselný příklad v předloze neodpovídá slovnímu vzorci "poloměr × poloměr + 10" (pro poloměr 10 by vyšlo 110, ne 10) — přepsáno doslovně dle skenu, bez tiché opravy.)' AS pop
  UNION ALL SELECT 'Zastav kouzla' AS nazev, NULL AS uroven, 'poloměr² + 20' AS mag, '0' AS dos, '1 směna' AS sesl, '24 hodin' AS trv, 'nevycerpavajici' AS un, 'Původní/magické jméno: Tafsik ksamim. Rozsah: podle dodané magenergie. Po seslání tohoto kouzla není možné na zasaženém území sesílat žádnou kouzelnická kouzla (ani pomocí démonů astrálních sfér), podrobovat nebo mentálně útočit. Pokud by někdo o něco takového v okamžiku, kdy kouzlo bylo sesláno, pokoušel, je pokus automaticky neúspěšný a vložená magenergie přijde nazmar. Kouzla seslaná před zastav kouzla nadále trvají a nejsou zrušena. Zastav kouzla ochrání i před kouzly, která byla seslána z vnějšku do chráněného území. Kouzelník, který zastav kouzla seslal, může kouzlo kdykoliv zrušit. Může ho také prodloužit o další den, a to se musí 1 kolo soustředit a odevzdat stejné množství magenergie, jaké použil na jeho seslání. Musí se také nacházet uvnitř zasažené oblasti. Potřebnou magenergii dostaneš, když poloměr zasaženého území (v sázích) vynásobíš ještě jím samým a k výsledku přičteš dvacet (zaokrouhluj nahoru). Zasažené území se nepohybuje s kouzelníkem, který z něj může odejít.' AS pop
  UNION ALL SELECT 'Zastrašení' AS nazev, NULL AS uroven, '22 magů' AS mag, '2 sáhy za úroveň kouzelníka' AS dos, '1 kolo' AS sesl, '10 kol' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Hartaa. Past: Roz+Int ~ 9 − počet tvorů ~ 0. Rozsah: tvorové s inteligencí 1 a vyšší. Pomocí tohoto zaklínadla může kouzelník získat ztracený respekt, popřípadě někoho zastrašit. Tvorům, kteří neuspěli v hodu proti pasti, se zdá, že kouzelník narostl do výšky tří sáhů a obklopila ho aura obklopeného divné energie a autority. Kouzlo působí na různé tvory různě, v závislosti na tom, o kolik se lišili jejich hod proti pasti a nebezpečnosti. 5 a více – smrtelný strach: bytost prchá a odhazuje vše, co jí překáží v útěku. Je pravděpodobnost 50 %, že zakopne a je zraněn za 1–6 životů. Na tuto pravděpodobnost házet každou dobu trvá útěku každou dobu, po tuto dobu trvá útěk. 4 – hrůza: bytost prchá a odhazuje vše, co jí překáží v útěku. 3 – silné znepokojení: bytost se bude snažit za každou cenu při jednání s kouzelníkem vyhnout souboji. 1 – znepokojení: bytost bude s kouzelníkem jednat velmi zdvořile a nesáhne k násilí, pokud to pro ni nebude nezbytně nutné. 0 – mírné neklidnění: bytost účastně pozoruje kouzelníka. méně než 0 – příjemné rozptýlení: bytost pozoruje snažícího se kouzelníka a dobře se baví. Kouzelník může podle svého uvážení z působnosti kouzla kohokoliv vyjmout. PŘÍKLAD: PŘÍKLAD: Mág Zak je na 15. úrovni a sešle zastrašení na kouzelníka Ariazela (12. úroveň, inteligence 19/+4) a válečníka Bextera (12. úroveň, inteligence 5/–3). Ariazelovi padne na kostce 3, Roz je −3, bonus na inteligenci +4, nebezpečnost pasti je 7. Ariazel tedy k hodu proti pasti neuspěl, a to o 3. Pociťuje tedy silné znepokojení. Bexter hodí na kostce 10, po úpravách je to 4, tedy také neuspěl o 3 a je rovněž silně znepokojen.' AS pop
  UNION ALL SELECT 'Zhasni' AS nazev, NULL AS uroven, '1 mag za 1 sáh vzdálenosti' AS mag, '20 sáhů' AS dos, '1 kolo' AS sesl, 'ihned' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Chabe menora. Rozsah: koule o poloměru 5 sáhů. Po seslání tohoto kouzla zhasne oheň do velikosti dvou loučí.' AS pop
  UNION ALL SELECT 'Zmrzlý blesk' AS nazev, NULL AS uroven, '25 magů' AS mag, '200 sáhů' AS dos, '1 kolo' AS sesl, 'do jedné směny' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Barak kafu. Rozsah: koule o průměru 5 sáhů. Toto kouzlo vytvoří v blízkosti kouzelníka zářivě oranžovou kouli o průměru 25 coulů (osvětlí prostor do dvou sáhů), která je na omak ledově studená. Kouzelník ji může ovládat jako levitující či kutálející se balón až do vzdálenosti 200 sáhů od sebe. Její rychlost je nejvýše 50 sáhů za kolo. Kouzelník však musí nechat kouli nejpozději do jedné směny vybuchnout. Pokud tak neučiní, vybuchne po uplynutí této doby sama. Při výbuchu zraní vše v okolí dva a půl sáhu od středu výbuchu dohromady za 10–40 životů. Zranění se mezi zasažené dělí rovnoměrně. Během existence kouzla není zmrzlý blesk žádným způsobem zničit – obyčejné zbraně se o něj tupí jako o kámen a ani magické s ním nic nesvedou. Jediná možnost je seslat na něj kouzlo rozptyl kouzla.' AS pop
  UNION ALL SELECT 'Zpomalení' AS nazev, NULL AS uroven, 'životaschopnost' AS mag, '10 sáhů' AS dos, '1 kolo' AS sesl, '1–6 kol' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Lech leat. Past: Roz ~ 5 ~ 0. Rozsah: 1 tvor. Postava, na kterou je zpomalení sesláno, se pohybuje, útočí atd. s rychlostí o polovinu nižší, než jaký jejich rychlost před sesláním kouzla. V případě, že na jednu již zpomalenou postavu bude toto kouzlo sesláno podruhé, postava se více nezpomalí, pouze doba trvání kouzla se příslušně prodlouží. Ještě více zpomalit postavu postiženou tímto kouzlem lze jen sesláním kouzla protoplazma. Postava pod vlivem kouzla zpomalení bude mít v rozšířeném soubojovém systému postih −3 k hodu na iniciativu za každý útok, který má v základním soubojovém systému. V základním soubojovém systému má postava poloviční počet útoků a obran zbraní než obvykle. Má-li jeden útok na kolo, může útočit a bránit se zbraní pouze jednou za dvě kola. Má-li například tři útoky za dvě kola, může útočit a bránit se zbraní pouze třikrát za čtyři kola, to znamená, že v prvních třech kolech útočí (a brání se) jednou, ve čtvrtém (pokud je stále pod vlivem zpomalení) již útočí a brání se nemůže.' AS pop
  UNION ALL SELECT 'Zrcadlové kouzlo' AS nazev, NULL AS uroven, '25 magů' AS mag, '0' AS dos, '5 kol' AS sesl, 'viz níže' AS trv, NULL AS un, 'Původní/magické jméno: Mare. Rozsah: jen kouzelník. Kouzlo vytvoří okolo kouzelníka pole, jež pohltí jakýkoliv útok kouzlem tváří v tvář. Kouzlo trvá až do chvíle, kdy je na kouzelníka potřetí zaútočeno s hodem na útok vyšším než 15 – v takovém případě útok projde nezeslabeně nebo do přílišného zaostření vůle. Kouzelník nemůže během trvání kouzla na nikoho útočit v boji tváří v tvář, jinak kouzlo pomine.' AS pop
) v
JOIN seznamy_kouzel s ON s.nazev = 'Kouzla mága PPP'
JOIN povolani p ON p.id = s.povolani_id AND p.nazev = 'Kouzelník';
-- TODO ověřit proti skenu (neúplný/nejasný zápis v předloze u): Dubl; Najdi kouzla; Zesměšni; Cestář; Dlouhá ruka; Granátové jablko; Chlad hvězd; Jídlonoš; Kouzlo spánku; Magický provaz; Napísknání si; Neviditelná torna; Posel; Zastav hraničáře

-- Kouzla mága PPE / Čaroděj (2 kouzel)
INSERT INTO kouzla (nazev, seznam_kouzel_id, uroven_kouzla, cena_magenergie, dosah, doba_seslani, doba_trvani, typ_unavy, popis)
SELECT v.nazev, s.id, v.uroven, v.mag, v.dos, v.sesl, v.trv, v.un, v.pop
FROM (
  SELECT 'Najdi hůl' AS nazev, NULL AS uroven, '1 mag za každou míli…' AS mag, '0' AS dos, '1 kolo za 100 mil poloměru hledání (zaokr. nahoru)' AS sesl, NULL AS trv, 'vycerpavajici' AS un, 'Magenergie (přesně): 1 mag za každou míli poloměru hledání. Původní/magické jméno: Timce mate. Rozsah: pouze vlastní čarodějova hůl. Čaroděj za pomoci tohoto kouzla zjistí, kde se v tu kterou chvíli nalézá jeho hůl, tj. zjistí směr a přesnou vzdálenost. Nenaváže si s ní však trvalý kontakt, a pakliže bude hůl přenesena jinam, čaroděj o tom již vědět nebude.' AS pop
  UNION ALL SELECT 'Vezmi hůl' AS nazev, NULL AS uroven, '2 magy (14 magů)' AS mag, '20 sáhů' AS dos, '1 kolo' AS sesl, 'ihned' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: Kach mate. Rozsah: pouze vlastní čarodějova hůl. Čaroděj si tímto kouzlem teleportuje vlastní hůl přímo do ruky. Toto působí pouze na vzdálenosti 20 sáhů, tedy v rozsahu, ve kterém čaroděj ví přesně, kde se jeho hůl nachází. Potřebuje-li čaroděj svou hůl okamžitě, může k základní magenergii přidat "expresní" příplatek 12 magů a kouzlo proběhne tak rychle, že v tomto kole pouze ztratí iniciativu a bude moci seslat ještě běžné zaklínadlo. V rozšířeném soubojovém systému se to projeví postihem −3 k hodu na iniciativu.' AS pop
) v
JOIN seznamy_kouzel s ON s.nazev = 'Kouzla mága PPE'
JOIN povolani p ON p.id = s.povolani_id AND p.nazev = 'Čaroděj';

-- Kouzla nekromanta / Nekromant (11 kouzel)
INSERT INTO kouzla (nazev, seznam_kouzel_id, uroven_kouzla, cena_magenergie, dosah, doba_seslani, doba_trvani, typ_unavy, popis)
SELECT v.nazev, s.id, v.uroven, v.mag, v.dos, v.sesl, v.trv, v.un, v.pop
FROM (
  SELECT 'Poznej anatomii' AS nazev, NULL AS uroven, '9 (16)' AS mag, '20 sáhů' AS dos, '3 kola' AS sesl, 'ihned' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 tvor. Kouzelník určí cíl a kouzlo kompletně zjistí anatomické informace daného tvora. Kouzlo zjistí i anatomické informace druhého (popř. všech) pohlaví, ale nesmí se jednat o jedince, který se příliš liší od průměru, například pokud má nějakou výraznou vrozenou tělesnou vadu. Pokud je cíl chráněn nějakou formou magické ochrany, kouzlo se nepovede. Samotné kouzlo může cíl zaregistrovat jen jako drobné mravenčení, někdy ho nezaregistruje vůbec. Kouzlo nefunguje na mrtvá těla starší než směnu. Ve druhé fázi kouzlo zapíše získané informace. Buď je zakreslí a zapíše do připravené prázdné knihy nebo je může zapsat na libovolnou dostatečně velkou plochu (například na skalní stěnu) a to jazykem kterému kouzelník rozumí. Ovšem tomuto zapisování se musí kouzelník několik směn věnovat, kouzlo samo k tomu nemá a nemůže mít dostatečné schopnosti. Druhá verze kouzla (platí pro ni údaje v závorkách) informace prostě nalije kouzelníkovi do hlavy. Zní to opravdu krásně (obzvlášť když člověk studuje), ale není to tak bezproblémové, jaké bysme to chtěli. Kouzelník hází proti pasti Int-Odol ~ 4 ~ přijal / nepřijal (bonus za odolnost se odečítá protože tělo se snaží bránit, což vy se snažíte bonusem za inteligenci naopak potlačit). Pokud přijme, obdrží zranění 1k6 životů a ještě nejmíň den bude kouzelníka nesnesitelně bolet hlava. Množství poznaných tvorů nevyžaduje další pozice pro kouzla. Nekromant je pouze musí prostudovat, aby je poznal a mohl je dál ´´zpracovávat´´.' AS pop
  UNION ALL SELECT 'Ledový dech' AS nazev, NULL AS uroven, '6 magů za každý cíl' AS mag, '3 sáhy ve výseči 180 stupňů' AS dos, '1 kolo' AS sesl, 'ihned' AS trv, 'vycerpavajici' AS un, 'Rozsah: Dle dodané magenergie. Kouzelník otevře ústa a prudce vydechne. oblast kterou si zvolí zaplaví ledově chladná mlha. Která ale nijak neomezuje výhled. Zasažené postavy si hází proti pasti Roz, Sil., Odol. - 12- Zmražení na 1k6 kol/nic I když uspějí proti pasti, jsou všichni zranění za 2k6+2 chladem. Pokud na sobě mají luxusní zimní oblečení, tak obdrží zranění pouze 1k4+1.' AS pop
  UNION ALL SELECT 'Bouře kostí' AS nazev, NULL AS uroven, '2 magy za každý úlomek' AS mag, '15 sáhů' AS dos, '2 kola' AS sesl, 'Ihned' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 - 4 cíle. Za pomocí tohoto kouzla může nekromant použít libovolné kosti jako velmi ostré projektily. Množství úlomků, které nekromant může teoreticky získat z jedné kostry se odvíjí od její velikosti. Velikost A 1 - 20 úlomků Velikost B 1 - 40 úlomků Velikost C 1 - 60 úlomků Velikost D 1 - 120 úlomků Počet úlomků v případě že je kostra kompletní. Každý úlomek se počítá jako projektil a je možné se proti němu bránit kouzlem sraž projektily apod. Zranění za každý úlomek je 1k6. Do obrany se započítává pouze KZ cíle. Naráz může nekromant vyslat dvojnásobek své úrovně v úlomcích. nebo dokud má magy. Je možné užít i kostěnou zbroj, kterou má nekromant zrovna na sobě.' AS pop
  UNION ALL SELECT 'Drak nemrtvý, nižší' AS nazev, NULL AS uroven, NULL AS mag, 'dotek' AS dos, '14 hodin' AS sesl, 'stálé' AS trv, NULL AS un, 'Rozsah: 1 tvor. životaschopnost:jako drak Útočné číslo: jako drak -2 Obranné číslo: jako drak -1 síly mysli: 13 velikost: D zranitelnost: B,C,D,E,G,H,I,J,K,L,N pohyblivost: jako drak / magický tvor inteligence: 6 přesvědčení: jako nekromant Tuto formu nemrtvého můžete vyvolat z libovolné dračí mrtvoly libovolného stáří. Kostra ovšem musí být alespoň z 90% kompletní a nesmí být zásadně poškozena žádná zásadní část (samozřejmě nesmí ani chybět; např. páteř). Z toho plyne i vzhled budoucího nemrtvého, můžete ho oživit z pouhé kostry i z čerstvé mrtvoly a v rámci možností tak bude vypadat. Je pravděpodobné, že se nemrtvý bude ještě rozkládat a že nakonec stejně skončí jako kostlivec, nicméně ta doba nebude výrazně kratší, než jak dlouho by mu to trvalo, být normálně mrtvý. Nižší nemrtvý drak nemá ve své výbavě schopnost mluvit, ale příslušným kouzlem ho to můžete naučit. Jeho kritický neklid je 14. Pokud byl nemrtvý vyvolán z nevyschlé mrtvoly, je zde 70% možnost, že získal schopnost hniloba a pokud je na něm ještě nějaké maso (i suché), pak je 60% možnost, že získal schopnost dorůstání (stejnou jakou disponují běsi, podívej se na nemrtvá zvířata). Nemrtvý má tři útoky, dva pařáty a jeden tlamou. Nemrtvý drak nemá žádnou vlastní magenergii a neumí kouzlit, ale může být bez omezení na slunečním světle (s jedinou výjimkou, na slunci nefunguje schopnost dorůstání a regenerace, pokud ji má).' AS pop
  UNION ALL SELECT 'Drak nemrtvý, vyšší' AS nazev, NULL AS uroven, NULL AS mag, 'dotek' AS dos, '18 hodin' AS sesl, 'stálé' AS trv, NULL AS un, 'Rozsah: 1 tvor. životaschopnost: jako drak Útočné číslo: jako drak + 3 Obranné číslo: jako drak + 2 síly mysli: 21 velikost: D - E zranitelnost: C,D,E,G1/2,H1/2,I,J,K,L1/2,N pohyblivost: jako drak / vyšší inteligence: 17 přesvědčení: jako nekromant Tento nemrtvý je silnější obdobou Nižšího nemrtvého draka. Navíc je schopen kouzlit a má i několik dalšího výhod. K disposici má 50 magů na den a může kouzlit 20 kouzel, která mu vybere nekromant ze svého seznamu nebo z nějakého svitku či knihy. Umí mluvit, je vybaven schopností dorůstání a na 60% je ještě vybaven schopností regenerace. Můžete ho vyvolat jen z relativně mladé dračí mrtvoly, řádově nejvýše týdny, lépe však dny. Tento nemrtvý odpovídá nejlépe ghulovi ze základních pravidel nebo popř. běsu z těchto pravidel, nepodléhá dalšímu rozkladu. Kritický neklid tohoto nemrtvého je 18 a je také imunní vůči slunečnímu světlu, se stejnou výjimkou jako v předešlém případě. Stejný je i počet útoků - tři. Musíte umět zaklínadlo Nižší nemrtvý drak, abyste se mohli naučit tuto formu.' AS pop
  UNION ALL SELECT 'Strigoj, menší' AS nazev, NULL AS uroven, NULL AS mag, 'dotek' AS dos, '8 hodin' AS sesl, 'stálé' AS trv, NULL AS un, 'Rozsah: 1 tvor. životaschopnost: jako lykantrop Útočné číslo: jako lykantrop - 2 Obranné číslo: jako lykantrop - 2 síly mysli: 17 velikost: B a menší zranitelnost: C,D,E,G1/2,H,I,J1/2,k1/2,N1/2 pohyblivost: jako lykantrop / šelma ale neunaví se inteligence: jako lykantrop - 2 přesvědčení: zákoné zlo Tato velice zvláštní forma nemrtvého vznikla pokusy s oživováním mrtvých lykantropů. Při jejich oživování vznikl zajímavý efekt - jejich tělo zmutovalo do jakéhosi prostředníku mezi oběma jejich podobami. Podle dosavadních bádání je to způsobeno jejich magickou podstatou. Jsou to tvorové, jejichž samotná existence je do značné míry postavena na magické bázi a jejich dvojjatost se projeví v jakési posmrtné magické křeči, spuštěné znovupoužitím těla magickým zásahem jiného základu. Všeobecně jsou strigojové skutečně prapodivnými nemrtvými, zachovávají si ze všech nemrtvých nejvíce původní osobnosti a přesto se u nich nikdy neprojevilo žádné odolávání pánově vůli a to ani náznakem. Vzhledem připomínají nemrtvé zvíře s výraznými humanoidními rysy, kráčející zpravidla po dvou, ovšem při běhu si často dopomáhající předníma.Není výjimkou,že tesáky nebo pařáty jsou výrazně prodlouženy i oproti zvířecí (nemluvě o té lidské) podobě. Pro určení údajů v tabulkách použijte vždy tu lepší hodnotu z obou podob původního lykantropa. Výjimkou je velikost. Strigojovu velikost určete podle velikosti lykantropa v jeho zvířecí podobě. Pokud by ta byla větší než B, musíte použít zaklínadlo pro vytvoření většího strigoje. Strigojové jsou do značné míry snem každého nekromanta. Sice poměrně nároční, co se magenergie týče, nicméně ve všech ostatních směrech dokonalá nestvůra. Jsou silní, odolní, a inteligentní, přesto však dokonale věrní a oddaní, navíc ještě velice odolní vůči magii. Strigojové jsou výbornými kapitány a veliteli nemrtvých zvířat, samozřejmě je to obzvlášť výrazné, pokud se jedná o zvířata stejného druhu, jakého byl lykantrop. strigojové pro tyto účely získávají válečnickou schopnost velení. Pro všechny zvířata stejné rasy jako sám strigoj se strigojové považují, jakoby byli o 5 úrovní výš. Kritický neklid je 10. strigojové umí mluvit. Pobyt na slunci je každou směnu zraňuje za 1k10 životů. K oživení tohoto nemrtvého je třeba velice čerstvé tělo - řádově nejvýše hodiny staré.' AS pop
  UNION ALL SELECT 'Strigoj, větší' AS nazev, NULL AS uroven, NULL AS mag, 'dotek' AS dos, '10 hodin' AS sesl, 'stálé' AS trv, NULL AS un, 'Rozsah: 1 tvor. životaschopnost: ako lykantrop Útočné číslo: jako lykantrop - 1 Obranné číslo: jako lykantrop - 1 síly mysli: 19 velikost: C zranitelnost: C,D,E,G1/2,H,I,J1/2,k1/2,N1/2 pohyblivost: jako lykantrop / šelma ale neunaví se inteligence: jako lykantrop - 1 přesvědčení: zákoné zlo Pro vyvolání velkého strigoje platí stejné podmínky jako pro vyvolání menšího strigoje a musíte také umět vyvolat menšího strigoje, abyste se mohli naučit tuto formu. Rozdíly jsou pouze v tabulce a tom, že většího strigoje lze vyvolat jen z mrtvého lakantropa, který měl ve zvířecí podobě velikost C nebo D. Jeho kritický neklid je 12.' AS pop
  UNION ALL SELECT 'Nemrtvý obr' AS nazev, NULL AS uroven, NULL AS mag, 'dotek' AS dos, '10 hodin' AS sesl, 'stálé' AS trv, NULL AS un, 'Rozsah: 1 tvor. životaschopnost: 8 Útočné číslo: 10 + 6 Obranné číslo: 3 síly mysli: 18 velikost: D zranitelnost: B,C,D,E,I,J,K,L,N pohyblivost: 20 / humanoid ale neunaví se inteligence: 4 přesvědčení: jako nekromant K vyvolání tohoto nemrtvého je třeba humaniodního těla velikosti D. Můžete použít mrtvého obra lidožrouta nebo jiného vhodného obra. Tělo může být libovolně staré, podle toho také vzniklý nemrtvý bude vypadat, mezi kostlivými a zombiími obry není prakticky žádný rozdíl, jen pokud mrtvola ještě nebyla vyschlá, je zde 80% možnost, že nemrtvý získá schopnost hniloba. Nemrtvý obr je vhodný doplněk vaší nemrtvé armády, obzvlášť pokud dobýváte opevněná města a hrady, výborně totiž funguje jako dobývací věž. Navíc je silně imunní vůči oblíbeným zbraním obránců - vroucí olej apod. Nemrtvý obr, resp. jeho horní partie, jsou na bojišti vhodné místo pro slabší velitele nebo jiné slabší osoby, které by měly mít o bojišti přehled, nicméně by měly být mimo dosah zbraní (samozřejmě musíte nějak vyřešit jejich obranu proti nepřátelským střelám). Na slunci je útočné a obranné číslo nemrtvého obra sníženo o 2. Kritický neklid je 9. Nemrtví obři jsou příliš hloupí, aby byli schopni proti svým pánům kout nějaké pikle a i proto jsou zkušenými nekromanty používáni. Nemrtví obři umí mluvit, přestože jim to moc nejde a občas jim není rozumět.' AS pop
  UNION ALL SELECT 'Pravý běs' AS nazev, NULL AS uroven, NULL AS mag, 'dotek' AS dos, '20 hodin' AS sesl, 'stálé' AS trv, NULL AS un, 'Rozsah: 1 tvor. životaschopnost: 10 Útočné číslo: 13 (roh) 16 (s rozběhem) Obranné číslo: 11 síly mysli: 30 velikost: C zranitelnost: D1/2,E1/2,N1/2 pohyblivost: jako jednorožec ale neunaví se inteligence: 22 přesvědčení: jako nekromant Pravý běs je velice nebezpečný a mocný nemrtvý. Vzniká oživením jednorožce, oproti němu je však mnohem nebezpečnější a mocnější. Je velice inteligentní a přirozeně vzpurný. I nekromant, který se odvážil vyvolat si upíra si ještě několikrát rozmyslí, jestli vyvolá pravého běsa, přestože ten, jako nemrtvý, nesmí neuposlechnout příkaz svého pána. Můžeme ho vytvořit z libovolné mrtvoly jednorožce. Vzniklý nemrtvý bude mít podobu mohutného tmavého jednorožce jakési zvláštní barvy vypadající z určitého úhlu jako bílá, když se však podíváte odjinud, bude vypadat jako bílá zastíněná do až do černošedé. Dalším poznávacím znakem jsou oči žhnoucí bílým žárem a naprosto černá kopyta. Roh žhne stejnou barvou jako oči. Jedná se o formu přízračného nemrtvého. Je sice hmotný a může na něm dokonce někdo i jezdit, avšak jeho vzhled i podstata je do určité míry magický podvod. Dá považovat za přízračného a to i přestože hmotný vlastně je. Setkání smrtelníka s takovým nemrtvým je velice úchvatný zážitek, často ten nejúchvatnější v životě a ještě častěji ten poslední. Pravý běs umí vyvolávat mentální souboj, pro tyto účely se jeho životy považují za magy. Útočí vždy na soupeřovy životy a polovinu takto sebraných životů sám získává, může tímto způsobem získat i více životů, než je jeho maximum a pokud na to má dost životů, může soupeře zabité mentálním soubojem oživit stejně jako by se jednalo o podrobování. Může si tak vytvořit i vlastní armádu ovládnutých obětí, počet podrobených obětí u něj je totiž omezený jen jeho životaschopností (nesmí mít víc obětí, než na jakou má životaschopnost) a jeho životy. Oběti se dají poznat podle žhnoucích očí, stejných, jaké má pravý běs (ovšem nějakým záhadným způsobem se může stát, že ani tento poznávací znak nemá). Pravý běs nemá pud sebezáchovy a vrhne se do vřavy nepřátel, jen aby jich co nejvíce odnesl s sebou. Pravý běs je nejsilnější trumf v rukou těch, kteří tvrdí, že nemrtví jsou těla z tohoto světa ovládaná nějakou formou duší, lépe řečeno démonů, odjinud, kteří jsou za své služby placeni magy. Pravý běs může prolínat hmotnými neživými objekty - prostě jimi projde / proběhne, jako by tam nebyly. Předpokládá se, že všechny tyto schopnosti jsou dány hlavně vysoce magickou podstatou jednorožců. Kritický neklid pravého běsa je 14. Pravý běs je pro družinu skutečně nebezpečný nepřítel a Pj je doporučováno, aby ho užíval s rozmyslem, pokud ho chce na postavy poslat. Přímé světlo Pravého běsa během několika kol rozpouští, avšak pokud je jen ve stínu, nic se mu neděje. Musí být skutečně na přímém slunci. Po smrti nekromanta získává Pravý běs svobodnou vůli a právě to je to, proč se nekromanté obávají nezodpovědných kolegů a proč je svitek s tímto kouzlem vždy velice pečlivě uschován a chráněn a rozhodně ne každý má možnost se k němu dostat.' AS pop
  UNION ALL SELECT 'Zabití dotykem' AS nazev, NULL AS uroven, '10 magů' AS mag, 'dotyk' AS dos, NULL AS sesl, NULL AS trv, NULL AS un, 'Rosah: 1 cíl' AS pop
  UNION ALL SELECT 'Zabití pohledem' AS nazev, NULL AS uroven, '20 magů' AS mag, '15 sáhů' AS dos, NULL AS sesl, NULL AS trv, NULL AS un, 'Rosah: 1 cíl' AS pop
) v
JOIN seznamy_kouzel s ON s.nazev = 'Kouzla nekromanta'
JOIN povolani p ON p.id = s.povolani_id AND p.nazev = 'Nekromant';

-- Kouzla pyromancera / Pyromancer (3 kouzel)
INSERT INTO kouzla (nazev, seznam_kouzel_id, uroven_kouzla, cena_magenergie, dosah, doba_seslani, doba_trvani, typ_unavy, popis)
SELECT v.nazev, s.id, v.uroven, v.mag, v.dos, v.sesl, v.trv, v.un, v.pop
FROM (
  SELECT 'Reaperace' AS nazev, NULL AS uroven, '8 magů' AS mag, '40 sáhů “současná úroveň tepla” sáhů' AS dos, '1 kolo' AS sesl, 'ihned' AS trv, 'vycerpavajici' AS un, 'Rozsah: pyromancer. Pyromancer vzplane jasným zášlehem ohně a zhmotní se na někde v dosahu 40 sáhů. Podmínkou je, aby tam, kam se chce přesunout, hořel oheň (přímo ten hex). V místě znovuobjevení je oheň v dosahu 3 sáhů uhašen, ale 1 sáh od pyromancera dojde k malému výbuchu a všechny cíle v dosahu jsou zasaženy za 1k6+3 životů. Je zde 55% šance na hoření za 1k6+1 životů po dobu 2 kol. toto kouzlo pyromancerovi sníží úroveň tepla o hodnotu rovnou vzdálenosti na kterou se přesunul' AS pop
  UNION ALL SELECT 'Teplotní most' AS nazev, NULL AS uroven, '0' AS mag, '5 sáhů' AS dos, '1 akce' AS sesl, 'max 3 kola' AS trv, NULL AS un, 'Rozsah: 1 bytost. Pyromancer vytvoří tepelný most mezi sebou a cílem a okamžitě do něho začne pouštět nashromážděné teplo Za každých 10 tepla co takto přelije, je zde 50% šance, že cíl chytne plamenem. Tem na něm bude hořet 3 kola za 1k6 životů. Nebo dokud se neuhasí. Každé kolo pyromancerovy klesne teplo o 10, pokud už teplo nemá, nemá kouzlo žádný účinek.' AS pop
  UNION ALL SELECT 'Surtur' AS nazev, 16 AS uroven, '50 magů' AS mag, '0' AS dos, '2 kola' AS sesl, '2 směny' AS trv, 'vycerpavajici' AS un, 'Rozsah: Pyromancer. Působení: 16. úroveň. V době kdy je proměněný, je nezranitelný ohnivými kouzly a ledová kouzla jej zraňují za dvojnásobek. Přirozený oheň Surtura léči ve stejné hodnotě v jaké by ho jinak popálil. Voda na něj má stejný účinek, jako svěcená voda na nemrtvé. Nemagické zbraně na něj nemají účinek, ani běžné projektily. Magické zraňují za polovinu. Ve chvíli přeměny se jeho teplo automaticky zvýší na dvojnásobek jeho úrovně a začne klesat až ve chvíli kdy proměna pomine. Pohybuje se rychlostí až 5 sáhů za akci. (Nemůže běhat ani sprintovat.) Pyromancer se promění ve ztělesnění ohně, ohnivého démona velikosti D. Z toho vyplývají všechny +- za boj s ohledem na velikost. Dosah útoku 3 sáhy. Úč. 10 + bonus za Int. útočnost je pak bonus za žár. Oč. 1 + bonus za Int Bonus k iniciativě pro boj TvT je 6. Oblast 2 sáhů okolo Surtura je zóna žáru. Cokoliv hořlavého ihned vzplane a vydrží hořet pouze 1 kolo, pak se to změní na prach. (stromy, keře dřevěné budovy apod. neplatí na hráče či jiné tvory) Každý kdo je zasažen touto oblastí je zraňován za 1k8 + bonus za žár každé kolo. Pokud je zasažen fyzickým útokem od Surtura, nebo stojí v zóně žáru hází si po každém kole, nebo po každém zásahu s 50 % šanci, že chytne plamenem, který jej bude zraňovat za 1k4 + bonus za žár po dobu 3 kol. Tento efekt se sčítá a uhasit jej lze pouze dostatečným množstvím vody či ledovou magií. V tomto stavu nemůže používat předměty, nebo sesílat další kouzla. Všichni kdo Surtura vidí, si hází na Past Int. -8- útěk/nic. Utíkají po dobu 5 kol. Ověřování je 1 za směnu.' AS pop
) v
JOIN seznamy_kouzel s ON s.nazev = 'Kouzla pyromancera'
JOIN povolani p ON p.id = s.povolani_id AND p.nazev = 'Pyromancer';

-- Kouzla cryomancera / Cryomancer (3 kouzel)
INSERT INTO kouzla (nazev, seznam_kouzel_id, uroven_kouzla, cena_magenergie, dosah, doba_seslani, doba_trvani, typ_unavy, popis)
SELECT v.nazev, s.id, v.uroven, v.mag, v.dos, v.sesl, v.trv, v.un, v.pop
FROM (
  SELECT 'Kra' AS nazev, NULL AS uroven, '8 magů' AS mag, '0' AS dos, '1 kolo' AS sesl, 'dokud má cryomancer chlad, nebo dokud nezruší…' AS trv, 'vycerpavajici' AS un, 'Doba trvání (přesně): dokud má cryomancer chlad, nebo dokud nezruší kouzlo. Rozsah: Cryomancer. Past: Obr -7-. Cryomancer se zastaví na místě a nechá své tělo obalit ledem. Tento funguje jako ochrana jeho těla a tepelný most zároveň. Po dobu trvání kouzla se může bránit bez postihu -3, ale nemůže vykonávat jiné činnosti. Díky ledu se jeho KZ zvýší o 4 + úroveň mrazu. Každé kolo které stráví v této schránce z jeho těla odvede 6 bodů chladu a bude tak pokračovat dokud Cryomancer má ve svém těle chlad, nebo dokud kouzlo nezruší. Jak se snižuje jeho stupeň mrazu, klesá podle toho i bonus ke KZ. Na konci se rozletí na ledové šrapnely všemi směry, Za každé kolo, které Cryomancer stráví ve kře, se dosah ledových odštěpků zvýší o 3 sáhy. Každý kdo neuspěje v hodu proti pasti je zraněn za 2k6 životů chladem.' AS pop
  UNION ALL SELECT 'Vysátí tepla' AS nazev, NULL AS uroven, '0' AS mag, '5 sáhů' AS dos, '1 akce' AS sesl, 'max 3 kola' AS trv, NULL AS un, 'Rozsah: 1 bytost s tělesnou teplotou. Cryomancer vytvoří mezi sebou a cílem neviditelný tepelný přechod. Po dobu trvání kouzla si krade teplo od své oběti. Aby mělo kouzlo efekt, musí mít chlad k předání. Každé kolo předá 10 chladu. Za každých 10 chladu má pak cíl pro příští kolo postih -1 k Úč. a Oč. (max -3)' AS pop
  UNION ALL SELECT 'Ymir' AS nazev, 16 AS uroven, '50 magů' AS mag, '0' AS dos, '2 kola' AS sesl, '2 směny' AS trv, 'vycerpavajici' AS un, 'Rozsah: Cryomancer. Působení: 16. úroveň. V době kdy je proměněný, je nezranitelný ledovými kouzly a ohnivá kouzla jej zraňují za dvojnásobek. Ve chvíli přeměny se jeho chlad automaticky zvýší na dvojnásobek jeho úrovně a začne klesat až ve chvíli kdy proměna pomine. Ymir může chodit nejvýše rychlostí 1 sáh za akci v rozšířeném soubojovém systému. (Nemůže běhat ani sprintovat.) Cryomancer se změní v ledového praotce obrů, zvětší se na velikost D se všemi plynoucími modifikátory za boj TvT. Jeho síla a odolnost se zmnohonásobí. Po proměně si Cryomancer počítá stupeň síly/odolnosti, jako by byl trojnásobný. Lze takto překročit 21+5. Nepočítají se ovšem žádné dočasné prostředky, které mohou zvýšit stupeň síly/odolnosti. Jeho kůže se změní na srstí porostlý ledový krunýř s KZ 8. Okolo něho bude zuřit ledová smršť, která se dělí na 3 zóny. První zóna je na 1 sáh od Ymira. Každý kdo ní byť i jen projde, je zraněn za 1k10+2 chladem. Pokud v ní setrvá aspoň 3 kola v rámci 1 směny, hází si past Roz. Odol -12- zmrznutí/nic. Pokud neuspěje v hodu proti pasti, je dokonale zmrzlý na 1k10 kol a obdrží zranění ve výši stupně za odolnost. Tento efekt může nastat max 1x za směnu. Druhá zóna je méně chladná, ale vír v ní krouží o síle bouře. Každý kdo s ní přijde do kontaktu je zraněn za 1k6+1 životů. A šípy mířící na Ymira mají díky této zóně postih k Úč -3. Postavy s luxusním zimním oblečením zde dostávají ½ zranění chladem. Dosah této zóny je prstenec o šíři jednoho sáhu okolo Ymira a je od něj vzdálen na 2 sáhy. Třetí zóna je zónou bodavého chladu. Postavy v něm stojící jsou zraňovány za 1k4 životů každé kolo. Pokud mají na sobě luxusní zimní oblečení, zranění neobdrží. Tato zóna je také široká jeden sáh a je vzdálena na 3 sáhy od Ymira. V této podobě může Cryomancer seslat a hodit v rámci jedné akce ledové kopí či sněhovou kouli. Při boji TvT má Cryomancer v této podobě bonus +5 k iniciativě. Jeho útoky rukou či nohou mají dosah 1-2. Každým úspěšných útokem TvT, který byl způsoben Ymirovým tělem, způsobí dalších 1k6+3 zranění chladem. V této podobě neakumuluje další chlad, ale po skončení či zrušení efektu kouzla Ymir jsou cíle v dosahu 5 sáhů zranění za 1 život za každý chlad, který Cryomancer v tu chvíli má a on sám přijde o veškerý naakumulovaný chlad, který měl. Množství poškození touto ledovou explozí, se rovnoměrně rozdělí mezi veškeré cíle. Bonusové zranění za mráz se vztahuje pouze na zóny chladu a jeho fyzické útoky, nikoliv na kouzla č jiné činnosti v této podobě vykonané.' AS pop
) v
JOIN seznamy_kouzel s ON s.nazev = 'Kouzla cryomancera'
JOIN povolani p ON p.id = s.povolani_id AND p.nazev = 'Cryomancer';

-- Kouzla ohně a ledu / Kouzelník (30 kouzel)
INSERT INTO kouzla (nazev, seznam_kouzel_id, uroven_kouzla, cena_magenergie, dosah, doba_seslani, doba_trvani, typ_unavy, popis)
SELECT v.nazev, s.id, v.uroven, v.mag, v.dos, v.sesl, v.trv, v.un, v.pop
FROM (
  SELECT 'Zmrzlá země' AS nazev, NULL AS uroven, '2 mag za sáh čtvereční' AS mag, '0' AS dos, '2 kola' AS sesl, '1 směna' AS trv, 'vycerpavajici' AS un, 'Rozsah: 40 sáhů. Od nohou kouzelníka začne zamrzat země (nebo klidná vodní hladina) rychlostí 6 sáhů za kolo jen tam kde určí kouzelník každý kdo v okamžiku zamrzání stojí na zasažené ploše je zraněn za 1k4 životů ledem do nohou. Po skončení zamrzání, vydrží efekt 1 směnu, během této doby je zasažené území extrémně kluzké (20%x rychlost pohybu šance na uklouznutí) v případě, že postava uklouzne, upadne a je zraněna dopadem na zmrzlou zemi za 1k8 životů a musí 1 akci vstávat. Cryomancerovi bonusy se aplikují i při uklouznutí.' AS pop
  UNION ALL SELECT 'Sněhová bouře' AS nazev, NULL AS uroven, '30 magů' AS mag, '40 sáhů' AS dos, '3 kola' AS sesl, '1 směna' AS trv, 'vycerpavajici' AS un, 'Rozsah: 40 sáhů. vytvoří sněhovou bouři v oblasti o poloměru 40 sáhů, která zasáhne všechny smysly tvorů v oblasti dezorientuje je a sníží jejich dohled na 3 sáhy, v oblasti nijak nefunguje termovize, ultrasluch, ani superčich, zároveň zraňuje všechny v oblasti za 1k4 ledem každé kolo. Překrývající se kouzla se nescaluji.' AS pop
  UNION ALL SELECT 'Permafrost' AS nazev, NULL AS uroven, '40 magů' AS mag, '10 sáhů' AS dos, '3 kola' AS sesl, '5 kol' AS trv, 'vycerpavajici' AS un, 'Rozsah: 10 sáhů. Past: Odol-8-třes/nic. Oblast je zahalena do mučivého chladu. Tvorové, kteří neuspěli proti pasti se začnou nekontrolovatelně třást. Past se snižuje o 1-3 podle úrovně kvality oblečení Ti jež jsou postiženi třasem ztrácí v daném kole všechny akce a jsou zraněni za 1k6+2 životů ledem TT' AS pop
  UNION ALL SELECT 'Sněhová koule' AS nazev, NULL AS uroven, '2 magy' AS mag, '0' AS dos, '1 kolo' AS sesl, '3 kola/zásah' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 koule. SZ: 2/0 +1k8 ledem Váha 10mn Kouzelník ve své ruce zdánlivě z ničeho vytvoří sněhovou kouli která může být použita jako projektil podobně jako kámen nebo v praku/praku na tyči, pokud kouzelník v jedné ruce drží danou střelnou zbraň jeho nabíjení se sníží o 1 akci. Tento projektil vydrží 3 kola pak se sám rozpustí, pokud hodem zraní minimálně za 1 život zraní za dalších 1k4+2 ledem Cryomancerovy bonusy z mrazu se aplikují pouze pokud kouli vrhnul sám cryomancer.' AS pop
  UNION ALL SELECT 'Ledové kopí' AS nazev, NULL AS uroven, '14 magů' AS mag, '0' AS dos, '1 kolo' AS sesl, '1 směna' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 kopí. SZ: TvT= 6/0/0 +1k10+5 ledem vrh 3/0 4/8/12 +1k10+5 ledem váha 40mn Kouzelník ve svých rukou zformuje ledové kopí které může používat bez postihů za své povolání buď v boji TvT, kdy mu vydrží 1 směnu než se rozpustí, může ho za použití jedné akce hodit. Kopí jež zraní alespoň za 1 život přimrznout k cíli. Kouzelník může kopí hodit i na volné sáhy. Bez použití akce může kouzelník nechat jakékoliv kopí nechat explodovat a zranit za dalších 1k10+5 ledem všechny v oblasti 3x3 sáhy. cryomacerovy bonusy za mráz se počítají pouze používá-li/vrhne-li ho sám cryomancer.' AS pop
  UNION ALL SELECT 'Rampouch' AS nazev, NULL AS uroven, '6 magů' AS mag, '0' AS dos, '1 kolo' AS sesl, '1 směna/1 výstřel váha 3mn' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 šíp. Kouzelník vytvoří ve svých rukou šíp/šipku ve velikosti jakou si určí, ta vydrží 1 směnu a pak roztaje. Tento projektil se může vystřelit z jakéhokoliv luku nebo kuše (i arbalestu nebo vertolova luku), má vlastnosti jako standardní šíp, ale pokud zraní alespoň za 1 život zraní za dalších 1k6+4 ledem Pokud kouzelník drží v jedné ruce střelnou zbraň může nabíjení ponížit o jednu akci. Cryomancerovy bonusy za mráz se počítají pouze vystřelí-li ho sám cryomancer' AS pop
  UNION ALL SELECT 'Ledovy dech' AS nazev, NULL AS uroven, '4magy za sáh vzdálenosti' AS mag, '0 sáhů' AS dos, '1 akce za sáh vzdálenosti' AS sesl, 'ihned' AS trv, NULL AS un, 'Rozsah: výseč 90 stupňů do vzdálenosti dané magenergií. Past: Obr-7-zranění\nic. Kouzelník vydechne ledový opar, který zraní všechny v 120ti stupňové výseči do vzdálenosti dané magenergií , pokud neuspěli v hodu proti pasti za 1k6+2 životů.' AS pop
  UNION ALL SELECT 'Ledová zbroj' AS nazev, NULL AS uroven, '12 magů' AS mag, '0' AS dos, '2 kola' AS sesl, '1 směna' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 cíl. KZ 7 (popis). Váha 200mn Cíl je obalen do zbroje z křišťálového ledu, tato zbroj vypadá a chrání stejně jako rytířská zbroj (KZ 7). Při každém zásahu TvT se část zbroje roztříští a zraní útočníka odštěpky za 1k6+2 životů ledem, zároveň se sníží její KZ o 1. Proti ostatním zraněním se chová jako běžná zbroj. Cryomancerovy bonusy za mráz se aplikují pouze má li zbroj na sobě sám cryomancer.' AS pop
  UNION ALL SELECT 'Ledový štít' AS nazev, NULL AS uroven, '14 magů' AS mag, '0' AS dos, '2 kola' AS sesl, '1 směna' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 štít. KZ +2 váha 30mn Kouzelník vytvoří štít z křišťálově hladkého ledu s KZ 2. Na čelní straně štítu je 12 ostrých krystalů směřujících ven jako bodliny. Pokud je nositel zepředu zasažen fyzickým útokem z dálky, jeden z těchto krystalů vyletí a zasáhne útočníka za 1k6+2 životů ledem. Když štít přijde o všechny krystaly funguje stále jako standardní štít, dokud nepomine jeho doba trvání. Tento štít může používat jako štít bez omezení pouze kouzelník, který ho vyvolal, ostatní postavy ho mohou používat pokud jim to jejich povolání dovoluje. Cryomancerovy bonusy za mráz se aplikují pouze má-li štít u sebe sám cryomancer.' AS pop
  UNION ALL SELECT 'Ledové zrcadlo' AS nazev, NULL AS uroven, '10 magů +2 mag kolo trvání…' AS mag, '4 sáhy' AS dos, '2 kola' AS sesl, 'dle dodané magenergie' AS trv, 'vycerpavajici' AS un, 'Magenergie (přesně): 10 magů +2 mag kolo trvání +4 magy za kolo v něm. Rozsah: 1 zrcadlo. kouzelník vytvoří ledové zrcadlo 2*4 sáhy velké, které stojí vzpřímeně a dotýká země. za běžných podmínek je průhledné a tudíž téměř neviditelné toto zrcadlo odráží všechny blesky zpět na sesilatele, pro ostatní kouzla a fyzické útoky se chová jako pevná překážka má 20 životů a Oč 1, když je zničeno roztříští se. zvláštností tohoto zrcadla je, že kouzelník do něho může vkročit a stát se vlastně vlastním odrazem, který je vidět z obou stran jako by stál sáh za ním čelem k němu. pokud má kouzelník vyčarovaných víc takovýchto zrcadel může se mezi nimi volně pohybovat v nulovém čase a ve svém kole pak vystoupit, kouzlit, nebo zaútočit ze kteréhokoliv si vybere pokud je kouzelník uvnitř zrcadel, zničení jednoho nic neznamená, pokud není poslední. Při zničení posledního se kouzelník zhmotní na jeho místě, je zraněn za 4k10 životů a omráčen na 1k6 kol. Do zrcadla může vstoupit pouze ten kdo ho vyvolal. Kdokoliv jiný do něj narazí a bude se mu jevit jako obyčejné zrcadlo.' AS pop
  UNION ALL SELECT 'Ledová zeď' AS nazev, NULL AS uroven, '5 magů za sáh krychlový' AS mag, '5 sáhů' AS dos, '4 kola' AS sesl, '3 směny' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1-20 sáhů krychlových. Na viditelném místě vytvoří kouzelník ledový blok, který zde zůstane jednu směnu jeho rozměry a umístění plně ovládá kouzelník. zeď může být jakkoliv vysoká či dlouhá dokud je jen jeden blok široká, za každý sáh krychlový platí kouzelník 5 magů, tento blok se dá rozbít fyzickým útokem, 1 krychlový sáh = 100 životů obrana 1, toto kouzlo musí být sesláno na místo kde se nenachází žádný živý tvor.' AS pop
  UNION ALL SELECT 'Ledová tvorba-zbraň' AS nazev, NULL AS uroven, 'součet (Uč Oč a útočnosti) +6' AS mag, '0' AS dos, '2 kola' AS sesl, '3 směny' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: gray. Rozsah: 1 zbraň. Kouzelník vytvoří ledovou kopii zbraně pro boj TvT, kterou už někdy držel v ruce tato zbraň má stejné vlastnosti jako jeji originál. Nebude mít vlastnosti magických nebo legendárních zbraní, pouze jejich vzhled. Kdykoliv tato zbraň zraní alespoň za 1 život dá bonusové poškození 1k6 chladem. Kouzelník který tuto zbraň vyvolal může tuto zbraň používat bez omezení, či postihů. Cryomancerovy bonusy za mráz se aplikují pouze když používá zbraň sám cryomancer' AS pop
  UNION ALL SELECT 'Ledová tvorba-předmět' AS nazev, NULL AS uroven, '1 mag za mn' AS mag, '0' AS dos, '2 kola' AS sesl, '24 hodin' AS trv, 'vycerpavajici' AS un, 'Původní/magické jméno: gray. Rozsah: 1 předmět. kouzelník ve svých rukou vytvoří jakýkoliv předmět ze stabilizovaného ledu tanto led má všechny vlastnosti křišťálu, vydrží celkem velké zatížení, ale je extrémě křehký při silnějším nárazu se rozpadne. Zároveň nesnese vyšší teploty, v horkém (oheň) prostředí se do 5ti kol roztaví. v extrémních teplotách (dračí dech, láva) se rozpustí okamžitě.' AS pop
  UNION ALL SELECT 'Ledová tvorba-objekt' AS nazev, NULL AS uroven, '1 mag za 20mn váhy' AS mag, '0' AS dos, '5 kol' AS sesl, '24 hodin' AS trv, NULL AS un, 'Původní/magické jméno: gray. Rozsah: 1 objekt. Kouzelník vytvoří objekt spojený se zemí, může se jednat o cokoliv si čaroděj dokáže představit. Může se jednat o ledovou sochu konkrétní osoby, dům, katapult. Objekt je pevně spojen se zemí a nemůže se nijak pohybovat, pokus o jeho přemístění ho zničí. Objekt má 10 životů a obranu 1.' AS pop
  UNION ALL SELECT 'Ledové vězení' AS nazev, NULL AS uroven, '20 magů' AS mag, '10 sáhů' AS dos, '2 kola' AS sesl, '1k6 kol' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 bytost max C. Uvězní jednu bytost v ledovém sloupu tato bytost ztrácí iniciativu na 1k6 kol, po kterých se sice nemůže jakkoliv hýbat nebo bránit, ale má KZ 20 Cryomancer se může rozhodnout zdali na bytost uplatní své bonusy za mráz či nikoliv' AS pop
  UNION ALL SELECT 'Chladná voda' AS nazev, NULL AS uroven, '20 magů' AS mag, 'dotyk' AS dos, '2 kola' AS sesl, '3 směny' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 bytost. Kouzelník dotykem přelije dávku chladu do nemagického tvora. Tento tvor získá imunitu proti vedru a přirozenému ohni, 50% odolnost proti ohnivé magii. lávě a ohnivému dračímu dechu' AS pop
  UNION ALL SELECT 'Absolutní nula' AS nazev, NULL AS uroven, '40 magů' AS mag, '0' AS dos, '2 kola' AS sesl, 'okamžitě' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 sáh. Past: Odol-7-zmrznutí/nic. kouzelník ze svého bezprostředního okolí vysaje veškeré teplo všechny bytosti kolem kouzelníka do 1 sáhu daleko jsou zraněni za 1k10+5 absolutním chladem a když neuspějí proti pasti zmrznou na 1k6 kol. Každá úroveň oblečení snižuje past o 1 (oblečení=1, kvalitní/luxusní/zimní oblečení=2, kvalitní/luxusní zimní oblečení=3)' AS pop
  UNION ALL SELECT 'Ohnivá střela' AS nazev, NULL AS uroven, '3 magy za střelu' AS mag, '10 sáhů' AS dos, '1 kolo' AS sesl, 'ihned' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1- 3 cíle. Za kolo lze seslat nejvíce 3 střely. Kouzelník vytvoří plamennou střelu, která zasažený cíl popálí za 1k10 životů.' AS pop
  UNION ALL SELECT 'Duchové ohně' AS nazev, NULL AS uroven, '4 magy za ducha, 4 max' AS mag, '5 sáhů od sesilatele, nebo jeden od druhého' AS dos, '2 kola' AS sesl, '1 směna' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 - 4 duchové. Kouzelník zhustí svou magenergii do podoby asi 4 coulových kuliček, které vydávají světlo a teplo. Může je libovolně přesouvat, pohybují se 10 sáhů za kolo. Každá dosvítí na 7 sáhů. Pokud jim vydá rozkaz k útoku, srazí se s cílem a popálí ho za 1k4+2 životy. Je zde 50% šance na malý lokální výbuch za dalších 1k6 životů. Po seslání se na světla už nemusí nijak soustředit.' AS pop
  UNION ALL SELECT 'Ohnivý břit' AS nazev, NULL AS uroven, '2 magy za kolo, 1 mag za další' AS mag, 'dotyk' AS dos, '1 kolo' AS sesl, 'dle dodané magenergie' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 zbraň TvT. Čaroděj očaruje na omezenou dobu zbraň, která bude působit bonusové zranění ohněm. Bonusové poškození je 1k6+1. Zde není šance na dodatečné vzplanutí cíle. Zbraň dosvítí na 1 sáh. Samotné držení zbraně nositele nezraní. Pyromancerovy bonusy za žár se aplikují jen používá-li zbraň pyromancer.' AS pop
  UNION ALL SELECT 'Živá bomba' AS nazev, NULL AS uroven, '18 magů' AS mag, '7 sáhů' AS dos, '2 kola' AS sesl, '3 kola' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 cíl. Cíl pod vlivem kouzla začne uvnitř sebe rostoucí žár. Každé kolo si cíl hází proti pasti Odol. -8- zranění1k6+2/zranění1k4+1. Po uplynutí 3 kol dojde k výbuchu uvnitř těla cíle a je nakonec zraněn za 1k10+3 životů. Pokud je cíl tímto kouzlem zabit, rozpadne se na jiskry a popel. Přežijí pouze kouzelné předměty a artefakty. Na jednom cíli může být naráz 1 bomba.' AS pop
  UNION ALL SELECT 'Fénixův plášť' AS nazev, NULL AS uroven, '12 magů' AS mag, '0' AS dos, '2 kola' AS sesl, '1 směna' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 cíl. Cíl se zahalí do krásných plamenů, které budou kopírovat jeho tělo a chránit ho. Každý útok TvT na cíl pod vlivem kouzla způsobí, že útočník si hází na past Obr. -9- Zranění/nic. Zranění je za 1k6 životů. Po dobu trvání kouzla se KZ nositele zvýší o 1. Pyromancerovy bonusy za žár se aplikují pouze jeli do pláště zahalen sám pyromancer' AS pop
  UNION ALL SELECT 'Katapult' AS nazev, NULL AS uroven, '4 magy' AS mag, '50 sáhů' AS dos, '1 kolo' AS sesl, 'ihned' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 cíl. Pyromancer uchopí do ruky projektil (kámen, ocel, olovo) a magicky ho vystřelí vůči cíli. Hod na útok je stejný, jako by jej Pyromancer hodil, ale namísto Obratnosti použije bonus za Inteligenci. Cíl je zraněn za hodnotu zranění projektilem + Int + 1k6+3 zranění ohněm.' AS pop
  UNION ALL SELECT 'Ohnivá stěna' AS nazev, NULL AS uroven, '16 magů vyvolání, 4 magy za…' AS mag, '1 - 15 sáhů' AS dos, '2 kola' AS sesl, 'dle dodané magenergie' AS trv, 'vycerpavajici' AS un, 'Magenergie (přesně): 16 magů vyvolání, 4 magy za každé 4 sáhy pohybu, nebo kolo stání. Rozsah: 3 hexy před kouzelníkem. Pyromancer před sebou na 3 hexech vyvolá divoký hučící oheň, který se bude pohybovat v určení přímce, kterou určí pyromancer. Stěna každé kolo urazí 4 sáhy za 1 kolo. Každý kdo se ocitne na hexu který je pod vlivem kouzla je každé kolo, které na něm setrvá zraněn za 2k8+2 životů. Vše hořlavé se promění v popel a oheň se omezuje jen na 3 určené hexy. Pokud je cíl pálen aspoň 2 kola, tak vše hořlavé je zničeno beze zbytku. Kouzlo trvá dokud je magenergie, nebo pokud se nevzdálí dále, jak 15 sáhů od kouzelníka.' AS pop
  UNION ALL SELECT 'Spalující paprsek' AS nazev, NULL AS uroven, '16 magů za paprsek' AS mag, '20 sáhů' AS dos, '2 kola' AS sesl, 'ihned' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 - 3 cíle. Od pyromancera vyšlehne úzký paprsek koncentrovaného ohně, který s 70% svůj cíl propálí a zraní i cíl za ním. 1 paprsek zraní nanejvíš 3 cíle v lince za sebou. poslední cíl nesmí být dále jak 40 sáhů od pyromancera. Cíl si hází na Past Obr -7- zranění/poloviční zranění. První zasažený cíl obdrží zranění ohněm za 3k6+6 životů. Druhý cíl za 2k6+4 životů a třetí za 1k6+2 životů. Nelze na 1 cíl seslat více paprsků v 1 kole.' AS pop
  UNION ALL SELECT 'Slzy slunce' AS nazev, NULL AS uroven, '20 magů vyvolání, 2 magy za…' AS mag, '50 sáhů' AS dos, '3 kola' AS sesl, '3 směny' AS trv, 'vycerpavajici' AS un, 'Magenergie (přesně): 20 magů vyvolání, 2 magy za každou vyslanou slzu. Rozsah: 1-12 cílů. Pyromancer nad sebou zhmotní malé slunce. To dosvítí na 120 sáhů od Pyromancera. Každé slunce má v sobě 12 slz, kterým pyromancer může určit cíl. Může naráz poslat tolik slz kolik je jeho úroveň, nebo dokud nějaké ve slunci jsou. Každá slza může mít jiný cíl, nebo všechny stejný. Každá slza zraní cíl za 1k4+3 životy. S každou slzou dosvit slunce klesá o 10 sáhů. Vyslat slzu/slzy trvá 1 akci.' AS pop
  UNION ALL SELECT 'Sloup ohně' AS nazev, NULL AS uroven, '50 magů' AS mag, '30 sáhů' AS dos, '3 kola' AS sesl, '1 směna' AS trv, 'vycerpavajici' AS un, 'Rozsah: válec 5 sáhů v průměru, 10 sáhů na výšku. Každý tvor v oblasti obdrží zranění dle své velikosti. A0 = 1k6, A = 2k6 B = 3k6, C = 4k6, D = 5k6, E = 6k6. Ke každému 1k6 se pak připočítá bonus za žár. Na sloup se kouzelník musí soustředit, pokud chce aby se hýbal. Je schopen se hýbat rychlostí 5 sáhů za kolo. Tam kam ho chce přesunout musí vidět. Pokud se kouzelník na sloup soustředí, má v dalších kolech -3 k iniciativě.' AS pop
  UNION ALL SELECT 'Pekelný kůň' AS nazev, NULL AS uroven, '50 magů' AS mag, '1 sáh' AS dos, '4 kola' AS sesl, 'stále, max 16 hodin' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 kůň. Kouzelník přivolá ohnivý běs s podobou koně, který mu může sloužit jako jezdecký tvor. Jezdit na něm může pouze kouzelník který ho vyvolal. Ať je váha kouzelníka + jeho nákladu jakákoliv, kůň se vždy pohybuje rychlostí 21+5. Vytrvalost 40. Vznáší se asi 10 coulů nad zemí a nechává za sebou cestičku vypálených otisků kopyt. Vždy se dokonale přizpůsobí svému jezdci a při ověřování se počítá, jako by kouzelník uměl jízdu na koni dokonale. Jízda samotná neunavuje, ale za udržování seslaného koně platí kouzelník 1 bodem únavy za hodinu. Množství životů koně je stejné jako max. množství životů kouzelníka. Zranitelný je pouze magickými zbraněmi, vodou, magií. Obyčejná voda na něj působí jako svěcená na nemrtvé. Oč. koně je 5. Úč 8+2 kopyty/2x za kolo. Pyromancerův bonus za žár se počítá pouze, když je pyromancer v jeho sedle' AS pop
  UNION ALL SELECT 'Magma' AS nazev, NULL AS uroven, '40 magů' AS mag, '4 sáhy' AS dos, '4 kola' AS sesl, 'okamžitě' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 sáh. Kouzelník dupne do země a od jeho nohou vyšplíchne rozžhavené magma, proud lávy zasáhne první překážku mezi kouzelníkem a cílem. Zraní za 5k10 životů a má o 50% větší šanci na zapálení. Horké magma v dráze kouzla vydrží 5 kol. Šlápnutí na něj zraňuje za 1k6 přirozeným ohněm.' AS pop
  UNION ALL SELECT 'Pouštní vítr' AS nazev, NULL AS uroven, '20 magů' AS mag, 'dotyk' AS dos, '2 kola' AS sesl, '1 směna' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 bytost. Kouzelník dotykem přelije dávku tepla do nemagického tvora. Tento tvor získá imunitu proti přirozenému chladu a ledu, 50% odolnost proti ledovým kouzlům, ledovému dračímu dechu a absolutní nule. Hnev Luny' AS pop
) v
JOIN seznamy_kouzel s ON s.nazev = 'Kouzla ohně a ledu'
JOIN povolani p ON p.id = s.povolani_id AND p.nazev = 'Kouzelník';

-- Kouzla hraničáře / Hraničář (27 kouzel)
INSERT INTO kouzla (nazev, seznam_kouzel_id, uroven_kouzla, cena_magenergie, dosah, doba_seslani, doba_trvani, typ_unavy, popis)
SELECT v.nazev, s.id, v.uroven, v.mag, v.dos, v.sesl, v.trv, v.un, v.pop
FROM (
  SELECT 'Mluv se zvířaty' AS nazev, 2 AS uroven, '3 magy za první kolo, 2 magy…' AS mag, '20 sáhů' AS dos, '2 kola' AS sesl, 'dle dodané magenergie' AS trv, 'vycerpavajici' AS un, 'Magenergie (přesně): 3 magy za první kolo, 2 magy za každé další. Rozsah: 1 zvíře. Účinkuje jen na typická nefantastická zvířata s alespoň zvířecí inteligencí (1). Během trvání lze zvířeti klást jednoduché otázky (jedna za kolo) a dostávat jednoduché odpovědi.' AS pop
  UNION ALL SELECT 'Najdi stopy' AS nazev, 2 AS uroven, '3 magy' AS mag, '0' AS dos, '2 kola' AS sesl, '6 směn' AS trv, 'vycerpavajici' AS un, 'Rozsah: jen hraničář. Zvyšuje pravděpodobnost úspěšného stopování (mimo nepoužitelný terén) o 25 %. Opakované seslání nezvyšuje šanci, ale sčítá dobu trvání.' AS pop
  UNION ALL SELECT 'Najdi zvíře' AS nazev, 2 AS uroven, '3 magy' AS mag, '5 mil' AS dos, '2 kola' AS sesl, 'ihned' AS trv, 'vycerpavajici' AS un, 'Rozsah: nejbližší zvíře daného druhu. Hraničář si představí typického zástupce druhu a vycítí směr nejbližšího jedince. 100% úspěšné do 1 míle (1000 sáhů), −20 % za každou další míli. Funguje jen na typická nefantastická zvířata s alespoň zvířecí inteligencí.' AS pop
  UNION ALL SELECT 'Neutralizuj jed' AS nazev, 2 AS uroven, '6 magů' AS mag, 'dotyk' AS dos, '1 kolo' AS sesl, 'stálé' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 postava. Sníží nebezpečnost jedu o 6 (viz "Pasti a jedy" str. 87), pokud je sesláno včas (okamžitě/několik kol u rychlých jedů; do jedné směny u jedů s nástupem hodiny až několik hodin; do 1 hodiny u jedů působících déle než 6 hodin). Účinkuje jen na přírodní jedy, ne na uměle vyrobené (např. alchymistou). Od 16. úrovně je hraničář schopen neutralizovat i uměle vyrobené jedy, ale jen takové, kde základem je nějaký přírodní rostlinný nebo živočišný jed.' AS pop
  UNION ALL SELECT 'Odstraň ochromení' AS nazev, 2 AS uroven, '4 magy' AS mag, 'dotyk' AS dos, '2 kola' AS sesl, 'ihned' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 postava. Odstraní mdloby, ochromení (např. po zásahu dikobrazem), křeče a podobné stavy.' AS pop
  UNION ALL SELECT 'Uzdrav lehká zranění' AS nazev, 2 AS uroven, '3 magy' AS mag, 'dotyk' AS dos, '3 kola' AS sesl, 'stálé' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 postava. Vyléčí 2–7 životů (počet životů po vyléčení nikdy nepřekročí základní počet). PŘÍKLAD: PŘÍKLAD: Válečník Rohan má základ 13 životů, po zranění 10. Hraničář Balto sešle kouzlo, hod 1k6+1 dá 5 — Rohan má opět 13 životů, zbylé 2 propadnou.' AS pop
  UNION ALL SELECT 'Uzdrav nemocného' AS nazev, 2 AS uroven, '12 magů' AS mag, 'dotyk' AS dos, '2 směny' AS sesl, 'stálé' AS trv, 'nevycerpavajici' AS un, 'Rozsah: 1 postava. Vyléčí většinu nemocí včetně lykantropie; u velmi vážné nemoci může být nutná rekonvalescence nebo nemoc přetrvá v menší míře.' AS pop
  UNION ALL SELECT 'Uzdrav těžká zranění' AS nazev, 2 AS uroven, '5 magů' AS mag, 'dotyk' AS dos, '3 kola' AS sesl, 'stálé' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 postava. Vyléčí 4–14 životů (nikdy nad základní počet).' AS pop
  UNION ALL SELECT 'Zmam osobu' AS nazev, 2 AS uroven, 'viz Tabulka inteligence a…' AS mag, '7 sáhů' AS dos, '3 kola' AS sesl, 'viz níže' AS trv, 'vycerpavajici' AS un, 'Magenergie (přesně): viz Tabulka inteligence a zmámení. Rozsah: 1 tvor. Účinkuje jen na tvory s inteligencí 1+. Šance na zmámení a interval kontroly závisí na inteligenci terče:' AS pop
  UNION ALL SELECT 'Chraň před dračím dechem' AS nazev, NULL AS uroven, '10 magů' AS mag, 'dotyk' AS dos, '1 kolo' AS sesl, '3 směny' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 tvor. Při hodu na obranu proti dračímu dechu se obranné číslo počítá jako dvojnásobné, v případě zranění se počítá pouze polovina (zaokrouhleno nahoru) nominálního zranění.' AS pop
  UNION ALL SELECT 'Magické zrcadlo' AS nazev, NULL AS uroven, 'nejméně 8 magů' AS mag, '0' AS dos, '1 kolo' AS sesl, 'dle dodané magenergie' AS trv, 'vycerpavajici' AS un, 'Rozsah: kruh o poloměru 2 sáhy. Toto kouzlo vytvoří kolem hraničáře ochranné pole proti útočným kouzlům typu blesků, jejichž terčem je hraničář. Toto pole má tolik magů, kolik jich hraničář spotřeboval na vyvolání kouzla. Hraničář při každém okamžiku ví, kolik magů jeho pole ještě má, a dokud kouzlo trvá, může do něj přilévat další magy. Během spánku však klesne počet magů "udržovaného" pole na polovinu. Při útoku, na který pole magického zrcadla zareaguje, se spící hraničář v následujícím kole vzbudí. Kouzly, na něž pole zareaguje, mohou být buď pohlcena, nebo odražena — jinými kouzly jím oběma mohou projít. Odražená kouzla se sníží pole o dvojnásobek magenergie, se kterou byla seslána, a s plnou silou se vrátí na postavu, jež je seslala; pohlcená kouzla odevzdávají poli polovinu energie, se kterou byla seslána (zaokrouhluj dolů). Kouzlo seslané s magenergií menší nebo rovnou polovině magenergie pole se buď odrazí (80% šance), nebo bude pohlceno (zbytek případů). U kouzel seslaných s magenergií větší než polovina, ale menší nebo rovnou celkové magenergii pole, je poměr obrácený (tj. 01–80 pohlcení, 81–100 odražení — v tomto případě je navíc pole zničeno a magické zrcadlo skončí). Kouzla seslaná s větší magenergií, než je magenergie pole, ale nejvýše čtyřnásobek magenergie pole, mají poměr opět obrácený. Kouzla s magenergií větší než čtyřnásobek magenergie pole vždy polem projdou a zničí ho. (Pozn.: pasáž o poměru pohlcení/odražení u kouzel s magenergií blízkou magenergii pole je na skenu částečně nejasná — přepsáno podle nejlepšího odhadu smyslu, procenta a podmínky se mohou v detailu odchylovat od originálu.)' AS pop
  UNION ALL SELECT 'Odčaruj zkamenění' AS nazev, NULL AS uroven, '30 magů' AS mag, 'dotyk' AS dos, '1 směna' AS sesl, 'stálé' AS trv, 'nevycerpavajici' AS un, 'Rozsah: 1 tvor. Tímto kouzlem může hraničář zvrátit působení některých bytostí, které jsou schopny proměňovat své oběti v kámen (např. medúza). Po seslání kouzla zkamenělá postava opět ožívne, bude mít tolik životů, kolik je její mez vyražení (nejméně 1 život), a nebude si pamatovat nic z toho, co se dělo během doby, kdy byla sochou. Tímto kouzlem nelze odstranit zkamenění způsobené kouzelnickými kouzly, při nichž se tvor sice promění v kámen, ale nadále žije, je schopen se pohybovat, eventuelně mluvit, a plně si uvědomuje svoji existenci. Pokud někdo skamenělou postavu poškodil (urazí jí nos nebo uštípne palec), projeví se tyto změny i na oživené postavě, ale nebude proto mít méně životů. Pokud někdo sochu zničil (rozlámal na střepy), její oživení už není možné. Poslední slovo v tom, kdy je ještě oživení možné a kdy už je poškození nevratné, má vždy Pán jeskyně.' AS pop
  UNION ALL SELECT 'Ošetři zranění chladem' AS nazev, NULL AS uroven, '8 magů' AS mag, 'dotyk' AS dos, '1 směna' AS sesl, 'stálé' AS trv, 'nevycerpavajici' AS un, 'Rozsah: 1 tvor. Tímto kouzlem může chodec nebo druid vrátit postavě 15 až 20 životů, o které byla připravena mrazem (například dechem bílého draka). Zranění však nesmí být starší než 3 směny. Toto kouzlo, je-li sesláno druidem ve hvozdu, vyléčí za 25–30 životů a odčerpá navíc 5 magů z probouzecí magenergie hvozdu.' AS pop
  UNION ALL SELECT 'Ošetři zranění kyselinou' AS nazev, NULL AS uroven, '6 magů' AS mag, 'dotyk' AS dos, '1 směna' AS sesl, 'stálé' AS trv, 'nevycerpavajici' AS un, 'Rozsah: 1 tvor. Tímto kouzlem může chodec nebo druid vrátit postavě 11 až 16 životů, o které byla připravena poleptáním (např. dechem hnědého draka nebo zeleným hlenem). Zranění však nesmí být starší než 3 směny. Sesláno druidem ve hvozdu vyléčí za 18–23 životů a odčerpá navíc 3 magy z probouzecí magenergie hvozdu.' AS pop
  UNION ALL SELECT 'Ošetři zranění ohněm' AS nazev, NULL AS uroven, '9 magů' AS mag, 'dotyk' AS dos, '1 směna' AS sesl, 'stálé' AS trv, 'nevycerpavajici' AS un, 'Rozsah: 1 tvor. Tímto kouzlem může chodec nebo druid vrátit postavě 17 až 22 životů, o které byla připravena popálením nebo opařením (např. dechem žlutého draka). Zranění však nesmí být starší než 3 směny. Sesláno druidem ve hvozdu vyléčí za 28–33 životů a odčerpá navíc 5 magů z probouzecí magenergie hvozdu.' AS pop
  UNION ALL SELECT 'Telepatická ochrana' AS nazev, NULL AS uroven, '10 magů' AS mag, 'dotyk' AS dos, '1 směna' AS sesl, '1 den' AS trv, 'nevycerpavajici' AS un, 'Rozsah: 1 tvor. Toto kouzlo chrání postavu, na kterou bylo sesláno, před všemi formami nepovolené telepatie a hraničářskými kouzly, která působí na psychiku (např. zmam osobu). Neposkytuje ochranu před žádnými schopnostmi kouzelníka a jeho kouzly.' AS pop
  UNION ALL SELECT 'Úder varování' AS nazev, NULL AS uroven, '5 magů' AS mag, '7 sáhů' AS dos, '2 kola' AS sesl, 'stálé' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 tvor. Tímto kouzlem je možno způsobit protivníkovi zranění za 2 až 7 životů.' AS pop
  UNION ALL SELECT 'Úder zloby' AS nazev, NULL AS uroven, '7 magů' AS mag, '9 sáhů' AS dos, '2 kola' AS sesl, 'stálé' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 tvor. Tímto kouzlem je možno způsobit protivníkovi zranění za 4 až 14 životů.' AS pop
  UNION ALL SELECT 'Úder nenávisti' AS nazev, NULL AS uroven, '12 magů' AS mag, '12 sáhů' AS dos, '1 kolo' AS sesl, 'stálé' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1–3 tvorové. Tímto kouzlem je možno způsobit až třem protivníkům, které hraničář určí, zranění v celkové hodnotě 3–30 životů. Zranění se mezi postižené dělí rovnoměrně. (Pozn.: kouzla Úkryt [pouze druid] a Vládni přirozeným věcem [pouze chodec] jsou pro svou vázanost na konkrétní obor uvedena níže v příslušných oddílech "Druid" a "Chodec".)' AS pop
  UNION ALL SELECT 'Magický střeh I' AS nazev, 16 AS uroven, '5 magů' AS mag, NULL AS dos, NULL AS sesl, NULL AS trv, NULL AS un, 'Magický střeh zareaguje na každé kouzelnické kouzlo, jehož terčem je hraničář, a pokusí se je pohltit vynaložením vlastní magenergie terče. V závislosti na tom, o jaký typ kouzla se jedná, na koho a za jakých okolností je sesláno, poklesne magenergie terče o určitý násobek magenergie seslaného kouzla (pokud terč uspěje v hodu proti pasti), a pokud si to bude hraničář přát, odrazí se s vynaložením dalšího násobku magenergie zpět k sesilateli. Kouzelnická kouzla, jež mohou být na hraničáře seslána, si hraničáři rozdělují do čtyř skupin: fyzická, psychická, útočná a ochranná. I. Kouzla fyzická působí na hraničářovo hmotné tělo, snaží se ho nějak spoutat, poutat nebo mu alespoň přičarovat oslí uši. II. Kouzla psychická se naopak soustředí na jeho mysl, snaží se ji nějak ovlivnit, od nenápadného vnuknutí nějaké myšlenky až po naprosté převzetí kontroly. III. Kouzla útočná mají schopnost přetvářet magenergii v různé hmotné či nehmotné látky a s jejich pomocí napadnout hraničářovo tělo a ublížit mu. IV. Kouzla ochranná jsou schopna chránit hraničáře před fyzickými i duševními útoky. O přesné zařazení kouzla se vždy postará PJ, který kouzlo po odečtení rozdílu úrovní hodí na příslušnou past. Toto kouzlo není všelékem proti kouzelníkům — vůbec například nechrání před mentálními útoky a také nijak nereaguje, pokud kouzelník vytvoří nějakou iluzi v prostoru mimo hraničáře. Zde totiž na hraničáře žádná magenergie přímo nepůsobí. Terčem seslaného kouzla může být chodec nebo druid, a sice na 16. a vyšší úrovni. U obou povolání záleží na tom, zda jsou v bdělém stavu, či spí, u druida pak dále na tom, zda je ve hvozdu či mimo něj. Nebezpečnost pasti rozhodující o tom, zda bylo kouzlo úspěšně odraženo, mimo jiné záleží na rozdílu úrovní sesilatele a terče (konkrétně na čtvrtině rozdílu úrovní). Tabulka magického střehu vyjadřuje obtížnost pohlcení respektive odražení kouzla v různých situacích. Číslem ze sloupce ,P'' si vynásobíme počet magů vynaložených na kouzlo seslané na hraničáře a zjistíme tak magenergii nutnou k jeho pohlcení. Kouzlo bude pohlceno, pokud terč uspěje v hodu proti pasti. Číslo ze sloupce ,O'' se použije při výpočtu magenergie nutné k odražení kouzla ze sesilatele.' AS pop
  UNION ALL SELECT 'Magický střeh' AS nazev, 16 AS uroven, NULL AS mag, NULL AS dos, '1 kolo' AS sesl, 'do prvního kouzla (potrvá, dokud úspěšně…' AS trv, 'vycerpavajici' AS un, 'Doba trvání (přesně): do prvního kouzla (potrvá, dokud úspěšně nezachytí první kouzelnické kouzlo). Magický střeh zareaguje na každé kouzelnické kouzlo, jehož terčem je hraničář, a pokusí se je pohltit vynaložením vlastní magenergie terče. V závislosti na tom, o jaký typ kouzla se jedná, na koho a za jakých okolností je sesláno, poklesne magenergie terče o určitý násobek magenergie seslaného kouzla (pokud terč uspěje v hodu proti pasti), a pokud si to bude hraničář přát, odrazí se s vynaložením dalšího násobku magenergie zpět k sesilateli. Kouzelnická kouzla, jež mohou být na hraničáře seslána, si hraničáři rozdělují do čtyř skupin: fyzická, psychická, útočná a ochranná. I. Kouzla fyzická působí na hraničářovo hmotné tělo, snaží se ho nějak spoutat, poutat nebo mu alespoň přičarovat oslí uši. II. Kouzla psychická se naopak soustředí na jeho mysl, snaží se ji nějak ovlivnit, od nenápadného vnuknutí nějaké myšlenky až po naprosté převzetí kontroly. III. Kouzla útočná mají schopnost přetvářet magenergii v různé hmotné či nehmotné látky a s jejich pomocí napadnout hraničářovo tělo a ublížit mu. IV. Kouzla ochranná jsou schopna chránit hraničáře před fyzickými i duševními útoky. O přesné zařazení kouzla se vždy postará PJ, který kouzlo po odečtení rozdílu úrovní hodí na příslušnou past. Toto kouzlo není všelékem proti kouzelníkům — vůbec například nechrání před mentálními útoky a také nijak nereaguje, pokud kouzelník vytvoří nějakou iluzi v prostoru mimo hraničáře. Zde totiž na hraničáře žádná magenergie přímo nepůsobí. Terčem seslaného kouzla může být chodec nebo druid, a sice na 16. a vyšší úrovni. U obou povolání záleží na tom, zda jsou v bdělém stavu, či spí, u druida pak dále na tom, zda je ve hvozdu či mimo něj. Nebezpečnost pasti rozhodující o tom, zda bylo kouzlo úspěšně odraženo, mimo jiné záleží na rozdílu úrovní sesilatele a terče (konkrétně na čtvrtině rozdílu úrovní). Tabulka magického střehu vyjadřuje obtížnost pohlcení respektive odražení kouzla v různých situacích. Číslem ze sloupce ,P'' si vynásobíme počet magů vynaložených na kouzlo seslané na hraničáře a zjistíme tak magenergii nutnou k jeho pohlcení. Kouzlo bude pohlceno, pokud terč uspěje v hodu proti pasti. Číslo ze sloupce ,O'' se použije při výpočtu magenergie nutné k odražení kouzla ze sesilatele.' AS pop
  UNION ALL SELECT 'Magický střeh II' AS nazev, 16 AS uroven, '20 magů' AS mag, NULL AS dos, NULL AS sesl, NULL AS trv, NULL AS un, 'Magický střeh zareaguje na každé kouzelnické kouzlo, jehož terčem je hraničář, a pokusí se je pohltit vynaložením vlastní magenergie terče. V závislosti na tom, o jaký typ kouzla se jedná, na koho a za jakých okolností je sesláno, poklesne magenergie terče o určitý násobek magenergie seslaného kouzla (pokud terč uspěje v hodu proti pasti), a pokud si to bude hraničář přát, odrazí se s vynaložením dalšího násobku magenergie zpět k sesilateli. Kouzelnická kouzla, jež mohou být na hraničáře seslána, si hraničáři rozdělují do čtyř skupin: fyzická, psychická, útočná a ochranná. I. Kouzla fyzická působí na hraničářovo hmotné tělo, snaží se ho nějak spoutat, poutat nebo mu alespoň přičarovat oslí uši. II. Kouzla psychická se naopak soustředí na jeho mysl, snaží se ji nějak ovlivnit, od nenápadného vnuknutí nějaké myšlenky až po naprosté převzetí kontroly. III. Kouzla útočná mají schopnost přetvářet magenergii v různé hmotné či nehmotné látky a s jejich pomocí napadnout hraničářovo tělo a ublížit mu. IV. Kouzla ochranná jsou schopna chránit hraničáře před fyzickými i duševními útoky. O přesné zařazení kouzla se vždy postará PJ, který kouzlo po odečtení rozdílu úrovní hodí na příslušnou past. Toto kouzlo není všelékem proti kouzelníkům — vůbec například nechrání před mentálními útoky a také nijak nereaguje, pokud kouzelník vytvoří nějakou iluzi v prostoru mimo hraničáře. Zde totiž na hraničáře žádná magenergie přímo nepůsobí. Terčem seslaného kouzla může být chodec nebo druid, a sice na 16. a vyšší úrovni. U obou povolání záleží na tom, zda jsou v bdělém stavu, či spí, u druida pak dále na tom, zda je ve hvozdu či mimo něj. Nebezpečnost pasti rozhodující o tom, zda bylo kouzlo úspěšně odraženo, mimo jiné záleží na rozdílu úrovní sesilatele a terče (konkrétně na čtvrtině rozdílu úrovní). Tabulka magického střehu vyjadřuje obtížnost pohlcení respektive odražení kouzla v různých situacích. Číslem ze sloupce ,P'' si vynásobíme počet magů vynaložených na kouzlo seslané na hraničáře a zjistíme tak magenergii nutnou k jeho pohlcení. Kouzlo bude pohlceno, pokud terč uspěje v hodu proti pasti. Číslo ze sloupce ,O'' se použije při výpočtu magenergie nutné k odražení kouzla ze sesilatele.' AS pop
  UNION ALL SELECT 'Magický střeh III' AS nazev, 16 AS uroven, '50 magů' AS mag, NULL AS dos, NULL AS sesl, NULL AS trv, NULL AS un, 'Magický střeh zareaguje na každé kouzelnické kouzlo, jehož terčem je hraničář, a pokusí se je pohltit vynaložením vlastní magenergie terče. V závislosti na tom, o jaký typ kouzla se jedná, na koho a za jakých okolností je sesláno, poklesne magenergie terče o určitý násobek magenergie seslaného kouzla (pokud terč uspěje v hodu proti pasti), a pokud si to bude hraničář přát, odrazí se s vynaložením dalšího násobku magenergie zpět k sesilateli. Kouzelnická kouzla, jež mohou být na hraničáře seslána, si hraničáři rozdělují do čtyř skupin: fyzická, psychická, útočná a ochranná. I. Kouzla fyzická působí na hraničářovo hmotné tělo, snaží se ho nějak spoutat, poutat nebo mu alespoň přičarovat oslí uši. II. Kouzla psychická se naopak soustředí na jeho mysl, snaží se ji nějak ovlivnit, od nenápadného vnuknutí nějaké myšlenky až po naprosté převzetí kontroly. III. Kouzla útočná mají schopnost přetvářet magenergii v různé hmotné či nehmotné látky a s jejich pomocí napadnout hraničářovo tělo a ublížit mu. IV. Kouzla ochranná jsou schopna chránit hraničáře před fyzickými i duševními útoky. O přesné zařazení kouzla se vždy postará PJ, který kouzlo po odečtení rozdílu úrovní hodí na příslušnou past. Toto kouzlo není všelékem proti kouzelníkům — vůbec například nechrání před mentálními útoky a také nijak nereaguje, pokud kouzelník vytvoří nějakou iluzi v prostoru mimo hraničáře. Zde totiž na hraničáře žádná magenergie přímo nepůsobí. Terčem seslaného kouzla může být chodec nebo druid, a sice na 16. a vyšší úrovni. U obou povolání záleží na tom, zda jsou v bdělém stavu, či spí, u druida pak dále na tom, zda je ve hvozdu či mimo něj. Nebezpečnost pasti rozhodující o tom, zda bylo kouzlo úspěšně odraženo, mimo jiné záleží na rozdílu úrovní sesilatele a terče (konkrétně na čtvrtině rozdílu úrovní). Tabulka magického střehu vyjadřuje obtížnost pohlcení respektive odražení kouzla v různých situacích. Číslem ze sloupce ,P'' si vynásobíme počet magů vynaložených na kouzlo seslané na hraničáře a zjistíme tak magenergii nutnou k jeho pohlcení. Kouzlo bude pohlceno, pokud terč uspěje v hodu proti pasti. Číslo ze sloupce ,O'' se použije při výpočtu magenergie nutné k odražení kouzla ze sesilatele.' AS pop
  UNION ALL SELECT 'Magický střeh IV' AS nazev, 16 AS uroven, '100 magů' AS mag, NULL AS dos, NULL AS sesl, NULL AS trv, NULL AS un, 'Magický střeh zareaguje na každé kouzelnické kouzlo, jehož terčem je hraničář, a pokusí se je pohltit vynaložením vlastní magenergie terče. V závislosti na tom, o jaký typ kouzla se jedná, na koho a za jakých okolností je sesláno, poklesne magenergie terče o určitý násobek magenergie seslaného kouzla (pokud terč uspěje v hodu proti pasti), a pokud si to bude hraničář přát, odrazí se s vynaložením dalšího násobku magenergie zpět k sesilateli. Kouzelnická kouzla, jež mohou být na hraničáře seslána, si hraničáři rozdělují do čtyř skupin: fyzická, psychická, útočná a ochranná. I. Kouzla fyzická působí na hraničářovo hmotné tělo, snaží se ho nějak spoutat, poutat nebo mu alespoň přičarovat oslí uši. II. Kouzla psychická se naopak soustředí na jeho mysl, snaží se ji nějak ovlivnit, od nenápadného vnuknutí nějaké myšlenky až po naprosté převzetí kontroly. III. Kouzla útočná mají schopnost přetvářet magenergii v různé hmotné či nehmotné látky a s jejich pomocí napadnout hraničářovo tělo a ublížit mu. IV. Kouzla ochranná jsou schopna chránit hraničáře před fyzickými i duševními útoky. O přesné zařazení kouzla se vždy postará PJ, který kouzlo po odečtení rozdílu úrovní hodí na příslušnou past. Toto kouzlo není všelékem proti kouzelníkům — vůbec například nechrání před mentálními útoky a také nijak nereaguje, pokud kouzelník vytvoří nějakou iluzi v prostoru mimo hraničáře. Zde totiž na hraničáře žádná magenergie přímo nepůsobí. Terčem seslaného kouzla může být chodec nebo druid, a sice na 16. a vyšší úrovni. U obou povolání záleží na tom, zda jsou v bdělém stavu, či spí, u druida pak dále na tom, zda je ve hvozdu či mimo něj. Nebezpečnost pasti rozhodující o tom, zda bylo kouzlo úspěšně odraženo, mimo jiné záleží na rozdílu úrovní sesilatele a terče (konkrétně na čtvrtině rozdílu úrovní). Tabulka magického střehu vyjadřuje obtížnost pohlcení respektive odražení kouzla v různých situacích. Číslem ze sloupce ,P'' si vynásobíme počet magů vynaložených na kouzlo seslané na hraničáře a zjistíme tak magenergii nutnou k jeho pohlcení. Kouzlo bude pohlceno, pokud terč uspěje v hodu proti pasti. Číslo ze sloupce ,O'' se použije při výpočtu magenergie nutné k odražení kouzla ze sesilatele.' AS pop
  UNION ALL SELECT 'Velký magický střeh' AS nazev, 16 AS uroven, '1000 magů' AS mag, NULL AS dos, NULL AS sesl, NULL AS trv, NULL AS un, 'Magický střeh zareaguje na každé kouzelnické kouzlo, jehož terčem je hraničář, a pokusí se je pohltit vynaložením vlastní magenergie terče. V závislosti na tom, o jaký typ kouzla se jedná, na koho a za jakých okolností je sesláno, poklesne magenergie terče o určitý násobek magenergie seslaného kouzla (pokud terč uspěje v hodu proti pasti), a pokud si to bude hraničář přát, odrazí se s vynaložením dalšího násobku magenergie zpět k sesilateli. Kouzelnická kouzla, jež mohou být na hraničáře seslána, si hraničáři rozdělují do čtyř skupin: fyzická, psychická, útočná a ochranná. I. Kouzla fyzická působí na hraničářovo hmotné tělo, snaží se ho nějak spoutat, poutat nebo mu alespoň přičarovat oslí uši. II. Kouzla psychická se naopak soustředí na jeho mysl, snaží se ji nějak ovlivnit, od nenápadného vnuknutí nějaké myšlenky až po naprosté převzetí kontroly. III. Kouzla útočná mají schopnost přetvářet magenergii v různé hmotné či nehmotné látky a s jejich pomocí napadnout hraničářovo tělo a ublížit mu. IV. Kouzla ochranná jsou schopna chránit hraničáře před fyzickými i duševními útoky. O přesné zařazení kouzla se vždy postará PJ, který kouzlo po odečtení rozdílu úrovní hodí na příslušnou past. Toto kouzlo není všelékem proti kouzelníkům — vůbec například nechrání před mentálními útoky a také nijak nereaguje, pokud kouzelník vytvoří nějakou iluzi v prostoru mimo hraničáře. Zde totiž na hraničáře žádná magenergie přímo nepůsobí. Terčem seslaného kouzla může být chodec nebo druid, a sice na 16. a vyšší úrovni. U obou povolání záleží na tom, zda jsou v bdělém stavu, či spí, u druida pak dále na tom, zda je ve hvozdu či mimo něj. Nebezpečnost pasti rozhodující o tom, zda bylo kouzlo úspěšně odraženo, mimo jiné záleží na rozdílu úrovní sesilatele a terče (konkrétně na čtvrtině rozdílu úrovní). Tabulka magického střehu vyjadřuje obtížnost pohlcení respektive odražení kouzla v různých situacích. Číslem ze sloupce ,P'' si vynásobíme počet magů vynaložených na kouzlo seslané na hraničáře a zjistíme tak magenergii nutnou k jeho pohlcení. Kouzlo bude pohlceno, pokud terč uspěje v hodu proti pasti. Číslo ze sloupce ,O'' se použije při výpočtu magenergie nutné k odražení kouzla ze sesilatele.' AS pop
  UNION ALL SELECT 'Oživ mrtvého' AS nazev, NULL AS uroven, 'nejméně 50 magů' AS mag, 'dotyk' AS dos, '1 směna' AS sesl, 'stálé' AS trv, 'nevycerpavajici' AS un, 'Rozsah: 1 tvor. Druh: hromadné. Tímto kouzlem lze oživit bytost, která je krátkou dobu po smrti, tj. přišla na veškeré životy. Na seslání kouzla je zapotřebí nejméně 50 magů, přičemž za každou směnu, která uplynula od úmrtí postavy, je třeba přidat dalších 5 magů. Když je magů dost, PJ si za oživovanou bytost hodí na past Odl ~ 10 ~ oživení/nic. Hraničář může tuto past ovlivnit — za každých dalších vydaných 5 magů se její nebezpečnost o 1 sníží. Oživená bytost bude mít 1 život a pravděpodobně se okamžitě ocitne pod mezí vyřazení. Kouzlo v bytosti udrží život jednu směnu. Za tu dobu je třeba ovázat jí rány, případně neutralizovat jed nebo jinou látku, která přivodila smrt. Nestane-li se tak, bytost opět zemře. Takto lze oživit pouze tělo celistvé, maximálně s jedním useknutým údem (nikoli hlavou). Oživení těla více narušeného, ale nikoli úplně zničeného, je ve všech ohledech magově dvakrát náročnější (možnost seslání kouzla a jeho cenu určí dle svého odhadu PJ). Kouzlem nelze rušit např. zkamenění. Sešle-li kouzlo druid ve hvozdu, dodá hvozd 1/5 celkové magenergie, která se odčerpá z jeho probouzecí magenergie.' AS pop
  UNION ALL SELECT 'Odstranění únavy' AS nazev, NULL AS uroven, '2 magy za 1–6 bodů únavy' AS mag, 'dotyk' AS dos, '1 kolo' AS sesl, 'stálé' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 tvor. Druh: osobní. Toto kouzlo při vynaložení 2 magů odstraní 1–6 bodů únavy tvorovi, na kterého je sesláno. Žádná bytost nemůže mít méně než 0 bodů únavy. Odstraňuje pouze únavu způsobenou bojem, pohybem či duševní námahou, nikoli hladověním nebo žízní. Kouzlo je během jednoho kola možno seslat s vyšší magenergií, přičemž za každé 2 dodané magy se sníží únava o 1k6 znovu. Denně lze tímto kouzlem odstranit nejvýše tolik bodů únavy, kolik je dvojnásobek vytrvalosti tvora, na něhož je sesíláno. Případné další seslání kouzla už nemá žádný efekt. Pomocí tohoto kouzla nelze nahradit spánek nutný k meditaci. Sešle-li kouzlo druid ve hvozdu, odstraní 1k10 bodů únavy a odčerpá navíc 1 mag z probouzecí magenergie hvozdu. Živočišné jedy a séra — Přírodní živočišné jedy jsou značně nestabilní a do použitelné formy je schopen zpracovat pouze pyrofor na dostatečně vysoké úrovni. Hraničář ovšem může být nápomocen při obstarávání výchozích surovin. Takové látky lze získat z mrtvoly čerstvě zabitého jedovatého tvora nebo manipulací s živým tvorem lapeným například pro lov podle pravidel pro lov. Hraničář je schopen získávat jed pouze z tvorů, které dobře zná, tedy z takových, na něž by mohl úspěšně seslat kouzlo uzdrav lehká zranění. Preparace mrtvoly nebo manipulace s živým tvorem trvá jednu směnu, během které lze do připraveného flakónku vytěžit 1 až 3 dávky jedu. Živý tvor může mít nejvýše stejnou třídu velikosti jako hraničář. Po 12 hodinách ve svém těle opět vyprodukuje dostatečné množství jedu, takže lze manipulaci s ním opakovat.' AS pop
) v
JOIN seznamy_kouzel s ON s.nazev = 'Kouzla hraničáře'
JOIN povolani p ON p.id = s.povolani_id AND p.nazev = 'Hraničář';
-- TODO ověřit proti skenu (neúplný/nejasný zápis v předloze u): Magické zrcadlo; Úder nenávisti

-- Kouzla hraničáře (domácí verze - Chodec) / Chodec (9 kouzel)
INSERT INTO kouzla (nazev, seznam_kouzel_id, uroven_kouzla, cena_magenergie, dosah, doba_seslani, doba_trvani, typ_unavy, popis)
SELECT v.nazev, s.id, v.uroven, v.mag, v.dos, v.sesl, v.trv, v.un, v.pop
FROM (
  SELECT 'Mluv se zvířaty' AS nazev, 2 AS uroven, '3magy za první kolo, 2 magy…' AS mag, '20 sáhů' AS dos, '2 kola' AS sesl, NULL AS trv, 'vycerpavajici' AS un, 'Magenergie (přesně): 3magy za první kolo, 2 magy za každé další. Rozsah: 1 zvíře. -jen zviřata s int.1 a výš, v jednom kole jedna otázka a jedna odpověd' AS pop
  UNION ALL SELECT 'Najdi stopy' AS nazev, NULL AS uroven, '3magy' AS mag, '0' AS dos, '2 kola' AS sesl, '6 směn' AS trv, 'vycerpavajici' AS un, 'Rozsah: jen hraničář.' AS pop
  UNION ALL SELECT 'Najdi zvíře' AS nazev, NULL AS uroven, '3 magy' AS mag, '5 mil' AS dos, '2 kola' AS sesl, 'ihned' AS trv, 'vycerpavajici' AS un, 'Rozsah: nejbližší zvíře daného druhu. - 100% šance najití zvířete do 1 míle, další míle -20% atd. jen běžná zvířata ve volné přírodě' AS pop
  UNION ALL SELECT 'Neutralizuj jed' AS nazev, NULL AS uroven, '6 magů' AS mag, 'dotyk' AS dos, '1 kolo' AS sesl, 'stále' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 postava. - u jedů působících v kolech(i ihned) musí seslat v kole po zasažení jedem, -u jedů působících ve směnách do jedné směny, u jedů v rámci hodin stačí do jedné hodiny' AS pop
  UNION ALL SELECT 'Odstraň ochromení' AS nazev, NULL AS uroven, '4 magy' AS mag, 'dotek' AS dos, '2 kola' AS sesl, 'ihned' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 postava. - mdloby, ochromení, křeče apod.' AS pop
  UNION ALL SELECT 'Uzdrav lehká zranění' AS nazev, NULL AS uroven, '3 magy' AS mag, 'dotyk' AS dos, '3 kola' AS sesl, 'stálé' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 postava. - vyléčí 1k6+1životů' AS pop
  UNION ALL SELECT 'Uzdrav těžká zranění' AS nazev, NULL AS uroven, '5 magů' AS mag, 'dotyk' AS dos, '3 kola' AS sesl, 'stálé' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 postava. - vyléčí 2k6+2 životů' AS pop
  UNION ALL SELECT 'Uzdrav nemocného' AS nazev, NULL AS uroven, '12 magů' AS mag, 'dotyk' AS dos, '2 směny' AS sesl, 'stálé' AS trv, 'nevycerpavajici' AS un, 'Rozsah: 1 postava. - vyléčí většinu nemocí včetně lykantropie. při vážné nemoci se bude muset postava podrobit rekonvalescenci.' AS pop
  UNION ALL SELECT 'Zmam osobu' AS nazev, NULL AS uroven, 'viz níže' AS mag, '7 sáhů' AS dos, '3kola' AS sesl, 'viz níže' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 tvor. - zmámit jde jen tvory s inteligencí 1 a výše. zmámený jedná jako nejlepší přítel hraničáře.' AS pop
) v
JOIN seznamy_kouzel s ON s.nazev = 'Kouzla hraničáře (domácí verze - Chodec)'
JOIN povolani p ON p.id = s.povolani_id AND p.nazev = 'Chodec';
-- TODO ověřit proti skenu (neúplný/nejasný zápis v předloze u): Najdi stopy

-- Kouzla hraničáře (chodecký luk) / Chodec (11 kouzel)
INSERT INTO kouzla (nazev, seznam_kouzel_id, uroven_kouzla, cena_magenergie, dosah, doba_seslani, doba_trvani, typ_unavy, popis)
SELECT v.nazev, s.id, v.uroven, v.mag, v.dos, v.sesl, v.trv, v.un, v.pop
FROM (
  SELECT 'Salva šípů' AS nazev, NULL AS uroven, 'viz níže' AS mag, NULL AS dos, '1 kolo' AS sesl, 'ihned' AS trv, 'vycerpavajici' AS un, 'Únava: 1 bod = 1 salva. Rozsah: 1 cíl = 1 salva. Chodec uchopí do ruky naráz 1 až 4 šípy. Každý další šíp k tomu prvnímu stojí 2 magy a Úč se snižuje o 1 za každý další šíp k tomu prvnímu. Při střelbě 4 šípů je tedy Úč 3 a stojí 6 magů. Útok luku lze navrátit na původní hodnotu zaplacením 2 magů za každý šíp navíc. 4 šípy s plným Úč tedy stojí 12 magů. V případě salvy šípů neplatí pravidlo střelby od boku a nemají tak postih -2Úč. Salvu šípů lze kombinovat s dovedností střelba do dálky. Bonusové zranění 1k4 při fatálním úspěchu lze aplikovat pouze na jednu část salvy. (4 šípy = 1k4 bonusového zranění) Za každý šíp si sesilatel hází útok zvlášť a cíl se na každý zvlášť brání. Pokud má k dispozici dostatek magů a šípů, může kouzlo ´´protáhnout´´ a vystřelit další salvu šípů za stejných podmínek jako tu první, ale seslání je pouze 1 akce. Takto může opakovat po splenění již řečených podmínek. Chodec musí nahlásit jak dlouho bude salvu protahovat. Pokud z nějakého důvodu salvu přeruší, přijde o vložené magy. Po dobu sesílání i samotné střelby se počítá jako kouzlící postava. Množství šípů a počet salv, které chodec vměstná do jednoho seslání se zvyšuje s jeho úrovní. salva vždy max 4 šípy 6. úroveň. až 4 šípy v maximálně 1 salvě | 1 salva | 4 šípy / 6+6 magů 10. úroveň. až 6 šípů v maximálně dvou salvách | 2 salvy | 6 šípů / 10+10 15. úroveň. až 7 šípů v maximálně dvou salvách | 2 salvy | 7 šípů / 12+12 21. úroveň. až 8 šípů šípů v maximálně dvou salvách | 2 salvy | 8 šípů / 14+14 25. úroveň. až 10 šípů v maximálně třech salvách | 3 salvy | 10 šípů / 18+18 30. úroveň až 11 šípů v maximálně třech salvách | 3 salvy | 11 šípů / 20+20 33. úroveň až 12 šípů v maximálně třech salvách | 3 salvy | 12 šípů / 22+22' AS pop
  UNION ALL SELECT 'Sestřel šípy' AS nazev, NULL AS uroven, NULL AS mag, NULL AS dos, 'ihned' AS sesl, '1 obrana' AS trv, NULL AS un, 'Chodec je schopen sestřelit max. 3 šípy. Každý musí být dál o 5 sáhů než ten první. Tedy 1 šíp z 5 sáhů, 2 šípy z 10 sáhů a 3 šípy z 15 sáhů. Šíp však nemusí být sestřelen. Úč útočníka musí být menší nebo stejné jako chodcovo Úč. Šípy úspěšně zasažené tímto kouzlem jsou zničené, chodcovi jsou v pořádku. Každý sestřelený šíp stojí 3 magy.' AS pop
  UNION ALL SELECT 'Obrana' AS nazev, NULL AS uroven, '3 magy' AS mag, NULL AS dos, 'ihned' AS sesl, '2 směny' AS trv, NULL AS un, 'Po seslání tohoto kouzla se chodcův luk zatvrdí a umožní mu se s ním bránit útokům z blízka. Útočnost se změní na 0 a obrana na +2. Bude li chodec takto pozměněným lukem útočit, bude působit pouze stínová zranění. Luk může být poškozen kouzlem chodcova meče - Poškození zbraně - v tomto případě se luk počítá jako kovaná zbraň. Je li takto luk ´´poškozen´´ kouzlo se přeruší a luk se vrátí do své původní podoby a parametrů.' AS pop
  UNION ALL SELECT 'Aura' AS nazev, NULL AS uroven, '5 magů' AS mag, NULL AS dos, '1 kolo' AS sesl, '2 směny' AS trv, 'vycerpavajici' AS un, 'Rozsah: Chodec. Kolem chodce se utvoří štít, který s 50% šancí odrazí útočná kouzla. každá další osoba do vlivu Aury stojí 5 magů. Každá osoba má svůj vlastní štít. Nesmí být však dále jak 100 sáhů od chodce, jinak se štít zruší.' AS pop
  UNION ALL SELECT 'Strážce' AS nazev, NULL AS uroven, '18 magů' AS mag, NULL AS dos, '2 kola' AS sesl, '2 směny' AS trv, 'vycerpavajici' AS un, 'Únava: 1 bod. Chodec zabodne svůj luk do země a za 2 kola z něj vyroste velký zlý strom s vlastní vůlí, který bude chránit chodce do posledního dechu. Funguje na každém povrchu, není li řečeno jinak. Životaschopnost: 20 (Nebo 80 životů) Úč 6, proti postavám beze zbroje +2 k Úč. Oč. 7 Velikost C Odolnost 18 Pohyblivost 4 - 1 sáh za kolo v roz. soub. systému Inteligence 6 4 útoky za akci Dosah 1-2 Útočí větvemi, které mají speciální vlastnost Třísky. Když zasáhne stejnou bytost 2x za sebou, dostanou se mu třísky do těla a sníží mu Úč. i Oč. o 1. Za každé další dva útoky se děje totéž. Nelze jít do mínusových hodnot. Má vlastní iniciativu. Bonus za obratnost je 0. Po vyvolání má okamžitě 1 akci.' AS pop
  UNION ALL SELECT 'Smrtící šíp' AS nazev, NULL AS uroven, '15 magů' AS mag, NULL AS dos, 'ihned' AS sesl, '1 útok' AS trv, NULL AS un, 'takto očarovaný šíp, který zraní nepřítele aspoň za 1 život způsobí, že do něj sjede blesk z čistého nebe za 4k10 životů. Je zde past Roz-1/2Odol- 50% zranění/-0-. Tedy že postava která si úspěšné hodí proti pasti dostane pouze poloviční zranění.' AS pop
  UNION ALL SELECT 'Přímá střela' AS nazev, NULL AS uroven, '5 magů za každou překážku' AS mag, NULL AS dos, '2 kola' AS sesl, 'ihned' AS trv, 'vycerpavajici' AS un, 'Šíp pod vlivem tohoto kouzla poletí dokud bude mít magy, nebo dokud cíle neuspějí proti pasti. Past Roz. Odol. -5- průnik/zranění za ⅓ Úč. luku. Má li na sobě postava aspoň šupinovou zbroj a lepší, je past o 1 vyšší. Magův štít chrání proti tomuto šípu pouze za +3 a projde li skrz, hází si na past. Šíp letí po celou dobu letu s nezměněnou silou a každý cíl který neuspěje proti pasti je zraněn za hodnotu hozeného útoku. Cíle musí být za sebou a v dostřelu luku. A maximální počet cílů je roven ½ úrovně chodce. Takto očarovaný šíp je schopen s 80% šancí projít skrz 5 coulů dřeva. I tato překážka se počítá jako cíl.' AS pop
  UNION ALL SELECT 'Krupobití střel' AS nazev, NULL AS uroven, NULL AS mag, NULL AS dos, '1 kolo' AS sesl, 'ihned' AS trv, 'vycerpavajici' AS un, 'Únava: 5 bodů / 10 bodů. Četnost: 1 za den. Chodec vystřelí do vzduchu obsah celého toulce naráz. Tyto šípy se pak ve výšce 10 sáhů prudce samy stočí k zemi kde dopadnou na cíle. Postavy které nemají štít mají automaticky -2 na obranu. Šípy dopadají v co nejkruhovějším tvaru s rozložením 1 šíp na hex. Všechny šípy mají útočnou hodnotu hozené útoku. Toulce musí mít volně k dispozici. Je zde 20% šance, že se zničí tětiva.' AS pop
  UNION ALL SELECT 'Naváděná střela' AS nazev, NULL AS uroven, '6 magů' AS mag, NULL AS dos, 'ihned' AS sesl, 'ihned' AS trv, NULL AS un, 'Únava: 1 bod. Šíp je naváděn silou vůle na cíl který je za překážkou. Například za hradbami. Chodec musí přesně vědět kde se cíl v moment výstřelu nachází byť ho přímo nevidí. Buďto ho musí sám bezprostředně zahlédnout, či mu toto musí někdo zprostředkovat.' AS pop
  UNION ALL SELECT 'Šíp Železného chodce' AS nazev, NULL AS uroven, '2 magy za každých 10 sáhů' AS mag, NULL AS dos, '1 kolo' AS sesl, 'ihned' AS trv, 'vycerpavajici' AS un, 'Chodec je schopen magicky posílit dostřel svého luku nad jeho maximální úroveň. Šípy které letí nad maximální dostřel mají -2Úč. Střílel by li chodec na dvojnásobek dostřelu či větší vzdálenost, postih je pak -4Úč. Při trojnásobku - 6Úč.' AS pop
  UNION ALL SELECT 'Fosforová střela' AS nazev, NULL AS uroven, '1 mag' AS mag, NULL AS dos, 'ihned' AS sesl, '1 směna' AS trv, NULL AS un, 'Chodecká střela bude svítit lehce nažloutlým světlem po dobu 1 směny od výstřelu intenzitou 1 pochodně. Parametry šípu se nijak nemění, ale šíp se po uplynutí 1 směny rozpadne na prach.' AS pop
) v
JOIN seznamy_kouzel s ON s.nazev = 'Kouzla hraničáře (chodecký luk)'
JOIN povolani p ON p.id = s.povolani_id AND p.nazev = 'Chodec';

-- Kouzla hraničáře (chodcův meč) / Chodec (8 kouzel)
INSERT INTO kouzla (nazev, seznam_kouzel_id, uroven_kouzla, cena_magenergie, dosah, doba_seslani, doba_trvani, typ_unavy, popis)
SELECT v.nazev, s.id, v.uroven, v.mag, v.dos, v.sesl, v.trv, v.un, v.pop
FROM (
  SELECT 'Dvojitý sek' AS nazev, 6 AS uroven, '8 magů' AS mag, NULL AS dos, NULL AS sesl, '1 kolo' AS trv, NULL AS un, 'Toto kouzlo chodci umožní, aby v jednom kole zaútočil dvakrát, respektive dává mu bonus k iniciativě +6 v rozšířeném soubojovém systému — herní mechanismus je podobný kouzlu rychlost, ale akce takto získané smíš využívat jen na boj, to znamená na akci obrana nebo útok tímto mečem. Je to, jako bys na začátku kola prohlásil, že budeš bojovat.' AS pop
  UNION ALL SELECT 'Odraz projektily' AS nazev, 6 AS uroven, '2, 4, 6, 8 magů' AS mag, NULL AS dos, NULL AS sesl, '1 kolo' AS trv, NULL AS un, 'Pomocí tohoto kouzla může chodec mečem odrazit hvězdici, kámen (do velikosti pěsti), flakónek či jiný vržený předmět malých rozměrů. Chodec se musí rozhodnout, zda chce seslat kouzlo nebo proti projektilu hodit na obranu. Nemůže si napřed hodit a pak teprve seslat kouzlo, na to je již pozdě. Chodec může v jednom kole na kouzlo vynaložit nejvýše 8 magů a odrazit tak celkem 4 projektily. (Hvězdice k odražení musí být na chodce vržena z dálky a plnou rychlostí, chodec si ji nemůže nahodit a mečem odpálit.) Chodec si po seslání kouzla vybere, které projektily bude mečem odrážet — jakmile je kouzlo sesláno, meč je začne odrážet, dokud bude magenergie kouzla stačit nebo dokud kolo neskončí. Z hlediska rozšířeného souboje odražení nestojí žádnou akci (podobně jako obrana proti střelbě).' AS pop
  UNION ALL SELECT 'Odraz šípy' AS nazev, 6 AS uroven, '3, 6 magů' AS mag, NULL AS dos, NULL AS sesl, '1 kolo' AS trv, NULL AS un, 'Pomocí tohoto kouzla může chodec mečem odrazit vystřelený šíp (nebo šipku z kuše). Je 80% pravděpodobnost, že šíp bude potom zlomený. Podobně jako u kouzla odraz projektily se chodec musí rozhodnout, zda kouzlit, nebo si házet na obranu. Chodec může v jednom kole na kouzlo vynaložit nejvýše 6 magů a odrazit tak 2 šípy nebo šipky. Stejně jako u odraz projektily i zde platí, že si chodec nemůže vybrat, které střely bude odrážet, a že z hlediska rozšířeného souboje nestojí odrážení žádnou akci (podobně jako obrana proti střelbě).' AS pop
  UNION ALL SELECT 'Poškození zbraně' AS nazev, 6 AS uroven, '5 magů' AS mag, NULL AS dos, NULL AS sesl, '1 kolo' AS trv, NULL AS un, 'Po seslání tohoto kouzla se chodec může pokusit poškodit až zničit protivníkovu zbraň výpadem. Poškodit se dají pouze nemagické zbraně (ale chodec nepozná, zda je zbraň magická, nebo ne). Po seslání kouzla se může chodec pokusit soupeře oklamat fintou nebo zaútočit přímo na jeho zbraň. Pokud zvolí první možnost, hází si na útok a zranil-li by soupeře alespoň 1 život (v opačném případě chodec ztrácí magenergii bez užitku). Při útoku přímo na zbraň, bez klamného výpadu na tělo, chodec při nejbližším soupeřově útoku (ale nejpozději v příštím kole) ztrácí obranu zbraní a má tedy postih −3 k hodu na obranu. Soupeřova zbraň má OČ 6 + bonus za obratnost majitele. Po útoku na zbraň záleží, kolik jí chodec ubral životů a z jakého je materiálu. Zbraně – dřevěné: 1–3 životy — useknutím kusu klesla útočnost zbraně o 1. 4–6 životů — useknutím kusu klesla útočnost zbraně o 2. 7 a více životů — zbraň byla zásahem zcela zničena. okované a druidova hůl: 1–4 životy — useknutím kusu klesla útočnost zbraně o 1. 5–8 životů — useknutím kusu klesla útočnost zbraně o 2. 9 a více životů — zbraň byla zásahem zcela zničena. kovové: 1–5 životů — na zbrani se udělal zub, který její útočnost snížil o 1. 6–11 životů — na zbrani se udělal zub, který její útočnost snížil o 2. 12 a více životů — zbraň byla zásahem zcela zničena.' AS pop
  UNION ALL SELECT 'Prasátko' AS nazev, 6 AS uroven, '2 magy' AS mag, NULL AS dos, NULL AS sesl, 'viz níže' AS trv, NULL AS un, 'Toto kouzlo lze použít pouze za slunného dne, když na meč svítí slunce. Čepel zbraně se v chodcově ruce natočí tak, že její lesklá plocha "blýskne" protivníkovi do očí. Chodcův oslněný protivník má v rozšířeném soubojovém systému v tomto kole postih −2 k hodu na iniciativu a v dalším −1 (respektive −4 a −2 se stříbrným mečem a −6 a −3 se zlatým mečem — viz transmutace kovu níže). Kouzlo lze použít jen jednou za kolo, avšak při vyvolání během dvou a více kol po sobě se postihy mohou sčítat (celkem tedy na −3, respektive −6 se stříbrným a −9 se zlatým mečem).' AS pop
  UNION ALL SELECT 'Svítící čepel' AS nazev, 6 AS uroven, '1 mag' AS mag, NULL AS dos, NULL AS sesl, '3 směny' AS trv, NULL AS un, 'Při tomto kouzle se čepel meče matně rozzáří. Intenzita světla závisí na materiálu, z něhož momentálně meč je (viz transmutace kovu níže). Ocel se v temnotách sotva leskne. V uzavřené chodbě si s ní lze svítit pod nohy a velmi pomalu postupovat (alespoň pokud nechcete někam spadnout nebo spustit nějakou past) rychlostí 50 sáhů za směnu. Venku je toto světlo prakticky nevyužitelné. Těsným přiblížením jím lze osvítit nějaký malý předmět. Stříbro září matným měsíčním svitem. V podzemí nezřetelně osvětlí několik sáhů kolem. Nelze při něm číst, psát, nejsou vidět rysy vzdálenějších postav, avšak dá se při něm docela slušně pomalu jít (rychlostí 100 sáhů za směnu). Venku svítí podobně jako zhasínající pochodeň — lze si osvítit pod nohy a pomalu postupovat, ukazuje se okolí. Zlato svítí v podzemí i na povrchu jako velmi silná lucerna a může snadno oslepit noční tvory nezvyklé světlu, ale nemůže je zranit.' AS pop
  UNION ALL SELECT 'Transmutace kovu' AS nazev, 6 AS uroven, '4 magy' AS mag, NULL AS dos, NULL AS sesl, 'stálé' AS trv, NULL AS un, 'Toto kouzlo chodci umožní proměnit (transmutovat) kov, z něhož je jeho meč, v kov jiný, například proto, že je jím určitá nestvůra v boji zranitelnější. Prakticky se hlavně jedná o proměnu z oceli ve stříbro a zpět, případně z oceli ve zlato, kvůli lepšímu účinku kouzla svítící čepel či prasátko. Stříbrný meč má SZ 5/+2 a svými dalšími vlastnostmi se od meče ocelového nikak neliší. Stříbrná zbraň nemá vliv na žádný jiný kov než na meč, ani kdyby byla s mečem těsně přiložena k jiné zbrani. Stříbrná zbraň má 2% pravděpodobnost poškození (útočnost o 1 klesne, přechází i na ocelový meč) při každém útoku protivníka vybaveného železnou zbraní. Zlatý meč má SZ 3/+2 a 10% pravděpodobnost poškození (viz výše). Transmutace trvá, dokud chodec nezmění materiál meče novým kouzlem. Pokud chodec pustí meč z ruky, změní se jeho kov v obyčejnou ocel. Vezme-li jej chodec opět do ruky, změní se materiál meče tak, aby odpovídal poslední transmutaci.' AS pop
  UNION ALL SELECT 'Uspání démona' AS nazev, 6 AS uroven, 'viz níže' AS mag, NULL AS dos, NULL AS sesl, 'dle dodané magenergie' AS trv, NULL AS un, 'Kouzelné vlastnosti propůjčují zbraním démoni, kteří jsou v nich zachyceni. Na podrobnosti se zeptej nějakého theurga, nyní je však důležité, že pomocí svého meče — a jeho démona — můžeš "uspat" démona ve zbrani nebo zbroji svého protivníka, a tak ji zbavit jejích kouzelných vlastností. Po seslání kouzla si hoď proti pasti Roz ~ 5 — usne/neusne, kde Roz je rozdíl mezi úrovní démona v tvém meči (zpravidla 1) a úrovní démona ve zbrani či zbroji tvého protivníka. Počet kol, na které si v případě úspěchu soupeřova démona uspíš, je určen množstvím dodané magenergie. Za 1 mag usne démon na 1 kolo, za další 2 magy bude spát další kolo, za další 3 magy další kolo atd. PŘÍKLAD: PŘÍKLAD: Uspat démona na 4 kola boje tedy znamená vydat na kouzlo 10 magů. Chodec sešle kouzlo na svou zbraň a pak zaútočí na soupeře. Podobně jako u kouzla poškození zbraně může zaútočit buď přímo na zbraň, nebo se pokusit o klamný výpad. Vyjde-li mu tato finta útoku na tělo (odebral by soupeři útokem alespoň 1 život), záleží na tom, zda útočí na démona ve zbrani, či démona ve zbroji. Útočí-li na démona ve zbroji, výpad se již povedl a démon usnul (pokud chodec uspěl v hodu proti pasti). Útočí-li na démona ve zbrani, musí si ještě hodit na útok proti démonu. Zbraň má OČ 0 + Obr majitele (avšak výsledné OČ nesmí být menší než 0). Pokud by útokem odebral zbrani alespoň 1 život, byl útok úspěšný a démon v ní usne (opět s předpokladem úspěchu v hodu proti pasti). Dokud démon ve zbrani spí, neúčinkuje na ni kouzlo poškození zbraně a nelze ji tak poškodit nebo zničit. Když se démon probudí, zbraň nebo zbroj získá zpět své magické vlastnosti. Pokud je však zbraň zničena, démon z ní uprchne. Magenergie z tohoto kouzla se při neúspěšném útoku neztrácí. Zbraň je jí nabita, dokud se chodci úspěšný útok nezdaří. Pokud na svou zbraň chodec seslal toto kouzlo, avšak neměl možnost jej využít, může jej buď odvolat a ztratit tak jeho magenergii, nebo čekat na jeho vhodné využití. Mezitím však nesmí na meč seslat jiné kouzlo.' AS pop
) v
JOIN seznamy_kouzel s ON s.nazev = 'Kouzla hraničáře (chodcův meč)'
JOIN povolani p ON p.id = s.povolani_id AND p.nazev = 'Chodec';

-- Kouzla hraničáře (psí výcvik) / Hraničář (4 kouzel)
INSERT INTO kouzla (nazev, seznam_kouzel_id, uroven_kouzla, cena_magenergie, dosah, doba_seslani, doba_trvani, typ_unavy, popis)
SELECT v.nazev, s.id, v.uroven, v.mag, v.dos, v.sesl, v.trv, v.un, v.pop
FROM (
  SELECT 'Host v hlavě' AS nazev, NULL AS uroven, '8 magů' AS mag, '50 sáhů' AS dos, NULL AS sesl, NULL AS trv, NULL AS un, 'Rozsah: pes. Vyvoláni: 1 kolo Trvání: 8 směn Hraničářovo vědomí bude sídlit v jeho psu. Bude jej ovládat, cítit, vidět i slyšet jako jeho pes. Jeho vlastní tělo po dobu trvání kouzla obývá jeho pes. jakékoliv zranění ať už psa či hraničáře kouzlo předčasně přeruší.' AS pop
  UNION ALL SELECT 'Jedno tělo' AS nazev, NULL AS uroven, '2 magy za 1. kolo, za další 1' AS mag, 'dotek' AS dos, '1 kolo' AS sesl, 'dle dodané magenergie' AS trv, 'vycerpavajici' AS un, 'Rozsah: pes. Umožní přelévat životy mezi hraničářem a psem rychlostí 5 životů za kolo. Nelze takto přesáhnout maximální množství životů, ani snížit životy pod 0. Hraničáři toto kouzlo používají hlavně k akutnímu léčení svého psa a opravdu jen výjimečně k léčení sama sebe.' AS pop
  UNION ALL SELECT 'Jedna mysl' AS nazev, NULL AS uroven, '2 magy za 1. kolo, za další 1' AS mag, '5 sáhů' AS dos, 'ihned' AS sesl, 'dle magenergie' AS trv, NULL AS un, 'Rozsah: 1 pes. Pod vlivem tohoto kouzla bojuje pes a hraničář jako jeden Při boji se stejným protivníkem mají oba bonus +1Úč. +1Oč. Pokud někdo z nich za trvání kouzla zemře, druhý díky šoku přijde o 2k10 + úrověň postavy životů.' AS pop
  UNION ALL SELECT 'Pes baskervilský' AS nazev, NULL AS uroven, '16 magů' AS mag, 'Dotyk' AS dos, '1 kolo' AS sesl, NULL AS trv, 'vycerpavajici' AS un, 'Rozsah: pes. Trvání 2 směny Po dobu trvání kouzla se hraničářův pes promění v pekelnou stvůru. Naroste do velikosti C, bude všem vyjíma samotného hraničáře, nahánět šílený strach svým zjevem i zápachem. Zvířata s bojovností pod 8 vystraší okamžitě. Ostatní v okruhu 10 sáhů si hází na past Roz., Odol. -6- Útěk/nic. Vystrašená postava bude utíkat nejsnazší cestou co nejdále od takto změněného psa. Bude útočit 3x za 2 kola a získá +2 Úč. +2Oč.' AS pop
) v
JOIN seznamy_kouzel s ON s.nazev = 'Kouzla hraničáře (psí výcvik)'
JOIN povolani p ON p.id = s.povolani_id AND p.nazev = 'Hraničář';

-- Druidova lesní kouzla / Druid (14 kouzel)
INSERT INTO kouzla (nazev, seznam_kouzel_id, uroven_kouzla, cena_magenergie, dosah, doba_seslani, doba_trvani, typ_unavy, popis)
SELECT v.nazev, s.id, v.uroven, v.mag, v.dos, v.sesl, v.trv, v.un, v.pop
FROM (
  SELECT 'Cit dřeva' AS nazev, NULL AS uroven, '2 magy' AS mag, NULL AS dos, '1 kolo' AS sesl, NULL AS trv, 'vycerpavajici' AS un, 'Četnost: kdykoliv. Působení: 6. úroveň. Jestliže druid položí dlaň na kmen libovolného živého stromu, vycítí, kde se v okolí nachází nejbližší čistý vodní zdroj.' AS pop
  UNION ALL SELECT 'Cit kamene' AS nazev, NULL AS uroven, '2 magy' AS mag, NULL AS dos, '1 kolo' AS sesl, NULL AS trv, 'vycerpavajici' AS un, 'Rozsah: koule o poloměru 50 sáhů. Četnost: kdykoliv. Působení: 6. úroveň. Položením dlaně na skálu je druid schopen odhalit blízké jeskynní prostory, jejich přibližný směr a vzdálenost. Stejně tak může ve skále odhalit například pramen.' AS pop
  UNION ALL SELECT 'Cit vody' AS nazev, NULL AS uroven, '2 magy' AS mag, NULL AS dos, '1 kolo' AS sesl, NULL AS trv, 'vycerpavajici' AS un, 'Четnost: kdykoliv. Působení: 6. úroveň. Jestliže druid vztáhne ruce nad pramen, vycítí, zda není škodlivý.' AS pop
  UNION ALL SELECT 'Cit země' AS nazev, NULL AS uroven, '2 magy' AS mag, NULL AS dos, '1 kolo' AS sesl, NULL AS trv, 'vycerpavajici' AS un, 'Četnost: kdykoliv. Působení: 6. úroveň. Jestliže druid vztáhne ruce nad lesní plodiny, vycítí, zda nejsou jedovaté nebo jinak škodlivé.' AS pop
  UNION ALL SELECT 'Hněv lesa' AS nazev, NULL AS uroven, 'veškerá současná' AS mag, NULL AS dos, '1× mezi dvěma úplňky' AS sesl, '1 směna' AS trv, NULL AS un, 'Rozsah: okruh o poloměru 50 sáhů. Působení: 6. úroveň. I v pravé poledne se kolem náhle rozprostře soumrak. Zvířata zděšeně prchají, lidé se chvějí, na všechny padá nevysvětlitelná hrůza. Stromy šumí, přestože je absolutní bezvětří. Kouzlo působí na různé tvory různě. Na tvory s inteligencí 0 kouzlo nepůsobí, takoví tvorové si ho neuvědomují. Ostatní bytosti si musejí hodit 1k10 a přičíst bonus (odečíst postih) za inteligenci. Podle výsledku se řídí jejich jednání. 0 a méně smrtelný strach — bytost prchá a odhazuje vše, co jí překáží v útěku. Je pravděpodobnost 50 %, že zakopne a zraní se za 1–6 životů. Na tuto pravděpodobnost hází každé kolo po dobu deseti kol (po tuto dobu trvá útěk). 1–2 hrůza — bytost prchá a odhazuje vše, co jí překáží v útěku. 3–4 panika — bytost prchá. 5–6 silné znepokojení — bytost se bude za každou cenu snažit při jednání s druidem vyhnout souboji. 7–8 znepokojení — bytost bude s druidem jednat velmi zdvořile a nesáhne k násilí, pokud to pro ni nebude nezbytně nutné. 9–10 mírné znepokojení — bytost se rozhlíží, zda nehrozí útok. 11 a více příjemné rozptýlení — bytost pozoruje snažícího se druida a dobře se baví.' AS pop
  UNION ALL SELECT 'Láska lesa' AS nazev, NULL AS uroven, 'veškerá současná' AS mag, NULL AS dos, '1 kolo' AS sesl, NULL AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 osoba. Четnost: 1× ročně. Působení: 6. úroveň. Toto kouzlo může druid seslat na osobu (tj. bytost s inteligencí 2 a vyšší), která se podle jeho mínění velmi zasloužila o prospěch a samo trvání lesa. Pokud má les (PJ) jiný dojem, kouzlo neúčinkuje a vyplýtvá se zbytečně. Tato osoba se dostává pod ochranu lesa, neútočí na ni divoká zvířata a ona sama nemá chuť je zabíjet, jelikož její přesvědčení se v tomto stavu, ve všem, co je lesní, upravuje až o čtyři stupně směrem k němu. Šestý smysl jí nedovolí, aby se ničím otrávila nebo padla na nastražené pasti, dokáže vždy nalézt dostatek potravy. Z takto vyznamenaných postav se často stávají poustevníci, kteří sídlí v hlubokém lese až do konce svého dlouhého života. Druid se může pokusit toto stav jednou ročně (tj. jednou mezi dvěma zimními slunovraty) zrušit. V případě, že nějaká osoba prokázala lesu opravdu velmi významnou pomoc, les na ni může seslat toto kouzlo sám, i tehdy, jestliže druid toto kouzlo tento rok nemůže láska lesa seslat (třeba proto, že na to nemá potřebný jeden mag). Osoba, která nesouhlasí, aby na ni toto kouzlo bylo sesláno, nebo si toho není vědoma, hází proti kouzlu jako proti pasti s Int ~ 12 ~ nic/láska lesa.' AS pop
  UNION ALL SELECT 'Najdi bytost' AS nazev, NULL AS uroven, '10 magů' AS mag, NULL AS dos, '1 směna' AS sesl, NULL AS trv, 'nevycerpavajici' AS un, 'Rozsah: okruh o poloměru 10 mil. Četnost: úspěšně 1× denně. Působení: 6. úroveň. Druid vyvolá toto kouzlo, pokud chce v okruhu 10 mil najít nějakou bytost či skupinu bytostí (např. bobra či královské vojáky) nebo pokud má pocit, že je družina sledována (pronásledována). Druid se na jednu směnu soustředí na svoji představu hledané bytosti či pocitu nebezpečí, a pokud se mu kouzlo zdaří, dokáže určit směr i vzdálenost místa, kde se daná bytost či skupina vyskytuje, a přibližnou činnost, kterou právě provádí (případně i počet bytostí ve skupině). O seslání tohoto kouzla se lze pokoušet každých šest směn, avšak je ho možno seslat jen jednou úspěšně denně (tj. jednou za dobu od půlnoci do půlnoci). Kouzlo má v okruhu sta sáhů od druida pravděpodobnost úspěchu 100 %; s každým dalším stem sáhů pravděpodobnost klesá o jedno procento. Pokud je v daném okruhu více jedinců či skupin hledaného druhu, druid vycítí nejbližší úspěšně objevenou skupinu. PŘÍKLAD: PŘÍKLAD: Družina je v hlubokém lese pronásledována královskou stráží. Druid o tom ví a rozhodne se zjistit její polohu. Ohlásí to PJ a na jednu směnu se soustředí. V pralese jsou celkem tři skupiny vojáků: první na SV vzdálená 2400 sáhů (pravděpodobnost 77 %), druhá na SZ vzdálená 4600 sáhů (pravděpodobnost 55 %), třetí na jihu vzdálená 12000 sáhů. PJ hodí k% a padne mu 91 — první skupina tedy není objevena. Hází znovu a padne mu 47. Oznámí tedy družině, že objevil skupinu vojáků na SZ, že je asi 4600 sáhů vzdálená a v ní asi 30 mužů, kteří právě táboří. (Kdyby byl druid neúspěšný i při druhém hodu, PJ by mu oznámil, že nic neobjevil — třetí jednotka je příliš daleko. O další hledání by se druid mohl pokusit až za hodinu.)' AS pop
  UNION ALL SELECT 'Orientace' AS nazev, NULL AS uroven, '1 mag' AS mag, NULL AS dos, '1 kolo' AS sesl, NULL AS trv, 'vycerpavajici' AS un, 'Четnost: kdykoliv. Působení: 6. úroveň. Po seslání tohoto kouzla je druid schopen vést družinu hustým lesem téměř tak rychle, jako by kráčela po cestě. Celá družina však musí jít pěšky a nesmí s sebou mít žádná jízdní zvířata. Toto kouzlo také v pralese zabrání bloudění (druid okamžitě najde správný směr). Kouzlo po svém seslání působí tak dlouho, dokud druid neusne.' AS pop
  UNION ALL SELECT 'Temnota' AS nazev, NULL AS uroven, '10 magů' AS mag, NULL AS dos, '1 kolo' AS sesl, '3 směny' AS trv, 'vycerpavajici' AS un, 'Rozsah: okruh o poloměru 300 sáhů. Четnost: 4× mezi dvěma úplňky. Působení: 6. úroveň. Po seslání tohoto kouzla se v okruhu 300 sáhů od druida rozprostře neproniknutelná tma. Druid sám v ní nevidí o nic lépe než ostatní, avšak s pomocí kouzla orientace ji může nezávisle na tom celou cestou opustit. Tato temnota je hustší než obvyklá noční tma; pohlcuje veškeré světlo, a to i světlo pochodní apod. Pochodeň není vidět déle než na 30 coulů a nedají se seslat ohnivá ani světelná kouzla (ale blesky ano, nedají kouzelníkovi však vidět jeho cíl). Temnota omezuje rovněž infravidění, které v ní má pouze desetinový dosah.' AS pop
  UNION ALL SELECT 'Úkryt' AS nazev, NULL AS uroven, '3×životaschopnost' AS mag, 'dotyk' AS dos, '2 kola' AS sesl, NULL AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 živý tvor. Četnost: kdykoliv. Působení: 6. úroveň. Tímto kouzlem je možné přenést duši (mysl, vzpomínky, osobnost) jednoho živého tvora s inteligencí vyšší než 1 do nějakého neživého předmětu. Podmínkou úspěchu je, že terč musí s přenosem souhlasit. Jeho staré tělo se mrtvé zhroutí k zemi. Terč se do něj může vrátit během následujících 12 hodin pomocí dalšího kouzla úkryt. Mysl terče je také možné přemístit do jiného těla mrtvého méně než 12 hodin. Pokud jde o jinou bytost stejné rasy jako terč, bude ji terč schopen ovládat, ale nebude schopen využívat jejích zvláštních schopností. Bude moci používat své vlastní zvláštní schopnosti, ovšem jako by byl v pozůstalém těle (zaokrouhluj nahoru). Pokud měla bytost navíc nižší úroveň (resp. životaschopnost) než terč, klesne úroveň terče v novém těle až na polovinu hodnotu původní úrovně (resp. životaschopnosti) bytosti, jíž tělo patřilo. Terči zůstává jeho původní inteligence, všechny ostatní stupně vlastností a životy se mění podle nového těla. Cílem přenosu duše nemusí být jen mrtvé tělo, ale i skutečný neživý předmět, například nůžky nebo pergamen. V takovém případě terč vůbec nebude schopen využívat své zvláštní schopnosti, nebude moci se pohybovat ani mluvit. Bude vnímat své okolí povrchem předmětu podobně jako kůží, uslyší i zvuky, byť zkreslené. Vizuální vjemy zachytí pouze tehdy, budou-li se na povrchu předmětu odrážet (zrcadlo, křišťálová koule). Úkryt je výjimečný tím, že jej může používat pouze druid.' AS pop
  UNION ALL SELECT 'Pouto krve' AS nazev, NULL AS uroven, 'veškerá současná' AS mag, NULL AS dos, '1 kolo' AS sesl, NULL AS trv, 'vycerpavajici' AS un, 'Четnost: 1× mezi dvěma úplňky. Působení: 9. úroveň. Vztažením rukou dokáže zraněný druid uprosit libovolné lesní zvíře (nebo smečku, podobně jako při odvracení zvířat), aby na něj neútočilo. Tato ochrana pak trvá ještě jeden celý den, ale vztahuje se pouze na toto konkrétní zvíře, respektive smečku.' AS pop
  UNION ALL SELECT 'Pouto lásky' AS nazev, NULL AS uroven, 'veškerá současná' AS mag, NULL AS dos, '1 směna' AS sesl, NULL AS trv, 'nevycerpavajici' AS un, 'Rozsah: 1 osoba. Четnost: 1× mezi dvěma úplňky. Působení: 12. úroveň. Druid dokáže vrátit život mrtvé postavě, která mu je drahá, tím, že nad ní vztáhne ruce a vykřikne: „Vstaň!" (Pán jeskyně zváží vztah mezi druidem a oživovanou postavou; drahá může být například osoba, která druidovi prokázala nějakou službu, zachránila mu život apod. Pokud to bude osoba, kterou druid bude pouze potřebovat živou a přitom ji nebude nesnášet, oživení se nezdaří a druid bude zraněn za 10–30 životů.) K oživení musí dojít nejvýše šest směn po zabití (směna potřebná na vyvolání kouzla je počítána jako sedmá). Po tomto kouzlu nebude druid schopen jeden den používat žádnou ze svých zvláštních schopností, tři dny (včetně toho jednoho) nebude sesílat lesní kouzla a týden (včetně těchto tří dnů) bude velmi unavený a nebude moci bojovat (bude mít postih −5 na útok i na obranu). Oživená postava bude mít 1 život a pravděpodobně se okamžitě ocitne pod mezí vyřazení.' AS pop
  UNION ALL SELECT 'Pouto života' AS nazev, NULL AS uroven, 'veškerá současná' AS mag, NULL AS dos, '1 kolo' AS sesl, NULL AS trv, 'vycerpavajici' AS un, 'Четnost: 3× za život. Působení: 15. úroveň. Druid vztáhne ruce a vykřikne: „Ty jsi můj život." Těmito slovy se plně vydává v ochranu lesní moci. Na toho, kdo by mu chtěl uškodit, bude tato prastará síla pohlížet jako na svého osobního nepřítele — ne nadarmo se říká, že někdy mohou ožít i stromy. Druid by však měl být opatrný; tímto kouzlem se vydává na milost a nemilost přísné lesní moci, a pokud ji musel žádat o pomoc proto, že se do nesnází dostal svým špatným jednáním, pak běda mu... Toto kouzlo může druid výjimečně seslat i tehdy, když nemá ani jeden mag.' AS pop
  UNION ALL SELECT 'Neúnavná zem' AS nazev, NULL AS uroven, NULL AS mag, 'dotyk' AS dos, '2 kola' AS sesl, '1 hodina' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 tvor. Pokud se cíl holou kůží dotýká země(hlína,přírodní kámen, volná příroda), nedostává únavu za pohyb.' AS pop
) v
JOIN seznamy_kouzel s ON s.nazev = 'Druidova lesní kouzla'
JOIN povolani p ON p.id = s.povolani_id AND p.nazev = 'Druid';

-- Malá lesní kouzla / Druid (8 kouzel)
INSERT INTO kouzla (nazev, seznam_kouzel_id, uroven_kouzla, cena_magenergie, dosah, doba_seslani, doba_trvani, typ_unavy, popis)
SELECT v.nazev, s.id, v.uroven, v.mag, v.dos, v.sesl, v.trv, v.un, v.pop
FROM (
  SELECT 'Bludička' AS nazev, NULL AS uroven, '4 nebo 8 magů' AS mag, NULL AS dos, '1 kolo' AS sesl, NULL AS trv, 'vycerpavajici' AS un, 'Rozsah: hvozd. Четnost: 1× za noc. Bludička je bludné světélko, které tančí lesem a nedá se polapit. Druid ví, že bludička je malá lesní magická bytost, kterou je schopen přivolat a na čas podřídit své vůli. Bludička může bloudící postavy chránit nebo je naopak zavést do záhuby. Druid může toto kouzlo seslat na inteligentní bytost, kterou má v dohledu nebo jejíž přesnou polohu zjistí. Stačí pak, když bludičce ukáže jako terč tuto bytost a přesně vysvětlí, kde má bloudit. Zmámeným postavám se pak zjeví plamének tančící mezi stromy a zvoucí je k neznámé záhubě. Zmámené postavy plamínek chvíli sledují, protože jim to bude připadat důležité, a budou se domnívat, že na tom závisí jejich život. Nebudou však zmámeny natolik, aby bludičku sledovaly bez rozmýšlení — budou se snažit nalézt si nejschůdnější cestu, ovšem budou mít utkvělou představu, že k bludičce vždy nějaká cesta vede. Zmámené postavy, kterým se někdo bude snažit bránit v následování bludičky, se budou chovat podle své povahy, jako by jim bylo bráněno v plnění životně důležitého úkolu. Druid může přivolat bludičku i tak, aby byla viditelná jen pro jednu konkrétní inteligentní bytost, toto kouzlo je však dvakrát dražší. Druid může povolat bludičku toliko v noci, a to nesmí být příliš blízko úplňku, při úplňku či hned po úplňku. Bludička je v telepatickém spojení s druidem a řídí se všemi jeho pokyny. Ve hvozdu je schopna se pohybovat nad jakýmkoli terénem a může vyvinout velkou rychlost, nebojí se žádných lesních tvorů a nevadí jí ani silný vítr. Druid může během jedné noci povolat toliko jednu bludičku a o zmámení postavy nebo postav se může pokusit pouze jednou za noc. Bludičku samozřejmě nelze zmámit jinému druidovi.' AS pop
  UNION ALL SELECT 'Čarovná mlha' AS nazev, NULL AS uroven, '20 magů' AS mag, NULL AS dos, '1 kolo' AS sesl, NULL AS trv, 'vycerpavajici' AS un, 'Rozsah: okruh o poloměru 2 míle. Četnost: 7× mezi dvěma úplňky. Po vyvolání tohoto kouzla se kolem druida během tří kol začne šířit mlha a během dalších tří neprostupně zahalí celý okolní okruh v poloměru dvou mil od vrcholků stromů. Mlha je naprosto neprostupná zrakem, infravidění i ultrasluchem. Mlha ruší i pachy, takže zvířata nemohou po čichu sledovat stopy. Z mlhy se ozývají různé podivné zvuky — praskání dřeva, zbluňkání vody, hlasy zvířat či podivné temné mručení a hukot. Kouzlo je silnější obdobou stejnojmenného kouzla z Pravidel pro začátečníky.' AS pop
  UNION ALL SELECT 'Odstínění' AS nazev, NULL AS uroven, '20 magů' AS mag, '10 sáhů' AS dos, '1 směna' AS sesl, NULL AS trv, 'nevycerpavajici' AS un, 'Четnost: kdykoliv. Tímto kouzlem lze účinně ukrýt před nalezením druidskými kouzly najdi bytost a oko zření. Ukryto je vše v okruhu deseti sáhů kolem pohybujícího se druida. Kouzlo přestane působit ve chvíli, kdy druid začne meditovat. Základní šance, že kouzla najdi bytost nebo oko zření naopak najde druida, je 50 %. Tato šance se zvyšuje o 5 % za každou úroveň, o kterou je hledající druid výše nad odstíněným druidem. Totéž platí i obráceně.' AS pop
  UNION ALL SELECT 'Oko zření' AS nazev, NULL AS uroven, '20 magů' AS mag, 'okruh o poloměru 100 mil' AS dos, '1 směna' AS sesl, NULL AS trv, 'nevycerpavajici' AS un, 'Četnost: úspěšně 3× denně. Oko zření je podobné kouzlu najdi bytost z Pravidel pro pokročilé, jen jeho dosah je desetinásobně větší. Jinak se od něj nijak neliší.' AS pop
  UNION ALL SELECT 'Posílení kouzel' AS nazev, NULL AS uroven, '—' AS mag, '—' AS dos, '—' AS sesl, NULL AS trv, NULL AS un, 'Четnost: kdykoliv. Zde se nejedná ani tak o kouzlo jako spíše o zvláštní schopnost, kterou druidovi samovolně poskytuje prostředí hvozdu. Některá hraničářská kouzla seslaná druidem ve hvozdu mají silnější účinky než venku, přičemž si odčerpají nějakou probouzecí magenergii hvozdu, která ono zesílení kouzla vyvolá. Pokud ve hvozdu žádná probouzecí magenergie přítomna není, zesílení se nekoná. Uzdrav lehká zranění vyléčí za 5–10 životů a odčerpá 2 magy z probouzecí magenergie hvozdu. Uzdrav těžká zranění vyléčí za 8–18 životů a odčerpá 4 magy z probouzecí magenergie hvozdu. Ošetři zranění chladem vyléčí za 25–30 životů a odčerpá 5 magů z probouzecí magenergie hvozdu. Ošetři zranění kyselinou vyléčí za 18–23 životů a odčerpá 3 magy z probouzecí magenergie hvozdu. Ošetři zranění ohněm vyléčí za 28–33 životů a odčerpá 5 magů z probouzecí magenergie hvozdu. Odstranění únavy odstraní 1k10 bodů únavy bytosti a odčerpá 1 mag z probouzecí magenergie hvozdu. Na oživ mrtvého hvozd dodá 1/5 celkové magenergie, která se odčerpá z jeho probouzecí magenergie. Právě kvůli posílení kouzel druidové často chlácholením nevyčerpávají probouzecí magenergii hvozdu až do dna.' AS pop
  UNION ALL SELECT 'Půst' AS nazev, NULL AS uroven, '—' AS mag, 'jen druid' AS dos, '—' AS sesl, NULL AS trv, NULL AS un, 'Четnost: kdykoliv. Půstem, tedy nepřijímáním žádné potravy, si druid pročistí mozek, ale poněkud oslabí tělo. Pokud jeden celý den nejí, druhý den mu při meditaci přibude o 1 mag více než obvykle, ale také 1 bod únavy, který nepůjde zahnat odpočinkem ani kouzlem. Půstí-li druid déle, magy navíc a body únavy se budou kumulovat. Opustí-li během půstu les, magy navíc zůstanou, ale přijde o všechny nadbytečné magy a s každým dnem ztrácí 10 bodů únavy. Dlouhodobější půst se často používá pro uspávání hvozdu či jiný dlouho očekávaný obřad, který je navíc náročný na magenergii. Při půstu se na druida nevztahují klasická pravidla pro hladovění. PŘÍKLAD: PŘÍKLAD: Druid s inteligencí 11 má na 20. úrovni 100 magů. Jednoho dne se začne postit. Druhý den bude mít při meditaci 101 magů a 1 bod únavy, další den 102 magů a 2 body únavy. Tak to půjde, dokud zase nezačne jíst nebo jednoho dne náhle nezahyne vyčerpáním.' AS pop
  UNION ALL SELECT 'Svolej druidy' AS nazev, NULL AS uroven, '8 nebo 16 magů za směnu' AS mag, 'hvozd' AS dos, '1 kolo' AS sesl, '1 kolo' AS trv, 'vycerpavajici' AS un, 'Четnost: kdykoliv. Po seslání tohoto kouzla vznikne ve hvozdu všeobecné telepatické pole, na něž jsou napojeni všichni druidi od 16. úrovně výše. Dokud kouzlo trvá, mohou se spolu radit, překřikovat se a nadávat si. Kouzlo je možno na konci každé směny prodlužovat nebo seslat najednou na více směn. Pokud je kouzlo sesláno za 16, nikoli 8 magů, jsou do telepatického pole zapojeni všichni druidové již od 6. úrovně. Toto kouzlo není odposlechnutelné žádným jiným kouzlem, v hlubokém lese se ovšem někdy ozývá tlumená změť hlasů z jistých druhů stromů, což trochu plaší zvěř. Za 32 magů se může druid z telepatického pole odpojit a má zaručeno, že jej až do příští meditace nikdo nebude rušit, ledaže by telepatické kouzlo znovu sám seslal. Hovor probudí spící druidy, avšak nevyruší meditující, kteří ho zaregistrují až ve chvíli ukončení meditace.' AS pop
  UNION ALL SELECT 'Zaharaš' AS nazev, NULL AS uroven, '1 mag za keř nebo osobu' AS mag, NULL AS dos, '1 kolo' AS sesl, '1 kolo' AS trv, 'vycerpavajici' AS un, 'Четnost: kdykoliv. Tímto kouzlem je druid schopen zaharasit jedním keřem, jako by jím procházel, a tak např. odvrátit pozornost nepřátel nebo vyplašit dotěrné ptactvo. Druid je najednou schopen zaharasit tolika keři, kolik je jeho úroveň. Druid je také schopen harašit vousy lesních humanoidních tvorů. Může to využít jako vtip, zastrašení nebo snížení bojeschopnosti případného nepřítele. Za harašení vousu delšího než 1 sáh má humanoidní bytost postih -3 v boji, za délky od půl sáhu do sáhu -2 a za délky do deseti coulů -1. Kratší vousy ani knír nelze harašit. Postižený se zachová podle své povahy a úvahy PJ, většinou se naštve a začne provádět pohyby, které by od něj majitel nečekal, nemá však tendenci mu nijak ublížit, jen tak haraší. V jednom kole nelze harašit zároveň keři i vousy. Vlasy harašit nelze. Druidi si mohou harašit vousy navzájem.' AS pop
) v
JOIN seznamy_kouzel s ON s.nazev = 'Malá lesní kouzla'
JOIN povolani p ON p.id = s.povolani_id AND p.nazev = 'Druid';

-- Velká lesní kouzla / Druid (14 kouzel)
INSERT INTO kouzla (nazev, seznam_kouzel_id, uroven_kouzla, cena_magenergie, dosah, doba_seslani, doba_trvani, typ_unavy, popis)
SELECT v.nazev, s.id, v.uroven, v.mag, v.dos, v.sesl, v.trv, v.un, v.pop
FROM (
  SELECT 'Drakomluva' AS nazev, NULL AS uroven, '1 mag za směnu' AS mag, 'hvozd' AS dos, '—' AS sesl, NULL AS trv, NULL AS un, 'Четnost: —. Druh: osobní. Drakomluva v podstatě vůbec není kouzlo (jak je asi jasné z výše uvedených parametrů), nýbrž učená schopnost rozumět prastarému dračímu jazyku. Naučit se jej ze starých knih však vyžaduje nemenší vůli a soustředění než zvládnutí kteréhokoli velkého lesního kouzla. Drakomluvu je možno používat i mimo hvozd, ovšem s menší úspěšností než ve hvozdu. Dračí řeč je prastará a její zvládnutí patří k pýše mudrců — vždyť už ji neovládají ani všichni draci! Těm drakům, kteří ji umějí používat a dokáží v ní sesílat různá dračí kouzla, se říká moudří draci, zatímco jejich zdivočelí kolegové, kteří již neumějí dračí řeč mluvit, se nazývají divocí draci. Každý drak, ať už moudrý či divoký, však dračí řeči rozumí, ať k němu promlouvá jakkoli nepatrný človíček. Mluvit na draka drakomluvou má několik výhod. Jednak dotyčný drakomluvci není schopen vždy říkat pravdu (pokud se ovšem přímo nebo nepřímo nevyhne odpovědi). Kromě toho ho nemůže dotyčný pokusit změnit hlasem ani pohledem, naopak, ten se může pokusit změnit draka (ovšem jen divokého, moudří draci jsou na to příliš moudří). Navíc se může drakomluvec pokusit drakovi rozkázat nebo ho požádat o nějakou věc. Úspěšnost všech těchto akcí závisí mimo jiné na tom, zda dračí řečí hovořící druid je ve hvozdu, nebo mimo něj. Žádost: Drak si hodí proti pasti Int ~ 5 (9) + Int druida ~ nic/splnění. Drak splní druidovo přání, pokud pro něj nebude nebezpečné nebo nepříjemné. Druid se může pokusit draka o něco požádat jednou za čtyři hodiny. Rozkaz: Drak si hodí proti pasti Int ~ 3 (7) + Int druida ~ nic/vyplnění. Drak vyplní druidův rozkaz, pokud pro něj nebude mít zjevné sebevražedné následky. Druid se může pokusit drakovi něco rozkázat jednou za čtyři hodiny. Zmámení: Drak si hodí proti pasti Int ~ 1 (5) + Int druida ~ nic/zmámení. Zmámený drak bude s druidem jednat, jako by to byl jeho nejlepší přítel, ovšem zjevně sebevražedný příkaz nesplní. Zmámení pomine tři směny poté, co se drak ocitne mimo dosah druidova hlasu, ale drak si toho nebude vědom a bude mít i nadále pocit, že se setkal s člověkem, který mu byl velmi sympatický. Druid se může jednoho konkrétního draka pokusit zmámit jen jednou za dvacet čtyři hodiny. Čísla uvedená v závorkách platí pro hvozd, čísla před závorkami mimo něj. V případě úspěchu příslušné akce účinkuje nejvýše 4 hodiny, zmámení 1 den. Toto kouzlo je jedno z mála použitelných i mimo hvozd.' AS pop
  UNION ALL SELECT 'Nenávist lesa' AS nazev, NULL AS uroven, 'veškerá současná' AS mag, NULL AS dos, '1 kolo' AS sesl, NULL AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 osoba. Четnost: 4× mezi dvěma úplňky. Druh: osobní. Toto kouzlo je velmi podobné lásce lesa. Druid je může seslat na osobu, jejíž přítomnost v lese či sama existence je pro les krajně nežádoucí. Pokud má les (PJ) jiný dojem, kouzlo neúčinkuje a magenergie je vyplýtvána zbytečně. Musíme však podotknout, že s nenávistí lesa hvozd nedělá zdaleka takové ciráty jako s láskou. Druid si sice těžko může seslat na kolegu druida nebo nějakého lesního elfa, ale jinak se mu úspěšně povede na každého, kdo lesu nějak škodí či v něm nějak obtěžuje. V případě seslání tohoto kouzla se neupraví vztah osoby k hvozdu, nýbrž vztah hvozdu k osobě, a to zásadním způsobem. Les se od chvíle seslání kouzla bude snažit danou osobu zlikvidovat či alespoň vypudit ze svého dosahu. Náhle odpadající větve, zdivočelá zvířata a zrádné jámy zakryté napadaným listím způsobí postavě každých šest směn zranění za 1–6 životů, násobeno stupněm probuzenosti hvozdu. Pokud nešťastníka z lesa vyprovodí druid a chrání ho, počet ztracených životů se dělí dvěma, pokud dva druidi, dělí se třemi atd., vždy však zaokrouhlujeme nahoru. Toto je obzvlášť znamenité, pokud se při uspání lesa náhle na nějakého kolegu druida snese nenávist lesa. V případě, že nějaká osoba les opravdu významně popudí, les na ni skrze přesnou polohu, kterou druid zná, může sám seslat toto kouzlo, a to i tehdy, jestliže druid toto kouzlo tento měsíc už seslal, a třeba ani nemá potřebný jeden mag.' AS pop
  UNION ALL SELECT 'Odčaruj nemrtvé' AS nazev, NULL AS uroven, '1× životaschopnost magů' AS mag, NULL AS dos, '1 kolo' AS sesl, NULL AS trv, 'vycerpavajici' AS un, 'Четnost: kdykoliv. Druh: osobní, hromadné. Tímto kouzlem lze obrátit v prach každého nemrtvého, který se ocitne v okruhu hvozdu a druid o něm ví. Nemrtvého může druid buď spatřit osobně, nebo se o něm dozvědět pomocí kouzla oko zření, případně najdi bytost. V prvním případě se rozpadnou v prach všichni nemrtví, které druid vidí. Druid nemůže z působení kouzla žádného nemrtvého vyjmout. Pokud chce druid zničit nemrtvé na dálku, musí znát jejich přesnou polohu. Nejlépe by tedy bylo, kdyby kouzlo odčaruj nemrtvé seslal hned po kouzlu oko zření, kterým zjistí přítomnost nemrtvých. Jinak, pokud je skupina nemrtvých od sebe místně rozdělena, nebude možné kouzlo seslat. Tímto kouzlem není schopen ničit „neaktivované" nemrtvé, tj. takové, kteří upadli do katalepsie po smrti svého sesilatele. Na místě rozpadu nemrtvého bude velmi úrodná půda, vhodná pro založení zahrádky magických bylin. PŘÍKLAD: PŘÍKLAD: Do hvozdu vtrhne pod velením zlého mága armáda padesáti kostlivců (životaschopnost 1). Druid si pomocí oka zření zjistí přesnou polohu, za 50 magů je všechny zničí, pak pošle na mága velký zlý strom a několik medvědů, zatímco na zbytek čtyři elfí a šest trpasličích lučištníků.' AS pop
  UNION ALL SELECT 'Odraz mentální souboj' AS nazev, NULL AS uroven, '10 magů' AS mag, NULL AS dos, '1 kolo' AS sesl, NULL AS trv, 'vycerpavajici' AS un, 'Rozsah: jen druid. Четnost: kdykoli. Druh: osobní. Mentální útok se projevuje trochu podobně, jako když něco špatného sníte. Začnou vám ubývat životy, případně magy a rozbolí vás hlava. Druid má celkem dvě možnosti, jak se s tímto útokem vypořádat. První je zrcadlení, druhá převedení. Při zrcadlení druid „zmizí" coby mágův terč a mág bude náhle útočit sám na sebe. Podrobné instrukce pro zrcadlení mentálního souboje má opět PJ. Převést lze jedním kouzlem pouze jeden mentální útok (lépe řečeno souboj), kouzlo nevytváří žádnou stálou ochranu. Při převedení druid mágův útok převede na pomocníka, který stojí při něm, totiž na sebe či hvozd. V takovém případě mág zanechá soupeře s pocitem, že se hodně popálil. Podrobnější instrukce má opět PJ. (Pozn.: pořadí odstavců zrcadlení/převedení v OCR skenu poněkud zmatené — ponecháno v pořadí, v jakém se objevuje ve skenu, bez svévolné úpravy smyslu.)' AS pop
  UNION ALL SELECT 'Odvrať posla živlů' AS nazev, NULL AS uroven, 'viz níže' AS mag, NULL AS dos, 'kdykoli, viz níže' AS sesl, NULL AS trv, NULL AS un, 'Rozsah: viz níže. Druh: osobní, hromadné. Poslové živlů se dělí do dvou základních kategorií. Jedni jsou podobni konkrétním bytostem vyvolaným z daného živlu, nazývají se elementálové a mohou útočit pouze jednotlivě. Druzí mají podobu samotného živlu — obrovské vlny, vichřice, zemětřesení nebo hejno blesků, a nazývají se bhuti. Na tyto dva druhy druid sesílá kouzlo podle podobných, avšak trochu odlišných pravidel. Elementálové — bytosti mohou být čtyř druhů: gnóm — elementál země, vyhlížející jako chodící socha, undina — elementál vody, vyhlížející jako vodní vír, sylfa — elementál vzduchu, vyhlížející jako vzdušný vír, a konečně salamandr — elementál ohně (v druidice ze všech nejneoblíbenější), připomínající dlouhou sálající ještěrku. Pravidla pro likvidaci elementálů se trochu podobají pravidlům pro odčarování nemrtvých. Druid musí elementála buď vidět, nebo znát jeho přesnou polohu ve hvozdu. Pak sešle kouzlo. Za každý vydaný mag magenergie ubude elementálovi jeden život. Druid může do kouzla vložit nějaké předem dané množství magů, nebo říci, že chce seslat kouzlo tak, aby elementála zcela zničil. Pokud má v dané chvíli elementál více životů než druid magů, druid přijde o všechny magy a elementálovi ubyde příslušný počet životů. Druid může tímto kouzlem na jednoho elementála zaútočit libovolněkrát (pokud na to má magy). Na likvidaci bhutů se většinou musí spojit celý kruh druidů — boj s nimi je podstatně náročnější na magenergii. Vyvolání kouzla také netrvá jedno kolo, nýbrž jednu směnu. I oni mají životaschopnost, k níž se váže určitý počet životů, a druidi jim musejí kouzlem odebrat veškeré tyto životy (1 vynaložený mag = 1 ztracený život bhuty), aby jejich životaschopnost o 1 klesla (čímž ovšem výrazně stoupne jejich odolnost). Pokud druidi nevynaloží nebo nemohou vynaložit dostatečný počet magů, bhutovi vůbec neuškodí. Proti oslabenému bhutu mohou druidi další směnu seslat kouzlo znovu. Po vyvolání kouzla uplynou tři směny, než bhuta začne působit. Jeho ničivé působení pak trvá další směnu. Pokud se epicentrem bhuty stane hvozd či jeho blízké okolí (2 míle), všichni druidové v daném hvozdu ovládající kouzlo odvrať posla živlů to ihned vycítí. Následně se mohou spojit pomocí malého lesního kouzla svolej druidy a dohodnout podmínky seslání hromadného kouzla. Za kruh druidů se v tomto případě považuje celý hvozd a všichni druidi, znající dané kouzlo, v něm přítomní. Tímto kouzlem lze bhutu oslabit nebo zničit během tří směn, kdy se vyvolává, ale již nikoli v následující směně, kdy se projevuje.' AS pop
  UNION ALL SELECT 'Probuzení lesa' AS nazev, NULL AS uroven, 'viz níže' AS mag, NULL AS dos, 'noc' AS sesl, NULL AS trv, NULL AS un, 'Четnost: kdykoliv. Druh: hromadné. Probuzení lesa spolu s uspáním lesa druid naučí během jednoho přestupu, jelikož se v podstatě jedná o dvě varianty téhož kouzla. Velikost magenergie, kterou je třeba vynaložit k probuzení hvozdu o jeden stupeň, závisí na aktuálním stupni probuzenosti hvozdu. Z prvního stupně na druhý je to 1 000 magů, z druhého na třetí 2 000 magů, ze třetího na čtvrtý 4 000 magů a z čtvrtého na pátý 8 000 magů. Kouzlo musí být sesláno s touto magenergií a nijak nezohledňuje probouzecí magenergii, kterou hvozd v sobě již samovolně nakumuloval. Pokud se kouzlo z nějakého důvodu seslat nepodaří, vynaložená magenergie zmizí a nepřičte se k probouzecí magenergii. Kouzlo začne působit se svítáním. Les kolem vyvolávajících se rozšumí podobným lidskému šepotem a větve stromů jakoby na poděkování začnou natahovat se k mýtině, na níž druidi kouzlo vyvolali.' AS pop
  UNION ALL SELECT 'Proměna ve zvíře' AS nazev, NULL AS uroven, '3 magy za směnu' AS mag, NULL AS dos, '1 kolo' AS sesl, NULL AS trv, 'vycerpavajici' AS un, 'Rozsah: jen druid. Четnost: 4× denně. Druh: osobní. Pomocí tohoto kouzla je druid schopen proměnit se ve zvíře s inteligencí 1, které zná. Musí jít o běžné, nefantastické a nemagické zvíře (například zajíc, medvěd, orel). Toto zvíře musí být přibližně stejné velikosti jako druid ve své původní podobě, tj. nesmí se lišit o víc než jednu třídu velikosti (ale ani druid velikosti A se nemůže proměnit ve zvíře velikosti A0). Druid získá vlastnosti zvířete (sílu, obratnost, odolnost, rychlost), ale zachovává si svoji inteligenci, počet životů a dosaženou úroveň. Získá anatomické a fyziologické vlastnosti zvířete (dovede létat, vidí dobře za šera). Zachovává si svoje zvláštní schopnosti (například telepatii), nemůže mluvit lidským hlasem, jen řečí daného zvířete. Druid se promění ve zvíře se všemi věcmi, které má při sobě, pokud však je mezi nimi něco železného, proměna ve zvíře se nezdaří. Maximální délku trvání kouzla určí druid při jeho seslání podle množství dodané magenergie.' AS pop
  UNION ALL SELECT 'Rozšiř hvozd' AS nazev, NULL AS uroven, '20 magů za každou načatou…' AS mag, NULL AS dos, 'noc' AS sesl, NULL AS trv, NULL AS un, 'Magenergie (přesně): 20 magů za každou načatou čtvereční míli. Rozsah: dle dodané magenergie. Četnost: kdykoli. Druh: osobní, hromadné, postupné. „Hvozd svými prsty dosáhne daleko." Toto přísloví se vztahuje právě k umění druidů rozšiřovat hvozd. Umožňuje jim spojit spící vědomí hvozdu se skupinami stromů, které přímo do hvozdu nenáleží, ale sousedí s ním, a dosáhnout tak toho, že i v nich mohou sesílat lesní kouzla a požívat všech výhod, jako by byli v hvozdu. Skupinou míníme kruh stromů o poloměru nejméně padesáti sáhů (nebo jiný útvar s odpovídající plochou). Úspěšné seslání kouzla má následující podmínky: Druidi vždy musejí připojovat ke hvozdu uzavřený celek stromů, nikoli pouze jeho část. Kouzlo musí být sesláno s dostatkem magenergie, jinak se nezadaří. Mezi zmíněnou lesní lokalitou a hvozdem nesmí být žádná frekventovaná cesta ani pole. Pokud je zmíněná lesní lokalita od hvozdu vzdálena více než sto sáhů, musí mezi ní a hvozdem každých sto sáhů růst nejméně jeden strom vyšší než dva sáhy. Pokud se toto spojení s hvozdem přeruší, ztrácí tato část vlastnosti hvozdu, dokud není spojení opět obnoveno. Pokud není obnoveno do nejbližšího úplňku, mizí docela a kouzlo je třeba opakovat. Samo kouzlo rozšíření hvozdu je poměrně malebný obřad, který začíná po západu slunce a končí s jeho východem, přičemž zvyklosti s ním spojené jsou v různých částech světa různé (rozhodně však nijak nesouvisejí s nemírným požíváním rozličných opojných nápojů).' AS pop
  UNION ALL SELECT 'Rychlý růst' AS nazev, NULL AS uroven, '1 mag/sáh²' AS mag, NULL AS dos, '1 směna' AS sesl, NULL AS trv, 'nevycerpavajici' AS un, 'Rozsah: dle dodané magenergie. Четnost: kdykoli. Druh: osobní, hromadné. Rychlý růst se spolu s rychlým vadnutím druid naučí během jednoho přestupu, jelikož se v podstatě jedná o dvě varianty téhož kouzla. Druid se nejprve musí jednu směnu soustředit. Pak sešle kouzlo na libovolné prostranství ve hvozdu nebo mimo hvozd, které mu bezprostředně přiléhá. Rozsah a tvar území zasaženého kouzlem záleží výlučně na druidově vůli a dodané magenergii. Za každý mag vyroste právě jeden čtvereční sáh porostu. Kouzlo je na pohled velmi působivé — vše roste a bují šílenou rychlostí. Druid se při sesílání tohoto kouzla vystavuje nebezpečí, že mu na oplátku les sešle nenávist lesa. Podrobná pravidla pro tento případ zná Pán jeskyně.' AS pop
  UNION ALL SELECT 'Rychlé vadnutí' AS nazev, NULL AS uroven, '1 mag/sáh²' AS mag, NULL AS dos, '1 směna' AS sesl, NULL AS trv, 'nevycerpavajici' AS un, 'Rozsah: dle dodané magenergie. Четnost: kdykoliv. Druh: osobní, hromadné. Rychlé vadnutí se spolu s rychlým růstem druid naučí během jednoho přestupu, protože se v podstatě jedná o dvě varianty téhož kouzla. Druid se nejprve musí jednu směnu soustředit. Pak sešle kouzlo na libovolné prostranství ve hvozdu nebo mimo hvozd, ale těsně přiléhající. Rozsah a tvar území zasaženého kouzlem záleží výlučně na druidově vůli a dodané magenergii. Za každý mag zvadne právě jeden čtvereční sáh porostu. Kouzlo je na pohled velmi působivé a značně děsivé — vše vadne, uschne a usychá šílenou rychlostí. Nakonec, po jedné směně, zbude jen holá, zcela sterilní zem, kterou je třeba osít, aby na ní opět něco vyrostlo (časem se o to samozřejmě postará vítr, ptáci a medvědi). Druid se při sesílání tohoto kouzla vystavuje nebezpečí, že mu na oplátku les sešle nenávist lesa. Podrobná pravidla pro tento případ zná Pán jeskyně.' AS pop
  UNION ALL SELECT 'Síla lesa' AS nazev, NULL AS uroven, 'viz níže' AS mag, NULL AS dos, 'v noci, viz níže' AS sesl, NULL AS trv, NULL AS un, 'Rozsah: jeden objekt, viz níže. Четnost: 4× mezi úplňky. Druh: osobní, hromadné. Toto kouzlo umožní vyvolávat následující lesní kouzla i mimo hvozd: Cit dřeva, Cit kamene, Cit vody, Cit země, Najdi bytost, Orientace, Temnota, Čarovná mlha, Mluv se zvířaty, Odstínění, Oko zření, Posílení kouzel, Zaharaš. Musí se však jednat o sesílání v přírodním prostředí, výše uvedená kouzla nelze sesílat ve městě, na návsi, v budovách ani v uměle vytvořených nebo k obývání upravených podzemních prostorách (doly, podzemní sídla). Samotné kouzlo síla lesa je rituál, při němž druid (druidi) přenese část síly hvozdu do nějakého přenosného objektu, který ve hvozdu vznikne a je jeho součástí. Tento objekt pak druid může vynést mimo hvozd a čerpat z něj při sesílání výše zmíněných méně náročných lesních kouzel, která přímo nevyžadují přítomnost hvozdu (nebo jen zcela zanedbatelně) a čerpají z přítomné probouzecí magenergie. Předpokladem samozřejmě je, že druidův kontakt s hvozdem není nijak narušen. Objektem, do něhož lze přenést sílu hvozdu, může být jen něco živého nebo něco, v čem život může vzniknout. Může to být například nějaké lesní zvíře (s inteligencí 0 nebo 1), pták, netopýr nebo hadí vejce, malý semeníček, v největší oblibě však druidi mají různá semena a plody lesních stromů. Je třeba mít na paměti, že nositelem síly hvozdu může být jen zdravý živý tvor nebo životaschopný zárodek. Na jeden objekt lze seslat sílu lesa pouze jednou. Pokusí-li se o to někdo znovu, je takový pokus automaticky neúspěšný a vložená magenergie přijde nazmar. Druidská tradice praví, že objekt, do něhož byla síla hvozdu přenesena, z hvozdu vzešel a do hvozdu by se měl, poté co splní svoji funkci, opět vrátit, a to pokud možno živý. Rituál sesílání kouzla probíhá v noci, alespoň hodinu kolem půlnoci — sesílá-li kouzlo jeden druid. Účastní-li se rituálu celý kruh druidů, trvá zpravidla od slunce západu do slunce východu. Magenergie do kouzla (objektu) vložená závisí na rozhodnutí druidů, nemůže však převýšit 1 000 magů. Objekt sám o sobě jako magický příliš nejeví, ale druid dokáže odhadnout jeho sílu s přesností cca 10 %, a i hraničář, který není druidem, pocítí jeho neobyčejnost a přírodní sílu. Objekt neslouží jako zásobník magenergie, odkud by druid čerpal magy, ale pouze nahrazuje hvozd, skrze nějž druid může lesní kouzla sesílat. Z hlediska herních mechanismů se to projeví tak, že druid sešle lesní kouzlo obvyklým způsobem a vynakládá na to vlastní magenergii — a stejný počet magů ubývá i „hvozdu" z objektu. Navíc objektu ubývá 1 mag za každý (i započatý) den. (Pozn.: sken PPE str. 30 obsahuje zjevnou duplikaci odstavce o magenergii vložené do objektu — sazba odstavec dvakrát téměř doslovně opakuje. V tomto přepisu ponechána jen jedna verze, bez ztráty informace, jelikož jde o doslovné opakování stejné věty.)' AS pop
  UNION ALL SELECT 'Uspání lesa' AS nazev, NULL AS uroven, 'viz níže' AS mag, NULL AS dos, 'noc' AS sesl, NULL AS trv, NULL AS un, 'Четnost: kdykoliv. Druh: postupné, hromadné. Uspání lesa spolu s probuzením lesa druid naučí během jednoho přestupu, jelikož se v podstatě jedná o dvě varianty téhož kouzla. Kouzlo uspání lesa prý kdysi vymyslel druid Bukovec, když strom, o který se opíral, poodešel, a Bukovec se převalil na záda. Hvozd na něj na oplátku seslal nenávist lesa a Bukovec si pak v hlavním městě otevřel krámek se smrtnostmi a vyřezávanými ozdobami. Tolik poučení pro mladé druidské adepty. Pravdou je, že kouzlo uspání lesa je esenciální druidská schopnost. Bez něj by si sousedé žijící na dohled hvozdu jistě netěšili takové vážnosti. Pověst praví, že kdysi se lidem podařilo pomocí vysoké magie uspat všeobjímající listnatý oceán, který tehdy obepínal celý svět a příliš toho inteligentním bytostem nedovoloval. Pak byli ustanoveni lesní kněží a strážci spánku hvozdu — druidové. Ti měli dohlížet na to, aby se les již nikdy neprobudil. Mnozí si však les příliš zamilovali, a když viděli, jak nemilosrdně je kácen a plundrován, stali se ze žalářníků jeho spojenci a naučili se, jak jej probudit. Postavili se na jeho stranu. Po strašlivých válkách bylo dohodnuto příměří a z druidů se stali ochránci hvozdu před lidmi a ochránci lidí před hvozdem — udržovatelé rovnováhy, kteří se starají, aby se říše hvozdu a říše inteligentních bytostí střetávaly co nejméně. Magenergie vynaložená na uspání lesa závisí na stupni jeho probuzenosti. Z pátého na čtvrtý stupeň je to 16 000 magů, z čtvrtého na třetí 8 000 magů, ze třetího na druhý 4 000 magů a z druhého na první 2 000 magů. Hvozd má ovšem tendenci uspání lesa bránit a je schopen pohltit část magenergie kouzla, které je na něj postupně sesíláno. Denně pohltí na druhém stupni 1/100 současných magů seslaného kouzla, na třetím stupni 1/50 magů, na čtvrtém stupni 1/20 magů a na pátém stupni 1/10 magů. Jak jeho probuzenost roste, je tedy nejen dražší, ale i těžší ho odčarovat zpět. Probuzený les je navíc schopen samovolně sesílat lesní kouzla — v tomto případě se pokusí seslat kouzlo nenávist lesa na všechny, kteří se jej pokoušejí uspat. (Podrobná pravidla pro tento případ má ve svém příručce Pán jeskyně.) Uspání lesa je velmi malebný obřad, který začíná po západu slunce a končí se svítáním. Odehrává se na nějakém magickém místě v hloubi hvozdu, kde se často nacházejí prastaré monolitické stavby, a účastní se ho celý lesní kruh druidů. Většina starších druidů se účastní obřadu, někteří jsou přítomni jako náhradníci, mladší stojí na pokraji mýtiny s pochodněmi a novicové hlídkují v okolních lesích, aby nikdo záměrně ani náhodou nevyrušil důležitý obřad. Většinou bývá jasná úplňková noc. Pravdou však zůstává, že v případě krajní nutnosti je možné seslat kouzlo uspání lesa i bez většiny těchto doprovodných efektů, jsou-li sami druidové ochotni porušit tradici (a druidové, jak je všeobecně známo, na tradicích velmi lpějí).' AS pop
  UNION ALL SELECT 'Vymítání ďáblů' AS nazev, NULL AS uroven, 'viz níže' AS mag, NULL AS dos, '1 kolo' AS sesl, NULL AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 osoba. Четnost: kdykoliv. Druh: osobní. Existence ďáblů je známa již od pradávných časů. Vyskytují se kdesi v Pekle, místě zcela bez souvislosti s hmotným světem, a z hmotného světa se snaží kořistit Duše, zasévajíce do ní neřest, aby ji inteligentní bytosti nedokázaly napáchat dost samy mezi sebou. Ďáblové mohou po světě chodit za vlastním posláním či v dané chvíli posluhovat někomu, jehož Duši si časem s sebou odnesou. Aby mohli působit v našem světě, musejí na sebe ďáblové vzít hmotnou podobu. Hvozd nemá pekelnou konkurenci na svém území rád a druid ji může vymítat — tedy zbavit ďábly tělesné podoby a poslat je zase tam, odkud přišli. Celé kouzlo probíhá podobně jako kouzla na zapuzení nemrtvých a poslů živlů. Druid, který se toto kouzlo naučil, automaticky pozná, že před ním stojí převtělený ďábel. Také se v každém okamžiku může pokusit nějakého ďábla vyhledat ve hvozdu okem zření. Pokud druid ďábla vidí, kouzlo stojí 1 mag za každou úroveň ďábla. Pokud druid nemá dostatek magů, kouzlo se nezdaří. Pokud je má, ďábel se rozplyne — nic po něm nezůstane, jeho hmotné tělo je jen velmi přesvědčivá iluze. Pokud se ďábel, který byl z hloubky hvozdu vymeten, zjeví v jeho dosahu znovu, hvozd si ho už pamatuje a automaticky naň sešle nenávist lesa. Kouzlo má ještě jeden vedlejší efekt. Druid po jeho naučení pozná od pohledu nejen ďábla, ale i osoby, které s ním záměrně nebo nedobrovolně vyvolávaly jeho služby. Na tyto osoby může druid seslat nenávist lesa za stejnou magenergii jako při vymítání ďáblů. Toto kouzlo lze seslat i na jiného druida, který záměrně paktoval s ďáblem!' AS pop
  UNION ALL SELECT 'Vyvolej velký zlý strom' AS nazev, NULL AS uroven, '40 magů' AS mag, NULL AS dos, '1 kolo' AS sesl, NULL AS trv, 'vycerpavajici' AS un, 'Четnost: 2× denně. Druh: osobní. Při sesílání tohoto kouzla druid rozpřáhne ruce, ukáže hlavou na blízký strom — musí to být pořádný chlapák (strom, ne druid). Strom náhle začne měnit tvar, jakoby se svíjet do sebe, přičemž se to vše odehrává neuvěřitelnou rychlostí. Na konci dalšího kola vytrhne ze země kořeny a dá se do pohybu. Ze všeho nejvíc teď vypadá jako postava ze zlých snů. Kmen má na výšku asi šest sáhů a na šířku méně než dva, s neobyčejně zvrásněnou kůrou připomínající kůži nosorožce. Asi sáh a půl nad zemí má strom obrovskou tlamu, plnou ostrých dřevěných kůlů a kolíků, která kdysi sevře, už nepustí. Větve stromu se promění ve dvě obrovské paže visící po bocích, korunu tvoří divoký a hustý spletenec větví. Kmen má dva hluboké otvory připomínající oči — podíváte-li se do nich pořádně, uvidíte v jejich hlubinách červený přísvit (ale asi se vám nebude chtít). Strom je zcela poslušen druidovy vůle. Ten s ním může komunikovat na dálku telepaticky, a to i v okruhu celého hvozdu. Strom je mu vždy schopen jednoduchými větami sdělit, co vidí, alespoň v hrubých obrysech (ano, opravdu umí a může nahlas mluvit — hlas má velmi hrdelní, praskavý a není příliš dobře rozumět). Sdělí například druidovi, že před sebou vidí pět dvounohých bytostí, ale jestli jsou to skřeti nebo vesničané, už neřekne — druid to musí uhodnout podle chytře položených doplňkových otázek (například: „Utíkají?"). Strom vyplní každý druidův rozkaz, nebo se o to alespoň pokusí. Od hvozdu se je schopen vzdálit jen sto sáhů (a nerad), nikoli však přes noc nebo přes frekventovanou cestu, pak zakoření a promění se zpátky ve strom, z něhož byl stvořen. Druid může najednou vyvolat jen jeden velký zlý strom a být s ním v telepatickém kontaktu. Sám mu může kdykoli rozkázat, čímž se strom zakoření a promění zpátky v původní strom. Je-li velký zlý strom ponechán sám sobě, obvykle se snaží lovit zvířata. Pokud mu druid přikáže, aby klidně stál, každou hodinou stoupá o 10 % pravděpodobnost, že strom druidův příkaz zapomene a začne se chovat spontánně. Druid by neměl zapomínat, že každá kořist stromu zvyšuje probuzenost lesa. Strom je však poměrně pomalý a není příliš dobrým lovcem. Druid je se stromem v telepatickém kontaktu. Ten je přerušen pouze v případě, že se pro to druid sám rozhodne (viz kouzlo bludička), nebo se strom ocitne mimo zorné pole a spojení tak zanikne. Druid ho může obnovit pouze v případě, že se strom ocitne v jeho zorném poli a pro tento den ještě nevyčerpal možnosti vyvolání stromu — ta jsou za den možná pouze dvě. Druid takto nemůže ovládnout strom, který je právě v telepatickém spojení s jiným druidem. Velký zlý strom nikdy nenapadne žádného druida. Podrobné údaje pro velký zlý strom má PJ v Bestiáři.' AS pop
) v
JOIN seznamy_kouzel s ON s.nazev = 'Velká lesní kouzla'
JOIN povolani p ON p.id = s.povolani_id AND p.nazev = 'Druid';
-- TODO ověřit proti skenu (neúplný/nejasný zápis v předloze u): Odraz mentální souboj; Síla lesa

-- Kouzla pocestných / Chodec (30 kouzel)
INSERT INTO kouzla (nazev, seznam_kouzel_id, uroven_kouzla, cena_magenergie, dosah, doba_seslani, doba_trvani, typ_unavy, popis)
SELECT v.nazev, s.id, v.uroven, v.mag, v.dos, v.sesl, v.trv, v.un, v.pop
FROM (
  SELECT 'Ochrana před bouří' AS nazev, 6 AS uroven, '10 magů' AS mag, NULL AS dos, '1 kolo' AS sesl, NULL AS trv, 'vycerpavajici' AS un, 'Pomůcky: svíce a pouštní písek. Může se stát, že vichr a liják dosáhnou rozměrů, na které již kouzlo ochrana před deštěm (viz níže) nestačí — propukne bouře. Tu může chodec usednout na zem a seslat toto kouzlo. Kolem něj se vytvoří asi 2 sáhy vysoká a obdobně široká kopule ztuhlého vzduchu, která jej ochrání před větrem a deštěm. Na ochranu každé další osoby je třeba o 1 mag méně než na osobu před ní. PŘÍKLAD: PŘÍKLAD: Na ochranu tří osob uvnitř kopule se tedy spotřebuje 27 magů (10+9+8), na ochranu deseti osob 55 magů (kouzlo ochrání nejvýše deset osob; taková kopule má výšku i průměr asi 6 sáhů). Po bouři kouzlo samo pomine. Jednotlivé osoby mohou z kopule odcházet a opět se do ní vracet, nesmí tak však učinit chodec, který ji vyvolal. Ke kouzlu je potřeba svíce z pravého včelího vosku (nikoli náhražky), jíž chodec při sesílání kouzla rozsvítí, a hrstička pouštního písku, kterou poté vyhodí do vzduchu. Svíci je možné koupit.' AS pop
  UNION ALL SELECT 'Ochrana před deštěm' AS nazev, 6 AS uroven, '2 magy za 1×1 sáh ochrany' AS mag, NULL AS dos, '1 kolo' AS sesl, NULL AS trv, 'vycerpavajici' AS un, 'Pomůcky: pouštní písek. Chodec vyhodí do vzduchu špetku pouštního písku, sešle kouzlo a ve vzduchu se nad ním vytvoří průhledný, deštivzdorný plát ztuhlého vzduchu velikosti 1×1 sáh. Dva takové pláty ochrání 1 osobu před poměrně silným lijavcem (jeden chrání tak zpola). Plátů je možno vyvolat libovolné množství (do vyčerpání magenergie). Na ochranu každých dalších dvou osob kromě vyvolávajícího chodce jsou potřeba již pouze 3 pláty. Kouzlo se nedá využít k žádné jiné manipulaci s vodou (například zastavení vody vytékající z díry nebo zastavení řeky). Kouzlo pomine, jakmile postavy vejdou do skrýše či přístřešku nebo když přestane pršet. Během působení kouzla se chodec či jeho skupina může pohybovat pouze chůzí, nikoli během, a rovněž nemůže používat svou schopnost rychlý pochod. Pouštní písek potřebný k seslání kouzla si chodec samozřejmě musí opatřit sám v nějaké poušti nebo ho dostat darem.' AS pop
  UNION ALL SELECT 'Ochrana před vlky' AS nazev, 6 AS uroven, '1 mag za osobu' AS mag, NULL AS dos, '1 kolo' AS sesl, '1 den + viz níže' AS trv, 'vycerpavajici' AS un, 'Pomůcky: medvědí srst. Smečky hladových vlků bývají hlavně zjara postrachem poutníků. Toto kouzlo způsobí, že za sebou bude postava zanechávat stopu s pachem rozzuřené medvědice, a tu si vlci rozmyslí následovat. Kouzlo nepůsobí žádnou vizuální ochranu — tj. pokud se takto chráněný člověk dostane vlkům na dohled, bude jimi stejně napaden. Kouzlo zmate i lovecké psy. Přestane působit, když poutníci vejdou na dlážděnou frekventovanou cestu či do města. Ke kouzlu je potřeba alespoň trocha srsti z medvěda, kterého chodec sám ulovil nebo ho nějak přemluvil, aby mu chomáč chlupů poskytl. Při zaklínání s ní potře postavám podrážky či chodidla. Během působení kouzla se chodec a jeho skupina může pohybovat pouze chůzí, nikoli během, a rovněž nemůže používat svou schopnost rychlý pochod. Pokud tvůj chodec pochází z oblasti, kde vlci nežijí, můžeš se se svým Pánem jeskyně domluvit na ochraně před jiným zvířetem.' AS pop
  UNION ALL SELECT 'Ochrana před zimou' AS nazev, 6 AS uroven, '5 magů' AS mag, NULL AS dos, '1 kolo' AS sesl, '1 den' AS trv, 'vycerpavajici' AS un, 'Pomůcky: oblázek. Toto kouzlo umožní postavě nevnímat ani velmi silný mráz (způsobený počasím či podnebím, nikoli součást nějakého útoku). Po 24 hodinách však klesne postavě bonus (či zvýší se postih) za odolnost. Je to tak od Odl ~ 5 — pokles o 1/pokles o 2. Klesne-li postih postavy za odolnost na −6 nebo níže, postava náhle usne a již se nikdy neprobudí. K léčbě poklesu odolnosti potřebuje postava přežívší mráz odpočinek v teple. Z poklesu o 1 se léčí dva dny, z poklesu o 2 další tři dny atd. PŘÍKLAD: PŘÍKLAD: Z poklesu odolnosti z bonusu +3 na postih −2 se bude postava léčit 20 dnů naprostým odpočinkem v teple. Při sesílání kouzla musí chodec terči do dlaně vtisknout oblázek odněkud z teplých pláží jižních moří, který si odtud sám donesl nebo ho dostal darem.' AS pop
  UNION ALL SELECT 'Přivolej druida' AS nazev, 6 AS uroven, '4 magy' AS mag, 'hvozd' AS dos, '1 směna' AS sesl, NULL AS trv, 'nevycerpavajici' AS un, 'Rozsah: hvozd. Pomůcky: dubový list. Chodec může takto kdekoli ve hvozdu upozornit všechny místní druidy na svou přítomnost. Každý druid přítomný v daném hvozdu uslyší v hlavě vzkaz "jsem zde" spolu s intuitivním pocitem místa, kde se chodec právě nachází. Vzkaz může být i delší a obsahovat nějaké sdělení (například "Potřebuji pomoc, protože..."), avšak nesmí být příliš komplikovaný. Chodec neví, zda jeho vzkaz někdo přijal, a druid neví (pokud to nebylo součástí vzkazu), jak se bude zmíněný chodec chovat dál. Chodec musí při seslání tohoto kouzla mezi prsty rozmnožit dubový list, který mu věnoval nějaký druid. List je opakovaně nepoužitelný.' AS pop
  UNION ALL SELECT 'Rozdělej oheň' AS nazev, 6 AS uroven, '4 magy' AS mag, NULL AS dos, '1 směna' AS sesl, NULL AS trv, 'nevycerpavajici' AS un, 'Pomůcky: dvě dřeva či křemeny. Toto kouzlo spojené s intenzivním třením dvou dřev či otloukáním dvou křemenů po dobu jedné směny (bez těchto pomůcek nepůsobí) dokáže i v jakkoli mokré hromadě klestí (pozor, nesmí ležet ve vodě!) rozdělat oheň, který nezhasne, dokud je naň přikládáno. Dřeva a kameny musejí být suché a zpravidla se jedná o pečlivě vybrané kusy, které chodec najde na svých cestách a nosí je s sebou zabalené. Za suchého počasí (alespoň tři dny nepršelo) má ve volné přírodě pravděpodobnost 15 %, že během 24 hodin vhodné pomůcky najde, za každým dnem v průběhu posledních tří dnů se pravděpodobnost sníží o 5 %. Pomůcky lze k rozdělání ohně použít opakovaně. Od 16. úrovně jsou chodcova nová kouzla pocestných: Hlídka, Maskování. Níže uvedená kouzla pocestných stojí 1 mag za směnu nebo méně; jde spíše o schopnost, na niž je třeba se soustředit. Chodec může po dobu takového kouzla sledovat okolí, ale nemůže kouzlit ani bojovat. Pokud chodec začne sesílat kouzlo jiného druhu nebo začne bojovat, veškerá tato „jednomagová" kouzla pocestných rázem pominou a je třeba je znovu seslat. Během jejich působení se chodec může pohybovat pouze chůzí, nikoli spěchem ani během (není-li řečeno jinak).' AS pop
  UNION ALL SELECT 'Hlídka' AS nazev, 16 AS uroven, '1 mag za tři směny' AS mag, NULL AS dos, '1 kolo' AS sesl, NULL AS trv, 'vycerpavajici' AS un, 'Pomůcky: žádné. Chodec se může uvést do stavu polospánku, při němž sedí na jednom místě. Chodec zná zvuky noční přírody a má možnost rozpoznat z nich, zda se k němu (nebo k táboru) blíží něco nebezpečného. Tato šance není automatická, přesná pravidla pro naslouchání ve volné přírodě zná PJ. Na rozdíl od normálního spánku má chodec v polospánku šanci zareagovat dřív, než se ocitne s mečem u hrdla. Z hlediska únavy se tento polospánek považuje za odpočinek, tj. má poloviční účinky oproti skutečnému spánku. Z hlediska meditace se však za skutečný spánek považuje, takže chodec může meditovat (není-li vyčerpaný), ovšem pouze za předpokladu, že od posledního plnohodnotného spánku neuplynulo více než 50 hodin. To znamená, že chce-li chodec pravidelně meditovat, musí se alespoň každou třetí noc pořádně vyspat.' AS pop
  UNION ALL SELECT 'Maskování' AS nazev, NULL AS uroven, '1 mag za směnu a tvora' AS mag, NULL AS dos, '1 kolo' AS sesl, NULL AS trv, 'vycerpavajici' AS un, 'Pomůcky: žádné. Pomocí tohoto kouzla se může chodec skrýt před svými pronásledovateli. Ve volné přírodě chodec dokáže maskovat a pohybovat se terénem tak, aby nebyl viděn, takže ti, kdo ho hledají, projdou kolem jeho úkrytu, aniž by ho spatřili. Proti druidovi a hvozdu je toto kouzlo neúčinné. Snaží-li se chodce vypátrat druid mimo hvozd nebo jiný chodec, hází si pátrající proti pasti Roz ~ 11 ~ úspěch při pátrání/neúspěch. Základní nebezpečnost pasti se však ještě opravuje podle Tabulky maskování v závislosti na terénu. Maskování může chodec na 16. úrovni uplatnit pouze na sebe, a na 20. úrovni i na tvory, s kterými cestuje (svého psa, koně, členy družiny a podobně). Počet takových tvorů závisí na chodcově úrovni a udává ho Tabulka matení. Maskování může chodec uplatnit i při lovu, při pokusu o nenápadné přiblížení se ke zvířeti, které by ho mohlo ucítit. PJ může v takovém případě dle své úvahy snížit nebezpečnost pasti.' AS pop
  UNION ALL SELECT 'Matení pachů' AS nazev, NULL AS uroven, '1 mag za směnu a tvora' AS mag, NULL AS dos, '1 kolo' AS sesl, NULL AS trv, 'vycerpavajici' AS un, 'Pomůcky: různé. Chodec dokáže zmást svou pachovou stopu natolik, že ji žádné zvíře ani jiný tvor obdařený výborným čichem nedokáže sledovat. Chodec může buď promísit se jinými pachovými stopami, rozhodit ze sebe pepř nebo jiný prášek znemožňující stopování, nebo použít srst, trus či jinou pachovou stopu nějakého tvora a nechat svou stopu za jinou. Toto kouzlo zmate loveckého psa při pokusu o vystopování chodce a způsobí automatický neúspěch loveckého psa po povelu hledej — ovšem jen dokud pes stopu teprve hledá; je-li pes už v přímém „dočichu" od chodce, zmást se nenechá. Matení pachů může chodec na 16. úrovni uplatnit toliko na sebe, na 20. úrovni i na tvory, s nimiž cestuje; platí stejná pravidla jako u maskování.' AS pop
  UNION ALL SELECT 'Matení stop' AS nazev, NULL AS uroven, '1 mag za směnu a tvora' AS mag, NULL AS dos, '1 kolo' AS sesl, NULL AS trv, 'vycerpavajici' AS un, 'Pomůcky: různé. Chodec velikosti B nebo C za sebou může zanechávat libovolnou stopu bytosti velikosti A, B nebo C a chodec velikosti A za sebou může zanechávat libovolnou stopu bytosti velikosti B. Kromě toho chodec nemusí zanechávat vůbec žádnou stopu. PJ vždy zváží, zda v daném terénu lze stopu takto pozměnit. Proti druidovi a hvozdu je toto kouzlo neúčinné. Snaží-li se chodce vystopovat druid mimo hvozd nebo jiný chodec, hází si stopující proti pasti Roz ~ 11 ~ úspěch při stopování/neúspěch. Matení stop může chodec na 16. úrovni uplatnit toliko na sebe, pro vyšší úrovně platí stejná pravidla jako u maskování.' AS pop
  UNION ALL SELECT 'Tichá chůze' AS nazev, NULL AS uroven, '1 mag za směnu' AS mag, NULL AS dos, '1 kolo' AS sesl, NULL AS trv, 'vycerpavajici' AS un, 'Pomůcky: žádné. Kouzlo zajistí chodci naprosto tichý pohyb, takže ho nikdo nezaregistruje, dokud jej neuvidí (nápadnost −10 %). Kouzlo lze plně využít pouze za světla nebo měsíční noci, nikoli v naprosté tmě. V úplné tmě má chodec nápadnost jenom 0. Toto kouzlo může chodec seslat pouze na sebe, nikoli na jiného tvora. (Pozn.: kouzla Matení pachů, Matení stop a Tichá chůze nejsou v PPE výslovně vyjmenována v úvodním seznamu „nová kouzla pocestných" [ten jmenuje jen Hlídku a Maskování], ale následují v textu bezprostředně za nimi jako součást stejného oddílu — přepsáno tak, jak jdou v pořadí za sebou na skenu, bez svévolného škrtání.)' AS pop
  UNION ALL SELECT 'Ledová čepel' AS nazev, 16 AS uroven, '3 magy za první kolo, 2 za…' AS mag, NULL AS dos, NULL AS sesl, 'dle dodané magenergie' AS trv, NULL AS un, 'Magenergie (přesně): 3 magy za první kolo, 2 za každé další. Po seslání tohoto kouzla začne z meče sálat strašlivý mráz. V naprosté tmě se meč mírně namodrale rozzáří. Při úspěšném zásahu nepřítele (je mu útokem odebrán alespoň 1 život), přijde tento navíc o 2–7 životů zraněním chladem. Pokud je takto zasažena hmotná bytost, která má za podstatu oheň, je zraněna za 4–14 životů, a pokud je takto zasažena nehmotná ohnivá bytost, ztrácí 2–7 životů. Kouzlo má všechny vlastnosti vyvolávání i působení podobné ohnivé čepeli a lze jím jinému chodci zrušit kouzlo ohnivá čepel. Na sobě samozřejmě nelze najednou seslat ohnivou a ledovou čepel, jinak se navzájem vyruší.' AS pop
  UNION ALL SELECT 'Najdi nepřítele' AS nazev, NULL AS uroven, '3 magy' AS mag, NULL AS dos, NULL AS sesl, '1 směna' AS trv, NULL AS un, 'Po seslání tohoto kouzla se meč i v naprosté tmě natočí vždy směrem k nepříteli, s nímž chodec bojuje, případně k nepříteli stojícímu poblíž, a v boji mu bude zasazovat rány na nechráněná místa. Meč jako by po dobu přítomnosti nepřítele dobře věděl, kde se zrovna nachází (tj. v rozšířeném soubojovém systému vždy pozná, na kterém hexu protivník je). Chodce tedy při použití tohoto kouzla nemohou žádní cizí nepřátelé překvapit v boji, ani po tmě nebo v naprosté tmě, kdy má jinak postih jen −2 (a v rozšířeném soubojovém systému −2).' AS pop
  UNION ALL SELECT 'Najdi neviditelného' AS nazev, NULL AS uroven, '20 magů' AS mag, NULL AS dos, NULL AS sesl, '1 směna' AS trv, NULL AS un, 'Pokud je chodec napaden někým neviditelným nebo má pocit, že někdo neviditelný prochází kolem, sešle toto kouzlo. Meč se nasměruje na neviditelného, a pokud tento začne prchat, směruje chodce za ním. Kouzlo má dosah třicet sáhů, takže pokud se neviditelnému podaří uprchnout za tuto hranici, chodec ho „ztratí". V boji s neviditelným se meč vždy snaží útočit na nekrytá místa, takže chodec má postih jen −2 (a v rozšířeném soubojovém systému vždy pozná, na kterém hexu protivník je). Pokud je neviditelných víc, meč si vybere toho, kdo je nejblíž, nebo toho, na kterého bude chodec chtít zaútočit. Kouzlo nepůsobí na bytosti neviditelné od přírody, ale pouze na ty, které jsou pod vlivem kouzla typu neviditelnost. Kouzlo působí i v naprosté tmě.' AS pop
  UNION ALL SELECT 'Ohnivá čepel' AS nazev, NULL AS uroven, '3 magy za první kolo, 2 za…' AS mag, NULL AS dos, NULL AS sesl, 'dle dodané magenergie' AS trv, NULL AS un, 'Magenergie (přesně): 3 magy za první kolo, 2 za každé další. Po seslání tohoto kouzla se kolem čepele meče rozhoří bledý plamen vydávající asi tolik světla jako pochodeň. Kouzlem lze v boji úspěšně zrušit kouzlo ledová čepel jinému chodci. Při srážce mečů se obě kouzla vyruší a je třeba je seslat znovu. Sešle-li chodec na meč najednou ohnivou a ledovou čepel, navzájem se vyruší. Při seslání kouzla není nutno určit přesný počet kol, po který má meč „hořet". Pokud chodec nechce po dobu trvání kouzla sesílat na meč žádná další kouzla, může trvání ohnivé čepele kontinuálně za každé dva magy prodlužovat. Chce-li však kouzlit i během trvání ohnivé čepele, musí hned při vyvolání tohoto kouzla určit, kolik kol má trvat, přičemž z meče ubude veškerá potřebná magenergie. Prodloužení trvání ohnivé čepele se v takovém případě považuje za nové seslání kouzla. Seslal-li chodec ohnivou čepel na více kol, může její trvání kdykoliv ukončit, ovšem považuje se to za magickou operaci (kouzlení) a nevyužitá magenergie do kouzla vložená bude nenávratně ztracena.' AS pop
  UNION ALL SELECT 'Rozpoznání nepřítele' AS nazev, NULL AS uroven, '2 magy' AS mag, NULL AS dos, NULL AS sesl, '1 kolo' AS trv, NULL AS un, 'Po světě se potulují různé nestvůry a ne každá je zranitelná všemi druhy zbraní. Tímto kouzlem chodec zjistí, zda je jeho meč vůči nestvůře, se kterou právě bojuje, účinný, aniž by to musel poznávat teprve podle výsledku útoku. (Pozn.: odstavec o Rozpoznání nepřítele obsahuje v OCR skenu zjevně poškozenou/zacyklenou pasáž — přesné doslovné znění nelze rekonstruovat, výše uveden nejpravděpodobnější smysl kouzla; PJ ať si při použití ověří ve skenu.)' AS pop
  UNION ALL SELECT 'Rychlost' AS nazev, NULL AS uroven, '3 magy za kolo' AS mag, NULL AS dos, NULL AS sesl, 'dle dodané magenergie' AS trv, NULL AS un, 'Po seslání tohoto kouzla je v dalším kole možno provést s mečem dvě magické operace, tj. seslat dvě kouzla nebo přelít magenergii a ještě seslat kouzlo. Chodec takto může dvakrát za kolo zaútočit dvojitým sekem, nikoli však dvakrát trojitým sekem. Při útoku dvěma dvojitými seky se vystavuje nebezpečí dvojnásobného zranění, jaké by hrozilo při útoku trojitým sekem. Pozor, rychlost zdvojnásobuje pouze počet magických operací, nikoli počet útoků — na to jsou kouzla dvojitý a trojitý sek. Toto kouzlo je také jediné kouzlo meče, jehož účinek začne působit až v dalším kole po seslání. Rychlost působí nepřetržitě více kol v závislosti na dodané magenergii. Magenergie z meče neubývá postupně, nýbrž zmizí ihned po seslání. Je-li na meč, který je pod vlivem rychlosti, seslána další rychlost, účinek kouzla se neznásobí, ale prodlouží se jeho trvání.' AS pop
  UNION ALL SELECT 'Trojitý sek' AS nazev, NULL AS uroven, '12 magů' AS mag, NULL AS dos, NULL AS sesl, '1 kolo' AS trv, NULL AS un, 'Toto kouzlo chodci umožní, aby v jednom kole zaútočil třikrát. V rozšířeném soubojovém systému to znamená, že má bonus +12 k hodu na iniciativu. Získané akce lze využít jen pro boj, tedy na akci obrana nebo útok tímto mečem. Toto kouzlo nelze v jednom kole za žádných okolností použít dvakrát, ani když má meč seslanou rychlost. Útok je již tak rychlý, že pohyby meče mohou být nebezpečné i samotnému chodci. Má-li sílu menší než 15, ztrácí počet životů rovný rozdílu mezi 15 a svou skutečnou silou. Má-li sílu menší než 12, musí navíc na 1k10 hodit víc, než je rozdíl mezi 12 a jeho skutečnou silou, jinak mu meč vyletí z ruky.' AS pop
  UNION ALL SELECT 'Většička' AS nazev, NULL AS uroven, '10 magů' AS mag, NULL AS dos, NULL AS sesl, 'viz níže' AS trv, NULL AS un, 'Meč se náhle promění v hůl či nenápadnou pokroucenou větev (závisí na chodci) a zůstane v této podobě, dokud si chodec nebude přát opak. Pak se bez vynaložení další magenergie změní zpět k původní podobě, ale chodec přitom hůl drží v ruce. Celá proměna je jenom iluze. Meč zůstává mečem a nikdo nedokáže onu „hůl" přelomit přes koleno. Protivník útočící na „hůl" po celou dobu působení kouzla uplatňuje stejný postih jako na útok proti meči. (Pozn.: odstavec o Většičce v OCR skenu obsahuje poškozenou pasáž míchající text s odstavcem o Zvýšení síly zbraně — ponechán co nejpravděpodobnější smysl, viz sken pro přesné znění.)' AS pop
  UNION ALL SELECT 'Zvýšení obrany zbraně' AS nazev, NULL AS uroven, 'dle velikosti a doby trvání' AS mag, NULL AS dos, NULL AS sesl, 'dle dodané magenergie' AS trv, NULL AS un, 'Toto kouzlo chodci umožní útočit a zároveň se lépe krýt. Pohyb meče se zrychlí a bude lépe reagovat na výpady protivníkova ostří či paratů. Za 1 mag se obrana zbraně zvýší o 1 na jeden takový hod na obranu, při němž chodec uplatňuje obranu zbraně. Chodec si může zvolit, na kolik obran a o kolik chce zvýšit obranu zbraně svého meče, ale musí dodržet následující podmínky: OZ musí být po všechny obrany zvýšena o stejnou hodnotu, zvýší se hned po seslání kouzla a bude nepřerušeně trvat až do vyčerpání magenergie. OZ není možno zvýšit více než o +7. V dalších kolech může chodec do meče se zvýšenou obranou normálně přelévat magenergii nebo na něj sesílat kouzla. Na meč nemůže zároveň působit zvýšení obrany zbraně a zvýšení síly zbraně. Pokud chodec během působení prvního kouzla sešle druhé, první tím automaticky zruší.' AS pop
  UNION ALL SELECT 'Zvýšení síly zbraně' AS nazev, NULL AS uroven, 'dle velikosti a doby trvání' AS mag, NULL AS dos, NULL AS sesl, 'dle dodané magenergie' AS trv, NULL AS un, 'Tímto kouzlem je chodec schopen zvýšit sílu zbraně svého meče. Za každý dodaný mag se za jeden útok zvýší o 1. Chodec si může zvolit, na kolik útoků a o kolik chce zvýšit sílu zbraně svého meče, ale musí přitom dodržet tyto podmínky: po celou dobu zvýšení musí být toto zvýšení stejné. Celková síla zbraně chodcova meče nesmí překročit 14, a to ani tehdy, je-li základní síla zbraně vyšší než 7. Síla zbraně vzroste ihned po seslání kouzla a bude bez přerušení trvat až do vyčerpání magenergie kouzla. Jedná se přitom o počet útoků, nikoli o počet kol, pokud tedy v dalším kole chodec na meč sešle dvojitý nebo trojitý sek, za jedno kolo vynaloží magenergii na dva či tři útoky. V dalších kolech může chodec do meče se zvýšenou silou zbraně normálně přelévat magenergii nebo na něj seslat jiná kouzla. Na meč nemůže zároveň působit zvýšení síly zbraně a zvýšení obrany zbraně. Pokud chodec během působení prvního kouzla sešle druhé, první tím automaticky zruší. PŘÍKLAD: PŘÍKLAD: Chodec Warden se v boji se šermířem ocitne v těžkém postavení a rozhodne se použít zvýšení síly zbraně. Warden je na 20. úrovni, do jeho meče se vejde 24 magů, a přesně tolik jich tam teď je. Warden se rozhodne zvýšit sílu zbraně na čtyři útoky o 6. Na to bude potřebovat veškerou magenergii meče. Zaútočí, a pak teprve (v témže kole) sešle kouzlo. V dalším kole síla zbraně vzroste na 13. Warden útočí a zároveň na meč přelije dalších 24 magů. Trochu šermíře pochroumá. Na začátku dalšího kola sešle trojitý sek, útočí třikrát, pokaždé se silou zbraně 13. Tím mu v meči zbude 12 magů a síla zbraně na konci kola opět klesne na 7. Na začátku dalšího kola přelije do meče dalších 12 magů, aby celou zásobu zopakoval, ale to se už zděšený šermíř dává na ústup, protože něco takového dosud nezažil.' AS pop
  UNION ALL SELECT 'Odhal vinu' AS nazev, 6 AS uroven, '3 magy' AS mag, '10 sáhů' AS dos, '1 kolo' AS sesl, NULL AS trv, 'vycerpavajici' AS un, 'Past: Chr + Roz ~ 10 + Int chodce. Kouzlem odhal vinu lze zkoumat vinu nebo nevinu osoby, na kterou předtím chodec úspěšně seslal uhrančivý pohled. Chodec se upřeně zahledí na zkoumanou postavu a ta si hodí proti pasti. Pokud neuspěje, chodec ví s jistotou, zda je dotyčný vinen či nikoliv. Pokud v pasti uspěje, chodec je na pochybách. Neuspěla-li by postava v hodu proti pasti s nebezpečností o 5 nižší, nevydrží chodcův psychický tlak a omdlí (pokud je nevinná) nebo se spontánně ke všemu přizná (pokud je vinná). Chodec musí mít před použitím kouzla alespoň hrubou představu, z čeho postavu podezírá — není možné s jeho pomocí zjistit, zda svědomí zkoumané postavy netíží nějaký hřích, o kterém chodec vůbec netuší. PŘÍKLAD: PŘÍKLAD: Chodec Marek přijde do vesnice a vesničané ho požádají, aby rozhodl při sporu dvou selek, které se nemohou dohodnout, čí je dítě, které se včera narodilo. Marek napřed sešle uhrančivý pohled — to jej stojí dva magy a vesničanky si házejí proti pasti Int + Roz ~ 5; jejich bonus za inteligenci je 0 a rozdíl úrovní je −6, protože Marek je na šesté úrovni a ony, jako prosté obyvatelky, musely by hodit 11, aby uspěly. Pak si Marek vybere tu z žen, u níž předpokládá menší autoritu, a sešle odhal vinu za 6 magů. Žena si hází proti pasti Chr + Roz ~ 14 (10 + přidaná magenergie 3 za inteligenci Marka). I s bonusem za charisma jí padne celkem 7 a Marek si je náhle jist, že tato žena je vinna. Ale dřív, než stačí nic říct, nešťastnice propukne v pláč a s hlasitými vzlyky se vyzná ze své špatnosti.' AS pop
  UNION ALL SELECT 'Odveď pozornost' AS nazev, 6 AS uroven, '5 magů' AS mag, '20 sáhů' AS dos, '1 kolo' AS sesl, NULL AS trv, 'vycerpavajici' AS un, 'Past: Int + Roz ~ 7 (10). Rozsah: skupina osob. Tímto kouzlem může chodec odvrátit pozornost od námětu hovoru, konkrétního předmětu či osoby, u nichž mu z nějakého důvodu vadí, že jsou v centru pozornosti. Po seslání kouzla si postava s nejvyšší životaschopností ve skupině hodí proti pasti s nebezpečností 7, a pokud neuspěje, chodec nenápadně odvede řeč jinam. Celá společnost se nového námětu hovoru chopí a na starý zapomene. Jednotliví účastníci rozpravy si druhý den házejí proti pasti s nebezpečností 10. Pokud uspějí, vzpomenou si na původní námět hovoru. Chodec však pomocí tohoto kouzla nemůže odvést pozornost od hlavního námětu večerního hovoru či osoby nebo předmětu, které se neustále nějak projevují. Odhad účinnosti kouzla v takovém případě je ponechán na Pánovi jeskyně.' AS pop
  UNION ALL SELECT 'Uhrančivý pohled' AS nazev, 6 AS uroven, '2 magy' AS mag, 'musí mít vidět do očí' AS dos, '1 kolo' AS sesl, '3 směny' AS trv, 'vycerpavajici' AS un, 'Past: Int + Roz ~ 5. Po seslání tohoto kouzla se chodcovy oči rozzáří nepřirozeným vnitřním jasem, který naplní všechny osoby, jež neuspějí v hodu proti pasti, velikou bázní, takže k chodci budou chovat velký respekt a nic si na něj nedovolí. Kouzlo je také předpokladem pro seslání několika dalších kouzel. Dosahem ,musí mít vidět do očí'' je míněno to, že terč má chodcovy oči ve svém zorném poli. Kouzlo samo zajistí, že chodec upoutá pozornost oběti, takže ta mu pohlédne do očí (pokud není slepá) a musí si pak hodit proti pasti.' AS pop
  UNION ALL SELECT 'Uspi okolí' AS nazev, 6 AS uroven, '7 magů' AS mag, '25 sáhů' AS dos, '1 směna' AS sesl, NULL AS trv, 'nevycerpavajici' AS un, 'Past: Odl + Roz ~ 10. Chodec sešle toto kouzlo a zároveň začne zívat a předstírat, že je ospalý. Ospalost brzy nakazí všechny v okolí. Všechny postavy, které neuspějí v hodu proti pasti, se do 2 směn odeberou spát či usnou na místě. Poté, co postavy upadnou do tvrdého spánku, ztratí kouzlo svou moc a mohou být normálně probuzeny.' AS pop
  UNION ALL SELECT 'Zrcadlo vzpomínek a melancholie' AS nazev, 6 AS uroven, '9 magů' AS mag, '40 sáhů' AS dos, '1 kolo' AS sesl, '6 směn' AS trv, 'vycerpavajici' AS un, 'Past: Chr + Roz ~ 9. Rozsah: 1 osoba. Sesláním tohoto kouzla může chodec jedné osobě, na kterou předtím úspěšně seslal uhrančivý pohled, na dobu jedné hodiny zlepšit přesvědčení. Kouzlo v dotčeném vyvolá melancholickou vzpomínku na nějakou zvláštní událost v uplynulých letech, která jej na uvedený čas učiní lepším. Pokud terč kouzla neuspěje v hodu proti pasti, musí si znovu hodit proti stejné pasti, ale s nebezpečností o 2 nižší. Za každý neúspěch se mu přesvědčení posune o 1 k lepšímu. Postava si tak hází tak dlouho, dokud neodolá pasti nebo nedosáhne nejlepšího možného přesvědčení. Pozor! Ani ten nejhorší lotr obrácený na zákonné dobro nebude jednat tak, aby se uvedl v nebezpečí, pouze bude mít snahu napravit křivdy, nikoli však za cenu ohrožení vlastního hrdla. Toto kouzlo trvale napraví uměle zhoršené přesvědčení.' AS pop
  UNION ALL SELECT 'Odhal tajemství' AS nazev, 6 AS uroven, 'viz níže' AS mag, '10 sáhů' AS dos, '1 směna' AS sesl, NULL AS trv, 'nevycerpavajici' AS un, 'Past: neháže se. Rozsah: 1 osoba, místo, předmět apod.. Tímto kouzlem lze odhalit tajemství určitého místa, stavby, předmětu nebo osoby. Tajemství musí mít vždy něco společného s nějakými inteligentními tvory. Může se jednat například o mytickou studánku, nehlubokou jeskyni, táboříště nebo cokoli podobného. Na každou úroveň tajemství musí chodec vynaložit 3 magy, až do své úrovně; na další úroveň je zapotřebí 6 magů, pak 12, 24 atd. Odhal tajemství je tzv. kouzlo s neurčitou magenergií — chodec musí předem oznámit, kolik magů chce do kouzla vložit. Pokud se kouzlo zdaří, PJ mu oznámí skutečný počet magů, které kouzlo stálo; jestliže chodec vložil magů málo, kouzlo se nezadaří a přijde o veškerou vloženou magenergii. PŘÍKLAD: PŘÍKLAD: Chodec Warden (18. úroveň) se v troskách staré budovy rozhodne použít kouzlo odhal tajemství (terčem bude budova). PJ ví, že se jedná o poklad zakopaný v základech sklepa. Před sto lety ho tam zakopal lupič Picnámol, tehdy na desáté úrovni. Tajemství pokladu je tedy tajemstvím 20. úrovně a Warden by potřeboval celkem 72 magů (18 × 3 + 6 + 12 magů), aby je odhalil. Tolik Warden nemá. PJ se Wardena zeptá, do kolika magů by chtěl jít. Ten odpoví 40 — to nestačí. Tvrdohlavý Warden na místě přespí a ráno to zkusí znovu. Druhý den tam bezvýsledně vynaloží veškerou svoji magenergii a přijde o ni. Naštván odejde s tím, že se vrátí, až bude na vyšší úrovni.' AS pop
  UNION ALL SELECT 'Rozčíl' AS nazev, 6 AS uroven, '3 magy' AS mag, '10 sáhů' AS dos, '1 směna' AS sesl, NULL AS trv, 'nevycerpavajici' AS un, 'Past: Roz + Chr ~ 11. Rozsah: 1 osoba. Toto kouzlo je schopno ve spojení s hovorem během jedné směny rozčílit jakoukoli osobu, která byla až do té doby zcela klidná. Zvláštní přitom je, že celému chodcovu okolí, vyjma terče kouzla, se chodcova řeč zdá být velmi rozumná a zcela neurážlivá. Rozčílená osoba je silně vyvedena z míry, avšak podoba jejího rozčílení závisí na její inteligenci a temperamentu. Inteligentním osobám se může jen trochu přiostřit hlas, jiné mohou vztekle začít mluvit pravdu, zatímco osoby s nízkou inteligencí mohou vztekem náhle začít demolovat vše kolem. Zda si dotyčná osoba uvědomí, že ji rozčílil právě chodec, je past Int ~ 11 ~ uvědomění si/nic. Reakce závisí na povaze či rozhodnutí PJ.' AS pop
  UNION ALL SELECT 'Uklidni' AS nazev, 6 AS uroven, '3 magy' AS mag, '10 sáhů' AS dos, '1 směna' AS sesl, NULL AS trv, 'nevycerpavajici' AS un, 'Past: Roz + Chr ~ 11. Rozsah: 1 osoba. Toto kouzlo je schopno ve spojení s hovorem během jedné směny uklidnit jakoukoli rozčílenou osobu, ať už se za jejím rozčílením skrývá cokoli. Chodcova řeč přitom nemusí být vůbec konejšivá; je věcná a jasná a okolostojícím se nezdá, že by se danou osobu snažil nějak zuřivě uklidňovat. Uklidnění se samozřejmě projeví podle inteligence a nátury. Elfímu kouzelníkovi se přestanou třást ruce, zatímco kroll válečník nejspíš nepřestane řvát, ale už nebude myslet vážně. Stejně jako v Pravidlech pro pokročilé je možné u obou výše uvedených psychických kouzel (Rozčíl, Uklidni) zvýšit nebezpečnost pasti přidáním magenergie navíc k základní sesílací. Od 16. úrovně včetně může chodec poznat, že jiný chodec sesílá nějaké psychické kouzlo, případně i jaké. Past má vlastnost Roz+Int, nebezpečnost je 1, resp. 6. ,Roz'' je v tom případě rozdíl úrovní mezi chodcem, který kouzlo poznává, a chodcem, který kouzlo sesílá. Uspěje-li chodec proti pasti s nebezpečností 1, pozná, že je nějaké psychické kouzlo sesíláno. Uspěje-li proti nebezpečnosti 6, pozná i druh kouzla.' AS pop
  UNION ALL SELECT 'Vládni přirozeným věcem' AS nazev, NULL AS uroven, '6 magů' AS mag, 'dotyk' AS dos, '4 kola' AS sesl, 'stálé' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 věc (o cca 2×2×2 sáhy). Chodec může tímto kouzlem poručit jedné věci (či raději uprosit ji) z přírodních materiálů (tedy nekovové), aby mu vyplnila přání (například kámen, aby se odvalil, větev, aby se ulomila, pavučina se roztrhala, dřevěné dveře se otevřely a podobně). Věci musejí být nemagické. Toto kouzlo je výjimečné tím, že je může používat toliko chodec.' AS pop
) v
JOIN seznamy_kouzel s ON s.nazev = 'Kouzla pocestných'
JOIN povolani p ON p.id = s.povolani_id AND p.nazev = 'Chodec';
-- TODO ověřit proti skenu (neúplný/nejasný zápis v předloze u): Tichá chůze; Rozpoznání nepřítele; Většička

-- Kouzla barda / Bard (75 kouzel)
INSERT INTO kouzla (nazev, seznam_kouzel_id, uroven_kouzla, cena_magenergie, dosah, doba_seslani, doba_trvani, typ_unavy, popis)
SELECT v.nazev, s.id, v.uroven, v.mag, v.dos, v.sesl, v.trv, v.un, v.pop
FROM (
  SELECT 'Allegro' AS nazev, NULL AS uroven, '2 magy za cíl' AS mag, 'poloměr Charizmatu' AS dos, '2 kola' AS sesl, '2 směny' AS trv, 'vycerpavajici' AS un, 'Rozsah: všichni v dosahu kouzla. Komponent: H/N. Všichni v dosahu kouzla získají +1 k iniciativě. Pokud chce bard někoho vynechat, musí za něj zaplatit 4 magy. Pokud cíl po dobu trvání opustí oblast a znovu se do ní vrátí, bard za něj toto zakouzlení již nemusí platit. Aby cíl získal bonus, musí být na začátku iniciativy v oblasti působení.' AS pop
  UNION ALL SELECT 'Piano' AS nazev, NULL AS uroven, '5 magů' AS mag, 'poloměr Charizmatu' AS dos, '2 kola' AS sesl, '1 hodina' AS trv, 'vycerpavajici' AS un, 'Rozsah: všichni v dosahu kouzla. Komponent: H+N. Vše co se nachází v dosahu se utiší a zklidní. Zbroj přestane být tak cinkavá a udýchaný válečník už taky nefuní tak nahlas. Všichni v efektu kouzla získají bonus k plížení +1, nebo +10% pokud mají dovednost. Sčítá se se zlodějským plížením. I když se budou postavy snažit, jejich hlučnost i hlasitost jejich hlasu je přibližně poloviční. Tichá oblast se pohybuje zároveň s bardem. Nebo se Bard může rozhodnout zakouzlit na místo. Po zakouzlení už nemusí hrát či zpívat.' AS pop
  UNION ALL SELECT 'Fortessimo' AS nazev, NULL AS uroven, '5 magů' AS mag, 'poloměr Charizmatu' AS dos, '2 kola' AS sesl, '1 hodina' AS trv, 'vycerpavajici' AS un, 'Rozsah: všichni v dosahu kouzla. Komponent: H+N. Vše co se nachází v dosahu začne být mnohem hlasitější. Zbroj bude skřípat a cinkat a udýchaný válečník bude slyšet i ve vedlejší budově.Všichni v efektu kouzla získají postih k plížení -1, nebo -10% pokud mají dovednost. I když se budou postavy snažit, jejich hlučnost i hlasitost jejich hlasu je přibližně dvojnásobná. Hlasitá oblast se pohybuje zároveň s bardem. Nebo se Bard může rozhodnout zakouzlit na místo. Po zakouzlení už nemusí hrát či zpívat.' AS pop
  UNION ALL SELECT 'Adagio' AS nazev, NULL AS uroven, '2 magy za cíl' AS mag, 'poloměr Charizmatu' AS dos, 'dokud trvá hledání, minimálně 1 směna' AS sesl, 'Ihned' AS trv, 'nevycerpavajici' AS un, 'Rozsah: všichni v dosahu kouzla. Komponent: N. Všichni v dosahu kouzla se budou více soustředit a budou všímavější. Každý ovlivněný cíl získá bonus +15% k hledání objektů či mechanizmů. Působí na jedno vybrané hledání' AS pop
  UNION ALL SELECT 'Metalový křik' AS nazev, NULL AS uroven, '10 magů' AS mag, 'poloměr Charizmatu' AS dos, '1 kolo' AS sesl, 'Ihned' AS trv, 'vycerpavajici' AS un, 'Rozsah: všichni v dosahu kouzla. Komponent: H. Bard zakřičí vší silou pod své nohy. Všichni v dosahu kouzla si hází na Past -6- Odol efekt/nic. Pokud cíl neuspěje v hodu proti pasti, je odtlačen mimo dosah kouzla. V případě fatálního neúspěchu je cíl sražen na zem.' AS pop
  UNION ALL SELECT 'Pán tance 1' AS nazev, NULL AS uroven, '2 magy za cíl' AS mag, 'poloměr Charizmatu' AS dos, '2 kola' AS sesl, '2 směny' AS trv, 'vycerpavajici' AS un, 'Rozsah: všichni v dosahu kouzla. Komponent: H+N+T. Všechny cíle které souhlasí s efektem získají +1 k hodu na past k dovednosti tanec. Pokud je kouzlo sesláno v boji, mají souhlasící cíle +1 k Oč. Když cíl nesouhlasí, bard se jej může pokusit donutit násilím. Cíl si hází na Past Char -5- Char efekt/nic efektem je naopak postih k Oč. -1 po dobu trvání tance. Všichni tančící ať už dobrovolní či nikoliv, získávají 2 body únavy za směnu tance i započatou. Po seslání kouzla musí bard udržovat pouze komponent T. Během kouzla se může přesouvat nejrychleji během, cíle které se dostanou mimo dosah kouzla, se ihned vrací k normálu.' AS pop
  UNION ALL SELECT 'Danse macabre 2' AS nazev, NULL AS uroven, '4 magy za cíl' AS mag, 'poloměr Charizmatu' AS dos, '2 kola' AS sesl, '2 směny' AS trv, 'vycerpavajici' AS un, 'Rozsah: všichni nemrtví v dosahu kouzla. Komponent: H+N+T. Působení: Musí umět Pán tance 1. Všechny nemrtvé cíle v dosahu kouzla popadne neodolatelná chuť připojit se tancem k bardovi, následovat jej a kopírovat jeho kreace. Bard musí určit cíle, které budou v dosahu kouzla ovlivněny, pokud sešle na jiný cíl než nemrtvý, kouzlo nebude mít efekt. Cíl si hází na past Roz -6- Int efekt/nic. Takto ovlivnění nemrtví mají postih -2 Úč, Oč. a -1 k iniciativě. V rámci tance se bard i cíle mohou pohybovat maximálně chůzí. Po dobu trvání kouzla musí bard udržovat komponenty N+T.' AS pop
  UNION ALL SELECT 'Píseň na cesty 1' AS nazev, NULL AS uroven, '3 magy za cíl' AS mag, 'poloměr Charizmatu' AS dos, '1 kolo' AS sesl, 'pochod' AS trv, 'vycerpavajici' AS un, 'Rozsah: všichni v dosahu kouzla. Komponent: H. Všichni pod vlivem kouzla se budou pohybovat rychleji o jeden stupeň, než by se pohybovali normálně dle svého aktuálního naložení. Kouzlo skončí dokud se skupina pohybuje a nezastaví se na déle než 1 směnu - krátký rozhovor apod.' AS pop
  UNION ALL SELECT 'Toulavá píseň 2' AS nazev, NULL AS uroven, '3 magy za cíl' AS mag, 'poloměr Charizmatu' AS dos, '1 kolo' AS sesl, 'pochod' AS trv, 'vycerpavajici' AS un, 'Rozsah: všichni v dosahu kouzla. Komponent: N. Působení: Musí umět Píseň na cesty 1. Všichni pod vlivem kouzla se budou unavovat poloviční rychlostí za pohyb. Nepočítá se, pokud se postavy vezou.' AS pop
  UNION ALL SELECT 'Pochodový step 3' AS nazev, NULL AS uroven, '3 magy za cíl' AS mag, 'poloměr Charizmatu' AS dos, '1 kolo' AS sesl, 'pochod' AS trv, 'vycerpavajici' AS un, 'Rozsah: všichni v dosahu kouzla. Komponent: T. Působení: Musí umět Toulavá píseň 2. Všichni pod vlivem kouzla se budou pohybovat rychleji o 10 jednotek pohybu. Nejlépe jako po cestě.' AS pop
  UNION ALL SELECT 'Ukolébavka' AS nazev, NULL AS uroven, '2 magy za cíl' AS mag, 'poloměr Charizmatu' AS dos, '1 směna' AS sesl, 'spánek' AS trv, 'nevycerpavajici' AS un, 'Rozsah: všichni v dosahu kouzla. Komponent: H+N. Bard umožní cílům kouzla usnout i v jinak nevhodných podmínkách. Cíle musí s kouzlem souhlasit. Nevýhodou je, že je mnohem těžší je probudit.' AS pop
  UNION ALL SELECT 'Mírné nepohodlí 1' AS nazev, NULL AS uroven, '12 magů' AS mag, 'poloměr Charizmatu x3' AS dos, '3 kola' AS sesl, '1 hodina' AS trv, 'vycerpavajici' AS un, 'Rozsah: všichni protivníci v dosahu. Komponent: H+N. Všichni nacházející se v dosahu si budou vědomí různých nepříjemných zkušeností. Tlačí je boty, je horko, jsou unavení apod. Má to za efekt, že mají postih -1 k Úč, Oč a ini. Po seslání již nemusí udržovat komponenty.' AS pop
  UNION ALL SELECT 'Střední nepohodlí 2' AS nazev, NULL AS uroven, '16 magů' AS mag, 'poloměr Charizmatu x3' AS dos, '2 kola' AS sesl, '1 směna' AS trv, 'vycerpavajici' AS un, 'Rozsah: všichni protivníci v dosahu. Komponent: H+N. Působení: Musí umět Mírné nepohodlí 1. Všichni nacházející se v dosahu si budou vědomí různých nepříjemných zkušeností. Je jim špatně, je velké horko, jsou velmi unavení apod. Má to za efekt, že mají postih -2 k Úč, Oč a ini. Po seslání již nemusí udržovat komponenty.' AS pop
  UNION ALL SELECT 'Velké nepohodlí 3' AS nazev, NULL AS uroven, '22 magů' AS mag, 'poloměr Charizmatu x3' AS dos, '1 kolo' AS sesl, '3 kola' AS trv, 'vycerpavajici' AS un, 'Rozsah: všichni protivníci v dosahu. Komponent: H+N. Působení: Musí umět Střední nepohodlí 2. Všichni nacházející se v dosahu si budou vědomí různých nepříjemných zkušeností. Je jím strašně špatně, je extrémní horko, jsou vyčerpaní apod. Má to za efekt, že mají postih -4 k Úč, Oč a ini. Po seslání již nemusí udržovat komponenty.' AS pop
  UNION ALL SELECT 'Staccato 1' AS nazev, NULL AS uroven, '10 magů' AS mag, 'poloměr Charizmatu' AS dos, '2 kola' AS sesl, '1 směna' AS trv, 'vycerpavajici' AS un, 'Rozsah: všichni protivníci v dosahu kouzla. Komponent: N. U cíle, který byl úspěšně zasažen, se zhmotní hudební nota a způsobí mu dalších 1k4 životů poškození zvukem.' AS pop
  UNION ALL SELECT 'Legato 2' AS nazev, NULL AS uroven, '10 magů' AS mag, 'poloměr Charizmatu' AS dos, '2 kola' AS sesl, '1 směna' AS trv, 'vycerpavajici' AS un, 'Rozsah: všichni v dosahu kouzla. Komponent: N. Působení: Musí umět Staccato 1. U cíle, který byl úspěšně vyléčen, se zhmotní hudební nota a vyléčí mu dalších 1k4 životů. Platí pro magické léčení, lektvary a obvazy.' AS pop
  UNION ALL SELECT 'Crescendo' AS nazev, NULL AS uroven, '10 magů' AS mag, 'poloměr Charizmatu' AS dos, '1 kolo' AS sesl, '1 směna' AS trv, 'vycerpavajici' AS un, 'Rozsah: všichni v dosahu kouzla. Komponent: H+N. Bard se rozhodne pro posílení 1 atributu všech, kteří jsou v dosahu kouzla. Atribut může libovolně měnit, ale vždy jen na začátku kola a jednou za kolo. Ke zvolenému atributu všichni získají +1 k hodu na past.' AS pop
  UNION ALL SELECT 'Arkánní bublina' AS nazev, NULL AS uroven, '12 magů' AS mag, 'poloměr Charizmatu' AS dos, '1 kolo' AS sesl, '1 směna' AS trv, 'vycerpavajici' AS un, 'Rozsah: všichni v dosahu kouzla. Komponent: H+N. Četnost: 1 za směnu. Bard okolo sebe vytvoří bariéru, která znesnadňuje průchod jakéhokoliv kouzla. Ať už pozitivního, či negativního. Zóna se pohybuje spolu s bardem. Bard musí udržovat oba komponenty dokud chce, aby kouzlo trvalo. Šance, že bude kouzlo pohlceno je 80%. Každé úspěšně zachycené kouzlo sníží šanci na zachycení dalšího o 20%. Pokud se kouzlo skládá z více projektilů naráz, jako například ohnivá koule, počítá se šance na každý projektil. Funguje i na pokusy o telepatii, podrobení apod.' AS pop
  UNION ALL SELECT 'Světelná show' AS nazev, NULL AS uroven, '2 magy' AS mag, 'poloměr Charizmatu' AS dos, '2 kola' AS sesl, '2 hodiny' AS trv, 'vycerpavajici' AS un, 'Rozsah: Bard. Komponent: T. Bard okolo sebe sešle mnohobarevná světla. Běžně se jedná o dodatečné efekty, aby uchátil svoje publikum. Tyto ovšem vydávají skutečné světlo a osvětlí tak bardovo okolí. Intenzita světla je asi jako svíčka, ale rovnoměrně v ploše kouzla.' AS pop
  UNION ALL SELECT 'Vize smrti' AS nazev, NULL AS uroven, '2 magy za cíl' AS mag, '20 sáhů' AS dos, '2 kola' AS sesl, 'ihned' AS trv, 'vycerpavajici' AS un, 'Rozsah: Cíle s inteligencí 2 a více. Komponent: H. Bard se snaží brutálním popisem blízké smrti vystrašit své protivníky. Cíl si hází na Past Int -5- Int efekt/nic. Pokud cíl neuspěje v hodu proti pasti, je vyděšený vidinou blízkého masakru. Raději se do boje vůbec nezapojí bude li to možné. Kouzlo nemá efekt, pokud již cíl bojuje. Kouzlo má šanci zapůsobit i na zvířata, jsou li dostatečně inteligentní.' AS pop
  UNION ALL SELECT 'Trapný fórky' AS nazev, NULL AS uroven, '3 magy za cíl' AS mag, '20 sáhů' AS dos, '2 kola' AS sesl, 'ihned' AS trv, 'vycerpavajici' AS un, 'Rozsah: Max 10 cílů naráz. Komponent: H. Nejhorší repertoár toho, co ´´zábavné´´ připadá primitivům. Všechny cíle, které uspěji v hodu proti pasti jsou zdrceni trapností řečených slov. Dostanou psychické zranění 1k6+4. Cíle které past nepřehodí, fór v jeho podstatě nepochopí a jsou nezraněni, navíc příjemně pobaveni. Past -7- Int efekt/nic' AS pop
  UNION ALL SELECT 'Kvintakord' AS nazev, NULL AS uroven, '4 magy za kolo' AS mag, 'poloměr charizmatu' AS dos, '2 kola' AS sesl, 'ihned' AS trv, 'vycerpavajici' AS un, 'Rozsah: Všichni v dosahu. Komponent: H+N+T. Bard zahalí svoje blízké okolí do krátké, ale intenzivní zimy. Všechny cíle v dosahu jsou zraněny za 1k4 životy za kolo, pokud nemají to nejteplejší oblečení, nebo jinou ochranu proti krutému mrazu. Dalším efektem je, že veškeré kapaliny ihned zmrznou. Lze takto tvořit instantní ledové mosty s krátkou životností. Jakmile se oblast působení kouzla přesune, předešlá oblast se vrátí do normálu. Led udrží i slona, ale může být i nadále ovlivňován silnou bouří, vlnobitím apod.' AS pop
  UNION ALL SELECT 'Měsíční sonáta' AS nazev, NULL AS uroven, '10 magů' AS mag, 'poloměr charizmatu' AS dos, '1 směna' AS sesl, 'ihned' AS trv, 'nevycerpavajici' AS un, 'Rozsah: Všechno v dosahu. Komponent: H+N. Bard skrze tuto píseň může odhalit skutečnou podobu věcí. Může se jednat jak o převleky, tak magické iluze. Samotný jejich efekt nezruší, ale dokud budou v působení kouzla, bude vidět jejich pravá podoba.' AS pop
  UNION ALL SELECT 'Čistý vzduch' AS nazev, NULL AS uroven, '10 magů' AS mag, 'poloměr charizmatu' AS dos, '1 kolo' AS sesl, '1 směna' AS trv, 'vycerpavajici' AS un, 'Rozsah: Všechno v dosahu. Komponent: H+N. Oblast ovlivněná kouzlem nedovolí vniknout dovnitř škodlivým plynům. Dokud chce aby bylo kouzlo aktivní, musí udržovat ob komponenty. Po uplynutí 1 směny stačí pokračovat, sice získá únavu, ale kouzlo samotné se nepřeruší.' AS pop
  UNION ALL SELECT 'Nutkavá melodie' AS nazev, 14 AS uroven, '6 magů za každý ovlivněný cíl' AS mag, '20 sáhů' AS dos, '3 kola' AS sesl, '1 směna' AS trv, 'vycerpavajici' AS un, 'Rozsah: bardova úroveň cílů. Komponent: N. Každý cíl pro kterého bard zpívá bude upozorněn na nějakou skutečnost. Například vy tři taureni nevšímejte si kouzelníka, soustřeďte se na našeho rytíře. Nebo, strážníku potřebujete si nutně odskočit. Cíle si hází na Past - 7 - Int vnuknutí/nic Přesný rozsah nutkání rozhoduje PJ.' AS pop
  UNION ALL SELECT 'Obtížná sláva' AS nazev, NULL AS uroven, '3 magy za ovlivněný cíl' AS mag, '15 sáhů' AS dos, '2 kola' AS sesl, 'ihned' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 cíl. Komponent: H+N. Bard začne nahlas zpívat o úžasnosti jedné konkrétní osoby. Ta samotná je kouzlem neovlivněná. Ovšem všichni ostatní do vzdálenosti 7 sáhů od ní, hází proti PAST Char -5- Int efekt/nic. Všichni kteří v dosahu kouzla neuspěli získají okamžitě 2 akce budou poblouzněni a budou se snažit dotknout cíle, chtít autogram, výskat nadšením z jeho blízkosti apod. Tyto dvě akce využijí okamžitě po neúspěšném hodu bez ohledu na pořadí v iniciativě. Tyto dvě akce jim nespotřebují jejich případné zbývající akce. K pohybu dojde i v případě, že žádné akce již nemají. Aby cíle mohly být ovlivněny, musí bardovi rozumnět.' AS pop
  UNION ALL SELECT 'Brutální zesměšnění' AS nazev, NULL AS uroven, '0 magů' AS mag, '10 sáhů' AS dos, '1 kolo' AS sesl, 'Ihned' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 cíl. Komponent: H. Četnost: 1 za kolo. Bard zesměšní cíl tak nevybíravým způsobem, že cíli způsobí psychickou újmu. Podmínkou je, že cíl musí bardovi rozumnět a musí mít city. Na bežné nemrtvé nebude mít vliv, ale třeba upíři a fextové již mohou být úspěšně zasažení. V případě nejasností rozhoduje PJ. Cíl si hází na Past Char -4- Int zranění za 1k4/nic Pokud cíl neuspěje v hodu proti pasti, je zraněn a na jeden útok/obranu má -1.' AS pop
  UNION ALL SELECT 'Brnkání na nervy 1' AS nazev, NULL AS uroven, '3 magy' AS mag, '10 sáhů' AS dos, '1 kolo' AS sesl, 'Ihned' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 cíl. Komponent: N. Cíl se ocitne pod efektem nepříjemných zvuků a je zraněn za 1k6 životů. Uslyší jej i ostatní, ale efekt bude mít jen na jeden vybraný cíl. Způsobuje psychické zranění.' AS pop
  UNION ALL SELECT 'Otravná melodie 2' AS nazev, 8 AS uroven, '6 magů' AS mag, '12 sáhů' AS dos, '1 kolo' AS sesl, 'Ihned' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 cíl. Komponent: N. Působení: musí umět Brnkání na nervy 1. Cíl se ocitne pod efektem nepříjemných zvuků a je zraněn za 2k6 životů. Uslyší jej i ostatní, ale efekt bude mít jen na jeden vybraný cíl. Způsobuje psychické zranění.' AS pop
  UNION ALL SELECT 'Zdrcující znělka 3' AS nazev, 10 AS uroven, '9 magů' AS mag, '15 sáhů' AS dos, '1 kolo' AS sesl, 'Ihned' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 cíl. Komponent: H+N. Působení: musí umět Otravná melodie 2. Cíl se ocitne pod efektem nepříjemných zvuků a je zraněn za 2k10+2 životů. Uslyší jej i ostatní, ale efekt bude mít jen na jeden vybraný cíl. Způsobuje psychické zranění.' AS pop
  UNION ALL SELECT 'Lamač srdcí 4' AS nazev, 10 AS uroven, '12 magů' AS mag, '15 sáhů' AS dos, '1 kolo' AS sesl, 'Ihned' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 cíl. Komponent: H/N. Působení: musí umět Zdrcující znělka 3. Cíl se ocitne pod efektem nepříjemných zvuků a je zraněn za 3k10+6 životů. Uslyší jej i ostatní, ale efekt bude mít jen na jeden vybraný cíl. Pokud byl cíl bardem sveden, či s ním měl nějakým způsobem sdílenou minulost, je tento zraněn za další 1k10 životů. Rozhoduje PJ. Způsobuje psychické zranění.' AS pop
  UNION ALL SELECT 'Bongo' AS nazev, NULL AS uroven, '2 magy' AS mag, '1 sáhů' AS dos, '1 kolo' AS sesl, 'Ihned' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 cíl. Komponent: N. Bard magicky zpevní svůj nástroj a může s ním zaútočit. Způsobené zranění není magické. Bard může provést klasický útok TvT. Tento je posílen o +3Úč a +2 Útoč.' AS pop
  UNION ALL SELECT 'Strhnutí pozornosti' AS nazev, NULL AS uroven, '5 magů' AS mag, '0' AS dos, '1 kolo' AS sesl, 'Ihned' AS trv, 'vycerpavajici' AS un, 'Rozsah: všichni kdo vidí/slyší. Komponent: H. Každý cíl, který neuspěje proti pasti, v dosahu kouzla se bude soustředit na barda příští směnu. Past -6- Int pozornost/nic. Pro všechny bude velice těžké odtrhnout od barda oči, či se věnovat něčemu jinému.' AS pop
  UNION ALL SELECT 'Odvrácení pozornosti' AS nazev, NULL AS uroven, '5 magů' AS mag, '15 sáhů' AS dos, '1 kolo' AS sesl, 'Ihned' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 cíl. Komponent: H. Každý cíl, který neuspěje proti pasti, v dosahu kouzla se bude soustředit na cíl, který bard určil, příští směnu. Past -6- Int pozornost/nic. Pro všechny bude velice těžké odtrhnout od cíle oči, či se věnovat něčemu jinému.' AS pop
  UNION ALL SELECT 'Panova melodie' AS nazev, NULL AS uroven, '4 magy' AS mag, 'doslech' AS dos, '1 kolo' AS sesl, '3 kola' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 cíl. Komponent: H+N. Bard láká zvířecí tvory v doslechu. Na jiné cíle nemá kouzlo vliv. Funguje na všechny běžná zvířata až na ryby. V závislosti na vzdálenosti od barda může trvat déle než 3 kola, než k němu zvíře dorazí. Jakmile kouzlo skonči, získá zase svou přirozenou plachost atd. Bard nemůže určit, která zvířata bude lákat.' AS pop
  UNION ALL SELECT 'Steve Dlouhán 1' AS nazev, NULL AS uroven, '4 magy za kolo' AS mag, 'poloměr charizmatu' AS dos, '1 kolo' AS sesl, 'dle dodané magenergie' AS trv, 'vycerpavajici' AS un, 'Rozsah: všichni v oblasti. Komponent: H+N. Všichni v oblasti působení mají dosah svých zbraní TvT zvětšený o 1. Střelné zbraně pak o 3 sáhy ve všech dostřelech. Na dosah kouzel seslaných v oblasti nemá vliv.' AS pop
  UNION ALL SELECT 'Leeroy jenkins 2' AS nazev, NULL AS uroven, '4 magy za cíl' AS mag, 'poloměr charizmatu' AS dos, '1 kolo' AS sesl, '1 útok s rozběhem' AS trv, 'vycerpavajici' AS un, 'Rozsah: všechny vybrané cíle. Komponent: H+N+T. Působení: musí umět Steve Dlouhán 1. Bard se s prastarým pokřikem Leeeeeroy Jenkins vrhne kupředu a inspiruje tak díky magii svoje okolí. Všichni pod vlivem kouzla mají na následující 1 útok s rozběhem +4 Úč. Kouzlo trvá dokud nedojde k útoku s rozeběhem nebo sprintem. Kouzlo nemá vliv na cíle co jsou na jezdeckých či leteckých tvorech. Bonus za rozběh nebo sprint se sčítá s efektem kouzla.' AS pop
  UNION ALL SELECT 'Ochrana múz' AS nazev, NULL AS uroven, '5 magů za cíl' AS mag, 'poloměr charizmatu' AS dos, '1 kolo' AS sesl, '5 kol' AS trv, 'vycerpavajici' AS un, 'Rozsah: všechny vybrané cíle. Komponent: H. Bard povolá ochrannou magii na vybrané cíle. Vybere jeden druh zranění (bodné, sečné, magie, pád apod.) Po dobu trvání kouzla bude cíl chráněn proti tomuto zranění v hodnotě, 1k6. Pokud by došlo ke zranění, hodí se ještě 1k6 a to se odečte od případného zranění. Může během jednoho seslání vybrat různé druhy zranění pro různé cíle. Vždy ale pouze jeden pro jeden cíl.' AS pop
  UNION ALL SELECT 'Oživení nástroje' AS nazev, NULL AS uroven, '2 magy za kolo' AS mag, 'dotyk' AS dos, '1 kolo' AS sesl, 'ihned' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 hudební nástroj. Komponent: N. Bard magicky rozezní hudební nástroj. Tento bude hrát sám od sebe co mu bard přikáže. Lze takto mít neustále aktivní komponent nástroje, ale zároveň mít volné ruce. Změna písně vyžaduje 1 akci od barda. Nástroj může zůstat zavěšený na bardovi a stejně bude hrát stejně, jako by na něj hrál on sám.' AS pop
  UNION ALL SELECT 'Hromový hlas' AS nazev, NULL AS uroven, '10 magů' AS mag, 'doslech' AS dos, '2 kola' AS sesl, 'ihned' AS trv, 'vycerpavajici' AS un, 'Rozsah: směr. Komponent: H. Bard se zhluboka nadechne a vykřikne s hlasitostí hromobití. Může tak předat zprávy na velké vzdálenosti. Pokud jsou vhodné podmínky, měl by být jasně slyšet na cca 2 kilometry. Pokud kouzlo použije v boji, všichni v dosahu charizmatu a ve výseči 120° získají zranění 2k6 hlasitým zvukem. Postavy s citlivým sluchem mohou být ochromeny.' AS pop
  UNION ALL SELECT 'Stěna zvuku' AS nazev, NULL AS uroven, '8 magů' AS mag, '5 sáhů' AS dos, '2 kola' AS sesl, '1 hodina' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 stěna. Komponent: H+N. V dosahu kouzla se vytvoří neviditelná stěna, která je jinak dokonale neviditelná. Pouze pro postavy s infrasluchem bude vypadat jako pevná překážka. Všichni, kteří se chtějí dostat skrz stěnu si musí hodit na Past Roz. Char -5- Int.Odol. Zranění/nic. Ti kteří neuspějí v hodu proti pasti jsou zranění za 1k6 životů a je jim znemožněno projít dál. Ti kteří uspějí mohou bez velkých problémů pokračovat skrz. (Nejasné: past „Roz. Char -5- Int.Odol. Zranění/nic“ kombinuje více vlastností nestandardním zápisem, přesný význam není z textu jasný.) Pokud by se postava pohybovala velkou rychlostí, hází si na past stejně a je případně navíc zraněna, jako by narazila do pevné překážky v případě neúspěchu. Zeď může být volně v prostoru a libovolně tvarovaná, ale maximální prostor, který na jedno zakouzlení pokryje je 20 sáhů čtverečních.' AS pop
  UNION ALL SELECT 'Píseň osudu' AS nazev, NULL AS uroven, '10 magů' AS mag, '20 sáhů' AS dos, 'ihned' AS sesl, 'ihned' AS trv, NULL AS un, 'Rozsah: 1 spojenec. Komponent: H. Bard může jednou za celé kolo vložit 1 další kostku svému spojenci či protivníkovi. Hodnota kostky je 1k10. Bard určuje jestli její hodnota bude pozitivní či negativní. Bard i určuje jestli kostka bude aktivní pro útok či obranu cíle. Nelze použít na hody proti pasti. Hodnota kostky se přičítá/odečítá jako poslední. Lze takto získat záporný útok. Pokud k tomu dojde, cíl zraní sám sebe za výši záporné hodnoty. Draci, džinové, démoni, andělé, konstrukty a elementálové jsou imunní.' AS pop
  UNION ALL SELECT 'Velkolepá show' AS nazev, 9 AS uroven, '10/20 magů' AS mag, '0' AS dos, '2 kola' AS sesl, '1 hodina' AS trv, 'vycerpavajici' AS un, 'Rozsah: sesilatel. Komponent: H+N+T. Jedná se o částečně iluzorní druh kouzla. Jeho přesná podoba se různí podle bardova přání. Během trvání kouzla si může bard počítat k útoku TvT, nebo střeleckému svůj modifikátor za charizma na místo síly, nebo obratnosti. Pokud zaplatí dvojnásobek magů k seslání, bonus za charizma přičítá k Síle nebo Obratnosti. Mimo boj má toto kouzlo efekt, že veškeré hody na past týkající se bardského umění mají +1, nebo +2 když zaplatí 20 magů.' AS pop
  UNION ALL SELECT 'Hromada' AS nazev, NULL AS uroven, '8 magů' AS mag, '20 sáhů' AS dos, '1 kolo' AS sesl, 'ihned' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 cíl. Komponent: T. Bard vytvoří v ruce magickou verzi fekálií či čehokoliv nechutného co uzná za vhodné. Toto vrhne na svůj cíl. Ten si hází na Past Obr -8- efekt/nic. Pokud cíl neuspěje v hodu proti pasti, je zraněn magií za 1k10 životů a příští směnu klesá jeho bonus za charizma a inteligenci o 2.' AS pop
  UNION ALL SELECT 'Císařovy šaty' AS nazev, NULL AS uroven, '6 magů' AS mag, 'dotyk' AS dos, '1 kolo' AS sesl, '10 hodin' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 cíl. Komponent: H. Bard vytvoří iluzorní oděv na sobě či na cíl. Tento může mít jakoukoliv podobu, jakou bard uzná za vhodné. Osoby, které přijdou s takto oděnou osobou do styku si hází na Past Char-5- Int efekt/nic. Pokud neuspějí v hodu proti pasti, věří tomu co vidí. Šaty neposkytují jiné benefity než vizuální. Neochrání před zimou či horkem apod. Lze zakouzlit přes již existující oděvy či zbroje. Pokud je kouzlo sesláno na osobu, která je nahá, či v obyčejných šatech, zvýší se její Oč o 1. Ale pouze proti protivníkům, kteří neprohlédli iluzi.' AS pop
  UNION ALL SELECT 'Nespokojené publikum' AS nazev, NULL AS uroven, '16 magů' AS mag, '15 sáhů' AS dos, '1 kolo' AS sesl, 'ihned' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 cíl. Komponent: H+N+T. Cíl který bard vybral se stane terčem bučení nespokojeného publika a je zasypán magickou zeleninou, kameny apod. Cíl je zraněn za 3k10+10 životů.' AS pop
  UNION ALL SELECT 'Až do dna' AS nazev, NULL AS uroven, '2 magy' AS mag, 'dotyk' AS dos, 'ihned' AS sesl, 'ihned' AS trv, NULL AS un, 'Rozsah: 1 nápoj. Komponent: T. Bard vytvoří magickou iluzi nápoje. Tento naplní nádobu jeho volby do maximálního objemu 1 litru. Tato bude mít stejnou podobu i chuť a vůni, jako jím zvolený nápoj. Tento ovšem nezpůsobuje opilost a do směny od zakouzlení se rozplyne. Bardi tento trik využívají, když nechtějí odmítat panáky, nebo si chtějí někoho naklonit. Je zde malá šance, že si cíl všimne, že je něco v nepořádku, když takový nápoj od barda obdrží.' AS pop
  UNION ALL SELECT 'Dokonalý sluch' AS nazev, NULL AS uroven, '1 mag' AS mag, '20 sáhů' AS dos, '1 kolo' AS sesl, '1 směna' AS trv, 'vycerpavajici' AS un, 'Rozsah: bard. Komponent: H. Bard si magicky zlepší sluch a získá schopnost infra sluchu na 20 sáhů, jako by byl rozený kroll.Pokud je bardem postava, která již infra sluch ovládá, jeho přirozený infra sluch se zlepší. Uslyší dvakrát tak daleko a s lepšími detaily.' AS pop
  UNION ALL SELECT 'Pohrdavý pohled' AS nazev, NULL AS uroven, '1 mag' AS mag, '10 sáhů' AS dos, '1 kolo' AS sesl, '1 směna' AS trv, 'vycerpavajici' AS un, 'Rozsah: všechny cíle v kontaktu s bardem. Bard si občas přeje, aby vypadal jako aristokrat a umí to dát najevo. Stráže se mnohdy raději vyhnou otázkám na jeho osobu, když vidí jeho tvář. Lze použít i jako prvek záměrné provokace. Záleží na okolnostech.' AS pop
  UNION ALL SELECT 'Rozhárané city' AS nazev, NULL AS uroven, '4 magy' AS mag, '5 sáhů' AS dos, '1 směna' AS sesl, '1 směna' AS trv, 'nevycerpavajici' AS un, 'Rozsah: 1 cíl. Komponent: H. Četnost: 1 denně na stejný cíl. Bard vede s cílem rozhovor. Dle povahy rozhovoru může snáz cíl přesvědčit, vyvolat v něm paniku, nejistotu apod. Ale může se tak i pokusit probudit v cíli city vůči sobě, nebo někomu jinému. Cíl si hází na past -7- Int efekt/nic. Pokud kouzlo selže, cíl si není vědom této manipulace. K tomuto může dojít až po opakovaných selháních.' AS pop
  UNION ALL SELECT 'Kapitán' AS nazev, NULL AS uroven, '6 magů' AS mag, 'dotyk' AS dos, '2 kola' AS sesl, '1 hodina' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 souhlasící cíl. Četnost: 1 denně na stejný cíl. Bard s trochou magie vytvoří iluzi, že cíl naprosto přesně ví co dělá. Cíl si pak může počítat Char jakožto atribut užívaný k hodům na danou dovednost. Mnohem snáz tak přesvědčí své okolí, že třeba přesně ví, jak se ovládá loď apod. Bude působit jistě, důvěryhodně a sebevědomě. Dle okolností, pokud i tak selže, bude se zdát, že to nebylo jeho zaviněním.' AS pop
  UNION ALL SELECT 'Bardí sounáležitost' AS nazev, NULL AS uroven, '0 magů' AS mag, 'dotyk' AS dos, '1 kolo' AS sesl, 'ihned' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 tulácké povolání. Četnost: 1 denně na stejný cíl. Bardi jsou častokrát soky, ale i oni dokážou táhnout za jeden provaz. Bard je tímto kouzlem schopen přesunout tolik magenergie do, nebo z cíle, jako je součet jejich úrovní. Pokud přesune více magenergie než má cíl kapacitu, tato se rozplyne. Bard nezná úroveň cíle, pokud mu ji někdo neřekne.' AS pop
  UNION ALL SELECT 'Kyselá slova' AS nazev, NULL AS uroven, '2 magy' AS mag, '6 sáhů' AS dos, 'ihned - 1 bod únavy' AS sesl, 'ihned' AS trv, NULL AS un, 'Rozsah: 1 zbraň/kouzlo. Komponent: H. Četnost: 1 za celé kolo. Bard vloží do příštího útoku zášť a doslovnou kyselost slov. Tyto se magicky změní na kyselinu a při úspěšném zásahu zraní cíl za dalších 1k6+2 životů. Lze použít na útoky TvT, střelbu i kouzla.' AS pop
  UNION ALL SELECT 'Hvězdná sláva' AS nazev, NULL AS uroven, '5 magů' AS mag, '12 sáhů' AS dos, '1 kolo' AS sesl, 'ihned' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 cíl. Komponent: N. Bard zhmotní pomíjivou slávu a vloží ji na předmět či osobu. Tato se bude po dobu trvání kouzla třpytit a slabě zářit. Tento efekt na cíli vydrží 24 hodin, nebo pokud na něj někdo nesešle zlom kouzlo.' AS pop
  UNION ALL SELECT 'Deptající pochybnosti' AS nazev, NULL AS uroven, '4 magy za kolo' AS mag, 'poloměr charizmatu' AS dos, '1 kolo' AS sesl, 'ihned' AS trv, 'vycerpavajici' AS un, 'Rozsah: všechny cíle v dosahu. Komponent: H. Bard potichu šeptá podmanivá slova, která cíl nečekaně zasáhnou. Cíl nemusí obsahu slov rozumnět. Každý kdo se nachází v oblasti působení na začátku kola získá 1k4 bodů psychického zranění. Nebo když do této oblasti vstoupí. V jednom kole může být cíl zraněn tímto způsobem pouze jednou i kdyby se překrývalo více bardů se stejným kouzlem.' AS pop
  UNION ALL SELECT 'Malá smrt' AS nazev, NULL AS uroven, '12 magů' AS mag, '20 sáhů' AS dos, '2 kola' AS sesl, 'ihned' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 cíl. Komponent: H. Bard se tímto kouzlem pokusí přesvědčit cíl, že mu hrozí bezprostřední smrt. Tento se pak stáhne, uteče, nebo se bude snažit jednat adekvátně k okolnostem. Cíl si hází na Past -7- Int efekt/nic. Pokud je cílem kouzla bojovník, může to u něj spustit efekt berserka bez ohledu na jeho současné životy, nebo další okolnosti.' AS pop
  UNION ALL SELECT 'Závoj lží' AS nazev, NULL AS uroven, '8 magů' AS mag, 'dotyk' AS dos, '1 směna' AS sesl, '2 hodiny' AS trv, 'nevycerpavajici' AS un, 'Rozsah: 1 cíl. Komponent: H. Cíl pod efektem kouzla se změní k nepoznání. Je možno tak změnit pohlaví, velikost, hlas a veškeré fyzické aspekty postavy. Nezmění to ovšem její oblečení. Jedná se o iluze. Šance že někdo prohlédne iluzi je Past -7- Int efekt/nic. Postava která se změní o velikost ovšem ve skutečnosti zůstane stejně vysoká, musí si tedy dávat velký pozor, aby se vešla, jinak je vysoká šance, že bude kouzlo odhaleno. Kouzlo také neposkytuje bonusy nebo postihy v závislosti na velikosti, protože ta je ve skutečnosti stále stejná.' AS pop
  UNION ALL SELECT 'Ovlivni sluch' AS nazev, NULL AS uroven, '5 magů' AS mag, '13 sáhů' AS dos, '1 kolo' AS sesl, '1 směna' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 cíl. Komponent: H. Bard magicky pokřiví sluch cíle, aby slyšel nesmysly nebo vůbec nic. Cíl si hází na Past Roz -6- Int efekt/nic. Cíl který neuspěl v hodu proti pasti bude mít vyřazený sluch dle přání barda. Bard ovšem nemůže přesně vybrat co cíl uslyší. Dle okolností si cíl nemusí být vědom, že byl cílem tohoto kouzla.' AS pop
  UNION ALL SELECT 'Pán loutek' AS nazev, NULL AS uroven, '25 magů' AS mag, '15 sáhů' AS dos, '1 kolo' AS sesl, '2 kola' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 cíl. Komponent: H+N. Toto kouzlo bardi před veřejností tají. Mají ovšem schopnost krátkodobě a násilně přivést mrtvého znovu k životu. Tento ovšem je jen stínem svého původního já. Nejedná se o skutečné oživení, ale bardova magie jej využije jako loutku na krátkou dobu. Takto oživený cíl má všechny dovednosti a schopnosti jako měl za života, ale pouze na dvě kola. Poslechne rozkaz barda byť by byl sebešílenější. Takto ´´oživení´´ po skončení kouzla zase padnou na zem mrtvi a není je možné takto oživit. Lze použít pouze na cíle, které nejsou mrtvi déle jak hodinu. Pokud je takto ovládaná postava s magenergii, může nakládat pouze s magy v předmětech které má k dispozici. (Její vlastní se rozplyne v okamžiku smrti)' AS pop
  UNION ALL SELECT 'Drill seržant' AS nazev, NULL AS uroven, '8 magů' AS mag, 'dotyk' AS dos, '1 kolo' AS sesl, 'stále' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 cíl. Komponent: H. Četnost: 1 denně na stejný cíl. Bard z plných plic zařve na vybraný cíl a začne s ním cloumat. Aby mělo kouzlo účinek, musí být v důsledku zranění vyřazený. Cíl je po skončení kouzla vyléčen za 1k10 životů + bonus za charizma barda.' AS pop
  UNION ALL SELECT 'Rozechvěj' AS nazev, NULL AS uroven, '8 magů' AS mag, '40 sáhů' AS dos, '1 směna' AS sesl, 'stále' AS trv, 'nevycerpavajici' AS un, 'Rozsah: 1 cíl. Komponent: H. Bard začne vyluzovat hluboké tóny, dokud nenajde správnou frekvenci pod kterou cílený objekt rezonuje. Podmínkou je, že bard musí na cíl vidět a nesmí od něj být dál jak 40 sáhů. Dle povahu předmětu a snahy barda může nastat několik efektů. Cíl praskne - například váza. Páka mechanizmu se pohne, kamení se sesune apod. O přesných parametrech a případných efektech vzhledem k okolnostem rozhoduje PJ. Mezi cílem a bardem by neměla být žádná překážka. Lze seslat pouze na neživé předměty.' AS pop
  UNION ALL SELECT 'Poběž! 1' AS nazev, NULL AS uroven, '7 magů' AS mag, '20 sáhů' AS dos, '1 kolo' AS sesl, 'ihned' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 spojenec. Komponent: H+N. Bard zahraje melodií, která umožní cíli jeden okamžitý přesun, Ale pouze přesun. Směr přesunu určuje cíl. Tento efekt na jednom cíli může nastat maximálně 1 za celé kolo.' AS pop
  UNION ALL SELECT 'Pauza 2' AS nazev, NULL AS uroven, '3 magy' AS mag, '12 sáhů' AS dos, 'ihned' AS sesl, 'stále' AS trv, NULL AS un, 'Rozsah: 1 cíl. Komponent: H. Působení: Musí umět Poběž! 1. Četnost: 1 za celé kolo. Bard se může rozhodnou půjčit svůj čas jiným. Po seslání kouzla dá vybranému cíli 1 svou akci. Tuto akci má cíl k dispozici až se dostane na řadu, nebo na konci kola. Akci pak může využít libovolně, nebo si ji schovat do dalšího kola. Pauza se sčítá se schováním akce, tedy až +6 k ini do dalšího kola.' AS pop
  UNION ALL SELECT 'Falešná čepel' AS nazev, NULL AS uroven, '6 magů' AS mag, '15 sáhů' AS dos, '1 akce' AS sesl, 'stále' AS trv, NULL AS un, 'Rozsah: 1 cíl. Komponent: H/T. Četnost: 1 za celé kolo. Může seslat i když není na řadě, ale musí mít k dispozici akci. Lze seslat pouze předtím, než se hráč dozví hodnoty hodu na útok a obranu. Po zakouzlení se jeden z vybraných útoků TvT změní na stínové zranění.' AS pop
  UNION ALL SELECT 'Najdi hospodu' AS nazev, NULL AS uroven, '1 mag' AS mag, '1 míle' AS dos, '1 kolo' AS sesl, 'stále' AS trv, 'vycerpavajici' AS un, 'Rozsah: všechny hospody v dosahu. Komponent: H/N/T. Bardův magii posílený 6. Smysl pro hledání míst, kde by mohl uplatnit svoje umění mu odhalí všechny hospody v dosahu. Hospodou se myslí jakýkoliv veřejný podnik, který nabízí ubytování, nebo stravu za úplatu. Bude fungovat na neoficiální podniky, či hráčská doupata apod.' AS pop
  UNION ALL SELECT 'Odrhovačka' AS nazev, NULL AS uroven, '3 magy za cíl' AS mag, '2 sáhy' AS dos, '1 kolo' AS sesl, '6 hodin' AS trv, 'vycerpavajici' AS un, 'Rozsah: všechny souhlasící cíle. Komponent: H/N. Všichni pod vlivem kouzla budou v hlavě neustále slyšet otravnou odrhovačku, kterou si budou muset neustále broukat. Všechny snahy o nepovolené čtení za pomocí telepatie, nebo snahy o hypnózu a všechny kouzla ovlivňující podvědomí a mysl cíle, mají o 1 nižší past. Které další dovednosti či kouzla to ovlivní rozhoduje PJ.' AS pop
  UNION ALL SELECT 'Uklidni pošuka' AS nazev, NULL AS uroven, '1 mag za cíl' AS mag, '15 sáhů' AS dos, '1 směna' AS sesl, '8 hodin' AS trv, 'nevycerpavajici' AS un, 'Rozsah: Všechny cíle na doslech ochotny poslouchat, cca 50 max. Komponent: H. Rozrušený fanoušek, který neodbytně škemrá o tvůj podpis? Faninka, která se ti v nevhodnou chvíli vrhá k nohám a žadoní aby ses jí zmocnil? Všechny a podobné cíle trpí duševní nerovnováhou. Toto kouzlo a trocha času umožní bardovi uklidnit cíl, aby se zase vrátil k racionálnímu jednání. Funguje na všechny cíle, které jsou ještě aspoň trochu ochotny jednat. O přesném rozsahu a fungování kouzla rozhoduje PJ dle okolností a motivací k rozrušení.' AS pop
  UNION ALL SELECT 'Zvuková bublina' AS nazev, NULL AS uroven, '6 magů' AS mag, 'poloměr charizmatu' AS dos, '2 kola' AS sesl, '1 hodina' AS trv, 'vycerpavajici' AS un, 'Rozsah: Všechny zvuky v oblasti kouzla. Komponent: H/N. Bard vytvoří oblast ze které neunikne žádný zvuk. Tato oblast zůstane na místě, kde ji bard zakouzlil. Zvuky neproniknou ani dovnitř zvenčí.' AS pop
  UNION ALL SELECT 'Živé lano' AS nazev, NULL AS uroven, '2 magy' AS mag, 'dotyk' AS dos, '2 kola' AS sesl, '1 hodina' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 provaz. Komponent: H/N. Bardi se občas museli vypořádávat s výškovými překážkami, aby mohli dál provozovat své slavné umění. Tímto kouzlem bard očaruje jeden vybraný provaz, jedno jak dlouhý a přikáže, aby se někde přivázal. Tento se sám začne plazit vybraným směrem. Kvalita uvázání samotného provazu se odvíjí od bardova zacházení s provazy a lany. Lano se samo pohybuje rychlostí 1 sáh za kolo tam, kam mu bard přikázal. Během pohybu jej nesmí nic zatěžovat, dokud není uvázané, jinak se kouzlo zruší. Lano se umí pohybovat pouze po pevné zemi, nebo zdech, nikoliv stropech. Je takto možné přikázat lanu aby se i odvázalo.' AS pop
  UNION ALL SELECT 'Barbarská etiketa' AS nazev, NULL AS uroven, '4 magy' AS mag, 'dotyk' AS dos, '1 kolo' AS sesl, '4 hodiny' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 cíl. Komponent: H/T. Bard souhlasícímu cíli prohodí atributy po dobu trvání kouzla. Sílu prohodí s inteligencí a Odolnost prohodí s charizmatem. Postava si jinak pamatuje a může dělat, jako by na ní kouzlo nebylo.' AS pop
  UNION ALL SELECT 'Opuštění scény' AS nazev, NULL AS uroven, '8 magů' AS mag, '0' AS dos, '1 kolo' AS sesl, 'ihned' AS trv, 'vycerpavajici' AS un, 'Rozsah: bard. Komponent: H. Četnost: 1 za 5 kol. Bardi jsou občas nuceni kvapně změnit scénu svého působení. Po zakouzlení je bard magicky vržen až do vzdálenosti 8 sáhů a výšky 4 sáhů. Přistání má Past Obr -6- přistání/pád. Při neúspěšném hodu proti pasti není zraněn, pouze sražen.' AS pop
  UNION ALL SELECT 'Živá voda' AS nazev, NULL AS uroven, '10 magů' AS mag, 'dotyk' AS dos, '4 kola' AS sesl, '1 hodina' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 nápoj. Jakákoliv pitelná tekutina - takže i jed se změní v lék po dobu trvání kouzla, po skončení kouzla se mu vrátí všechny normální vlastnosti. Ten kdo nápoj vypije je vyléčen za 1k4+3 životů. Toto léčení je magické. Jedna osoba může za den vypít pouze 1 takovýto nápoj.' AS pop
  UNION ALL SELECT 'Kecka' AS nazev, NULL AS uroven, '5 magů za cíl' AS mag, 'dotyk' AS dos, '1 kolo' AS sesl, '6 hodin' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 cíl. Komponent: H. Každý cíl na který je toto kouzlo sesláno, získá schopnost slyšet a předávat zprávy ostatním s od ostatních, kteří jsou pod vlivem stejného kouzla a v dosahu. Dosah kouzla je 40 sáhů a není zkracováno překážkami. Výjimku mohou tvořit některé magické bariéry. Aby bylo kouzlo aktivní, ten který chce mluvit, se musí dotýkat ucha.' AS pop
  UNION ALL SELECT 'Zvukový výboj' AS nazev, 16 AS uroven, '13 magů' AS mag, '15 sáhů' AS dos, '1 kolo' AS sesl, 'ihned' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 cíl. Bard zhmotní malý výboj čistě akustické energie. Cíl musí bard v době seslání vidět. Výboj se protáhne se i malými škvírami, jako například klíčovou dírkou. Každý tvor, nebo předmět, který stojí v cestě je zraněn za 1k4 životů. Samotný cíl se pak ocitne v oblasti akustické exploze a je zraněn za 1k10+5 životů. Všechny jiné cíle či předměty v okolí 3 sáhů od dopadu, jsou pak zraněny za polovinu hodnoty. (věci jako sklo, papír, slabá kůže apod. budou kouzlem poškozeny/zničeny, podle konečné síly výboje - (rozhoduje PJ)' AS pop
  UNION ALL SELECT 'Záštiplná múza' AS nazev, 16 AS uroven, '12 magů' AS mag, '15 sáhů' AS dos, '1 kolo' AS sesl, '1 kolo' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 cíl. Cíl si bude připadat méněceně a neohrabaně.. Pokud hází na past, odečtě od hodnoty hodu 1k4. Pokud hází na útok či obranu, odečte 1k6 od finální hodnoty. Pokud padne 6, hází znovu. Když se teoreticky prohází do záporných čísel, zraní sám sebe za záporný rozdíl. Nemůže se takto zabít, ale vyřadit ano. Pokud sesílá kouzlo hází na seslání znovu a počítá se ten horší výsledek.' AS pop
) v
JOIN seznamy_kouzel s ON s.nazev = 'Kouzla barda'
JOIN povolani p ON p.id = s.povolani_id AND p.nazev = 'Bard';
