-- Kouzla pamětníka / Pamětník (81 kouzel)
INSERT INTO kouzla (nazev, seznam_kouzel_id, uroven_kouzla, cena_magenergie, dosah, doba_seslani, doba_trvani, typ_unavy, popis)
SELECT v.nazev, s.id, v.uroven, v.mag, v.dos, v.sesl, v.trv, v.un, v.pop
FROM (
  SELECT 'Věčná sláva' AS nazev, NULL AS uroven, 'veškerá současná, nejméně 1' AS mag, '1 sáh' AS dos, '1 směna' AS sesl, 'ihned' AS trv, 'nevycerpavajici' AS un, 'Rozsah: 1 padlý trollobíjec. Finální kapitola v životě každého trollobíjce, který zemřel hrdinskou smrtí. Tímto kouzlem pamětník zapíše do své knihy a do historie, na věky věků, vzpomínku na jeho činy a hlavně jeho smrt. (pamětník si schová deník padlé postavy)' AS pop
  UNION ALL SELECT 'Slovo síly I' AS nazev, NULL AS uroven, '2 magy' AS mag, '7 sáhů' AS dos, '1 kolo' AS sesl, '1 směna' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 cíl. Cíl pod vlivem kouzla získá +1 ke stupni síly včetně bonusů, které z toho plynou. Lze navýšit nad 21+5.' AS pop
  UNION ALL SELECT 'Slovo síly II' AS nazev, NULL AS uroven, '4 magy' AS mag, '6 sáhů' AS dos, '1 kolo' AS sesl, '1 směna' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 cíl. Cíl pod vlivem kouzla získá +2 ke stupni síly včetně bonusů, které z toho plynou. Lze navýšit nad 21+5.' AS pop
  UNION ALL SELECT 'Slovo síly III' AS nazev, NULL AS uroven, '6 magů' AS mag, '5 sáhů' AS dos, '1 kolo' AS sesl, '1 směna' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 cíl. Cíl pod vlivem kouzla získá +3 ke stupni síly včetně bonusů, které z toho plynou. Lze navýšit nad 21+5.' AS pop
  UNION ALL SELECT 'Slovo síly IV' AS nazev, NULL AS uroven, '8 magů' AS mag, '5 sáhů' AS dos, '1 kolo' AS sesl, '1 směna' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 cíl. Cíl pod vlivem kouzla získá +4 ke stupni síly včetně bonusů, které z toho plynou. Lze navýšit nad 21+5.' AS pop
  UNION ALL SELECT 'Slovo ochrany I' AS nazev, NULL AS uroven, '4 magy' AS mag, '5 sáhů' AS dos, '1 kolo' AS sesl, '1 směna' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 cíl. Cíl pod vlivem kouzla získá ochranný štít v hodnotě 15 % maximálních životů cíle. Tento štít pohltí veškeré zdroje zranění a ubývá jako první.' AS pop
  UNION ALL SELECT 'Slovo ochrany II' AS nazev, NULL AS uroven, '6 magů' AS mag, '6 sáhů' AS dos, '1 kolo' AS sesl, '1 směna' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 cíl. Cíl pod vlivem kouzla získá ochranný štít v hodnotě 20 % maximálních životů cíle. Tento štít pohltí veškeré zdroje zranění a ubývá jako první.' AS pop
  UNION ALL SELECT 'Slovo ochrany III' AS nazev, NULL AS uroven, '8 magů' AS mag, '7 sáhů' AS dos, '1 kolo' AS sesl, '1 směna' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 cíl. Cíl pod vlivem kouzla získá ochranný štít v hodnotě 25 % maximálních životů cíle. Tento štít pohltí veškeré zdroje zranění a ubývá jako první.' AS pop
  UNION ALL SELECT 'Slovo rychlosti I' AS nazev, NULL AS uroven, '2 magy' AS mag, '7 sáhů' AS dos, '1 kolo' AS sesl, '1 směna' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 cíl. Cíl pod vlivem kouzla získá +1 ke stupni obratnosti včetně bonusů, které z toho plynou. Lze navýšit nad 21+5.' AS pop
  UNION ALL SELECT 'Slovo rychlosti II' AS nazev, NULL AS uroven, '4 magů' AS mag, '6 sáhů' AS dos, '1 kolo' AS sesl, '1 směna' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 cíl. Cíl pod vlivem kouzla získá +2 ke stupni obratnosti včetně bonusů, které z toho plynou. Lze navýšit nad 21+5.' AS pop
  UNION ALL SELECT 'Slovo rychlosti III' AS nazev, NULL AS uroven, '6 magů' AS mag, '5 sáhů' AS dos, '1 kolo' AS sesl, '1 směna' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 cíl. Cíl pod vlivem kouzla získá +3 ke stupni obratnosti včetně bonusů, které z toho plynou. Lze navýšit nad 21+5.' AS pop
  UNION ALL SELECT 'Slovo rychlosti IV' AS nazev, NULL AS uroven, '8 magů' AS mag, '5 sáhů' AS dos, '1 kolo' AS sesl, '1 směna' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 cíl. Cíl pod vlivem kouzla získá +4 ke stupni obratnosti včetně bonusů, které z toho plynou. Lze navýšit nad 21+5.' AS pop
  UNION ALL SELECT 'Píseň chrabrosti' AS nazev, NULL AS uroven, '5 magů' AS mag, '10 sáhů v průměru okolo pamětníka' AS dos, '3 kola' AS sesl, '2 hodiny' AS trv, 'vycerpavajici' AS un, 'Rozsah: všichni v ovlivněné oblasti. Všichni v ovlivněné oblasti jsou povzbuzeni pamětníkovou písní a po dobu trvání kouzla nezískávají další únavu. Platí pro zdroje únavy kterými jsou běžné fyzické či duševní aktivity. Únava plynoucí přímo z kouzlení či jako vedlejší/hlavní efekt kouzel, pak bude poloviční.' AS pop
  UNION ALL SELECT 'Zasloužený odpočinek' AS nazev, NULL AS uroven, '10 magů za směnu' AS mag, 'pamětník' AS dos, '1-3 směny' AS sesl, 'ihned' AS trv, 'nevycerpavajici' AS un, 'Rozsah: 8 sáhů v průměru. Působení: umí píseň chrabrosti. Pamětník pomalu předříkává posvátné texty o klidu, odpočinku a pokoji. Síla jeho slov se projeví vyléčením osob v ovlivněné oblasti za 1k6+4 životů za každou směnu trvání.' AS pop
  UNION ALL SELECT 'Sevření' AS nazev, NULL AS uroven, '2 magy' AS mag, '10 sáhů' AS dos, '1 kolo' AS sesl, 'ihned' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 cíl. Četnost: na jeden cíl 1 za 3 kola. Cíl je krátce, ale prudce sevřen svou vlastní zbrojí. Cíl je zraněn za svoje KZ. Kouzlo nefunguje na cíle beze zbroje, nebo na cíle jejichž zbroj je jejich součástí - ryby a jejich šupiny apod. V případě nejasností rozhoduje PJ.' AS pop
  UNION ALL SELECT 'Síla hlasu' AS nazev, NULL AS uroven, 'dle dodané magenergie' AS mag, '4 sáhy' AS dos, '2 kola' AS sesl, 'ihned' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 dveře. Pamětník silou svého hlasu může rozrazit dveře, které mohou být teoreticky vyraženy. Musí to být dveře v pravém slova smyslu tzn. žádné kamenné posuvné desky apod. Za každá čtverečný sáh musí pamětník vložit 2 magy. Šance že dveře nevydrží a otevřou se, je 60 %.' AS pop
  UNION ALL SELECT 'Verš kamene I' AS nazev, NULL AS uroven, '4 magy' AS mag, '1 sáh' AS dos, '1 kolo' AS sesl, 'ihned' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 hex. Pamětník před sebou nechá vyrůst zem, aby mu poskytla krytí. Tento úkryt zabírá 1 hex a je vysoký jako pamětník sám. Z hlediska ochrany proti střelám se počítá jako +6 pro samotného pamětníka. Pro kohokoliv jiného, stejně vysokého to je +3. Na hexu nesmí nic stát, žádná bytost, zeď apod. Toto krytí se samo po 3 dnech rozpadne.' AS pop
  UNION ALL SELECT 'Verš kamene II' AS nazev, NULL AS uroven, '7 magů' AS mag, '1 sáh' AS dos, '1 kolo' AS sesl, 'ihned' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 hex. Pamětník před sebou nechá vyrůst zem, aby mu poskytla krytí. Tento úkryt zabírá 3 hexy před pamětníkem a je vysoký jako pamětník sám. Z hlediska ochrany proti střelám se počítá jako +6 pro samotného pamětníka. Pro kohokoliv jiného, stejně vysokého to je +3. Na hexu nesmí nic stát, žádná bytost, zeď apod. Toto krytí se samo po 3 dnech rozpadne.' AS pop
  UNION ALL SELECT 'Verš kamene III' AS nazev, NULL AS uroven, '10 magů' AS mag, '1 sáh' AS dos, '1 kolo' AS sesl, 'ihned' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 hex. Pamětník před sebou nechá vyrůst zem, aby mu poskytla krytí. Tento úkryt zabírá 5 hexů okolo pamětníka a je vysoký jako pamětník sám. Z hlediska ochrany proti střelám se počítá jako +6 pro samotného pamětníka. Pro kohokoliv jiného, stejně vysokého to je +3. Tato zeď je pokryta ostny. Každá bytost nepřátelská pamětníkovi v blízkosti této zdi je zraněna automaticky za 1 život za každou akci kterou vykoná v blízkosti zdi. Na hexu nesmí nic stát, žádná bytost, zeď apod. Toto krytí se samo po 3 dnech rozpadne.' AS pop
  UNION ALL SELECT 'Verš kamene IV' AS nazev, NULL AS uroven, '5 magů' AS mag, '10 sáhů' AS dos, '1 kolo' AS sesl, '8 hodin' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 spojenec. Cíl je v mžiku pokrytý ochranným prachem z okolí. Pokud je zraněn, způsobené zranění je sníženo o 2 životy ze všech zdrojů.' AS pop
  UNION ALL SELECT 'Zloba kamene' AS nazev, NULL AS uroven, '3 magy' AS mag, '10 sáhů' AS dos, '1 kolo' AS sesl, 'ihned' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 cíl. V dosahu cíle musí být nějaký nerost - jedno jak velký, který exploduje a zraní určený cíl za 1k10+5 životů.' AS pop
  UNION ALL SELECT 'Zuřivost kamene' AS nazev, NULL AS uroven, '7 magů' AS mag, '20 sáhů' AS dos, '1 kolo' AS sesl, 'ihned' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 cíl. V dosahu cíle musí být nějaký nerost - jedno jak velký, který exploduje a zraní určený cíl za 2k10+10 životů.' AS pop
  UNION ALL SELECT 'Kamenná bouře' AS nazev, NULL AS uroven, '13 magů' AS mag, '40 sáhů' AS dos, '2 kola' AS sesl, 'ihned' AS trv, 'vycerpavajici' AS un, 'Rozsah: kruh o průměru 5 sáhů. V dosahu cíle musí být nějaký nerost - jedno jak velký, který exploduje a zraní určený cíl za 1k10+5 životů.' AS pop
  UNION ALL SELECT 'Kamenná zahrada' AS nazev, NULL AS uroven, '15 magů' AS mag, '0' AS dos, '1 akce' AS sesl, 'ihned' AS trv, NULL AS un, 'Rozsah: 1-2 sáhy okolo sesilatele. Působení: musí umět aspoň 4 jiná kamenná kouzla. Četnost: 1 za 5 kol. Pamětník musí stát na pevné zemi, nemusí být nutně skála, hlína stačí. Všechny cíle v okruhu v dosahu 1-2 jsou tímto kouzlem zasaženy. Ze země prudce vyrazí ostré hroty a zraní všechny v dosahu za 2k6+2. Pohyb na těchto hexem automaticky zraní za 1k6 životů za ovlivněný hex. Pokud na nich postava začne kolo, je také zraněna. Ostny se samy rozpadnou po směně.' AS pop
  UNION ALL SELECT 'Houževnatost kamene' AS nazev, NULL AS uroven, '3 magy' AS mag, 'dotyk' AS dos, '1 kolo' AS sesl, '6 hodin' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 cíl. Působení: musí umět aspoň 4 jiná kamenná kouzla. Ovlivněný cíl musí stát na pevné zemi. Cíl pod efektem kouzla je částečně srostlý se zemí. Získá tak +2 při hodu proti sražení, odhození apod. Země jej ale tímto i zatěžuje. Po dobu trvání má naložení vyšší o 50 mincí.' AS pop
  UNION ALL SELECT 'Urputnost kamene' AS nazev, NULL AS uroven, '0' AS mag, '5 sáhů v poloměru' AS dos, 'ihned' AS sesl, 'stále' AS trv, NULL AS un, 'Rozsah: všichni spojenci v dosahu. Působení: musí umět aspoň 8 jiných kamenných kouzel. Pasivní efekt, který je neustále aktivní. Všechny útoky na dálku i TvT v dosahu pamětníka získají bonus +1 k útočnosti.' AS pop
  UNION ALL SELECT 'Verš ohně I' AS nazev, NULL AS uroven, '3 magy za hex' AS mag, '10 sáhů' AS dos, '2 kola' AS sesl, '4 kola' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 hex. Ovlivněná oblast vzplane jasným plamenem. Vše hořlavé uvnitř vzplane s 50 % pravděpodobností. Stojí-li někdo na hexu v době vzplanutí, je zraněn za 1k6+1 životů. Toto zranění se počítá jako zranění od přírodního ohně. Oheň se pak samovolně sám šíří jsou-li v okolí hořlavé materiály.' AS pop
  UNION ALL SELECT 'Verš ohně II' AS nazev, NULL AS uroven, '4 magů za hex' AS mag, '10 sáhů' AS dos, '2 kola' AS sesl, '4 kola' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 hex. Ovlivněná oblast vzplane jasným plamenem. Vše hořlavé uvnitř vzplane s 50 % pravděpodobností. Stojí-li někdo na hexu v době vzplanutí, je zraněn za 2k6+2 životů. Toto zranění se počítá jako zranění od přírodního ohně. Oheň se pak samovolně sám šíří jsou-li v okolí hořlavé materiály.' AS pop
  UNION ALL SELECT 'Verš ohně III' AS nazev, NULL AS uroven, '6 magů za hex' AS mag, '10 sáhů' AS dos, '2 kola' AS sesl, '4 kola' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 hex. Ovlivněná oblast vzplane jasným plamenem. Vše hořlavé uvnitř vzplane s 50 % pravděpodobností. Stojí-li někdo na hexu v době vzplanutí, je zraněn za 3k6+3 životů. Toto zranění se počítá jako zranění od přírodního ohně. Oheň se pak samovolně sám šíří jsou-li v okolí hořlavé materiály.' AS pop
  UNION ALL SELECT 'Žhavý břit' AS nazev, NULL AS uroven, '5 magů za zbraň/kombinaci' AS mag, '15 sáhů' AS dos, '1 kolo' AS sesl, '1 směna' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 zbraň/kombinace. Působení: Musí umět alespoň 3 další ohnivá kouzla. Vybraná zbraň nebo jejich kombinace TvT je okouzlena magickým ohněm. Při úspěšném zásahu způsobí dalších 4 body zranění magickým ohněm. Pro vrhací útoky je bonusové poškození 2. 30 % na vzplanutí.' AS pop
  UNION ALL SELECT 'Strážná hydra' AS nazev, NULL AS uroven, '7 magů' AS mag, '5 sáhů' AS dos, '2 kola' AS sesl, '1 směna' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 cíl. Působení: Musí umět alespoň 4 další ohnivá kouzla. Okolo cíle bude šestihlavá hydra hledící všemi směry. Při vstupu, opuštění nebo začátku kola v oblasti okolo ovlivněné osoby v dosahu 1 je cíl kousnut touto hydrou. Proti jejímu kousnutí chrání pouze mágův štít, není-li řečeno jinak. Zasažený cíl je automaticky zraněn za 5 životů magickým ohněm. Jeden cíl může být zasažen maximálně 1 v rámci jednoho celého kola. I když se hydra kouká všemi směry, nijak nevaruje nositele. Hydra vydává světlo do vzdálenosti 3 sáhů všemi směry.' AS pop
  UNION ALL SELECT 'Plamen života' AS nazev, NULL AS uroven, '0' AS mag, '20 sáhů od pamětníka' AS dos, 'ihned' AS sesl, 'stále' AS trv, NULL AS un, 'Rozsah: všichni spojenci. Působení: Musí umět alespoň 4 další ohnivá kouzla. Pokud je jakýkoliv spojenec v dosahu zasažen smrtelnou ranou. Dříve než spadne, získá jednu okamžitou útočnou akci. Když zasáhne cíl, způsobí dalších 1k10 bodů zranění magickým ohněm.' AS pop
  UNION ALL SELECT 'Dech větru' AS nazev, NULL AS uroven, '2 magy za hex' AS mag, '10 sáhů' AS dos, '1 kolo' AS sesl, 'ihned' AS trv, 'vycerpavajici' AS un, 'Oblast ovlivněná kouzlem kde hoří vzplane s novou silou. Všechny cíle které hoří jsou zraněny za dalších 1k6+2 životů a hoření se prodlouží o 2 kola. Funguje na všechny zdroje ohňů (svíčky, pochodně apod. tyto ihned shoří). Nebo se pamětník může rozhodnout učinit opak a všechny zdroje v této oblasti uhasit.' AS pop
  UNION ALL SELECT 'Ochrana větru' AS nazev, NULL AS uroven, '1 mag za projektil' AS mag, '10 sáhů' AS dos, '2 kola' AS sesl, '1 směna' AS trv, 'vycerpavajici' AS un, 'Cíl se ocitne pod neviditelnou bariérou. Tato snižuje sílu všech fyzických projektilů o 6. Pokud sesilatel již nemá magy, projektil projde beze změny. Pamětník se může rozhodnout nechat projektil projít a nezaplatit za něj magy. Ovšem dříve, než se dozví zda-li zasáhne nebo množství poškození které udělí. Není-li řečeno jinak, vždy projektily brzdí.' AS pop
  UNION ALL SELECT 'Lávová dlaň' AS nazev, NULL AS uroven, '7 magů' AS mag, '20 sáhů' AS dos, '2 kola' AS sesl, 'ihned' AS trv, 'vycerpavajici' AS un, 'Rozsah: 3 sáhy v průměru. Působení: Musí umět alespoň 3 ohnivá a kamenná kouzla. Nad zvolenou oblastí se zhmotní velká ruka tvořená z magmatického kamene. Tato dopadne a zraní všechny v ovlivnění oblasti za 2k10+6 životů. Ovlivněná oblast bude 1 směnu hořet za 1k6.' AS pop
  UNION ALL SELECT 'Lávová pěst' AS nazev, NULL AS uroven, '10 magů' AS mag, '25 sáhů' AS dos, '2 kola' AS sesl, 'ihned' AS trv, 'vycerpavajici' AS un, 'Rozsah: 5 sáhů v průměru. Působení: Musí umět alespoň 4 ohnivá a kamenná kouzla. Nad zvolenou oblastí se zhmotní ohromná ruka tvořená z magmatického kamene. Tato dopadne a zraní všechny v ovlivnění oblasti za 3k10+4 životů. Ovlivněná oblast bude 1 směnu hořet za 1k8.' AS pop
  UNION ALL SELECT 'Titánská pěst' AS nazev, NULL AS uroven, '20 magů' AS mag, '30 sáhů' AS dos, '2 kola' AS sesl, 'ihned' AS trv, 'vycerpavajici' AS un, 'Rozsah: 8 sáhů v průměru. Působení: Musí umět alespoň 5 ohnivých a kamenných kouzel. Nad zvolenou oblastí se zhmotní obří ruka tvořená z magmatického kamene. Tato dopadne a zraní všechny v ovlivnění oblasti za 4k10+2 životů. Ovlivněná oblast bude 1 hodinu hořet za 1k10. Titánská pěst má takovou sílu, že dokáže bořit i pevné stavby. Rozhoduje PJ.' AS pop
  UNION ALL SELECT 'Žalozpěv' AS nazev, NULL AS uroven, '10 magů' AS mag, 'Pamětník' AS dos, '1 kolo, stále' AS sesl, 'stále, nejvýše však hodinu, pak musí zakouzlit…' AS trv, 'vycerpavajici' AS un, 'Doba trvání (přesně): stále, nejvýše však hodinu, pak musí zakouzlit znovu. Rozsah: 30 sáhů v okruhu od pamětníka. Působení: Musí umět alespoň 3 libovolná základní požehnání. Osoby v oblasti pod vlivem kouzla jsou prodchnuty melancholií o slovech udatné smrti. Všechny osoby získají -1 k iniciativě, ale i když jejich životy klesnou pod 50 % maximální hodnoty nezemřou a jejich mez vyřazení je pak -10 životů, teprve poté upadají do bezvědomí. Jestliže žalozpěv ustane na déle jak 3 kola, efekt zmizí a zranění se počítá jako vždy. Každá směna žalozpěvu jsou 2 body únavy pro pamětníka. Dokud je žalozpěv aktivní, nemůže sesílat jiná kouzla.' AS pop
  UNION ALL SELECT 'Píseň slavné smrti' AS nazev, NULL AS uroven, '6 magů' AS mag, '6 sáhů' AS dos, '1 kolo' AS sesl, '1 směna' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 cíl. Působení: Musí umět alespoň 4 libovolná základní požehnání. Cíl je povzbuzen vyhlídkou na slavnou smrt a vyburcován k větším činům. Cíl pod efektem kouzla se udrží na nohou i do -50 % svých maximálních životů. Dále získá +2 ÚČ a +2 k hodu na iniciativu za každých -10 % životů co mu schází. Jakmile kouzlo skončí, nebo jsou jeho zranění přes -50 %, padá k zemi mrtev. Postavám pod efektem berserku přidá dalších 50 % životů pod které může jít.' AS pop
  UNION ALL SELECT 'Hymna trollobíjců' AS nazev, NULL AS uroven, '12 magů' AS mag, 'pamětník' AS dos, '3 kola' AS sesl, '3 směny' AS trv, 'vycerpavajici' AS un, 'Rozsah: 12 sáhů v průměru s pamětníkem ve středu. Působení: Musí umět alespoň 2 žalozpěvy. Všichni spojenci v ovlivněné oblasti si začnou zpívat tuto bojovou píseň. Každý protivník bojující proti postavě pod vlivem kouzla má -2 ÚČ a -2 OČ. Bojuje-li spojenec proti protivníkovy který je vyšší než on, získává další bonus do ÚČ. Za každou kategorii velikosti vyšší než li je on sám. Každý stupeň rozdílu je +2 k ÚČ, tento bonus neguje přirozený případný postih za rozdíl velikostí.' AS pop
  UNION ALL SELECT 'Píseň sdíleného osudu' AS nazev, NULL AS uroven, '20 magů' AS mag, 'pamětník' AS dos, '1 kolo' AS sesl, '3 směny' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 cíl. Pamětník prováže svůj osud s cílem. Pokud oba útočí na stejného protivníka, získají +2 ÚČ a +2 OČ. Zranění se dělí rovnoměrně mezi ně a dokud nejsou oba pod mezí vyřazení, oba stojí a bojují.' AS pop
  UNION ALL SELECT 'Sláva zesnulých' AS nazev, NULL AS uroven, '12 magů' AS mag, 'pamětník' AS dos, '2 kola' AS sesl, '2 směny' AS trv, 'vycerpavajici' AS un, 'Rozsah: 10 sáhů okolo pamětníka. Působení: Musí umět alespoň 2 žalozpěvy a 4 libovolná základní požehnání. Oblast okolo pamětníka zaplní duše jeho padlých předků a každý z nich šeptem pronáší slova o své dávné slávě a velikosti. Jsou to mlhavé přízraky a nijak nebrání ve výhledu. každý spojenec který stojí v ovlivněné oblastí získá bonus 1k4 ke způsobenému zranění které způsobí bojem TvT. Všichni protivníci s inteligenci 3 a menší budou odmítat do této oblasti vstoupit. Neplatí pro hmyz, nebo tvory immuní vůči strachu.' AS pop
  UNION ALL SELECT 'Hlodající vina' AS nazev, NULL AS uroven, '3 magy za cíl, max 10 cílů' AS mag, '15 sáhů' AS dos, '1 kolo' AS sesl, '6 kol' AS trv, 'vycerpavajici' AS un, 'Rozsah: dle dodané magenergie. Působení: Musí umět sláva zesnulých. Cíl zasažený kouzlem začne být zpytován vlastním svědomím a začnou se mu připomínat všechny nepravosti. Jeho vina je individuální, což znamená, že se bude cítit vinen podle své vlastní morálky. Tzn. co je pro jednoho dobré, může být pro druhého zlé. Každé kolo jeho vina roste. Po uplynutí 6 kol si cíl hází na Past Int-12- zdrcení/nic, je-li cíl zdrcen vlastní špatností/dobrotou. Na dalších 1k6 kol je ochromen a ztrácí iniciativu.' AS pop
  UNION ALL SELECT 'Soud předků' AS nazev, NULL AS uroven, '2 magy za cíl a předka' AS mag, '15 sáhů' AS dos, '1 kolo' AS sesl, '1 kolo za každého předka' AS trv, 'vycerpavajici' AS un, 'Rozsah: dle dodané magenergie. Působení: Musí umět hlodající vinu. Pamětník se může ještě před uplynutím 6 kol u kouzla Hlodající vina, rozhodnout přivolat jako soudce jeho vlastní předky. Každé kolo, které nechá pamětník vinu hlodat, pak přivolá jednoho předka. To značí maximálně 5. Každý z předků bude nahlas vykřikovat jeho poklesky a vysmívat se mu. Cíl si hází na Past Char -12- předci jej napadnou/nic. Když cíl neuspěje proti pasti, začne sám sebe zraňovat každé kolo za 1k8 životů. Po dobu trvání kouzla má -3 k iniciativě útoku i obraně. Pokud chce kouzlit, šance na úspěšné seslání je snížena o 50 %' AS pop
  UNION ALL SELECT 'Věčné pouto' AS nazev, NULL AS uroven, '10 magů' AS mag, '15 sáhů' AS dos, '1 kolo' AS sesl, '1 směna' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 vzpomínka na trollobíjce. Působení: Musí umět alespoň 3 žalozpěvy. Četnost: 1x za 4 měsíce u stejného trollobíjce. Tímto kouzlem pamětník přivolá vzpomínku na padlého trollobíjce ze své knihy, kterého zapsal za pomocí kouzla ´´věčná sláva´´. Tento se jako duch vrátí na bitevní pole, aby pomohl pamětníkovi, který mu prokázal tuto poslední službu. Tento duch má všechny vlastnosti, povahu atd zapsaného trollobíjce. Jeho tělo je nehmotné. Zranit jej lze pouze magickou zbraní a magií. Jeho maximální životy ve chvíli vyvolání jsou stejné, jako jsou životy pamětníka. Po uplynutí doby vyvolání, či zničení ducha, se tento rozplyne zpět do své sféry existence. Způsobuje magické poškození, obchází zbroje. Finální zranění je pak poloviční.' AS pop
  UNION ALL SELECT 'Milost Valayi' AS nazev, NULL AS uroven, '1 mag za cíl' AS mag, 'Dotyk' AS dos, '2 kola' AS sesl, '1 spánek až do probuzení' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 humanoid. Působení: Musí umět alespoň 6 základních požehnání.. Pamětník pronese před spánkem slova útěchy bohyně Valayi. Tento umocněný spánek doplní trollobíjci dvojnásobek životů za jeho přirozenou regeneraci. Pokud cílem kouzla není trollobíjec, doplní si za spánek 8 životů.' AS pop
  UNION ALL SELECT 'Zbroj Grugniho' AS nazev, NULL AS uroven, '6 magů' AS mag, '10 sáhů' AS dos, '1 kolo' AS sesl, '5 kol' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 cíl. Působení: Musí umět alespoň 6 základních požehnání.. Cíl je obalen zeminou či jiným vhodným materiálem ze svého bezprostředního okolí, tento na něm vytvoří ochrannou krustu. Po dobu trvání kouzla se pak cíl bere jako v maximálním naložení. (-4 iniciativa) Jeho KZ se zvýší o 12. Pokud je cílem koula trollobíjec, polovinu KZ získá i pamětník, ale bez postihu k naložení. Po skončení kouzla se na něm zbroj rozpadne. (Nejasné: zdroj uvádí „Pokud je cílem koula trollobíjec" — význam slova „koula" není jasný, ponecháno v původním znění.)' AS pop
  UNION ALL SELECT 'Grimnirova zuřivost' AS nazev, NULL AS uroven, '8 magů za cíl' AS mag, '12 sáhů' AS dos, '1 akce' AS sesl, '5 kol' AS trv, NULL AS un, 'Rozsah: 1 cíl. Působení: Musí umět alespoň 6 základních požehnání.. Cíl je rozzuřen do běla a tak tak si udržuje příčetnost. Efekt kouzla se projeví až při dalším hodu na iniciativu. Cíl pod vlivem získá +3 k hodu na iniciativu +3 ÚČ a +3 útoč. ale -4 k hodu na obranu. Postih se počítá i když již nemá akce, nebo mu někdo útočí do zad apod. (když nemá akci má -7 k obraně namísto -3)' AS pop
  UNION ALL SELECT 'Požehnání předků' AS nazev, NULL AS uroven, '4 magy' AS mag, '13 sáhů' AS dos, 'ihned' AS sesl, 'stále/ 1 past/1den' AS trv, NULL AS un, 'Rozsah: 1 cíl. Působení: Musí umět alespoň 5 písní předků.. Cíl pod efektem kouzla získá bonus +2 k hodu na jednu jakoukoliv past. Tento efekt se na jednom cíli nemůže objevit častěji, jak jednou denně, bez ohledu na to, zda-li byl hod úspěšný či nikoliv. Hráč musí oznámit, že cíli požehná, ale musí to nahlásit dřív, než dojde k samotnému hodu.' AS pop
  UNION ALL SELECT 'Runa Oceli I' AS nazev, NULL AS uroven, '4 magy za runu' AS mag, '1 sáh' AS dos, '1 směna' AS sesl, '1 den' AS trv, 'nevycerpavajici' AS un, 'Rozsah: 1 zbroj. Působení: Musí umět alespoň 8 základních požehnání.. Lze použít na zbroj cíle a zvýšit po dobu trvání tak její Kz o 1.' AS pop
  UNION ALL SELECT 'Runa Oceli II' AS nazev, NULL AS uroven, '7 magů za runu' AS mag, '1 sáh' AS dos, '1 směna' AS sesl, '1 den' AS trv, 'nevycerpavajici' AS un, 'Rozsah: 1 zbroj. Působení: Musí umět Runu ochrany I. Lze použít na zbroj cíle a zvýšit po dobu trvání tak její Kz o 2. (Nejasné: podmínka v původním textu odkazuje na „Runu ochrany I", ale v dokumentu žádná runa tohoto jména není — pravděpodobně jde o Runu Oceli I.)' AS pop
  UNION ALL SELECT 'Runa Oceli III' AS nazev, NULL AS uroven, '10 magů za runu' AS mag, '1 sáh' AS dos, '1 směna' AS sesl, '1 den' AS trv, 'nevycerpavajici' AS un, 'Rozsah: 1 zbroj. Působení: Musí umět Runu ochrany II. Lze použít na zbroj cíle a zvýšit po dobu trvání tak její Kz o 3. (Nejasné: podmínka v původním textu odkazuje na „Runu ochrany II", ale v dokumentu žádná runa tohoto jména není — pravděpodobně jde o Runu Oceli II.)' AS pop
  UNION ALL SELECT 'Runa Odhalení I' AS nazev, NULL AS uroven, '5 magů za runu' AS mag, 'dotyk' AS dos, '2 kola' AS sesl, '1 den' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 zbraň/projektil. Působení: Musí umět alespoň 8 základních požehnání.. Zbraně či projektily pod touto runou snižují cíli bonus k OČ získaného díky krytu. Počítá se bonus za předměty které cíl kryjí, nikoliv například štít cíle. Výjimku tvoří šermířské finty, které poskytují bonus k OČ. Pro zjednodušení si útočník počítá bonus +1 k ÚČ.' AS pop
  UNION ALL SELECT 'Runa Odhalení II' AS nazev, NULL AS uroven, '8 magů za runu' AS mag, 'dotyk' AS dos, '2 kola' AS sesl, '1 den' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 zbraň/projektil. Působení: Musí umět Runa Odhalení I. Zbraně či projektily pod touto runou snižují cíli bonus k OČ získaného díky krytu. Počítá se bonus za předměty které cíl kryjí, nikoliv například štít cíle. Výjimku tvoří šermířské finty, které poskytují bonus k OČ. Pro zjednodušení si útočník počítá bonus +2 k ÚČ. Pokud útočí na neviditelný cíl, počítá si útočník postih -4 ÚČ namísto -6 ÚČ.' AS pop
  UNION ALL SELECT 'Runa Odhalení III' AS nazev, NULL AS uroven, '11 magů za runu' AS mag, 'dotyk' AS dos, '2 kola' AS sesl, '1 den' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 zbraň/projektil. Působení: Musí umět Runa Odhalení II. Zbraně či projektily pod touto runou snižují cíli bonus k OČ získaného díky krytu. Počítá se bonus za předměty které cíl kryjí, nikoliv například štít cíle. Výjimku tvoří šermířské finty, které poskytují bonus k OČ. Pro zjednodušení si útočník počítá bonus +3 k ÚČ. Pokud útočí na neviditelný cíl, počítá si útočník postih -2 ÚČ namísto -6 ÚČ. Cíl zasažený touto runou se nemůže zneviditelnit kouzlem neviditelnost po dobu 8 hodin od zásahu.' AS pop
  UNION ALL SELECT 'Runa Hromu I' AS nazev, NULL AS uroven, '3 magy za runu' AS mag, 'dotyk' AS dos, '3 kola' AS sesl, '2 dny' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 sáh čtvereční. Působení: Musí umět alespoň 2 libovolné runy. Pamětník pokreslí vybraný hex touto runou. Tato hlasitě exploduje jakmile se jí někdo dotkne či ji jinak aktivuje. Runa se aktivuje fyzickým kontaktem. Runu lze seslat na podlahy, stropy i stěny, nebo předměty. Runa se automaticky aktivuje jakmile s ní manipuluje kdokoliv jiný, než sám pamětník. Hlasitost rány kterou runa udělá je přibližně jako výstřel z moderní pistole. Šance na zaslechnutí je 100 % v dosahu do 1 kilometru na otevřeném prostoru. Klesá o 1 % za každých 10 sáhů nad 1 kilometr.' AS pop
  UNION ALL SELECT 'Runa Hromu II' AS nazev, NULL AS uroven, '6 magů za runu' AS mag, 'dotyk' AS dos, '3 kola' AS sesl, '2 dny' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 sáh čtvereční. Působení: Musí umět Runa Hromu I. Pamětník pokreslí vybraný hex touto runou. Tato hlasitě exploduje jakmile se jí někdo dotkne či ji jinak aktivuje. Runa se aktivuje fyzickým kontaktem. Runu lze seslat na podlahy, stropy i stěny, nebo předměty. Runa se automaticky aktivuje jakmile s ní manipuluje kdokoliv jiný, než sám pamětník. Základní nápadnost runy je - 20 %. Hlasitost rány kterou runa udělá je přibližně jako výstřel z moderní pistole. Šance na zaslechnutí je 100 % v dosahu do 2 kilometrů na otevřeném prostoru. Klesá o 1 % za každých 20 sáhů nad 1 kilometr.' AS pop
  UNION ALL SELECT 'Runa Hromu III' AS nazev, NULL AS uroven, '9 magů za runu' AS mag, 'dotyk' AS dos, '3 kola' AS sesl, '2 dny' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 sáh čtvereční. Působení: Musí umět Runa Hromu II. Pamětník pokreslí vybraný hex touto runou. Tato hlasitě exploduje jakmile se jí někdo dotkne či ji jinak aktivuje. Runa se aktivuje fyzickým kontaktem. Runu lze seslat na podlahy, stropy i stěny, nebo předměty. Runa se automaticky aktivuje jakmile s ní manipuluje kdokoliv jiný, než sám pamětník. Hlasitost rány kterou runa udělá je přibližně jako výstřel z moderní pistole. Šance na zaslechnutí je 100 % v dosahu do 3 kilometrů na otevřeném prostoru. Klesá o 1 % za každých 30 sáhů nad 1 kilometr.' AS pop
  UNION ALL SELECT 'Runa Volnosti I' AS nazev, NULL AS uroven, '1 mag za runu' AS mag, 'dotyk' AS dos, '1 kolo' AS sesl, '1 den' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 cíl. Působení: Musí umět alespoň 2 libovolné runy. Touto runou pamětník umožní předmětu či osobě pohybovat se rychleji během cestování v otevřeném světě. Počítá se, jako by byla jeho pohyblivost, o 1 vyšší. Lze navýšit i nad 21+5. Nepočítá se pro let nebo levitaci.' AS pop
  UNION ALL SELECT 'Runa Volnosti II' AS nazev, NULL AS uroven, '2 magy za runu' AS mag, 'dotyk' AS dos, '1 kolo' AS sesl, '1 den' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 cíl. Působení: Musí umět Runa Volnosti I. Touto runou pamětník umožní předmětu či osobě pohybovat se rychleji během cestování v otevřeném světě. Počítá se, jako by byla jeho pohyblivost, o 2 vyšší. Lze navýšit i nad 21+5. Nepočítá se pro let nebo levitaci.' AS pop
  UNION ALL SELECT 'Runa Volnosti III' AS nazev, NULL AS uroven, '4 magy za runu' AS mag, 'dotyk' AS dos, '1 kolo' AS sesl, '1 den' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 cíl. Působení: Musí umět Runa Volnosti II. Touto runou pamětník umožní předmětu či osobě pohybovat se rychleji během cestování v otevřeném světě. Počítá se, jako by byla jeho pohyblivost, o 3 vyšší. Lze navýšit i nad 21+5. Nepočítá se pro let nebo levitaci. Cíl navíc získá +1 sáh za akci v rozšířeném souboji.' AS pop
  UNION ALL SELECT 'Runa Síry I' AS nazev, NULL AS uroven, '5 magů za runu' AS mag, 'dotyk' AS dos, '3 kola' AS sesl, '2 dny' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 hex. Působení: Musí umět Runa Hromu I, Runa Oceli I, Runa Odhalení I. Aktivovaná runa zaplaví oblast 5x5 štiplavým bezbarvým plynem. Cíle v této oblasti, které dýchají mají postih -1 OČ, ÚČ. Po aktivaci zůstane plyn na místě 1 hodinu. Není ovlivňován větrem.' AS pop
  UNION ALL SELECT 'Runa Síry II' AS nazev, NULL AS uroven, '7 magů za runu' AS mag, 'dotyk' AS dos, '3 kola' AS sesl, '2 dny' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 hex. Působení: Musí umět Runa Síry I. Aktivovaná runa zaplaví oblast 5x5 štiplavým bezbarvým plynem. Cíle v této oblasti, které dýchají mají postih -2 OČ, ÚČ. Po aktivaci zůstane plyn na místě 1 hodinu. Není ovlivňován větrem.' AS pop
  UNION ALL SELECT 'Runa Síry III' AS nazev, NULL AS uroven, '9 magů za runu' AS mag, 'dotyk' AS dos, '3 kola' AS sesl, '2 dny' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 hex. Působení: Musí umět Runa Síry II. Aktivovaná runa zaplaví oblast 5x5 štiplavým bezbarvým plynem. Cíle v této oblasti, které dýchají mají postih -3 OČ, ÚČ. Tento plyn se stává 100 % zápalným. Cíle v oblasti působení si hážou na past Obr -8- Zranění/poloviční zranění. Zranění je nemagický oheň. Hodnota zranění je 1k10. Po aktivaci zůstane plyn na místě 1 hodinu. Není ovlivňován větrem. Pokud vybuchne, jeho efekt zmizí.' AS pop
  UNION ALL SELECT 'Runa Zničení I' AS nazev, NULL AS uroven, '10 magů za runu' AS mag, 'dotyk' AS dos, '3 kola' AS sesl, '2 dny' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 hex. Působení: Musí umět Runa Síry III, Runa Volnosti I. Aktivovaná runa způsobí, že se terén změní v těžký. 2 akce pohybu na překonání. Cíl nacházející se v oblasti působení je zraněn za 1k10 životů horkým zemním plynem. Efekt zranění na místě vydrží 1 kolo. Poté zůstane již jen extrémně těžký terén po dobu 1 dne. Lze seslat pouze na zem kde je kámen. Jeden cíl může být jednou a tou samou runou zraněn pouze 1 za celé kolo. Pokud cíl zabírá více jak 2 hexy rozhoduje PJ jak bude cíl zpomalený, zraněn bude vždy.' AS pop
  UNION ALL SELECT 'Runa Zničení II' AS nazev, NULL AS uroven, '15 magů za runu' AS mag, 'dotyk' AS dos, '3 kola' AS sesl, '2 dny' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 hex. Působení: Musí umět Runa Zničení I. Aktivovaná runa způsobí, že se terén změní v těžký. 2 akce pohybu na překonání. Cíl nacházející se v oblasti působení je zraněn za 2k10 životů horkým zemním plynem. Efekt zranění na místě vydrží 2 kola. Poté zůstane již jen extrémně těžký terén po dobu 1 dne. Lze seslat pouze na zem kde je kámen. Jeden cíl může být jednou a tou samou runou zraněn pouze 1 za celé kolo. Pokud cíl zabírá více jak 2 hexy rozhoduje PJ jak bude cíl zpomalený, zraněn bude vždy.' AS pop
  UNION ALL SELECT 'Runa Zničení III' AS nazev, NULL AS uroven, '20 magů za runu' AS mag, 'dotyk' AS dos, '3 kola' AS sesl, '2 dny' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 hex. Působení: Musí umět Runa Zničení II. Aktivovaná runa způsobí, že se terén změní v extrémně těžký. 3 akce pohybu na překonání. Cíl nacházející se v oblasti působení je zraněn za 3k10 životů horkým zemním plynem. Efekt zranění na místě vydrží 3 kola. Poté zůstane již jen extrémně těžký terén po dobu 1 dne. Lze seslat pouze na zem kde je kámen. Jeden cíl může být jednou a tou samou runou zraněn pouze 1 za celé kolo. Pokud cíl zabírá více jak 2 hexy rozhoduje PJ jak bude cíl zpomalený, zraněn bude vždy.' AS pop
  UNION ALL SELECT 'Runa Zášti' AS nazev, NULL AS uroven, '10 magů za runu' AS mag, 'dotyk' AS dos, '2 kola' AS sesl, '8 hodin' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 osoba. Působení: Musí umět Runa Zničení III, Runa Síry III, Runa Hromu I. Četnost: 1 za měsíc na stejné osobě. Runa se zakreslí přímo na kůži cíle. Pod efektem runy, pokud nositel hodí 5 nebo 6 hází znovu na útok. Ovšem je zde 20 % šance s každým, že bude zraněn za stejnou hodnotu za jakou zranil cíl.' AS pop
  UNION ALL SELECT 'Runa Vody' AS nazev, NULL AS uroven, '5 magů za runu' AS mag, 'dotyk' AS dos, '1 směna' AS sesl, '1 hodina' AS trv, 'nevycerpavajici' AS un, 'Rozsah: 1 hex. Působení: Musí umět 2 libovolné runy. Lze seslat pouze na kámen. Na vybraném místě se po dobu trvání bude srážet voda. Množství vody z jedné runy jsou 3 litry/dávky vody.' AS pop
  UNION ALL SELECT 'Runa Skoku I' AS nazev, NULL AS uroven, '3 magy za runu' AS mag, 'dotyk' AS dos, '3 kola' AS sesl, '1 směna' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 hex. Působení: Musí umět 4 libovolné runy. Ovlivněný hex pomůže cíli skočit dále/výš. Větší tvorové zabírající více hexů musí být takto podpořeny na všech hexech. Bonus ke skoku jsou 2 sáhy do dálky a 1 sáh do výšky navíc k jeho stávajícím schopnostem skoku. (základní vzdálenost je rovna bonusu za sílu, minimálně 1)' AS pop
  UNION ALL SELECT 'Runa Skoku II' AS nazev, NULL AS uroven, '5 magy za runu' AS mag, 'dotyk' AS dos, '3 kola' AS sesl, '1 směna' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 hex. Působení: Musí umět Runa Skoku I. Ovlivněný hex pomůže cíli skočit dále/výš. Větší tvorové zabírající více hexů musí být takto podpořeny na všech hexech. Bonus ke skoku jsou 4 sáhy do dálky a 2 sáhy do výšky navíc k jeho stávajícím schopnostem skoku. (základní vzdálenost je rovna bonusu za sílu, minimálně 1)' AS pop
  UNION ALL SELECT 'Runa Skoku III' AS nazev, NULL AS uroven, '7 magy za runu' AS mag, 'dotyk' AS dos, '3 kola' AS sesl, '1 směna' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 hex. Působení: Musí umět Runa Skoku II. Ovlivněný hex pomůže cíli skočit dále/výš. Větší tvorové zabírající více hexů musí být takto podpořeny na všech hexech. Bonus ke skoku jsou 6 sáhů do dálky a 4 sáhy do výšky navíc k jeho stávajícím schopnostem skoku. (základní vzdálenost je rovna bonusu za sílu, minimálně 1)' AS pop
  UNION ALL SELECT 'Runa Oběti I' AS nazev, NULL AS uroven, '4 magy za runu' AS mag, 'dotyk' AS dos, '1 kolo' AS sesl, '1 směna' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 cíl. Působení: Musí umět 5 libovolných run. Zasažená postava si hází proti pasti Obr -x- Obr efekt/nic. Bránění se runě spotřebovává akce. Cíl který neuspěl v hodu proti pasti, obdrží bonusové zranění stejné povahy jako byl samostatný útok. Velikost bonusu je 1k4+1.' AS pop
  UNION ALL SELECT 'Runa Oběti II' AS nazev, NULL AS uroven, '6 magů za runu' AS mag, 'dotyk' AS dos, '1 kolo' AS sesl, '1 směna' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 cíl. Působení: Musí umět Runa Oběti I. Zasažená postava si hází proti pasti Obr -x- Obr efekt/nic. Bránění se runě spotřebovává akce. Cíl který neuspěl v hodu proti pasti, obdrží bonusové zranění stejné povahy jako byl samostatný útok. Velikost bonusu je 1k6+2.' AS pop
  UNION ALL SELECT 'Runa Oběti III' AS nazev, NULL AS uroven, '8 magů za runu' AS mag, 'dotyk' AS dos, '1 kolo' AS sesl, '1 směna' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 cíl. Působení: Musí umět Runa Oběti II. Zasažená postava si hází proti pasti Obr -x- Obr efekt/nic. Bránění se runě spotřebovává akce. Cíl který neuspěl v hodu proti pasti, obdrží bonusové zranění stejné povahy jako byl samostatný útok. Velikost bonusu je 1k8+3.' AS pop
  UNION ALL SELECT 'Runa Lékárníka I' AS nazev, NULL AS uroven, '4 magy za runu' AS mag, 'dotyk' AS dos, '1 kolo' AS sesl, '1 směna' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 cíl. Působení: Musí umět Runa Oběti I. Cíl nemusí souhlasit s efektem kouzla. Pokud nesouhlasí hází si na past. Char -x- Char efekt/nic. Bránění se runě spotřebovává akce.Cíl který neuspěl v hodu proti pasti, obdrží bonusové léčení stejné povahy jakým byl samotný zdroj. Velikost bonusu je 1k4+1.' AS pop
  UNION ALL SELECT 'Runa Lékárníka II' AS nazev, NULL AS uroven, '6 magů za runu' AS mag, 'dotyk' AS dos, '1 kolo' AS sesl, '1 směna' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 cíl. Působení: Musí umět Runa Lékárníka I. Cíl nemusí souhlasit s efektem kouzla. Pokud nesouhlasí hází si na past. Char -x- Char efekt/nic. Bránění se runě spotřebovává akce.Cíl který neuspěl v hodu proti pasti, obdrží bonusové léčení stejné povahy jakým byl samotný zdroj. Velikost bonusu je 1k6+2.' AS pop
  UNION ALL SELECT 'Runa Lékárníka III' AS nazev, NULL AS uroven, '8 magů za runu' AS mag, 'dotyk' AS dos, '1 kolo' AS sesl, '1 směna' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 cíl. Působení: Musí umět Runa Lékárníka II. Cíl nemusí souhlasit s efektem kouzla. Pokud nesouhlasí hází si na past. Char -x- Char efekt/nic. Bránění se runě spotřebovává akce.Cíl který neuspěl v hodu proti pasti, obdrží bonusové léčení stejné povahy jakým byl samotný zdroj. Velikost bonusu je 1k8+3.' AS pop
  UNION ALL SELECT 'Runa Slunce I' AS nazev, NULL AS uroven, '6 magů za runu' AS mag, 'dotyk' AS dos, '1 kolo' AS sesl, '1 směna' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 nemrtvý. Působení: Musí umět Runa Oběti I, Runa Lékárníka I. Cíl si hází si na past. Char -x- Char efekt/nic. Bránění se runě spotřebovává akce. Nemrtvý který neuspěl v hodu proti pasti, obdrží každé kolo zranění jako od svěcené vody v hodnotě 1k10. Na jednom cíli může být naráz pouze jedna runa slunce.' AS pop
  UNION ALL SELECT 'Runa Slunce II' AS nazev, NULL AS uroven, '9 magů za runu' AS mag, 'dotyk' AS dos, '1 kolo' AS sesl, '1 směna' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 nemrtvý. Působení: Musí umět Runa Slunce I. Cíl si hází si na past. Char -x- Char efekt/nic. Bránění se runě spotřebovává akce. Nemrtvý který neuspěl v hodu proti pasti, obdrží každé kolo zranění jako od svěcené vody v hodnotě 2k10. Na jednom cíli může být naráz pouze jedna runa slunce.' AS pop
  UNION ALL SELECT 'Runa Slunce III' AS nazev, NULL AS uroven, '12 magů za runu' AS mag, 'dotyk' AS dos, '1 kolo' AS sesl, '1 směna' AS trv, 'vycerpavajici' AS un, 'Rozsah: 1 nemrtvý. Působení: Musí umět Runa Slunce II. Cíl si hází si na past. Char -x- Char efekt/nic. Bránění se runě spotřebovává akce. Nemrtvý který neuspěl v hodu proti pasti, obdrží každé kolo zranění jako od svěcené vody v hodnotě 3k10. Na jednom cíli může být naráz pouze jedna runa slunce.' AS pop
) v
JOIN seznamy_kouzel s ON s.nazev = 'Kouzla pamětníka'
JOIN povolani p ON p.id = s.povolani_id AND p.nazev = 'Pamětník';
