INSERT INTO predmet_efekty (predmet_id, efekt_id)
SELECT p.id, e.id FROM predmety p, efekty e
WHERE p.nazev = 'Jaspis (kapacitní drahokam)' AND p.typ = 'artefakt' AND e.nazev = 'Krvácení Jaspisu';
