-- =====================================================================
INSERT INTO lektvar_efekty (lektvar_id, efekt_id)
SELECT l.id, e.id FROM lektvary l, efekty e
WHERE l.nazev = 'Antigravitační cloumák' AND e.nazev = 'Antigravitační cloumák';
INSERT INTO lektvar_efekty (lektvar_id, efekt_id)
SELECT l.id, e.id FROM lektvary l, efekty e
WHERE l.nazev = 'Lektvar obří síly' AND e.nazev = 'Obří síla';
