INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, odolnost, velikost, bojovnost, pohyblivost, inteligence, charisma, zsm, presvedceni_id, poklady, zkusenost, prostredi, popis) VALUES
('Bazilišek', '8', '(+4 + 6/+1) = 10+/1 (tlama) + 2×10/+1', '+2 + 6 = 8', '21', 'B–C', '6', '14/magický tvor', '3', '2', '36',
 (SELECT id FROM presvedceni WHERE nazev='Zákonné zlo'),
 '5 000/100', 2500, 'skalnaté jeskyně, doupata',
 'Až šest sáhů dlouhý mohutný ještěr, vzdáleně spřízněný s draky. Sbírá poklady, je zbabělý a inteligencí nevalný, zato smrtelně nebezpečný smrtícím pohledem (past Int, past 15, neúspěch = okamžitá smrt oběti; funguje na vzdálenost 30 sáhů, jen za světla, na bytosti s int 2+ které mají otevřené oči a bazilišek je vidí). V jednom kole útočí buď normálně, nebo pohledem, nikoli obojí. Bojí se draků. Hřbetní korunka je cenná loveckou trofejí. -- TODO ověřit proti skenu, str. 131-132.');

