((SELECT id FROM nestvury WHERE nazev='Bazilišek' ORDER BY id DESC LIMIT 1), (SELECT id FROM kody_zranitelnosti WHERE kod='G'), NULL),
((SELECT id FROM nestvury WHERE nazev='Bazilišek' ORDER BY id DESC LIMIT 1), (SELECT id FROM kody_zranitelnosti WHERE kod='H'), NULL),
