-- Behemont — theurgy vyráběný "umělý" strážce s parametrizovanou životaschopností (8+X, X=1-7).
INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, odolnost, velikost, bojovnost, pohyblivost, inteligence, charisma, zsm, presvedceni_id, poklady, zkusenost, prostredi, popis) VALUES
('Behemont¹', '8 + X', 'X + síla zbraně; 10 + X : 2 (čepele)', '(3 − X) + 10 = 13 − X', '20 + X', 'B–D', '12', '16 − X/humanoid', 'viz popis (1 nebo víc)', '2 (u inteligentních)', '30 (u inteligentních)',
 (SELECT id FROM presvedceni WHERE nazev='Neutrální'),
 'nic', NULL, 'u svého pána / tvůrce',
 'Theurgy stvořený osobní strážce (X = 1–7 udává sílu, zkušenost = (45X²+1260X+7200):(14+2X)). Humanoidní, ale mohutné až čtverhranné tělo s kostrou z kovu, může mít místo dlaní čepele. V telepatickém spojení s pánem do 200 sáhů, automaticky ho brání i proti jeho vůli. Po smrti pána se chová nevyzpytatelně. Zranitelnost je individuálně dohodnuta mezi tvůrcem a pánem při výrobě (viz nestvura_zranitelnosti — jen orientační): odolný proti výbušninám a ohni (poloviční zranění), hraničářská kouzla normálně, kouzelnická kouzla dle domluvy s tvůrcem (může být částečně imunní vůči bleskům), fyzická kouzla (L) zasáhnou jen na hod k% 1–50, psychická kouzla (M) fungují jen na behemonty s int > 1 a jen když jsou v telepatickém kontaktu s pánem. Nelze podrobit, lze vyzvat na mentální souboj (on sám souboj nevyvolává).');

-- Behemont: zranitelnost je bespoke (dohodou tvůrce/pána), nevkládáme fixní seznam kódů — viz popis. TODO ověřit proti skenu je-li k dispozici přesnější tabulka.

-- Bizon
INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, odolnost, velikost, bojovnost, pohyblivost, vytrvalost, inteligence, poklady, zkusenost, ochoceni, prostredi, popis) VALUES
('Bizon', '10', '(+4 + 5) = 9; (+4 + 5/6) = 9/6 (s rozběhem)', '(−1 + 7) = 6', '23', 'C', '9', '20/zvěř', '18/zvěř', '1', 'nic', 480, '8 mládě, 12 dospělí', 'prérie v létě, les v zimě',
 'Obr mezi suchozemskými býložravci, šedohnědá srst, hříva na bedrech, lesklé černé rohy a kopyta. Žije ve velkých stádech, mláďata jsou hravá a snadno ochočitelná, dospělí bizoni jsou nevrlí a neurvalí. Napaden ve stádě je nebezpečný téměř všemu, co neumí létat.');

INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator)
SELECT (SELECT id FROM nestvury WHERE nazev='Bizon' ORDER BY id DESC LIMIT 1), id, NULL FROM kody_zranitelnosti WHERE kod IN ('B','C','D','G','H','I','J','K','L');
-- Zranitelnost zapsána v předloze jako skupina "zvíře" = B,C,D,G,H,I,J,K,L (viz legenda skupin v úvodu Bestiáře).

-- Blátoplazové
INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, odolnost, velikost, bojovnost, pohyblivost, inteligence, charisma, presvedceni_id, poklady, zkusenost, prostredi, popis) VALUES
('Blátoplazové', 'X', '(−2 + 1 + 2X) = −1 + 2X (tlama); −2 + 2X (spáry)', '(+1 + 2) = 3', '3X', 'A0–C', 'X + 5', '15/humanoid (v bahně); 4/humanoid (na suchu)', '2', '2',
 (SELECT id FROM presvedceni WHERE nazev='Zmatené zlo'),
 'nic', NULL, 'rozsáhlé stojaté bažiny',
 'Tvor neurčeného vzhledu žijící v řídkých bažinách — navenek prozrazuje jen vlnka nebo přemísťující se hrouda bahna ("vlnky"/"vlny"). Velikost i síla škálují parametrem X (1–7, zkušenost = 2,65·(2X²+X−1)). Na suchu nabývá mírně humanoidního tvaru obaleného bahnem a může bojovat, ale delší pobyt mimo bažinu (tekoucí voda) je pro něj smrtelný.');

INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator)
SELECT (SELECT id FROM nestvury WHERE nazev='Blátoplazové' ORDER BY id DESC LIMIT 1), id, NULL FROM kody_zranitelnosti WHERE kod IN ('A','B','C','D','G','H','I','J','K','L','M');
-- Zapsáno jako "humanoid, ale O 0" — základ humanoid = A,B,C,D,G,H,I,J,K,L,M,O; kód O (podrobování) vyloučen (imunní).

