-- Bron
INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, odolnost, velikost, bojovnost, pohyblivost, inteligence, charisma, presvedceni_id, poklady, zkusenost, prostredi, popis) VALUES
('Bron', '3 + 2', '(+4 + 4) = 8 (klacek)', '(0 + 3) = 3', '19', 'B', '3', '19/humanoid', '5', '8',
 (SELECT id FROM presvedceni WHERE nazev='Zmatené dobro'),
 'nic, 10/0 osada', 60, 'listnaté lesy',
 'Chlupatí tvorové vzdáleně připomínající člověka (možná přechodný stupeň mezi opicí a člověkem), s hrbem na zádech, v němž skladují živiny (vydrží až 14 dní bez jídla a vody). Mírní býložravci žijící v malých skupinách v chatrčích, náčelníci mají druidské schopnosti a každý bron umí odvracet zvířata jako druid na 10. úrovni. Neznají zbraně, dají se snadno získat drobnými lesklými dárky, jsou dobří nosiči. Nesnášejí sarkony a útočí na ně od pohledu; ve svém rodném lese mají bonus +1 k útoku i obraně.');

INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator) VALUES
((SELECT id FROM nestvury WHERE nazev='Bron' ORDER BY id DESC LIMIT 1), (SELECT id FROM kody_zranitelnosti WHERE kod='A'), '1/2');
INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator)
SELECT (SELECT id FROM nestvury WHERE nazev='Bron' ORDER BY id DESC LIMIT 1), id, NULL FROM kody_zranitelnosti WHERE kod IN ('B','C','D','G','H','I','J','K','L','M','O');
-- Zapsáno jako "humanoid, ale A 1/2".

-- Bytosti astrální* — samostatný stat blok chybí, předloha odkazuje "viz heslo Démoni" — pokryto entitami Démon níže, samostatný řádek nezakládáme.

