INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, odolnost, velikost, bojovnost, pohyblivost, vytrvalost, inteligence, poklady, zkusenost, prostredi, popis) VALUES
('Červ', 'závisí na délce', 'závisí na délce', '(–1 + 1) = 0', '11', 'B–E', '12', '10/hmyz', '23/hmyz', '0', 'nic, 50/0 v okolí doupěte', NULL, 'vlhké hluboké šachty a studny',
 'Velký bílý až průsvitný masožravec s přísavkami umožňujícími lézt i po kolmých stěnách; dokáže pohltit obrovské množství potravy a žít z ní měsíce. Útočí lepkavou tekutinou z povrchu těla, která znehybní oběti v dosahu; znehybněná postava se během 1–6 kol stává potravou, pokud ji nikdo neodtáhne — sama se vyprostit nedokáže. Nemá skoro žádný pud sebezáchovy (dokud je kořist nablízku, neuteče), ale po vzdálení se družiny rychle (1–6 kol) zaleze do doupěte. Životaschopnost, útočné číslo i zkušenost škálují s délkou červa (1 úroveň životaschop. = 2 sáhy délky; zkušenost = 10×úroveň + 10 za každou úroveň navíc, přesný vzorec viz text). Zranitelný vším kromě střelných zbraní.');

INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator)
SELECT (SELECT id FROM nestvury WHERE nazev='Červ' ORDER BY id DESC LIMIT 1), id, NULL FROM kody_zranitelnosti WHERE kod IN ('B','C','D','G','H','I','J','K','L');
-- Zapsáno jako skupina "zvíře".

