-- ---------------------------------------------------------------------
-- Draci — 4 divocí s plným stat blokem (Bílý/Žlutý/Modrý/Hnědý) +
-- 8 pojmenovaných druhů popsaných jen slovně (bez čísel v předloze,
-- jde o rozšíření o "moudré draky" z Pravidel pro pokročilé) + Drakodlak.
-- Obecná dračí mechanika (zmámení, dech, boj) je shrnuta v popisu níže.
-- ---------------------------------------------------------------------

INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, odolnost, velikost, pohyblivost, manevrovaci_schopnost, inteligence, charisma, zsm, presvedceni_id, poklady, zkusenost, prostredi, popis) VALUES
('Bílý drak', '12', '(+7+5/+2,5/+2)=12/+2 (paráty)+(+7+9/+2)=16/+2 (tlama)', '(+3+9)=12', '25', 'E', '8/drak (na zemi), 14/drak (ve vzduchu)', '18', '11', '19', '116',
 (SELECT id FROM presvedceni WHERE nazev='Neutrální'),
 '60 000/100', 3000, 'ledové pláně severu',
 'Chladnomilný divoký drak, dech (2× denně, dosah 40 sáhů, 18 magů) je mrazivý chlad. Povaha nevrlá a drsná, ale lze s ním vyjednávat. Obecně pro draky: zmámení pohledem/hlasem (past Int 5 ± inteligence draka, max 3 pokusy/kolo mimo boj), dlouhý spánek (šance na neprobuzení 1/1k10, po prvním útoku se probudí vždy), boj 2 pařáty + tlama = 3 útoky/kolo na tři cíle (bonus +12 k iniciativě v rozšířeném souboji) nebo dech místo útoků. Draka nelze podrobit, lze s ním vést mentální souboj.');
INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator)
SELECT (SELECT id FROM nestvury WHERE nazev='Bílý drak' ORDER BY id DESC LIMIT 1), id, NULL FROM kody_zranitelnosti WHERE kod IN ('B','C','D','G','H','I','J','L');
-- Zapsáno jako "drak, ale mráz G 0, K 0": základ drak = B,C,D,G,H,I,J,K,L; K vyloučen, G platí jen na oheň (ne mráz, na který je imunní).

INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, odolnost, velikost, pohyblivost, manevrovaci_schopnost, inteligence, charisma, zsm, presvedceni_id, poklady, zkusenost, prostredi, popis) VALUES
('Žlutý drak', '14', '(+8+5/+2,5/+2)=13/+2 (paráty)+(+8+9/+2)=17/+2 (tlama)', '(+3+10)=13', '25', 'E', '9/drak (na zemi), 15/drak (ve vzduchu)', '17', '17', '17', '98',
 (SELECT id FROM presvedceni WHERE nazev='Zákonné zlo'),
 '90 000/250', 4250, 'pouště',
 'Divoký drak pouští, dech (2× denně, dosah 50 sáhů, 22 magů) je žhavý vzduch. Zlý a nemilosrdný, neušetří nic živého; má dosti špatný zrak od slunečního světla. Obecná dračí mechanika viz heslo Bílý drak / Drak.');
INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator)
SELECT (SELECT id FROM nestvury WHERE nazev='Žlutý drak' ORDER BY id DESC LIMIT 1), id, NULL FROM kody_zranitelnosti WHERE kod IN ('B','C','D','G','H','I','J','L');
-- Zapsáno jako "drak, ale oheň G 0, K 0": K vyloučen, G platí jen na mráz (imunní vůči ohni).

INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, odolnost, velikost, pohyblivost, manevrovaci_schopnost, inteligence, charisma, zsm, presvedceni_id, poklady, zkusenost, prostredi, popis) VALUES
('Modrý drak', '16', '(+9+5/+2,5/+2)=14/+2 (paráty)+(+9+9/+2)=18/+2 (tlama)', '(+3+11)=14', '25', 'E', '10/drak (na zemi), 16/drak (ve vzduchu), 11/drak (ve vodě)', '18', '14', '20', '127',
 (SELECT id FROM presvedceni WHERE nazev='Zmatené dobro'),
 '80 000/200', 6000, 'mírné přímořské oblasti',
 'Jediný z divokých draků schopný plavat a potápět se, dech (3× denně, dosah 60 sáhů/30 sáhů ve vodě, 29 magů). Povaha mírná, straní se lidí, občas chrání spřátelenou vesnici. Obecná dračí mechanika viz heslo Bílý drak / Drak.');
INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator)
SELECT (SELECT id FROM nestvury WHERE nazev='Modrý drak' ORDER BY id DESC LIMIT 1), id, NULL FROM kody_zranitelnosti WHERE kod IN ('B','C','D','G','H','I','J','L');
-- Zapsáno jako "drak, ale oheň G 0, K 0": K vyloučen, G platí jen na mráz.

INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, odolnost, velikost, pohyblivost, manevrovaci_schopnost, inteligence, charisma, zsm, presvedceni_id, poklady, zkusenost, prostredi, popis) VALUES
('Hnědý drak', '18', '(+10+5/+2,5/+2)=15/+2 (paráty)+(+10+9/+2)=19/+2 (tlama)', '(+3+12)=14', '25', 'E', '10/drak (na zemi), 17/drak (ve vzduchu)', '17', '9', '15', '79',
 (SELECT id FROM presvedceni WHERE nazev='Zmatené zlo'),
 '50 000/80', 7120, 'bažiny a mokřady',
 'Divoký drak bažin, dech (3× denně, dosah 70 sáhů, 20 magů) je leptavý proud kyseliny. Nerudný a poněkud přihlouplý, sežere vše, co přijde; podezřívavý vůči bytostem, které mluví příliš chytře. Obecná dračí mechanika viz heslo Bílý drak / Drak.');
INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator)
SELECT (SELECT id FROM nestvury WHERE nazev='Hnědý drak' ORDER BY id DESC LIMIT 1), id, NULL FROM kody_zranitelnosti WHERE kod IN ('B','C','D','G','H','I','J','K','L');
-- Zapsáno jako "drak, ale H+": zůstává plný základ drak (B,C,D,G,H,I,J,K,L); H platí jen jako H+ (jen magické jedy/kyseliny).

-- Následujících 8 pojmenovaných draků (Rudý, Zelený, Vodní, Černý, Duhový,
-- Ledový, Ohnivý, Zlatý) je v předloze popsáno jen slovně — bez vlastní
-- číselné tabulky Životaschop./ÚČ/OČ (ta je jen u Bílého/Žlutého/Modrého/
-- Hnědého draka výše). Jde patrně o rozšíření o varianty "moudrých draků"
-- z Pravidel pro pokročilé, jejichž čísla podle textu měla být uvedena
-- v závorce vedle divoké varianty, ale v tomto zdroji chybí.
-- TODO ověřit proti skenu — může jít o poškozené/chybějící tabulky.

INSERT INTO nestvury (nazev, velikost, presvedceni_id, prostredi, popis) VALUES
('Rudý drak', 'E', NULL, 'krátery činných sopek',
 'Teplomilný drak brodící se lávou. Ohrožen jen v epicentru sopečného výbuchu (80% šance přežití se zraněními). Vylétá na lov jen zřídka, drží se lávy. Dech: žhavá směs podobná lávě. Poklad z drahých kamenů vyvržených sopkou; příliš nestřežený, oblast výskytu lidé navštěvují zřídka. -- TODO chybí číselný stat blok v předloze, ověřit proti skenu.');

INSERT INTO nestvury (nazev, velikost, presvedceni_id, prostredi, popis) VALUES
('Zelený drak', 'E', NULL, 'jehličnaté a listnaté lesy mírného pásu',
 'Velmi žravý drak, který loví, dokud nevyhubí zvěř v okolí, pak se stěhuje jinam. Dva zelení draci stejného pohlaví, kteří se střetnou, spolu obvykle boj svedou na život a na smrt. Dech: omračující plyn (na zvěř, jinak jen stínové zranění). V konfliktu s druidy kvůli devastaci lesa. -- TODO chybí číselný stat blok v předloze, ověřit proti skenu.');

INSERT INTO nestvury (nazev, velikost, presvedceni_id, prostredi, popis) VALUES
('Vodní drak', 'E', NULL, 'moře a oceány',
 'Jeden z mála tvorů schopných dlouhodobě fungovat ve všech třech živlech; podobá se modrému draku, ale drží se víc na souši. Dýchá libovolně dlouho pod vodou i na suchu, živí se rybami, kraby a chobotnicemi. Velký poklad ukrytý z potopených korábů. Dech (proud vzduchu podobný podmořskému výbuchu) používá jen pod vodou; v konfliktu raději uprchne do vody. 3% šance, že jde o moudrého draka. -- TODO chybí číselný stat blok v předloze, ověřit proti skenu.');

INSERT INTO nestvury (nazev, velikost, inteligence, presvedceni_id, prostredi, popis) VALUES
('Černý drak', 'E', 'velmi vysoká', NULL, 'mezi hvězdami, na svět slétá jen za soumraku',
 'Vzácný drak neznámého sídla, neuvěřitelně ostrý zrak, ví o všem dění ve světě. Slétá dolů ve velkých spirálách, připomíná obrovského netopýra; celý černý s lesklými pařáty a zlatýma očima, za bezměsíčné noci téměř neviditelný. Zasahuje do světových záležitostí ve snaze udržet jakousi rovnováhu. Umí plavat pod vodou (nepotřebuje dýchat). Dech: mráz Vnějšího světa, tak chladný, že zraní i bílého a ledového draka. 25% šance, že jde o moudrého draka. -- TODO chybí číselný stat blok v předloze, ověřit proti skenu.');

INSERT INTO nestvury (nazev, velikost, presvedceni_id, poklady, prostredi, popis) VALUES
('Duhový drak', 'E', NULL, 'obvykle žádný, výjimečně zajímavý kouzelný předmět', 'potuluje se po světě, bez stálého sídla',
 'Menší, ale obratnější a rychlejší než ostatní draci; duhově hrající šupiny. Nerad bojuje, spíš družině poradí (rady však díky lehkomyslnosti a smyslu pro humor nemusí být spolehlivé). Dech: oblak duhové páry, v němž zákonně zlé postavy a všechny obzvlášť zlé bytosti ztrácejí stínové životy. 50% šance, že jde o moudrého draka. -- TODO chybí číselný stat blok v předloze, ověřit proti skenu.');

INSERT INTO nestvury (nazev, velikost, presvedceni_id, prostredi, popis) VALUES
('Ledový drak', 'E', NULL, 'vysoké hory, rozlehlé doupě/palác',
 'Kruté, vypočítavé a chladné tělo porostlé modrými šupinami; despektuje drobné bytosti jako lidi, ale váží si jejich řemeslné zručnosti. Sběratel — miluje čisté a studené věci: sklo, drahokamy, stříbro, chladné zbraně, i legendární zbraně hrdinů. Dechem může zabíjet, nebo místo toho jen zmrazovat (ubírá stínové životy; při nule postava zamrzne do ledového kvádru, zůstává živá a nestárne, dokud kvádr nerozmrzne v teple — pak procitne za 1–6 směn); někdy sbírá takto zmrazené protivníky jako trofeje. 15% šance, že jde o moudrého draka. -- TODO chybí číselný stat blok v předloze, ověřit proti skenu.');

INSERT INTO nestvury (nazev, velikost, presvedceni_id, poklady, prostredi, popis) VALUES
('Ohnivý drak', 'E', NULL, 'obvykle žádný, výjimečně zajímavý kouzelný předmět', 'horké krajiny, sídlo tvarované vlastním dechem',
 'Strašlivý, ale ne příliš inteligentní drak, na kterého lze vyzrát lstí a lichotkami (byť to obětem nezaručí přežití — než zabije, rád si s kořistí hraje). Nafoukaný a marnivý, menší bytosti považuje za hlupáky. Mrzoutský samotář, kterého lze vylákat jen zprávou o zajímavé ohnivé dračici. Sídlo si upravuje ohnivým dechem tavícím i kámen. 10% šance, že jde o moudrého draka. -- TODO chybí číselný stat blok v předloze, ověřit proti skenu.');

INSERT INTO nestvury (nazev, velikost, inteligence, presvedceni_id, prostredi, popis) VALUES
('Zlatý drak', 'E', 'velmi vysoká (jako čaroděj/mág na 25. úrovni)', (SELECT id FROM presvedceni WHERE nazev='Zákonné dobro'), 'proměnlivé, cestuje světem',
 'Nejsympatičtější a nejinteligentnější ze všech druhů draků, patrně patriarcha celého dračího rodu (možná existuje jen jediný na světě). Umí měnit podobu a často se vydává za lidi či zvířata ze zvědavosti nebo s posláním. Dech: libovolný z dechů ostatních draků podle volby, navíc vlastní "zlatý třpyt" (pokrývá povrchy tenkým zlatým povlakem; při zásahu obličeje past Obr(7) — neúspěch = udušení; seškrábnuté zlato váží 50 mn). V dračí podobě útočí 3× za kolo (2× pařáty, 1× kousnutím), přeměna podoby trvá 2 kola bez magenergie. Dech může použít i v lidské podobě (jen zlatý třpyt), jinak jen v dračí podobě, kde smí použít libovolný typ dechu. Univerzální magenergie pro kouzelnická i hraničářská kouzla; v lidské podobě má schopnosti chodce i druida na 25. úrovni. 100% šance, že jde o moudrého draka. -- TODO chybí číselný stat blok v předloze, ověřit proti skenu.');

-- Drakodlak
INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, odolnost, velikost, pohyblivost, manevrovaci_schopnost, inteligence, charisma, zsm, presvedceni_id, poklady, zkusenost, popis) VALUES
('Drakodlak', '35', '(+15 + 9/+5, 9/+5) = 24/+5 (pařáty) + (+15 + 15/+10) = 30/+10 (tlama)', '(+10 + 22) = 32', '36', 'E', '18/drak (na zemi); 25/drak (ve vzduchu); 25/humanoid', '31', '35', '35', '163',
 (SELECT id FROM presvedceni WHERE nazev='Zákonné zlo'),
 '50 000/1 000', 300000,
 'Zlé bytosti zvou drakodlaka "Korunou všeho tvorstva", dobří o jeho existenci vědí jen výjimečně a nesmírně se ho bojí. Temný protějšek zlatého draka (stejné vlastnosti, opačné přesvědčení); dokáže libovolně měnit podobu, často humanoidní (odtud mylné zařazení mezi lykantropy — sdílí jen koncovku "-dlak"). Stojí v pozadí a řídí dění skrze humanoidy a divoké draky, moudří draci se jeho ovládání brání. Má schopnosti čaroděje i mága na 25. úrovni současně (bez omezení navzájem), ale neovládá hraničářská kouzla a nemůže používat vlastní zlatý třpyt. Dech 6× denně, dosah 155 sáhů, magenergie 600. -- TODO text v předloze je místy obtížně čitelný/opakuje se, ověřit proti skenu.');

INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator) VALUES
((SELECT id FROM nestvury WHERE nazev='Drakodlak' ORDER BY id DESC LIMIT 1), (SELECT id FROM kody_zranitelnosti WHERE kod='C'), '1/4'),
((SELECT id FROM nestvury WHERE nazev='Drakodlak' ORDER BY id DESC LIMIT 1), (SELECT id FROM kody_zranitelnosti WHERE kod='H'), '1/2'),
((SELECT id FROM nestvury WHERE nazev='Drakodlak' ORDER BY id DESC LIMIT 1), (SELECT id FROM kody_zranitelnosti WHERE kod='I'), '1/2'),
((SELECT id FROM nestvury WHERE nazev='Drakodlak' ORDER BY id DESC LIMIT 1), (SELECT id FROM kody_zranitelnosti WHERE kod='J'), '1/2'),
((SELECT id FROM nestvury WHERE nazev='Drakodlak' ORDER BY id DESC LIMIT 1), (SELECT id FROM kody_zranitelnosti WHERE kod='P'), NULL);
-- H má navíc kvalifikátor H+ (jen magické jedy) a P kvalifikátor P+ (sám útočí mentálně) — viz popis, modifikátor pro "+" kvalifikátor nelze zapsat číselně.

-- Družina Cizích postav (CP) — obecný rámec, ne konkrétní nestvůra s pevnými čísly.
INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, odolnost, velikost, pohyblivost, inteligence, charisma, zsm, presvedceni_id, poklady, zkusenost, popis) VALUES
('Družina Cizích postav (CP)', 'podle úrovně', 'určuje se jako u hráčů', 'určuje se jako u hráčů', 'určuje se jako u hráčů', 'závisí na rase', 'určuje se jako u hráčů', 'určuje se jako u hráčů', 'určuje se jako u hráčů', 'určuje se jako u hráčů',
 NULL, 'různé', NULL,
 'Skupina Cizích postav vytvořená stejně jako hráčská družina — libovolná rasa, jedno z pěti základních povolání (nebo desítka oborů z Pravidel pro pokročilé) na libovolné úrovni, se srovnatelnou výbavou i schopnostmi. Patří mezi nejnebezpečnější "nestvůry" právě proto, že zná stejné triky jako hráčská družina a má srovnatelnou inteligenci — může jak zaútočit, tak vyjednávat podle toho, jakou pověst má družina hráčů. Přesvědčení, poklady i zkušenost jsou různé dle konkrétního složení.');

INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator)
SELECT (SELECT id FROM nestvury WHERE nazev='Družina Cizích postav (CP)' ORDER BY id DESC LIMIT 1), id, NULL FROM kody_zranitelnosti WHERE kod IN ('A','B','C','D','G','H','I','J','K','L','M','O');

