INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, velikost, bojovnost, pohyblivost, inteligence, poklady, zkusenost, popis) VALUES
('Elfocvak*', '6', '(+2 + 6/+3) = 8/+3 (kusadla)', '(0 + 6) = 6', 'B', '12', '2/magický tvor', '0', 'nic', 190,
 'Dvousáhový tvor podobný roháči bez křídel, tělo v chitinovém pancíři, šest nohou, dvě strašná kusadla. Uměle stvořen k boji proti elfům, bývá součástí gard zlých mágů; elfí zbraně jsou proti pancíři málo účinné a elfové mají v boji s ním postih −2 na útok i obranu. Sevře-li kusadly postavu, drží ji a každé další kolo jí způsobí 3 životy zranění, dokud oběť neklesne pod třetinu původních životů (oběť s odolností 15+ může po tu dobu útočit s bonusem +2). Slabina: pancíř není odolný proti sekyrám (postih −2 na obranu proti sekyře).');

