INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, odolnost, velikost, bojovnost, pohyblivost, inteligence, charisma, presvedceni_id, poklady, zkusenost, popis) VALUES
('Goblin', '2', '+1 + síla zbraně', '+1 + kvalita zbroje + štít', '15', 'A–B', '9', '11/humanoid', '6', '8',
 (SELECT id FROM presvedceni WHERE nazev='Zmatené zlo'),
 '3/0, 2 500/20 sídlo', 40,
 'Bývá strkán do jednoho pytle se skřety, ale je větší, odvážnější a inteligentnější — až 1,75 sáhu, zelená šupinatá suchá kůže podobná hadí. Do boje zpravidla nenosí zbroj (náčelníci mívají kvalitnější brnění). Sluneční světlo mu neškodí, ale za plného slunce má postih k útoku i obraně. Se skřety a orky drží mír, s ostatními rasami raději obchoduje; goblinní vojska bojují jen za vlastní cíle, jednotlivci se však najímají jako kapitáni a zvědové zákonně zlých armád. Oblíbené zbraně: dlouhá kopí, dlouhé meče, luky. Vzácně se vyskytnou inteligentnější jedinci se sklonem k dobru a zájmem o alchymii.');

INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator)
SELECT (SELECT id FROM nestvury WHERE nazev='Goblin' ORDER BY id DESC LIMIT 1), id, NULL FROM kody_zranitelnosti WHERE kod IN ('A','B','C','D','G','H','I','J','K','L','M','O');

INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, odolnost, velikost, bojovnost, pohyblivost, vytrvalost, inteligence, poklady, zkusenost, prostredi, popis) VALUES
('Gobloch', '3 + 1', '(+3 + 4/+1) = 7/+1 (zuby)', '(0 + 3) = 3', '15', 'B', '8', '7/plaz', '23/plaz', '1', 'nic, 200/5 doupě', 60, 'vlhké oblasti a bažiny, ruiny a opuštěné stavby',
 'Necelé 2 sáhy dlouhý světlemodrý ještěr s bílými skvrnami. Loví v noci, umí běhat po zdech a stromech pomocí zvlášť upravených nohou a při útoku na kořist padá shora, což mu často (1–4 na 1k6) zajistí překvapení. Větší kořist odtahuje do doupěte, kolem něhož lze mezi zbytky nalézt i cennější předměty.');

INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator)
SELECT (SELECT id FROM nestvury WHERE nazev='Gobloch' ORDER BY id DESC LIMIT 1), id, NULL FROM kody_zranitelnosti WHERE kod IN ('B','C','D','G','H','I','J','K','L');

INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, velikost, pohyblivost, manevrovaci_schopnost, inteligence, charisma, zsm, presvedceni_id, poklady, zkusenost, prostredi, popis) VALUES
('Gorgona⁺', '4', '(+2+3/+1)=5/+1 (paráty) + (+2+4/+1)=6/+1 (tlama); +1 + dlouhý luk (2× za kolo)', '(+1+2)=3', 'B', '8/drak (na zemi), 12/drak (ve vzduchu)', '13', '17', '15', '12',
 (SELECT id FROM presvedceni WHERE nazev='Zákonné zlo'),
 'nic, 750/15 doupě', 105, 'skryté doupě, aktivní za noci',
 'Člověku podobný tvor s dlouhými netopýřími křídly a ostnatým ohonem, tělo připomínající kámen, často zaměňována za sochu. Nemá ráda sluneční světlo, přemísťuje se za noci létáním. Kromě parátů a tlamy střílí z dlouhého luku (z výšky). Velmi lstivá a inteligentní, útočí takřka na cokoliv, co se přiblíží. V kole zaútočí buď 2× paráty+tlama, nebo 2× lukem.');

