INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, odolnost, velikost, bojovnost, manevrovaci_schopnost, inteligence, charisma, presvedceni_id, poklady, zkusenost, ochoceni, prostredi, popis) VALUES
('Gryf', '12', '(+7 +7/4) = 14/+4 (zobák) + (+7 +5/+2, 5/+2) = 12/+2, 12/+2 (spáry)', '(+2 + 4) = 6', '19', 'D', '9 pro inteligenci 1', '18', '1 nebo 11', '11 (u inteligentních)',
 (SELECT id FROM presvedceni WHERE nazev='Zmatené dobro'),
 'nic, 400/5 hnízdo, intel. 600/10 hnízdo', 1800, '8 (u neinteligentních exemplářů)', 'skály a vyvýšeniny poblíž planin',
 'Tělo lva, hlava orla, velká orlí křídla, přední nohy lví síly zakončené orlími spáry umožňujícími snadné uchopení kořisti za letu. Velký jako mladý nedorostlý drak, srst hnědá až hnědožlutá, peří tmavě hnědé. Živí se jeleny a jinými velkými savci, humanoidů si nevšímá; nejraději má koňské maso a při spatření koně naň zaútočí (jezdce jen srazí ze sedla). Hnízdí ve skupinách 2–12 dospělých, snáší 1–2 vejce, mláďata brání tvrdě. Vzácní inteligentní gryfové vyjednávají o koních místo útoku. Nehromadí poklady, v hnízdě lze najít jen cennosti obětí; vejce je ceněný alchymistický úlovek. Pohyblivost/vytrvalost dle Tabulky jezdeckých zvířat (str. 124, v tomto zdroji samostatně nepřepsáno).');

INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator) VALUES
((SELECT id FROM nestvury WHERE nazev='Gryf' ORDER BY id DESC LIMIT 1), (SELECT id FROM kody_zranitelnosti WHERE kod='C'), NULL),
((SELECT id FROM nestvury WHERE nazev='Gryf' ORDER BY id DESC LIMIT 1), (SELECT id FROM kody_zranitelnosti WHERE kod='G'), '1/2'),
