INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, odolnost, velikost, bojovnost, pohyblivost, vytrvalost, manevrovaci_schopnost, inteligence, poklady, zkusenost, prostredi, popis) VALUES
('Hroznýš skalní', '4', '(+4+3/–1)=7/–1 (tlama) + zvl.; (+4+5/–1)=9/–1 (skrcení); (+4+5)=9 (úder)', '(+3+2)=5', '9', 'C', '11', '9/plaz', '18/plaz', '9 (vodomilné druhy)', '1', 'nic, 10/0 doupě', 130, 'noční lovec, některé druhy u vody',
 'Může měřit 10 i více sáhů, trojhranná hlava, silné tělo. Útočí ovinutím a rozdrcením oběti, případně vzepřením a úderem hlavou jako beranidlem. Zvláštní útok — skrcení: po úspěšném zakousnutí se ovine a v dalších kolech škrtí (útočné číslo 9 na nehybnou oběť); oběť může útok opětovat, jen pokud před kousnutím držela jednoruční zbraň. Legendární obří exempláře: za každých 10 sáhů délky navíc +4 k životaschopnosti a +2 k bonusu za sílu.');

INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator)
SELECT (SELECT id FROM nestvury WHERE nazev='Hroznýš skalní' ORDER BY id DESC LIMIT 1), id, NULL FROM kody_zranitelnosti WHERE kod IN ('B','C','D','G','H','I','J','K','L');

-- Chřestýš obří — stat blok je v předloze neúplný (chybí Životaschop./ÚČ/OČ/Odolnost/
-- Velikost/Bojovnost/Zranitelnost/Pohyblivost/Vytrvalost, tabulka začíná rovnou
-- Manévr. schop.) — TODO ověřit proti skenu, zapsáno jen co je v textu čitelné.
INSERT INTO nestvury (nazev, manevrovaci_schopnost, inteligence, poklady, zkusenost, popis) VALUES
('Chřestýš obří', '9 (vodomilné druhy)', '1', 'nic, 10/0 doupě', 30,
 '3 sáhy dlouhý had s hnědými a bílými šupinami v károvaném vzoru, na konci ocasu zrohovatělé chřestítko, kterým straší vetřelce. Zvláštní útok: smrtelně nebezpečný jed (past nebezpečnost 6, síla jedu 3–18/73–100). Po přežití prvního kousnutí už jed chřestýšů pro postavu není smrtelný, ale nadále platí past Odl(4) ~ 1–6/3–18. -- TODO stat blok v předloze neúplný (chybí životaschop./ÚČ/OČ/odolnost/velikost/bojovnost/zranitelnost/pohyblivost/vytrvalost), ověřit proti skenu.');

INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, odolnost, velikost, bojovnost, pohyblivost, vytrvalost, inteligence, poklady, zkusenost, prostredi, popis) VALUES
('Mamba černá', '2 + 2', '(+1+4)=5 + zvl.', '(+6+1)=7', '6', 'B–C', '11', '20/plaz', '5/plaz', '1', 'nic', 120, 'buš a prales teplého pásma, koruny stromů',
 'Dva až pět sáhů dlouhý velmi jedovatý had, bleskurychlý v korunách stromů; chová se nevyzpytatelně (někdy prchá, jindy útočí bez varování), dokáže se vztyčit a zaútočit i na jezdce na koni. Zvláštní útok: jed — velmi silný, past Odl(6) ~ 3–30/123–150, projeví se do jedné směny.');
INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator)
SELECT (SELECT id FROM nestvury WHERE nazev='Mamba černá' ORDER BY id DESC LIMIT 1), id, NULL FROM kody_zranitelnosti WHERE kod IN ('B','C','D','G','H','I','J','K','L');

INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, odolnost, velikost, bojovnost, pohyblivost, vytrvalost, inteligence, poklady, zkusenost, prostredi, popis) VALUES
('Zmije rohatá', '1', '(–1+5)=4 + zvl.', '(4+5+1)=6 (viz text)', '4', 'A', '11', '18/plaz', '2/plaz', '1', 'nic', 30, 'pouště, zahrabaná v písku',
 'Jeden až dva sáhy dlouhý jedovatý žlutý had s jamkami na hlavě, dobré infravidění na 10 sáhů (bonus k iniciativě při útoku). Zvláštní útok: jed — past Odl(4) ~ 1–6/3–18, působí do jedné směny.');
INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator)
SELECT (SELECT id FROM nestvury WHERE nazev='Zmije rohatá' ORDER BY id DESC LIMIT 1), id, NULL FROM kody_zranitelnosti WHERE kod IN ('B','C','D','G','H','I','J','K','L');

INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, odolnost, velikost, bojovnost, pohyblivost, manevrovaci_schopnost, inteligence, poklady, zkusenost, prostredi, popis) VALUES
('Had mořský', '25', '(+12 + 7) = 19 + zvl.', '(+3 + 5) = 8', '25', 'E', '11', '30/vodní tvor', '17', '1', 'nic', 1800, 'mořské hlubiny, výjimečně na hladině',
 'Obávaný obří had mořských hlubin, dorůstá až 200 sáhů (obvykle do 100). Před vynořením voda kolem místa asi tři směny kypí. Napadá lodě jako kořist, hlavu zvedá vysoko nad vodu, chrlí proudy vody a hledá oběť na palubě. Zmocnění se oběti trvá 2 kola. Zvláštní útok: buď plivnutí (past Odl(6) ~ 1–3/18, oslepení — léčitelné kouzlem uzdrav těžká zranění, ale bez obnovení životů), nebo kousnutí (jed, past Odl(6) ~ 1–6/2–12); v jednom kole jen jedno z toho. Neútočí na nebezpečnou kořist lidské velikosti a větší, není-li ohrožen. Průměrně sežere 2–12 obětí. -- TODO text kolem plivnutí/kousnutí je v předloze místy poškozený, ověřit proti skenu.');
INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator)
SELECT (SELECT id FROM nestvury WHERE nazev='Had mořský' ORDER BY id DESC LIMIT 1), id, NULL FROM kody_zranitelnosti WHERE kod IN ('B','C','D','G','H','I','J','K','L');

INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, odolnost, velikost, bojovnost, pohyblivost, vytrvalost, inteligence, poklady, zkusenost, prostredi, popis) VALUES
('Zlatulka', '1', '(0 + 3) = 3 (kousnutí) + zvl.', '(+4 + 1) = 5', '3', 'A0 až A', '11', '1/plaz', '15/plaz', '1', 'viz popis', 20, 'pokladnice a doupata se zlatem',
 'Malý (do 30 coulů) prudce jedovatý hádek, vyskytující se všude, kde je zlato — vleze i do většího doupěte či paláce. Po prvním útoku (přehrabávání se ve zlatě mu slouží jako "zbroj 0") zpravidla prchá. Zvláštní útok: jed, nebezpečnost 7, síla 1–6/3–18, trvání ihned/1 kolo. Sama žádný poklad nemá — zlato, ve kterém se skrývá, patří někomu jinému.');
INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator)
SELECT (SELECT id FROM nestvury WHERE nazev='Zlatulka' ORDER BY id DESC LIMIT 1), id, NULL FROM kody_zranitelnosti WHERE kod IN ('B','C','D','G','H','I','J','K','L');

INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, odolnost, velikost, bojovnost, pohyblivost, vytrvalost, inteligence, poklady, zkusenost, popis) VALUES
('Kobra plivající', '3', '(+2 + 5/–2) = 7/–2 (kousnutí) + zvl.; (+3 + 7) = 10 (plivnutí) pouze zvl.', '(+3 + 4) = 7', '6', 'A až B', '11', '3/plaz', '16/plaz', '1', 'nic', 210,
 '1–3 sáhy dlouhý šedobílý had s kápí zdobenou kresbou brýlí; při útoku komíhá horní částí těla. Zvláštní útok: jed lze buď plivat (na cíl do 3 sáhů, samo plivnutí neraní, ale past Odl(6) ~ 1–3/18 = oslepení, léčitelné uzdrav těžká zranění bez obnovení životů), nebo vypouštět do rány při kousnutí (past Odl(6) ~ 1–6/2–12). V kole jen jedno z toho; neútočí na protivníka lidské velikosti a většího, není-li ohrožena.');
INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator)
SELECT (SELECT id FROM nestvury WHERE nazev='Kobra plivající' ORDER BY id DESC LIMIT 1), id, NULL FROM kody_zranitelnosti WHERE kod IN ('B','C','D','G','H','I','J','K','L');

-- Handlíř — obchodník se zvířaty, čistě popisná CP bez stat bloku (odkazuje na heslo
-- Obyvatelé v PPZ) — nezakládáme samostatný řádek nestvůry.

INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, odolnost, velikost, pohyblivost, vytrvalost, manevrovaci_schopnost, inteligence, charisma, presvedceni_id, poklady, zkusenost, prostredi, popis) VALUES
('Harpyje', '3', '(0+2/+1)=2/+1 (paráty) + (0+3/0)=3/0 (tlama) nebo zvl.', '(–1+1)=0', '10', 'A', '2/humanoid (na zemi), 10/okřídlenec (ve vzduchu)', '10', '9', '18 (15 u samců)', '5',
 (SELECT id FROM presvedceni WHERE nazev='Zákonné zlo'),
 '5/0, 750/10 hnízdo', 40, 'vysoké skály, jeskyně, ruiny starých hradů',
 'Tělo orla, hlava a hruď ohavné ženy nebo starce. Nemá ji ráda žádná inteligentní rasa, harpyje se mstí, jak může. Hnízdí ve vysokých skalách/ruinách a zpěvem láká osamělé poutníky. Zvláštní útok: zpěv — past Int(8) ~ nic/zmámení, obětovaný spěchá k harpyji, ta ho pak požírá (omámení trvá do smrti harpyje nebo 1–6 směn); úspěšný hod chrání na 24 hodin. V kole útočí buď paráty a zpěvem, nebo paráty a kousnutím. Samci jsou stejně ošklivý, ale méně inteligentní (int 15) a bez zvláštního útoku.');

