INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, odolnost, velikost, bojovnost, pohyblivost, vytrvalost, inteligence, poklady, zkusenost, prostredi, popis) VALUES
('Hlen zelený', '2 za 1 čtvereční sáh', '4 (padáním) + zvl.', '0', '17', 'B', '7', '1/plaz', '21', '0', '200/0 (drahokamy)', NULL, 'stěny a stropy podzemních chodeb',
 'Podzemní obdoba mechu v chomáčích nebo souvislé vrstvě, reaguje na pohyb a čeká na oběť, které pak padá na hlavu. Splývá s okolím (trpaslík ho neuvidí, hobit ho nezjistí ani infravidením). Zbraně ani většina kouzel neúčinkují (odolný vůči ohni i mrazu, zranitelný blesky). Rozpouští plátno/kůži/dřevo okamžitě, kov po 6 kolech. Při doteku obnažené kůže mění maso v zelený hlen (nelze seškrábat) — zasažená postava se sama promění v zeleného hlena, není-li tvor do 6 kol zničen ohněm. Zkušenost počítej 20 za čtvereční sáh (jako životaschopnost).');
INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator)
SELECT (SELECT id FROM nestvury WHERE nazev='Hlen zelený' ORDER BY id DESC LIMIT 1), id, NULL FROM kody_zranitelnosti WHERE kod IN ('G','J','K');

INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, odolnost, velikost, bojovnost, pohyblivost, vytrvalost, manevrovaci_schopnost, inteligence, poklady, zkusenost, prostredi, popis) VALUES
('Brouk nosatec', '2 + 2', '(+1+3)=4 (bodec)', '(+2+3)=5', '18', 'A', '11', '16/hmyz (na zemi), 5/plaz (ve vzduchu)', '6/hmyz', '3', '0', 'nic', 30, 'stinná podzemní místa',
 'Asi sáh dlouhý brouk s téměř půlsáhovým ostrým bodcem, kterým napichuje drobné hlodavce. Poplašený se vrhá bezhlavě na družinu; při úvodním útoku s rozběhem má bonus +3 k obraně. Létá jen velmi zřídka.');
INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator)
SELECT (SELECT id FROM nestvury WHERE nazev='Brouk nosatec' ORDER BY id DESC LIMIT 1), id, NULL FROM kody_zranitelnosti WHERE kod IN ('B','C','D','G','H','I','J','K','L');

INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, odolnost, velikost, bojovnost, pohyblivost, vytrvalost, manevrovaci_schopnost, inteligence, poklady, zkusenost, prostredi, popis) VALUES
('Brouk ostnatec', '2 + 1', '(+2+1)=3 (ostny)', '(+2+5)=7', '16', 'A', '10', '15/hmyz (na zemi), 4/plaz (ve vzduchu)', '7/hmyz', '1', '0', 'nic', 20, 'vlhká místa a bažiny',
 '1,5 sáhu dlouhý brouk s tvrdým pancířem posetým ostny, okraje pancíře jako bodce pily obrácené proti směru běhu. Útočí proběhnutím kolem oběti, snaží se jí rozříznout nohu a srazit ji na zem; při prvním útoku s rozběhem má bonus +3 k útoku. Žijí ve velkém počtu, létají jen v krajní nouzi (např. při stěhování přemnožené kolonie).');
INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator)
SELECT (SELECT id FROM nestvury WHERE nazev='Brouk ostnatec' ORDER BY id DESC LIMIT 1), id, NULL FROM kody_zranitelnosti WHERE kod IN ('B','C','D','G','H','I','J','K','L');

INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, odolnost, velikost, bojovnost, pohyblivost, vytrvalost, manevrovaci_schopnost, inteligence, charisma, presvedceni_id, poklady, zkusenost, prostredi, popis) VALUES
('Moucha zlodějka', '1', '(–1+2)=1 (kusadla)', '(+1+2)=3', '14', 'A', '5', '1/hmyz (na zemi), 12/hmyz (ve vzduchu)', '8/hmyz', '15', '3', '2',
 (SELECT id FROM presvedceni WHERE nazev='Neutrální'),
 '10/0, 1 000/5 kolonie', 10, 'temné kouty podzemí',
 'Obří (asi sáh dlouhá) moucha s poněkud humanoidními rysy a stračími sklony ke sbírání lesklých věcí. Nedorozumívá se řečí, jen bzučením křídel, ale s postavami umí naznačit souhlas/nesouhlas při výměně. Číhá v podzemí, sleduje družinu, a když spí nebo bojuje, snaží se ukrást viditelné šperky. Ke koloniím jezdí kupci vyměňovat třpytivé tretky za cenné věci. Zvláštní útok: ukradení předmětu — past pro mouchu (vlastnost manévrovací schopnost, nebezpečnost dle umístění předmětu: ozdoba na šatech −5, předmět v ruce −7, prsten na prstě −10), síla ukradení/nic.');
INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator)
SELECT (SELECT id FROM nestvury WHERE nazev='Moucha zlodějka' ORDER BY id DESC LIMIT 1), id, NULL FROM kody_zranitelnosti WHERE kod IN ('B','C','D','G','H','I','J','K','L','O');
-- Zapsáno jako "zvíře + O".

INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, odolnost, velikost, bojovnost, pohyblivost, vytrvalost, manevrovaci_schopnost, inteligence, poklady, zkusenost, popis) VALUES
('Ploštice zelená', '½ (1–4 životy)', '(–1+2)=1 (kusadla) + zvl.', '(+1+2)=3', '9', 'A', '12', '5/hmyz (na zemi), 7/plaz (ve vzduchu)', '18/hmyz', '5', '0', 'nic', 5,
 'Připomíná 30 coulů dlouhou ploštěnku mléčnou. Jedovatá kusadla nezpůsobují velké zranění, ale vyvolávají částečné ochromení. Zvláštní útok: zásah ochromí příslušnou část těla na 2–7 směn, snižuje ÚČ i OČ o 1 po tuto dobu.');
INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator)
SELECT (SELECT id FROM nestvury WHERE nazev='Ploštice zelená' ORDER BY id DESC LIMIT 1), id, NULL FROM kody_zranitelnosti WHERE kod IN ('B','C','D','G','H','I','J','K','L');

INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, odolnost, velikost, bojovnost, pohyblivost, vytrvalost, manevrovaci_schopnost, inteligence, poklady, zkusenost, prostredi, popis) VALUES
('Roháč obří', '2', '(+2+2)=4 (kusadla) sameček; (+1+1)=2 (kusadla) samička', '(+2+4)=6', '17', 'A', '9', '5/hmyz (na zemi), 5/plaz (ve vzduchu)', '22/hmyz', '2', '0', 'nic', 25, 'mokřiny a vlhké jeskyně',
 '1,5 sáhu dlouhý brouk s lesklým černým krunýřem a obrovskými kusadly, živí se hlodavci, na postavy útočí jen v nouzi či při napadení. Kusadly se zakusuje do nohy a nepustí — oběť ztrácí 1 život/kolo, dokud brouk (OČ v tu chvíli −5) nezemře nebo se kusadla nerozevřou (past Sil(9) ~ rozevření/nic). Samičky jsou slabší, s menšími kusadly (nebezpečnost rozevření 7). Létají jen při hledání samičky.');
INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator)
SELECT (SELECT id FROM nestvury WHERE nazev='Roháč obří' ORDER BY id DESC LIMIT 1), id, NULL FROM kody_zranitelnosti WHERE kod IN ('B','C','D','G','H','I','J','K','L');

INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, odolnost, velikost, bojovnost, pohyblivost, vytrvalost, manevrovaci_schopnost, inteligence, poklady, zkusenost, ochoceni, prostredi, popis) VALUES
('Vážka jeskynní', '1', '(0+2/–1)=2/–1 (kusadla) + zvl.', '(+4+1)=5', '15', 'A', '6', '15/hmyz (na zemi), 10/okřídlenec (ve vzduchu)', '13/okřídlenec', '19', '1', 'nic, 100/0 hnízdo', 10, '9', 'podzemní jezera, na povrch jen v noci',
 'Podobná říční vážce, asi sáh dlouhá. Živí se drobnými hlodavci, hraničáře zabíjí modrými blesky (jako kouzlo modré blesky) z orgánu pod kusadly — denně má k dispozici 4 takové blesky (házej 4k6, 1–3 = ještě nevystřelený blesk). Infravidění na 30 sáhů, nesnáší přímé světlo a útočí na cokoliv ve svém zorném poli (pak má bojovnost 12 místo 6). V hnízdě po nočních výletech nashromáždí slušný poklad z lesklých předmětů. Po odstranění orgánu metajícího blesky je neškodná a cenná jako exotické zvíře pro voliéru.');
INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator)
SELECT (SELECT id FROM nestvury WHERE nazev='Vážka jeskynní' ORDER BY id DESC LIMIT 1), id, NULL FROM kody_zranitelnosti WHERE kod IN ('B','C','D','G','H','I','J','K','L');

-- Termit obří — kolonie se čtyřmi kastami (královna/bojovníci/dělníci/larvy+trubci),
-- vlastnosti jsou odlišné pro každou kastu; zapsáno souhrnně, detaily v popisu.
INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, odolnost, velikost, bojovnost, pohyblivost, vytrvalost, inteligence, charisma, zsm, presvedceni_id, poklady, zkusenost, prostredi, popis) VALUES
('Termit obří', 'královna 8, bojovníci 4, dělníci 2, larvy a trubci 1',
 'královna (−1+3)=2 (kusadla); bojovníci (+2+4)=6 (kusadla); dělníci (0+3)=3 (kusadla); larvy a trubci 0',
 'královna (−5+5)=0 (nepohyblivá); larvy (−3+3)=0; trubci (0+5)=5; bojovníci a dělníci (+2+5)=7',
 '20', 'B', '12 pro inteligenci 1', '5/hmyz', '23/hmyz', '1 (kolektivně 17, viz popis)', '14 (jen královna)', '9 nebo 10 (jen královna)',
 (SELECT id FROM presvedceni WHERE nazev='Neutrální'),
 '1 500/20 (v termitišti u královny)', 80, 'termitiště (kopulovité stavby) až 200×200 sáhů, uvnitř až 1000 termitů',
 'Vznikli kouzelnickým křížením, dvousáhoví bílí tvorové s tvrdým chitinovým pancířem. Královna má int 17, cha 14, schopnosti kouzelníka (mág/čaroděj dle volby PJ) na 6. úrovni, nelze ji podrobit, lze ji vyzvat na mentální souboj; nepohybuje se ani nemluví, telepaticky řídí termity v okruhu 200 sáhů (sdílejí její inteligenci a informace); mimo termitiště vyslaná skupina má jen inteligenci 1. Po smrti královny telepatické spojení zaniká a termiti se stávají všežravými tvory bez cíle mimo shánění potravy. Bojovníci v boji nepřestanou, dokud nezvítězí nebo nezemřou, ale nepřekročí plameny.');
INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator)
SELECT (SELECT id FROM nestvury WHERE nazev='Termit obří' ORDER BY id DESC LIMIT 1), id, NULL FROM kody_zranitelnosti WHERE kod IN ('B','C','D','H','I','J','K','L');
INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator) VALUES
((SELECT id FROM nestvury WHERE nazev='Termit obří' ORDER BY id DESC LIMIT 1), (SELECT id FROM kody_zranitelnosti WHERE kod='G'), '1/2'),
((SELECT id FROM nestvury WHERE nazev='Termit obří' ORDER BY id DESC LIMIT 1), (SELECT id FROM kody_zranitelnosti WHERE kod='M'), NULL),
((SELECT id FROM nestvury WHERE nazev='Termit obří' ORDER BY id DESC LIMIT 1), (SELECT id FROM kody_zranitelnosti WHERE kod='P'), NULL);
-- M a P se vztahují jen na královnu ("královna + M, P" v předloze), viz popis.

INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, odolnost, velikost, bojovnost, pohyblivost, vytrvalost, manevrovaci_schopnost, inteligence, poklady, zkusenost, prostredi, popis) VALUES
('Ohnivec', '4 + 2', '(+3 + 4) = 7 (kusadla)', '(+3 + 5) = 8', '19', 'A až B', '11', '5/hmyz (na zemi); 7/plaz (ve vzduchu)', '21/hmyz', '5', '0', 'nic', 170, 'podzemí, bažiny, u řek, hluboké hvozdy',
 '1–2 sáhy dlouzí noční brouci. Jméno dostali podle fosforeskujícího pancíře (osvětluje okruh 2 sáhů), po smrti svítí ještě asi 2 hodiny.');
INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator)
SELECT (SELECT id FROM nestvury WHERE nazev='Ohnivec' ORDER BY id DESC LIMIT 1), id, NULL FROM kody_zranitelnosti WHERE kod IN ('B','C','D','H','I','J','K','L');
INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator) VALUES
((SELECT id FROM nestvury WHERE nazev='Ohnivec' ORDER BY id DESC LIMIT 1), (SELECT id FROM kody_zranitelnosti WHERE kod='G'), '1/2');

INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, odolnost, velikost, bojovnost, pohyblivost, vytrvalost, manevrovaci_schopnost, inteligence, poklady, zkusenost, prostredi, popis) VALUES
('Brouk třasotník', '3 + 1', '(+2 + 2) = 4 (kusadla); (+2 + 2/7) = 4/7 (s rozletem)', '(+3 + 4) = 7', '18', 'A', '11', '6/hmyz (na zemi); 9/plaz (ve vzduchu)', '20/hmyz', '4', '0', 'nic', 120, 'lesy, u mýtin',
 'Dostal jméno podle charakteristického třesu krovek, který se rozléhá lesem. Čeká na stromě u mýtiny, na procházející zvěř se vrhá plachtěním s roztaženými krovkami a útočí dlouhým zoubkovaným kusadlem. Při netrefení oběti sám při dopadu na zem utrpí 2–12 životů zranění. Rozmnožuje se rychle, takže riskantní způsob lovu populaci nehubí.');
INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator)
SELECT (SELECT id FROM nestvury WHERE nazev='Brouk třasotník' ORDER BY id DESC LIMIT 1), id, NULL FROM kody_zranitelnosti WHERE kod IN ('B','C','D','H','I','J','K','L');
INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator) VALUES
((SELECT id FROM nestvury WHERE nazev='Brouk třasotník' ORDER BY id DESC LIMIT 1), (SELECT id FROM kody_zranitelnosti WHERE kod='G'), '1/2');
-- Text uvádí "G 1/2, mráz G 1/2" duplicitně pro totéž — zapsáno jen jednou.

-- Hnus plíživý
INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, odolnost, velikost, bojovnost, pohyblivost, inteligence, poklady, zkusenost, popis) VALUES
('Hnus plíživý', '12', '3 + zvl.', '(−3 + 5) = 2', '21', 'C', '12', '1/magický tvor', '0', 'nic', 270,
 'Nezdravě vyhlížející namodralá obří améba, zranitelná jen ohněm, mrazem, fyzickými kouzly a blesky. Protahuje se škvírami, za jedno kolo zničí dřevo, kůži a podobné materiály (kov a skálu neprojde). Zvláštní útok: leptání — při dotyku holé kůže způsobuje 2–12 životů zranění za kolo (menší exempláře jen poloviční); vydává zvuky mezi mlaskáním a smíchem.');
INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator)
SELECT (SELECT id FROM nestvury WHERE nazev='Hnus plíživý' ORDER BY id DESC LIMIT 1), id, NULL FROM kody_zranitelnosti WHERE kod IN ('G','J','K','L');

INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, odolnost, velikost, bojovnost, pohyblivost, vytrvalost, inteligence, poklady, zkusenost, prostredi, popis) VALUES
('Huňáč modrý', '4', '(0+2/+1)=2/+1 (drápy) + zvl.', '(+2+4)=6', '11', 'A', '8', '13/šelma', '11/šelma', '1', 'nic, 300/7 doupě', 80, 'doupata, sbírá barevné předměty',
 'Asi sáh dlouhý tvor kočkovitého vzhledu s modrou srstí a očima žhnoucíma modře ve tmě. Zbraně nepoužívá, útočí drápy; rád sbírá barevné věci do doupěte. Zvláštní útok: akumulace magenergie — dokáže "vysát" až 1 mag za kolo od kouzelníka (nepůsobí na vázanou magenergii alchymistických předmětů ani na hraničářskou magenergii), sbírá postupně od více obětí; při 3 nasbíraných magech příští kolo z něj vyšlehnou modré blesky (jako kouzlo modré blesky). V kole útočí buď blesky, nebo drápy.');
INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator)
SELECT (SELECT id FROM nestvury WHERE nazev='Huňáč modrý' ORDER BY id DESC LIMIT 1), id, NULL FROM kody_zranitelnosti WHERE kod IN ('B','C','D','G','H','I','J','K','L');

INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, odolnost, velikost, bojovnost, pohyblivost, vytrvalost, inteligence, poklady, zkusenost, popis) VALUES
('Huňáč zelený', '8', '(2 + 3/+1) = 5/+1 (základní podoba) + zvl.', '(+3 + 5) = 8', '15', 'B', '10', '14/šelma', '12/šelma', '1', 'nic', 300,
 'Asi dva sáhy dlouhý tvor kočkovitého vzhledu se zelenou srstí, ve tmě zeleně září. Umí měnit tvar (1 kolo, po dobu proměny neútočí) na jakékoli zvíře či postavu, kterou viděl, ale vždy zůstává nádechem zelený. Zvláštní útok: akumulace magenergie — pohltí až 2 magy za kolo (nepůsobí na vázanou magenergii alchymistických předmětů), po nasbírání 4 magů příští kolo z očí vyšlehne zelený blesk (jako kouzlo zelené blesky). Poklady nesbírá, jen má v oblibě zelenou barvu.');
INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator)
SELECT (SELECT id FROM nestvury WHERE nazev='Huňáč zelený' ORDER BY id DESC LIMIT 1), id, NULL FROM kody_zranitelnosti WHERE kod IN ('B','C','D','G','H','I','J','K','L');

-- ---------------------------------------------------------------------
-- Hvozd — nestvůry vázané na toto prostředí
-- ---------------------------------------------------------------------

-- Bludička — netělesná bytost bez klasického boje (ÚČ/OČ/odolnost/zranitelnost
-- v předloze uvedeny jako "—", nelze jí ublížit ani ji podrobit).
INSERT INTO nestvury (nazev, zivotaschopnost, velikost, pohyblivost, inteligence, charisma, presvedceni_id, poklady, prostredi, popis) VALUES
('Bludička', '1', 'A', '18/magický tvor', '18', '15',
 NULL,
 'nic', 'bažiny a podmáčená místa hvozdu',
 'Netělesný noční tvor bludných světélek tančících na těžko přístupných místech hvozdu. Nelákají poutníky záměrně do záhuby (to je pověra) — lidská zvědavost dělá zbytek. Komunikují telepaticky, umí oslovit inteligentní bytosti v dohledu, ale číst myšlenky neumí — jen ty "dobrovolně odtajněné". Žijí ve svazku s druidy: druid je může kouzlem bludička ovládnout do svítání, ale bludička odmítá činy odporující jejímu (dobrému) přesvědčení a při krajním dilematu může navždy zhasnout. Nelze jim ublížit ani je podrobit/vyzvat na mentální souboj — jsou netělesné, nikoli však přímo magické. Přes den spí ve vykotlaných pařezech v srdci hvozdu. Přesvědčení zákonné dobro nebo zmatené dobro (v tabulce presvedceni_id ponecháno NULL, protože pole umožňuje jen jednu hodnotu — viz text). Příbuzná neklidné záři.');

-- Oživlé stromy — mají místo klasického stat bloku past-mechaniku (Obr/past),
-- ne pevná čísla ÚČ/OČ/odolnosti — viz popis. TODO ověřit proti skenu.
INSERT INTO nestvury (nazev, velikost, inteligence, presvedceni_id, prostredi, popis) VALUES
('Oživlé stromy', 'C až D (dle tloušťky kmene)', 'jako druid (ovládající hvozd)', (SELECT id FROM presvedceni WHERE nazev='Neutrální'), 'probuzený hvozd od 3. stupně probuzenosti',
 'Netolerantní ke všem cizincům v lese, snaží se je vystrnadit — útočí drcnutím, ve větším počtu se snaží vetřelce rozmačkat mezi sebou. Pomalé, snadno utíkatelné, ale hvozd nechá vetřelce nejdřív zajít hlouběji, než zaútočí. Boj řešen jako past, ne klasickým ÚČ/OČ: jeden strom = past Obr(−1) ~ nic/zasažení, nebezpečnost roste o 1 za každý další útočící strom; drcnutí jedním stromem = past Odl(1) ~ nic/1–6 životů, více stromy = past Odl(−počet stromů) ~ 1–6/2–20 životů. OČ (3–10) a počet životů (10–50) závisí na stáří a tloušťce stromu — určuje PJ. -- TODO past-mechanika místo klasického stat bloku, ověřit proti skenu.');

INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, odolnost, velikost, bojovnost, pohyblivost, inteligence, charisma, presvedceni_id, poklady, zkusenost, prostredi, popis) VALUES
('Velký zlý strom', '40', '(+7 + 3) = 10 (větve); (+7 + 5/+2) = 12/+2 (tlama)', '(−2 + 9) = 7', '22', 'D', '12', '8/magický tvor', '4', '2',
 (SELECT id FROM presvedceni WHERE nazev='Neutrální'),
 'nic', 1800, 'hvozd, vyvolán druidovým kouzlem nebo dostatečně probuzeným hvozdem',
 'Vzhled odpovídá druidovu kouzlu vyvolej velký zlý strom. Vzniká seslaným kouzlem, nebo ho v ohrožení vyvolá sám probuzený hvozd — i tak musí poslechnout každého druida na doslech; ovládat ho telepaticky lze, jen je-li s ním druid v přímém kontaktu (ústní rozkaz k zakořenění neuposlechne). Nikdy nenapadne druida.');

