INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, odolnost, velikost, bojovnost, inteligence, poklady, zkusenost, ochoceni, prostredi, popis) VALUES
('Jelen', '3 + 2', '(+1 + 4/+1) = 5/+1 (jelen – parohy); (+1 + 3) = 4 (kopyta)', '(+2 + 1) = 3', '12', 'C', '4', '1', 'nic', 30, '6', 'listnaté lesy mírného pásma',
 'Býložravec, člověka napadne, jen je-li zraněn nebo zahnán do pasti. Pohyblivost a vytrvalost jako u jezdeckých zvířat (str. 124, v tomto zdroji samostatně nepřepsáno). Lze lovit i využít jako jezdecké zvíře.');

