INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, odolnost, velikost, bojovnost, inteligence, poklady, zkusenost, prostredi, popis) VALUES
('Obří kůň', '6', '(+2+4)=6 (kopyta)', '(+2+1)=3', '15', 'C', '4', '1', 'nic', 70, 'používán obry',
 'Mohutností a masivností daleko převyšuje ostatní plemena, není zcela domestikovaný (i zkrocený zůstává polodivoký), velmi samostatný a nepoddajný. Při prvním útoku s rozběhem má bonus +6 k ÚČ; postavy útočící zblízka/z boku musí každé kolo hodit past Obr(5) ~ nic/sražení a pád za 20–25 životů. Nájezd obrů na těchto koních bývá pohromou pro celý kraj. Váha 24000–26000 mn.');
