INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, odolnost, velikost, bojovnost, pohyblivost, inteligence, charisma, presvedceni_id, poklady, zkusenost, prostredi, popis) VALUES
('Kanibal', '1 + 2', '0 + síla zbraně', '+3 + kvalita zbroje', '11', 'B', '5', '13/humanoid', '7', '6',
 (SELECT id FROM presvedceni WHERE nazev='Zmatené zlo'),
 '10/0, 600/20 vesnice', 20, 'ostrovy a husté pralesy',
 'Člověku podobná bytost černé pleti, bojuje oštěpem nebo foukačkou se šípy namočenými v kuraré (SZ 5, zásah vždy jen 1 život, dostřel 5/9/12). Zpravidla polonazí (KZ 1) nebo ve zvířecích kůžích (KZ 2, max. 3), občas se štítem. Žijí nomádsky v tlupách 30–130 ve vesnicích 10–60 chatrčí; šamanova chýše (usušené lebky, rituální předměty) může obsahovat 1–6 kouzelných předmětů.');
INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator)
SELECT (SELECT id FROM nestvury WHERE nazev='Kanibal' ORDER BY id DESC LIMIT 1), id, NULL FROM kody_zranitelnosti WHERE kod IN ('A','B','C','D','G','H','I','J','K','L','M','O');

INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, odolnost, velikost, pohyblivost, vytrvalost, inteligence, charisma, presvedceni_id, poklady, zkusenost, prostredi, popis) VALUES
('Kentaur', '3 + 3', '(0+4)=4 (kopyta); +5 + dlouhý luk (2–5 krát za kolo)', '(+5+1)=6', '13', 'C', '20/zvěř', '15/zvěř', '13', '10',
 (SELECT id FROM presvedceni WHERE nazev='Neutrální'),
 '25/0, 400/10 vesnice', 130, 'úrodné travnaté stepi',
 'Mýtický národ napůl lidí, napůl koní — trup a paže člověka, čtyřnohé koňské tělo. Žijí ve vesnicích slaměných domů podobných stáním, spravovaných náčelníky, spojují se jen v ohrožení. Vynikající lučištníci s velkými tisovými luky — mladí vystřelí 2 šípy za kolo, staří zkušení až 5; udržují systém hlídek ve vysoké trávě. V boji bojují seřazenými oddíly a manévrují, aby se k nim nepřítel nedostal na dosah. Mimo luk téměř nepoužívají jiné zbraně. Hrdí, opovrhují jinými rasami a nesnášejí těsná města, proto se v žoldnéřských armádách prakticky nevyskytují.');
INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator)
SELECT (SELECT id FROM nestvury WHERE nazev='Kentaur' ORDER BY id DESC LIMIT 1), id, NULL FROM kody_zranitelnosti WHERE kod IN ('A','B','C','D','G','H','I','J','K','L','M','O');

INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, odolnost, velikost, bojovnost, pohyblivost, vytrvalost, inteligence, poklady, zkusenost, popis) VALUES
('Keř dravý', '6 + 3 životy za každou větev', 'pouze zvl.', '4 (tlama); 6 (větve v pohybu); 2 (větve omotané kolem oběti)', '8', 'C', '12', '1/plaz', '21/plaz', '0', '1000/0', 180,
 'Navenek vypadá jako obyčejný keř s hustým listím, ve skutečnosti bezinteligentní živočich živící se hlavně masem (fotosyntéza jen doplňkově); "listy" jsou ve skutečnosti šupiny na maskovaných chapadlech-větvích. Při přiblížení oběti se dosud nehybné větve bleskurychle omotají (první útok vždy s překvapením) — na jednu postavu útočí 2–7 větví, každá s ÚČ 4, zbroj se do OČ nepočítá; zranění od větví jsou jen stínová. Jsou-li omotány alespoň 2 větve, oběť je lapena a nemůže se osvobodit; keř ji pak 2 kola dopravuje k ústnímu otvoru (2,5 sáhu vysokému jícnu plnému zubů), kde ztrácí 3–18 životů za kolo. Keř neútočí, jen když měl útočník zbraň v ruce a odolnost 15+ (pak OČ keře 0). Postavy mohou útočit na jednotlivé větve (každá má 3 životy, useknuté dorostou) nebo na tlamu.');
INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator)
SELECT (SELECT id FROM nestvury WHERE nazev='Keř dravý' ORDER BY id DESC LIMIT 1), id, NULL FROM kody_zranitelnosti WHERE kod IN ('B','C','D','H','I','J','L');
INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator) VALUES
((SELECT id FROM nestvury WHERE nazev='Keř dravý' ORDER BY id DESC LIMIT 1), (SELECT id FROM kody_zranitelnosti WHERE kod='G'), '2'),
((SELECT id FROM nestvury WHERE nazev='Keř dravý' ORDER BY id DESC LIMIT 1), (SELECT id FROM kody_zranitelnosti WHERE kod='K'), '2');
-- Zapsáno jako "zvíře, ale G 2, K 2" — dvojnásobná zranitelnost ohni/mrazu a mrazivým/ohnivým kouzlům.

-- Kobold — stat blok je v předloze rozdělen na dvě tabulky se stránkovým
-- zlomem ("dokončeno na str. 149"), sloučeno do jednoho řádku.
INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, odolnost, velikost, bojovnost, inteligence, charisma, presvedceni_id, poklady, zkusenost, prostredi, popis) VALUES
('Kobold', '4', '(+3 + 5) = 8 (zobák); +3 + síla zbraně', '(−1 + 1 + štít) = 1', '13', 'B', '4 (samice)', '10 (samci); 3 (samice)', '8 (samci); 5 (samice)',
 (SELECT id FROM presvedceni WHERE nazev='Zmatené zlo'),
 '5/0, 2500/0 sídlo', 80, 'kmenová sídla a hvozdy',
 'Pronárod se slepičí hlavou a ostrými zoubky, jinak dosti podobný lidem — bojuje raději zbraněmi než přirozeným zobákem, dokud není rozzuřen. Žije v kmenech, vede je náčelník "Velký kohout" (rudý hřebínek, životaschopnost 12) s asi 8 pomocníky (oranžové hřebínky, životaschopnost 8). Mluva připomíná kvokání, mají zvláštní vztah k lasičkám.');
INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator)
SELECT (SELECT id FROM nestvury WHERE nazev='Kobold' ORDER BY id DESC LIMIT 1), id, NULL FROM kody_zranitelnosti WHERE kod IN ('A','B','C','D','G','H','I','J','K','L','M','O');

INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, odolnost, velikost, bojovnost, pohyblivost, vytrvalost, inteligence, poklady, zkusenost, prostredi, popis) VALUES
('Kopromlask', '½ (1–4 životy)', '(0+3)=3 (kousnutí)', '(+2+1)=3', '5', 'A', '12', '4/hmyz', '16/hmyz', '0', 'nic', 4, 'místa nedávných bojů',
 'Neužitečný obtížný zelený červ (30–60 coulů), objevuje se do 3 směn po bitvě a živí se krví a odpadem z padlých. Velmi nesnášenlivý — komukoli nablízku útočí s překvapením na nohy za automatický 1 život. Vyskytují se v hejnech po 3–8; zbavit se jich lze jen odchodem z bojiště a důkladným umytím krve.');
INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator)
SELECT (SELECT id FROM nestvury WHERE nazev='Kopromlask' ORDER BY id DESC LIMIT 1), id, NULL FROM kody_zranitelnosti WHERE kod IN ('B','C','D','G','H','I','J','K','L');

INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, odolnost, velikost, pohyblivost, inteligence, charisma, zsm, presvedceni_id, poklady, zkusenost, prostredi, popis) VALUES
('Kostěj nesmrtelný*', '7 + 3', '+8 + síla zbraně; (+8 + 5) = 13 (paráty)', '(+5 + 6) = 11', '25', 'C', '27/drak', '18', '15', '19',
 (SELECT id FROM presvedceni WHERE nazev='Zákonné zlo'),
 '300/5, 5000/100 sídlo', 500, 'věž či pevnost stranou civilizace',
 '2,5 sáhu vysoká humanoidní nestvůra s kostěným hřebenem, planoucíma jantarovýma hmyzíma očima a žabí tlamou plnou zubů; tělo tvrdé jako kámen, hubené, ale nesmírně silné, z trupu trčí žebrovité výrůstky (odtud jméno) bez souvislosti se skutečnou kostrou, nenosí brnění ani šaty. Žije obklopen živými i nemrtvými služebníky. Denně 25 magů, umí kouzelnická kouzla. Zvláštní útok: upřený pohled znehybní toho, kdo mu pohlédne do očí (past nebezpečnost Int+Roz(8) ~ nic/znehybnění během 2 kol); neúspěch = 1–6 směn nehybnosti, během níž mu kostěj ve třech kolech posune přesvědčení o stupeň ke zlu. Po procitnutí může znehybnit znovu, ale přesvědčení téže postavy podruhé ovlivnit nemůže.');
INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator) VALUES
((SELECT id FROM nestvury WHERE nazev='Kostěj nesmrtelný*' ORDER BY id DESC LIMIT 1), (SELECT id FROM kody_zranitelnosti WHERE kod='A'), '1/4'),
((SELECT id FROM nestvury WHERE nazev='Kostěj nesmrtelný*' ORDER BY id DESC LIMIT 1), (SELECT id FROM kody_zranitelnosti WHERE kod='C'), '1/2'),
((SELECT id FROM nestvury WHERE nazev='Kostěj nesmrtelný*' ORDER BY id DESC LIMIT 1), (SELECT id FROM kody_zranitelnosti WHERE kod='H'), NULL),
((SELECT id FROM nestvury WHERE nazev='Kostěj nesmrtelný*' ORDER BY id DESC LIMIT 1), (SELECT id FROM kody_zranitelnosti WHERE kod='I'), '1/2'),
((SELECT id FROM nestvury WHERE nazev='Kostěj nesmrtelný*' ORDER BY id DESC LIMIT 1), (SELECT id FROM kody_zranitelnosti WHERE kod='J'), '1/2'),
((SELECT id FROM nestvury WHERE nazev='Kostěj nesmrtelný*' ORDER BY id DESC LIMIT 1), (SELECT id FROM kody_zranitelnosti WHERE kod='K'), '1/2'),
((SELECT id FROM nestvury WHERE nazev='Kostěj nesmrtelný*' ORDER BY id DESC LIMIT 1), (SELECT id FROM kody_zranitelnosti WHERE kod='N'), NULL),
((SELECT id FROM nestvury WHERE nazev='Kostěj nesmrtelný*' ORDER BY id DESC LIMIT 1), (SELECT id FROM kody_zranitelnosti WHERE kod='P'), NULL);
-- H má navíc kvalifikátor H+ (jen magické jedy), P kvalifikátor P+ (sám útočí mentálně); "I J K 1/2" v předloze bez čárek — modifikátor 1/2 aplikován na všechny tři, TODO ověřit dělení proti skenu.

-- Kovboj — jen odkaz na heslo Handlíř, bez vlastního stat bloku, nezakládáme samostatný řádek.

INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, odolnost, velikost, pohyblivost, vytrvalost, inteligence, poklady, zkusenost, popis) VALUES
('Kožožrout', '1 nebo 2 životy', 'pouze zvl.', '0', '11', 'A0', '0/magický tvor', '0/magický tvor', '0', 'nic', 1,
 'Na první pohled vypadá jako drahokam, na omak teplý. Zvláštní útok: požírání — číhá mezi poklady, hrdinové ho obvykle nevědomky vloží do tlumoku, kde se pak nenápadně živí kůží (rovnoměrně ji vstřebává, takže tlumok se náhle úplně rozpadne a věci se vysypou/rozbijí). Usmrtit lze vodou, ohněm i pouhým úderem — pak se změní v růžovou kapku, která se rychle vypaří.');
INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator)
SELECT (SELECT id FROM nestvury WHERE nazev='Kožožrout' ORDER BY id DESC LIMIT 1), id, NULL FROM kody_zranitelnosti WHERE kod IN ('B','C','D','G','H','I','J','K','L');

INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, odolnost, velikost, bojovnost, pohyblivost, vytrvalost, manevrovaci_schopnost, inteligence, poklady, zkusenost, prostredi, popis) VALUES
('Krab obří', '12 + 3', '(+5 + 5) = 10 (klepeta 2× za kolo); (+3 + 1) = 4 (kousnutí)', '(+2 + 6) = 8 (trup); (+2 + 4) = 6 (klepeta)', '30', 'C', '12', '14/vodní tvor (ve vodě); 10/šelma (na suchu)', '13/šelma (na suchu)', '13', '1', 'nic', 690, 'mořské a slané dno, mokřiny, přímoří',
 'Asi 2 sáhy vysoký, válcovité tělo o průměru 3 sáhy. Všežravý, útočí na cokoli slabšího a nenasyceného pohledem. Bojuje klepety (2 útoky za kolo na dvě různé postavy), na kousnutí přejde až po ztrátě obou klepet, po ztrátě druhého klepeta prchá. Postavy mohou útočit na trup nebo na klepeta (každé má třetinu původních životů, useknuté dorůstá); na trup je bonus +2 sekerou/kladivem, +1 těžkým kyjem, postih −1 sečnými, −2 bodnými, −3 na střelbu (u klepet stejně, ale šípy postih neplatí).');
INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator)
SELECT (SELECT id FROM nestvury WHERE nazev='Krab obří' ORDER BY id DESC LIMIT 1), id, NULL FROM kody_zranitelnosti WHERE kod IN ('B','C','D','I','J','L');
INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator) VALUES
((SELECT id FROM nestvury WHERE nazev='Krab obří' ORDER BY id DESC LIMIT 1), (SELECT id FROM kody_zranitelnosti WHERE kod='H'), NULL),
((SELECT id FROM nestvury WHERE nazev='Krab obří' ORDER BY id DESC LIMIT 1), (SELECT id FROM kody_zranitelnosti WHERE kod='G'), '1/2'),
((SELECT id FROM nestvury WHERE nazev='Krab obří' ORDER BY id DESC LIMIT 1), (SELECT id FROM kody_zranitelnosti WHERE kod='K'), '1/2');
-- H má navíc kvalifikátor H+ (jen magické jedy); G poloviční jen na oheň dle textu "oheň G 1/2".

INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, odolnost, velikost, bojovnost, pohyblivost, vytrvalost, inteligence, poklady, zkusenost, popis) VALUES
('Krysí hejno', '25', '7 (zuby)', '0', '9', 'C', '12', '9/šelma', '6/šelma', '1', 'nic', 400,
 'Reprezentuje zhruba 80 krys jako jedna souhrnná nestvůra namísto počítání jednotlivých zvířat z hesla Krysy obyčejné — usnadňuje boj s velkými smečkami. Útočí na každou postavu stojící na zemi každé kolo; počet zbývajících životů hejna se dělí 1,5, aby vyšel počet krys v hejnu. Početnější hejna zaútočí na jednu postavu i vícekrát za kolo.');
INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator)
SELECT (SELECT id FROM nestvury WHERE nazev='Krysí hejno' ORDER BY id DESC LIMIT 1), id, NULL FROM kody_zranitelnosti WHERE kod IN ('B','C','D','G','H','I','J','K','L');

INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, odolnost, velikost, bojovnost, pohyblivost, vytrvalost, inteligence, poklady, zkusenost, prostredi, popis) VALUES
('Krysy obří', '1', '(0+2)=2 (zuby)', '(0+1)=1', '8', 'A (řídce i B)', '7', '11/šelma', '9/šelma', '1', 'nic, 40/0 doupě', 5, 'temné kouty podzemí, místa s nemrtvými',
 'Asi sáh dlouhá krysa s tvrdou štětinatou srstí, hbitá na svou velikost, živí se zbytky obětí nemrtvých a odtahuje si je do doupěte, kde lze najít cennější pozůstatky. Krysodlak kolem sebe může shromáždit gardu 1–10 zvlášť mohutných obřích krys se životaschopností 3.');
INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator)
SELECT (SELECT id FROM nestvury WHERE nazev='Krysy obří' ORDER BY id DESC LIMIT 1), id, NULL FROM kody_zranitelnosti WHERE kod IN ('B','C','D','G','H','I','J','K','L');

INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, odolnost, velikost, bojovnost, pohyblivost, vytrvalost, inteligence, poklady, zkusenost, ochoceni, prostredi, popis) VALUES
('Krysy obyčejné', '1 nebo 2 životy', '0 (zuby)', '(–1+1)=0', '5', 'A0', '12 v hejnu, jinak 4', '9/šelma', '6/šelma', '1', 'nic', 1, '7', 'podzemí',
 'Téměř nejslabší nestvůra Bestiáře, nebezpečná jen v obrovských hejnech (kolem 100 kusů), útočí jako "přílivová vlna". Bojí se ohně — každá zapálená pochodeň sníží jejich bojovnost o 1, silnější oheň je obrátí na útěk (na 1–6 směn, pak se vracejí, hrozí-li jim nebezpečí). Zvláštní útok postav proti nim: plošné zbraně zasáhnou víc krys najednou (střední zbraň 1–3, dlouhá 1–6, dlouhá obouruční 1–10 krys za jeden hod na útok, každá zasažená krysa hází na obranu zvlášť).');
INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator)
SELECT (SELECT id FROM nestvury WHERE nazev='Krysy obyčejné' ORDER BY id DESC LIMIT 1), id, NULL FROM kody_zranitelnosti WHERE kod IN ('B','C','D','G','H','I','J','K','L');

INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, odolnost, velikost, bojovnost, pohyblivost, vytrvalost, inteligence, poklady, zkusenost, ochoceni, popis) VALUES
('Kůň', '3', '(0+4)=4 (kopyta)', '(+2+1)=3', '10', 'C', '3', '18/zvěř', '14/zvěř', '1', 'nic', 30, '7',
 'Základní typ koně z Pravidel pro začátečníky (odlišný od rozšířeného systému jezdeckých nestvůr — viz Klasický/Jezdecký/Tažný/Válečný/Obří/Ušlechtilý kůň a Pony). Cena kolísá od desítek do desetitisíců zlaťáků; dražší kůň může být rychlejší a životaschopnější, levný kůň (kolem 70 zl) má nosnost jen 300 mn (max. naložení 1200 mn) a je pomalejší než průměrný hobit. Divocí mustangové jdou zkrotit, ale nesnadno.');
INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator)
SELECT (SELECT id FROM nestvury WHERE nazev='Kůň' ORDER BY id DESC LIMIT 1), id, NULL FROM kody_zranitelnosti WHERE kod IN ('B','C','D','G','H','I','J','K','L');

