INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, odolnost, velikost, bojovnost, pohyblivost, vytrvalost, inteligence, poklady, zkusenost, ochoceni, popis) VALUES
('Lasička obří', '1 + 1', '(+1 + 3) = 4 (zuby 2× za kolo)', '(+5 + 2) = 7', '11', 'A', '7', '16/šelma', '12/šelma', '1', 'nic', 15, '6',
 'Sáh dlouhá velmi rychlá lasička, loví menší živočichy (zvláště krysy). Lze ji vycvičit k lovu, ale bojí se psů a útočí na přátele, a pokud ji cvičitel pošle proti nepříteli nad její síly, obvykle navzdory ochočení uteče.');
