-- Lemrouch — magická "guvernantka" princezen, nezvyklý typ CP.
INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, odolnost, velikost, pohyblivost, inteligence, charisma, zsm, presvedceni_id, poklady, zkusenost, prostredi, popis) VALUES
('Lemrouch¹', '7', '(+3 + 5/+1) = 8/+1 (tlama) + zvl.', '+5 + 4 = 9', '18', 'C', '18/zvěř', '13', '5', '10',
 (SELECT id FROM presvedceni WHERE nazev='Neutrální'),
 'nic', 260, 'palácová zahrada pod princezniným oknem',
 'Magická bytost vzhledu obrovské (2 sáhy) ošklivé mluvící žáby, sama sebe označuje za ženu. Slouží jako dokonalá guvernantka princezen — vzdělává je a chrání jejich ctnost, útočí na kohokoli nemístného vůči princezně (od flirtu ignoruje, přes pokárání zahradníka, až po zabití banditů/dotěrných šlechticů). Prakticky nesmrtelná, věří, že ji polibek muže s modrou krví promění v princeznu (1% šance při prvním polibku na skutečnou proměnu v krásnou dívku s charismou 21, zamilovanou do dotyčného). Zvláštní útok: zasednutí — může zasednout tvory velikosti A0 až C ohrožující princeznu (past Obr(−12) ~ nic/zasažení, poté past Odl(−12) ~ 10–100/10–100×úroveň); skáče až 8 sáhů dlouhými skoky. Políbit ji je samo o sobě past Odl(−8) ~ polibek/mdloby. Funkci končí zasnoubením princezny, poté odchází do výslužby nebo je prodán/pronajat jinam.');
INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator)
SELECT (SELECT id FROM nestvury WHERE nazev='Lemrouch¹' ORDER BY id DESC LIMIT 1), id, NULL FROM kody_zranitelnosti WHERE kod IN ('B','C','D','G','I','J','K','L');
INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator) VALUES
((SELECT id FROM nestvury WHERE nazev='Lemrouch¹' ORDER BY id DESC LIMIT 1), (SELECT id FROM kody_zranitelnosti WHERE kod='H'), NULL),
((SELECT id FROM nestvury WHERE nazev='Lemrouch¹' ORDER BY id DESC LIMIT 1), (SELECT id FROM kody_zranitelnosti WHERE kod='N'), NULL);
-- Zapsáno jako "zvíře, ale H+, N1": H omezeno na H+ (jen magické jedy), N s modifikátorem "1" — nejasné (možná normální/beze změny), TODO ověřit proti skenu.

INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, odolnost, velikost, bojovnost, pohyblivost, vytrvalost, inteligence, poklady, zkusenost, prostredi, popis) VALUES
('Lev horský', '11', '(+3 + 4/−2) = 7/−2 (drápy); (+3 + 3/+2) = 6/+2 (tlama)', '(+3 + 4) = 7', '15', 'B', '7', '15/šelma', '11/šelma', '1', 'nic', 410, 'hory, skály, jeskyně',
 'Starší, menší, ale houževnatější a rychlejší příbuzný obyčejného lva, stejně zbarven, žije v horách. Při prvním útoku s rozběhem bonus +3 na tlapy, snaží se srazit oběť k zemi (past Sil+Odl(13) ~ nic/sražení; sražená postava 1–6 kol nemůže vstát, bojovat ani kouzlit). V kole útočí tlapami i kousnutím, ale jen na jednu postavu.');
INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator)
SELECT (SELECT id FROM nestvury WHERE nazev='Lev horský' ORDER BY id DESC LIMIT 1), id, NULL FROM kody_zranitelnosti WHERE kod IN ('B','C','D','G','H','I','J','K','L');

INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, odolnost, velikost, bojovnost, pohyblivost, vytrvalost, inteligence, poklady, zkusenost, prostredi, popis) VALUES
('Lev obyčejný', '9', '(+4 + 4) = 8 (drápy) + (+4 + 5/+5) = 9/+5 (tlama)', '(+2 + 4) = 6', '15', 'B (lvice) až C (lev)', '8', '14/šelma', '9/šelma', '1', 'nic', 520, 'savany a polopouště',
 'Spíše mrchožrout, odhání skutečné lovce od kořisti, ale nucen k boji je strašným soupeřem. Při prvním útoku s rozběhem bonus +3 na tlapy, snaží se srazit oběť k zemi (past Sil+Odl(12) ~ nic/sražení; sražená postava 1–6 kol nemůže vstát, bojovat ani kouzlit). V kole útočí tlapami i kousnutím, jen na jednu postavu.');
INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator)
SELECT (SELECT id FROM nestvury WHERE nazev='Lev obyčejný' ORDER BY id DESC LIMIT 1), id, NULL FROM kody_zranitelnosti WHERE kod IN ('B','C','D','G','H','I','J','K','L');

INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, odolnost, velikost, pohyblivost, inteligence, charisma, presvedceni_id, poklady, zkusenost, prostredi, popis) VALUES
('Lid kočičí', '4', '(+5 + 4/+2) = 9/+2 (čepele 2× za kolo); (+5 + 3) = 8 (tesáky)', '(+5 + 1) = 6', '16', 'B', '22/humanoid', '14', '16',
 (SELECT id FROM presvedceni WHERE nazev='Neutrální'),
 'perly + 40/0, 2500/5 sídlo', 160, 'sídla kočičího lidu',
 'Kočkovití humanoidé vzrůstu elfů, chodí po zadních, nosí oděvy a zbraně jako lidé. Nenávidí nemrtvé (útočí na ně od pohledu), jsou zvědaví, ješitní, čistotní. Mohou pomoci družině, v nebezpečí jsou strašnými protivníky; mají přirozenou hrůzu z tygrodlaků. Bojují čepelemi na kovových náramcích na obou předních tlapách, brnění nenosí (kvůli obratnosti). Milují perly (jejich počet na oděvu značí rodové postavení), za ně bojují s kýmkoli mimo vlastní rod. Zvláštnost: mají devět "životů" — po usmrcení za 5–10 směn ožívají neranění, ale životy postupně ubývají od narození, takže postavy častěji potkají exempláře se sedmi a méně životy. Zkušenost se počítá za každé "zabití" zvlášť.');
INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator)
SELECT (SELECT id FROM nestvury WHERE nazev='Lid kočičí' ORDER BY id DESC LIMIT 1), id, NULL FROM kody_zranitelnosti WHERE kod IN ('A','B','C','D','G','H','I','J','K','L','M','O');

INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, odolnost, velikost, bojovnost, inteligence, poklady, zkusenost, ochoceni, prostredi, popis) VALUES
('Los', '6 + 1', '(+3 + 4) = 7 (parohy); (+1 + 4) = 5 (na útok zepředu); (+1 + 2) = 3 (na útok ze strany)', '(+1 + 5) = 6', '16', 'C', '8', '1', 'nic', 120, '7', 'divoké lesy s bažinami a výmoly',
 'Větší a silnější než jelen, nevypočitatelný, zvlášť nesnáší lidi a může napadnout osamělého člověka. Loven kvůli masu, dá se zkrotit jako jezdecké zvíře — často ho jezdí lesní víly.');
