INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, odolnost, velikost, inteligence, charisma, presvedceni_id, poklady, zkusenost, prostredi, popis) VALUES
('Medvědodlak (lidská podoba)', '15', '+6 + síla zbraně', '+1 + kvalita zbroje', '15', 'C', '17', '14',
 (SELECT id FROM presvedceni WHERE nazev='Neutrální'),
 '130/3, 800/10 doupě', 1735, 'osamělé lesní obydlí',
 'Rozvážný, dobrácký samotář žijící v ručně postaveném dřevěném domě, chce jen klid — družina si ho snadno splete s bývalým bojovníkem-poustevníkem. Obrovitý, zavalitý, chlupatý, se smyslem pro humor, přísný a spravedlivý. Vzácný zlý exemplář může díky vysoké inteligenci a dlouhověkosti dosáhnout až na panovníka království. V lidské podobě bojuje jakoukoli zbraní a dokáže dočasně ovládnout všechny medvědy v okolí, aby mu pomohli.');
