INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, odolnost, velikost, inteligence, charisma, zsm, presvedceni_id, poklady, zkusenost, prostredi, popis) VALUES
('Medúza⁺', '4', '–1 + síla zbraně + zvl.; +2 + dlouhý luk + zvl.', '(+2+1)=3', '18', 'B', '15', '8', '16',
 (SELECT id FROM presvedceni WHERE nazev='Zákonné zlo'),
 '20/0, 3 000/20 doupě', 240, 'opuštěný hrad či tvrz, sbírka soch',
 'Žena s hady místo vlasů a děsivým výrazem, který mění na kámen kohokoli, kdo se jí zadívá do tváře. Vyzbrojena dlouhým kostěným lukem a krátkým/širokým mečem, žije osaměle se sbírkou zkamenělých obětí. Zkamenění lze zrušit vyšším hraničářským kouzlem. Zvláštní útok: pohled do tváře = past nebezpečnost 12, síla nic/zkamenění, vlastnost charisma; uspěje-li oběť, promění se v kámen naopak sama medúza.');
INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator)
SELECT (SELECT id FROM nestvury WHERE nazev='Medúza⁺' ORDER BY id DESC LIMIT 1), id, NULL FROM kody_zranitelnosti WHERE kod IN ('A','B','C','D','G','I','J','K','L');
INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator) VALUES
((SELECT id FROM nestvury WHERE nazev='Medúza⁺' ORDER BY id DESC LIMIT 1), (SELECT id FROM kody_zranitelnosti WHERE kod='N'), NULL),
((SELECT id FROM nestvury WHERE nazev='Medúza⁺' ORDER BY id DESC LIMIT 1), (SELECT id FROM kody_zranitelnosti WHERE kod='P'), NULL);
-- Zapsáno jako "humanoid + N, P, ale H+, M 0, O 0": humanoid základ bez M a O (vyloučeny), navíc N a P; H omezeno na H+ (jen magické jedy).

INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, odolnost, velikost, bojovnost, pohyblivost, vytrvalost, inteligence, poklady, zkusenost, popis) VALUES
('Medvěd černý', '3 + 3', '(+2+2/+1)=4/+1 (drápy) + (+2+2/+1)=4/+1 (tlama)', '(0+3)=3', '13', 'C', '7', '15/šelma', '13/šelma', '1', 'nic', 65,
 'Zvaný též medvěd brtník, vzpřímený měří 2 sáhy. Býložravý, mírné až dobrácké povahy, ale po ochutnání zdechliny si zvykne na maso a stává se agresivnějším postrachem stád. V kole útočí tlapami i kousnutím, jen na jednu postavu. Nechá-li ho družina na pokoji, zaútočí jen zřídka.');
INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator)
SELECT (SELECT id FROM nestvury WHERE nazev='Medvěd černý' ORDER BY id DESC LIMIT 1), id, NULL FROM kody_zranitelnosti WHERE kod IN ('B','C','D','G','H','I','J','K','L');

INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, odolnost, velikost, bojovnost, pohyblivost, vytrvalost, inteligence, poklady, zkusenost, popis) VALUES
('Medvěd grizzly', '5 + 4', '(+4+2/+1)=6/+1 (drápy) + (+4+3/+1)=7/+1 (tlama)', '(+1+4)=5', '16', 'C', '9', '13/šelma', '11/šelma', '1', 'nic', 190,
 'Mnohem větší (až 3 sáhy vstoje), silnější a masožravější než medvěd černý, se stříbřitou srstí a divokou krutou povahou; znám i útok na mladého draka ze zálohy. Bojovat s ním se zavázanýma očima (pravidla pro boj s neviditelným) nebo s pomocí zrcátka (postih −4 na útok, nelze držet štít) omezuje jeho nebezpečnost — na medvěda nepůsobí psychická kouzla. Při prvním útoku s rozběhem bonus +4 na tlapy, snaží se srazit oběť k zemi (past Sil+Odl(14) ~ nic/sražení; sražený 1–6 kol nemůže vstát, bojovat ani kouzlit).');
INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator)
SELECT (SELECT id FROM nestvury WHERE nazev='Medvěd grizzly' ORDER BY id DESC LIMIT 1), id, NULL FROM kody_zranitelnosti WHERE kod IN ('B','C','D','G','H','I','J','K','L');
-- Pozn.: "na medvěda nepůsobí psychická kouzla" v textu — v rozporu se skupinovým zápisem "zvíře" (který M neobsahuje, takže je to konzistentní, jen zdůrazněno slovně).

INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, odolnost, velikost, bojovnost, pohyblivost, vytrvalost, inteligence, poklady, zkusenost, prostredi, popis) VALUES
('Medvěd kodiak', '12', '(+5 + 4/+1) = 9/+1 (drápy); (+5 + 6/+1) = 11/+1 (tlama)', '(+1 + 4) = 5', '20', 'C', '11', '12/šelma', '17/šelma', '1', 'nic', 610, 'severní pobřeží',
 'Větší příbuzný grizzlyho. Při prvním útoku s rozběhem bonus +4 na tlapy, snaží se srazit oběť k zemi (past Sil+Odl(14) ~ nic/sražení; sražený 1–6 kol nemůže vstát, bojovat ani kouzlit). V kole útočí tlapami i kousnutím, jen na jednu postavu. Kůže se dá zpracovat na kožené brnění KZ 2.');
INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator)
SELECT (SELECT id FROM nestvury WHERE nazev='Medvěd kodiak' ORDER BY id DESC LIMIT 1), id, NULL FROM kody_zranitelnosti WHERE kod IN ('B','C','D','G','H','I','J','K','L');

INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, odolnost, velikost, bojovnost, pohyblivost, vytrvalost, inteligence, poklady, zkusenost, prostredi, popis) VALUES
('Medvěd jeskynní', '15', '(+6 + 4/+1) = 10/+1 (drápy); (+6 + 5/+2) = 11/+2 (tlama)', '(+1 + 5) = 6', '26', 'D', '11', '14/šelma', '8/šelma', '1', 'nic', 890, 'jeskyně',
 'Pravěké až 5 sáhů dlouhé zvíře, největší a nejnebezpečnější z medvědů — i hladový drak mu raději uhne. Preferuje čerstvé maso, hladový neúnavně sleduje družinu díky vynikajícímu čichu. Při prvním útoku s rozběhem bonus +6 na tlapy, snaží se srazit oběť k zemi (past Sil+Odl(16) ~ nic/sražení; sražený 1–6 kol nemůže vstát, bojovat ani kouzlit). V kole útočí tlapami i kousnutím, jen na jednu postavu.');
INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator)
SELECT (SELECT id FROM nestvury WHERE nazev='Medvěd jeskynní' ORDER BY id DESC LIMIT 1), id, NULL FROM kody_zranitelnosti WHERE kod IN ('B','C','D','G','H','I','J','K','L');

INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, odolnost, velikost, bojovnost, pohyblivost, vytrvalost, manevrovaci_schopnost, inteligence, charisma, presvedceni_id, poklady, zkusenost, prostredi, popis) VALUES
('Medvěd lední', '10', '(+5 + 3/+1) = 8/+1 (drápy); (+5 + 4/+2) = 9/+2 (tlama)', '(+2 + 4) = 6', '18', 'C', '8', '12/šelma', '10/šelma', '16', '6', '5',
 (SELECT id FROM presvedceni WHERE nazev='Neutrální'),
 '10/0, 500/0 sídlo', 80, 'ledové pláně dalekého severu',
 'Protáhlé tělo, dlouhý krk, mohutné nohy, široké tlapy umožňující běh po sněhu bez boření. Žije samotářsky nebo ve velkých stádech, živí se rybami a mořskými tvory, na družinu zaútočí kvůli zásobám potravy jako vítané zpestření. Vynikající čich, umí plavat. Při prvním útoku s rozběhem bonus +5 na tlapy, snaží se srazit oběť k zemi (past Sil+Odl(15) ~ nic/sražení; sražený 1–6 kol nemůže vstát, bojovat ani kouzlit). V kole útočí tlapami i kousnutím, jen na jednu postavu.');
INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator)
SELECT (SELECT id FROM nestvury WHERE nazev='Medvěd lední' ORDER BY id DESC LIMIT 1), id, NULL FROM kody_zranitelnosti WHERE kod IN ('B','C','D','H','I','J','L');
INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator) VALUES
((SELECT id FROM nestvury WHERE nazev='Medvěd lední' ORDER BY id DESC LIMIT 1), (SELECT id FROM kody_zranitelnosti WHERE kod='G'), '1/2'),
((SELECT id FROM nestvury WHERE nazev='Medvěd lední' ORDER BY id DESC LIMIT 1), (SELECT id FROM kody_zranitelnosti WHERE kod='K'), '1/2');
-- Zapsáno jako "zvíře, ale oheň G 2, K 2, mráz G 1/2, K 1/2": lední medvěd je citlivější na oheň (2×) a odolnější vůči mrazu (1/2). Modifikátor G/K výše zapsán jako 1/2 pro mráz — TODO: pole modifikator neumí rozlišit oheň/mráz zvlášť u téhož kódu, viz obdobná poznámka u Bazliška; přesná hodnota pro variantu "oheň" (2×) je jen v tomto komentáři.

-- Místa se zvýšeným výskytem magenergie — prostředí/mechanika, ne nestvůra;
-- nezakládáme samostatný řádek (viz jednotlivé "tvory magického pole" níže).

INSERT INTO nestvury (nazev, zivotaschopnost, oc, velikost, pohyblivost, inteligence, poklady, zkusenost, prostredi, popis) VALUES
('Píšťík¹', '1–2 životy', '(−5 + 1) = 0', 'A0, vzácné A', '1/magický tvor', '0', 'nic', 2, 'kruh magie I–II, záhony na kamenech',
 'Zmutovaná, pestře barevná květina (asi 20 coulů), kolem homolovitého těla se otáčí barevná spirála. Pohybuje se pomalu (coul/s) po slunci, denní tvor. Vysává kouzelnickou magenergii (denní dávka 2, jednou za 36 směn). Po vysátí magu spirála za 1 kolo nabobtná a s hlasitým zapištěním vystřelí rozmnožovací spóry, pak se 36 směn navíjí zpět. Žije v koloniích 5–50 kusů, dokáže vyvolat kakofonii pištění.');
INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator)
SELECT (SELECT id FROM nestvury WHERE nazev='Píšťík¹' ORDER BY id DESC LIMIT 1), id, NULL FROM kody_zranitelnosti WHERE kod IN ('B','C','D','G','I','L','N');

INSERT INTO nestvury (nazev, zivotaschopnost, oc, velikost, pohyblivost, inteligence, poklady, zkusenost, prostredi, popis) VALUES
('Nafouk¹', '1 život', '(+4 + 1) = 5', 'A0, při zvětšování A, největší exempláře i B', '3/magický tvor', '0', 'nic', 3, 'kruh magie I, ve vzduchu',
 'Vznikl z motýla — malá vznášející se barevná průsvitná kulička (základně necelý coul), barva podle druhu motýla. Vysává hraničářskou magenergii (kdykoli ve dne, jednou za kolo, dosah 25 sáhů); po vysátí magu se zvětší o 20 coulů a vystoupá o 2 sáhy, ztrácí velikost bez další magenergie. S každým vysátým magem +10 % šance na prasknutí; po 10 vysátých hraničářských mazích za den praskne automaticky. Po prasknutí se rozptýlí spóry, z nichž vzniknou další nafouci. Přes noc splaskne na původní velikost. Vyskytuje se jednotlivě i v hejnech.');
INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator)
SELECT (SELECT id FROM nestvury WHERE nazev='Nafouk¹' ORDER BY id DESC LIMIT 1), id, NULL FROM kody_zranitelnosti WHERE kod IN ('B','C','D','G','J','K','L','N');

INSERT INTO nestvury (nazev, zivotaschopnost, oc, velikost, inteligence, charisma, presvedceni_id, poklady, zkusenost, prostredi, popis) VALUES
('Telepka¹', '2 životy', '(+5 + 2) = 7', 'A0, výjimečné A', '4', '2',
 (SELECT id FROM presvedceni WHERE nazev='Neutrální'),
 'nic', 5, 'kruh magie I–II, vyhřívá se na slunci',
 'Zmutovaný superinteligentní ježek s mimikry balvanu. Nepožírá magenergii přímo, ale jen tu uvolněnou při seslání kouzel blesky nebo hyperprostor: vyčte kouzelníkovi z mysli jeho nejhorší obavu a vyvolá jí odpovídající iluzi (past Int(7), pro sesilatele past Int(12) ~ poznání/nepoznání), aby ho vyprovokoval tato kouzla seslat — pak magenergii pohltí, aniž kouzlo vznikne. Ohrožená telepka umí levitovat 10 sáhů/kolo za cenu 1 magu. Po pohlcení 100 magů vytvoří dalšího telepku.');
INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator)
SELECT (SELECT id FROM nestvury WHERE nazev='Telepka¹' ORDER BY id DESC LIMIT 1), id, NULL FROM kody_zranitelnosti WHERE kod IN ('B','C','D','G','I','K','M','N');

INSERT INTO nestvury (nazev, zivotaschopnost, oc, velikost, inteligence, poklady, zkusenost, prostredi, popis) VALUES
('Flek¹', '1 život', '(+3 + 1) = 4', 'A0', '0', 'nic', 3, 'kruh magie I, na kamenech',
 'Drobný zmutovaný hmyz (broučci) různé velikosti, tvaru a barvy, placatý a kulatý, sbírá magický prach na kamenech. Vysává jen alchymistickou (vázanou) magenergii — obsah truhly, lektvary, svitky — na dálku až 20 sáhů, i skrz kůži/dřevo/kov (prolne coulem kůže za 1 kolo, dřeva za 4, kovu za 10). Pomalý (jeden skok do 3 sáhů za 6 směn). Po pohlcení 10 vázaných magů mutuje v treštíka. Nevyskytuje se ve vyšších magických kruzích.');
INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator)
SELECT (SELECT id FROM nestvury WHERE nazev='Flek¹' ORDER BY id DESC LIMIT 1), id, NULL FROM kody_zranitelnosti WHERE kod IN ('B','C','D','G','I','J','K','N');

INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, odolnost, velikost, bojovnost, pohyblivost, vytrvalost, manevrovaci_schopnost, inteligence, poklady, zkusenost, prostredi, popis) VALUES
('Oživlý svitek¹', '1 nebo 2 životy', '(−3 + 1) = 0', '(+2 + 1) = 3', '5', 'A0', '2', '6/okřídlenec', '5/okřídlenec', '15', '1', 'nic', 3, 'kruh magie I, ve vzduchu',
 'Vzniklý z rostliny, jejíž listy zbělely a rostlina se vytrhla z kořenů a začala létat. Existují 1-4magové svitky; touží, aby na ně bylo sesláno kouzlo (jako při výrobě kouzelného svitku), a obtěžuje kouzelníky/hraničáře s aktivní magenergií oblétáváním a dorážením, dokud se jim nevěnují. Kouzelník od 16. úrovně na něj dokáže kouzlo "zaznamenat"; níže úrovní kouzelník sešle kouzlo bez efektu (svitek je zranitelný jen bílou střelou). Svitek se zaznamenaným kouzlem si denně obnovuje magenergii a sesílá kouzlo na první nemagický cíl, který zaregistruje (magy vnímá, aktivní psychiku vidí, neaktivní magické předměty ne). Základní bojovnost 2, klesá o 1 za každé kolo, kdy ignoruje blízkou nezacílenou magickou postavu. Čistě denní tvor.');
INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator)
SELECT (SELECT id FROM nestvury WHERE nazev='Oživlý svitek¹' ORDER BY id DESC LIMIT 1), id, NULL FROM kody_zranitelnosti WHERE kod IN ('B','C','D','G','I','N');

INSERT INTO nestvury (nazev, zivotaschopnost, oc, velikost, pohyblivost, vytrvalost, manevrovaci_schopnost, inteligence, poklady, zkusenost, prostredi, popis) VALUES
('Treštík¹', '1 život', '(+3 + 1) = 4', 'A0', '5/okřídlenec', '4/okřídlenec', '6', '0', 'nic', 3, 'kruh magie II–III, ve vzduchu',
 'Vyšší stádium oživlého fleku, 5–15 coulů dlouhý, létá díky lehkosti těla a plynem nafouknutým partiím. Vysává kouzelnickou magenergii (denní dávka 1 mag/směnu, +5% šance na úspěch oproti běžným tvorům magického pole) a ovládá jedno (náhodné, i potenciálně nebezpečné) kouzelnické kouzlo, které sešle na první vhodný cíl, jakmile posbírá potřebnou magenergii — často právě na dárce magenergie. Čistě denní tvor, obtížně odlišitelný od nevysátých fleků v hejnu.');
INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator)
SELECT (SELECT id FROM nestvury WHERE nazev='Treštík¹' ORDER BY id DESC LIMIT 1), id, NULL FROM kody_zranitelnosti WHERE kod IN ('B','C','D','G','I','J','K','N');

