INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, odolnost, velikost, bojovnost, pohyblivost, vytrvalost, inteligence, poklady, zkusenost, popis) VALUES
('Nezmar', '5 + každá hlava 1 život', '(0 + 6) = 6 (zuby, 3× za kolo)', '(+3 + 2) = 5 (krky); (0 + 10) = 10 (krunýř)', '18', 'B', '9', '5/plaz', '22/plaz', '5', 'nic, 1500/0 doupě', 270,
 'Třihlavá želvovitá bytost asi 2 sáhy dlouhá, neobyčejně chamtivá, ale mdlé inteligence (nerozezná drahokamy od bezcenných tretek — může zaútočit na válečníka jen pro lesklé brnění). Krunýř je obyčejnými zbraněmi neprorazitelný (jen kouzelnou sekyrou, kladivem či palcátem); zranitelné jsou jen dlouhé pohyblivé krky, ale za každou useknutou hlavu narostou dvě nové (max. 27 hlav, pak už jen ubývají). Skutečně mrtvý je jen, když jsou v jednom kole zničeny všechny hlavy najednou. Nejúčinnější zbraní proti němu je mágův velký mix.');
INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator) VALUES
((SELECT id FROM nestvury WHERE nazev='Nezmar' ORDER BY id DESC LIMIT 1), (SELECT id FROM kody_zranitelnosti WHERE kod='B'), NULL),
((SELECT id FROM nestvury WHERE nazev='Nezmar' ORDER BY id DESC LIMIT 1), (SELECT id FROM kody_zranitelnosti WHERE kod='C'), NULL),
((SELECT id FROM nestvury WHERE nazev='Nezmar' ORDER BY id DESC LIMIT 1), (SELECT id FROM kody_zranitelnosti WHERE kod='D'), NULL),
((SELECT id FROM nestvury WHERE nazev='Nezmar' ORDER BY id DESC LIMIT 1), (SELECT id FROM kody_zranitelnosti WHERE kod='H'), '1/2'),
((SELECT id FROM nestvury WHERE nazev='Nezmar' ORDER BY id DESC LIMIT 1), (SELECT id FROM kody_zranitelnosti WHERE kod='I'), NULL),
((SELECT id FROM nestvury WHERE nazev='Nezmar' ORDER BY id DESC LIMIT 1), (SELECT id FROM kody_zranitelnosti WHERE kod='L'), NULL);
-- B a D nefungují na krunýř (jen na odhalené krky), viz popis.

INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, odolnost, velikost, bojovnost, pohyblivost, vytrvalost, inteligence, poklady, zkusenost, ochoceni, prostredi, popis) VALUES
('Nosorožec', '10', '(+5 + 6) = 11', '(−1 + 10) = 9', '23', 'D', '9', '16/zvěř', '20/zvěř', '1', 'roh 320–500', 950, '8', 'savany a otevřená krajina',
 'Velké suchozemské zvíře s jedním nebo dvěma rohy na hlavě (u dvou je přední delší); useknutý/ulomený roh doroste. Velmi silný, na svou velikost rychlý a obratný, chráněný silnou kůží. Dobrý čich a sluch, ale velmi špatný zrak — útočí na cokoli ve směru pachu, i na stromy. Odvázný, nerudný, nevypočitatelný; samice pečlivě chrání mláďata. Obři je občas chovají jako bojová jízdní zvířata. Při prvním útoku s rozběhem bonus +6 k ÚČ; postavy útočící zblízka/z boku musí každé kolo hodit past Obr(5) ~ nic/sražení a pád za 20–25 životů.');
INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator)
SELECT (SELECT id FROM nestvury WHERE nazev='Nosorožec' ORDER BY id DESC LIMIT 1), id, NULL FROM kody_zranitelnosti WHERE kod IN ('B','C','D','G','H','I','J','K','L');

INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, odolnost, velikost, inteligence, charisma, zsm, presvedceni_id, poklady, zkusenost, prostredi, popis) VALUES
('Nymfa*', '7', '−5 + síla zbraně + zvl.', '(+4 + 2) = 6', NULL, 'A–B', '17', '20', '7',
 NULL, '10 + magenergie v muší', 50, 'sladké i mořské vody, podmořské jeskyně',
 'Vodní obdoba víly, existují říční, jezerní i mořské nymfy (žijí v obou typech vod), jezdí na mořských koníčcích. Mírné, slabé, téměř bezbranné (mohou používat lehké zbraně jako dýku). Zvláštní útok: dokáží vyvolat vodní elementaly (undiny) pomocí magické mušle na zlatém řetízku místo elementální hole; vkládají do ní 10 magů denně (max. 280 magů v mušli, nevyužitá magenergie po 28 dnech mizí a nelze ji přenést jinam ani vydestilovat). Přesvědčení je různé.');
INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator) VALUES
((SELECT id FROM nestvury WHERE nazev='Nymfa*' ORDER BY id DESC LIMIT 1), (SELECT id FROM kody_zranitelnosti WHERE kod='C'), '1/4'),
((SELECT id FROM nestvury WHERE nazev='Nymfa*' ORDER BY id DESC LIMIT 1), (SELECT id FROM kody_zranitelnosti WHERE kod='G'), NULL),
((SELECT id FROM nestvury WHERE nazev='Nymfa*' ORDER BY id DESC LIMIT 1), (SELECT id FROM kody_zranitelnosti WHERE kod='I'), '1/2'),
((SELECT id FROM nestvury WHERE nazev='Nymfa*' ORDER BY id DESC LIMIT 1), (SELECT id FROM kody_zranitelnosti WHERE kod='J'), NULL),
((SELECT id FROM nestvury WHERE nazev='Nymfa*' ORDER BY id DESC LIMIT 1), (SELECT id FROM kody_zranitelnosti WHERE kod='K'), NULL),
((SELECT id FROM nestvury WHERE nazev='Nymfa*' ORDER BY id DESC LIMIT 1), (SELECT id FROM kody_zranitelnosti WHERE kod='P'), NULL),
((SELECT id FROM nestvury WHERE nazev='Nymfa*' ORDER BY id DESC LIMIT 1), (SELECT id FROM kody_zranitelnosti WHERE kod='H'), NULL);
