INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, odolnost, velikost, bojovnost, pohyblivost, inteligence, charisma, presvedceni_id, poklady, zkusenost, prostredi, popis) VALUES
('Obr lidožrout', '8 + 1', '+6 + síla zbraně', '0 + kvalita zbroje', '19', 'C nebo D', '8', '22/humanoid', '6', '4',
 (SELECT id FROM presvedceni WHERE nazev='Zmatené zlo'),
 '10/0, 3 000/10 doupě', 350, 'vysoko v horách',
 'Asi čtyřsáhový nevlídný kolohnát ve zvířecích kůžích (KZ 3), žije samotářsky vysoko v horách, dlouhověký, celoživotně hromadí poklady (někdy vyžene obyvatele hradu a nastřádá bohatství v trůnním sále). Do nížin sestupuje nerad. Bojuje kyjem silným jako kmen stromu (síla zbraně 0/+10, zbroj oběti se do obrany nepočítá). Děsivý řev může slabší postavu srazit do mdlob (past Odl(1) ~ nic/mdloby na 1–3 směny). Nebezpečný soupeř, nižší úroveň družiny s ním nemusí přežít.');
INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator)
SELECT (SELECT id FROM nestvury WHERE nazev='Obr lidožrout' ORDER BY id DESC LIMIT 1), id, NULL FROM kody_zranitelnosti WHERE kod IN ('B','C','D','G','H','I','J','K','L','M','O');
-- Zapsáno jako "humanoid, ale A 0": kód A (zápas) vyloučen.

-- Obyvatelé — obecná šablona pro civilní CP (rolníci, řemeslníci apod.), ne
-- konkrétní nestvůra; přesná čísla se dopočítávají podle rasy zvolené PJ.
INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, odolnost, velikost, presvedceni_id, poklady, zkusenost, popis) VALUES
('Obyvatelé', '1', 'Sil + síla zbraně', 'Obr + kvalita zbroje', '11', 'závisí na rase',
 NULL, 'různé', 10,
 'Cizí postavy představující civilní obyvatelstvo (rolníci, řemeslníci, úředníci) jakékoli rasy popsané v pravidlech — trvale mají životaschopnost 1, počet životů se určuje logicky, ne kostkou. Mohou skrývat pravé schopnosti (např. bývalý válečník vydávající se za kováře). Tvoří se stejně jako postava s rasou bez povolání.');
INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator)
SELECT (SELECT id FROM nestvury WHERE nazev='Obyvatelé' ORDER BY id DESC LIMIT 1), id, NULL FROM kody_zranitelnosti WHERE kod IN ('A','B','C','D','G','H','I','J','K','L','M','O');

INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, velikost, bojovnost, pohyblivost, inteligence, charisma, zsm, poklady, zkusenost, prostredi, popis) VALUES
('Oči plíživé*', '12', '5 + (1k10) (dotyk)', '5 + (1k10) (oblak); 1k10 (každé oko)', 'E (oblak)', '12', '15/magický tvor', '1', '1', '38', 'nic', 600, 'téměř pustá krajina, okruh 1k10 tisíc sáhů',
 'Dvě zářící, nenávistně planoucí oči uprostřed neprůhledného temného oblaku, který si samy vytvářejí a od kterého je nelze oddělit ani rozptýlit. Každé oko drží desetinu jejích životů, zbytek je v oblaku (zničení obojího = smrt). Všežravé, zlikvidují vše živé ve svém okruhu a pak čekají hladově dál; nebojí se slunečního světla. Nezranitelné obyčejnou ani kouzelnou zbraní; lze vyzvat na mentální souboj (samy ho ale nikdy nezahajují), účinný je jen oheň — plameny je nutí uhýbat (1. kolo ztráta 2–7 životů, pak ústup na 30 coulů). Zvláštní útok: leptání — mrtvá oběť zvyšuje počet životů nestvůry o svůj vlastní počet.');
INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator)
SELECT (SELECT id FROM nestvury WHERE nazev='Oči plíživé*' ORDER BY id DESC LIMIT 1), id, NULL FROM kody_zranitelnosti WHERE kod IN ('G','J','N','P');
INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator) VALUES
((SELECT id FROM nestvury WHERE nazev='Oči plíživé*' ORDER BY id DESC LIMIT 1), (SELECT id FROM kody_zranitelnosti WHERE kod='K'), '2');

INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, odolnost, velikost, bojovnost, pohyblivost, vytrvalost, inteligence, poklady, zkusenost, popis) VALUES
('Ogloj-chorchoj', '6', '6/0 (bílé blesky, třikrát za kolo)', '(+2+1)=3', '17', 'C–D', '10', '11/hmyz', '25/hmyz', '1', 'nic, 400/5 doupě', 175,
 'Červ tlustý jako mužské stehno, dlouhý 2–4 sáhy. Skřeti, orkové a podobné méně inteligentní nestvůry z něj mají panickou hrůzu. Nebezpečný zejména pro postavy v kovovém brnění (postih −2 na obranu proti jeho blescích). Zvláštní útok: bílé blesky — po zásahu postavou 1 kolo lomcují křeče, další kolo úpí na zemi, ubírají vždy 4 životy. Nejlepší obranou je luk či jiná střelná zbraň.');
INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator)
SELECT (SELECT id FROM nestvury WHERE nazev='Ogloj-chorchoj' ORDER BY id DESC LIMIT 1), id, NULL FROM kody_zranitelnosti WHERE kod IN ('B','C','D','G','H','I','J','K','L');

INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, odolnost, velikost, pohyblivost, vytrvalost, manevrovaci_schopnost, inteligence, charisma, presvedceni_id, poklady, zkusenost, prostredi, popis) VALUES
('Orel královský', '10', '(+4 + 4) = 8 (zobák); (+4 + 6) = 10 nebo (+4 + 6/+6) = 10/+6 (spáry s čepelemi)', '(+6 + 4) = 10', '23', 'C', '1/okřídlenec (na zemi); 25/okřídlenec (ve vzduchu)', '25/okřídlenec', '19', '17', '13',
 NULL, '500/5, 2000/15 hnízdo', 630, 'vysoké nedostupné skály, hnízda přístupná jen ze vzduchu',
 'Na rozdíl od orla stříbrného inteligentní, mluví lidskou řečí, větší a silnější. Žije v rodech vedených patriarchou, hnízda připomínají paláce; členové rodu sdílí přesvědčení, různé rody spolu mohou válčit. Ke spárům si mohou nechat připevnit ocelové (i kouzelné) čepele, které zvyšují jejich účinnost (zkušenost pak 900 místo 630). Nedají se ochočit, ale lze se s nimi domluvit na spolupráci jako s leteckými nestvůrami. Vzácně existují osamělí samotáři vyloučení z rodu (např. jiné přesvědčení), někteří ovládají jednoduchá kouzla a přátelí se s ptáčníky. V kole útočí spáry i zobákem, jen na jednu postavu.');
INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator)
SELECT (SELECT id FROM nestvury WHERE nazev='Orel královský' ORDER BY id DESC LIMIT 1), id, NULL FROM kody_zranitelnosti WHERE kod IN ('B','C','D','G','H','I','J','K','L','M');
-- Zapsáno jako "zvíře + M".

INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, odolnost, velikost, bojovnost, pohyblivost, vytrvalost, manevrovaci_schopnost, inteligence, poklady, zkusenost, ochoceni, popis) VALUES
('Orel stříbrný', '5', '(+4 + 5) = 9 (spáry) + (+4 + 3) = 7 (zobák)', '(+3 + 4) = 7', '18', 'B', '8', '20/okřídlenec (ve vzduchu); 1/okřídlenec (na zemi)', '20/okřídlenec', '17', '1', 'viz popis', 215, '8',
 'Větší a silnější než obyčejný orel skalní, jen zvířecí inteligence, snadno ochočitelný pro postavy nebo CP velikosti A. Sám nemá poklady, ale unese 1600 mincí nákladu (bez leteckého souboje). Nemá rád varany — pokud je letec donutí letět v hejnu varanů, 20% šance, že se navzdory ochočení pokusí letce shodit a zaútočit na varany. V kole útočí spáry i zobákem, jen na jednu postavu.');
INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator)
SELECT (SELECT id FROM nestvury WHERE nazev='Orel stříbrný' ORDER BY id DESC LIMIT 1), id, NULL FROM kody_zranitelnosti WHERE kod IN ('B','C','D','G','H','I','J','K','L');

INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, odolnost, velikost, bojovnost, pohyblivost, inteligence, charisma, presvedceni_id, poklady, zkusenost, popis) VALUES
('Ork', '1 + 2', '0 + síla zbraně', '–1 + kvalita zbroje + štít', '13', 'A', '8', '7/humanoid', '5', '4',
 (SELECT id FROM presvedceni WHERE nazev='Zmatené zlo'),
 '2/0, 2 000/0 sídlo', 20,
 'Vzdálený humanoidní příbuzný skřetů — silnější, chytřejší a odolnější. Často se odívá do zvířecích kůží (KZ 3). U orků se často vyskytuje osamělý troll pověřený ochranou hejtmana.');
INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator)
SELECT (SELECT id FROM nestvury WHERE nazev='Ork' ORDER BY id DESC LIMIT 1), id, NULL FROM kody_zranitelnosti WHERE kod IN ('A','B','C','D','G','H','I','J','K','L','M','O');

INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, velikost, inteligence, charisma, zsm, presvedceni_id, poklady, zkusenost, prostredi, popis) VALUES
('Zkamenělý trpasličí válečník', '4', '(+6+4/+3)=10/+3 (válečná sekera)', '(–3+8)=5', 'A', '12', '9', '11',
 (SELECT id FROM presvedceni WHERE nazev='Neutrální'),
 '400/0', 160, 'toulá se horami',
 'Příklad oživlé sochy první skupiny — trpasličí válečník Odil, kdysi zkamenělý mocným čarodějem a poté oživený jako jeho sluha; po čarodějově smrti zůstal osamocen v kamenné podobě. Nesmrtelný v kameni, nemusí jíst/pít/spát, hledá způsob, jak se nechat odčarovat. Obezřetný, ne nepřátelský, ochoten za pomoc slíbit informace o zlatě. Lze odčarovat mocným hraničářským kouzlem vyšších úrovní — po odčarování začne opět stárnout.');
INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator)
SELECT (SELECT id FROM nestvury WHERE nazev='Zkamenělý trpasličí válečník' ORDER BY id DESC LIMIT 1), id, NULL FROM kody_zranitelnosti WHERE kod IN ('B','C','D','I','J','L','N','P');

INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, velikost, inteligence, charisma, zsm, presvedceni_id, poklady, zkusenost, popis) VALUES
('Křišťálová socha', '6', '(+5+2/–2)=7/–2 (pěsti); +5 + síla zbraně', '(0+8)=8', 'C', '19', '18', '11',
 (SELECT id FROM presvedceni WHERE nazev='Zákonné dobro'),
 '300/10', 250,
 'Sochu z neživé hmoty si tvoří dobří čarodějové jako moudrého a věrného pomocníka v boji za dobro. "Vidí" všechny druhy neviděných a umí proti nim bojovat pěstmi (jinak jen normálními zbraněmi nezranitelná), útočí na ně od pohledu z přirozené nenávisti.');
INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator)
SELECT (SELECT id FROM nestvury WHERE nazev='Křišťálová socha' ORDER BY id DESC LIMIT 1), id, NULL FROM kody_zranitelnosti WHERE kod IN ('B','C','D','I','J','L','N','P');

INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, velikost, inteligence, charisma, zsm, presvedceni_id, poklady, zkusenost, popis) VALUES
('Železná socha', '6', '(+6+2/–2)=8/–2 (pěsti); +6 + síla zbraně', '(0+8)=8', 'C', '6', '10', '11',
 NULL,
 '300/5', 270,
 'Sochu z neživé hmoty si obvykle tvoří neutrální čarodějové zaneprázdnění všedními starostmi. O trochu silnější než křišťálová socha, ale velmi hloupá; vyzná se v kovářství a za vhodných podmínek dokáže vykovat vynikající zbraně (o jednu sílu zbraně vyšší). -- TODO formulace o vztahu k neutrálním čarodějům je v předloze gramaticky poškozená, přepsáno podle smyslu, ověřit proti skenu.');
INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator)
SELECT (SELECT id FROM nestvury WHERE nazev='Železná socha' ORDER BY id DESC LIMIT 1), id, NULL FROM kody_zranitelnosti WHERE kod IN ('B','C','D','I','J','L','N','P');

INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, velikost, inteligence, charisma, zsm, presvedceni_id, poklady, zkusenost, popis) VALUES
('Kamenná socha', '6', '(+5+2/–2)=7/–2 (pěsti); +5 + síla zbraně; (+2+3/+3)=5/+3 (láva)', '(+2+8)=8', 'C', '18', '11', '11',
 (SELECT id FROM presvedceni WHERE nazev='Zákonné zlo'),
 '500/10', 300,
 'Sochu z neživé hmoty si tvoří zlí čarodějové jako chytrého a lstivého velitele svého vojska. Nenávidí se s křišťálovými sochami a útočí na ně od pohledu. Zvláštní útok: stříká z prstů lávu (dostřel 3/7/11), má 5 dávek, po vyčerpání musí 5 směn čekat, než v ní roztaje kámen, a dalších 6 hodin, než v ní znovu roztaje láva.');
INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator)
SELECT (SELECT id FROM nestvury WHERE nazev='Kamenná socha' ORDER BY id DESC LIMIT 1), id, NULL FROM kody_zranitelnosti WHERE kod IN ('B','C','D','I','J','L','N','P');

