INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, odolnost, velikost, manevrovaci_schopnost, inteligence, charisma, zsm, presvedceni_id, poklady, zkusenost, prostredi, popis) VALUES
('Panna mořská*', '5', '−1 + síla zbraně; (−1 + 3/−2) = 2/−2 (ocas)', '(0 + 1) = 1 (tělo); (0 + 7) = 7 (ocas)', '13', 'B', '17 (ve vodě)', '10', '17', '18',
 (SELECT id FROM presvedceni WHERE nazev='Zákonné dobro'),
 '1800/0', 20, 'moře',
 'Podobná lesní víle, ale se zelenou kůží a tvrdým šupinatým ocasem, žije jen v moři. Komunikuje telepaticky (lze navázat kontakt hraničářskou telepatií), na břehu rozumí lidské řeči, ale nemluví jí. Má 36 magů denně a umí zvláštní kouzlo mořských panen (obdoba vodního dechu, vyvolání 1 směna, dosah dotyk, 12 magů, trvání 24 hodin, umožňuje dýchat/bojovat/kouzlit pod vodou, ale ne mluvit). Plachá, láká se na drobné třpytivé dárky a šperky (korálové náhrdelníky s perlami); může znát polohy potopených lodí a pokladů, ale sama u sebe nic neuchovává (nemá stálé doupě). Nerada bojuje, používá dýky/šavle (i stříbrné), případně udeří ocasem (stínové zranění, ale hrozí utonutí zasaženého pod vodou). Vychází dobře se všemi obyvateli moří kromě žraloků.');
INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator)
SELECT (SELECT id FROM nestvury WHERE nazev='Panna mořská*' ORDER BY id DESC LIMIT 1), id, NULL FROM kody_zranitelnosti WHERE kod IN ('A','B','C','D','G','I','J','K','L','M');
INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator) VALUES
((SELECT id FROM nestvury WHERE nazev='Panna mořská*' ORDER BY id DESC LIMIT 1), (SELECT id FROM kody_zranitelnosti WHERE kod='H'), NULL),
((SELECT id FROM nestvury WHERE nazev='Panna mořská*' ORDER BY id DESC LIMIT 1), (SELECT id FROM kody_zranitelnosti WHERE kod='P'), NULL);
-- Zapsáno jako "humanoid, ale H+, O 0, P": humanoid základ bez O (vyloučeno), H omezeno na H+, navíc P.

INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, odolnost, velikost, bojovnost, pohyblivost, vytrvalost, inteligence, poklady, zkusenost, prostredi, popis) VALUES
('Panter', '4', '(+3 + 5/−3) = 8/−3 (drápy) + (+3 + 3) = 6 (tlama)', '(+4 + 3) = 7', '12', 'B', '5', '14/šelma', '19/šelma', '1', 'nic', 50, 'lesy s vysokou trávou',
 'Nepříliš velká kočkovitá šelma, vyskytuje se hojně v lesích. Vychytralá, vydrží hodiny nehnutě číhat, inteligentním bytostem se raději vyhýbá, ale zahnaná do úzkých bojuje zuřivě a útočí okamžitě — nelze ji podceňovat.');
INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator)
SELECT (SELECT id FROM nestvury WHERE nazev='Panter' ORDER BY id DESC LIMIT 1), id, NULL FROM kody_zranitelnosti WHERE kod IN ('B','C','D','G','H','I','J','K','L');

INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, velikost, bojovnost, pohyblivost, vytrvalost, inteligence, poklady, zkusenost, popis) VALUES
('Křižák obří', '1 + 1', '(0+4)=4 (kusadla) + zvl.', '(0+8)=8', 'A', '12', '11/hmyz', '11/hmyz', '0', 'nic', 10,
 'Obří pavouk asi 1,5 sáhu dlouhý s bílým křížem na šedých zádech, síť pavučin v okolí nory. Umí běhat po stěnách a stropě (OČ 12 proti střelbě); sestřelený padá a zraní se 1–6 životů za každých 5 sáhů pádu. Pavučinu lze sbírat jako u pavouka zeleného. Zvláštní útok: slabý jed, past Odl(2) ~ 1–3/2–12, působí za 1 směnu.');
INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator)
SELECT (SELECT id FROM nestvury WHERE nazev='Křižák obří' ORDER BY id DESC LIMIT 1), id, NULL FROM kody_zranitelnosti WHERE kod IN ('B','C','D','G','H','I','J','K','L');

INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, odolnost, velikost, bojovnost, pohyblivost, vytrvalost, inteligence, poklady, zkusenost, popis) VALUES
('Pavouk zelený', '1', '(–1+4)=3 (kusadla) + zvl.', '(+2+2)=4', '12', 'A', '12', '12/hmyz', '12/hmyz', '0', 'nic', 10,
 'Obrovský, sáh dlouhý pavouk. Zvláštní útoky: pavučina (past Sil(9) ~ nic/přilepení) a jed (past Odl(4) ~ 2–7/7–12, působí během tří kol).');
INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator)
SELECT (SELECT id FROM nestvury WHERE nazev='Pavouk zelený' ORDER BY id DESC LIMIT 1), id, NULL FROM kody_zranitelnosti WHERE kod IN ('B','C','D','G','H','I','J','K','L');

INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, odolnost, velikost, pohyblivost, inteligence, charisma, presvedceni_id, poklady, zkusenost, prostredi, popis) VALUES
('Permoník', '1', '–1 + síla zbraně', '(+4+1)=5', '14', 'A', '15/humanoid', '16', '14',
 NULL, 'viz popis', 10, 'podzemí',
 'Asi půl sáhu vysocí příbuzní trpaslíků, znají celé podzemí — tajné dveře, chodby, pasti. Nezaplatí-li jim postavy dostatečně, obvykle jim poskytnou falešné informace. Přesvědčení různé.');
