INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator) VALUES
((SELECT id FROM nestvury WHERE nazev='Permoník' ORDER BY id DESC LIMIT 1), (SELECT id FROM kody_zranitelnosti WHERE kod='A'), '2');
