INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, odolnost, velikost, bojovnost, pohyblivost, manevrovaci_schopnost, inteligence, poklady, zkusenost, popis) VALUES
('Řasnatka', '1', '4 (svazek blesků)', '(+2+1)=3', '8', 'A', '12', '6/magický tvor', '15', '0', 'nic', 10,
 'Fialový tvor tvaru koule s osmi chapadly, volně plující vzduchem. Živí se krví, kterou usmrcuje fialovými blesky (2 životy za zásah). Vyskytuje se v hejnech o 3–18 kusech.');
