INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, odolnost, velikost, bojovnost, pohyblivost, vytrvalost, inteligence, poklady, zkusenost, prostredi, popis) VALUES
('Vlk sněžný', '3 + 4', '(+2+2/+1)=4/+1 (drápy) + (+2+3/+1)=5/+1 (tlama)', '(+1+3)=4', '16', 'B–C', '9', '17/šelma', '14/šelma', '1', 'nic', 85, 'věčně bílé pláně dalekého severu',
 'Husté bílé srsti, mimikry v zasněžené krajině mu dává 90% šanci zaútočit s překvapením.');
INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator)
SELECT (SELECT id FROM nestvury WHERE nazev='Vlk sněžný' ORDER BY id DESC LIMIT 1), id, NULL FROM kody_zranitelnosti WHERE kod IN ('B','C','D','G','H','I','J','K','L');

INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, odolnost, velikost, manevrovaci_schopnost, inteligence, charisma, presvedceni_id, poklady, zkusenost, popis) VALUES
('Vodník', '2', '(+3+2/–3)=5/–3 (ruce) + zvl.', '(+2+1)=3', '7', 'B', '16', '11', '8',
 (SELECT id FROM presvedceni WHERE nazev='Zmatené zlo'),
 '2/0, 200/0 sídlo', 30,
 'Přesvědčení bývá zmatené zlo, ale i jiné. Zvláštní útok: stahování pod hladinu — oběť se za 3 kola topí (past 1k10, s rostoucí nebezpečností a silou v každém kole).');
INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator)
SELECT (SELECT id FROM nestvury WHERE nazev='Vodník' ORDER BY id DESC LIMIT 1), id, NULL FROM kody_zranitelnosti WHERE kod IN ('A','B','C','D','G','H','I','J','K','L','M');
-- Zapsáno jako "humanoid, ale O 0": O vyloučeno (imunní vůči podrobování).

INSERT INTO nestvury (nazev, zivotaschopnost, uc, oc, odolnost, velikost, bojovnost, pohyblivost, vytrvalost, inteligence, poklady, zkusenost, prostredi, popis) VALUES
('Všežrout odporný', '8', '(+4 + 4/+1) = 8/+1 (zuby) + 4/−1 (kyselina)', '(+1 + 2) = 3', '20', 'B', '9', '25/plaz', '5/plaz', '1', 'nic', 170, 'poblíž bažin, tůní, řek',
 '1,5 sáhu dlouhá slizká šestinohá nestvůra podobná ropuše. Žere vše kromě kamenů, nejraději železo, nepohrdne ani člověkem; útočí tupými zuby s obrovskou silou. Před požitím potravu nalepá kyselinou z tlamy, kterou umí použít i v boji (3 kola) — leptá hlavně železo, ale i kůži (u postavy s KZ 4+ sníží po zásahu na 1–6 kol kvalitu zbroje na 1, plus 1–6 životů zranění). Pohybuje se několikasáhovými skoky, takže útěk je téměř zbytečný, pokud družina neodhodí kovové předměty (min. 200 mincí váhy) — tvor se pak zpravidla pustí do jídla a nechá družinu utéct.');
INSERT INTO nestvura_zranitelnosti (nestvura_id, kod_zranitelnosti_id, modifikator) VALUES
((SELECT id FROM nestvury WHERE nazev='Všežrout odporný' ORDER BY id DESC LIMIT 1), (SELECT id FROM kody_zranitelnosti WHERE kod='B'), '1/2'),
