((SELECT id FROM nestvury WHERE nazev='Všežrout odporný' ORDER BY id DESC LIMIT 1), (SELECT id FROM kody_zranitelnosti WHERE kod='J'), NULL),
((SELECT id FROM nestvury WHERE nazev='Všežrout odporný' ORDER BY id DESC LIMIT 1), (SELECT id FROM kody_zranitelnosti WHERE kod='K'), NULL),
((SELECT id FROM nestvury WHERE nazev='Všežrout odporný' ORDER BY id DESC LIMIT 1), (SELECT id FROM kody_zranitelnosti WHERE kod='L'), NULL),
